#Requires -Version 5.1
<#
    Jebtool - Tạo OU và Group Policy (GPO) bằng giao diện
    Chạy trên máy Windows đã tham gia domain, có cài RSAT.
#>

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()
# ==============================================================================
# JEBTOOL SECURITY, ANTI-COPY, HWID LICENSE GATE & LOADING SCREEN
# ==============================================================================
$script:JebBannerB64 = ''
$script:JebBadgeB64  = ''

if (-not ('JebtoolSecurity.Guard' -as [type])) {
    Add-Type -ReferencedAssemblies System.Windows.Forms, System.Drawing -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Windows.Forms;
using Microsoft.Win32;

namespace JebtoolSecurity {
    internal sealed class NoCopyWindow : NativeWindow {
        private const int WM_CUT  = 0x0300;
        private const int WM_COPY = 0x0301;
        private readonly Control _ctrl;

        public NoCopyWindow(Control ctrl) {
            _ctrl = ctrl;
            _ctrl.HandleCreated += OnHandleCreated;
            _ctrl.HandleDestroyed += OnHandleDestroyed;
            if (_ctrl.IsHandleCreated) AssignHandle(_ctrl.Handle);
        }

        private void OnHandleCreated(object sender, EventArgs e) {
            if (_ctrl.IsHandleCreated) AssignHandle(_ctrl.Handle);
        }

        private void OnHandleDestroyed(object sender, EventArgs e) {
            ReleaseHandle();
        }

        protected override void WndProc(ref Message m) {
            if (m.Msg == WM_COPY || m.Msg == WM_CUT) {
                return;
            }
            base.WndProc(ref m);
        }
    }

    public static class Guard {
        [DllImport("kernel32.dll")]
        private static extern bool IsDebuggerPresent();

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool CheckRemoteDebuggerPresent(IntPtr hProcess, ref bool isDebuggerPresent);

        private const string B32 = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

        // Split & obfuscated secret bytes (shared with Jebtool-KeyGen)
        private static byte[] GetMasterSecret() {
            byte[] a = new byte[] { 0x4A^0x5A, 0x65^0x5A, 0x62^0x5A, 0x54^0x5A, 0x6F^0x5A, 0x6F^0x5A, 0x6C^0x5A, 0x2D^0x5A, 0x32^0x5A, 0x30^0x5A, 0x32^0x5A, 0x36^0x5A };
            byte[] b = new byte[] { 0x23^0xA5, 0x4B^0xA5, 0x65^0xA5, 0x79^0xA5, 0x4D^0xA5, 0x61^0xA5, 0x73^0xA5, 0x74^0xA5, 0x65^0xA5, 0x72^0xA5, 0x21^0xA5, 0x39^0xA5 };
            byte[] c = new byte[] { 0x58^0x3C, 0x71^0x3C, 0x37^0x3C, 0x5A^0x3C, 0x6D^0x3C, 0x50^0x3C, 0x34^0x3C, 0x40^0x3C };
            byte[] res = new byte[a.Length + b.Length + c.Length];
            for (int i = 0; i < a.Length; i++) res[i] = (byte)(a[i] ^ 0x5A);
            for (int i = 0; i < b.Length; i++) res[a.Length + i] = (byte)(b[i] ^ 0xA5);
            for (int i = 0; i < c.Length; i++) res[a.Length + b.Length + i] = (byte)(c[i] ^ 0x3C);
            return res;
        }

        private static readonly string[] BlockedTools = new string[] {
            "dnspy", "dnspy-x86", "ilspy", "dotpeek", "dotpeek32", "dotpeek64",
            "x64dbg", "x32dbg", "ollydbg", "processhacker", "cheatengine",
            "cheatengine-x86_64", "fiddler", "procmon", "procmon64",
            "ida", "ida64", "idag", "idag64", "ghidra", "justdecompile", "reflector"
        };

        private static readonly List<NoCopyWindow> _noCopyHooks = new List<NoCopyWindow>();

        public static string CheckEnvironment() {
            try {
                if (Debugger.IsAttached) return "Debugger.IsAttached";
                if (IsDebuggerPresent()) return "IsDebuggerPresent";
                bool remoteDbg = false;
                if (CheckRemoteDebuggerPresent(Process.GetCurrentProcess().Handle, ref remoteDbg) && remoteDbg) {
                    return "RemoteDebugger";
                }
            } catch { }

            try {
                Process[] procs = Process.GetProcesses();
                for (int i = 0; i < procs.Length; i++) {
                    try {
                        string nm = (procs[i].ProcessName ?? "").ToLowerInvariant();
                        for (int j = 0; j < BlockedTools.Length; j++) {
                            if (nm == BlockedTools[j]) {
                                return procs[i].ProcessName;
                            }
                        }
                    } catch { }
                    finally {
                        try { procs[i].Dispose(); } catch { }
                    }
                }
            } catch { }

            return null;
        }

        private static string ReadRegStr(RegistryKey root, string subPath, string valueName) {
            try {
                using (RegistryKey k = root.OpenSubKey(subPath, false)) {
                    if (k == null) return "";
                    object v = k.GetValue(valueName);
                    if (v == null) return "";
                    byte[] bytes = v as byte[];
                    if (bytes != null) {
                        using (SHA256 sha = SHA256.Create()) {
                            return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", "");
                        }
                    }
                    return v.ToString().Trim();
                }
            } catch {
                return "";
            }
        }

        public static string GetMachineHwid() {
            string machineGuid = "";
            string productId   = "";
            string digProdHash = "";
            string boardMfg    = "";
            string boardProd   = "";
            string sysProd     = "";
            string biosVendor  = "";
            string cpuName     = "";

            try {
                using (RegistryKey hklm = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64)) {
                    machineGuid = ReadRegStr(hklm, @"SOFTWARE\Microsoft\Cryptography", "MachineGuid");
                    productId   = ReadRegStr(hklm, @"SOFTWARE\Microsoft\Windows NT\CurrentVersion", "ProductId");
                    digProdHash = ReadRegStr(hklm, @"SOFTWARE\Microsoft\Windows NT\CurrentVersion", "DigitalProductId");
                    boardMfg    = ReadRegStr(hklm, @"HARDWARE\DESCRIPTION\System\BIOS", "BaseBoardManufacturer");
                    boardProd   = ReadRegStr(hklm, @"HARDWARE\DESCRIPTION\System\BIOS", "BaseBoardProduct");
                    sysProd     = ReadRegStr(hklm, @"HARDWARE\DESCRIPTION\System\BIOS", "SystemProductName");
                    biosVendor  = ReadRegStr(hklm, @"HARDWARE\DESCRIPTION\System\BIOS", "BIOSVendor");
                    cpuName     = ReadRegStr(hklm, @"HARDWARE\DESCRIPTION\System\CentralProcessor\0", "ProcessorNameString");
                }
            } catch { }

            string raw = string.Join("|", new string[] {
                "JEBTOOL-HWID-V1",
                machineGuid.ToUpperInvariant(),
                productId.ToUpperInvariant(),
                digProdHash.ToUpperInvariant(),
                boardMfg.ToUpperInvariant(),
                boardProd.ToUpperInvariant(),
                sysProd.ToUpperInvariant(),
                biosVendor.ToUpperInvariant(),
                cpuName.ToUpperInvariant()
            });

            using (SHA256 sha = SHA256.Create()) {
                byte[] hash = sha.ComputeHash(Encoding.UTF8.GetBytes(raw));
                string b32 = EncodeBase32(hash, 8); // 8 bytes -> 13 chars
                string code = b32.Substring(0, 12);
                return "JEB-" + code.Substring(0, 4) + "-" + code.Substring(4, 4) + "-" + code.Substring(8, 4);
            }
        }

        private static string EncodeBase32(byte[] data, int count) {
            StringBuilder sb = new StringBuilder();
            int buffer = 0;
            int bitsLeft = 0;
            for (int i = 0; i < count; i++) {
                buffer = (buffer << 8) | data[i];
                bitsLeft += 8;
                while (bitsLeft >= 5) {
                    bitsLeft -= 5;
                    int idx = (buffer >> bitsLeft) & 0x1F;
                    sb.Append(B32[idx]);
                }
            }
            if (bitsLeft > 0) {
                int idx = (buffer << (5 - bitsLeft)) & 0x1F;
                sb.Append(B32[idx]);
            }
            return sb.ToString();
        }

        private static byte[] DecodeBase32(string input, int expectedBytes) {
            byte[] result = new byte[expectedBytes];
            int buffer = 0;
            int bitsLeft = 0;
            int outIdx = 0;
            for (int i = 0; i < input.Length; i++) {
                int val = B32.IndexOf(input[i]);
                if (val < 0) return null;
                buffer = (buffer << 5) | val;
                bitsLeft += 5;
                if (bitsLeft >= 8) {
                    bitsLeft -= 8;
                    if (outIdx < expectedBytes) {
                        result[outIdx++] = (byte)((buffer >> bitsLeft) & 0xFF);
                    }
                }
            }
            if (outIdx != expectedBytes) return null;
            return result;
        }

        private static byte[] ComputeExpMask(byte[] nonce, byte[] secret) {
            byte[] buf = new byte[nonce.Length + secret.Length];
            Buffer.BlockCopy(nonce, 0, buf, 0, nonce.Length);
            Buffer.BlockCopy(secret, 0, buf, nonce.Length, secret.Length);
            using (SHA256 sha = SHA256.Create()) {
                return sha.ComputeHash(buf);
            }
        }

        private static byte[] ComputeSig(string hwid, byte[] expBytes, byte[] nonce, byte[] secret) {
            byte[] hwidBytes = Encoding.UTF8.GetBytes(hwid.Trim().ToUpperInvariant());
            byte[] msg = new byte[hwidBytes.Length + 1 + expBytes.Length + nonce.Length];
            Buffer.BlockCopy(hwidBytes, 0, msg, 0, hwidBytes.Length);
            msg[hwidBytes.Length] = (byte)'|';
            Buffer.BlockCopy(expBytes, 0, msg, hwidBytes.Length + 1, expBytes.Length);
            Buffer.BlockCopy(nonce, 0, msg, hwidBytes.Length + 1 + expBytes.Length, nonce.Length);
            using (HMACSHA256 hmac = new HMACSHA256(secret)) {
                return hmac.ComputeHash(msg);
            }
        }

        public static string ValidateKey(string keyInput, string currentHwid) {
            if (string.IsNullOrWhiteSpace(keyInput)) {
                return "ERR|Vui lòng nhập Key bản quyền!";
            }

            string clean = keyInput.Trim().ToUpperInvariant().Replace("-", "").Replace(" ", "").Replace("\r", "").Replace("\n", "");
            if (clean.StartsWith("JEB")) {
                clean = clean.Substring(3);
            }
            if (clean.Length != 21) {
                return "ERR|Định dạng Key không hợp lệ! Key phải có dạng JEB-XXXXX-XXXXX-XXXXX-XXXXXX.";
            }

            byte[] payload = DecodeBase32(clean, 13);
            if (payload == null) {
                return "ERR|Key chứa ký tự không hợp lệ!";
            }

            byte[] secret = GetMasterSecret();
            byte[] obfExp = new byte[4];
            byte[] nonce  = new byte[3];
            byte[] sig    = new byte[6];
            Buffer.BlockCopy(payload, 0, obfExp, 0, 4);
            Buffer.BlockCopy(payload, 4, nonce, 0, 3);
            Buffer.BlockCopy(payload, 7, sig, 0, 6);

            byte[] mask = ComputeExpMask(nonce, secret);
            byte[] expBytes = new byte[4];
            for (int i = 0; i < 4; i++) {
                expBytes[i] = (byte)(obfExp[i] ^ mask[i]);
            }

            byte[] expectedSig = ComputeSig(currentHwid, expBytes, nonce, secret);
            int diff = 0;
            for (int i = 0; i < 6; i++) {
                diff |= (sig[i] ^ expectedSig[i]);
            }
            if (diff != 0) {
                return "ERR|Key không hợp lệ hoặc không khớp với mã máy / Windows này!";
            }

            uint expVal = ((uint)expBytes[0] << 24) | ((uint)expBytes[1] << 16) | ((uint)expBytes[2] << 8) | expBytes[3];
            if (expVal == 0) {
                return "OK|LIFETIME|Vĩnh viễn";
            }

            int yyyy = (int)(expVal / 10000);
            int mm   = (int)((expVal / 100) % 100);
            int dd   = (int)(expVal % 100);
            DateTime expDate;
            try {
                expDate = new DateTime(yyyy, mm, dd);
            } catch {
                return "ERR|Dữ liệu thời hạn trong Key bị lỗi!";
            }

            if (DateTime.Today > expDate) {
                return "ERR|Key đã hết hạn vào ngày " + expDate.ToString("dd/MM/yyyy") + "!";
            }

            int daysLeft = (int)(expDate - DateTime.Today).TotalDays;
            return "OK|TIMED|HSD: " + expDate.ToString("dd/MM/yyyy") + " (còn " + daysLeft + " ngày)";
        }

        public static void ProtectReadOnlyControls(Control root) {
            if (root == null) return;
            ContextMenuStrip emptyMenu = new ContextMenuStrip();
            emptyMenu.Opening += delegate(object s, System.ComponentModel.CancelEventArgs e) { e.Cancel = true; };
            WalkAndProtect(root, emptyMenu);
        }

        private static void WalkAndProtect(Control ctrl, ContextMenuStrip emptyMenu) {
            if (ctrl == null) return;
            string tagStr = ctrl.Tag != null ? ctrl.Tag.ToString() : "";
            if (tagStr != "AllowCopy") {
                TextBoxBase tb = ctrl as TextBoxBase;
                if (tb != null && tb.ReadOnly) {
                    tb.ShortcutsEnabled = false;
                    tb.ContextMenuStrip = emptyMenu;
                    tb.KeyDown += delegate(object s, KeyEventArgs e) {
                        if ((e.Control && (e.KeyCode == Keys.C || e.KeyCode == Keys.X || e.KeyCode == Keys.A || e.KeyCode == Keys.Insert)) ||
                            (e.Shift && e.KeyCode == Keys.Delete)) {
                            e.SuppressKeyPress = true;
                            e.Handled = true;
                        }
                    };
                    _noCopyHooks.Add(new NoCopyWindow(tb));
                }
            }
            for (int i = 0; i < ctrl.Controls.Count; i++) {
                WalkAndProtect(ctrl.Controls[i], emptyMenu);
            }
        }
    }
}
'@
}

# Anti-debug / Anti-reverse-engineering startup check
$script:JebDbgCheck = [JebtoolSecurity.Guard]::CheckEnvironment()
if ($script:JebDbgCheck) {
    [System.Windows.Forms.MessageBox]::Show(
        "Phát hiện công cụ gỡ lỗi / sao chép mã nguồn ($script:JebDbgCheck)!
Jebtool sẽ tự động đóng để bảo vệ bản quyền.",
        "Jebtool — Bảo vệ mã nguồn",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Stop
    ) | Out-Null
    exit 1
}

function Get-JebtoolImageFromB64([string]$b64) {
    try {
        $bytes = [Convert]::FromBase64String($b64)
        $ms = New-Object System.IO.MemoryStream(, $bytes)
        return [System.Drawing.Image]::FromStream($ms)
    } catch { return $null }
}

function Get-JebtoolAppIcon {
    try {
        $procExe = ""
        try { $procExe = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { }
        if ($procExe -and $procExe.EndsWith('.exe', [System.StringComparison]::OrdinalIgnoreCase) -and
            ([System.IO.Path]::GetFileNameWithoutExtension($procExe) -notmatch '^(?i)(powershell|pwsh|powershell_ise)$') -and
            (Test-Path -LiteralPath $procExe)) {
            return [System.Drawing.Icon]::ExtractAssociatedIcon($procExe)
        }
        $dir = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }
        $ico = Join-Path $dir "Jebtool.ico"
        if (Test-Path -LiteralPath $ico) { return New-Object System.Drawing.Icon($ico) }
    } catch { }
    return $null
}

