    [System.Windows.Forms.Application]::DoEvents()
    return $sp
}

function Update-JebtoolLoading($sp, [int]$targetPct, [string]$msg, [int]$stepDelayMs = 14) {
    if (-not $sp -or $sp.IsDisposed) { return }
    $st = $sp.Tag
    $st.Step.Text = $msg
    $from = [int]$st.CurPct
    if ($targetPct -lt $from) { $targetPct = $from }
    for ($p = $from; $p -le $targetPct; $p += 2) {
        $st.CurPct = $p
        $st.Pct.Text = "$p%"
        $st.Fill.Width = [Math]::Max(4, [int]([Math]::Round($st.TrackW * ($p / 100.0))))
        $sp.Refresh()
        [System.Windows.Forms.Application]::DoEvents()
        if ($stepDelayMs -gt 0) { Start-Sleep -Milliseconds $stepDelayMs }
    }
    if ($st.CurPct -ne $targetPct) {
        $st.CurPct = $targetPct
        $st.Pct.Text = "$targetPct%"
        $st.Fill.Width = [Math]::Max(4, [int]([Math]::Round($st.TrackW * ($targetPct / 100.0))))
        $sp.Refresh()
        [System.Windows.Forms.Application]::DoEvents()
    }
}

