    public sealed class MfVideoDecoder : IDisposable {
        [DllImport("kernel32.dll", EntryPoint = "RtlMoveMemory", SetLastError = false)]
        private static extern void CopyMemory(IntPtr dest, IntPtr src, UIntPtr count);

        private readonly string _path;
        private IMFSourceReader _reader;
        private bool _mfStarted;
        private int _srcWidth;
        private int _srcHeight;
        private int _stride;
        private int _cropX;
        private int _cropY;
        private int _cropW;
        private int _cropH;
        private int _rotation;
        private int _defaultDelayMs = 33;
        private Bitmap _frameBmp;
        private Bitmap _rotatedBmp;
        private bool _disposed;

        public MfVideoDecoder(string path) {
            _path = path;
            int hr = MfNative.MFStartup(MfNative.MF_API_VERSION, 0);
            if (hr < 0) throw new InvalidOperationException("MFStartup failed: 0x" + hr.ToString("X8"));
            _mfStarted = true;
            OpenReader();
        }

        private void OpenReader() {
            IMFAttributes attr = null;
            IMFMediaType reqMt = null;
            try {
                int hr = MfNative.MFCreateAttributes(out attr, 1);
                if (hr < 0) throw new InvalidOperationException("MFCreateAttributes failed: 0x" + hr.ToString("X8"));
                Guid gVp = MfNative.MF_SOURCE_READER_ENABLE_VIDEO_PROCESSING;
                attr.SetUINT32(ref gVp, 1);

                hr = MfNative.MFCreateSourceReaderFromURL(_path, attr, out _reader);
                if (hr < 0 || _reader == null) {
                    throw new InvalidOperationException("Không mở được video MP4 (HR=0x" + hr.ToString("X8") + ").");
                }

                _reader.SetStreamSelection(MfNative.MF_SOURCE_READER_ALL_STREAMS, false);
                hr = _reader.SetStreamSelection(MfNative.MF_SOURCE_READER_FIRST_VIDEO_STREAM, true);
                if (hr < 0) throw new InvalidOperationException("Video không có luồng hình hợp lệ (HR=0x" + hr.ToString("X8") + ").");

                hr = MfNative.MFCreateMediaType(out reqMt);
                if (hr < 0) throw new InvalidOperationException("MFCreateMediaType failed: 0x" + hr.ToString("X8"));
                Guid gMajor = MfNative.MF_MT_MAJOR_TYPE;
                Guid gSub = MfNative.MF_MT_SUBTYPE;
                Guid gVid = MfNative.MFMediaType_Video;
                Guid gRgb = MfNative.MFVideoFormat_RGB32;
                reqMt.SetGUID(ref gMajor, ref gVid);
                reqMt.SetGUID(ref gSub, ref gRgb);

                hr = _reader.SetCurrentMediaType(MfNative.MF_SOURCE_READER_FIRST_VIDEO_STREAM, IntPtr.Zero, reqMt);
                if (hr < 0) throw new InvalidOperationException("Không giải mã được định dạng video sang RGB32 (HR=0x" + hr.ToString("X8") + ").");

                RefreshFormat();
            } finally {
                if (reqMt != null) Marshal.ReleaseComObject(reqMt);
                if (attr != null) Marshal.ReleaseComObject(attr);
            }
        }

        private void RefreshFormat() {
            IMFMediaType curMt = null;
            try {
                int hr = _reader.GetCurrentMediaType(MfNative.MF_SOURCE_READER_FIRST_VIDEO_STREAM, out curMt);
                if (hr < 0 || curMt == null) throw new InvalidOperationException("GetCurrentMediaType failed: 0x" + hr.ToString("X8"));

                Guid gSize = MfNative.MF_MT_FRAME_SIZE;
                ulong fs;
                hr = curMt.GetUINT64(ref gSize, out fs);
                if (hr < 0) throw new InvalidOperationException("Không đọc được kích thước video.");
                _srcWidth = (int)(fs >> 32);
                _srcHeight = (int)(fs & 0xFFFFFFFF);
                if (_srcWidth <= 0 || _srcHeight <= 0) throw new InvalidOperationException("Kích thước video không hợp lệ.");

                Guid gStride = MfNative.MF_MT_DEFAULT_STRIDE;
                uint strideU;
                if (curMt.GetUINT32(ref gStride, out strideU) >= 0 && strideU != 0) {
                    _stride = unchecked((int)strideU);
                } else {
                    _stride = _srcWidth * 4;
                }

                Guid gRate = MfNative.MF_MT_FRAME_RATE;
                ulong fr;
                _defaultDelayMs = 33;
                if (curMt.GetUINT64(ref gRate, out fr) >= 0) {
                    uint num = (uint)(fr >> 32);
                    uint den = (uint)(fr & 0xFFFFFFFF);
                    if (num > 0 && den > 0) {
                        double fps = (double)num / (double)den;
                        if (fps >= 5.0 && fps <= 60.0) {
                            _defaultDelayMs = Math.Max(16, (int)Math.Round(1000.0 / fps));
                        } else if (fps > 60.0) {
                            _defaultDelayMs = 16;
                        } else if (fps >= 1.0) {
                            _defaultDelayMs = Math.Min(500, (int)Math.Round(1000.0 / fps));
                        }
                    }
                }

                _cropX = 0; _cropY = 0; _cropW = _srcWidth; _cropH = _srcHeight;
                Guid gAp = MfNative.MF_MT_MINIMUM_DISPLAY_APERTURE;
                uint blobSize;
                if (curMt.GetBlobSize(ref gAp, out blobSize) >= 0 && blobSize >= 16) {
                    IntPtr pBlob = Marshal.AllocCoTaskMem((int)blobSize);
                    try {
                        uint readSz;
                        if (curMt.GetBlob(ref gAp, pBlob, blobSize, out readSz) >= 0 && readSz >= 16) {
                            byte[] blob = new byte[16];
                            Marshal.Copy(pBlob, blob, 0, 16);
                            int ox = BitConverter.ToInt16(blob, 2);
                            int oy = BitConverter.ToInt16(blob, 6);
                            int cw = BitConverter.ToInt32(blob, 8);
                            int ch = BitConverter.ToInt32(blob, 12);
                            if (ox >= 0 && oy >= 0 && cw > 0 && ch > 0 && (ox + cw) <= _srcWidth && (oy + ch) <= _srcHeight) {
                                _cropX = ox;
                                _cropY = oy;
                                _cropW = cw;
                                _cropH = ch;
                            }
                        }
                    } finally {
                        Marshal.FreeCoTaskMem(pBlob);
                    }
                }

                Guid gRot = MfNative.MF_MT_VIDEO_ROTATION;
                uint rotVal;
                _rotation = 0;
                if (curMt.GetUINT32(ref gRot, out rotVal) >= 0) {
                    _rotation = (int)rotVal;
                }

                if (_frameBmp == null || _frameBmp.Width != _cropW || _frameBmp.Height != _cropH) {
                    if (_frameBmp != null) _frameBmp.Dispose();
                    _frameBmp = new Bitmap(_cropW, _cropH, PixelFormat.Format32bppRgb);
                }
            } finally {
                if (curMt != null) Marshal.ReleaseComObject(curMt);
            }
        }

        public bool ReadNextFrame(out Bitmap frame, out int delayMs) {
            frame = null;
            delayMs = _defaultDelayMs;
            if (_disposed || _reader == null) return false;

            for (int attempts = 0; attempts < 8; attempts++) {
                uint actualStream, flags;
                long ts;
                IMFSample sample = null;
                int hr = _reader.ReadSample(MfNative.MF_SOURCE_READER_FIRST_VIDEO_STREAM, 0, out actualStream, out flags, out ts, out sample);
                if (hr < 0) return false;

                try {
                    if ((flags & MfNative.MF_SOURCE_READERF_CURRENTMEDIATYPECHANGED) != 0) {
                        RefreshFormat();
                    }
                    if ((flags & MfNative.MF_SOURCE_READERF_ENDOFSTREAM) != 0) {
                        _reader.Flush(MfNative.MF_SOURCE_READER_FIRST_VIDEO_STREAM);
                        Guid empty = Guid.Empty;
                        PropVariant pv = new PropVariant { vt = 20, hVal = 0 };
                        int hrSeek = _reader.SetCurrentPosition(ref empty, ref pv);
                        if (hrSeek < 0) {
                            Marshal.ReleaseComObject(_reader);
                            _reader = null;
                            OpenReader();
                        }
                        continue;
                    }
                    if (sample == null) continue;

                    long dur;
                    if (sample.GetSampleDuration(out dur) >= 0 && dur > 0) {
                        int d = (int)(dur / 10000L);
                        if (d >= 16 && d <= 250) delayMs = d;
                    }

                    if (!CopySampleToBitmap(sample)) continue;

                    if (_rotation == 90 || _rotation == 180 || _rotation == 270) {
                        if (_rotatedBmp != null) { _rotatedBmp.Dispose(); _rotatedBmp = null; }
                        _rotatedBmp = (Bitmap)_frameBmp.Clone();
                        if (_rotation == 90) _rotatedBmp.RotateFlip(RotateFlipType.Rotate270FlipNone);
                        else if (_rotation == 180) _rotatedBmp.RotateFlip(RotateFlipType.Rotate180FlipNone);
                        else if (_rotation == 270) _rotatedBmp.RotateFlip(RotateFlipType.Rotate90FlipNone);
                        frame = _rotatedBmp;
                        return true;
                    }

                    frame = _frameBmp;
                    return true;
                } finally {
                    if (sample != null) Marshal.ReleaseComObject(sample);
                }
            }
            return false;
        }

        private bool CopySampleToBitmap(IMFSample sample) {
            IMFMediaBuffer buf = null;
            IMFMediaBuffer contig = null;
            IMF2DBuffer buf2d = null;
            bool locked2d = false;
            bool locked1d = false;
            try {
                uint count = 0;
                if (sample.GetBufferCount(out count) >= 0 && count == 1) {
                    if (sample.GetBufferByIndex(0, out buf) >= 0 && buf != null) {
                        buf2d = buf as IMF2DBuffer;
                        if (buf2d != null) {
                            IntPtr scan0;
                            int pitch;
                            if (buf2d.Lock2D(out scan0, out pitch) >= 0) {
                                locked2d = true;
                                BlitScanlines(scan0, pitch);
                                return true;
                            }
                        }
                    }
                }

                if (sample.ConvertToContiguousBuffer(out contig) < 0 || contig == null) return false;
                IntPtr ptr;
                uint maxLen, curLen;
                if (contig.Lock(out ptr, out maxLen, out curLen) < 0) return false;
                locked1d = true;
                IntPtr topRow = ptr;
                if (_stride < 0) {
                    topRow = new IntPtr(ptr.ToInt64() + (long)(-_stride) * (_srcHeight - 1));
                }
                BlitScanlines(topRow, _stride);
                return true;
            } finally {
                if (locked2d && buf2d != null) buf2d.Unlock2D();
                if (locked1d && contig != null) contig.Unlock();
                if (contig != null) Marshal.ReleaseComObject(contig);
                if (buf != null) Marshal.ReleaseComObject(buf);
            }
        }

        private void BlitScanlines(IntPtr topRow, int pitch) {
            BitmapData bd = _frameBmp.LockBits(new Rectangle(0, 0, _cropW, _cropH), ImageLockMode.WriteOnly, PixelFormat.Format32bppRgb);
            try {
                int copyBytes = _cropW * 4;
                long srcBase = topRow.ToInt64() + (long)_cropY * pitch + (long)_cropX * 4;
                long dstBase = bd.Scan0.ToInt64();
                int dstStride = bd.Stride;
                UIntPtr count = new UIntPtr((uint)copyBytes);
                for (int y = 0; y < _cropH; y++) {
                    CopyMemory(new IntPtr(dstBase + (long)y * dstStride), new IntPtr(srcBase + (long)y * pitch), count);
                }
            } finally {
                _frameBmp.UnlockBits(bd);
            }
        }

        public void Dispose() {
            if (_disposed) return;
            _disposed = true;
            if (_reader != null) {
                try { Marshal.ReleaseComObject(_reader); } catch { }
                _reader = null;
            }
            if (_frameBmp != null) {
                try { _frameBmp.Dispose(); } catch { }
                _frameBmp = null;
            }
            if (_rotatedBmp != null) {
                try { _rotatedBmp.Dispose(); } catch { }
                _rotatedBmp = null;
            }
            if (_mfStarted) {
                _mfStarted = false;
                try { MfNative.MFShutdown(); } catch { }
            }
        }
    }

    public sealed class GifDecoder : IDisposable {
        private readonly MemoryStream _ms;
        private readonly Image _img;
        private readonly FrameDimension _dim;
        private readonly int _frameCount;
        private readonly int[] _delays;
        private readonly Bitmap _canvas;
        private bool _disposed;

        public int FrameCount { get { return _frameCount; } }

        public GifDecoder(string path) {
            byte[] bytes = File.ReadAllBytes(path);
            _ms = new MemoryStream(bytes);
            _img = Image.FromStream(_ms);
            _dim = new FrameDimension(_img.FrameDimensionsList[0]);
            _frameCount = Math.Max(1, _img.GetFrameCount(_dim));
            _delays = new int[_frameCount];
            for (int i = 0; i < _frameCount; i++) _delays[i] = 80;
            try {
                PropertyItem prop = _img.GetPropertyItem(0x5100);
                if (prop != null && prop.Value != null) {
                    int n = Math.Min(_frameCount, prop.Value.Length / 4);
                    for (int i = 0; i < n; i++) {
                        int cs = BitConverter.ToInt32(prop.Value, i * 4);
                        _delays[i] = Math.Max(40, cs * 10);
                    }
                }
            } catch { }
            _canvas = new Bitmap(Math.Max(1, _img.Width), Math.Max(1, _img.Height), PixelFormat.Format32bppRgb);
        }

        public Bitmap ReadFrame(int index, out int delayMs) {
            if (_disposed) { delayMs = 80; return null; }
            int idx = ((index % _frameCount) + _frameCount) % _frameCount;
            _img.SelectActiveFrame(_dim, idx);
            using (Graphics g = Graphics.FromImage(_canvas)) {
                g.Clear(Color.Black);
                g.DrawImage(_img, 0, 0, _canvas.Width, _canvas.Height);
            }
            delayMs = _delays[idx];
            return _canvas;
        }

        public void Dispose() {
            if (_disposed) return;
            _disposed = true;
            if (_canvas != null) _canvas.Dispose();
            if (_img != null) _img.Dispose();
            if (_ms != null) _ms.Dispose();
        }
    }

