    internal static class Win32Native {
        public const int WM_PAINT = 0x000F;
        public const int WM_ERASEBKGND = 0x0014;
        public const int WM_NCPAINT = 0x0085;
        public const int LVM_GETHEADER = 0x101F;
        public const uint RDW_INVALIDATE = 0x0001;
        public const uint RDW_FRAME = 0x0400;

        [StructLayout(LayoutKind.Sequential)]
        public struct RECT {
            public int Left;
            public int Top;
            public int Right;
            public int Bottom;
        }

        [DllImport("user32.dll")]
        public static extern IntPtr GetWindowDC(IntPtr hWnd);

        [DllImport("user32.dll")]
        public static extern int ReleaseDC(IntPtr hWnd, IntPtr hDC);

        [DllImport("user32.dll")]
        public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);

        [DllImport("user32.dll")]
        public static extern bool RedrawWindow(IntPtr hWnd, IntPtr lprcUpdate, IntPtr hrgnUpdate, uint flags);

        [DllImport("user32.dll", CharSet = CharSet.Auto)]
        public static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);
    }

    internal sealed class ThemedTabStripWindow : NativeWindow {
        private readonly ThemeSurfaceEngine _engine;
        private readonly TabControl _tc;

        public ThemedTabStripWindow(ThemeSurfaceEngine engine, TabControl tc) {
            _engine = engine;
            _tc = tc;
            _tc.HandleCreated += OnHandleCreated;
            _tc.HandleDestroyed += OnHandleDestroyed;
            if (_tc.IsHandleCreated) AssignHandle(_tc.Handle);
        }

        private void OnHandleCreated(object sender, EventArgs e) {
            if (_tc.IsHandleCreated) AssignHandle(_tc.Handle);
        }

        private void OnHandleDestroyed(object sender, EventArgs e) {
            ReleaseHandle();
        }

        protected override void WndProc(ref Message m) {
            base.WndProc(ref m);
            if (m.Msg == Win32Native.WM_PAINT && _engine != null && _engine.IsStyled && _tc.TabCount > 0 && _tc.Visible) {
                try {
                    bool lightMode = !_engine.IsActive;
                    using (Graphics g = Graphics.FromHwnd(_tc.Handle))
                    using (SolidBrush br = new SolidBrush(lightMode ? Color.White : Color.FromArgb(14, 20, 36))) {
                        Rectangle disp = _tc.DisplayRectangle;
                        int stripH = Math.Max(22, disp.Top);
                        Rectangle lastRect = _tc.GetTabRect(_tc.TabCount - 1);
                        int fillX = Math.Max(0, lastRect.Right - 1);
                        if (fillX < _tc.Width) {
                            g.FillRectangle(br, fillX, 0, _tc.Width - fillX, stripH);
                        }
                        g.FillRectangle(br, 0, 0, 2, stripH);
                        g.FillRectangle(br, 0, stripH - 2, _tc.Width, 3);
                        if (lightMode) {
                            Color c1, c2, c3;
                            ThemeSurfaceEngine.GetBorderColorsForMode(_engine.BorderStyle, true, out c1, out c2, out c3);
                            RectangleF bRect = new RectangleF(0f, stripH - 1f, Math.Max(4f, _tc.Width), Math.Max(4f, _tc.Height - stripH));
                            using (LinearGradientBrush gb = ThemeSurfaceEngine.CreateGradientBrush(bRect, c1, c2, c3, 195))
                            using (Pen pen = new Pen(gb, 1.3f)) {
                                g.DrawLine(pen, 0, stripH - 1, _tc.Width, stripH - 1);
                                g.DrawRectangle(pen, 0, stripH - 1, _tc.Width - 1, Math.Max(1, _tc.Height - stripH));
                            }
                        } else {
                            using (Pen pen = new Pen(Color.FromArgb(70, 96, 138), 1)) {
                                g.DrawLine(pen, 0, stripH - 1, _tc.Width, stripH - 1);
                                g.DrawRectangle(pen, 0, stripH - 1, _tc.Width - 1, Math.Max(1, _tc.Height - stripH));
                            }
                        }
                    }
                } catch { }
            }
        }
    }

    internal sealed class ThemedComboBoxWindow : NativeWindow {
        private readonly ThemeSurfaceEngine _engine;
        private readonly ComboBox _cbo;
        private bool _hovered;

        public ThemedComboBoxWindow(ThemeSurfaceEngine engine, ComboBox cbo) {
            _engine = engine;
            _cbo = cbo;
            _cbo.HandleCreated += OnHandleCreated;
            _cbo.HandleDestroyed += OnHandleDestroyed;
            _cbo.MouseEnter += OnMouseEnter;
            _cbo.MouseLeave += OnMouseLeave;
            _cbo.GotFocus += OnFocusChanged;
            _cbo.LostFocus += OnFocusChanged;
            _cbo.SelectedIndexChanged += OnFocusChanged;
            if (_cbo.IsHandleCreated) AssignHandle(_cbo.Handle);
        }

        public void RefreshControl() {
            if (_cbo != null && !_cbo.IsDisposed && _cbo.Visible && _cbo.IsHandleCreated) _cbo.Invalidate();
        }

        private void OnHandleCreated(object sender, EventArgs e) {
            if (_cbo.IsHandleCreated) AssignHandle(_cbo.Handle);
        }

        private void OnHandleDestroyed(object sender, EventArgs e) {
            ReleaseHandle();
        }

        private void OnMouseEnter(object sender, EventArgs e) {
            _hovered = true;
            if (_engine != null && _engine.IsStyled) _cbo.Invalidate();
        }

        private void OnMouseLeave(object sender, EventArgs e) {
            _hovered = false;
            if (_engine != null && _engine.IsStyled) _cbo.Invalidate();
        }

        private void OnFocusChanged(object sender, EventArgs e) {
            if (_engine != null && _engine.IsStyled) _cbo.Invalidate();
        }

        protected override void WndProc(ref Message m) {
            if (m.Msg == Win32Native.WM_ERASEBKGND && _engine != null && _engine.IsStyled && _cbo.Visible) {
                m.Result = (IntPtr)1;
                return;
            }
            base.WndProc(ref m);
            if (m.Msg == Win32Native.WM_PAINT && _engine != null && _engine.IsStyled && _cbo.Visible && _cbo.Width > 6 && _cbo.Height > 6) {
                try {
                    bool lightMode = !_engine.IsActive;
                    using (Graphics hg = Graphics.FromHwnd(_cbo.Handle))
                    using (BufferedGraphics bg = BufferedGraphicsManager.Current.Allocate(hg, new Rectangle(0, 0, _cbo.Width, _cbo.Height))) {
                        Graphics og = bg.Graphics;
                        if (lightMode) og.Clear(Color.White);
                        else _engine.PaintAlignedParentLayer(og, _cbo);
                        Color c1, c2, c3;
                        ThemeSurfaceEngine.GetBorderColorsForMode(_engine.BorderStyle, lightMode, out c1, out c2, out c3);
                        bool active = _hovered || _cbo.Focused || _cbo.DroppedDown;
                        Color topFill, botFill, fg, arrCol;
                        if (lightMode) {
                            topFill = _cbo.Enabled ? Color.White : Color.FromArgb(248, 250, 252);
                            botFill = _cbo.Enabled ? Color.FromArgb(255, 247, 250, 255) : Color.FromArgb(241, 245, 249);
                            fg = _cbo.Enabled ? Color.FromArgb(15, 23, 42) : Color.FromArgb(148, 163, 184);
                            arrCol = _cbo.Enabled ? Color.FromArgb(51, 65, 85) : Color.FromArgb(148, 163, 184);
                        } else {
                            topFill = _cbo.Enabled ? Color.FromArgb(220, 14, 22, 40) : Color.FromArgb(170, 16, 22, 36);
                            botFill = _cbo.Enabled ? Color.FromArgb(215, 22, 32, 56) : Color.FromArgb(165, 20, 28, 44);
                            fg = _cbo.Enabled ? Color.White : Color.FromArgb(148, 163, 184);
                            arrCol = _cbo.Enabled ? Color.FromArgb(226, 232, 240) : Color.FromArgb(148, 163, 184);
                        }
                        ThemeSurfaceEngine.DrawGlowingPill(og, new Rectangle(0, 0, _cbo.Width, _cbo.Height), c1, c2, c3, topFill, botFill, 8f, active, false, (_engine.BorderStyle == 1 || _engine.BorderStyle == 4 || _engine.BorderStyle == 5 || _engine.BorderStyle == 9 || _engine.BorderStyle == 12), _cbo.Enabled, _engine.BorderStyle, _engine.CurrentAmbientPhase, _engine.ShowOrnaments ? 1 : 0, lightMode, _engine.OrnamentSeason);

                        string txt = "";
                        if (_cbo.SelectedIndex >= 0 && _cbo.SelectedItem != null) {
                            txt = _cbo.GetItemText(_cbo.SelectedItem);
                        } else {
                            txt = _cbo.Text;
                        }
                        Rectangle txtRect = new Rectangle(10, 1, Math.Max(4, _cbo.Width - 28), Math.Max(4, _cbo.Height - 2));
                        TextFormatFlags cFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
                        if (_cbo.Enabled) {
                            ThemeSurfaceEngine.DrawModeText(og, txt, _cbo.Font, txtRect, fg, _cbo.Font.Bold, cFlags, _engine.TextPreset, lightMode, _engine.StrongTextOutline);
                        } else {
                            TextRenderer.DrawText(og, txt, _cbo.Font, txtRect, fg, cFlags);
                        }

                        int cx = _cbo.Width - 15;
                        int cy = _cbo.Height / 2 - 2;
                        og.SmoothingMode = SmoothingMode.AntiAlias;
                        using (Pen arrPen = new Pen(arrCol, 1.6f)) {
                            arrPen.StartCap = LineCap.Round;
                            arrPen.EndCap = LineCap.Round;
                            arrPen.LineJoin = LineJoin.Round;
                            og.DrawLines(arrPen, new Point[] {
                                new Point(cx - 4, cy),
                                new Point(cx, cy + 4),
                                new Point(cx + 4, cy)
                            });
                        }
                        bg.Render(hg);
                    }
                } catch { }
            }
        }
    }

    internal sealed class ThemedBorderWindow : NativeWindow {
        private readonly ThemeSurfaceEngine _engine;
        private readonly Control _ctrl;

        public ThemedBorderWindow(ThemeSurfaceEngine engine, Control ctrl) {
            _engine = engine;
            _ctrl = ctrl;
            _ctrl.HandleCreated += OnHandleCreated;
            _ctrl.HandleDestroyed += OnHandleDestroyed;
            if (_ctrl.IsHandleCreated) AssignHandle(_ctrl.Handle);
        }

        public void RefreshControl() {
            if (_ctrl != null && !_ctrl.IsDisposed && _ctrl.Visible && _ctrl.IsHandleCreated) {
                Win32Native.RedrawWindow(_ctrl.Handle, IntPtr.Zero, IntPtr.Zero, Win32Native.RDW_INVALIDATE | Win32Native.RDW_FRAME);
            }
        }

        private void OnHandleCreated(object sender, EventArgs e) {
            if (_ctrl.IsHandleCreated) AssignHandle(_ctrl.Handle);
        }

        private void OnHandleDestroyed(object sender, EventArgs e) {
            ReleaseHandle();
        }

        private bool ShouldSkipBorder() {
            TextBoxBase tb = _ctrl as TextBoxBase;
            if (tb != null && tb.BorderStyle == BorderStyle.None) return true;
            TreeView tv = _ctrl as TreeView;
            if (tv != null && tv.BorderStyle == BorderStyle.None) return true;
            ListView lv = _ctrl as ListView;
            if (lv != null && lv.BorderStyle == BorderStyle.None) return true;
            return false;
        }

        protected override void WndProc(ref Message m) {
            base.WndProc(ref m);
            if ((m.Msg == Win32Native.WM_NCPAINT || m.Msg == Win32Native.WM_PAINT) && _engine != null && _engine.IsStyled && _ctrl.Visible) {
                if (ShouldSkipBorder()) return;
                IntPtr hdc = IntPtr.Zero;
                try {
                    Win32Native.RECT rc;
                    if (!Win32Native.GetWindowRect(_ctrl.Handle, out rc)) return;
                    int w = rc.Right - rc.Left;
                    int h = rc.Bottom - rc.Top;
                    if (w <= 4 || h <= 4) return;
                    hdc = Win32Native.GetWindowDC(_ctrl.Handle);
                    if (hdc == IntPtr.Zero) return;
                    bool lightMode = !_engine.IsActive;
                    using (Graphics g = Graphics.FromHdc(hdc)) {
                        Color c1, c2, c3;
                        ThemeSurfaceEngine.GetBorderColorsForMode(_engine.BorderStyle, lightMode, out c1, out c2, out c3);
                        using (Pen baseFrame = new Pen(lightMode ? Color.White : Color.FromArgb(14, 22, 38), 2f)) {
                            g.DrawRectangle(baseFrame, 0, 0, w - 1, h - 1);
                        }
                        Rectangle frameRect = new Rectangle(0, 0, w - 1, h - 1);
                        using (LinearGradientBrush gb = ThemeSurfaceEngine.CreateGradientBrush(new RectangleF(0, 0, w - 1, h - 1), c1, c2, c3, lightMode ? 235 : 210))
                        using (Pen accent = new Pen(gb, 1.5f)) {
                            g.DrawRectangle(accent, frameRect);
                        }
                        if (_engine.ShowOrnaments && w >= 120 && h >= 44) {
                            Color warmCol, coolCol;
                            ThemeSurfaceEngine.GetSeasonalOrnamentColors(_engine.OrnamentSeason, _engine.BorderStyle, lightMode, out warmCol, out coolCol);
                            Color dotCol = lightMode ? Color.FromArgb(230, warmCol) : ((_engine.OrnamentSeason == 0) ? Color.FromArgb(225, 255, 226, 240) : Color.FromArgb(225, coolCol));
                            using (Pen pWarm = new Pen(Color.FromArgb(225, warmCol), 1.6f))
                            using (Pen pCool = new Pen(Color.FromArgb(225, coolCol), 1.6f))
                            using (SolidBrush bDot = new SolidBrush(dotCol)) {
                                int k = 7;
                                g.DrawLine(pWarm, 0, 0, k, 0);
                                g.DrawLine(pWarm, 0, 0, 0, k);
                                g.DrawLine(pWarm, 0, h - 1, k, h - 1);
                                g.DrawLine(pWarm, 0, h - 1 - k, 0, h - 1);
                                g.DrawLine(pCool, w - 1 - k, 0, w - 1, 0);
                                g.DrawLine(pCool, w - 1, 0, w - 1, k);
                                g.DrawLine(pCool, w - 1 - k, h - 1, w - 1, h - 1);
                                g.DrawLine(pCool, w - 1, h - 1 - k, w - 1, h - 1);
                                g.FillEllipse(bDot, 2, 2, 2, 2);
                                g.FillEllipse(bDot, w - 4, 2, 2, 2);
                                g.FillEllipse(bDot, 2, h - 4, 2, 2);
                                g.FillEllipse(bDot, w - 4, h - 4, 2, 2);
                            }
                        }
                    }
                } catch {
                } finally {
                    if (hdc != IntPtr.Zero) Win32Native.ReleaseDC(_ctrl.Handle, hdc);
                }
            }
        }
    }

    internal sealed class ThemedListHeaderWindow : NativeWindow {
        private readonly ThemeSurfaceEngine _engine;
        private readonly ListView _lv;

        public ThemedListHeaderWindow(ThemeSurfaceEngine engine, ListView lv) {
            _engine = engine;
            _lv = lv;
            _lv.HandleCreated += OnHandleCreated;
            _lv.HandleDestroyed += OnHandleDestroyed;
            if (_lv.IsHandleCreated) AttachHeader();
        }

        public void RefreshControl() {
            if (_lv != null && !_lv.IsDisposed && _lv.Visible && _lv.IsHandleCreated) _lv.Invalidate();
            if (Handle != IntPtr.Zero) Win32Native.RedrawWindow(Handle, IntPtr.Zero, IntPtr.Zero, Win32Native.RDW_INVALIDATE | Win32Native.RDW_FRAME);
        }

        private void OnHandleCreated(object sender, EventArgs e) {
            AttachHeader();
        }

        private void OnHandleDestroyed(object sender, EventArgs e) {
            ReleaseHandle();
        }

        private void AttachHeader() {
            ReleaseHandle();
            if (!_lv.IsHandleCreated) return;
            IntPtr hHdr = Win32Native.SendMessage(_lv.Handle, Win32Native.LVM_GETHEADER, IntPtr.Zero, IntPtr.Zero);
            if (hHdr != IntPtr.Zero) AssignHandle(hHdr);
        }

        protected override void WndProc(ref Message m) {
            base.WndProc(ref m);
            if (m.Msg == Win32Native.WM_PAINT && _engine != null && _engine.IsStyled && _lv.Visible && _lv.View == View.Details) {
                try {
                    Win32Native.RECT rc;
                    if (!Win32Native.GetWindowRect(Handle, out rc)) return;
                    int w = rc.Right - rc.Left;
                    int h = rc.Bottom - rc.Top;
                    int usedW = 0;
                    foreach (ColumnHeader col in _lv.Columns) usedW += col.Width;
                    if (usedW < w) {
                        bool lightMode = !_engine.IsActive;
                        Color sepCol;
                        if (lightMode) {
                            Color c1, c2, c3;
                            ThemeSurfaceEngine.GetBorderColorsForMode(_engine.BorderStyle, true, out c1, out c2, out c3);
                            sepCol = Color.FromArgb(180, c2);
                        } else {
                            sepCol = Color.FromArgb(55, 76, 110);
                        }
                        using (Graphics g = Graphics.FromHwnd(Handle))
                        using (SolidBrush br = new SolidBrush(lightMode ? Color.White : Color.FromArgb(18, 28, 48)))
                        using (Pen sep = new Pen(sepCol, 1)) {
                            g.FillRectangle(br, usedW, 0, w - usedW, h);
                            g.DrawLine(sep, usedW, h - 1, w, h - 1);
                        }
                    }
                } catch { }
            }
        }
    }

    public sealed class GlassSlider : Control {
        private int _min = 20;
        private int _max = 88;
        private int _val = 58;
        private bool _dragging;
        private bool _hovered;
        private ThemeSurfaceEngine _engine;

        public event EventHandler ValueChanged;

        public int Minimum {
            get { return _min; }
            set { _min = value; if (_max < _min) _max = _min; Value = _val; Invalidate(); }
        }

        public int Maximum {
            get { return _max; }
            set { _max = value; if (_max < _min) _min = _max; Value = _val; Invalidate(); }
        }

        public int Value {
            get { return _val; }
            set {
                int clamped = Math.Max(_min, Math.Min(_max, value));
                if (clamped != _val) {
                    _val = clamped;
                    Invalidate();
                    EventHandler h = ValueChanged;
                    if (h != null) h(this, EventArgs.Empty);
                } else {
                    Invalidate();
                }
            }
        }

        public ThemeSurfaceEngine ThemeEngine {
            get { return _engine; }
            set { _engine = value; Invalidate(); }
        }

        public GlassSlider() {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.Selectable, true);
            Cursor = Cursors.Hand;
            Size = new Size(396, 26);
        }

        protected override void OnPaintBackground(PaintEventArgs pevent) {
        }

        private void SetFromX(int x) {
            int pad = 10;
            int trackW = Math.Max(1, Width - pad * 2);
            double ratio = Math.Max(0.0, Math.Min(1.0, (double)(x - pad) / trackW));
            Value = _min + (int)Math.Round(ratio * (_max - _min));
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hovered = true; Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hovered = false; Invalidate(); }

        protected override void OnMouseDown(MouseEventArgs e) {
            base.OnMouseDown(e);
            if (e.Button == MouseButtons.Left) {
                Focus();
                _dragging = true;
                SetFromX(e.X);
            }
        }

        protected override void OnMouseMove(MouseEventArgs e) {
            base.OnMouseMove(e);
            if (_dragging) SetFromX(e.X);
        }

        protected override void OnMouseUp(MouseEventArgs e) {
            base.OnMouseUp(e);
            _dragging = false;
        }

        protected override bool IsInputKey(Keys keyData) {
            if (keyData == Keys.Left || keyData == Keys.Right || keyData == Keys.Up || keyData == Keys.Down) return true;
            return base.IsInputKey(keyData);
        }

        protected override void OnKeyDown(KeyEventArgs e) {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Left || e.KeyCode == Keys.Down) { Value = _val - 2; e.Handled = true; }
            else if (e.KeyCode == Keys.Right || e.KeyCode == Keys.Up) { Value = _val + 2; e.Handled = true; }
        }

        protected override void OnPaint(PaintEventArgs e) {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            bool isStyled = (_engine != null && _engine.IsStyled);
            bool isThemed = (_engine != null && _engine.IsActive);
            bool lightMode = !isThemed;

            if (isThemed) {
                _engine.PaintAlignedLayer(g, this, false);
                _engine.PaintParticlesOverlay(g, this, false);
            } else if (isStyled) {
                _engine.PaintWhiteBackdropWithParticles(g, this);
            } else {
                Color bg = (Parent != null) ? Parent.BackColor : Color.White;
                using (SolidBrush br = new SolidBrush(bg)) {
                    g.FillRectangle(br, 0, 0, Width, Height);
                }
            }

            int pad = 10;
            int trackW = Math.Max(8, Width - pad * 2);
            int cy = Height / 2;
            int trackH = 6;
            RectangleF trackRect = new RectangleF(pad, cy - trackH / 2f, trackW, trackH);
            double frac = (_max > _min) ? (double)(_val - _min) / (_max - _min) : 0.0;
            int thumbX = pad + (int)Math.Round(frac * trackW);

            using (GraphicsPath trackPath = ThemeSurfaceEngine.CreateRoundedRect(trackRect, 3f)) {
                using (SolidBrush tBr = new SolidBrush(isThemed ? Color.FromArgb(180, 15, 23, 42) : Color.FromArgb(226, 232, 240))) {
                    g.FillPath(tBr, trackPath);
                }
                if (isThemed || isStyled) {
                    using (Pen tPen = new Pen(isThemed ? Color.FromArgb(110, 148, 163, 184) : Color.FromArgb(180, 203, 213, 225), 1f)) {
                        g.DrawPath(tPen, trackPath);
                    }
                }
            }

            int fillW = Math.Max(4, thumbX - pad);
            RectangleF fillRect = new RectangleF(pad, cy - trackH / 2f, fillW, trackH);
            Color c1, c2, c3;
            if (isStyled) {
                ThemeSurfaceEngine.GetBorderColorsForMode(_engine.BorderStyle, lightMode, out c1, out c2, out c3);
            } else {
                c1 = Color.FromArgb(37, 99, 235);
                c2 = Color.FromArgb(59, 130, 246);
                c3 = Color.FromArgb(29, 78, 216);
            }
            using (GraphicsPath fillPath = ThemeSurfaceEngine.CreateRoundedRect(fillRect, 3f))
            using (LinearGradientBrush fBr = ThemeSurfaceEngine.CreateGradientBrush(fillRect, c1, c2, c3, 255)) {
                g.FillPath(fBr, fillPath);
            }

            if (isStyled && _engine.ShowOrnaments) {
                Color warmCol, coolCol;
                int season = _engine.OrnamentSeason;
                ThemeSurfaceEngine.GetSeasonalOrnamentColors(season, _engine.BorderStyle, lightMode, out warmCol, out coolCol);
                float phase = _engine.CurrentAmbientPhase;
                int glA = Math.Max(140, Math.Min(245, (int)Math.Round(185.0 + 45.0 * Math.Sin(phase * 1.4))));
                ThemeSurfaceEngine.DrawSeasonBud(g, season, pad - 1f, cy, 4.6f, -90f, glA, lightMode);
                ThemeSurfaceEngine.DrawSeasonDrift(g, season, pad + trackW + 1f, cy, 4.6f, 45f, warmCol, glA, lightMode);
            }

            int r = (_hovered || _dragging) ? 8 : 7;
            RectangleF thumbRect = new RectangleF(thumbX - r, cy - r, r * 2, r * 2);
            if (isStyled) {
                RectangleF glowRect = thumbRect;
                glowRect.Inflate(2.5f, 2.5f);
                int haloA = (_hovered || _dragging) ? (lightMode ? 75 : 95) : (lightMode ? 42 : 55);
                using (SolidBrush gBr = new SolidBrush(Color.FromArgb(haloA, c2))) {
                    g.FillEllipse(gBr, glowRect);
                }
            }
            using (SolidBrush core = new SolidBrush(isThemed ? Color.FromArgb(14, 22, 40) : Color.White)) {
                g.FillEllipse(core, thumbRect);
            }
            using (Pen ring = new Pen(isThemed ? c2 : c1, 2.2f)) {
                g.DrawEllipse(ring, thumbRect);
            }
            if (isStyled && _engine.ShowOrnaments) {
                Color warmCol, coolCol;
                int season = _engine.OrnamentSeason;
                ThemeSurfaceEngine.GetSeasonalOrnamentColors(season, _engine.BorderStyle, lightMode, out warmCol, out coolCol);
                Color innerTip = (season == 0) ? Color.FromArgb(255, 245, 250) : coolCol;
                ThemeSurfaceEngine.DrawSeasonEmblem(g, season, thumbX, cy, 5.4f, _dragging ? 20f : 0f, warmCol, innerTip, 245, lightMode);
            }
        }
    }

