        private volatile bool _showAnimation = true;
        private volatile int _animEffect = 0; // 0=FollowSeason, 1=Meteor, 2=ShootingStar, 3=Wind, 4=Sunbeams, 5=Rain, 6=Sunflower, 7=Fire, 8=Lightning, 9=Tornado, 10=Tsunami
        private int _pendingRepaint = 0;
