                if (_showOrnaments != value) {
                    _showOrnaments = value;
                    SyncAmbientTimer();
                    if (IsStyled) RefreshNow();
                }
            }
        }
        public int OrnamentSeason {
            get { return _ornamentSeason; }
            set {
                int clamped = Math.Max(0, Math.Min(13, value));
                if (_ornamentSeason != clamped || _borderStyle != clamped) {
                    _ornamentSeason = clamped;
                    _borderStyle = clamped;
                    ReinitParticlesForSeason();
                    if (IsStyled) RefreshNow();
                }
            }
        }
        public bool ShowAnimation {
            get { return _showAnimation; }
            set {
                if (_showAnimation != value) {
                    _showAnimation = value;
                    SyncAmbientTimer();
                    if (IsStyled) RefreshNow();
                }
            }
        }
        public int AnimEffect {
            get { return _animEffect; }
            set {
                int clamped = Math.Max(0, Math.Min(10, value));
                if (_animEffect != clamped) {
                    _animEffect = clamped;
                    ReinitParticlesForSeason();
                    SyncAmbientTimer();
                    if (IsStyled) RefreshNow();
                }
            }
        }
        public int ActiveParticleCount { get { return (IsStyled && _showAnimation && _particles != null) ? _particles.Length : 0; } }
        public bool ParticleTimerRunning { get { return _ambientTimer != null && _ambientTimer.Enabled && _showAnimation; } }
        public long ParticleTickCount { get { return Interlocked.Read(ref _particleTickCount); } }
        public bool AmbientTimerRunning { get { return _ambientTimer != null && _ambientTimer.Enabled; } }
        internal float CurrentAmbientPhase { get { return GetAmbientPhase(); } }
        public long FrameCount { get { return Interlocked.Read(ref _frameCount); } }
        public int ActiveAnimationCount { get { return _activeAnims.Count; } }
        public string LastError { get { return _lastError; } }
        public Control ActiveNavButton { get { return _activeNavBtn; } set { _activeNavBtn = value; } }

        private float GetAmbientPhase() {
            return (float)(_animClock.ElapsedMilliseconds * 0.0018);
        }

        private Rectangle[] _dirtyRectBuf;

        private Point GetControlFormOrigin(Control ctrl) {
            if (ctrl == null || ctrl == _form || _form == null || !_form.IsHandleCreated || !ctrl.IsHandleCreated) {
                return Point.Empty;
            }
            try {
                return _form.PointToClient(ctrl.PointToScreen(Point.Empty));
            } catch {
                return Point.Empty;
            }
        }

        private void DisposeParticleSprites() {
            if (_particleSpritesLight != null) {
                for (int i = 0; i < _particleSpritesLight.Length; i++) {
                    if (_particleSpritesLight[i] != null) {
                        _particleSpritesLight[i].Dispose();
                        _particleSpritesLight[i] = null;
                    }
                }
                _particleSpritesLight = null;
            }
            if (_particleSpritesDark != null) {
                for (int i = 0; i < _particleSpritesDark.Length; i++) {
                    if (_particleSpritesDark[i] != null) {
                        _particleSpritesDark[i].Dispose();
                        _particleSpritesDark[i] = null;
                    }
                }
                _particleSpritesDark = null;
            }
            _spriteSeason = -1;
        }

        private static Bitmap RenderParticleSprite(int season, int slot, bool lightBg) {
            Bitmap bmp = new Bitmap(28, 28, PixelFormat.Format32bppPArgb);
            using (Graphics sg = Graphics.FromImage(bmp)) {
                sg.Clear(Color.Transparent);
                sg.SmoothingMode = SmoothingMode.AntiAlias;
                sg.PixelOffsetMode = PixelOffsetMode.HighQuality;
                int a = lightBg ? 215 : 230;
                switch (season) {
                    case 1: // Ha: la xanh / huong duong / tia nang
                        if (slot <= 1) {
                            DrawSummerLeaf(sg, 14f, 14f, 10.6f, 0f, a, lightBg);
                        } else if (slot <= 3) {
                            DrawSunflower(sg, 14f, 14f, 9.2f, 0f, a, lightBg);
                        } else {
                            Color sCol = lightBg
                                ? (slot == 4 ? Color.FromArgb(234, 158, 12) : Color.FromArgb(14, 165, 233))
                                : (slot == 4 ? Color.FromArgb(254, 240, 138) : Color.FromArgb(125, 211, 252));
                            DrawFourPointStar(sg, 14f, 14f, 8.6f, sCol, a, lightBg);
                        }
                        break;

                    case 2: // Thu: la phong 3 mau / la dai 3 mau
                        if (slot <= 2) {
                            Color bCol = (slot == 0)
                                ? Color.FromArgb(217, 119, 6)
                                : ((slot == 1) ? Color.FromArgb(234, 88, 12) : Color.FromArgb(202, 138, 4));
                            Color tCol = lightBg
                                ? ((slot == 0) ? Color.FromArgb(253, 224, 71) : ((slot == 1) ? Color.FromArgb(251, 191, 36) : Color.FromArgb(254, 240, 138)))
                                : Color.FromArgb(254, 249, 195);
                            DrawAutumnMapleLeaf(sg, 14f, 14f, 9.6f, 0f, bCol, tCol, a, lightBg);
                        } else {
                            int v = slot - 3;
                            Color lCol = lightBg
                                ? ((v == 0) ? Color.FromArgb(234, 158, 12) : ((v == 1) ? Color.FromArgb(234, 88, 12) : Color.FromArgb(217, 119, 6)))
                                : ((v == 0) ? Color.FromArgb(250, 204, 21) : ((v == 1) ? Color.FromArgb(251, 146, 60) : Color.FromArgb(253, 224, 71)));
                            DrawAutumnLeaf(sg, 14f, 14f, 10.6f, 0f, lCol, a, lightBg);
                        }
                        break;

                    case 3: // Dong: bong tuyet / hat tuyet
                        if (slot <= 1) {
                            DrawSnowflake(sg, 14f, 14f, 9.4f, 0f, a, lightBg);
                        } else {
                            DrawSnowDot(sg, 14f, 14f, 8.8f, a, lightBg);
                        }
                        break;

                    case 4: // Hoa Huong Duong: bong hoa huong duong, canh vang, la xanh
                        if (slot <= 2) {
                            float rad = (slot == 0) ? 9.8f : ((slot == 1) ? 8.8f : 7.8f);
                            DrawSunflower(sg, 14f, 14f, rad, 0f, a, lightBg);
                        } else if (slot <= 4) {
                            DrawSunflowerPetal(sg, 14f, 14f, 10.6f, 0f, a, lightBg);
                        } else {
                            DrawSummerLeaf(sg, 14f, 14f, 10.2f, 0f, a, lightBg);
                        }
                        break;

                    default: // Xuan: canh dao / hoa anh dao
                        if (slot <= 1) {
                            Color pCol = lightBg
                                ? (slot == 0 ? Color.FromArgb(244, 108, 166) : Color.FromArgb(255, 134, 186))
                                : (slot == 0 ? Color.FromArgb(255, 166, 206) : Color.FromArgb(255, 204, 228));
                            DrawSakuraPetal(sg, 14f, 14f, 10.6f, 0f, pCol, a, lightBg);
                        } else {
                            Color oCol = lightBg ? Color.FromArgb(244, 92, 156) : Color.FromArgb(255, 138, 192);
                            Color iCol = lightBg ? Color.FromArgb(255, 224, 238) : Color.White;
                            DrawSakuraFlower(sg, 14f, 14f, 9.2f, 0f, oCol, iCol, Color.FromArgb(219, 39, 119), a, lightBg);
                        }
                        break;
                }
            }
            return bmp;
        }

        private int GetEffectiveAnimEffect() {
            if (_animEffect == 0) {
                if (_ornamentSeason >= 5 && _ornamentSeason <= 8) return _ornamentSeason + 2;
                if (_ornamentSeason >= 9 && _ornamentSeason <= 13) return _ornamentSeason - 8;
            }
            return _animEffect;
        }

        private int GetEffectiveSpriteSeason() {
            if (GetEffectiveAnimEffect() == 6) return 4;
            return Math.Max(0, Math.Min(4, _ornamentSeason));
        }

        private static int GetParticleCountForEffect(int effect) {
            switch (effect) {
                case 1:  return 14; // Thien thach
                case 2:  return 16; // Sao bang
                case 3:  return 16; // Gio
                case 4:  return 24; // Tia nang
                case 5:  return 42; // Mua
                case 7:  return 30; // Lua
                case 8:  return 16; // Sam chop
                case 9:  return 20; // Loc xoay
                case 10: return 26; // Song than
                default: return 22; // Hoa tiet mua / Hoa huong duong
            }
        }

        private void EnsureParticleSprites() {
            int s = GetEffectiveSpriteSeason();
            if (_spriteSeason == s && _particleSpritesLight != null && _particleSpritesDark != null) return;
            DisposeParticleSprites();
            _particleSpritesLight = new Bitmap[6];
            _particleSpritesDark  = new Bitmap[6];
            for (int i = 0; i < 6; i++) {
                _particleSpritesLight[i] = RenderParticleSprite(s, i, true);
                _particleSpritesDark[i]  = RenderParticleSprite(s, i, false);
            }
            _spriteSeason = s;
        }

        private void EnsureParticlesInitialized() {
            int effAnim = GetEffectiveAnimEffect();
            if (_particles == null || _particleSeason != _ornamentSeason || _particleEffect != effAnim) {
                ReinitParticlesForSeason();
            } else {
                EnsureParticleSprites();
            }
        }

        private void ReinitParticlesForSeason() {
            int effAnim = GetEffectiveAnimEffect();
            int count = GetParticleCountForEffect(effAnim);
            int w = (_form != null && !_form.IsDisposed) ? Math.Max(640, _form.ClientSize.Width) : 1102;
            int h = (_form != null && !_form.IsDisposed) ? Math.Max(420, _form.ClientSize.Height) : 658;
            if (_particles == null || _particles.Length != count) {
                _particles = new SeasonParticle[count];
                for (int i = 0; i < count; i++) {
                    _particles[i] = new SeasonParticle();
                }
            }
            for (int i = 0; i < count; i++) {
                SeasonParticle p = _particles[i];
                if (effAnim == 1) p.Kind = (i < 10) ? 0 : 1;
                else if (effAnim == 2) p.Kind = (i < 9) ? 0 : 1;
                else if (effAnim == 3) p.Kind = (i < 10) ? 0 : 1;
                else if (effAnim == 4) p.Kind = (i < 10) ? 0 : 1;
                else if (effAnim == 5) p.Kind = (i < 34) ? 0 : 1;
                else if (effAnim == 7) p.Kind = (i < 14) ? 0 : 1;
                else if (effAnim == 8) p.Kind = (i < 7) ? 0 : 1;
                else if (effAnim == 9) p.Kind = (i < 4) ? 0 : 1;
                else if (effAnim == 10) p.Kind = (i < 8) ? 0 : 1;
                ResetParticle(p, w, h, true);
                p.PrevRect = p.CurRect;
            }
            _particleSeason = _ornamentSeason;
            _particleEffect = effAnim;
            EnsureParticleSprites();
            _lastParticleMs = _animClock.ElapsedMilliseconds;
        }

        private static Rectangle ComputeParticleRect(SeasonParticle p, int effect) {
            if (effect == 0 || effect == 6) {
                int pad = (int)Math.Ceiling(p.Size * 1.5f + 6f);
                return new Rectangle((int)Math.Floor(p.X) - pad, (int)Math.Floor(p.Y) - pad, pad * 2, pad * 2);
            }
            if (effect == 9 && p.Kind == 0) {
                int fh = (int)Math.Ceiling(Math.Max(75f, p.Size));
                return new Rectangle((int)Math.Floor(p.X) - 62, (int)Math.Floor(p.Y) - fh - 20, 124, fh + 38);
            }
            if (effect == 10 && p.Kind == 0) {
                float minWx = Math.Min(p.X, p.TailX);
                float maxWx = Math.Max(p.X, p.TailX);
                int ch = (int)Math.Ceiling(Math.Max(26f, p.Size));
                return new Rectangle((int)Math.Floor(minWx) - 24, (int)Math.Floor(p.Y) - ch - 22, Math.Max(12, (int)Math.Ceiling(maxWx - minWx) + 52), ch + 44);
            }
            int padX = 14, padY = 14;
            switch (effect) {
                case 1: padX = 18; padY = 18; break;
                case 2: padX = 16; padY = 16; break;
                case 3:
                    int wave = (int)Math.Ceiling(Math.Abs(p.SwayAmp) + 16f);
                    padX = 16;
                    padY = wave;
                    break;
                case 4:
                    padX = (p.Kind == 0) ? 14 : 18;
                    padY = (p.Kind == 0) ? 14 : 18;
                    break;
                case 5:
                    if (p.Kind == 0) {
                        padX = 8; padY = 8;
                    } else {
                        return new Rectangle((int)Math.Floor(p.X) - 26, (int)Math.Floor(p.Y) - 18, 52, 30);
                    }
                    break;
                case 7: padX = 18; padY = 20; break;
                case 8: padX = (p.Kind == 0) ? 58 : 16; padY = (p.Kind == 0) ? 26 : 16; break;
                case 9: padX = 20; padY = (int)Math.Ceiling(Math.Abs(p.SwayAmp) + 18f); break;
                case 10: padX = 14; padY = 14; break;
            }
            float minX = Math.Min(p.X, p.TailX);
            float maxX = Math.Max(p.X, p.TailX);
            float minY = Math.Min(p.Y, p.TailY);
            float maxY = Math.Max(p.Y, p.TailY);
            int rx = (int)Math.Floor(minX) - padX;
            int ry = (int)Math.Floor(minY) - padY;
            int rw = Math.Max(4, (int)Math.Ceiling(maxX - minX) + padX * 2);
            int rh = Math.Max(4, (int)Math.Ceiling(maxY - minY) + padY * 2);
            return new Rectangle(rx, ry, rw, rh);
        }

        private void ResetParticle(SeasonParticle p, int w, int h, bool scatterY) {
            if (p == null) return;
            float r1 = (float)_particleRng.NextDouble();
            float r2 = (float)_particleRng.NextDouble();
            float r3 = (float)_particleRng.NextDouble();
            float r4 = (float)_particleRng.NextDouble();
            float r5 = (float)_particleRng.NextDouble();
            float r6 = (float)_particleRng.NextDouble();

            p.X = -12f + r1 * (w + 24f);
            p.Y = scatterY ? (r2 * h) : (-12f - r2 * 26f);
            p.PrevX = p.X;
            p.PrevY = p.Y;
            p.TailX = p.X;
            p.TailY = p.Y;
            p.Rot = r3 * 360f;
            p.SwayPhase = r4 * (float)(Math.PI * 2.0);
            p.SwayFreq = 1.1f + r5 * 1.4f;
            p.Life = 0f;
            p.MaxLife = 3.0f;

            int effAnim = GetEffectiveAnimEffect();
            if ((effAnim >= 1 && effAnim <= 5) || (effAnim >= 7 && effAnim <= 10)) {
                switch (effAnim) {
                    case 1: // Thien thach (Meteor)
                        if (p.Kind == 0) {
                            float spd = 240f + r3 * 125f;
                            float ang = 0.68f + (r4 - 0.5f) * 0.14f; // ~39 deg down-right
                            float ux = (float)Math.Cos(ang);
                            float uy = (float)Math.Sin(ang);
                            p.Vx = ux * spd;
                            p.Vy = uy * spd;
                            float trailLen = 72f + r5 * 48f;
                            p.Size = 4.2f + r6 * 3.0f; // stores meteor radius scale
                            p.SwayAmp = trailLen;
                            p.SwayFreq = 8f + r4 * 6f;
                            p.RotSpeed = 0f;
                            if (scatterY) {
                                p.X = r1 * (w + 60f);
                                p.Y = r2 * (h + 40f);
                                p.Life = r3 * 1.2f;
                            } else if (r6 < 0.72f) {
                                p.X = -60f + r1 * (w * 0.85f);
                                p.Y = -20f - r2 * 70f;
                            } else {
                                p.X = -20f - r1 * 70f;
                                p.Y = r2 * (h * 0.45f);
                            }
                            p.TailX = p.X - ux * trailLen;
                            p.TailY = p.Y - uy * trailLen;
                            p.MaxLife = 4.5f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 195 + _particleRng.Next(55);
                        } else {
                            p.Vx = 40f + r3 * 45f;
                            p.Vy = 32f + r4 * 40f;
                            p.SwayAmp = 14f;
                            p.SwayFreq = 4.2f;
                            p.RotSpeed = 0f;
                            p.Size = 2.6f + r5 * 2.2f;
                            p.X = r1 * w;
                            p.Y = scatterY ? (r2 * h) : (r2 * h * 0.75f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.MaxLife = 1.6f + r6 * 1.4f;
                            p.Life = scatterY ? (r3 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 175 + _particleRng.Next(65);
                        }
                        break;

                    case 2: // Sao bang (Shooting Star)
                        if (p.Kind == 0) {
                            float spd = 310f + r3 * 150f;
                            float ang = 0.48f + (r4 - 0.5f) * 0.14f; // ~27 deg
                            float ux = (float)Math.Cos(ang);
                            float uy = (float)Math.Sin(ang);
                            p.Vx = ux * spd;
                            p.Vy = uy * spd;
                            float trailLen = 82f + r5 * 48f;
                            p.SwayAmp = trailLen;
                            p.Size = 3.2f + r6 * 2.0f;
                            p.RotSpeed = 40f;
                            if (scatterY) {
                                p.X = r1 * (w * 0.9f);
                                p.Y = r2 * (h * 0.75f);
                                p.MaxLife = 1.7f + r5 * 1.0f;
                                p.Life = r3 * p.MaxLife * 0.8f;
                            } else {
                                if (r6 < 0.75f) {
                                    p.X = -40f + r1 * (w * 0.80f);
                                    p.Y = -12f - r2 * 45f;
                                } else {
                                    p.X = -15f - r1 * 50f;
                                    p.Y = r2 * (h * 0.40f);
                                }
                                p.MaxLife = 1.8f + r5 * 1.0f;
                                p.Life = 0f;
                            }
                            p.TailX = p.X - ux * trailLen;
                            p.TailY = p.Y - uy * trailLen;
                            p.ColorVariant = _particleRng.Next(3);
                            p.Alpha = 195 + _particleRng.Next(55);
                        } else {
                            p.Vx = 3f + r3 * 6f;
                            p.Vy = 2f + r4 * 6f;
                            p.SwayAmp = 0f;
                            p.SwayFreq = 2.6f + r5 * 2.2f;
                            p.RotSpeed = -20f + r6 * 40f;
                            p.Size = 3.0f + r3 * 2.4f;
                            p.X = 16f + r1 * Math.Max(60f, w - 32f);
                            p.Y = 16f + r2 * Math.Max(60f, h - 32f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.MaxLife = 2.6f + r5 * 1.8f;
                            p.Life = scatterY ? (r4 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 160 + _particleRng.Next(80);
                        }
                        break;

                    case 3: // Gio (Wind)
                        if (p.Kind == 0) {
                            float trailLen = 88f + r5 * 52f;
                            p.Vx = 145f + r3 * 95f;
                            p.Vy = -14f + r4 * 28f;
                            p.SwayAmp = (r6 < 0.5f ? 1f : -1f) * (7f + r5 * 6f);
                            p.SwayFreq = 2.4f + r4 * 1.6f;
                            p.RotSpeed = trailLen; // repurpose unused RotSpeed for ribbon length cleanly
                            p.Size = 1.5f + r3 * 0.7f;
                            p.X = scatterY ? (r1 * (w + 100f)) : (-16f - r1 * 80f);
                            p.Y = 24f + r2 * Math.Max(60f, h - 48f);
                            p.TailX = p.X - trailLen;
                            p.TailY = p.Y - p.Vy * (trailLen / Math.Max(80f, p.Vx));
                            p.MaxLife = 5.5f;
                            p.Life = scatterY ? (r3 * 2.0f) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 145 + _particleRng.Next(55);
                        } else {
                            float trailLen = 28f + r5 * 24f;
                            p.Vx = 195f + r3 * 105f;
                            p.Vy = -10f + r4 * 20f;
                            p.SwayAmp = 6f + r6 * 5f;
                            p.SwayFreq = 3.2f + r4 * 1.5f;
                            p.RotSpeed = trailLen;
                            p.Size = 1.2f + r3 * 0.6f;
                            p.X = scatterY ? (r1 * (w + 40f)) : (-12f - r1 * 50f);
                            p.Y = 18f + r2 * Math.Max(60f, h - 36f);
                            p.TailX = p.X - trailLen;
                            p.TailY = p.Y - p.Vy * (trailLen / Math.Max(80f, p.Vx));
                            p.MaxLife = 4.0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 135 + _particleRng.Next(60);
                        }
                        break;

                    case 4: // Tia nang (Sunbeams)
                        if (p.Kind == 0) {
                            float ang = 1.08f + (r4 - 0.5f) * 0.08f; // matches ~62 deg shafts from top-left
                            float spd = 48f + r3 * 36f;
                            float ux = (float)Math.Cos(ang);
                            float uy = (float)Math.Sin(ang);
                            p.Vx = ux * spd;
                            p.Vy = uy * spd;
                            float rayLen = 58f + r5 * 42f;
                            p.SwayAmp = rayLen;
                            p.Size = 2.2f + r6 * 1.6f;
                            p.X = r1 * (w * 0.92f);
                            p.Y = scatterY ? (r2 * (h * 0.85f)) : (r2 * (h * 0.35f) - 10f);
                            p.TailX = p.X - ux * rayLen;
                            p.TailY = p.Y - uy * rayLen;
                            p.MaxLife = 2.6f + r5 * 1.6f;
                            p.Life = scatterY ? (r3 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 130 + _particleRng.Next(60);
                        } else {
                            p.Vx = 8f + r3 * 16f;
                            p.Vy = 10f + r4 * 18f;
                            p.SwayAmp = 8f + r5 * 8f;
                            p.SwayFreq = 1.6f + r6 * 1.4f;
                            p.RotSpeed = -22f + r5 * 44f;
                            p.Size = 3.8f + r3 * 4.4f;
                            p.X = 16f + r1 * Math.Max(80f, w - 32f);
                            p.Y = 16f + r2 * Math.Max(80f, h - 32f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.MaxLife = 3.2f + r5 * 2.0f;
                            p.Life = scatterY ? (r4 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(3);
                            p.Alpha = 135 + _particleRng.Next(65);
                        }
                        break;

                    case 5: // Mua (Rain)
                        if (p.Kind == 0) {
                            bool fgLayer = (r6 >= 0.42f);
                            p.ColorVariant = fgLayer ? 1 : 0;
                            float vy = fgLayer ? (470f + r3 * 130f) : (325f + r3 * 90f);
                            float vx = -vy * (0.165f + r4 * 0.03f);
                            float len = fgLayer ? (24f + r5 * 12f) : (15f + r5 * 8f);
                            float invV = 1f / (float)Math.Sqrt(vx * vx + vy * vy);
                            p.Vx = vx;
                            p.Vy = vy;
                            p.SwayAmp = len;
                            p.Size = fgLayer ? 1.45f : 1.0f;
                            if (scatterY) {
                                p.X = -20f + r1 * (w + 90f);
                                p.Y = r2 * h;
                            } else {
                                p.X = -10f + r1 * (w + 130f);
                                p.Y = -12f - r2 * 48f;
                            }
                            p.TailX = p.X - vx * invV * len;
                            p.TailY = p.Y - vy * invV * len;
                            p.Alpha = fgLayer ? (180 + _particleRng.Next(45)) : (135 + _particleRng.Next(45));
                        } else {
                            p.Vx = 0f;
                            p.Vy = 0f;
                            p.SwayAmp = 0f;
                            p.Size = 6f + r3 * 6f;
                            p.X = 24f + r1 * Math.Max(80f, w - 48f);
                            p.Y = 42f + r2 * Math.Max(80f, h - 68f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.MaxLife = 0.48f + r4 * 0.30f;
                            p.Life = scatterY ? (r5 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 165 + _particleRng.Next(50);
                        }
                        break;

                    case 7: // Lua (Fire)
                        if (p.Kind == 0) {
                            p.X = 20f + r1 * Math.Max(80f, w - 40f);
                            p.Y = scatterY ? (h * 0.36f + r2 * (h * 0.66f)) : (h + 6f + r2 * 26f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.Vx = -10f + r4 * 20f;
                            p.Vy = -(52f + r3 * 44f);
                            p.SwayAmp = 12f + r5 * 14f;
                            p.SwayFreq = 3.2f + r6 * 2.2f;
                            p.Size = 6.2f + r3 * 4.4f;
                            p.MaxLife = 1.6f + r5 * 1.2f;
                            p.Life = scatterY ? (r4 * p.MaxLife * 0.75f) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 185 + _particleRng.Next(55);
                        } else {
                            p.X = 16f + r1 * Math.Max(80f, w - 32f);
                            p.Y = scatterY ? (h * 0.12f + r2 * (h * 0.88f)) : (h + 4f + r2 * 22f);
                            p.Vx = -18f + r4 * 36f;
                            p.Vy = -(72f + r3 * 65f);
                            p.TailX = p.X - p.Vx * 0.08f;
                            p.TailY = p.Y - p.Vy * 0.08f;
                            p.SwayAmp = 18f + r5 * 16f;
                            p.SwayFreq = 4.0f + r6 * 2.4f;
                            p.Size = 2.6f + r3 * 2.2f;
                            p.MaxLife = 1.8f + r5 * 1.5f;
                            p.Life = scatterY ? (r3 * p.MaxLife * 0.75f) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 190 + _particleRng.Next(55);
                        }
                        break;

                    case 8: // Sam chop (Lightning)
                        if (p.Kind == 0) {
                            float topX = 48f + r1 * Math.Max(120f, w - 96f);
                            float topY = -8f + r2 * (h * 0.20f);
                            float spanX = -60f + r4 * 120f;
                            float spanY = 140f + r5 * 175f;
                            p.TailX = topX;
                            p.TailY = topY;
                            p.X = topX + spanX;
                            p.Y = topY + spanY;
                            p.Vx = -6f + r3 * 12f;
                            p.Vy = 4f + r6 * 8f;
                            p.SwayAmp = 14f + r5 * 12f;
                            p.Size = 3.2f + r3 * 1.8f;
                            p.MaxLife = 0.75f + r6 * 0.65f;
                            p.Life = scatterY ? (r4 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(3);
                            p.Alpha = 210 + _particleRng.Next(45);
                        } else {
                            p.X = 24f + r1 * Math.Max(80f, w - 48f);
                            p.Y = 24f + r2 * Math.Max(80f, h - 48f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.Vx = -35f + r3 * 70f;
                            p.Vy = 15f + r4 * 45f;
                            p.SwayAmp = 22f;
                            p.SwayFreq = 5.0f;
                            p.RotSpeed = -90f + r5 * 180f;
                            p.Size = 4.2f + r6 * 3.0f;
                            p.MaxLife = 0.85f + r5 * 0.65f;
                            p.Life = scatterY ? (r3 * p.MaxLife) : 0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 185 + _particleRng.Next(60);
                        }
                        break;

                    case 9: // Loc xoay (Tornado)
                        if (p.Kind == 0) {
                            p.X = scatterY ? (60f + r1 * Math.Max(120f, w - 120f)) : (-55f - r1 * 45f);
                            p.Y = h * 0.28f + r2 * (h * 0.56f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.Vx = 42f + r3 * 28f;
                            p.Vy = -6f + r4 * 12f;
                            p.SwayAmp = 14f + r5 * 10f;
                            p.SwayFreq = 1.4f + r6 * 0.8f;
                            p.Size = 78f + r3 * 44f; // funnel height
                            p.MaxLife = 8.0f;
                            p.Alpha = 180 + _particleRng.Next(50);
                        } else {
                            float trailLen = 36f + r5 * 34f;
                            p.Vx = 100f + r3 * 85f;
                            p.Vy = -16f + r4 * 32f;
                            p.SwayAmp = (r6 < 0.5f ? 1f : -1f) * (18f + r5 * 14f);
                            p.SwayFreq = 3.6f + r4 * 1.8f;
                            p.RotSpeed = trailLen;
                            p.Size = 1.4f + r3 * 0.8f;
                            p.X = scatterY ? (r1 * (w + 60f)) : (-16f - r1 * 50f);
                            p.Y = 24f + r2 * Math.Max(80f, h - 48f);
                            p.TailX = p.X - trailLen;
                            p.TailY = p.Y - p.Vy * (trailLen / Math.Max(80f, p.Vx));
                            p.MaxLife = 5.0f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 155 + _particleRng.Next(55);
                        }
                        break;

                    case 10: // Song than (Tsunami)
                        if (p.Kind == 0) {
                            float waveW = 96f + r5 * 58f;
                            p.Vx = 88f + r3 * 64f;
                            p.Vy = -4f + r4 * 8f;
                            p.SwayAmp = waveW;
                            p.Size = 26f + r6 * 16f; // crest height
                            p.X = scatterY ? (r1 * (w + 80f)) : (-18f - r1 * 70f);
                            p.Y = 90f + r2 * Math.Max(120f, h - 125f);
                            p.TailX = p.X - waveW;
                            p.TailY = p.Y;
                            p.SwayFreq = 2.0f + r4 * 1.0f;
                            p.MaxLife = 6.5f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 150 + _particleRng.Next(55);
                        } else {
                            p.Vx = 72f + r3 * 62f;
                            p.Vy = -12f + r4 * 26f;
                            p.SwayAmp = 10f + r5 * 8f;
                            p.SwayFreq = 3.0f + r6 * 1.5f;
                            p.Size = 4.2f + r3 * 3.0f;
                            p.X = scatterY ? (r1 * (w + 30f)) : (-12f - r1 * 40f);
                            p.Y = 30f + r2 * Math.Max(80f, h - 56f);
                            p.TailX = p.X;
                            p.TailY = p.Y;
                            p.MaxLife = 4.5f;
                            p.ColorVariant = _particleRng.Next(2);
                            p.Alpha = 165 + _particleRng.Next(55);
                        }
                        break;
                }
                p.CurRect = ComputeParticleRect(p, effAnim);
                return;
            }

            int seasonMode = GetEffectiveSpriteSeason();
            switch (seasonMode) {
                case 1: // Mua Ha: La xanh, hoa huong duong nho & tia nang vang
                    p.Vx = 8f + r6 * 14f;
                    p.Vy = 18f + r3 * 18f;
                    p.SwayAmp = 10f + r4 * 12f;
                    p.RotSpeed = -40f + r5 * 80f;
                    if (r6 < 0.42f) {
                        p.Kind = 0;
                        p.Size = 5.8f + r3 * 2.8f;
                    } else if (r6 < 0.75f) {
                        p.Kind = 1;
                        p.Size = 6.2f + r3 * 2.2f;
                    } else {
                        p.Kind = 2;
                        p.Size = 5.4f + r3 * 2.4f;
                    }
                    p.ColorVariant = _particleRng.Next(2);
                    p.Alpha = 155 + _particleRng.Next(61);
                    break;

                case 2: // Mua Thu: La phong & la vang roi
                    p.Vx = 14f + r6 * 18f;
                    p.Vy = 26f + r3 * 22f;
                    p.SwayAmp = 18f + r4 * 16f;
                    p.RotSpeed = -60f + r5 * 120f;
                    if (r6 < 0.50f) {
                        p.Kind = 0;
                        p.Size = 6.6f + r3 * 3.0f;
                    } else {
                        p.Kind = 1;
                        p.Size = 6.2f + r3 * 2.8f;
                    }
                    p.ColorVariant = _particleRng.Next(3);
                    p.Alpha = 160 + _particleRng.Next(61);
                    break;

                case 3: // Mua Dong: Bong tuyet & tuyet roi
                    p.Vx = -10f + r6 * 24f;
                    p.Vy = 24f + r3 * 24f;
                    p.SwayAmp = 8f + r4 * 10f;
                    p.RotSpeed = -25f + r5 * 50f;
                    if (r6 < 0.58f) {
                        p.Kind = 0;
                        p.Size = 5.8f + r3 * 4.4f;
                    } else {
                        p.Kind = 1;
                        p.Size = 4.4f + r3 * 2.8f;
                    }
                    p.ColorVariant = _particleRng.Next(2);
                    p.Alpha = 165 + _particleRng.Next(61);
                    break;

                case 4: // Hoa Huong Duong roi: Bong huong duong, canh vang, la xanh
                    p.Vx = 9f + r6 * 15f;
                    p.Vy = 20f + r3 * 18f;
                    p.SwayAmp = 12f + r4 * 14f;
                    p.RotSpeed = -42f + r5 * 84f;
                    if (r6 < 0.36f) {
                        p.Kind = 0; // Hoa huong duong
                        p.Size = 6.4f + r3 * 2.6f;
                    } else if (r6 < 0.80f) {
                        p.Kind = 1; // Canh hoa vang
                        p.Size = 5.8f + r3 * 2.8f;
                    } else {
                        p.Kind = 2; // La xanh
                        p.Size = 5.4f + r3 * 2.2f;
                    }
                    p.ColorVariant = _particleRng.Next(2);
                    p.Alpha = 160 + _particleRng.Next(61);
                    break;

                default: // Mua Xuan: Canh hoa & bong hoa anh dao roi
                    p.Vx = 10f + r6 * 14f;
                    p.Vy = 22f + r3 * 20f;
                    p.SwayAmp = 14f + r4 * 14f;
                    p.RotSpeed = -45f + r5 * 90f;
                    if (r6 < 0.82f) {
                        p.Kind = 0;
                        p.Size = 5.8f + r3 * 3.8f;
                    } else {
                        p.Kind = 1;
                        p.Size = 6.2f + r3 * 2.0f;
                    }
                    p.ColorVariant = _particleRng.Next(2);
                    p.Alpha = 155 + _particleRng.Next(61);
                    break;
            }
            p.CurRect = ComputeParticleRect(p, effAnim);
        }

        private static int GetParticleSpriteIndex(int season, int kind, int colorVariant) {
            if (season == 2) {
                return Math.Max(0, Math.Min(5, kind * 3 + (colorVariant % 3)));
            }
            if (season == 4) {
                if (kind == 0) return _clamp3(colorVariant);
                if (kind == 1) return 3 + (colorVariant & 1);
                return 5;
            }
            return Math.Max(0, Math.Min(5, kind * 2 + (colorVariant & 1)));
        }

        private static int _clamp3(int v) {
            int m = v % 3;
            return (m < 0) ? 0 : m;
        }

        private void DrawSeasonParticle(Graphics g, SeasonParticle p, float x, float y, bool lightBg) {
            EnsureParticleSprites();
            Bitmap[] bank = lightBg ? _particleSpritesLight : _particleSpritesDark;
            if (bank == null) return;
            int effSeason = GetEffectiveSpriteSeason();
            int idx = GetParticleSpriteIndex(effSeason, p.Kind, p.ColorVariant);
            Bitmap sp = bank[idx];
            if (sp == null) return;

            float drawSz = Math.Max(10f, Math.Min(26f, p.Size * 2.5f));
            float half = drawSz * 0.5f;
            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(x, y);
                g.RotateTransform(p.Rot);
                g.DrawImage(sp, -half, -half, drawSz, drawSz);
            } finally {
                g.Restore(gs);
            }
        }

        private void DrawSunbeamsBackdrop(Graphics g, Point origin, bool lightBg) {
            float fw = (_form != null && !_form.IsDisposed) ? Math.Max(640f, _form.ClientSize.Width) : 1102f;
            float fh = (_form != null && !_form.IsDisposed) ? Math.Max(420f, _form.ClientSize.Height) : 658f;
            float ox = origin.X;
            float oy = origin.Y;

            // Soft solar glow in upper-left form coordinates (static alpha -> zero dirty-rect seams)
            float gx = -ox;
            float gy = -oy;
            RectangleF haloR = new RectangleF(gx - 150f, gy - 110f, 340f, 240f);
            using (SolidBrush haloBr = new SolidBrush(Color.FromArgb(lightBg ? 26 : 34, 253, 224, 71))) {
                g.FillEllipse(haloBr, haloR);
            }

            float[] topXs = new float[] { -80f, fw * 0.08f, fw * 0.28f, fw * 0.50f, fw * 0.72f };
            float[] halfWs = new float[] { 46f, 64f, 52f, 70f, 48f };
            int[] midAlphas = lightBg ? new int[] { 34, 40, 32, 36, 28 } : new int[] { 38, 44, 34, 38, 30 };
            Color beamCol = lightBg ? Color.FromArgb(250, 204, 21) : Color.FromArgb(254, 240, 138);

            float dxShift = fh * 0.48f;
            for (int i = 0; i < topXs.Length; i++) {
                float xTop = topXs[i] - ox;
                float xBot = xTop + dxShift;
                float yTop = -20f - oy;
                float yBot = fh + 20f - oy;
                float hwTop = halfWs[i];
                float hwBot = hwTop * 1.45f;

                PointF p1 = new PointF(xTop - hwTop, yTop);
                PointF p2 = new PointF(xTop + hwTop, yTop);
                PointF p3 = new PointF(xBot + hwBot, yBot);
                PointF p4 = new PointF(xBot - hwBot, yBot);

                float midX = (xTop + xBot) * 0.5f;
                float midY = (yTop + yBot) * 0.5f;
                float perpSpan = (hwTop + hwBot) * 0.55f;
                PointF gL = new PointF(midX - perpSpan, midY + perpSpan * 0.45f);
                PointF gR = new PointF(midX + perpSpan, midY - perpSpan * 0.45f);

                if (Math.Abs(gR.X - gL.X) < 4f && Math.Abs(gR.Y - gL.Y) < 4f) continue;

                using (LinearGradientBrush gb = new LinearGradientBrush(gL, gR, Color.FromArgb(0, beamCol), Color.FromArgb(0, beamCol))) {
                    ColorBlend cb = new ColorBlend(3);
                    cb.Positions = new float[] { 0f, 0.5f, 1f };
                    cb.Colors = new Color[] {
                        Color.FromArgb(0, beamCol),
                        Color.FromArgb(midAlphas[i], beamCol),
                        Color.FromArgb(0, beamCol)
                    };
                    gb.InterpolationColors = cb;
                    g.FillPolygon(gb, new PointF[] { p1, p2, p3, p4 });
                }
            }
        }

        private static void DrawEffectParticle(Graphics g, SeasonParticle p, int effect, float ox, float oy, bool lightBg, float phaseSec) {
            float hx = p.X - ox;
            float hy = p.Y - oy;
            float tx = p.TailX - ox;
            float ty = p.TailY - oy;
            float dx = hx - tx;
            float dy = hy - ty;
            float len = (float)Math.Sqrt(dx * dx + dy * dy);
            SmoothingMode oldSm = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            try {
                switch (effect) {
                    case 1: { // Thien thach (Meteor)
                        if (p.Kind == 0) {
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * Math.Min(1f, p.Life / 0.22f))));
                            if (a <= 4) break;
                            Color flameOuter = lightBg ? Color.FromArgb(a, 234, 88, 12) : Color.FromArgb(a, 249, 115, 22);
                            Color flameCore  = lightBg ? Color.FromArgb(a, 250, 204, 21) : Color.FromArgb(a, 254, 249, 195);
                            if (len >= 4f) {
                                using (LinearGradientBrush ob = new LinearGradientBrush(new PointF(tx, ty), new PointF(hx, hy), Color.FromArgb(0, flameOuter), Color.FromArgb((int)(a * 0.85f), flameOuter)))
                                using (Pen op = new Pen(ob, Math.Max(3.2f, p.Size * 1.65f))) {
                                    op.StartCap = LineCap.Round;
                                    op.EndCap = LineCap.Round;
                                    g.DrawLine(op, tx, ty, hx, hy);
                                }
                                float cx0 = tx + dx * 0.30f;
                                float cy0 = ty + dy * 0.30f;
                                if ((float)Math.Sqrt((hx - cx0) * (hx - cx0) + (hy - cy0) * (hy - cy0)) >= 2.5f) {
                                    using (LinearGradientBrush ib = new LinearGradientBrush(new PointF(cx0, cy0), new PointF(hx, hy), Color.FromArgb(0, flameCore), flameCore))
                                    using (Pen ip = new Pen(ib, Math.Max(1.6f, p.Size * 0.72f))) {
                                        ip.StartCap = LineCap.Round;
                                        ip.EndCap = LineCap.Round;
                                        g.DrawLine(ip, cx0, cy0, hx, hy);
                                    }
                                }
                                // Ember sparks along wake
                                using (SolidBrush spkBr = new SolidBrush(Color.FromArgb((int)(a * 0.82f), flameCore))) {
                                    for (int k = 1; k <= 3; k++) {
                                        float frac = 0.25f * k;
                                        float jitter = (float)Math.Sin(p.SwayPhase + k * 2.1f + p.Life * 6f) * (p.Size * 0.9f);
                                        float nx = (len > 1f) ? (-dy / len) : 0f;
                                        float ny = (len > 1f) ? (dx / len) : 1f;
                                        float sx = hx - dx * frac + nx * jitter;
                                        float sy = hy - dy * frac + ny * jitter;
                                        float sd = Math.Max(1.5f, p.Size * (0.45f - k * 0.08f));
                                        g.FillEllipse(spkBr, sx - sd * 0.5f, sy - sd * 0.5f, sd, sd);
                                    }
                                }
                            }
                            float r = Math.Max(3.2f, p.Size * 0.90f);
                            using (SolidBrush halo = new SolidBrush(Color.FromArgb((int)(a * 0.38f), 249, 115, 22))) {
                                g.FillEllipse(halo, hx - r * 1.85f, hy - r * 1.85f, r * 3.7f, r * 3.7f);
                            }
                            Color rockDark = lightBg ? Color.FromArgb(a, 124, 45, 18) : Color.FromArgb(a, 154, 52, 18);
                            using (SolidBrush rock = new SolidBrush(rockDark))
                            using (Pen hotRim = new Pen(Color.FromArgb(a, 253, 224, 71), Math.Max(1.0f, r * 0.28f))) {
                                g.FillEllipse(rock, hx - r, hy - r, r * 2f, r * 2f);
                                g.DrawEllipse(hotRim, hx - r, hy - r, r * 2f, r * 2f);
                            }
                            using (SolidBrush core = new SolidBrush(Color.FromArgb(a, 254, 249, 195))) {
                                g.FillEllipse(core, hx - r * 0.42f, hy - r * 0.42f, r * 0.84f, r * 0.84f);
                            }
                        } else {
                            float tLife = Math.Max(0f, Math.Min(1f, p.Life / Math.Max(0.2f, p.MaxLife)));
                            float env = (float)Math.Sin(tLife * Math.PI);
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * env)));
                            if (a <= 4) break;
                            Color c = (p.ColorVariant == 0)
                                ? (lightBg ? Color.FromArgb(a, 234, 88, 12) : Color.FromArgb(a, 253, 224, 71))
                                : (lightBg ? Color.FromArgb(a, 217, 119, 6) : Color.FromArgb(a, 251, 146, 60));
                            using (SolidBrush br = new SolidBrush(c)) {
                                float r = p.Size * 0.7f;
                                g.FillEllipse(br, hx - r, hy - r, r * 2f, r * 2f);
                            }
                        }
                        break;
                    }

                    case 2: { // Sao bang (Shooting Star)
                        float tLife = Math.Max(0f, Math.Min(1f, p.Life / Math.Max(0.2f, p.MaxLife)));
                        float env = (tLife < 0.18f) ? (tLife / 0.18f) : ((tLife > 0.72f) ? ((1f - tLife) / 0.28f) : 1f);
                        if (p.Kind == 0) {
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * Math.Max(0f, env))));
                            if (a <= 4) break;
                            Color cTail = lightBg
                                ? ((p.ColorVariant == 2) ? Color.FromArgb(0, 217, 119, 6) : Color.FromArgb(0, 14, 165, 233))
                                : ((p.ColorVariant == 2) ? Color.FromArgb(0, 253, 224, 71) : Color.FromArgb(0, 56, 189, 248));
                            Color cMid = lightBg
                                ? ((p.ColorVariant == 2) ? Color.FromArgb((int)(a * 0.72f), 234, 158, 12) : Color.FromArgb((int)(a * 0.75f), 2, 132, 199))
                                : ((p.ColorVariant == 2) ? Color.FromArgb((int)(a * 0.72f), 253, 224, 71) : Color.FromArgb((int)(a * 0.75f), 125, 211, 252));
                            Color cHead = lightBg
                                ? Color.FromArgb(a, 37, 99, 235)
                                : Color.FromArgb(a, 255, 255, 255);
                            if (len >= 4f) {
                                using (LinearGradientBrush outerGb = new LinearGradientBrush(new PointF(tx, ty), new PointF(hx, hy), cTail, Color.FromArgb((int)(a * 0.85f), cMid))) {
                                    ColorBlend cb = new ColorBlend(3);
                                    cb.Positions = new float[] { 0f, 0.55f, 1f };
                                    cb.Colors = new Color[] { cTail, cMid, cHead };
                                    outerGb.InterpolationColors = cb;
                                    using (Pen op = new Pen(outerGb, Math.Max(2.2f, p.Size * 0.95f))) {
                                        op.StartCap = LineCap.Round;
                                        op.EndCap = LineCap.Round;
                                        g.DrawLine(op, tx, ty, hx, hy);
                                    }
                                }
                                float cx0 = tx + dx * 0.45f;
                                float cy0 = ty + dy * 0.45f;
                                if ((float)Math.Sqrt((hx - cx0) * (hx - cx0) + (hy - cy0) * (hy - cy0)) >= 2.5f) {
                                    Color coreHead = lightBg ? Color.FromArgb(a, 224, 242, 254) : Color.FromArgb(a, 255, 255, 255);
                                    using (LinearGradientBrush coreGb = new LinearGradientBrush(new PointF(cx0, cy0), new PointF(hx, hy), Color.FromArgb(0, coreHead), coreHead))
                                    using (Pen cp = new Pen(coreGb, Math.Max(1.0f, p.Size * 0.36f))) {
                                        cp.StartCap = LineCap.Round;
                                        cp.EndCap = LineCap.Round;
                                        g.DrawLine(cp, cx0, cy0, hx, hy);
                                    }
                                }
                            }
                            Color starCol = lightBg ? Color.FromArgb(14, 165, 233) : Color.FromArgb(254, 249, 195);
                            DrawFourPointStar(g, hx, hy, Math.Max(4.2f, p.Size * 1.45f), starCol, a, lightBg);
                        } else {
                            float tw = 0.45f + 0.55f * (float)(0.5 + 0.5 * Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase));
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * tw * Math.Max(0.25f, (float)Math.Sin(tLife * Math.PI)))));
                            if (a <= 4) break;
                            Color sc = (p.ColorVariant == 0)
                                ? (lightBg ? Color.FromArgb(14, 165, 233) : Color.FromArgb(186, 230, 253))
                                : (lightBg ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138));
                            DrawFourPointStar(g, hx, hy, p.Size * (0.75f + tw * 0.45f), sc, a, lightBg);
                        }
                        break;
                    }

                    case 3: { // Gio (Wind)
                        int a = Math.Max(0, Math.Min(255, p.Alpha));
                        if (a <= 4 || len < 4f) break;
                        Color wCol = (p.ColorVariant == 0)
                            ? (lightBg ? Color.FromArgb(14, 165, 233) : Color.FromArgb(224, 242, 254))
                            : (lightBg ? Color.FromArgb(100, 116, 139) : Color.FromArgb(125, 211, 252));
                        float amp = p.SwayAmp * (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase);
                        PointF p0 = new PointF(tx, ty);
                        PointF p1 = new PointF(tx + dx * 0.35f, ty + dy * 0.35f - amp);
                        PointF p2 = new PointF(tx + dx * 0.72f, ty + dy * 0.72f + amp * 0.85f);
                        PointF p3 = new PointF(hx, hy);
                        using (LinearGradientBrush wg = new LinearGradientBrush(p0, p3, Color.FromArgb(0, wCol), Color.FromArgb(0, wCol))) {
                            ColorBlend cb = new ColorBlend(4);
                            cb.Positions = new float[] { 0f, 0.35f, 0.78f, 1f };
                            cb.Colors = new Color[] {
                                Color.FromArgb(0, wCol),
                                Color.FromArgb((int)(a * 0.72f), wCol),
                                Color.FromArgb(a, wCol),
                                Color.FromArgb((int)(a * 0.25f), wCol)
                            };
                            wg.InterpolationColors = cb;
                            using (Pen wp = new Pen(wg, p.Size)) {
                                wp.StartCap = LineCap.Round;
                                wp.EndCap = LineCap.Round;
                                g.DrawBezier(wp, p0, p1, p2, p3);
                            }
                        }
                        if (p.Kind == 0) {
                            float curlD = Math.Max(7f, Math.Abs(p.SwayAmp) * 1.05f);
                            float dirY = (p.SwayAmp >= 0f) ? -1f : 1f;
                            RectangleF curlR = new RectangleF(hx - curlD * 0.85f, (dirY < 0f) ? (hy - curlD) : hy, curlD, curlD);
                            using (Pen cp = new Pen(Color.FromArgb((int)(a * 0.72f), wCol), Math.Max(1.0f, p.Size * 0.82f))) {
                                cp.StartCap = LineCap.Round;
                                cp.EndCap = LineCap.Round;
                                g.DrawArc(cp, curlR, (dirY < 0f) ? 85f : 275f, (dirY < 0f) ? -235f : 235f);
                            }
                        }
                        break;
                    }

                    case 4: { // Tia nang (Sunbeams: animated diagonal light rays + bokeh motes)
                        float tLife = Math.Max(0f, Math.Min(1f, p.Life / Math.Max(0.2f, p.MaxLife)));
                        float env = (float)Math.Sin(tLife * Math.PI);
                        int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * Math.Max(0f, env))));
                        if (a <= 4) break;
                        if (p.Kind == 0) {
                            if (len < 4f) break;
                            Color cBeam = (p.ColorVariant == 0)
                                ? (lightBg ? Color.FromArgb(245, 158, 11) : Color.FromArgb(253, 224, 71))
                                : (lightBg ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 249, 195));
                            using (LinearGradientBrush rg = new LinearGradientBrush(new PointF(tx, ty), new PointF(hx, hy), Color.FromArgb(0, cBeam), Color.FromArgb(0, cBeam))) {
                                ColorBlend cb = new ColorBlend(3);
                                cb.Positions = new float[] { 0f, 0.5f, 1f };
                                cb.Colors = new Color[] {
                                    Color.FromArgb(0, cBeam),
                                    Color.FromArgb(a, cBeam),
                                    Color.FromArgb(0, cBeam)
                                };
                                rg.InterpolationColors = cb;
                                using (Pen rp = new Pen(rg, p.Size)) {
                                    rp.StartCap = LineCap.Round;
                                    rp.EndCap = LineCap.Round;
                                    g.DrawLine(rp, tx, ty, hx, hy);
                                }
                            }
                        } else {
                            float r = p.Size * (0.82f + 0.28f * env);
                            Color bCol = lightBg ? Color.FromArgb(234, 158, 12) : Color.FromArgb(254, 240, 138);
                            using (SolidBrush outer = new SolidBrush(Color.FromArgb((int)(a * 0.34f), bCol))) {
                                g.FillEllipse(outer, hx - r * 1.4f, hy - r * 1.4f, r * 2.8f, r * 2.8f);
                            }
                            using (SolidBrush inner = new SolidBrush(Color.FromArgb((int)(a * 0.70f), lightBg ? Color.FromArgb(250, 204, 21) : Color.FromArgb(254, 249, 195)))) {
                                g.FillEllipse(inner, hx - r * 0.58f, hy - r * 0.58f, r * 1.16f, r * 1.16f);
                            }
                            if (p.ColorVariant == 2 && env > 0.45f) {
                                DrawFourPointStar(g, hx, hy, Math.Max(2.8f, r * 0.72f), bCol, (int)(a * 0.90f), lightBg);
                            }
                        }
                        break;
                    }

                    case 5: { // Mua (Rain)
                        if (p.Kind == 0) {
                            if (len < 3f) break;
                            int a = Math.Max(0, Math.Min(255, p.Alpha));
                            Color rTail = lightBg ? Color.FromArgb(0, 56, 189, 248) : Color.FromArgb(0, 125, 211, 252);
                            Color rHead = lightBg ? Color.FromArgb(a, 2, 132, 199) : Color.FromArgb(a, 224, 242, 254);
                            using (LinearGradientBrush rb = new LinearGradientBrush(new PointF(tx, ty), new PointF(hx, hy), rTail, rHead))
                            using (Pen rp = new Pen(rb, p.Size)) {
                                rp.StartCap = LineCap.Round;
                                rp.EndCap = LineCap.Round;
                                g.DrawLine(rp, tx, ty, hx, hy);
                            }
                        } else {
                            float prog = Math.Max(0f, Math.Min(1f, p.Life / Math.Max(0.15f, p.MaxLife)));
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * (1f - prog))));
                            if (a <= 4) break;
                            float rx = 2.5f + prog * (p.Size * 1.45f);
                            float ry = Math.Max(1.2f, rx * 0.34f);
                            Color ringCol = lightBg ? Color.FromArgb(a, 14, 165, 233) : Color.FromArgb(a, 186, 230, 253);
                            using (Pen ringPen = new Pen(ringCol, 1.15f)) {
                                g.DrawEllipse(ringPen, hx - rx, hy - ry, rx * 2f, ry * 2f);
                            }
                            if (prog < 0.55f) {
                                float up = (float)Math.Sin((prog / 0.55f) * Math.PI) * 5.5f;
                                float sp = 2.0f + prog * 9.0f;
                                using (SolidBrush db = new SolidBrush(Color.FromArgb(a, lightBg ? 2 : 224, lightBg ? 132 : 242, lightBg ? 199 : 254))) {
                                    g.FillEllipse(db, hx - sp - 1.2f, hy - up - 1.2f, 2.4f, 2.4f);
                                    g.FillEllipse(db, hx + sp - 1.2f, hy - up * 0.85f - 1.2f, 2.4f, 2.4f);
                                }
                            }
                        }
                        break;
                    }

                    case 7: { // Lua (Fire - ngọn lửa & tàn tro bay lên)
                        float tLife = p.Life / Math.Max(0.25f, p.MaxLife);
                        float fade = (tLife < 0.14f) ? (tLife / 0.14f) : ((tLife > 0.68f) ? Math.Max(0f, (1f - tLife) / 0.32f) : 1f);
                        float flicker = 0.86f + 0.14f * (float)Math.Sin(phaseSec * 11f + p.SwayPhase);
                        int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * fade * flicker)));
                        if (a <= 6) break;

                        if (p.Kind == 0) {
                            float swayTilt = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * 14f;
                            float flameSz = Math.Min(11.5f, p.Size * (0.92f + 0.12f * flicker));
                            using (SolidBrush haloBr = new SolidBrush(Color.FromArgb(Math.Max(10, a / 5), lightBg ? 234 : 251, lightBg ? 88 : 146, lightBg ? 12 : 60))) {
                                g.FillEllipse(haloBr, hx - flameSz * 1.15f, hy - flameSz * 1.15f, flameSz * 2.3f, flameSz * 2.3f);
                            }
                            DrawFireFlame(g, hx, hy, flameSz, swayTilt, a, lightBg);
                        } else {
                            float dxT = hx - tx;
                            float dyT = hy - ty;
                            if (dxT * dxT + dyT * dyT >= 6.25f) {
                                Color tailStart = Color.FromArgb(0, lightBg ? 234 : 249, lightBg ? 88 : 115, lightBg ? 12 : 22);
                                Color tailEnd = Color.FromArgb((int)(a * 0.65f), lightBg ? 220 : 251, lightBg ? 38 : 191, lightBg ? 38 : 36);
                                using (LinearGradientBrush tBr = new LinearGradientBrush(new PointF(tx, ty), new PointF(hx, hy), tailStart, tailEnd))
                                using (Pen tPen = new Pen(tBr, Math.Max(1.1f, p.Size * 0.55f))) {
                                    tPen.StartCap = LineCap.Round;
                                    tPen.EndCap = LineCap.Round;
                                    g.DrawLine(tPen, tx, ty, hx, hy);
                                }
                            }
                            DrawFireEmber(g, hx, hy, p.Size, p.Rot, a, lightBg);
                        }
                        break;
                    }

                    case 8: { // Sam chop (Lightning - tia sét ziczac & tia điện)
                        float tLife = p.Life / Math.Max(0.25f, p.MaxLife);
                        if (p.Kind == 0) {
                            // Double-flicker visible bolt pulse only in first 55% of life
                            bool pulseOn = (tLife < 0.14f) || (tLife > 0.20f && tLife < 0.44f);
                            if (!pulseOn) break;
                            float pulseAmp = (tLife < 0.14f) ? 1f : (0.72f + 0.28f * (float)Math.Sin((tLife - 0.20f) * 32f));
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * pulseAmp)));
                            if (a <= 10) break;

                            float minBoundX = Math.Min(tx, hx) - 42f;
                            float maxBoundX = Math.Max(tx, hx) + 42f;
                            float minBoundY = Math.Min(ty, hy) - 14f;
                            float maxBoundY = Math.Max(ty, hy) + 18f;

                            const int segs = 7;
                            PointF[] pts = new PointF[segs + 1];
                            pts[0] = new PointF(tx, ty);
                            pts[segs] = new PointF(hx, hy);
                            for (int k = 1; k < segs; k++) {
                                float frac = (float)k / segs;
                                float jSeed = (float)Math.Sin(p.SwayPhase * 3.7f + k * 2.35f + p.ColorVariant * 1.9f);
                                float jAmp = Math.Min(28f, p.SwayAmp * 1.4f) * (1f - Math.Abs(frac - 0.5f) * 0.55f);
                                float px = tx + (hx - tx) * frac + jSeed * jAmp;
                                float py = ty + (hy - ty) * frac;
                                pts[k] = new PointF(
                                    Math.Max(minBoundX, Math.Min(maxBoundX, px)),
                                    Math.Max(minBoundY, Math.Min(maxBoundY, py))
                                );
                            }

                            Color glowCol = lightBg ? Color.FromArgb((int)(a * 0.28f), 79, 70, 229) : Color.FromArgb((int)(a * 0.36f), 56, 189, 248);
                            Color arcCol = lightBg ? Color.FromArgb((int)(a * 0.80f), 67, 56, 202) : Color.FromArgb((int)(a * 0.82f), 125, 211, 252);
                            Color coreCol = lightBg ? Color.FromArgb(a, 14, 165, 233) : Color.FromArgb(a, 248, 250, 252);

                            using (Pen glowPen = new Pen(glowCol, Math.Max(3.6f, p.Size * 2.5f)))
                            using (Pen arcPen = new Pen(arcCol, Math.Max(1.8f, p.Size * 1.05f)))
                            using (Pen corePen = new Pen(coreCol, Math.Max(1.1f, p.Size * 0.45f))) {
                                glowPen.LineJoin = LineJoin.Bevel;
                                arcPen.LineJoin = LineJoin.Bevel;
                                corePen.LineJoin = LineJoin.Bevel;
                                g.DrawLines(glowPen, pts);
                                g.DrawLines(arcPen, pts);
                                g.DrawLines(corePen, pts);

                                // 1-2 forked side branches clamped strictly inside bolt pad
                                for (int bIdx = 0; bIdx < 2; bIdx++) {
                                    if (bIdx == 1 && (p.ColorVariant % 2 != 0)) continue;
                                    int rootIdx = (bIdx == 0) ? 2 : 4;
                                    PointF rp = pts[rootIdx];
                                    float dir = ((rootIdx + p.ColorVariant + bIdx) % 2 == 0) ? 1f : -1f;
                                    float m1x = Math.Max(minBoundX, Math.Min(maxBoundX, rp.X + dir * (16f + bIdx * 4f)));
                                    float m1y = Math.Max(minBoundY, Math.Min(maxBoundY, rp.Y + 20f));
                                    float e1x = Math.Max(minBoundX, Math.Min(maxBoundX, m1x + dir * 18f));
                                    float e1y = Math.Max(minBoundY, Math.Min(maxBoundY, m1y + 24f));
                                    PointF[] bPts = new PointF[] { rp, new PointF(m1x, m1y), new PointF(e1x, e1y) };
                                    using (Pen fGlow = new Pen(Color.FromArgb((int)(a * 0.22f), glowCol.R, glowCol.G, glowCol.B), Math.Max(2.4f, p.Size * 1.4f)))
                                    using (Pen fCore = new Pen(arcCol, Math.Max(1.0f, p.Size * 0.55f))) {
                                        g.DrawLines(fGlow, bPts);
                                        g.DrawLines(fCore, bPts);
                                    }
                                }
                            }
                            using (SolidBrush flashBr = new SolidBrush(Color.FromArgb(Math.Max(12, a / 5), lightBg ? 99 : 186, lightBg ? 102 : 230, lightBg ? 241 : 253))) {
                                g.FillEllipse(flashBr, tx - 14f, ty - 14f, 28f, 28f);
                                g.FillEllipse(flashBr, hx - 12f, hy - 12f, 24f, 24f);
                            }
                        } else {
                            float fade = (tLife < 0.18f) ? (tLife / 0.18f) : Math.Max(0f, (1f - tLife) / 0.82f);
                            float pulse = 0.68f + 0.32f * (float)Math.Sin(phaseSec * 18f + p.SwayPhase);
                            int a = Math.Max(0, Math.Min(255, (int)(p.Alpha * fade * pulse)));
                            if (a <= 8) break;
                            DrawLightningSpark(g, hx, hy, p.Size, p.Rot, a, lightBg);
                        }
                        break;
                    }

                    case 9: { // Loc xoay (Tornado - phễu xoáy & gió cuốn rác/bụi)
                        if (p.Kind == 0) {
                            float swirlPhase = phaseSec * p.SwayFreq + p.SwayPhase;
                            int a = Math.Max(0, Math.Min(255, p.Alpha));
                            if (a <= 8) break;
                            DrawTornadoFunnel(g, hx, hy, p.Size, swirlPhase, a, lightBg);
                            // Base dust cloud ring (strictly inside [-54..+54] x [-12..+14] of tip)
                            using (SolidBrush dustBr = new SolidBrush(Color.FromArgb((int)(a * 0.22f), lightBg ? 100 : 203, lightBg ? 116 : 213, lightBg ? 139 : 225))) {
                                g.FillEllipse(dustBr, hx - 24f, hy - 5f, 48f, 12f);
                            }
                            // Orbiting debris specks inside funnel bounds
                            for (int d = 0; d < 3; d++) {
                                float ang = swirlPhase * 2.2f + d * 2.1f;
                                float hFrac = 0.28f + d * 0.26f;
                                float orbitR = 14f + hFrac * 26f;
                                float debX = hx + (float)Math.Cos(ang) * orbitR;
                                float debY = hy - p.Size * hFrac + (float)Math.Sin(ang) * 4.5f;
                                DrawWindSwirlSpeck(g, debX, debY, 3.6f + d * 0.6f, ang * 57.3f, (int)(a * 0.82f), lightBg);
                            }
                        } else {
                            float dxT = hx - tx;
                            float dyT = hy - ty;
                            if (dxT * dxT + dyT * dyT >= 9f) {
                                float waveCtrl = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp * 0.55f;
                                float mx = (tx + hx) * 0.5f;
                                float my = (ty + hy) * 0.5f;
                                PointF p0 = new PointF(tx, ty);
                                PointF p1 = new PointF(tx + dxT * 0.35f, ty + dyT * 0.35f + waveCtrl);
                                PointF p2 = new PointF(tx + dxT * 0.70f, ty + dyT * 0.70f - waveCtrl * 0.85f);
                                PointF p3 = new PointF(hx, hy);
                                Color tailStart = Color.FromArgb(0, lightBg ? 71 : 148, lightBg ? 85 : 163, lightBg ? 105 : 184);
                                Color tailEnd = Color.FromArgb((int)(p.Alpha * 0.72f), lightBg ? 51 : 226, lightBg ? 65 : 232, lightBg ? 85 : 240);
                                using (LinearGradientBrush wBr = new LinearGradientBrush(p0, p3, tailStart, tailEnd))
                                using (Pen wPen = new Pen(wBr, Math.Max(1.2f, p.Size))) {
                                    wPen.StartCap = LineCap.Round;
                                    wPen.EndCap = LineCap.Round;
                                    g.DrawBezier(wPen, p0, p1, p2, p3);
                                }
                                DrawWindSwirlSpeck(g, mx, my, p.Size * 2.1f, p.Rot, (int)(p.Alpha * 0.75f), lightBg);
                            }
                        }
                        break;
                    }

                    case 10: { // Song than (Tsunami - ngọn sóng bạc đầu & bọt biển)
                        if (p.Kind == 0) {
                            int a = Math.Max(0, Math.Min(255, p.Alpha));
                            if (a <= 8) break;
                            float waveW = Math.Max(48f, hx - tx);
                            float crestH = Math.Max(22f, p.Size);
                            float surgeBob = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * 3.5f;
                            float topY = hy - crestH + surgeBob;
                            float baseY = hy + 8f;

                            using (GraphicsPath wavePath = new GraphicsPath()) {
                                wavePath.AddBezier(
                                    new PointF(tx - 6f, baseY),
                                    new PointF(tx + waveW * 0.36f, hy - crestH * 0.28f),
                                    new PointF(tx + waveW * 0.76f, topY - 4f),
                                    new PointF(hx + 10f, topY + crestH * 0.16f)
                                );
                                wavePath.AddBezier(
                                    new PointF(hx + 10f, topY + crestH * 0.16f),
                                    new PointF(hx - 6f, topY + crestH * 0.34f),
                                    new PointF(hx - 10f, hy - crestH * 0.18f),
                                    new PointF(hx + 2f, baseY)
                                );
                                wavePath.CloseFigure();

                                int bodyTopA = Math.Max(48, Math.Min(82, (int)(a * 0.38f)));
                                int bodyBotA = Math.Max(32, Math.Min(64, (int)(a * 0.26f)));
                                Color topCol = lightBg ? Color.FromArgb(bodyTopA, 2, 132, 199) : Color.FromArgb(bodyTopA, 56, 189, 248);
                                Color botCol = lightBg ? Color.FromArgb(bodyBotA, 3, 105, 161) : Color.FromArgb(bodyBotA, 14, 116, 144);
                                using (LinearGradientBrush wBr = new LinearGradientBrush(new PointF(hx, topY - 4f), new PointF(hx, baseY), topCol, botCol)) {
                                    g.FillPath(wBr, wavePath);
                                }
                            }

                            Color rimCol = lightBg ? Color.FromArgb((int)(a * 0.72f), 3, 105, 161) : Color.FromArgb((int)(a * 0.78f), 125, 211, 252);
                            Color foamCol = lightBg ? Color.FromArgb((int)(a * 0.85f), 224, 242, 254) : Color.FromArgb((int)(a * 0.88f), 240, 249, 255);
                            using (Pen rimPen = new Pen(rimCol, 2.2f))
                            using (Pen foamPen = new Pen(foamCol, 2.6f)) {
                                rimPen.StartCap = LineCap.Round;
                                rimPen.EndCap = LineCap.Round;
                                foamPen.StartCap = LineCap.Round;
                                foamPen.EndCap = LineCap.Round;
                                g.DrawBezier(rimPen,
                                    new PointF(tx + waveW * 0.25f, hy - crestH * 0.12f),
                                    new PointF(tx + waveW * 0.62f, topY - 3f),
                                    new PointF(hx + 4f, topY + 2f),
                                    new PointF(hx + 10f, topY + crestH * 0.18f));
                                g.DrawBezier(foamPen,
                                    new PointF(tx + waveW * 0.66f, topY + 1f),
                                    new PointF(hx - 2f, topY - 1f),
                                    new PointF(hx + 11f, topY + crestH * 0.14f),
                                    new PointF(hx - 3f, topY + crestH * 0.34f));
                            }

                            using (SolidBrush spBr = new SolidBrush(foamCol)) {
                                g.FillEllipse(spBr, hx + 6f, topY - 3f, 4.2f, 4.2f);
                                g.FillEllipse(spBr, hx + 12f, topY + 3f, 3.2f, 3.2f);
                                g.FillEllipse(spBr, hx + 1f, topY - 5f, 3.0f, 3.0f);
                            }
                        } else {
                            int a = Math.Max(0, Math.Min(255, p.Alpha));
                            if (a <= 8) break;
                            if (p.ColorVariant == 0) {
                                DrawTsunamiWaveIcon(g, hx, hy, Math.Min(8.5f, p.Size * 1.15f), p.Rot * 0.08f, a, lightBg);
                            } else {
                                DrawSeaFoamDrop(g, hx, hy, p.Size, p.Rot, a, lightBg);
                            }
                        }
                        break;
                    }
                }
            } finally {
                g.SmoothingMode = oldSm;
            }
        }

        internal void PaintParticlesOverlay(Graphics g, Control ctrl, bool lightBg) {
            if (!IsStyled || !_showAnimation || _particles == null || ctrl == null) return;
            EnsureParticlesInitialized();

            int effAnim = GetEffectiveAnimEffect();
            Point origin = GetControlFormOrigin(ctrl);
            if (effAnim == 4) {
                DrawSunbeamsBackdrop(g, origin, lightBg);
            }

            Rectangle ctrlRect = new Rectangle(origin.X, origin.Y, ctrl.Width, ctrl.Height);
            float phaseSec = _animClock.ElapsedMilliseconds * 0.001f;

            InterpolationMode oldInterp = g.InterpolationMode;
            bool interpChanged = false;
            try {
                bool spriteMode = (effAnim == 0 || effAnim == 6);
                for (int i = 0; i < _particles.Length; i++) {
                    SeasonParticle p = _particles[i];
                    if (!ctrlRect.IntersectsWith(p.CurRect)) continue;
                    if (spriteMode) {
                        if (!interpChanged) {
                            g.InterpolationMode = InterpolationMode.Bilinear;
                            interpChanged = true;
                        }
                        DrawSeasonParticle(g, p, p.X - origin.X, p.Y - origin.Y, lightBg);
                    } else {
                        DrawEffectParticle(g, p, effAnim, origin.X, origin.Y, lightBg, phaseSec);
                    }
                }
            } finally {
                if (interpChanged) g.InterpolationMode = oldInterp;
            }
        }

        internal void PaintWhiteBackdropWithParticles(Graphics g, Control ctrl) {
            if (ctrl == null) return;
            g.FillRectangle(Brushes.White, 0, 0, ctrl.Width, ctrl.Height);
            PaintParticlesOverlay(g, ctrl, true);
        }

        private void InvalidateControlDirtyPatches(Control c, Rectangle[] dirtyRects, int dirtyCount) {
            if (c == null || c.IsDisposed || !c.Visible || !c.IsHandleCreated || c.Width <= 0 || c.Height <= 0) return;
            Point orig = GetControlFormOrigin(c);
            Rectangle cRect = new Rectangle(orig.X, orig.Y, c.Width, c.Height);
            int hits = 0;
            Rectangle union = Rectangle.Empty;
            for (int k = 0; k < dirtyCount; k++) {
                Rectangle inter = Rectangle.Intersect(cRect, dirtyRects[k]);
                if (inter.IsEmpty) continue;
                union = (hits == 0) ? inter : Rectangle.Union(union, inter);
                hits++;
            }
            if (hits == 0) return;
            bool isSmall = (c.Width * c.Height) <= 18000;
            if (hits == 1 || isSmall || hits > 6 || (union.Width * union.Height) <= (c.Width * c.Height) / 3) {
                union.Offset(-orig.X, -orig.Y);
                c.Invalidate(union, false);
                return;
            }
            for (int k = 0; k < dirtyCount; k++) {
                Rectangle inter = Rectangle.Intersect(cRect, dirtyRects[k]);
                if (!inter.IsEmpty) {
                    inter.Offset(-orig.X, -orig.Y);
                    c.Invalidate(inter, false);
                }
            }
        }

        private bool AdvanceParticlesPhysics(out int dirtyCount) {
            dirtyCount = 0;
            if (!IsStyled || !_showAnimation || _form == null || _form.IsDisposed || !_form.IsHandleCreated) return false;
            EnsureParticlesInitialized();

            int w = Math.Max(640, _form.ClientSize.Width);
            int h = Math.Max(420, _form.ClientSize.Height);
            long nowMs = _animClock.ElapsedMilliseconds;
            float dt = (_lastParticleMs > 0) ? ((nowMs - _lastParticleMs) * 0.001f) : 0.055f;
            if (dt < 0.015f) dt = 0.015f;
            if (dt > 0.09f) dt = 0.09f;
            _lastParticleMs = nowMs;
            float phaseSec = nowMs * 0.001f;

            int need = _particles.Length * 2;
            if (_dirtyRectBuf == null || _dirtyRectBuf.Length < need) {
                _dirtyRectBuf = new Rectangle[need];
            }

            int effAnim = GetEffectiveAnimEffect();
            for (int i = 0; i < _particles.Length; i++) {
                SeasonParticle p = _particles[i];
                p.PrevX = p.X;
                p.PrevY = p.Y;
                p.PrevRect = p.CurRect;
                if (!p.PrevRect.IsEmpty) {
                    _dirtyRectBuf[dirtyCount++] = p.PrevRect;
                }

                p.Life += dt;

                if ((effAnim >= 1 && effAnim <= 5) || (effAnim >= 7 && effAnim <= 10)) {
                    switch (effAnim) {
                        case 1: // Thien thach
                        case 2: // Sao bang
                            if (p.Kind == 0) {
                                float ddx = p.Vx * dt;
                                float ddy = p.Vy * dt;
                                p.X += ddx;
                                p.Y += ddy;
                                p.TailX += ddx;
                                p.TailY += ddy;
                                bool outOfBounds = (p.TailX > w + 45f || p.TailY > h + 45f);
                                bool expired = (effAnim == 2 && p.Life >= p.MaxLife);
                                if (outOfBounds || expired) {
                                    ResetParticle(p, w, h, false);
                                }
                            } else {
                                float sw = (effAnim == 1) ? ((float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp) : 0f;
                                p.X += (p.Vx + sw) * dt;
                                p.Y += p.Vy * dt;
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                p.Rot += p.RotSpeed * dt;
                                if (p.Life >= p.MaxLife || p.Y > h + 25f || p.X > w + 25f) {
                                    ResetParticle(p, w, h, true);
                                }
                            }
                            break;

                        case 3: // Gio
                            float wy = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * (p.SwayAmp * 0.35f);
                            p.X += p.Vx * dt;
                            p.Y += (p.Vy + wy) * dt;
                            float rLen = Math.Max(20f, p.RotSpeed);
                            p.TailX = p.X - rLen;
                            p.TailY = p.Y - (p.Vy + wy * 0.4f) * (rLen / Math.Max(80f, p.Vx));
                            if (p.TailX > w + 40f || p.Y < -50f || p.Y > h + 50f) {
                                ResetParticle(p, w, h, false);
                            }
                            break;

                        case 4: // Tia nang
                            if (p.Kind == 0) {
                                float ddx = p.Vx * dt;
                                float ddy = p.Vy * dt;
                                p.X += ddx;
                                p.Y += ddy;
                                p.TailX += ddx;
                                p.TailY += ddy;
                                if (p.Life >= p.MaxLife || p.TailX > w + 40f || p.TailY > h + 40f) {
                                    ResetParticle(p, w, h, true);
                                }
                            } else {
                                float sw = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp;
                                p.X += (p.Vx + sw) * dt;
                                p.Y += p.Vy * dt;
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                if (p.Life >= p.MaxLife || p.Y > h + 30f || p.X > w + 30f) {
                                    ResetParticle(p, w, h, true);
                                }
                            }
                            break;

                        case 5: // Mua
                            if (p.Kind == 0) {
                                float ddx = p.Vx * dt;
                                float ddy = p.Vy * dt;
                                p.X += ddx;
                                p.Y += ddy;
                                p.TailX += ddx;
                                p.TailY += ddy;
                                if (p.TailY > h + 28f || p.X < -60f) {
                                    ResetParticle(p, w, h, false);
                                }
                            } else {
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                if (p.Life >= p.MaxLife) {
                                    ResetParticle(p, w, h, true);
                                }
                            }
                            break;

                        case 7: { // Lua (Fire - ngọn lửa & tàn tro bay lên)
                            float swayF = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp;
                            p.X += (p.Vx + swayF) * dt;
                            p.Y += p.Vy * dt;
                            if (p.Kind == 0) {
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                p.Rot = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * 16f;
                            } else {
                                p.TailX = p.X - (p.Vx + swayF) * 0.065f;
                                p.TailY = p.Y - p.Vy * 0.065f;
                                p.Rot += p.RotSpeed * dt;
                            }
                            if (p.Life >= p.MaxLife || p.Y < -28f || p.X < -30f || p.X > w + 30f) {
                                ResetParticle(p, w, h, false);
                            }
                            break;
                        }

                        case 8: // Sam chop (Lightning - tia sét & tia điện)
                            if (p.Kind == 0) {
                                p.X += p.Vx * dt * 0.25f;
                                p.Y += p.Vy * dt * 0.25f;
                                p.TailX += p.Vx * dt * 0.25f;
                                p.TailY += p.Vy * dt * 0.25f;
                            } else {
                                float swayL = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp;
                                p.X += (p.Vx + swayL) * dt;
                                p.Y += p.Vy * dt;
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                p.Rot += p.RotSpeed * dt;
                            }
                            if (p.Life >= p.MaxLife) {
                                ResetParticle(p, w, h, false);
                            }
                            break;

                        case 9: // Loc xoay (Tornado - phễu xoáy & gió xoáy)
                            if (p.Kind == 0) {
                                float swayY = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * (p.SwayAmp * 0.45f);
                                p.X += p.Vx * dt;
                                p.Y += (p.Vy + swayY) * dt;
                                float minTy = Math.Max(48f, p.Size + 24f);
                                float maxTy = Math.Max(minTy + 10f, h - 18f);
                                if (p.Y < minTy) { p.Y = minTy; p.Vy = Math.Abs(p.Vy); }
                                else if (p.Y > maxTy) { p.Y = maxTy; p.Vy = -Math.Abs(p.Vy); }
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                if (p.X > w + 90f || p.Life >= p.MaxLife) {
                                    ResetParticle(p, w, h, false);
                                }
                            } else {
                                float swayY = (float)Math.Cos(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp * 0.55f;
                                p.X += p.Vx * dt;
                                p.Y += (p.Vy + swayY) * dt;
                                float tLen = Math.Max(26f, p.RotSpeed);
                                p.TailX = p.X - tLen;
                                p.TailY = p.Y - p.Vy * (tLen / Math.Max(80f, p.Vx));
                                p.Rot += 140f * dt;
                                if (p.TailX > w + 40f || p.Y < -40f || p.Y > h + 40f || p.Life >= p.MaxLife) {
                                    ResetParticle(p, w, h, false);
                                }
                            }
                            break;

                        case 10: // Song than (Tsunami - sóng cuộn & bọt biển)
                            if (p.Kind == 0) {
                                float bobY = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * 8f;
                                p.X += p.Vx * dt;
                                p.Y += (p.Vy + bobY) * dt;
                                float minWy = 72f;
                                float maxWy = Math.Max(minWy + 20f, h - 24f);
                                if (p.Y < minWy) { p.Y = minWy; p.Vy = Math.Abs(p.Vy); }
                                else if (p.Y > maxWy) { p.Y = maxWy; p.Vy = -Math.Abs(p.Vy); }
                                float waveW = Math.Max(48f, p.SwayAmp);
                                p.TailX = p.X - waveW;
                                p.TailY = p.Y;
                                if (p.TailX > w + 40f || p.Life >= p.MaxLife) {
                                    ResetParticle(p, w, h, false);
                                }
                            } else {
                                float swayY = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp;
                                p.X += p.Vx * dt;
                                p.Y += (p.Vy + swayY) * dt;
                                p.TailX = p.X;
                                p.TailY = p.Y;
                                p.Rot += 75f * dt;
                                if (p.X > w + 32f || p.Y < -30f || p.Y > h + 30f || p.Life >= p.MaxLife) {
                                    ResetParticle(p, w, h, false);
                                }
                            }
                            break;
                    }
                    p.CurRect = ComputeParticleRect(p, effAnim);
                    if (!p.CurRect.IsEmpty) {
                        _dirtyRectBuf[dirtyCount++] = p.CurRect;
                    }
                    continue;
                }

                float sway = (float)Math.Sin(phaseSec * p.SwayFreq + p.SwayPhase) * p.SwayAmp;
                p.X += (p.Vx + sway) * dt;
                p.Y += p.Vy * dt;
                p.TailX = p.X;
                p.TailY = p.Y;
                p.Rot += p.RotSpeed * dt;
                if (p.Rot >= 360f) p.Rot -= 360f;
                else if (p.Rot < 0f) p.Rot += 360f;

                if (p.Y > h + 18f) {
                    ResetParticle(p, w, h, false);
                } else {
                    if (p.X > w + 22f) p.X -= (w + 44f);
                    else if (p.X < -22f) p.X += (w + 44f);
                    p.TailX = p.X;
                    p.TailY = p.Y;
                    p.CurRect = ComputeParticleRect(p, effAnim);
                }
                if (!p.CurRect.IsEmpty) {
                    _dirtyRectBuf[dirtyCount++] = p.CurRect;
                }
            }

            Interlocked.Increment(ref _particleTickCount);
            return true;
        }

        private void InvalidateParticlePatches(int dirtyCount) {
            if (dirtyCount <= 0 || _form == null || _form.IsDisposed || !_form.IsHandleCreated) return;
            InvalidateControlDirtyPatches(_form, _dirtyRectBuf, dirtyCount);
            for (int i = 0; i < _glassContainers.Count; i++) {
                InvalidateControlDirtyPatches(_glassContainers[i], _dirtyRectBuf, dirtyCount);
            }
            for (int i = 0; i < _glassLeaves.Count; i++) {
                InvalidateControlDirtyPatches(_glassLeaves[i], _dirtyRectBuf, dirtyCount);
            }
        }

        private void SyncAmbientTimer() {
            if (_disposed || _form == null || _form.IsDisposed) {
                if (_ambientTimer != null) {
                    try { _ambientTimer.Stop(); } catch { }
                }
                return;
            }
            if (_form.InvokeRequired) {
                try { _form.BeginInvoke(new MethodInvoker(SyncAmbientTimer)); } catch { }
                return;
            }
            bool want = (IsStyled && (_showOrnaments || _showAnimation));
            if (want) {
                if (_ambientTimer == null) {
                    _ambientTimer = new System.Windows.Forms.Timer();
                    _ambientTimer.Tick += OnAmbientTimerTick;
                }
                if (_ambientTimer.Interval != 55) _ambientTimer.Interval = 55;
                if (_showAnimation) EnsureParticlesInitialized();
                _lastParticleMs = _animClock.ElapsedMilliseconds;
                _lastAmbientRunMs = 0;
                if (!_ambientTimer.Enabled) _ambientTimer.Start();
            } else {
                if (_ambientTimer != null && _ambientTimer.Enabled) _ambientTimer.Stop();
            }
        }

        private void OnAmbientTimerTick(object sender, EventArgs e) {
            if (_disposed || !IsStyled || (!_showOrnaments && !_showAnimation) || _form == null || _form.IsDisposed || !_form.Visible || _form.WindowState == FormWindowState.Minimized) {
                return;
            }
            long nowMs = _animClock.ElapsedMilliseconds;
            if ((nowMs - _lastAmbientRunMs) < 46) return;
            _lastAmbientRunMs = nowMs;

            _ambientTick++;
            if (_isActive && _isAnimated && !_isPaused) {
                if (_showAnimation && (nowMs - _lastParticleMs) >= 85) {
                    int fdc;
                    if (AdvanceParticlesPhysics(out fdc)) InvalidateParticlePatches(fdc);
                }
                return;
            }

            if (_showAnimation) {
                int dc;
                if (AdvanceParticlesPhysics(out dc)) InvalidateParticlePatches(dc);
            }
            if (!_showOrnaments) return;
            if ((_ambientTick & 1) != 0) return;

            int swayPhaseTick = _ambientTick / 2;
            bool pulseControls = ((swayPhaseTick & 1) == 0);
            bool pulseFormEdge = ((swayPhaseTick % 3) == 0);

            foreach (Control c in _navContainers) {
                if (c == null || c.IsDisposed || !c.Visible || !c.IsHandleCreated) continue;
                if (object.Equals(c.Tag, "HeaderBar")) {
                    int openW = Math.Max(40, c.Width - 870);
                    c.Invalidate(new Rectangle(485, 0, openW, c.Height), false);
                    c.Invalidate(new Rectangle(0, 0, 50, 32), false);
                } else if (pulseControls && object.Equals(c.Tag, "NavSidebar")) {
                    c.Invalidate(new Rectangle(0, Math.Max(0, c.Height - 78), c.Width, 78), false);
                    c.Invalidate(new Rectangle(0, 0, 48, 36), false);
                }
            }

            if (_mainTabs != null && !_mainTabs.IsDisposed) {
                TabPage tp = _mainTabs.SelectedTab;
                if (tp != null && !tp.IsDisposed && tp.Visible && tp.IsHandleCreated) {
                    tp.Invalidate(new Rectangle(Math.Max(0, tp.Width - 155), 0, 155, 56), false);
                    tp.Invalidate(new Rectangle(0, 0, 105, 44), false);
                    if (pulseFormEdge) {
                        tp.Invalidate(new Rectangle(0, Math.Max(0, tp.Height - 44), 105, 44), false);
                        tp.Invalidate(new Rectangle(Math.Max(0, tp.Width - 105), Math.Max(0, tp.Height - 44), 105, 44), false);
                    }
                }
            }

            foreach (Control c in _glassContainers) {
                if (c == null || c.IsDisposed || !c.Visible || !c.IsHandleCreated) continue;
                if (c is GroupBox) {
                    c.Invalidate(new Rectangle(Math.Max(0, c.Width - 135), 0, 135, 52), false);
                    if (pulseFormEdge) {
                        c.Invalidate(new Rectangle(Math.Max(0, c.Width - 95), Math.Max(0, c.Height - 40), 95, 40), false);
                        c.Invalidate(new Rectangle(0, Math.Max(0, c.Height - 40), 95, 40), false);
                    }
                } else if (pulseControls && object.Equals(c.Tag, "QuickCard")) {
                    c.Invalidate(new Rectangle(Math.Max(0, c.Width - 105), 0, 105, 42), false);
                }
            }

            if (pulseControls) {
                if (_modeBadge != null && !_modeBadge.IsDisposed && _modeBadge.Visible && _modeBadge.IsHandleCreated && !_activeAnims.Contains(_modeBadge)) {
                    _modeBadge.Invalidate(false);
                }
                if (_activeNavBtn != null && !_activeNavBtn.IsDisposed && _activeNavBtn.Visible && _activeNavBtn.IsHandleCreated && !_activeAnims.Contains(_activeNavBtn)) {
                    _activeNavBtn.Invalidate(false);
                }
                foreach (Control b in _themedButtons) {
                    if (b == null || b.IsDisposed || !b.Visible || !b.IsHandleCreated || _activeAnims.Contains(b)) continue;
                    string tag = (b.Tag != null) ? b.Tag.ToString() : "";
                    if (tag == "ThemeQuick" || tag == "Primary") {
                        b.Invalidate(false);
                    }
                }
                foreach (Control leaf in _glassLeaves) {
                    if (leaf is GlassSlider && !leaf.IsDisposed && leaf.Visible && leaf.IsHandleCreated) {
                        leaf.Invalidate(false);
                    }
                }
            }

            if (pulseFormEdge && _form.IsHandleCreated) {
                _form.Invalidate(new Rectangle(0, Math.Max(0, _form.ClientSize.Height - 26), _form.ClientSize.Width, 26), false);
            }
        }

        public void TriggerButtonAnimation(Control c, int x, int y) {
            if (_disposed || c == null || c.IsDisposed || !c.Enabled) return;
            ButtonAnimState st = GetOrCreateAnimState(c);
            st.HoverPos = new PointF(Math.Max(0, Math.Min(c.Width, x)), Math.Max(0, Math.Min(c.Height, y)));
            st.HasHoverPos = true;
            st.ClickDipActive = true;
            st.ClickDipT = 0f;
            StartAnimFor(c);
        }

        public void TriggerHoverAnimation(Control c, int x, int y) {
            if (_disposed || c == null || c.IsDisposed || !c.Enabled) return;
            _hoveredControls.Add(c);
            ButtonAnimState st = GetOrCreateAnimState(c);
            st.HoverPos = new PointF(Math.Max(0, Math.Min(c.Width, x)), Math.Max(0, Math.Min(c.Height, y)));
            st.HasHoverPos = true;
            st.HoverSweepActive = true;
            st.HoverSweepT = 0f;
            StartAnimFor(c);
        }

        public void ClearHoverAnimation(Control c) {
            if (_disposed || c == null || c.IsDisposed) return;
            _hoveredControls.Remove(c);
            _pressedControls.Remove(c);
            StartAnimFor(c);
        }

        public void Attach(Form form, Control[] navLayerContainers, Control[] navLayerLeaves, Control[] excludedControls, TabControl mainTabs, TabControl[] subTabControls, Label modeBadge) {
            _form = form;
            _mainTabs = mainTabs;
            _modeBadge = modeBadge;
            _targetW = Math.Max(320, form.ClientSize.Width);
            _targetH = Math.Max(240, form.ClientSize.Height);

            if (navLayerContainers != null) foreach (Control c in navLayerContainers) if (c != null) _navContainers.Add(c);
            if (navLayerLeaves != null) foreach (Control c in navLayerLeaves) if (c != null) _navLeaves.Add(c);
            if (excludedControls != null) foreach (Control c in excludedControls) if (c != null) _excluded.Add(c);

            EnableDoubleBuffering(form);
            _noEraseHooks.Add(new NoEraseWindow(this, form));
            _formCanAnimate = (form.Visible && form.WindowState != FormWindowState.Minimized);
            form.Paint += OnFormPaint;
            form.SizeChanged += OnFormSizeChanged;
            form.VisibleChanged += OnFormStateChanged;
            form.FormClosing += OnFormClosingHandler;

            if (subTabControls != null) {
                foreach (TabControl tc in subTabControls) {
                    if (tc == null) continue;
                    _subTabs.Add(tc);
                    tc.DrawItem += OnSubTabDrawItem;
                    _tabStripHooks.Add(new ThemedTabStripWindow(this, tc));
                }
            }

            if (_modeBadge != null) {
                EnableDoubleBuffering(_modeBadge);
                _noEraseHooks.Add(new NoEraseWindow(this, _modeBadge));
                _glassLeaves.Add(_modeBadge);
                _modeBadge.Paint += OnModeBadgePaint;
                _modeBadge.MouseEnter += OnControlMouseEnter;
                _modeBadge.MouseMove += OnControlMouseMove;
                _modeBadge.MouseLeave += OnControlMouseLeave;
                _modeBadge.MouseDown += OnControlMouseDown;
                _modeBadge.MouseUp += OnControlMouseUp;
            }

            HookRecursive(form);
            _isAttached = true;
            SyncAmbientTimer();
        }

        private void OnFormStateChanged(object sender, EventArgs e) {
            bool prev = _formCanAnimate;
            _formCanAnimate = (_form != null && !_form.IsDisposed && _form.Visible && _form.WindowState != FormWindowState.Minimized);
            if (!prev && _formCanAnimate) {
                try { _workerWake.Set(); } catch { }
            }
        }

        private void OnFormClosingHandler(object sender, FormClosingEventArgs e) {
            _formCanAnimate = false;
            Interlocked.Increment(ref _workerGen);
            try { _workerWake.Set(); } catch { }
        }

        private bool IsExcludedOrDescendant(Control c) {
            Control cur = c;
            while (cur != null) {
                if (_excluded.Contains(cur)) return true;
                cur = cur.Parent;
            }
            return false;
        }

        private void HookRecursive(Control parent) {
            foreach (Control c in parent.Controls) {
                if (c == null) continue;
                if (object.ReferenceEquals(c, _modeBadge)) continue;
                bool isExcluded = IsExcludedOrDescendant(c);
                EnableDoubleBuffering(c);

                if (c is Panel || c is TabPage || c is GroupBox) {
                    if (!isExcluded) {
                        _glassContainers.Add(c);
                        _noEraseHooks.Add(new NoEraseWindow(this, c));
                        if (c is GroupBox) c.Paint += OnGroupBoxPaint;
                        else c.Paint += OnGlassContainerPaint;

                        ScrollableControl sc = c as ScrollableControl;
                        if (sc != null) {
                            sc.Scroll += OnContainerScroll;
                        }
                    }
                } else if (!isExcluded && (c is Label)) {
                    _glassLeaves.Add(c);
                    _noEraseHooks.Add(new NoEraseWindow(this, c));
                    c.Paint += OnLabelPaint;
                } else if (!isExcluded && (c is CheckBox)) {
                    _glassLeaves.Add(c);
                    _noEraseHooks.Add(new NoEraseWindow(this, c));
                    c.Paint += OnCheckBoxPaint;
                } else if (!isExcluded && (c is RadioButton)) {
                    _glassLeaves.Add(c);
                    _noEraseHooks.Add(new NoEraseWindow(this, c));
                    c.Paint += OnRadioButtonPaint;
                } else if (!isExcluded && (c is GlassSlider)) {
                    _glassLeaves.Add(c);
                } else if (!isExcluded && (c is Button)) {
                    _glassLeaves.Add(c);
                    _themedButtons.Add(c);
                    _noEraseHooks.Add(new NoEraseWindow(this, c));
                    c.Paint += OnThemedButtonPaint;
                    c.MouseEnter += OnControlMouseEnter;
                    c.MouseMove += OnControlMouseMove;
                    c.MouseLeave += OnControlMouseLeave;
                    c.MouseDown += OnControlMouseDown;
                    c.MouseUp += OnControlMouseUp;
                    c.KeyDown += OnControlKeyDown;
                } else if (c is ComboBox) {
                    ComboBox cbo = (ComboBox)c;
                    cbo.DrawItem += OnComboDrawItem;
                    _comboHooks.Add(new ThemedComboBoxWindow(this, cbo));
                } else if (c is ListView) {
                    ListView lv = (ListView)c;
                    lv.DrawColumnHeader += OnListViewDrawColumnHeader;
                    lv.DrawItem += OnListViewDrawItem;
                    lv.DrawSubItem += OnListViewDrawSubItem;
                    _borderHooks.Add(new ThemedBorderWindow(this, lv));
                    _listHeaderHooks.Add(new ThemedListHeaderWindow(this, lv));
                } else if (c is TextBoxBase || c is TreeView || c is NumericUpDown) {
                    _borderHooks.Add(new ThemedBorderWindow(this, c));
                }

                if (c.HasChildren) {
                    HookRecursive(c);
                }
            }
        }

        private static void EnableDoubleBuffering(Control c) {
            if (s_propDoubleBuffered == null || c == null) return;
            if (c is Form || c is Panel || c is TabPage || c is GroupBox || c is Label || c is CheckBox || c is RadioButton || c is Button) {
                try { s_propDoubleBuffered.SetValue(c, true, null); } catch { }
            }
        }

        private ButtonAnimState GetAnimStateOrNull(Control c) {
            if (c == null) return null;
            ButtonAnimState st;
            return _animStates.TryGetValue(c, out st) ? st : null;
        }

        private ButtonAnimState GetOrCreateAnimState(Control c) {
            ButtonAnimState st;
            if (!_animStates.TryGetValue(c, out st)) {
                st = new ButtonAnimState();
                _animStates[c] = st;
            }
            return st;
        }

        private void StartAnimFor(Control c) {
            if (_disposed || c == null || c.IsDisposed) return;
            GetOrCreateAnimState(c);
            _activeAnims.Add(c);
            if (_animTimer == null) {
                _animTimer = new System.Windows.Forms.Timer();
                _animTimer.Interval = 16;
                _animTimer.Tick += OnAnimTimerTick;
            }
            if (!_animTimer.Enabled) {
                _lastAnimTickMs = _animClock.ElapsedMilliseconds;
                _animTimer.Start();
            }
            if (c.Visible && c.IsHandleCreated) c.Invalidate();
        }

        private static float ComputeClickDipDepth(float t) {
            if (t <= 0f) return 0f;
            if (t < 0.28f) {
                float u = t / 0.28f;
                return 1f - (1f - u) * (1f - u);
            }
            if (t < 0.78f) {
                float u = (t - 0.28f) / 0.50f;
                float s = u * u * (3f - 2f * u);
                return 1f - 1.12f * s;
            }
            if (t < 1f) {
                float u = (t - 0.78f) / 0.22f;
                float s = u * u * (3f - 2f * u);
                return -0.12f * (1f - s);
            }
            return 0f;
        }

        private void OnAnimTimerTick(object sender, EventArgs e) {
            if (_disposed || _activeAnims.Count == 0) {
                if (_animTimer != null) _animTimer.Stop();
                return;
            }

            long nowMs = _animClock.ElapsedMilliseconds;
            float dt = (nowMs - _lastAnimTickMs) / 1000f;
            _lastAnimTickMs = nowMs;
            if (dt < 0.005f) dt = 0.005f;
            if (dt > 0.06f) dt = 0.06f;

            List<Control> snapshot = new List<Control>(_activeAnims);
            for (int i = 0; i < snapshot.Count; i++) {
                Control c = snapshot[i];
                if (c == null || c.IsDisposed) {
                    _activeAnims.Remove(c);
                    continue;
                }
                ButtonAnimState st = GetOrCreateAnimState(c);
                bool isHovered = c.Enabled && _hoveredControls.Contains(c);
                bool isPressed = c.Enabled && _pressedControls.Contains(c);
                float targetHover = isHovered ? 1f : 0f;

                st.HoverT = StepTowards(st.HoverT, targetHover, dt * (isHovered ? 9.0f : 7.5f));

                if (st.HoverSweepActive) {
                    st.HoverSweepT += dt / 0.34f;
                    if (st.HoverSweepT >= 1f) {
                        st.HoverSweepActive = false;
                        st.HoverSweepT = 0f;
                    }
                }

                if (st.ClickDipActive) {
                    st.ClickDipT += dt / 0.21f;
                    if (isPressed && st.ClickDipT > 0.28f) {
                        st.ClickDipT = 0.28f;
                    }
                    if (st.ClickDipT >= 1f) {
                        st.ClickDipActive = false;
                        st.ClickDipT = 0f;
                        st.PressDepth = 0f;
                    } else {
                        st.PressDepth = ComputeClickDipDepth(st.ClickDipT);
                    }
                } else {
                    if (isPressed) {
                        st.PressDepth = StepTowards(st.PressDepth, 1f, dt * 14f);
                    } else {
                        st.PressDepth = StepTowards(st.PressDepth, 0f, dt * 12f);
                    }
                }

                if (st.HoverT <= 0.001f && !isHovered) {
                    st.HasHoverPos = false;
                }

                if (c.Visible && c.IsHandleCreated) c.Invalidate();

                if (!st.HoverSweepActive && !st.ClickDipActive && !isPressed &&
                    Math.Abs(st.HoverT - targetHover) < 0.005f &&
                    Math.Abs(st.PressDepth) < 0.005f) {
                    st.HoverT = targetHover;
                    st.PressDepth = 0f;
                    _activeAnims.Remove(c);
                }
            }

            if (_activeAnims.Count == 0 && _animTimer != null) {
                _animTimer.Stop();
            }
        }

        private static float StepTowards(float cur, float target, float delta) {
            if (cur < target) return Math.Min(target, cur + delta);
            if (cur > target) return Math.Max(target, cur - delta);
            return cur;
        }

        private void OnControlMouseEnter(object sender, EventArgs e) {
            Control c = sender as Control;
            if (c != null) {
                _hoveredControls.Add(c);
                if (c.Enabled) {
                    ButtonAnimState st = GetOrCreateAnimState(c);
                    try {
                        Point pt = c.PointToClient(Control.MousePosition);
                        st.HoverPos = new PointF(Math.Max(0, Math.Min(c.Width, pt.X)), Math.Max(0, Math.Min(c.Height, pt.Y)));
                    } catch {
                        st.HoverPos = new PointF(c.Width * 0.5f, c.Height * 0.5f);
                    }
                    st.HasHoverPos = true;
                    st.HoverSweepActive = true;
                    st.HoverSweepT = 0f;
                    StartAnimFor(c);
                }
            }
        }

        private void OnControlMouseMove(object sender, MouseEventArgs e) {
            Control c = sender as Control;
            if (_disposed || c == null || !c.Enabled || !_hoveredControls.Contains(c)) return;
            ButtonAnimState st = GetOrCreateAnimState(c);
            if (!st.HasHoverPos || Math.Abs(e.X - st.HoverPos.X) >= 1f || Math.Abs(e.Y - st.HoverPos.Y) >= 1f) {
                st.HoverPos = new PointF(e.X, e.Y);
                st.HasHoverPos = true;
                if (c.Visible && c.IsHandleCreated) c.Invalidate();
            }
        }

        private void OnControlMouseLeave(object sender, EventArgs e) {
            Control c = sender as Control;
            if (c != null) {
                _hoveredControls.Remove(c);
                _pressedControls.Remove(c);
                if (_animStates.ContainsKey(c) || _activeAnims.Contains(c)) StartAnimFor(c);
            }
        }

        private void OnControlMouseDown(object sender, MouseEventArgs e) {
            Control c = sender as Control;
            if (c != null && e.Button == MouseButtons.Left && c.Enabled) {
                _pressedControls.Add(c);
                TriggerButtonAnimation(c, e.X, e.Y);
            }
        }

        private void OnControlMouseUp(object sender, MouseEventArgs e) {
            Control c = sender as Control;
            if (c != null) {
                _pressedControls.Remove(c);
                if (_animStates.ContainsKey(c) || _activeAnims.Contains(c)) StartAnimFor(c);
            }
        }

        private void OnControlKeyDown(object sender, KeyEventArgs e) {
            Control c = sender as Control;
            if (c != null && c.Enabled && (e.KeyCode == Keys.Space || e.KeyCode == Keys.Return)) {
                TriggerButtonAnimation(c, c.Width / 2, c.Height / 2);
            }
        }

        private void OnContainerScroll(object sender, ScrollEventArgs e) {
            if (!IsStyled) return;
            Control c = sender as Control;
            if (c != null) c.Invalidate(true);
        }

        private void OnFormSizeChanged(object sender, EventArgs e) {
            _formCanAnimate = (_form != null && !_form.IsDisposed && _form.Visible && _form.WindowState != FormWindowState.Minimized);
            if (_formCanAnimate) {
                try { _workerWake.Set(); } catch { }
            }
            if (_form == null || _form.WindowState == FormWindowState.Minimized) return;
            int w = Math.Max(320, _form.ClientSize.Width);
            int h = Math.Max(240, _form.ClientSize.Height);
            if (w == _targetW && h == _targetH) return;
            _targetW = w;
            _targetH = h;
            if (!IsStyled) return;
            if (!_isActive) {
                RefreshNow();
                return;
            }

            if (_resizeTimer == null) {
                _resizeTimer = new System.Windows.Forms.Timer();
                _resizeTimer.Interval = 60;
                _resizeTimer.Tick += OnResizeTimerTick;
            }
            _resizeTimer.Stop();
            _resizeTimer.Start();
        }

        private void OnResizeTimerTick(object sender, EventArgs e) {
            if (_resizeTimer != null) _resizeTimer.Stop();
            if (!_isActive) return;
            RecomposeCurrentFrame(true);
            RefreshNow();
        }

        private void RecomposeCurrentFrame(bool highQuality) {
            if (!_isAnimated && _staticSource != null) {
                ComposeLayersFromSource(_staticSource, highQuality, false);
                return;
            }
            lock (_srcLock) {
                if (_lastSourceFrame != null) {
                    ComposeLayersFromSource(_lastSourceFrame, highQuality, false);
                }
            }
        }

        public bool LoadTheme(string filePath) {
            _lastError = "";
            if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath)) {
                _lastError = "Không tìm thấy tệp theme: " + filePath;
                return false;
            }

            StopWorkerAndClearDecoders();

            string ext = Path.GetExtension(filePath).ToLowerInvariant();
            try {
                if (ext == ".mp4") {
                    using (MfVideoDecoder probe = new MfVideoDecoder(filePath)) {
                        Bitmap first;
                        int delay;
                        if (!probe.ReadNextFrame(out first, out delay) || first == null) {
                            throw new InvalidOperationException("Không đọc được khung hình đầu tiên từ video MP4.");
                        }
                        ComposeLayersFromSource(first, false, true);
                    }
                    _activePath = filePath;
                    _activeKind = "MP4";
                    _isAnimated = true;
                    _isPaused = false;
                    _isActive = true;
                    _activeAnimatedPath = filePath;
                    _activeAnimatedIsMp4 = true;
                    StartWorkerThread();
                    SyncAmbientTimer();
                    RefreshNow();
                    return true;
                } else if (ext == ".gif") {
                    GifDecoder gif = new GifDecoder(filePath);
                    int delay;
                    Bitmap first = gif.ReadFrame(0, out delay);
                    if (first == null) {
                        gif.Dispose();
                        throw new InvalidOperationException("Không đọc được khung hình GIF.");
                    }
                    if (gif.FrameCount <= 1) {
                        _staticSource = new Bitmap(first);
                        gif.Dispose();
                        ComposeLayersFromSource(_staticSource, true, false);
                        _activePath = filePath;
                        _activeKind = "GIF";
                        _isAnimated = false;
                        _isPaused = false;
                        _isActive = true;
                        SyncAmbientTimer();
                        RefreshNow();
                        return true;
                    }
                    ComposeLayersFromSource(first, false, true);
                    gif.Dispose();
                    _activePath = filePath;
                    _activeKind = "GIF";
                    _isAnimated = true;
                    _isPaused = false;
                    _isActive = true;
                    _activeAnimatedPath = filePath;
                    _activeAnimatedIsMp4 = false;
                    StartWorkerThread();
                    SyncAmbientTimer();
                    RefreshNow();
                    return true;
                } else {
                    byte[] bytes = File.ReadAllBytes(filePath);
                    using (MemoryStream ms = new MemoryStream(bytes))
                    using (Image img = Image.FromStream(ms)) {
                        _staticSource = new Bitmap(img.Width, img.Height, PixelFormat.Format32bppRgb);
                        using (Graphics g = Graphics.FromImage(_staticSource)) {
                            g.DrawImage(img, 0, 0, img.Width, img.Height);
                        }
                    }
                    ComposeLayersFromSource(_staticSource, true, false);
                    _activePath = filePath;
                    _activeKind = "Image";
                    _isAnimated = false;
                    _isPaused = false;
                    _isActive = true;
                    SyncAmbientTimer();
                    RefreshNow();
                    return true;
                }
            } catch (Exception ex) {
                _lastError = ex.Message;
                ClearTheme();
                return false;
            }
        }

        public void ClearTheme() {
            StopWorkerAndClearDecoders();
            _isActive = false;
            _isAnimated = false;
            _isPaused = false;
            _activePath = "";
            _activeKind = "None";
            _activeAnimatedPath = "";
            SyncAmbientTimer();
            lock (_frameLock) {
                if (_layerRaw != null) { _layerRaw.Dispose(); _layerRaw = null; }
                if (_layerPanel != null) { _layerPanel.Dispose(); _layerPanel = null; }
                if (_layerNav != null) { _layerNav.Dispose(); _layerNav = null; }
            }
            RefreshNow();
        }

