            _strongTextOutline = strongOutline;
            _textPreset = Math.Max(0, Math.Min(6, textPreset));
            _showOrnaments = showOrnaments;
            _showAnimation = showAnimation;
            int clampedSeason = Math.Max(0, Math.Min(13, ornamentSeason));
            int clampedAnim = Math.Max(0, Math.Min(10, animEffect));
            bool needReinit = (_ornamentSeason != clampedSeason) || (_animEffect != clampedAnim);
            _ornamentSeason = clampedSeason;
            _borderStyle = clampedSeason;
            _animEffect = clampedAnim;
            if (needReinit) ReinitParticlesForSeason();
            SyncAmbientTimer();
        }

