        private void ClearPendingLayers() {
            Bitmap pRaw = null, pPanel = null, pNav = null;
            lock (_pendingLock) {
                pRaw = _pendingRaw;
                pPanel = _pendingPanel;
                pNav = _pendingNav;
                _pendingRaw = null;
                _pendingPanel = null;
                _pendingNav = null;
            }
            if (pRaw != null) pRaw.Dispose();
            if (pPanel != null) pPanel.Dispose();
            if (pNav != null) pNav.Dispose();
        }

        private void PromotePendingLayers() {
            Bitmap nRaw = null, nPanel = null, nNav = null;
            lock (_pendingLock) {
                if (_pendingRaw != null) {
                    nRaw = _pendingRaw;
                    nPanel = _pendingPanel;
                    nNav = _pendingNav;
                    _pendingRaw = null;
                    _pendingPanel = null;
                    _pendingNav = null;
                }
            }
            if (nRaw == null) return;

            Bitmap oldRaw, oldPanel, oldNav;
            lock (_frameLock) {
                oldRaw = _layerRaw;
                oldPanel = _layerPanel;
                oldNav = _layerNav;
                _layerRaw = nRaw;
                _layerPanel = nPanel;
                _layerNav = nNav;
            }
            Interlocked.Increment(ref _frameCount);

            if (oldRaw != null) oldRaw.Dispose();
            if (oldPanel != null) oldPanel.Dispose();
            if (oldNav != null) oldNav.Dispose();
        }

        private void StopWorkerAndClearDecoders() {
            Interlocked.Increment(ref _workerGen);
            Interlocked.Exchange(ref _pendingRepaint, 0);
            try { _workerWake.Set(); } catch { }
            Thread w = _worker;
            _worker = null;
            if (w != null && w.IsAlive) {
                try { w.Join(1200); } catch { }
            }
            ClearPendingLayers();
            if (_staticSource != null) {
                _staticSource.Dispose();
                _staticSource = null;
            }
            lock (_srcLock) {
                if (_lastSourceFrame != null) {
                    _lastSourceFrame.Dispose();
                    _lastSourceFrame = null;
                }
            }
        }

        private void StartWorkerThread() {
            long myGen = Interlocked.Increment(ref _workerGen);
            if (_form != null && !_form.IsDisposed) {
                _formCanAnimate = (_form.Visible && _form.WindowState != FormWindowState.Minimized);
            }
            try { _workerWake.Reset(); } catch { }
            Thread t = new Thread(delegate() { WorkerLoop(myGen); });
            t.IsBackground = true;
            t.Name = "JebtoolThemeWorker";
            t.SetApartmentState(ApartmentState.MTA);
            _worker = t;
            t.Start();
        }

        private void WorkerLoop(long myGen) {
            string path = _activeAnimatedPath;
            bool isMp4 = _activeAnimatedIsMp4;
            MfVideoDecoder mp4 = null;
            GifDecoder gif = null;
            int gifIdx = 0;
            Stopwatch sw = Stopwatch.StartNew();
            long lastRepaintMs = 0;

            try {
                if (isMp4) mp4 = new MfVideoDecoder(path);
                else gif = new GifDecoder(path);

                while (Interlocked.Read(ref _workerGen) == myGen && _isActive && !_disposed) {
                    if (_isPaused || !_formCanAnimate) {
                        _workerWake.WaitOne(120);
                        continue;
                    }

                    if (Interlocked.CompareExchange(ref _pendingRepaint, 0, 0) != 0 && (sw.ElapsedMilliseconds - lastRepaintMs) < 90) {
                        _workerWake.WaitOne(16);
                        continue;
                    }

                    long frameStartMs = sw.ElapsedMilliseconds;
                    Bitmap bmp = null;
                    int delayMs = 33;

                    if (isMp4) {
                        Bitmap decoded;
                        if (mp4.ReadNextFrame(out decoded, out delayMs) && decoded != null) {
                            if (Interlocked.Read(ref _workerGen) != myGen || !_isActive) break;
                            ComposeLayersToPending(decoded, false, true, myGen);
                        } else {
                            _workerWake.WaitOne(40);
                            continue;
                        }
                    } else {
                        bmp = gif.ReadFrame(gifIdx++, out delayMs);
                        if (bmp != null) {
                            if (Interlocked.Read(ref _workerGen) != myGen || !_isActive) break;
                            ComposeLayersToPending(bmp, false, true, myGen);
                        }
                    }

                    if (Interlocked.Read(ref _workerGen) != myGen || !_isActive) break;

                    long nowMs = sw.ElapsedMilliseconds;
                    if ((nowMs - lastRepaintMs) >= 33) {
                        lastRepaintMs = nowMs;
                        ScheduleRepaint(myGen);
                    }

                    int elapsed = (int)(sw.ElapsedMilliseconds - frameStartMs);
                    int waitMs = Math.Max(16, delayMs - elapsed);
                    if (waitMs > 0) _workerWake.WaitOne(waitMs);
                }
            } catch (Exception ex) {
                if (Interlocked.Read(ref _workerGen) == myGen) {
                    _lastError = ex.Message;
                }
            } finally {
                if (mp4 != null) mp4.Dispose();
                if (gif != null) gif.Dispose();
            }
        }

        private void BuildLayerBitmaps(Bitmap src, bool highQuality, bool updateLastSource, out Bitmap rawBmp, out Bitmap panelBmp, out Bitmap navBmp) {
            rawBmp = null; panelBmp = null; navBmp = null;
            if (src == null) return;
            if (updateLastSource) {
                Bitmap frameCopy = new Bitmap(src.Width, src.Height, PixelFormat.Format32bppRgb);
                using (Graphics gc = Graphics.FromImage(frameCopy)) {
                    gc.CompositingMode = CompositingMode.SourceCopy;
                    gc.DrawImage(src, 0, 0, src.Width, src.Height);
                }
                Bitmap oldSrc;
                lock (_srcLock) {
                    oldSrc = _lastSourceFrame;
                    _lastSourceFrame = frameCopy;
                }
                if (oldSrc != null) oldSrc.Dispose();
            }

            int w = Math.Max(320, _targetW);
            int h = Math.Max(240, _targetH);

            double scale = Math.Max((double)w / Math.Max(1, src.Width), (double)h / Math.Max(1, src.Height));
            int drawW = Math.Max(w, (int)Math.Ceiling(src.Width * scale));
            int drawH = Math.Max(h, (int)Math.Ceiling(src.Height * scale));
            int drawX = (w - drawW) / 2;
            int drawY = (h - drawH) / 2;

            int dim = _dimPercent;
            int aRaw = Math.Max(25, Math.Min(145, (int)Math.Round(dim * 1.15)));
            int aPanel = Math.Max(45, Math.Min(218, (int)Math.Round(dim * 2.25)));
            int aNav = Math.Max(65, Math.Min(232, (int)Math.Round((dim + 8) * 2.35)));

            Bitmap baseBmp = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
            rawBmp = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
            panelBmp = new Bitmap(w, h, PixelFormat.Format32bppPArgb);
            navBmp = new Bitmap(w, h, PixelFormat.Format32bppPArgb);

            try {
                using (Graphics g = Graphics.FromImage(baseBmp)) {
                    g.CompositingMode = CompositingMode.SourceCopy;
                    g.InterpolationMode = highQuality ? InterpolationMode.HighQualityBicubic : InterpolationMode.Bilinear;
                    g.PixelOffsetMode = PixelOffsetMode.Half;
                    g.DrawImage(src, drawX, drawY, drawW, drawH);
                }

                using (Graphics g = Graphics.FromImage(rawBmp)) {
                    g.CompositingMode = CompositingMode.SourceCopy;
                    g.DrawImageUnscaled(baseBmp, 0, 0);
                    g.CompositingMode = CompositingMode.SourceOver;
                    using (SolidBrush br = new SolidBrush(Color.FromArgb(aRaw, 8, 12, 24))) {
                        g.FillRectangle(br, 0, 0, w, h);
                    }
                }

                using (Graphics g = Graphics.FromImage(panelBmp)) {
                    g.CompositingMode = CompositingMode.SourceCopy;
                    g.DrawImageUnscaled(baseBmp, 0, 0);
                    g.CompositingMode = CompositingMode.SourceOver;
                    using (SolidBrush br = new SolidBrush(Color.FromArgb(aPanel, 10, 15, 28))) {
                        g.FillRectangle(br, 0, 0, w, h);
                    }
                }

                using (Graphics g = Graphics.FromImage(navBmp)) {
                    g.CompositingMode = CompositingMode.SourceCopy;
                    g.DrawImageUnscaled(baseBmp, 0, 0);
                    g.CompositingMode = CompositingMode.SourceOver;
                    using (SolidBrush br = new SolidBrush(Color.FromArgb(aNav, 8, 13, 25))) {
                        g.FillRectangle(br, 0, 0, w, h);
                    }
                }
            } finally {
                baseBmp.Dispose();
            }
        }

        private void ComposeLayersToPending(Bitmap src, bool highQuality, bool updateLastSource, long myGen) {
            Bitmap rawBmp, panelBmp, navBmp;
            BuildLayerBitmaps(src, highQuality, updateLastSource, out rawBmp, out panelBmp, out navBmp);
            if (rawBmp == null) return;

            if (Interlocked.Read(ref _workerGen) != myGen || !_isActive || _disposed) {
                rawBmp.Dispose();
                panelBmp.Dispose();
                navBmp.Dispose();
                return;
            }

            Bitmap oldRaw = null, oldPanel = null, oldNav = null;
            lock (_pendingLock) {
                if (Interlocked.Read(ref _workerGen) != myGen || !_isActive || _disposed) {
                    oldRaw = rawBmp;
                    oldPanel = panelBmp;
                    oldNav = navBmp;
                } else {
                    oldRaw = _pendingRaw;
                    oldPanel = _pendingPanel;
                    oldNav = _pendingNav;
                    _pendingRaw = rawBmp;
                    _pendingPanel = panelBmp;
                    _pendingNav = navBmp;
                }
            }
            if (oldRaw != null) oldRaw.Dispose();
            if (oldPanel != null) oldPanel.Dispose();
            if (oldNav != null) oldNav.Dispose();
        }

        private void ComposeLayersFromSource(Bitmap src, bool highQuality, bool updateLastSource) {
            Bitmap rawBmp, panelBmp, navBmp;
            BuildLayerBitmaps(src, highQuality, updateLastSource, out rawBmp, out panelBmp, out navBmp);
            if (rawBmp == null) return;
            ClearPendingLayers();

            Bitmap oldRaw, oldPanel, oldNav;
            lock (_frameLock) {
                oldRaw = _layerRaw;
                oldPanel = _layerPanel;
                oldNav = _layerNav;
                _layerRaw = rawBmp;
                _layerPanel = panelBmp;
                _layerNav = navBmp;
            }
            Interlocked.Increment(ref _frameCount);

            if (oldRaw != null) oldRaw.Dispose();
            if (oldPanel != null) oldPanel.Dispose();
            if (oldNav != null) oldNav.Dispose();
        }

        private void ScheduleRepaint() {
            ScheduleRepaint(-1);
        }

        private void ScheduleRepaint(long expectedGen) {
            if (_disposed || _form == null || _form.IsDisposed || !_form.IsHandleCreated) return;
            if (expectedGen >= 0 && Interlocked.Read(ref _workerGen) != expectedGen) return;
            if (Interlocked.CompareExchange(ref _pendingRepaint, 1, 0) == 0) {
                try {
                    _form.BeginInvoke(new MethodInvoker(RefreshVisibleGlassSurfaces));
                } catch {
                    Interlocked.Exchange(ref _pendingRepaint, 0);
                }
            }
        }

        private void RefreshBorderedControls() {
            for (int i = 0; i < _comboHooks.Count; i++) {
                if (_comboHooks[i] != null) _comboHooks[i].RefreshControl();
            }
            for (int i = 0; i < _borderHooks.Count; i++) {
                if (_borderHooks[i] != null) _borderHooks[i].RefreshControl();
            }
            for (int i = 0; i < _listHeaderHooks.Count; i++) {
                if (_listHeaderHooks[i] != null) _listHeaderHooks[i].RefreshControl();
            }
        }

        public void RefreshNow() {
            if (_form == null || _form.IsDisposed || !_form.IsHandleCreated) return;
            if (_form.InvokeRequired) {
                ScheduleRepaint();
                return;
            }
            RefreshVisibleGlassSurfaces();
            RefreshBorderedControls();
            foreach (TabControl tc in _subTabs) {
                if (tc != null && tc.Visible && tc.IsHandleCreated) tc.Invalidate(false);
            }
        }

        private void RefreshVisibleGlassSurfaces() {
            Interlocked.Exchange(ref _pendingRepaint, 0);
            PromotePendingLayers();
            if (_form == null || _form.IsDisposed || !_form.IsHandleCreated) return;
            if (_isActive && _isAnimated && !_isPaused && _showAnimation) {
                long nowMs = _animClock.ElapsedMilliseconds;
                if ((nowMs - _lastParticleMs) >= 32) {
                    int dc;
                    AdvanceParticlesPhysics(out dc);
                }
            }

            _form.Invalidate(false);
            foreach (Control c in _glassContainers) {
                if (c != null && !c.IsDisposed && c.IsHandleCreated && c.Visible) {
                    c.Invalidate(false);
                }
            }
            foreach (Control c in _glassLeaves) {
                if (c != null && !c.IsDisposed && c.IsHandleCreated && c.Visible) {
                    c.Invalidate(false);
                }
            }
        }

        public static void GetBorderColors(int season, out Color c1, out Color c2, out Color c3) {
            switch (season) {
                case 1: // Mua Ha: Vang nang <-> Xanh la ngoc <-> Xanh bien he
                    c1 = Color.FromArgb(250, 204, 21);
                    c2 = Color.FromArgb(74, 222, 128);
                    c3 = Color.FromArgb(56, 189, 248);
                    break;
                case 2: // Mua Thu: Vang ho phach <-> Vang nang <-> Cam la phong
                    c1 = Color.FromArgb(245, 158, 11);
                    c2 = Color.FromArgb(253, 224, 71);
                    c3 = Color.FromArgb(234, 88, 12);
                    break;
                case 3: // Mua Dong: Xanh bang <-> Trang tuyet <-> Xanh duong lanh
                    c1 = Color.FromArgb(56, 189, 248);
                    c2 = Color.FromArgb(224, 242, 254);
                    c3 = Color.FromArgb(59, 130, 246);
                    break;
                case 4: // Hoa Huong Duong: Vang ruc <-> Ho phach <-> Cam mat ong
                    c1 = Color.FromArgb(250, 204, 21);
                    c2 = Color.FromArgb(245, 158, 11);
                    c3 = Color.FromArgb(217, 119, 6);
                    break;
                case 5: // Nguyen to Lua: Do ruc <-> Cam lua <-> Vang ruc
                    c1 = Color.FromArgb(239, 68, 68);
                    c2 = Color.FromArgb(249, 115, 22);
                    c3 = Color.FromArgb(250, 204, 21);
                    break;
                case 6: // Nguyen to Sam Chop: Tim dien <-> Xanh neon <-> Vang tia set
                    c1 = Color.FromArgb(168, 85, 247);
                    c2 = Color.FromArgb(56, 189, 248);
                    c3 = Color.FromArgb(254, 240, 138);
                    break;
                case 7: // Nguyen to Loc Xoay: Ngoc lam <-> Xanh gio <-> Xam bac
                    c1 = Color.FromArgb(45, 212, 191);
                    c2 = Color.FromArgb(167, 243, 208);
                    c3 = Color.FromArgb(148, 163, 184);
                    break;
                case 8: // Nguyen to Song Than: Xanh dai duong <-> Ngoc lam <-> Trang bot song
                    c1 = Color.FromArgb(14, 165, 233);
                    c2 = Color.FromArgb(6, 182, 212);
                    c3 = Color.FromArgb(224, 242, 254);
                    break;
                case 9: // Thien Thach (Meteor): Cam ruc <-> Vang nong chay <-> Tim vu tru
                    c1 = Color.FromArgb(249, 115, 22);
                    c2 = Color.FromArgb(250, 204, 21);
                    c3 = Color.FromArgb(139, 92, 246);
                    break;
                case 10: // Sao Bang (Shooting Star): Cham sao dem <-> Xanh thien ha <-> Vang nhat
                    c1 = Color.FromArgb(99, 102, 241);
                    c2 = Color.FromArgb(125, 211, 252);
                    c3 = Color.FromArgb(254, 240, 138);
                    break;
                case 11: // Gio (Wind): Bac ha nhe <-> Xanh ngoc <-> Xanh da troi
                    c1 = Color.FromArgb(110, 231, 183);
                    c2 = Color.FromArgb(209, 250, 229);
                    c3 = Color.FromArgb(125, 211, 252);
                    break;
                case 12: // Tia Nang (Sunbeams): Vang tia sang <-> Vang ruc ro <-> Ho phach am
                    c1 = Color.FromArgb(254, 240, 138);
                    c2 = Color.FromArgb(250, 204, 21);
                    c3 = Color.FromArgb(245, 158, 11);
                    break;
                case 13: // Mua (Rain): Xanh pha le <-> Suong tim nhe <-> Cham may mua
                    c1 = Color.FromArgb(56, 189, 248);
                    c2 = Color.FromArgb(165, 180, 252);
                    c3 = Color.FromArgb(99, 102, 241);
                    break;
                default: // Mua Xuan: Hoa Anh Dao Sakura (Hong phan <-> Vang kim)
                    c1 = Color.FromArgb(255, 118, 175);
                    c2 = Color.FromArgb(255, 224, 238);
                    c3 = Color.FromArgb(251, 191, 36);
                    break;
            }
        }

