        public static void GetOrnamentColors(int style, out Color warmGold, out Color coolStar) {
            switch (style) {
                case 1: // Amber Gold + Sakura Blush
                    warmGold = Color.FromArgb(255, 142, 190);
                    coolStar = Color.FromArgb(253, 224, 71);
                    break;
                case 2: // Furina Live + Sakura Blush
                    warmGold = Color.FromArgb(255, 132, 186);
                    coolStar = Color.FromArgb(255, 232, 244);
                    break;
                case 3: // Gemini Neon + Sakura Blush
                    warmGold = Color.FromArgb(244, 114, 182);
                    coolStar = Color.FromArgb(245, 208, 254);
                    break;
                case 4: // WLOP Cosmic + Sakura Blush
                    warmGold = Color.FromArgb(255, 135, 188);
                    coolStar = Color.FromArgb(253, 224, 71);
                    break;
                case 5: // Midnight Obsidian + Sakura Blush
                    warmGold = Color.FromArgb(249, 168, 212);
                    coolStar = Color.FromArgb(252, 231, 243);
                    break;
                default: // Hoa Anh Đào Sakura
                    warmGold = Color.FromArgb(255, 128, 182);
                    coolStar = Color.FromArgb(255, 226, 240);
                    break;
            }
        }

        public static void GetOrnamentColorsForMode(int style, bool lightMode, out Color warmGold, out Color coolStar) {
            if (!lightMode) {
                GetOrnamentColors(style, out warmGold, out coolStar);
                return;
            }
            switch (style) {
                case 1:
                    warmGold = Color.FromArgb(244, 102, 162);
                    coolStar = Color.FromArgb(217, 145, 10);
                    break;
                case 2:
                    warmGold = Color.FromArgb(244, 96, 158);
                    coolStar = Color.FromArgb(14, 165, 233);
                    break;
                case 3:
                    warmGold = Color.FromArgb(236, 72, 153);
                    coolStar = Color.FromArgb(168, 85, 247);
                    break;
                case 4:
                    warmGold = Color.FromArgb(244, 98, 160);
                    coolStar = Color.FromArgb(217, 145, 10);
                    break;
                case 5:
                    warmGold = Color.FromArgb(236, 98, 164);
                    coolStar = Color.FromArgb(99, 102, 241);
                    break;
                default:
                    warmGold = Color.FromArgb(244, 92, 156);
                    coolStar = Color.FromArgb(234, 158, 12);
                    break;
            }
        }

        public static void GetSeasonalOrnamentColors(int season, int style, bool lightMode, out Color primaryCol, out Color secondaryCol) {
            switch (season) {
                case 1: // Ha: Nang vang & Hoa huong duong + la xanh
                    primaryCol = lightMode ? Color.FromArgb(234, 158, 12) : Color.FromArgb(250, 204, 21);
                    secondaryCol = lightMode ? Color.FromArgb(22, 163, 74) : Color.FromArgb(56, 189, 248);
                    break;
                case 2: // Thu: La phong vang & cam am
                    primaryCol = lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(251, 191, 36);
                    secondaryCol = lightMode ? Color.FromArgb(234, 88, 12) : Color.FromArgb(249, 115, 22);
                    break;
                case 3: // Dong: Nguoi tuyet & bong tuyet xanh bang
                    primaryCol = lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(125, 211, 252);
                    secondaryCol = lightMode ? Color.FromArgb(56, 189, 248) : Color.FromArgb(224, 242, 254);
                    break;
                case 4: // Hoa Huong Duong: Vang ho phach ruc ro & la xanh
                    primaryCol = lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(250, 204, 21);
                    secondaryCol = lightMode ? Color.FromArgb(22, 163, 74) : Color.FromArgb(254, 240, 138);
                    break;
                case 5: // Nguyen to Lua
                    primaryCol = lightMode ? Color.FromArgb(220, 38, 38) : Color.FromArgb(249, 115, 22);
                    secondaryCol = lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138);
                    break;
                case 6: // Nguyen to Sam Chop
                    primaryCol = lightMode ? Color.FromArgb(124, 58, 237) : Color.FromArgb(56, 189, 248);
                    secondaryCol = lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(254, 240, 138);
                    break;
                case 7: // Nguyen to Loc Xoay
                    primaryCol = lightMode ? Color.FromArgb(13, 148, 136) : Color.FromArgb(45, 212, 191);
                    secondaryCol = lightMode ? Color.FromArgb(71, 85, 105) : Color.FromArgb(167, 243, 208);
                    break;
                case 8: // Nguyen to Song Than
                    primaryCol = lightMode ? Color.FromArgb(3, 105, 161) : Color.FromArgb(14, 165, 233);
                    secondaryCol = lightMode ? Color.FromArgb(8, 145, 178) : Color.FromArgb(224, 242, 254);
                    break;
                case 9: // Thien Thach (Meteor)
                    primaryCol = lightMode ? Color.FromArgb(234, 88, 12) : Color.FromArgb(251, 146, 60);
                    secondaryCol = lightMode ? Color.FromArgb(109, 40, 217) : Color.FromArgb(253, 224, 71);
                    break;
                case 10: // Sao Bang (Shooting Star)
                    primaryCol = lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(125, 211, 252);
                    secondaryCol = lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138);
                    break;
                case 11: // Gio (Wind)
                    primaryCol = lightMode ? Color.FromArgb(13, 148, 136) : Color.FromArgb(167, 243, 208);
                    secondaryCol = lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(186, 230, 253);
                    break;
                case 12: // Tia Nang (Sunbeams)
                    primaryCol = lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(253, 224, 71);
                    secondaryCol = lightMode ? Color.FromArgb(234, 88, 12) : Color.FromArgb(254, 249, 195);
                    break;
                case 13: // Mua (Rain)
                    primaryCol = lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(56, 189, 248);
                    secondaryCol = lightMode ? Color.FromArgb(79, 70, 229) : Color.FromArgb(199, 210, 254);
                    break;
                default: // Xuan: Hoa Anh Dao
                    GetOrnamentColorsForMode(style, lightMode, out primaryCol, out secondaryCol);
                    break;
            }
        }

        public static void DrawFourPointStar(Graphics g, float cx, float cy, float r, Color col, int alpha) {
            DrawFourPointStar(g, cx, cy, r, col, alpha, false);
        }

        public static void DrawFourPointStar(Graphics g, float cx, float cy, float r, Color col, int alpha, bool lightBg) {
            if (r < 0.8f || alpha <= 3) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float gr = Math.Max(1.4f, r * 1.35f);
            using (SolidBrush halo = new SolidBrush(Color.FromArgb(Math.Max(2, lightBg ? (a / 4) : (a / 3)), col))) {
                g.FillEllipse(halo, cx - gr * 0.55f, cy - gr * 0.55f, gr * 1.1f, gr * 1.1f);
            }
            float w = Math.Max(0.45f, r * 0.24f);
            PointF[] pts = new PointF[] {
                new PointF(cx, cy - r),
                new PointF(cx + w, cy - w),
                new PointF(cx + r, cy),
                new PointF(cx + w, cy + w),
                new PointF(cx, cy + r),
                new PointF(cx - w, cy + w),
                new PointF(cx - r, cy),
                new PointF(cx - w, cy - w)
            };
            Color polyCol = lightBg ? DarkenColor(col, 0.10f) : BlendWithWhite(col, 0.35f);
            using (SolidBrush br = new SolidBrush(Color.FromArgb(a, polyCol))) {
                g.FillPolygon(br, pts);
            }
            if (r >= 2.3f) {
                int coreA = Math.Max(0, Math.Min(255, (int)(a * 0.92f)));
                Color coreCol = lightBg ? Color.FromArgb(coreA, 255, 248, 220) : Color.FromArgb(coreA, Color.White);
                using (SolidBrush core = new SolidBrush(coreCol)) {
                    g.FillEllipse(core, cx - 0.8f, cy - 0.8f, 1.6f, 1.6f);
                }
            }
        }

        public static void DrawSakuraFlower(Graphics g, float cx, float cy, float radius, float rotDeg, Color petalOuter, Color petalInner, Color centerTint, int alpha) {
            DrawSakuraFlower(g, cx, cy, radius, rotDeg, petalOuter, petalInner, centerTint, alpha, false);
        }

        public static void DrawSakuraFlower(Graphics g, float cx, float cy, float radius, float rotDeg, Color petalOuter, Color petalInner, Color centerTint, int alpha, bool lightBg) {
            if (radius < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                int haloA = Math.Max(2, lightBg ? (a / 7) : (a / 5));
                using (SolidBrush halo = new SolidBrush(Color.FromArgb(haloA, petalOuter))) {
                    g.FillEllipse(halo, -r * 1.18f, -r * 1.18f, r * 2.36f, r * 2.36f);
                }

                Color effTip = petalInner;
                if (lightBg) {
                    double tipLuma = 0.299 * petalInner.R + 0.587 * petalInner.G + 0.114 * petalInner.B;
                    if (tipLuma > 235.0) effTip = Color.FromArgb(255, 224, 238);
                }
                Color pBase = Color.FromArgb(a, petalOuter);
                Color pTip = Color.FromArgb(Math.Min(255, a + 15), effTip);
                Color pEdge = lightBg
                    ? Color.FromArgb((int)(a * 0.78f), DarkenColor(petalOuter, 0.16f))
                    : Color.FromArgb((int)(a * 0.86f), BlendWithWhite(petalInner, 0.45f));
                float edgeW = Math.Max(0.55f, r * 0.08f);

                for (int k = 0; k < 5; k++) {
                    GraphicsState pGs = g.Save();
                    try {
                        g.RotateTransform(k * 72f);
                        using (GraphicsPath pp = new GraphicsPath()) {
                            pp.AddBezier(0f, -0.07f * r, 0.48f * r, -0.30f * r, 0.62f * r, -0.82f * r, 0.25f * r, -1.00f * r);
                            pp.AddLine(0.25f * r, -1.00f * r, 0f, -0.82f * r);
                            pp.AddLine(0f, -0.82f * r, -0.25f * r, -1.00f * r);
                            pp.AddBezier(-0.25f * r, -1.00f * r, -0.62f * r, -0.82f * r, -0.48f * r, -0.30f * r, 0f, -0.07f * r);
                            pp.CloseFigure();

                            using (LinearGradientBrush pBr = new LinearGradientBrush(new PointF(0f, -0.05f * r), new PointF(0f, -1.04f * r), pBase, pTip)) {
                                g.FillPath(pBr, pp);
                            }
                            using (Pen pPen = new Pen(pEdge, edgeW)) {
                                g.DrawPath(pPen, pp);
                            }
                        }
                        if (r >= 4.5f) {
                            using (Pen vein = new Pen(Color.FromArgb((int)(a * 0.45f), centerTint), Math.Max(0.5f, r * 0.06f))) {
                                vein.StartCap = LineCap.Round;
                                vein.EndCap = LineCap.Round;
                                g.DrawLine(vein, 0f, -0.18f * r, 0f, -0.58f * r);
                            }
                        }
                    } finally {
                        g.Restore(pGs);
                    }
                }

                float cR = r * 0.28f;
                using (SolidBrush cBr = new SolidBrush(Color.FromArgb(a, centerTint))) {
                    g.FillEllipse(cBr, -cR, -cR, cR * 2f, cR * 2f);
                }

                if (r >= 3.2f) {
                    Color pollenCol = lightBg ? Color.FromArgb(a, 217, 136, 12) : Color.FromArgb(a, 253, 224, 71);
                    Color stLineCol = lightBg ? Color.FromArgb((int)(a * 0.88f), 234, 162, 10) : Color.FromArgb((int)(a * 0.85f), 254, 240, 138);
                    float dotD = Math.Max(1.0f, r * 0.14f);
                    using (Pen stPen = new Pen(stLineCol, Math.Max(0.55f, r * 0.06f)))
                    using (SolidBrush stDot = new SolidBrush(pollenCol)) {
                        for (int s = 0; s < 5; s++) {
                            double ang = (s * 72.0 + 36.0) * Math.PI / 180.0;
                            float cosA = (float)Math.Cos(ang);
                            float sinA = (float)Math.Sin(ang);
                            float r1 = r * 0.12f;
                            float r2 = r * 0.36f;
                            g.DrawLine(stPen, cosA * r1, sinA * r1, cosA * r2, sinA * r2);
                            g.FillEllipse(stDot, cosA * r2 - dotD * 0.5f, sinA * r2 - dotD * 0.5f, dotD, dotD);
                        }
                    }
                }

                float coreR = Math.Max(0.75f, r * 0.13f);
                Color coreCol = lightBg ? Color.FromArgb(Math.Min(255, a + 15), 253, 210, 72) : Color.FromArgb(Math.Min(255, a + 15), 254, 249, 195);
                using (SolidBrush coreBr = new SolidBrush(coreCol)) {
                    g.FillEllipse(coreBr, -coreR, -coreR, coreR * 2f, coreR * 2f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSakuraPetal(Graphics g, float cx, float cy, float size, float rotDeg, Color petalCol, int alpha) {
            DrawSakuraPetal(g, cx, cy, size, rotDeg, petalCol, alpha, false);
        }

        public static void DrawSakuraPetal(Graphics g, float cx, float cy, float size, float rotDeg, Color petalCol, int alpha, bool lightBg) {
            if (size < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size;
            float w = size * 0.65f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (GraphicsPath pp = new GraphicsPath()) {
                    pp.AddBezier(0f, 0.48f * h, 0.50f * w, 0.22f * h, 0.58f * w, -0.32f * h, 0.22f * w, -0.48f * h);
                    pp.AddLine(0.22f * w, -0.48f * h, 0f, -0.32f * h);
                    pp.AddLine(0f, -0.32f * h, -0.22f * w, -0.48f * h);
                    pp.AddBezier(-0.22f * w, -0.48f * h, -0.58f * w, -0.32f * h, -0.50f * w, 0.22f * h, 0f, 0.48f * h);
                    pp.CloseFigure();

                    Color topC = Color.FromArgb(Math.Min(255, a + 10), BlendWithWhite(petalCol, lightBg ? 0.42f : 0.72f));
                    using (LinearGradientBrush pBr = new LinearGradientBrush(new PointF(0f, 0.50f * h), new PointF(0f, -0.50f * h), Color.FromArgb(a, petalCol), topC)) {
                        g.FillPath(pBr, pp);
                    }
                    Color rimCol = lightBg ? DarkenColor(petalCol, 0.18f) : BlendWithWhite(petalCol, 0.85f);
                    using (Pen pRim = new Pen(Color.FromArgb((int)(a * 0.78f), rimCol), 0.7f)) {
                        g.DrawPath(pRim, pp);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSakuraBud(Graphics g, float cx, float cy, float size, float rotDeg, int alpha) {
            DrawSakuraBud(g, cx, cy, size, rotDeg, alpha, false);
        }

        public static void DrawSakuraBud(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.2f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size;
            float w = size * 0.58f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (GraphicsPath bp = new GraphicsPath()) {
                    bp.AddBezier(0f, 0.46f * h, 0.48f * w, 0.24f * h, 0.52f * w, -0.20f * h, 0f, -0.48f * h);
                    bp.AddBezier(0f, -0.48f * h, -0.52f * w, -0.20f * h, -0.48f * w, 0.24f * h, 0f, 0.46f * h);
                    bp.CloseFigure();

                    Color cBot = lightBg ? Color.FromArgb(a, 244, 78, 148) : Color.FromArgb(a, 255, 107, 169);
                    Color cTop = lightBg ? Color.FromArgb(a, 255, 188, 218) : Color.FromArgb(a, 255, 209, 230);
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.48f * h), new PointF(0f, -0.50f * h), cBot, cTop)) {
                        g.FillPath(br, bp);
                    }
                    Color rimC = lightBg ? Color.FromArgb((int)(a * 0.85f), 219, 54, 122) : Color.FromArgb((int)(a * 0.78f), 255, 228, 242);
                    using (Pen rim = new Pen(rimC, 0.7f)) {
                        g.DrawPath(rim, bp);
                    }
                }
                using (SolidBrush calyx = new SolidBrush(Color.FromArgb(a, 112, 34, 68))) {
                    g.FillEllipse(calyx, -0.34f * w, 0.22f * h, 0.68f * w, 0.28f * h);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSakuraBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact) {
            DrawSakuraBranchCorner(g, anchorX, anchorY, scale, flipX, flipY, phase, alpha, compact, false);
        }

        public static void DrawSakuraBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float swayRot = (float)Math.Sin(phase * 1.1) * 3.5f;
            float tw1 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5);
            float tw2 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5 + 1.9);
            float driftX = (float)Math.Sin(phase * 0.95) * 2.2f;
            float driftY = (float)Math.Cos(phase * 0.85) * 1.5f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                // Dark cherry-wood twig + soft rose-gold highlight
                using (Pen woodPen = new Pen(Color.FromArgb((int)(a * 0.92f), 94, 40, 66), 2.3f)) {
                    woodPen.StartCap = LineCap.Round;
                    woodPen.EndCap = LineCap.Round;
                    g.DrawBezier(woodPen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(woodPen, -56f, 2f, -66f, 9f, -74f, 13f, -82f, 16f);
                    if (!compact) {
                        g.DrawBezier(woodPen, -22f, 4f, -11f, 3f, -3f, 5f, 3f, 12f);
                    }
                }
                Color woodHiCol = lightBg ? Color.FromArgb((int)(a * 0.72f), 236, 122, 178) : Color.FromArgb((int)(a * 0.70f), 249, 168, 212);
                using (Pen woodHi = new Pen(woodHiCol, 0.9f)) {
                    woodHi.StartCap = LineCap.Round;
                    woodHi.EndCap = LineCap.Round;
                    g.DrawBezier(woodHi, -104f, -2.6f, -59f, 5.2f, -21f, -1.8f, 1f, 22f);
                }

                // Flanking twinkling sparkles
                DrawFourPointStar(g, -94f, -4f, 2.7f * tw1, lightBg ? Color.FromArgb(236, 72, 153) : Color.FromArgb(255, 196, 224), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.4f * tw2, lightBg ? Color.FromArgb(234, 162, 10) : Color.FromArgb(253, 224, 71), (int)(a * tw2), lightBg);

                // Buds along shoot tips
                DrawSakuraBud(g, -64f, 11f, 5.6f, 126f + swayRot, a, lightBg);
                DrawSakuraBud(g, 1f, 32f, 5.2f, 160f - swayRot, a, lightBg);

                // Detaching & drifting sakura petals
                DrawSakuraPetal(g, -96f + driftX, 8f + driftY, 6.2f, -42f + (float)Math.Sin(phase) * 14f, lightBg ? Color.FromArgb(244, 108, 166) : Color.FromArgb(255, 145, 192), (int)(a * 0.94f), lightBg);
                DrawSakuraPetal(g, -54f - driftX * 0.7f, 17f + driftY * 1.1f, 5.5f, 36f + (float)Math.Cos(phase) * 16f, lightBg ? Color.FromArgb(248, 126, 180) : Color.FromArgb(255, 166, 206), (int)(a * 0.90f), lightBg);
                if (!compact) {
                    DrawSakuraPetal(g, -15f + driftX * 0.5f, 33f + driftY * 0.8f, 5.3f, 68f + swayRot * 2f, Color.FromArgb(244, 114, 182), (int)(a * 0.88f), lightBg);
                }

                // Lush 5-petal sakura blossoms layered on top
                Color p1Out = Color.FromArgb(255, 118, 175);
                Color p1In  = Color.FromArgb(255, 240, 246);
                Color c1Mid = Color.FromArgb(219, 39, 119);
                Color p2Out = Color.FromArgb(255, 148, 198);
                Color p2In  = Color.FromArgb(255, 255, 255);
                Color c2Mid = Color.FromArgb(225, 29, 72);

                DrawSakuraFlower(g, -42f, -1f, 8.2f, 18f - swayRot, p2Out, p2In, c2Mid, a, lightBg);
                if (!compact) {
                    DrawSakuraFlower(g, -76f, 2f, 5.8f, -24f + swayRot, p1Out, p1In, c1Mid, a, lightBg);
                    DrawSakuraFlower(g, -3f, 20f, 7.3f, 28f + swayRot, p2Out, p2In, c1Mid, a, lightBg);
                }
                DrawSakuraFlower(g, -18f, 4f, 10.2f, -12f + swayRot, p1Out, p1In, c1Mid, Math.Min(255, a + 10), lightBg);
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSunflower(Graphics g, float cx, float cy, float radius, float rotDeg, int alpha, bool lightBg) {
            if (radius < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                int haloA = Math.Max(2, lightBg ? (a / 7) : (a / 5));
                using (SolidBrush halo = new SolidBrush(Color.FromArgb(haloA, 250, 204, 21))) {
                    g.FillEllipse(halo, -r * 1.22f, -r * 1.22f, r * 2.44f, r * 2.44f);
                }

                Color pBase = lightBg ? Color.FromArgb(a, 234, 118, 12) : Color.FromArgb(a, 245, 158, 11);
                Color pTip  = lightBg ? Color.FromArgb(Math.Min(255, a + 15), 253, 224, 71) : Color.FromArgb(Math.Min(255, a + 15), 254, 240, 138);
                Color pEdge = lightBg ? Color.FromArgb((int)(a * 0.78f), 180, 83, 9) : Color.FromArgb((int)(a * 0.80f), 254, 249, 195);
                float edgeW = Math.Max(0.5f, r * 0.07f);

                for (int k = 0; k < 10; k++) {
                    GraphicsState pGs = g.Save();
                    try {
                        g.RotateTransform(k * 36f);
                        using (GraphicsPath pp = new GraphicsPath()) {
                            pp.AddBezier(0f, -0.22f * r, 0.25f * r, -0.46f * r, 0.24f * r, -0.82f * r, 0f, -1.00f * r);
                            pp.AddBezier(0f, -1.00f * r, -0.24f * r, -0.82f * r, -0.25f * r, -0.46f * r, 0f, -0.22f * r);
                            pp.CloseFigure();
                            using (LinearGradientBrush pBr = new LinearGradientBrush(new PointF(0f, -0.20f * r), new PointF(0f, -1.04f * r), pBase, pTip)) {
                                g.FillPath(pBr, pp);
                            }
                            using (Pen pPen = new Pen(pEdge, edgeW)) {
                                g.DrawPath(pPen, pp);
                            }
                        }
                    } finally {
                        g.Restore(pGs);
                    }
                }

                if (r >= 5.5f) {
                    Color p2Base = lightBg ? Color.FromArgb(a, 245, 158, 11) : Color.FromArgb(a, 250, 204, 21);
                    Color p2Tip  = Color.FromArgb(Math.Min(255, a + 10), 254, 240, 138);
                    for (int k = 0; k < 10; k++) {
                        GraphicsState pGs = g.Save();
                        try {
                            g.RotateTransform(k * 36f + 18f);
                            using (GraphicsPath pp = new GraphicsPath()) {
                                pp.AddBezier(0f, -0.22f * r, 0.19f * r, -0.44f * r, 0.18f * r, -0.72f * r, 0f, -0.84f * r);
                                pp.AddBezier(0f, -0.84f * r, -0.18f * r, -0.72f * r, -0.19f * r, -0.44f * r, 0f, -0.22f * r);
                                pp.CloseFigure();
                                using (LinearGradientBrush pBr = new LinearGradientBrush(new PointF(0f, -0.20f * r), new PointF(0f, -0.86f * r), p2Base, p2Tip)) {
                                    g.FillPath(pBr, pp);
                                }
                            }
                        } finally {
                            g.Restore(pGs);
                        }
                    }
                }

                float cR = r * 0.40f;
                using (SolidBrush cBr = new SolidBrush(Color.FromArgb(a, 120, 53, 15))) {
                    g.FillEllipse(cBr, -cR, -cR, cR * 2f, cR * 2f);
                }
                using (Pen cRim = new Pen(Color.FromArgb((int)(a * 0.88f), lightBg ? 180 : 245, lightBg ? 83 : 158, 11), Math.Max(0.6f, r * 0.08f))) {
                    g.DrawEllipse(cRim, -cR, -cR, cR * 2f, cR * 2f);
                }
                if (r >= 4.0f) {
                    float dSz = Math.Max(0.9f, r * 0.11f);
                    using (SolidBrush seedBr = new SolidBrush(Color.FromArgb((int)(a * 0.90f), 251, 191, 36))) {
                        for (int s = 0; s < 6; s++) {
                            double ang = s * Math.PI / 3.0;
                            float sx = (float)Math.Cos(ang) * (cR * 0.56f);
                            float sy = (float)Math.Sin(ang) * (cR * 0.56f);
                            g.FillEllipse(seedBr, sx - dSz * 0.5f, sy - dSz * 0.5f, dSz, dSz);
                        }
                        g.FillEllipse(seedBr, -dSz * 0.5f, -dSz * 0.5f, dSz, dSz);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSunflowerPetal(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size * 1.12f;
            float w = size * 0.44f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (GraphicsPath pp = new GraphicsPath()) {
                    pp.AddBezier(0f, 0.46f * h, 0.62f * w, 0.18f * h, 0.58f * w, -0.26f * h, 0f, -0.52f * h);
                    pp.AddBezier(0f, -0.52f * h, -0.58f * w, -0.26f * h, -0.62f * w, 0.18f * h, 0f, 0.46f * h);
                    pp.CloseFigure();

                    Color cBot = lightBg ? Color.FromArgb(a, 217, 119, 6) : Color.FromArgb(a, 245, 158, 11);
                    Color cTop = lightBg ? Color.FromArgb(Math.Min(255, a + 12), 253, 224, 71) : Color.FromArgb(Math.Min(255, a + 12), 254, 249, 195);
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.48f * h), new PointF(0f, -0.54f * h), cBot, cTop)) {
                        g.FillPath(br, pp);
                    }
                    Color rimCol = lightBg ? Color.FromArgb((int)(a * 0.80f), 180, 83, 9) : Color.FromArgb((int)(a * 0.82f), 254, 240, 138);
                    using (Pen rim = new Pen(rimCol, 0.65f)) {
                        g.DrawPath(rim, pp);
                    }
                }
                if (size >= 4.0f) {
                    using (Pen vein = new Pen(lightBg ? Color.FromArgb((int)(a * 0.48f), 180, 83, 9) : Color.FromArgb((int)(a * 0.55f), 254, 240, 138), 0.55f)) {
                        vein.StartCap = LineCap.Round;
                        vein.EndCap = LineCap.Round;
                        g.DrawLine(vein, 0f, 0.34f * h, 0f, -0.28f * h);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSunflowerBud(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.2f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size;
            float w = size * 0.62f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (GraphicsPath bp = new GraphicsPath()) {
                    bp.AddBezier(0f, 0.44f * h, 0.52f * w, 0.20f * h, 0.48f * w, -0.22f * h, 0f, -0.50f * h);
                    bp.AddBezier(0f, -0.50f * h, -0.48f * w, -0.22f * h, -0.52f * w, 0.20f * h, 0f, 0.44f * h);
                    bp.CloseFigure();

                    Color cBot = lightBg ? Color.FromArgb(a, 234, 118, 12) : Color.FromArgb(a, 245, 158, 11);
                    Color cTop = lightBg ? Color.FromArgb(a, 253, 224, 71) : Color.FromArgb(a, 254, 240, 138);
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.46f * h), new PointF(0f, -0.52f * h), cBot, cTop)) {
                        g.FillPath(br, bp);
                    }
                    using (Pen rim = new Pen(lightBg ? Color.FromArgb((int)(a * 0.78f), 180, 83, 9) : Color.FromArgb((int)(a * 0.80f), 254, 249, 195), 0.65f)) {
                        g.DrawPath(rim, bp);
                    }
                }
                using (GraphicsPath calyx = new GraphicsPath()) {
                    calyx.AddBezier(-0.56f * w, 0.08f * h, -0.34f * w, 0.54f * h, 0.34f * w, 0.54f * h, 0.56f * w, 0.08f * h);
                    calyx.AddLine(0.56f * w, 0.08f * h, 0.16f * w, 0.18f * h);
                    calyx.AddLine(0.16f * w, 0.18f * h, 0f, -0.02f * h);
                    calyx.AddLine(0f, -0.02f * h, -0.16f * w, 0.18f * h);
                    calyx.CloseFigure();
                    using (SolidBrush cBr = new SolidBrush(Color.FromArgb(a, 21, 128, 61))) {
                        g.FillPath(cBr, calyx);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSunflowerBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float swayRot = (float)Math.Sin(phase * 1.1) * 3.5f;
            float tw1 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5);
            float tw2 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5 + 1.9);
            float driftX = (float)Math.Sin(phase * 0.95) * 2.2f;
            float driftY = (float)Math.Cos(phase * 0.85) * 1.5f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                using (Pen vinePen = new Pen(Color.FromArgb((int)(a * 0.92f), 21, 128, 61), 2.3f)) {
                    vinePen.StartCap = LineCap.Round;
                    vinePen.EndCap = LineCap.Round;
                    g.DrawBezier(vinePen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(vinePen, -56f, 2f, -66f, 9f, -74f, 13f, -82f, 16f);
                    if (!compact) {
                        g.DrawBezier(vinePen, -22f, 4f, -11f, 3f, -3f, 5f, 3f, 12f);
                    }
                }
                Color vineHiCol = lightBg ? Color.FromArgb((int)(a * 0.78f), 74, 222, 128) : Color.FromArgb((int)(a * 0.75f), 134, 239, 172);
                using (Pen vineHi = new Pen(vineHiCol, 0.9f)) {
                    vineHi.StartCap = LineCap.Round;
                    vineHi.EndCap = LineCap.Round;
                    g.DrawBezier(vineHi, -104f, -2.6f, -59f, 5.2f, -21f, -1.8f, 1f, 22f);
                }

                DrawFourPointStar(g, -94f, -4f, 2.7f * tw1, lightBg ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.5f * tw2, lightBg ? Color.FromArgb(234, 158, 12) : Color.FromArgb(253, 224, 71), (int)(a * tw2), lightBg);

                DrawSummerLeaf(g, -64f, 11f, 5.8f, 124f + swayRot, a, lightBg);
                DrawSummerLeaf(g, 1f, 31f, 5.4f, 158f - swayRot, a, lightBg);
                DrawSunflowerBud(g, -82f, 16f, 5.2f, 145f + swayRot, a, lightBg);
                DrawSunflowerPetal(g, -96f + driftX, 8f + driftY, 5.8f, -38f + (float)Math.Sin(phase) * 14f, (int)(a * 0.94f), lightBg);
                DrawSunflowerPetal(g, -54f - driftX * 0.7f, 17f + driftY * 1.1f, 5.4f, 40f + (float)Math.Cos(phase) * 14f, (int)(a * 0.90f), lightBg);

                if (!compact) {
                    DrawSunflowerPetal(g, -15f + driftX * 0.5f, 33f + driftY * 0.8f, 5.2f, 28f, (int)(a * 0.88f), lightBg);
                    DrawSunflower(g, -74f, 4f, 7.6f, -20f + swayRot, a, lightBg);
                    DrawSunflower(g, -3f, 20f, 7.2f, 24f - swayRot, a, lightBg);
                }
                DrawSunflower(g, -42f, -1f, 8.6f, 16f - swayRot, a, lightBg);
                DrawSunflower(g, -18f, 4f, 10.8f, -10f + swayRot, Math.Min(255, a + 10), lightBg);
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawFireFlame(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size * 1.25f;
            float w = size * 0.78f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (SolidBrush halo = new SolidBrush(Color.FromArgb(Math.Max(3, a / 4), 249, 115, 22))) {
                    g.FillEllipse(halo, -w * 0.95f, -h * 0.65f, w * 1.9f, h * 1.3f);
                }

                using (GraphicsPath fp = new GraphicsPath()) {
                    fp.AddBezier(0f, 0.48f * h, 0.72f * w, 0.34f * h, 0.56f * w, -0.14f * h, 0.12f * w, -0.56f * h);
                    fp.AddBezier(0.12f * w, -0.56f * h, -0.04f * w, -0.26f * h, -0.18f * w, -0.34f * h, -0.26f * w, -0.12f * h);
                    fp.AddBezier(-0.26f * w, -0.12f * h, -0.66f * w, 0.08f * h, -0.58f * w, 0.42f * h, 0f, 0.48f * h);
                    fp.CloseFigure();

                    Color cBot = lightBg ? Color.FromArgb(a, 185, 28, 28) : Color.FromArgb(a, 239, 68, 68);
                    Color cTop = lightBg ? Color.FromArgb(Math.Min(255, a + 10), 245, 158, 11) : Color.FromArgb(Math.Min(255, a + 10), 253, 224, 71);
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.50f * h), new PointF(0f, -0.58f * h), cBot, cTop)) {
                        g.FillPath(br, fp);
                    }
                    Color rimCol = lightBg ? Color.FromArgb((int)(a * 0.78f), 153, 27, 27) : Color.FromArgb((int)(a * 0.80f), 254, 240, 138);
                    using (Pen rim = new Pen(rimCol, Math.Max(0.6f, size * 0.07f))) {
                        g.DrawPath(rim, fp);
                    }
                }

                float ih = h * 0.55f;
                float iw = w * 0.46f;
                if (ih >= 2.0f) {
                    using (GraphicsPath core = new GraphicsPath()) {
                        core.AddBezier(0f, 0.42f * h, 0.45f * iw, 0.30f * h, 0.36f * iw, 0.02f * h, 0.04f * iw, 0.42f * h - ih);
                        core.AddBezier(0.04f * iw, 0.42f * h - ih, -0.36f * iw, 0.02f * h, -0.45f * iw, 0.30f * h, 0f, 0.42f * h);
                        core.CloseFigure();
                        Color coreBot = lightBg ? Color.FromArgb(a, 250, 204, 21) : Color.FromArgb(a, 253, 224, 71);
                        Color coreTop = Color.FromArgb(Math.Min(255, a + 15), 254, 249, 195);
                        using (LinearGradientBrush cbr = new LinearGradientBrush(new PointF(0f, 0.44f * h), new PointF(0f, 0.40f * h - ih), coreBot, coreTop)) {
                            g.FillPath(cbr, core);
                        }
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawFireEmber(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.6f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size;
            float w = size * 0.54f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (SolidBrush halo = new SolidBrush(Color.FromArgb(Math.Max(3, a / 3), 249, 115, 22))) {
                    g.FillEllipse(halo, -size * 0.7f, -size * 0.7f, size * 1.4f, size * 1.4f);
                }
                using (GraphicsPath ep = new GraphicsPath()) {
                    ep.AddBezier(0f, 0.45f * h, 0.55f * w, 0.22f * h, 0.48f * w, -0.22f * h, 0f, -0.50f * h);
                    ep.AddBezier(0f, -0.50f * h, -0.48f * w, -0.22f * h, -0.55f * w, 0.22f * h, 0f, 0.45f * h);
                    ep.CloseFigure();
                    Color eb = lightBg ? Color.FromArgb(a, 234, 88, 12) : Color.FromArgb(a, 249, 115, 22);
                    Color et = Color.FromArgb(Math.Min(255, a + 12), 254, 240, 138);
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.47f * h), new PointF(0f, -0.52f * h), eb, et)) {
                        g.FillPath(br, ep);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawFireBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float sway = (float)Math.Sin(phase * 2.1) * 6.5f;
            float tw1 = 0.72f + 0.28f * (float)Math.Sin(phase * 2.4);
            float tw2 = 0.72f + 0.28f * (float)Math.Sin(phase * 2.4 + 1.8);
            float liftX = (float)Math.Sin(phase * 1.4) * 2.2f;
            float liftY = (float)Math.Cos(phase * 1.5) * 1.8f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                Color arcGlow = Color.FromArgb((int)(a * 0.42f), 239, 68, 68);
                Color arcCore = lightBg ? Color.FromArgb((int)(a * 0.92f), 220, 38, 38) : Color.FromArgb((int)(a * 0.92f), 249, 115, 22);
                Color arcHi   = lightBg ? Color.FromArgb((int)(a * 0.85f), 250, 204, 21) : Color.FromArgb((int)(a * 0.85f), 254, 240, 138);
                using (Pen gPen = new Pen(arcGlow, 4.4f))
                using (Pen cPen = new Pen(arcCore, 2.2f))
                using (Pen hPen = new Pen(arcHi, 0.95f)) {
                    gPen.StartCap = LineCap.Round; gPen.EndCap = LineCap.Round;
                    cPen.StartCap = LineCap.Round; cPen.EndCap = LineCap.Round;
                    hPen.StartCap = LineCap.Round; hPen.EndCap = LineCap.Round;
                    g.DrawBezier(gPen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(cPen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(cPen, -56f, 2f, -66f, 9f, -74f, 13f, -82f, 16f);
                    g.DrawBezier(hPen, -104f, -2.5f, -59f, 5.2f, -21f, -1.7f, 1f, 22f);
                    if (!compact) {
                        g.DrawBezier(cPen, -22f, 4f, -11f, 3f, -3f, 5f, 3f, 12f);
                    }
                }

                DrawFourPointStar(g, -94f, -4f, 2.7f * tw1, lightBg ? Color.FromArgb(220, 38, 38) : Color.FromArgb(254, 240, 138), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.5f * tw2, lightBg ? Color.FromArgb(234, 88, 12) : Color.FromArgb(253, 224, 71), (int)(a * tw2), lightBg);

                DrawFireEmber(g, -64f, 11f, 5.6f, 20f + sway, a, lightBg);
                DrawFireEmber(g, -96f + liftX, 8f + liftY, 5.8f, -22f - sway, (int)(a * 0.94f), lightBg);
                DrawFireEmber(g, -54f - liftX * 0.7f, 17f + liftY, 5.2f, 30f + sway, (int)(a * 0.90f), lightBg);
                DrawFireEmber(g, 1f, 31f, 5.2f, 15f - sway, a, lightBg);

                if (!compact) {
                    DrawFireFlame(g, -74f, 3f, 7.6f, -14f + sway, a, lightBg);
                    DrawFireFlame(g, -3f, 19f, 7.2f, 18f - sway, a, lightBg);
                }
                DrawFireFlame(g, -42f, -1f, 8.6f, 10f - sway * 0.8f, a, lightBg);
                DrawFireFlame(g, -18f, 4f, 10.6f, -12f + sway * 0.8f, Math.Min(255, a + 10), lightBg);
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawLightningBoltIcon(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.2f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size * 1.32f;
            float w = size * 0.84f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                PointF[] pts = new PointF[] {
                    new PointF(0.14f * w, -0.54f * h),
                    new PointF(-0.44f * w, 0.04f * h),
                    new PointF(-0.04f * w, 0.04f * h),
                    new PointF(-0.22f * w, 0.54f * h),
                    new PointF(0.44f * w, -0.06f * h),
                    new PointF(0.05f * w, -0.06f * h)
                };

                Color glowCol = lightBg ? Color.FromArgb((int)(a * 0.34f), 124, 58, 237) : Color.FromArgb((int)(a * 0.42f), 56, 189, 248);
                using (Pen glowPen = new Pen(glowCol, Math.Max(1.6f, size * 0.34f))) {
                    glowPen.LineJoin = LineJoin.Round;
                    g.DrawPolygon(glowPen, pts);
                }

                Color cTop = lightBg ? Color.FromArgb(a, 124, 58, 237) : Color.FromArgb(a, 56, 189, 248);
                Color cBot = lightBg ? Color.FromArgb(a, 245, 158, 11) : Color.FromArgb(a, 254, 249, 195);
                using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, -0.56f * h), new PointF(0f, 0.56f * h), cTop, cBot)) {
                    g.FillPolygon(br, pts);
                }
                Color rimCol = lightBg ? Color.FromArgb((int)(a * 0.90f), 49, 46, 129) : Color.FromArgb((int)(a * 0.92f), 255, 255, 255);
                using (Pen rim = new Pen(rimCol, Math.Max(0.65f, size * 0.08f))) {
                    rim.LineJoin = LineJoin.Round;
                    g.DrawPolygon(rim, pts);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawLightningSpark(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                Color arcCol = lightBg ? Color.FromArgb(a, 79, 70, 229) : Color.FromArgb(a, 125, 211, 252);
                Color coreCol = lightBg ? Color.FromArgb(a, 217, 119, 6) : Color.FromArgb(a, 254, 249, 195);
                using (Pen pGlow = new Pen(Color.FromArgb((int)(a * 0.38f), lightBg ? 124 : 168, lightBg ? 58 : 85, lightBg ? 237 : 247), Math.Max(1.8f, r * 0.34f)))
                using (Pen pCore = new Pen(arcCol, Math.Max(0.8f, r * 0.16f))) {
                    pGlow.StartCap = LineCap.Round; pGlow.EndCap = LineCap.Round; pGlow.LineJoin = LineJoin.Round;
                    pCore.StartCap = LineCap.Round; pCore.EndCap = LineCap.Round; pCore.LineJoin = LineJoin.Round;
                    for (int k = 0; k < 3; k++) {
                        GraphicsState sgs = g.Save();
                        try {
                            g.RotateTransform(k * 120f);
                            PointF[] arc = new PointF[] {
                                new PointF(0f, 0f),
                                new PointF(0.24f * r, -0.42f * r),
                                new PointF(-0.14f * r, -0.68f * r),
                                new PointF(0.10f * r, -1.0f * r)
                            };
                            g.DrawLines(pGlow, arc);
                            g.DrawLines(pCore, arc);
                        } finally {
                            g.Restore(sgs);
                        }
                    }
                }
                using (SolidBrush node = new SolidBrush(coreCol)) {
                    float d = Math.Max(1.6f, r * 0.34f);
                    g.FillEllipse(node, -d * 0.5f, -d * 0.5f, d, d);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawLightningBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float flicker = 0.72f + 0.28f * (float)Math.Sin(phase * 3.4);
            float rotWobble = (float)Math.Sin(phase * 2.2) * 5.0f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                PointF[] zigPts = new PointF[] {
                    new PointF(-106f, -2f),
                    new PointF(-80f, 5f),
                    new PointF(-60f, -3f),
                    new PointF(-36f, 7f),
                    new PointF(-14f, 2f),
                    new PointF(3f, 22f)
                };
                Color gCol = lightBg ? Color.FromArgb((int)(a * 0.36f * flicker), 124, 58, 237) : Color.FromArgb((int)(a * 0.48f * flicker), 168, 85, 247);
                Color mCol = lightBg ? Color.FromArgb((int)(a * 0.90f), 2, 132, 199) : Color.FromArgb((int)(a * 0.92f), 56, 189, 248);
                Color cCol = lightBg ? Color.FromArgb((int)(a * 0.92f), 254, 240, 138) : Color.FromArgb((int)(a * 0.95f), 255, 255, 255);
                using (Pen pGlow = new Pen(gCol, 4.6f))
                using (Pen pMid  = new Pen(mCol, 2.0f))
                using (Pen pCore = new Pen(cCol, 0.95f)) {
                    pGlow.LineJoin = LineJoin.Round; pGlow.StartCap = LineCap.Round; pGlow.EndCap = LineCap.Round;
                    pMid.LineJoin = LineJoin.Round;  pMid.StartCap = LineCap.Round;  pMid.EndCap = LineCap.Round;
                    pCore.LineJoin = LineJoin.Round; pCore.StartCap = LineCap.Round; pCore.EndCap = LineCap.Round;
                    g.DrawLines(pGlow, zigPts);
                    g.DrawLines(pMid, zigPts);
                    g.DrawLines(pCore, zigPts);
                    g.DrawLines(pMid, new PointF[] { new PointF(-60f, -3f), new PointF(-72f, 11f), new PointF(-84f, 16f) });
                }

                DrawFourPointStar(g, -94f, -4f, 2.8f * flicker, lightBg ? Color.FromArgb(124, 58, 237) : Color.FromArgb(254, 240, 138), (int)(a * flicker), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.6f * flicker, lightBg ? Color.FromArgb(2, 132, 199) : Color.FromArgb(125, 211, 252), (int)(a * flicker), lightBg);

                DrawLightningSpark(g, -64f, 12f, 5.4f, phase * 35f, a, lightBg);
                DrawLightningSpark(g, -96f, 8f, 5.2f, -phase * 30f, (int)(a * 0.94f), lightBg);
                DrawLightningSpark(g, 1f, 30f, 4.8f, phase * 28f, a, lightBg);

                if (!compact) {
                    DrawLightningBoltIcon(g, -74f, 2f, 7.4f, -15f + rotWobble, a, lightBg);
                    DrawLightningBoltIcon(g, -3f, 20f, 7.0f, 20f - rotWobble, a, lightBg);
                }
                DrawLightningBoltIcon(g, -40f, -1f, 8.2f, 12f + rotWobble, a, lightBg);
                DrawLightningBoltIcon(g, -17f, 4f, 10.2f, -14f - rotWobble, Math.Min(255, a + 10), lightBg);
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawTornadoVortex(Graphics g, float cx, float cy, float radius, float rotDeg, int alpha, bool lightBg) {
            if (radius < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (SolidBrush halo = new SolidBrush(Color.FromArgb(Math.Max(3, a / 4), lightBg ? 13 : 45, lightBg ? 148 : 212, lightBg ? 136 : 191))) {
                    g.FillEllipse(halo, -r * 1.15f, -r * 1.15f, r * 2.3f, r * 2.3f);
                }
                Color armCol = lightBg ? Color.FromArgb(a, 13, 148, 136) : Color.FromArgb(a, 167, 243, 208);
                Color subCol = lightBg ? Color.FromArgb((int)(a * 0.85f), 71, 85, 105) : Color.FromArgb((int)(a * 0.88f), 45, 212, 191);
                using (Pen pArm = new Pen(armCol, Math.Max(1.0f, r * 0.20f)))
                using (Pen pSub = new Pen(subCol, Math.Max(0.7f, r * 0.12f))) {
                    pArm.StartCap = LineCap.Round; pArm.EndCap = LineCap.Round;
                    pSub.StartCap = LineCap.Round; pSub.EndCap = LineCap.Round;
                    for (int k = 0; k < 3; k++) {
                        GraphicsState ags = g.Save();
                        try {
                            g.RotateTransform(k * 120f);
                            g.DrawBezier(pArm, 0f, -0.18f * r, 0.56f * r, -0.34f * r, 0.92f * r, 0.22f * r, 0.42f * r, 0.88f * r);
                            g.DrawBezier(pSub, 0.10f * r, -0.26f * r, 0.50f * r, -0.18f * r, 0.72f * r, 0.24f * r, 0.34f * r, 0.64f * r);
                        } finally {
                            g.Restore(ags);
                        }
                    }
                }
                float er = Math.Max(1.2f, r * 0.22f);
                using (SolidBrush eye = new SolidBrush(lightBg ? Color.FromArgb(a, 15, 118, 110) : Color.FromArgb(a, 240, 253, 250))) {
                    g.FillEllipse(eye, -er, -er, er * 2f, er * 2f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawTornadoFunnel(Graphics g, float cx, float cy, float height, float phase, int alpha, bool lightBg) {
            if (height < 10f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float topW = height * 0.56f;
            float tipX = cx + (float)Math.Sin(phase * 2.4f) * (height * 0.08f);

            PointF[] mistCone = new PointF[] {
                new PointF(cx - topW * 0.5f, cy - height),
                new PointF(cx + topW * 0.5f, cy - height),
                new PointF(tipX + 2.2f, cy),
                new PointF(tipX - 2.2f, cy)
            };
            using (SolidBrush mistBr = new SolidBrush(Color.FromArgb(Math.Max(6, a / 6), lightBg ? 15 : 45, lightBg ? 118 : 212, lightBg ? 110 : 191))) {
                g.FillPolygon(mistBr, mistCone);
            }

            Color cRing1 = lightBg ? Color.FromArgb((int)(a * 0.88f), 13, 148, 136) : Color.FromArgb((int)(a * 0.90f), 167, 243, 208);
            Color cRing2 = lightBg ? Color.FromArgb((int)(a * 0.80f), 71, 85, 105) : Color.FromArgb((int)(a * 0.85f), 45, 212, 191);
            int rings = 7;
            for (int i = 0; i < rings; i++) {
                float t = i / (float)(rings - 1); // 0=top wide, 1=bottom tip
                float yPos = (cy - height) + t * (height - 2f);
                float wobble = (float)Math.Sin(phase * 2.8f + i * 0.85f) * (2.2f + t * 2.4f);
                float rw = Math.Max(3.6f, topW * (1f - t * 0.84f) * 0.5f);
                float rh = Math.Max(2.0f, rw * 0.34f);
                Color rc = ((i & 1) == 0) ? cRing1 : cRing2;
                using (Pen rp = new Pen(rc, Math.Max(1.0f, (1.9f - t * 0.7f)))) {
                    rp.StartCap = LineCap.Round; rp.EndCap = LineCap.Round;
                    g.DrawEllipse(rp, cx + wobble - rw, yPos - rh, rw * 2f, rh * 2f);
                }
            }
        }

        public static void DrawWindSwirlSpeck(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                Color col = lightBg ? Color.FromArgb(a, 13, 148, 136) : Color.FromArgb(a, 167, 243, 208);
                using (Pen p = new Pen(col, Math.Max(0.9f, r * 0.22f))) {
                    p.StartCap = LineCap.Round; p.EndCap = LineCap.Round;
                    g.DrawBezier(p, -0.85f * r, 0.25f * r, -0.25f * r, -0.35f * r, 0.35f * r, 0.35f * r, 0.85f * r, -0.15f * r);
                    g.DrawArc(p, 0.25f * r, -0.60f * r, 0.65f * r, 0.55f * r, 60f, 220f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawTornadoBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float spin = phase * 65f;
            float sway = (float)Math.Sin(phase * 1.6) * 2.5f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                Color wCol = lightBg ? Color.FromArgb((int)(a * 0.85f), 13, 148, 136) : Color.FromArgb((int)(a * 0.88f), 45, 212, 191);
                Color hCol = lightBg ? Color.FromArgb((int)(a * 0.72f), 5, 150, 105) : Color.FromArgb((int)(a * 0.78f), 204, 251, 241);
                using (Pen pW = new Pen(wCol, 2.0f))
                using (Pen pH = new Pen(hCol, 1.0f)) {
                    pW.StartCap = LineCap.Round; pW.EndCap = LineCap.Round;
                    pH.StartCap = LineCap.Round; pH.EndCap = LineCap.Round;
                    g.DrawBezier(pW, -106f, -2f, -62f, 8f, -24f, -3f, 2f, 23f);
                    g.DrawBezier(pH, -102f, 3f, -60f, 11f, -22f, 1f, 0f, 26f);
                    if (!compact) {
                        g.DrawBezier(pW, -56f, 2f, -66f, 9f, -74f, 13f, -84f, 16f);
                    }
                }

                DrawWindSwirlSpeck(g, -96f + sway, 8f, 5.6f, -15f, a, lightBg);
                DrawWindSwirlSpeck(g, -62f - sway, 13f, 5.2f, 22f, a, lightBg);
                DrawWindSwirlSpeck(g, 1f, 31f, 5.0f, 38f, a, lightBg);

                DrawTornadoVortex(g, -42f, 0f, 7.8f, spin, a, lightBg);
                if (!compact) {
                    DrawTornadoVortex(g, -74f, 3f, 6.6f, -spin * 0.85f, a, lightBg);
                    DrawTornadoVortex(g, -3f, 20f, 6.4f, spin * 0.9f, a, lightBg);
                } else {
                    DrawTornadoVortex(g, -18f, 4f, 9.2f, -spin, Math.Min(255, a + 10), lightBg);
                }
            } finally {
                g.Restore(gs);
            }

            if (!flipX && !flipY && !compact) {
                float fnH = Math.Max(14f, 24f * scale);
                DrawTornadoFunnel(g, anchorX - 22f * scale, anchorY + 26f * scale, fnH, phase, Math.Min(255, a + 10), lightBg);
            }
        }

        public static void DrawTsunamiWaveIcon(Graphics g, float cx, float cy, float radius, float rotDeg, int alpha, bool lightBg) {
            if (radius < 2.2f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (GraphicsPath wp = new GraphicsPath()) {
                    wp.AddBezier(-0.92f * r, 0.45f * r, -0.45f * r, 0.25f * r, -0.20f * r, -0.58f * r, 0.55f * r, -0.50f * r);
                    wp.AddBezier(0.55f * r, -0.50f * r, 0.92f * r, -0.42f * r, 0.82f * r, -0.04f * r, 0.48f * r, -0.06f * r);
                    wp.AddBezier(0.48f * r, -0.06f * r, 0.62f * r, -0.22f * r, 0.36f * r, -0.28f * r, 0.20f * r, 0.04f * r);
                    wp.AddBezier(0.20f * r, 0.04f * r, 0.14f * r, 0.26f * r, 0.45f * r, 0.45f * r, 0.92f * r, 0.45f * r);
                    wp.CloseFigure();

                    Color cBot = lightBg ? Color.FromArgb(a, 3, 105, 161) : Color.FromArgb(a, 2, 132, 199);
                    Color cTop = lightBg ? Color.FromArgb(a, 14, 165, 233) : Color.FromArgb(a, 103, 232, 249);
                    using (LinearGradientBrush wBr = new LinearGradientBrush(new PointF(0f, 0.48f * r), new PointF(0f, -0.60f * r), cBot, cTop)) {
                        g.FillPath(wBr, wp);
                    }
                    Color crestCol = lightBg ? Color.FromArgb(a, 224, 242, 254) : Color.FromArgb(a, 255, 255, 255);
                    using (Pen crestPen = new Pen(crestCol, Math.Max(0.9f, r * 0.16f))) {
                        crestPen.StartCap = LineCap.Round; crestPen.EndCap = LineCap.Round;
                        g.DrawBezier(crestPen, -0.18f * r, -0.24f * r, 0.14f * r, -0.56f * r, 0.72f * r, -0.50f * r, 0.68f * r, -0.14f * r);
                    }
                    using (Pen rim = new Pen(lightBg ? Color.FromArgb((int)(a * 0.80f), 12, 74, 110) : Color.FromArgb((int)(a * 0.85f), 186, 230, 253), Math.Max(0.6f, r * 0.07f))) {
                        g.DrawPath(rim, wp);
                    }
                }
                using (SolidBrush sp = new SolidBrush(lightBg ? Color.FromArgb(a, 14, 165, 233) : Color.FromArgb(a, 240, 249, 255))) {
                    float d = Math.Max(1.4f, r * 0.18f);
                    g.FillEllipse(sp, 0.64f * r, -0.66f * r, d, d);
                    g.FillEllipse(sp, 0.88f * r, -0.44f * r, d * 0.8f, d * 0.8f);
                    g.FillEllipse(sp, 0.28f * r, -0.68f * r, d * 0.7f, d * 0.7f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSeaFoamDrop(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.6f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size * 0.56f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                Color cBg = lightBg ? Color.FromArgb(a, 14, 165, 233) : Color.FromArgb(a, 186, 230, 253);
                using (SolidBrush br = new SolidBrush(cBg)) {
                    g.FillEllipse(br, -r, -r, r * 2f, r * 2f);
                }
                using (SolidBrush hi = new SolidBrush(Color.FromArgb(Math.Min(255, a + 15), 255, 255, 255))) {
                    g.FillEllipse(hi, -r * 0.45f, -r * 0.50f, r * 0.65f, r * 0.55f);
                }
                using (Pen rim = new Pen(lightBg ? Color.FromArgb((int)(a * 0.80f), 3, 105, 161) : Color.FromArgb((int)(a * 0.78f), 255, 255, 255), 0.7f)) {
                    g.DrawEllipse(rim, -r, -r, r * 2f, r * 2f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawTsunamiBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float bob = (float)Math.Sin(phase * 1.5) * 2.2f;
            float roll = (float)Math.Cos(phase * 1.3) * 4.5f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                Color deepCol = lightBg ? Color.FromArgb((int)(a * 0.90f), 3, 105, 161) : Color.FromArgb((int)(a * 0.92f), 14, 165, 233);
                Color foamCol = lightBg ? Color.FromArgb((int)(a * 0.88f), 14, 165, 233) : Color.FromArgb((int)(a * 0.90f), 224, 242, 254);
                using (Pen wPen = new Pen(deepCol, 2.5f))
                using (Pen fPen = new Pen(foamCol, 1.15f)) {
                    wPen.StartCap = LineCap.Round; wPen.EndCap = LineCap.Round;
                    fPen.StartCap = LineCap.Round; fPen.EndCap = LineCap.Round;
                    g.DrawBezier(wPen, -106f, -2f, -64f, 8f, -24f, -2f, 2f, 23f);
                    g.DrawBezier(fPen, -104f, -3.5f, -64f, 6.2f, -23f, -3.6f, 0f, 21f);
                    if (!compact) {
                        g.DrawBezier(wPen, -56f, 2f, -66f, 9f, -74f, 13f, -84f, 16f);
                    }
                }

                DrawSeaFoamDrop(g, -96f + bob, 8f - bob * 0.5f, 5.0f, 0f, a, lightBg);
                DrawSeaFoamDrop(g, -64f - bob, 12f, 4.8f, 0f, a, lightBg);
                DrawSeaFoamDrop(g, 1f, 30f + bob * 0.5f, 4.6f, 0f, a, lightBg);

                DrawTsunamiWaveIcon(g, -42f, 0f, 8.2f, -8f + roll, a, lightBg);
                if (!compact) {
                    DrawTsunamiWaveIcon(g, -74f, 3f, 6.8f, 6f - roll, a, lightBg);
                    DrawTsunamiWaveIcon(g, -4f, 19f, 6.6f, 14f + roll, a, lightBg);
                } else {
                    DrawTsunamiWaveIcon(g, -18f, 4f, 9.6f, -6f + roll, Math.Min(255, a + 10), lightBg);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawMeteorIcon(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (SolidBrush aura = new SolidBrush(Color.FromArgb(Math.Max(6, lightBg ? (a / 6) : (a / 4)), lightBg ? 234 : 249, lightBg ? 88 : 115, lightBg ? 12 : 22))) {
                    g.FillEllipse(aura, -r * 0.9f, -r * 0.9f, r * 2.1f, r * 1.8f);
                }

                // Fiery comet tail stretching backward (-X)
                using (GraphicsPath tail = new GraphicsPath()) {
                    tail.AddLine(0f, -r * 0.56f, -r * 2.15f, -r * 0.06f);
                    tail.AddLine(-r * 2.15f, -r * 0.06f, -r * 2.15f, r * 0.06f);
                    tail.AddLine(-r * 2.15f, r * 0.06f, 0f, r * 0.56f);
                    tail.CloseFigure();
                    Color tBack = Color.FromArgb(0, lightBg ? 109 : 139, lightBg ? 40 : 92, lightBg ? 217 : 246);
                    Color tHead = Color.FromArgb((int)(a * 0.90f), lightBg ? 234 : 249, lightBg ? 88 : 115, lightBg ? 12 : 22);
                    using (LinearGradientBrush tBr = new LinearGradientBrush(new PointF(-r * 2.15f, 0f), new PointF(r * 0.1f, 0f), tBack, tHead)) {
                        g.FillPath(tBr, tail);
                    }
                }

                using (Pen innerStreak = new Pen(Color.FromArgb((int)(a * 0.85f), 253, 224, 71), Math.Max(0.9f, r * 0.24f))) {
                    innerStreak.StartCap = LineCap.Round;
                    innerStreak.EndCap = LineCap.Round;
                    g.DrawLine(innerStreak, -r * 1.55f, 0f, 0f, 0f);
                }

                Color headOut = lightBg ? Color.FromArgb(a, 217, 119, 6) : Color.FromArgb(a, 249, 115, 22);
                Color headRim = lightBg ? Color.FromArgb(a, 185, 28, 28) : Color.FromArgb(a, 254, 240, 138);
                using (SolidBrush hBr = new SolidBrush(headOut))
                using (Pen hPen = new Pen(headRim, Math.Max(0.75f, r * 0.14f))) {
                    g.FillEllipse(hBr, -r * 0.54f, -r * 0.54f, r * 1.08f, r * 1.08f);
                    g.DrawEllipse(hPen, -r * 0.54f, -r * 0.54f, r * 1.08f, r * 1.08f);
                }
                using (SolidBrush coreBr = new SolidBrush(Color.FromArgb(a, 254, 249, 195))) {
                    g.FillEllipse(coreBr, -r * 0.26f, -r * 0.26f, r * 0.52f, r * 0.52f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawMeteorBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float drift = (float)Math.Sin(phase * 1.4) * 2.2f;
            float tw = 0.78f + 0.22f * (float)Math.Sin(phase * 1.8);

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                Color cGlow = lightBg ? Color.FromArgb((int)(a * 0.36f), 109, 40, 217) : Color.FromArgb((int)(a * 0.44f), 139, 92, 246);
                Color cCore = lightBg ? Color.FromArgb((int)(a * 0.90f), 234, 88, 12) : Color.FromArgb((int)(a * 0.92f), 249, 115, 22);
                Color cHi = lightBg ? Color.FromArgb((int)(a * 0.85f), 250, 204, 21) : Color.FromArgb((int)(a * 0.90f), 254, 240, 138);
                using (Pen pGlow = new Pen(cGlow, 4.0f))
                using (Pen pCore = new Pen(cCore, 2.1f))
                using (Pen pHi = new Pen(cHi, 0.95f)) {
                    pGlow.StartCap = LineCap.Round; pGlow.EndCap = LineCap.Round;
                    pCore.StartCap = LineCap.Round; pCore.EndCap = LineCap.Round;
                    pHi.StartCap = LineCap.Round; pHi.EndCap = LineCap.Round;
                    g.DrawBezier(pGlow, -106f, -2f, -62f, 7f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(pCore, -106f, -2f, -62f, 7f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(pHi, -104f, -2.8f, -61f, 6.2f, -21f, -1.8f, 1f, 22f);
                    if (!compact) {
                        g.DrawBezier(pCore, -56f, 2f, -68f, 9f, -76f, 13f, -84f, 16f);
                    }
                }

                DrawFourPointStar(g, -94f, -4f, 2.7f * tw, lightBg ? Color.FromArgb(109, 40, 217) : Color.FromArgb(254, 240, 138), (int)(a * tw), lightBg);
                DrawFireEmber(g, -96f + drift, 8f - drift * 0.5f, 4.8f, -20f, a, lightBg);
                DrawFireEmber(g, -64f - drift, 12f, 4.6f, 22f, a, lightBg);
                DrawFireEmber(g, 1f, 30f + drift * 0.5f, 4.4f, 14f, a, lightBg);

                DrawMeteorIcon(g, -40f, 0f, 6.8f, 22f, a, lightBg);
                if (!compact) {
                    DrawMeteorIcon(g, -74f, 3f, 5.6f, 16f, a, lightBg);
                    DrawMeteorIcon(g, -3f, 18f, 5.6f, 34f, a, lightBg);
                } else {
                    DrawMeteorIcon(g, -18f, 4f, 7.6f, 24f, Math.Min(255, a + 10), lightBg);
                }
            } finally {
                g.Restore(gs);
            }
        }

