                    tail.CloseFigure();
                    Color cBack = Color.FromArgb(0, lightBg ? 67 : 125, lightBg ? 56 : 211, lightBg ? 202 : 252);
                    Color cFront = Color.FromArgb((int)(a * 0.88f), lightBg ? 2 : 224, lightBg ? 132 : 242, lightBg ? 199 : 254);
