        public static void DrawStarlightCrescent(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.6f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (GraphicsPath moon = new GraphicsPath()) {
                    moon.AddBezier(0f, -r, r * 0.95f, -r * 0.55f, r * 0.95f, r * 0.55f, 0f, r);
                    moon.AddBezier(0f, r, r * 0.32f, r * 0.45f, r * 0.32f, -r * 0.45f, 0f, -r);
                    moon.CloseFigure();
                    Color fillC = lightBg ? Color.FromArgb(a, 217, 119, 6) : Color.FromArgb(a, 254, 240, 138);
                    Color rimC = lightBg ? Color.FromArgb(a, 67, 56, 202) : Color.FromArgb(a, 255, 255, 255);
                    using (SolidBrush br = new SolidBrush(fillC))
                    using (Pen pen = new Pen(rimC, Math.Max(0.65f, r * 0.12f))) {
                        g.FillPath(br, moon);
                        g.DrawPath(pen, moon);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawShootingStarBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float tw1 = 0.72f + 0.28f * (float)Math.Sin(phase * 1.9);
            float tw2 = 0.72f + 0.28f * (float)Math.Sin(phase * 1.9 + 1.8);
            float sway = (float)Math.Sin(phase * 1.2) * 3.0f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                Color cGlow = lightBg ? Color.FromArgb((int)(a * 0.32f), 67, 56, 202) : Color.FromArgb((int)(a * 0.42f), 99, 102, 241);
                Color cMain = lightBg ? Color.FromArgb((int)(a * 0.88f), 2, 132, 199) : Color.FromArgb((int)(a * 0.90f), 125, 211, 252);
                Color cGold = lightBg ? Color.FromArgb((int)(a * 0.80f), 217, 119, 6) : Color.FromArgb((int)(a * 0.88f), 254, 240, 138);
                using (Pen pGlow = new Pen(cGlow, 3.8f))
                using (Pen pMain = new Pen(cMain, 1.9f))
                using (Pen pGold = new Pen(cGold, 0.9f)) {
                    pGlow.StartCap = LineCap.Round; pGlow.EndCap = LineCap.Round;
                    pMain.StartCap = LineCap.Round; pMain.EndCap = LineCap.Round;
                    pGold.StartCap = LineCap.Round; pGold.EndCap = LineCap.Round;
                    g.DrawBezier(pGlow, -106f, -2f, -64f, 6f, -24f, -2f, 2f, 23f);
                    g.DrawBezier(pMain, -106f, -2f, -64f, 6f, -24f, -2f, 2f, 23f);
                    g.DrawBezier(pGold, -104f, -2.8f, -63f, 5.2f, -23f, -2.8f, 1f, 22f);
                    if (!compact) {
                        g.DrawBezier(pMain, -56f, 2f, -66f, 9f, -74f, 13f, -84f, 16f);
                    }
                }

                DrawFourPointStar(g, -95f, -4f, 2.8f * tw1, lightBg ? Color.FromArgb(2, 132, 199) : Color.FromArgb(125, 211, 252), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -64f, 12f, 2.4f * tw2, lightBg ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138), (int)(a * tw2), lightBg);
                DrawStarlightCrescent(g, -18f, 24f, 5.2f, -24f + sway, a, lightBg);

                DrawShootingStarIcon(g, -42f, 0f, 6.8f, 18f, a, lightBg);
                if (!compact) {
                    DrawShootingStarIcon(g, -74f, 3f, 5.8f, 14f, a, lightBg);
                    DrawShootingStarIcon(g, -3f, 18f, 5.8f, 32f, a, lightBg);
                } else {
                    DrawShootingStarIcon(g, -18f, 4f, 7.6f, 22f, Math.Min(255, a + 10), lightBg);
                }
            } finally {
                g.Restore(gs);
            }
        }

