        public static void DrawBokehMoteIcon(Graphics g, float cx, float cy, float size, int alpha, bool lightBg) {
            if (size < 1.4f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            using (SolidBrush halo = new SolidBrush(Color.FromArgb(Math.Max(6, lightBg ? (a / 5) : (a / 4)), lightBg ? 234 : 253, lightBg ? 179 : 224, lightBg ? 8 : 71))) {
                g.FillEllipse(halo, cx - r * 1.25f, cy - r * 1.25f, r * 2.5f, r * 2.5f);
            }
            using (SolidBrush body = new SolidBrush(Color.FromArgb((int)(a * 0.58f), lightBg ? 250 : 254, lightBg ? 204 : 240, lightBg ? 21 : 138)))
            using (Pen rim = new Pen(lightBg ? Color.FromArgb((int)(a * 0.90f), 217, 119, 6) : Color.FromArgb((int)(a * 0.92f), 254, 249, 195), Math.Max(0.75f, r * 0.22f))) {
                g.FillEllipse(body, cx - r * 0.82f, cy - r * 0.82f, r * 1.64f, r * 1.64f);
                g.DrawEllipse(rim, cx - r * 0.82f, cy - r * 0.82f, r * 1.64f, r * 1.64f);
            }
            using (SolidBrush glint = new SolidBrush(Color.FromArgb(a, 255, 255, 245))) {
                g.FillEllipse(glint, cx - r * 0.28f, cy - r * 0.28f, r * 0.56f, r * 0.56f);
