        public static void DrawSunbeamsBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
