                    g.FillPolygon(rayBr, new PointF[] { new PointF(2f, -2f), new PointF(-66f, 18f), new PointF(-52f, 31f) });
                    g.FillPolygon(rayBr, new PointF[] { new PointF(2f, -2f), new PointF(-36f, 34f), new PointF(-18f, 41f) });
