                Color cArc = lightBg ? Color.FromArgb((int)(a * 0.90f), 217, 119, 6) : Color.FromArgb((int)(a * 0.92f), 250, 204, 21);
                Color cHi = lightBg ? Color.FromArgb((int)(a * 0.85f), 250, 204, 21) : Color.FromArgb((int)(a * 0.90f), 254, 249, 195);
                using (Pen aPen = new Pen(cArc, 2.2f))
                using (Pen hPen = new Pen(cHi, 1.0f)) {
                    aPen.StartCap = LineCap.Round; aPen.EndCap = LineCap.Round;
                    hPen.StartCap = LineCap.Round; hPen.EndCap = LineCap.Round;
