                DrawBokehMoteIcon(g, -94f, 6f, 4.6f, a, lightBg);
                DrawBokehMoteIcon(g, -64f, 14f, 5.0f, a, lightBg);
                DrawBokehMoteIcon(g, 0f, 30f, 4.4f, a, lightBg);
                DrawFourPointStar(g, -26f, -4f, 2.7f * pulse, lightBg ? Color.FromArgb(234, 88, 12) : Color.FromArgb(254, 249, 195), (int)(a * pulse), lightBg);

                DrawSummerSun(g, -42f, 0f, 8.0f, phase * 18f, a, lightBg);
                if (!compact) {
                    DrawSummerSun(g, -74f, 3f, 6.8f, -phase * 15f, a, lightBg);
                    DrawSummerSun(g, -4f, 19f, 6.8f, phase * 16f, a, lightBg);
