        public static void DrawRaindropIcon(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (GraphicsPath drop = new GraphicsPath()) {
                    drop.AddBezier(0f, -r * 1.12f, r * 0.56f, -r * 0.25f, r * 0.78f, r * 0.25f, r * 0.64f, r * 0.62f);
                    drop.AddBezier(r * 0.64f, r * 0.62f, r * 0.42f, r * 0.98f, -r * 0.42f, r * 0.98f, -r * 0.64f, r * 0.62f);
                    drop.AddBezier(-r * 0.64f, r * 0.62f, -r * 0.78f, r * 0.25f, -r * 0.56f, -r * 0.25f, 0f, -r * 1.12f);
                    drop.CloseFigure();

                    Color cTop = lightBg ? Color.FromArgb(a, 56, 189, 248) : Color.FromArgb(a, 224, 242, 254);
                    Color cBot = lightBg ? Color.FromArgb(a, 2, 132, 199) : Color.FromArgb(a, 56, 189, 248);
                    Color cRim = lightBg ? Color.FromArgb(a, 3, 105, 161) : Color.FromArgb(a, 186, 230, 253);
                    using (LinearGradientBrush dBr = new LinearGradientBrush(new PointF(0f, -r * 1.12f), new PointF(0f, r * 0.98f), cTop, cBot))
                    using (Pen dPen = new Pen(cRim, Math.Max(0.75f, r * 0.14f))) {
                        g.FillPath(dBr, drop);
                        g.DrawPath(dPen, drop);
                    }
                }
                using (SolidBrush spec = new SolidBrush(Color.FromArgb(a, 255, 255, 255))) {
                    g.FillEllipse(spec, -r * 0.30f, r * 0.08f, Math.Max(1.2f, r * 0.28f), Math.Max(1.4f, r * 0.40f));
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawRainRippleIcon(Graphics g, float cx, float cy, float size, int alpha, bool lightBg) {
            if (size < 1.8f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size;

            Color rimCol = lightBg ? Color.FromArgb((int)(a * 0.85f), 2, 132, 199) : Color.FromArgb((int)(a * 0.88f), 186, 230, 253);
            using (Pen outerPen = new Pen(rimCol, Math.Max(0.75f, r * 0.16f)))
            using (Pen innerPen = new Pen(Color.FromArgb((int)(a * 0.65f), rimCol.R, rimCol.G, rimCol.B), Math.Max(0.6f, r * 0.12f))) {
                g.DrawEllipse(outerPen, cx - r * 1.10f, cy - r * 0.42f, r * 2.20f, r * 0.84f);
                g.DrawEllipse(innerPen, cx - r * 0.62f, cy - r * 0.22f, r * 1.24f, r * 0.44f);
            }
            using (SolidBrush cDot = new SolidBrush(Color.FromArgb(a, lightBg ? 3 : 224, lightBg ? 105 : 242, lightBg ? 161 : 254))) {
                g.FillEllipse(cDot, cx - r * 0.18f, cy - r * 0.12f, r * 0.36f, r * 0.24f);
            }
