        public static void DrawRainBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float sway = (float)Math.Sin(phase * 1.3) * 2.2f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                Color cArc = lightBg ? Color.FromArgb((int)(a * 0.88f), 2, 132, 199) : Color.FromArgb((int)(a * 0.90f), 125, 211, 252);
                Color cInd = lightBg ? Color.FromArgb((int)(a * 0.72f), 79, 70, 229) : Color.FromArgb((int)(a * 0.78f), 199, 210, 254);
                using (Pen rPen = new Pen(cArc, 2.2f))
                using (Pen mPen = new Pen(cInd, 1.05f)) {
                    rPen.StartCap = LineCap.Round; rPen.EndCap = LineCap.Round;
                    mPen.StartCap = LineCap.Round; mPen.EndCap = LineCap.Round;
                    g.DrawBezier(rPen, -106f, -2f, -64f, 7f, -24f, -1f, 2f, 23f);
                    g.DrawBezier(mPen, -104f, -3.2f, -63f, 5.6f, -23f, -2.4f, 1f, 21.8f);
                    if (!compact) {
                        g.DrawBezier(rPen, -56f, 2f, -66f, 9f, -74f, 13f, -84f, 16f);
                    }
                    // Crisp diagonal rain streaks
                    g.DrawLine(mPen, -86f, -1f, -92f, 11f);
                    g.DrawLine(mPen, -52f, 5f, -58f, 17f);
                    g.DrawLine(mPen, -20f, 9f, -25f, 20f);
                }

                DrawRainRippleIcon(g, -94f, 12f, 4.8f, a, lightBg);
                DrawRainRippleIcon(g, -62f, 18f, 4.6f, a, lightBg);
                DrawRaindropIcon(g, 0f, 30f, 4.4f, 14f, a, lightBg);

                DrawRaindropIcon(g, -42f, 0f, 6.2f, 12f + sway, a, lightBg);
                if (!compact) {
                    DrawRaindropIcon(g, -74f, 3f, 5.4f, 10f - sway, a, lightBg);
                    DrawRaindropIcon(g, -4f, 19f, 5.4f, 16f + sway, a, lightBg);
                } else {
                    DrawRaindropIcon(g, -18f, 4f, 6.8f, 12f + sway, Math.Min(255, a + 10), lightBg);
                }
            } finally {
                g.Restore(gs);
            }
