        public static void DrawSummerSun(Graphics g, float cx, float cy, float radius, float rotDeg, int alpha, bool lightBg) {
            if (radius < 2.2f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (SolidBrush aura = new SolidBrush(Color.FromArgb(Math.Max(4, lightBg ? (a / 5) : (a / 4)), 250, 204, 21))) {
                    g.FillEllipse(aura, -r * 1.32f, -r * 1.32f, r * 2.64f, r * 2.64f);
                }

                Color rayCol = lightBg ? Color.FromArgb(a, 217, 119, 6) : Color.FromArgb(a, 253, 224, 71);
                using (Pen rayPen = new Pen(rayCol, Math.Max(1.0f, r * 0.15f))) {
                    rayPen.StartCap = LineCap.Round;
                    rayPen.EndCap = LineCap.Round;
                    for (int k = 0; k < 8; k++) {
                        double ang = k * Math.PI / 4.0;
                        float rOut = ((k & 1) == 0) ? (r * 1.08f) : (r * 0.88f);
                        float rIn  = r * 0.62f;
                        float ca = (float)Math.Cos(ang);
                        float sa = (float)Math.Sin(ang);
                        g.DrawLine(rayPen, ca * rIn, sa * rIn, ca * rOut, sa * rOut);
                    }
                }

                float coreR = r * 0.52f;
                Color cTop = lightBg ? Color.FromArgb(a, 253, 224, 71) : Color.FromArgb(a, 254, 249, 195);
                Color cBot = lightBg ? Color.FromArgb(a, 234, 88, 12) : Color.FromArgb(a, 245, 158, 11);
                using (LinearGradientBrush coreBr = new LinearGradientBrush(new PointF(0f, -coreR - 0.5f), new PointF(0f, coreR + 0.5f), cTop, cBot)) {
                    g.FillEllipse(coreBr, -coreR, -coreR, coreR * 2f, coreR * 2f);
                }
                using (Pen rim = new Pen(lightBg ? Color.FromArgb(a, 180, 83, 9) : Color.FromArgb(a, 254, 240, 138), Math.Max(0.7f, r * 0.08f))) {
                    g.DrawEllipse(rim, -coreR, -coreR, coreR * 2f, coreR * 2f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSummerLeaf(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size * 1.1f;
            float w = size * 0.56f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (GraphicsPath lp = new GraphicsPath()) {
                    lp.AddBezier(0f, 0.48f * h, 0.56f * w, 0.20f * h, 0.54f * w, -0.24f * h, 0f, -0.50f * h);
                    lp.AddBezier(0f, -0.50f * h, -0.54f * w, -0.24f * h, -0.56f * w, 0.20f * h, 0f, 0.48f * h);
                    lp.CloseFigure();

                    Color cBot = lightBg ? Color.FromArgb(a, 21, 128, 61) : Color.FromArgb(a, 16, 185, 129);
                    Color cTop = lightBg ? Color.FromArgb(a, 74, 222, 128) : Color.FromArgb(a, 134, 239, 172);
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.50f * h), new PointF(0f, -0.52f * h), cBot, cTop)) {
                        g.FillPath(br, lp);
                    }
                    Color rimCol = lightBg ? Color.FromArgb((int)(a * 0.85f), 20, 83, 45) : Color.FromArgb((int)(a * 0.80f), 167, 243, 208);
                    using (Pen rim = new Pen(rimCol, 0.7f)) {
                        g.DrawPath(rim, lp);
                    }
                }
                using (Pen vein = new Pen(lightBg ? Color.FromArgb((int)(a * 0.75f), 187, 247, 208) : Color.FromArgb((int)(a * 0.75f), 236, 253, 245), 0.65f)) {
                    vein.StartCap = LineCap.Round;
                    vein.EndCap = LineCap.Round;
                    g.DrawLine(vein, 0f, 0.42f * h, 0f, -0.34f * h);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSummerBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float swayRot = (float)Math.Sin(phase * 1.1) * 3.5f;
            float sunSpin = phase * 22f;
            float tw1 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5);
            float tw2 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5 + 1.9);
            float driftX = (float)Math.Sin(phase * 0.95) * 2.2f;
            float driftY = (float)Math.Cos(phase * 0.85) * 1.5f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                using (Pen vinePen = new Pen(Color.FromArgb((int)(a * 0.92f), 21, 128, 61), 2.3f)) {
                    vinePen.StartCap = LineCap.Round;
                    vinePen.EndCap = LineCap.Round;
                    g.DrawBezier(vinePen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(vinePen, -56f, 2f, -66f, 9f, -74f, 13f, -82f, 16f);
                    if (!compact) {
                        g.DrawBezier(vinePen, -22f, 4f, -11f, 3f, -3f, 5f, 3f, 12f);
                    }
                }
                Color vineHiCol = lightBg ? Color.FromArgb((int)(a * 0.75f), 74, 222, 128) : Color.FromArgb((int)(a * 0.72f), 110, 231, 183);
                using (Pen vineHi = new Pen(vineHiCol, 0.9f)) {
                    vineHi.StartCap = LineCap.Round;
                    vineHi.EndCap = LineCap.Round;
                    g.DrawBezier(vineHi, -104f, -2.6f, -59f, 5.2f, -21f, -1.8f, 1f, 22f);
                }

                DrawFourPointStar(g, -94f, -4f, 2.7f * tw1, lightBg ? Color.FromArgb(234, 158, 12) : Color.FromArgb(254, 240, 138), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.5f * tw2, lightBg ? Color.FromArgb(14, 165, 233) : Color.FromArgb(125, 211, 252), (int)(a * tw2), lightBg);

                DrawSummerLeaf(g, -64f, 11f, 5.8f, 124f + swayRot, a, lightBg);
                DrawSummerLeaf(g, 1f, 31f, 5.4f, 158f - swayRot, a, lightBg);
                DrawSummerLeaf(g, -96f + driftX, 8f + driftY, 6.2f, -38f + (float)Math.Sin(phase) * 12f, (int)(a * 0.94f), lightBg);
                DrawSummerLeaf(g, -54f - driftX * 0.7f, 17f + driftY * 1.1f, 5.6f, 40f + (float)Math.Cos(phase) * 14f, (int)(a * 0.90f), lightBg);

                if (!compact) {
                    DrawSummerSun(g, -74f, 4f, 7.6f, sunSpin, a, lightBg);
                    DrawSunflower(g, -3f, 20f, 7.2f, 24f + swayRot, a, lightBg);
                }
                DrawSunflower(g, -42f, -1f, 8.4f, 16f - swayRot, a, lightBg);
                DrawSunflower(g, -18f, 4f, 10.2f, -10f + swayRot, Math.Min(255, a + 10), lightBg);
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawAutumnMapleLeaf(Graphics g, float cx, float cy, float radius, float rotDeg, Color baseCol, Color tipCol, int alpha, bool lightBg) {
            if (radius < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                int haloA = Math.Max(2, lightBg ? (a / 7) : (a / 5));
                using (SolidBrush halo = new SolidBrush(Color.FromArgb(haloA, baseCol))) {
                    g.FillEllipse(halo, -r * 1.16f, -r * 1.16f, r * 2.32f, r * 2.32f);
                }

                PointF[] pts = new PointF[] {
                    new PointF(0f, 0.48f * r),
                    new PointF(0.18f * r, 0.34f * r),
                    new PointF(0.62f * r, 0.42f * r),
                    new PointF(0.42f * r, 0.16f * r),
                    new PointF(0.96f * r, -0.02f * r),
                    new PointF(0.58f * r, -0.18f * r),
                    new PointF(0.66f * r, -0.34f * r),
                    new PointF(0.34f * r, -0.26f * r),
                    new PointF(0.38f * r, -0.62f * r),
                    new PointF(0.18f * r, -0.56f * r),
                    new PointF(0f, -1.00f * r),
                    new PointF(-0.18f * r, -0.56f * r),
                    new PointF(-0.38f * r, -0.62f * r),
                    new PointF(-0.34f * r, -0.26f * r),
                    new PointF(-0.66f * r, -0.34f * r),
                    new PointF(-0.58f * r, -0.18f * r),
                    new PointF(-0.96f * r, -0.02f * r),
                    new PointF(-0.42f * r, 0.16f * r),
                    new PointF(-0.62f * r, 0.42f * r),
                    new PointF(-0.18f * r, 0.34f * r)
                };

                using (GraphicsPath mp = new GraphicsPath()) {
                    mp.AddPolygon(pts);
                    using (LinearGradientBrush mBr = new LinearGradientBrush(new PointF(0f, -1.02f * r), new PointF(0f, 0.52f * r), Color.FromArgb(Math.Min(255, a + 10), tipCol), Color.FromArgb(a, baseCol))) {
                        g.FillPath(mBr, mp);
                    }
                    Color edgeCol = lightBg ? Color.FromArgb((int)(a * 0.85f), 146, 64, 14) : Color.FromArgb((int)(a * 0.85f), 254, 240, 138);
                    using (Pen mPen = new Pen(edgeCol, Math.Max(0.55f, r * 0.08f))) {
                        mPen.LineJoin = LineJoin.Round;
                        g.DrawPath(mPen, mp);
                    }
                }

                Color veinCol = lightBg ? Color.FromArgb((int)(a * 0.82f), 120, 53, 15) : Color.FromArgb((int)(a * 0.72f), 254, 243, 199);
                using (Pen stem = new Pen(veinCol, Math.Max(0.6f, r * 0.09f))) {
                    stem.StartCap = LineCap.Round;
                    stem.EndCap = LineCap.Round;
                    g.DrawLine(stem, 0f, 0.44f * r, 0.06f * r, 0.88f * r);
                    if (r >= 4.0f) {
                        g.DrawLine(stem, 0f, 0.30f * r, 0f, -0.62f * r);
                        g.DrawLine(stem, 0f, 0.22f * r, 0.56f * r, -0.06f * r);
                        g.DrawLine(stem, 0f, 0.22f * r, -0.56f * r, -0.06f * r);
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawAutumnLeaf(Graphics g, float cx, float cy, float size, float rotDeg, Color leafCol, int alpha, bool lightBg) {
            if (size < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size * 1.15f;
            float w = size * 0.58f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);
                using (GraphicsPath lp = new GraphicsPath()) {
                    lp.AddBezier(0f, 0.46f * h, 0.54f * w, 0.22f * h, 0.52f * w, -0.22f * h, 0f, -0.50f * h);
                    lp.AddBezier(0f, -0.50f * h, -0.52f * w, -0.22f * h, -0.54f * w, 0.22f * h, 0f, 0.46f * h);
                    lp.CloseFigure();

                    Color cBot = Color.FromArgb(a, lightBg ? DarkenColor(leafCol, 0.14f) : leafCol);
                    Color cTop = Color.FromArgb(Math.Min(255, a + 10), BlendWithWhite(leafCol, lightBg ? 0.35f : 0.62f));
                    using (LinearGradientBrush br = new LinearGradientBrush(new PointF(0f, 0.50f * h), new PointF(0f, -0.52f * h), cBot, cTop)) {
                        g.FillPath(br, lp);
                    }
                    Color rimC = lightBg ? Color.FromArgb((int)(a * 0.85f), 120, 53, 15) : Color.FromArgb((int)(a * 0.82f), 254, 240, 138);
                    using (Pen rim = new Pen(rimC, 0.7f)) {
                        g.DrawPath(rim, lp);
                    }
                }
                using (Pen vein = new Pen(lightBg ? Color.FromArgb((int)(a * 0.80f), 120, 53, 15) : Color.FromArgb((int)(a * 0.72f), 254, 243, 199), 0.65f)) {
                    vein.StartCap = LineCap.Round;
                    vein.EndCap = LineCap.Round;
                    g.DrawLine(vein, 0f, 0.64f * h, 0f, -0.34f * h);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawAutumnAcorn(Graphics g, float cx, float cy, float size, float rotDeg, int alpha, bool lightBg) {
            if (size < 2.2f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float h = size;
            float w = size * 0.66f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                using (GraphicsPath nut = new GraphicsPath()) {
                    nut.AddBezier(-0.46f * w, -0.05f * h, -0.52f * w, 0.32f * h, -0.18f * w, 0.46f * h, 0f, 0.52f * h);
                    nut.AddBezier(0f, 0.52f * h, 0.18f * w, 0.46f * h, 0.52f * w, 0.32f * h, 0.46f * w, -0.05f * h);
                    nut.CloseFigure();
                    Color nTop = lightBg ? Color.FromArgb(a, 245, 158, 11) : Color.FromArgb(a, 251, 191, 36);
                    Color nBot = lightBg ? Color.FromArgb(a, 180, 83, 9) : Color.FromArgb(a, 217, 119, 6);
                    using (LinearGradientBrush nbr = new LinearGradientBrush(new PointF(0f, -0.06f * h), new PointF(0f, 0.54f * h), nTop, nBot)) {
                        g.FillPath(nbr, nut);
                    }
                    using (Pen nRim = new Pen(lightBg ? Color.FromArgb((int)(a * 0.85f), 120, 53, 15) : Color.FromArgb((int)(a * 0.80f), 254, 240, 138), 0.7f)) {
                        g.DrawPath(nRim, nut);
                    }
                }

                RectangleF capRect = new RectangleF(-0.54f * w, -0.34f * h, 1.08f * w, 0.34f * h);
                using (GraphicsPath cap = CreateRoundedRect(capRect, Math.Max(1f, 0.16f * h)))
                using (SolidBrush cbr = new SolidBrush(Color.FromArgb(a, 120, 53, 15))) {
                    g.FillPath(cbr, cap);
                }
                using (Pen stem = new Pen(Color.FromArgb(a, 92, 42, 14), Math.Max(0.8f, size * 0.14f))) {
                    stem.StartCap = LineCap.Round;
                    stem.EndCap = LineCap.Round;
                    g.DrawLine(stem, 0f, -0.32f * h, 0.08f * w, -0.52f * h);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawAutumnBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float swayRot = (float)Math.Sin(phase * 1.05) * 4.2f;
            float tw1 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.4);
            float tw2 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.4 + 2.0);
            float driftX = (float)Math.Sin(phase * 0.90) * 2.5f;
            float driftY = (float)Math.Cos(phase * 0.85) * 1.7f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                using (Pen woodPen = new Pen(Color.FromArgb((int)(a * 0.92f), 110, 52, 18), 2.3f)) {
                    woodPen.StartCap = LineCap.Round;
                    woodPen.EndCap = LineCap.Round;
                    g.DrawBezier(woodPen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(woodPen, -56f, 2f, -66f, 9f, -74f, 13f, -82f, 16f);
                    if (!compact) {
                        g.DrawBezier(woodPen, -22f, 4f, -11f, 3f, -3f, 5f, 3f, 12f);
                    }
                }
                Color woodHiCol = lightBg ? Color.FromArgb((int)(a * 0.75f), 217, 119, 6) : Color.FromArgb((int)(a * 0.72f), 251, 191, 36);
                using (Pen woodHi = new Pen(woodHiCol, 0.9f)) {
                    woodHi.StartCap = LineCap.Round;
                    woodHi.EndCap = LineCap.Round;
                    g.DrawBezier(woodHi, -104f, -2.6f, -59f, 5.2f, -21f, -1.8f, 1f, 22f);
                }

                DrawFourPointStar(g, -94f, -4f, 2.6f * tw1, lightBg ? Color.FromArgb(217, 119, 6) : Color.FromArgb(253, 224, 71), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.4f * tw2, lightBg ? Color.FromArgb(234, 88, 12) : Color.FromArgb(251, 146, 60), (int)(a * tw2), lightBg);

                DrawAutumnAcorn(g, -64f, 11f, 5.8f, 125f + swayRot, a, lightBg);
                DrawAutumnAcorn(g, 1f, 32f, 5.4f, 155f - swayRot, a, lightBg);

                DrawAutumnLeaf(g, -96f + driftX, 8f + driftY, 6.4f, -42f + (float)Math.Sin(phase) * 16f, Color.FromArgb(245, 158, 11), (int)(a * 0.95f), lightBg);
                DrawAutumnLeaf(g, -54f - driftX * 0.7f, 17f + driftY * 1.1f, 5.8f, 38f + (float)Math.Cos(phase) * 18f, Color.FromArgb(234, 88, 12), (int)(a * 0.92f), lightBg);
                if (!compact) {
                    DrawAutumnLeaf(g, -15f + driftX * 0.5f, 33f + driftY * 0.8f, 5.5f, 70f + swayRot * 2f, Color.FromArgb(250, 204, 21), (int)(a * 0.90f), lightBg);
                }

                Color m1Base = Color.FromArgb(234, 88, 12);
                Color m1Tip  = Color.FromArgb(250, 204, 21);
                Color m2Base = Color.FromArgb(217, 119, 6);
                Color m2Tip  = Color.FromArgb(253, 224, 71);

                DrawAutumnMapleLeaf(g, -42f, -1f, 8.2f, 18f - swayRot, m2Base, m2Tip, a, lightBg);
                if (!compact) {
                    DrawAutumnMapleLeaf(g, -76f, 2f, 6.2f, -24f + swayRot, m1Base, m1Tip, a, lightBg);
                    DrawAutumnMapleLeaf(g, -3f, 20f, 7.4f, 28f + swayRot, m2Base, m2Tip, a, lightBg);
                }
                DrawAutumnMapleLeaf(g, -18f, 4f, 10.2f, -12f + swayRot, m1Base, m1Tip, Math.Min(255, a + 10), lightBg);
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSnowflake(Graphics g, float cx, float cy, float radius, float rotDeg, int alpha, bool lightBg) {
            if (radius < 2.0f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = radius;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(rotDeg);

                int haloA = Math.Max(3, lightBg ? (a / 6) : (a / 4));
                using (SolidBrush halo = new SolidBrush(Color.FromArgb(haloA, 56, 189, 248))) {
                    g.FillEllipse(halo, -r * 1.18f, -r * 1.18f, r * 2.36f, r * 2.36f);
                }

                float pwGlow = Math.Max(1.4f, r * 0.24f);
                float pwCore = Math.Max(0.85f, r * 0.13f);
                Color glowCol = lightBg ? Color.FromArgb((int)(a * 0.35f), 56, 189, 248) : Color.FromArgb((int)(a * 0.55f), 56, 189, 248);
                Color coreCol = lightBg ? Color.FromArgb(a, 2, 132, 199) : Color.FromArgb(Math.Min(255, a + 15), 240, 249, 255);

                using (Pen glowPen = new Pen(glowCol, pwGlow))
                using (Pen corePen = new Pen(coreCol, pwCore)) {
                    glowPen.StartCap = LineCap.Round; glowPen.EndCap = LineCap.Round;
                    corePen.StartCap = LineCap.Round; corePen.EndCap = LineCap.Round;
                    for (int k = 0; k < 6; k++) {
                        GraphicsState armGs = g.Save();
                        try {
                            g.RotateTransform(k * 60f);
                            g.DrawLine(glowPen, 0f, 0f, 0f, -r);
                            g.DrawLine(glowPen, 0f, -0.64f * r, 0.24f * r, -0.84f * r);
                            g.DrawLine(glowPen, 0f, -0.64f * r, -0.24f * r, -0.84f * r);

                            g.DrawLine(corePen, 0f, 0f, 0f, -r);
                            g.DrawLine(corePen, 0f, -0.64f * r, 0.24f * r, -0.84f * r);
                            g.DrawLine(corePen, 0f, -0.64f * r, -0.24f * r, -0.84f * r);

                            if (r >= 4.5f) {
                                g.DrawLine(corePen, 0f, -0.36f * r, 0.19f * r, -0.52f * r);
                                g.DrawLine(corePen, 0f, -0.36f * r, -0.19f * r, -0.52f * r);
                            }
                            if (r >= 6.0f) {
                                float tipD = Math.Max(1.0f, r * 0.14f);
                                using (SolidBrush tBr = new SolidBrush(lightBg ? Color.FromArgb(a, 56, 189, 248) : Color.FromArgb(a, 255, 255, 255))) {
                                    g.FillEllipse(tBr, -tipD * 0.5f, -r - tipD * 0.5f, tipD, tipD);
                                }
                            }
                        } finally {
                            g.Restore(armGs);
                        }
                    }
                }

                float gemR = Math.Max(0.9f, r * 0.18f);
                using (SolidBrush gemBr = new SolidBrush(lightBg ? Color.FromArgb(a, 14, 165, 233) : Color.FromArgb(a, 224, 242, 254))) {
                    g.FillEllipse(gemBr, -gemR, -gemR, gemR * 2f, gemR * 2f);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawSnowDot(Graphics g, float cx, float cy, float size, int alpha, bool lightBg) {
            if (size < 1.6f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float r = size * 0.50f;
            using (SolidBrush halo = new SolidBrush(Color.FromArgb(Math.Max(3, lightBg ? (int)(a * 0.30f) : (int)(a * 0.38f)), lightBg ? 14 : 125, lightBg ? 165 : 211, lightBg ? 233 : 252))) {
                g.FillEllipse(halo, cx - r * 1.45f, cy - r * 1.45f, r * 2.90f, r * 2.90f);
            }
            using (SolidBrush core = new SolidBrush(lightBg ? Color.FromArgb(a, 224, 242, 254) : Color.FromArgb(Math.Min(255, a + 15), 255, 255, 255))) {
                g.FillEllipse(core, cx - r, cy - r, r * 2f, r * 2f);
            }
            if (lightBg) {
                using (Pen rim = new Pen(Color.FromArgb((int)(a * 0.85f), 2, 132, 199), 0.75f)) {
                    g.DrawEllipse(rim, cx - r, cy - r, r * 2f, r * 2f);
                }
            }
        }

        public static void DrawSnowman(Graphics g, float cx, float cy, float height, float swayDeg, int alpha, bool lightBg) {
            if (height < 12f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float s = height / 30f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(cx, cy);
                g.RotateTransform(swayDeg);

                // Soft ice shadow under base
                using (SolidBrush shBr = new SolidBrush(Color.FromArgb((int)(a * (lightBg ? 0.30f : 0.42f)), lightBg ? 14 : 56, lightBg ? 165 : 189, lightBg ? 233 : 248))) {
                    g.FillEllipse(shBr, -8.5f * s, -1.6f * s, 17f * s, 3.2f * s);
                }

                // Brown twig arms + tiny forks
                using (Pen armPen = new Pen(Color.FromArgb(a, lightBg ? 120 : 180, lightBg ? 53 : 83, lightBg ? 15 : 9), Math.Max(0.9f, 1.15f * s))) {
                    armPen.StartCap = LineCap.Round;
                    armPen.EndCap = LineCap.Round;
                    g.DrawLine(armPen, -5.2f * s, -9.8f * s, -10.8f * s, -13.6f * s);
                    g.DrawLine(armPen, -9.2f * s, -12.5f * s, -11.6f * s, -11.4f * s);
                    g.DrawLine(armPen, -9.2f * s, -12.5f * s, -9.4f * s, -15.2f * s);

                    g.DrawLine(armPen, 5.2f * s, -9.8f * s, 10.8f * s, -13.6f * s);
                    g.DrawLine(armPen, 9.2f * s, -12.5f * s, 11.6f * s, -11.4f * s);
                    g.DrawLine(armPen, 9.2f * s, -12.5f * s, 9.4f * s, -15.2f * s);
                }

                Color rimCol = lightBg ? Color.FromArgb(a, 2, 132, 199) : Color.FromArgb((int)(a * 0.90f), 125, 211, 252);
                float rimW = Math.Max(0.95f, 1.05f * s);

                // Bottom snowball
                RectangleF bodyRect = new RectangleF(-7.6f * s, -12.6f * s, 15.2f * s, 12.6f * s);
                using (LinearGradientBrush bodyBr = new LinearGradientBrush(new PointF(0f, bodyRect.Y - 0.5f), new PointF(0f, bodyRect.Bottom + 0.5f), Color.FromArgb(a, 255, 255, 255), Color.FromArgb(a, 186, 230, 253))) {
                    g.FillEllipse(bodyBr, bodyRect);
                }
                using (Pen bRim = new Pen(rimCol, rimW)) {
                    g.DrawEllipse(bRim, bodyRect);
                }

                // Belly coal buttons
                float btnD = Math.Max(1.3f, 1.75f * s);
                using (SolidBrush coal = new SolidBrush(Color.FromArgb(a, 15, 23, 42))) {
                    g.FillEllipse(coal, -btnD * 0.5f, -8.3f * s - btnD * 0.5f, btnD, btnD);
                    g.FillEllipse(coal, -btnD * 0.5f, -4.6f * s - btnD * 0.5f, btnD, btnD);
                }

                // Head snowball
                RectangleF headRect = new RectangleF(-5.3f * s, -21.3f * s, 10.6f * s, 9.8f * s);
                using (LinearGradientBrush headBr = new LinearGradientBrush(new PointF(0f, headRect.Y - 0.5f), new PointF(0f, headRect.Bottom + 0.5f), Color.FromArgb(a, 255, 255, 255), Color.FromArgb(a, 204, 238, 254))) {
                    g.FillEllipse(headBr, headRect);
                }
                using (Pen hRim = new Pen(rimCol, rimW)) {
                    g.DrawEllipse(hRim, headRect);
                }

                // Cozy crimson-red scarf + hanging tail
                PointF[] tailPts = new PointF[] {
                    new PointF(1.6f * s, -12.0f * s),
                    new PointF(4.4f * s, -12.0f * s),
                    new PointF(5.6f * s, -6.8f * s),
                    new PointF(2.8f * s, -7.2f * s)
                };
                using (SolidBrush scBr = new SolidBrush(Color.FromArgb(a, 220, 38, 38)))
                using (Pen scRim = new Pen(Color.FromArgb((int)(a * 0.85f), 153, 27, 27), Math.Max(0.65f, 0.7f * s))) {
                    g.FillPolygon(scBr, tailPts);
                    g.DrawPolygon(scRim, tailPts);
                    RectangleF neckBand = new RectangleF(-5.5f * s, -13.1f * s, 11.0f * s, 2.5f * s);
                    using (GraphicsPath nbp = CreateRoundedRect(neckBand, Math.Max(1f, 1.2f * s))) {
                        g.FillPath(scBr, nbp);
                        g.DrawPath(scRim, nbp);
                    }
                }
                using (Pen goldTrim = new Pen(Color.FromArgb((int)(a * 0.85f), 253, 224, 71), Math.Max(0.55f, 0.6f * s))) {
                    g.DrawLine(goldTrim, 3.0f * s, -7.8f * s, 5.2f * s, -7.4f * s);
                }

                // Rosy cheeks + coal eyes
                float chD = Math.Max(1.2f, 1.6f * s);
                using (SolidBrush cheek = new SolidBrush(Color.FromArgb((int)(a * 0.80f), 251, 113, 133))) {
                    g.FillEllipse(cheek, -3.2f * s - chD * 0.5f, -15.8f * s - chD * 0.5f, chD, chD);
                    g.FillEllipse(cheek, 2.8f * s - chD * 0.5f, -15.8f * s - chD * 0.5f, chD, chD);
                }
                float eyeD = Math.Max(1.1f, 1.45f * s);
                using (SolidBrush eyeBr = new SolidBrush(Color.FromArgb(a, 15, 23, 42))) {
                    g.FillEllipse(eyeBr, -1.9f * s - eyeD * 0.5f, -17.5f * s - eyeD * 0.5f, eyeD, eyeD);
                    g.FillEllipse(eyeBr, 1.5f * s - eyeD * 0.5f, -17.5f * s - eyeD * 0.5f, eyeD, eyeD);
                    if (height >= 18f) {
                        float smD = Math.Max(0.8f, 0.9f * s);
                        g.FillEllipse(eyeBr, -1.6f * s, -14.7f * s, smD, smD);
                        g.FillEllipse(eyeBr, -0.2f * s, -14.3f * s, smD, smD);
                        g.FillEllipse(eyeBr, 1.2f * s, -14.7f * s, smD, smD);
                    }
                }

                // Bright orange carrot nose pointing right
                PointF[] nosePts = new PointF[] {
                    new PointF(0.0f, -16.7f * s),
                    new PointF(4.8f * s, -15.9f * s),
                    new PointF(0.0f, -15.1f * s)
                };
                using (SolidBrush noseBr = new SolidBrush(Color.FromArgb(a, 249, 115, 22)))
                using (Pen noseRim = new Pen(Color.FromArgb((int)(a * 0.85f), 194, 65, 12), Math.Max(0.55f, 0.6f * s))) {
                    g.FillPolygon(noseBr, nosePts);
                    g.DrawPolygon(noseRim, nosePts);
                }

                // Classic dark top hat + crimson hatband + snow highlight
                RectangleF crownRect = new RectangleF(-4.3f * s, -27.2f * s, 8.6f * s, 5.4f * s);
                RectangleF brimRect  = new RectangleF(-6.7f * s, -22.2f * s, 13.4f * s, 2.0f * s);
                using (GraphicsPath crP = CreateRoundedRect(crownRect, Math.Max(1f, 1.1f * s)))
                using (GraphicsPath brP = CreateRoundedRect(brimRect, Math.Max(0.8f, 0.9f * s)))
                using (SolidBrush hatBr = new SolidBrush(Color.FromArgb(a, 30, 41, 59)))
                using (Pen hatRim = new Pen(Color.FromArgb((int)(a * 0.82f), lightBg ? 15 : 148, lightBg ? 23 : 163, lightBg ? 42 : 184), Math.Max(0.65f, 0.7f * s))) {
                    g.FillPath(hatBr, crP);
                    g.DrawPath(hatRim, crP);
                    using (SolidBrush bandBr = new SolidBrush(Color.FromArgb(a, 239, 68, 68))) {
                        g.FillRectangle(bandBr, -4.1f * s, -23.5f * s, 8.2f * s, 1.4f * s);
                    }
                    g.FillPath(hatBr, brP);
                    g.DrawPath(hatRim, brP);
                }
                using (SolidBrush hatSnow = new SolidBrush(Color.FromArgb((int)(a * 0.92f), 240, 249, 255))) {
                    g.FillEllipse(hatSnow, 0.8f * s, -27.7f * s, 3.2f * s, 1.2f * s);
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawWinterBranchCorner(Graphics g, float anchorX, float anchorY, float scale, bool flipX, bool flipY, float phase, int alpha, bool compact, bool lightBg) {
            if (scale < 0.22f || alpha <= 4) return;
            int a = Math.Max(0, Math.Min(255, alpha));
            float swayRot = (float)Math.Sin(phase * 1.0) * 3.0f;
            float spin1 = phase * 14f;
            float spin2 = -phase * 11f;
            float tw1 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5);
            float tw2 = 0.75f + 0.25f * (float)Math.Sin(phase * 1.5 + 1.9);
            float driftX = (float)Math.Sin(phase * 0.85) * 2.2f;
            float driftY = (float)Math.Cos(phase * 0.95) * 1.6f;

            GraphicsState gs = g.Save();
            try {
                g.TranslateTransform(anchorX, anchorY);
                g.ScaleTransform((flipX ? -1f : 1f) * scale, (flipY ? -1f : 1f) * scale);

                // Frosted ice-pine bough
                Color boughBase = lightBg ? Color.FromArgb((int)(a * 0.90f), 3, 105, 161) : Color.FromArgb((int)(a * 0.90f), 56, 189, 248);
                Color boughHi   = lightBg ? Color.FromArgb((int)(a * 0.78f), 125, 211, 252) : Color.FromArgb((int)(a * 0.78f), 224, 242, 254);
                using (Pen icePen = new Pen(boughBase, 2.2f))
                using (Pen iceHi  = new Pen(boughHi, 0.95f)) {
                    icePen.StartCap = LineCap.Round; icePen.EndCap = LineCap.Round;
                    iceHi.StartCap = LineCap.Round; iceHi.EndCap = LineCap.Round;
                    g.DrawBezier(icePen, -106f, -2f, -60f, 6f, -22f, -1f, 2f, 23f);
                    g.DrawBezier(icePen, -56f, 2f, -66f, 9f, -74f, 13f, -82f, 16f);
                    g.DrawBezier(iceHi, -104f, -2.6f, -59f, 5.2f, -21f, -1.8f, 1f, 22f);
                    if (!compact) {
                        g.DrawBezier(icePen, -22f, 4f, -11f, 3f, -3f, 5f, 3f, 12f);
                    }
                }

                DrawFourPointStar(g, -94f, -4f, 2.7f * tw1, lightBg ? Color.FromArgb(2, 132, 199) : Color.FromArgb(224, 242, 254), (int)(a * tw1), lightBg);
                DrawFourPointStar(g, -6f, -5f, 2.4f * tw2, lightBg ? Color.FromArgb(56, 189, 248) : Color.FromArgb(125, 211, 252), (int)(a * tw2), lightBg);

                DrawSnowDot(g, -64f, 11f, 4.8f, a, lightBg);
                DrawSnowDot(g, 1f, 31f, 4.4f, a, lightBg);
                DrawSnowDot(g, -96f + driftX, 8f + driftY, 5.0f, (int)(a * 0.94f), lightBg);
                DrawSnowDot(g, -54f - driftX * 0.7f, 17f + driftY * 1.1f, 4.6f, (int)(a * 0.90f), lightBg);
                if (!compact) {
                    DrawSnowDot(g, -15f + driftX * 0.5f, 33f + driftY * 0.8f, 4.4f, (int)(a * 0.88f), lightBg);
                }

                DrawSnowflake(g, -42f, -1f, 7.6f, spin1, a, lightBg);
                if (!compact) {
                    DrawSnowflake(g, -74f, 2f, 6.2f, spin2, a, lightBg);
                    DrawSnowflake(g, -3f, 20f, 6.6f, spin1 * 0.8f, a, lightBg);
                } else {
                    DrawSnowflake(g, -18f, 4f, 8.8f, spin2, Math.Min(255, a + 10), lightBg);
                }
            } finally {
                g.Restore(gs);
            }

            // Upright cute Snowman in unflipped top-right wide corners
            if (!flipX && !flipY && !compact) {
                float smH = Math.Max(14f, 23f * scale);
                float smX = anchorX - 24f * scale;
                float smY = anchorY + 25f * scale;
                using (SolidBrush ledge = new SolidBrush(Color.FromArgb((int)(a * 0.85f), lightBg ? 224 : 240, lightBg ? 242 : 249, 255)))
                using (Pen lRim = new Pen(lightBg ? Color.FromArgb((int)(a * 0.85f), 2, 132, 199) : Color.FromArgb((int)(a * 0.75f), 125, 211, 252), 0.9f)) {
                    RectangleF bank = new RectangleF(smX - 11f * scale, smY - 2.5f * scale, 22f * scale, 5.2f * scale);
                    g.FillEllipse(ledge, bank);
                    g.DrawEllipse(lRim, bank);
                }
                DrawSnowman(g, smX, smY, smH, swayRot, Math.Min(255, a + 10), lightBg);
            }
        }

