        private static Color GetSeasonTwigColor(int season, bool lightMode, int alpha) {
            switch (season) {
                case 1:
                case 4:
                    return lightMode ? Color.FromArgb(alpha, 21, 128, 61) : Color.FromArgb(alpha, 74, 222, 128);
                case 2:
                    return Color.FromArgb(alpha, 110, 52, 18);
                case 3:
                    return lightMode ? Color.FromArgb(alpha, 2, 132, 199) : Color.FromArgb(alpha, 125, 211, 252);
                case 5:
                    return lightMode ? Color.FromArgb(alpha, 220, 38, 38) : Color.FromArgb(alpha, 249, 115, 22);
                case 6:
                    return lightMode ? Color.FromArgb(alpha, 124, 58, 237) : Color.FromArgb(alpha, 168, 85, 247);
                case 7:
                    return lightMode ? Color.FromArgb(alpha, 13, 148, 136) : Color.FromArgb(alpha, 45, 212, 191);
                case 8:
                    return lightMode ? Color.FromArgb(alpha, 3, 105, 161) : Color.FromArgb(alpha, 14, 165, 233);
                case 9:
                    return lightMode ? Color.FromArgb(alpha, 180, 83, 9) : Color.FromArgb(alpha, 251, 146, 60);
                case 10:
                    return lightMode ? Color.FromArgb(alpha, 67, 56, 202) : Color.FromArgb(alpha, 129, 140, 248);
                case 11:
                    return lightMode ? Color.FromArgb(alpha, 5, 150, 105) : Color.FromArgb(alpha, 110, 231, 183);
                case 12:
                    return lightMode ? Color.FromArgb(alpha, 217, 119, 6) : Color.FromArgb(alpha, 250, 204, 21);
                case 13:
                    return lightMode ? Color.FromArgb(alpha, 3, 105, 161) : Color.FromArgb(alpha, 125, 211, 252);
                default:
                    return Color.FromArgb(alpha, 94, 40, 66);
            }
        }

        private static Color GetSeasonStarColor(int season, bool lightMode) {
            switch (season) {
                case 1:
                    return lightMode ? Color.FromArgb(234, 158, 12) : Color.FromArgb(254, 240, 138);
                case 2:
                    return lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(253, 224, 71);
                case 3:
                    return lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(224, 242, 254);
                case 4:
                    return lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138);
                case 5:
                    return lightMode ? Color.FromArgb(234, 88, 12) : Color.FromArgb(254, 240, 138);
                case 6:
                    return lightMode ? Color.FromArgb(124, 58, 237) : Color.FromArgb(254, 249, 195);
                case 7:
                    return lightMode ? Color.FromArgb(13, 148, 136) : Color.FromArgb(167, 243, 208);
                case 8:
                    return lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(224, 242, 254);
                case 9:
                    return lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138);
                case 10:
                    return lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(254, 249, 195);
                case 11:
                    return lightMode ? Color.FromArgb(13, 148, 136) : Color.FromArgb(209, 250, 229);
                case 12:
                    return lightMode ? Color.FromArgb(234, 88, 12) : Color.FromArgb(254, 249, 195);
                case 13:
                    return lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(224, 242, 254);
                default:
                    return lightMode ? Color.FromArgb(234, 158, 12) : Color.FromArgb(253, 224, 71);
            }
        }

        public static void DrawSeasonHeaderBanner(Graphics g, int season, float bx0, float bx1, float phase, Color warmCol, bool lightMode) {
            float sway = (float)Math.Sin(phase * 1.1) * 3.5f;
            float drift = (float)Math.Sin(phase * 0.9) * 2.4f;
            float midB = (bx0 + bx1) * 0.5f;

            switch (season) {
                case 1: // Mua Ha: Nang vang & Hoa huong duong + la xanh
                    using (Pen bPen = new Pen(Color.FromArgb(220, 21, 128, 61), 2.2f))
                    using (Pen bHi  = new Pen(lightMode ? Color.FromArgb(180, 74, 222, 128) : Color.FromArgb(175, 134, 239, 172), 0.95f)) {
                        bPen.StartCap = LineCap.Round; bPen.EndCap = LineCap.Round;
                        bHi.StartCap = LineCap.Round; bHi.EndCap = LineCap.Round;
                        g.DrawBezier(bPen, bx0, 26f, bx0 + (bx1 - bx0) * 0.35f, 15f, bx0 + (bx1 - bx0) * 0.68f, 27f, bx1, 14f);
                        g.DrawBezier(bPen, bx0 + 52f, 21f, bx0 + 68f, 14f, bx0 + 82f, 10f, bx0 + 96f, 9f);
                        g.DrawBezier(bHi,  bx0 + 2f, 25.2f, bx0 + (bx1 - bx0) * 0.35f, 14.2f, bx0 + (bx1 - bx0) * 0.68f, 26.2f, bx1 - 2f, 13.4f);
                    }
                    DrawSummerSun(g, bx1 - 24f, 16f, 10.6f, phase * 22f, 240, lightMode);
                    DrawSummerLeaf(g, bx0 + 96f, 9f, 5.6f, 68f + sway, 225, lightMode);
                    DrawSummerLeaf(g, bx0 + 4f + drift, 12f, 5.4f, -38f + sway * 2f, 215, lightMode);
                    DrawSummerLeaf(g, midB - 14f - drift, 31f, 5.8f, 42f - sway * 2f, 215, lightMode);
                    DrawSummerLeaf(g, midB + 26f + drift * 0.8f, 11f, 5.2f, -18f + sway * 2f, 210, lightMode);
                    DrawSummerLeaf(g, bx0 + 44f + drift * 0.6f, 34f, 5.0f, -52f, 205, lightMode);
                    DrawSunflower(g, bx0 + 26f, 22f, 7.8f, -14f + sway, 235, lightMode);
                    DrawSunflower(g, bx0 + 66f, 16f, 9.4f, 16f - sway, 242, lightMode);
                    DrawSunflower(g, bx1 - 54f, 24f, 6.8f, 24f + sway, 230, lightMode);
                    DrawFourPointStar(g, midB + 12f, 14f, 2.8f, lightMode ? Color.FromArgb(234, 158, 12) : Color.FromArgb(254, 240, 138), 220, lightMode);
                    break;

                case 2: // Mua Thu: Canh thu & La phong vang roi + hat de
                    using (Pen bPen = new Pen(Color.FromArgb(220, 110, 52, 18), 2.2f))
                    using (Pen bHi  = new Pen(lightMode ? Color.FromArgb(180, 217, 119, 6) : Color.FromArgb(175, 251, 191, 36), 0.95f)) {
                        bPen.StartCap = LineCap.Round; bPen.EndCap = LineCap.Round;
                        bHi.StartCap = LineCap.Round; bHi.EndCap = LineCap.Round;
                        g.DrawBezier(bPen, bx0, 26f, bx0 + (bx1 - bx0) * 0.35f, 15f, bx0 + (bx1 - bx0) * 0.68f, 27f, bx1, 14f);
                        g.DrawBezier(bPen, bx0 + 52f, 21f, bx0 + 68f, 14f, bx0 + 82f, 10f, bx0 + 96f, 9f);
                        g.DrawBezier(bHi,  bx0 + 2f, 25.2f, bx0 + (bx1 - bx0) * 0.35f, 14.2f, bx0 + (bx1 - bx0) * 0.68f, 26.2f, bx1 - 2f, 13.4f);
                    }
                    DrawAutumnAcorn(g, bx0 + 96f, 9f, 5.4f, 72f + sway, 225, lightMode);
                    DrawAutumnAcorn(g, bx1 - 20f, 26f, 5.2f, 145f - sway, 220, lightMode);
                    DrawAutumnMapleLeaf(g, bx0 + 26f, 22f, 7.6f, -14f + sway, Color.FromArgb(217, 119, 6), Color.FromArgb(253, 224, 71), 235, lightMode);
                    DrawAutumnMapleLeaf(g, bx0 + 66f, 16f, 9.4f, 16f - sway, Color.FromArgb(234, 88, 12), Color.FromArgb(250, 204, 21), 242, lightMode);
                    DrawAutumnMapleLeaf(g, midB + 8f, 20f, 7.0f, -22f + sway, Color.FromArgb(234, 88, 12), Color.FromArgb(251, 191, 36), 230, lightMode);
                    DrawAutumnMapleLeaf(g, bx1 - 36f, 19f, 6.8f, 24f + sway, Color.FromArgb(217, 119, 6), Color.FromArgb(253, 224, 71), 232, lightMode);
                    DrawAutumnLeaf(g, bx0 + 4f + drift, 12f, 5.6f, -38f + sway * 2f, Color.FromArgb(245, 158, 11), 215, lightMode);
                    DrawAutumnLeaf(g, midB - 14f - drift, 31f, 6.0f, 42f - sway * 2f, Color.FromArgb(234, 88, 12), 215, lightMode);
                    DrawAutumnLeaf(g, midB + 32f + drift * 0.8f, 11f, 5.2f, -18f + sway * 2f, Color.FromArgb(250, 204, 21), 210, lightMode);
                    DrawAutumnLeaf(g, bx1 - 6f - drift * 0.5f, 32f, 5.6f, 58f, Color.FromArgb(245, 158, 11), 210, lightMode);
