                    DrawSakuraFlower(g, bx0 + 26f, 22f, 7.4f, -14f + sway, warmCol, Color.FromArgb(255, 242, 248), Color.FromArgb(219, 39, 119), 235, lightMode);
                    DrawSakuraFlower(g, bx0 + 66f, 16f, 9.2f, 16f - sway, Color.FromArgb(255, 142, 194), Color.White, Color.FromArgb(225, 29, 72), 240, lightMode);
                    DrawSakuraFlower(g, bx1 - 36f, 20f, 6.4f, 24f + sway, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), 230, lightMode);
                    DrawSakuraPetal(g, bx0 + 4f + drift, 12f, 5.2f, -38f + sway * 2f, warmCol, 215, lightMode);
                    DrawSakuraPetal(g, midB - 14f - drift, 31f, 5.6f, 42f - sway * 2f, lightMode ? Color.FromArgb(248, 126, 180) : Color.FromArgb(255, 166, 206), 215, lightMode);
                    DrawSakuraPetal(g, midB + 26f + drift * 0.8f, 11f, 5.0f, -18f + sway * 2f, warmCol, 210, lightMode);
                    DrawSakuraPetal(g, bx1 - 6f - drift * 0.5f, 32f, 5.4f, 58f, Color.FromArgb(244, 114, 182), 210, lightMode);
                    DrawSakuraPetal(g, bx0 + 44f + drift * 0.6f, 34f, 4.8f, -52f, lightMode ? Color.FromArgb(244, 134, 186) : Color.FromArgb(255, 212, 232), 205, lightMode);
                    break;
            }
        }

        public static void DrawSeasonSidebarFooter(Graphics g, int season, float width, float fy, float phase, Color c1, Color c2, Color c3, Color warmCol, bool lightMode) {
            float sway = (float)Math.Sin(phase * 1.1) * 3.0f;
            float drift = (float)Math.Sin(phase * 0.9) * 1.8f;
            RectangleF fLineRect = new RectangleF(12f, fy - 1f, Math.Max(8f, width - 24f), 2f);
            using (LinearGradientBrush fGb = CreateGradientBrush(fLineRect, c1, c2, c3, 145))
            using (Pen fPen = new Pen(fGb, 1.2f)) {
                g.DrawLine(fPen, 12f, fy, width - 12f, fy);
            }

            switch (season) {
                case 1: // Mua Ha
                    using (Pen fbPen = new Pen(Color.FromArgb(215, 21, 128, 61), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 6f, width * 0.36f, fy - 4f, width * 0.66f, fy + 8f, width - 16f, fy - 4f);
                    }
                    DrawSummerSun(g, 24f, fy - 2f, 6.2f, phase * 20f, 230, lightMode);
                    DrawSunflower(g, width * 0.44f, fy + 2f, 6.4f, -15f + sway, 235, lightMode);
                    DrawSunflower(g, width * 0.72f, fy - 1f, 5.4f, 22f - sway, 228, lightMode);
                    DrawSummerLeaf(g, width * 0.25f + drift, fy + 10f, 5.0f, -35f, 210, lightMode);
                    DrawSummerLeaf(g, width - 22f - drift, fy + 9f, 4.8f, 44f, 210, lightMode);
                    break;

                case 2: // Mua Thu
                    using (Pen fbPen = new Pen(Color.FromArgb(215, 110, 52, 18), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 6f, width * 0.36f, fy - 4f, width * 0.66f, fy + 8f, width - 16f, fy - 4f);
                    }
                    DrawAutumnAcorn(g, 24f, fy + 10f, 4.8f, 115f + sway, 220, lightMode);
                    DrawAutumnMapleLeaf(g, width * 0.34f, fy + 1f, 6.2f, -15f + sway, Color.FromArgb(217, 119, 6), Color.FromArgb(253, 224, 71), 232, lightMode);
                    DrawAutumnMapleLeaf(g, width * 0.58f, fy + 2f, 7.4f, 14f - sway, Color.FromArgb(234, 88, 12), Color.FromArgb(250, 204, 21), 238, lightMode);
                    DrawAutumnMapleLeaf(g, width - 26f, fy - 3f, 5.6f, 28f + sway, Color.FromArgb(217, 119, 6), Color.FromArgb(253, 224, 71), 228, lightMode);
                    DrawAutumnLeaf(g, width * 0.20f + drift, fy - 8f, 5.0f, -35f, Color.FromArgb(245, 158, 11), 205, lightMode);
                    DrawAutumnLeaf(g, width * 0.78f - drift, fy + 11f, 4.8f, 44f, Color.FromArgb(234, 88, 12), 205, lightMode);
                    break;

                case 3: // Mua Dong: Nguoi tuyet xinh xan + bong tuyet
                    using (SolidBrush snowHill = new SolidBrush(lightMode ? Color.FromArgb(225, 224, 242, 254) : Color.FromArgb(185, 224, 242, 254)))
                    using (Pen hillRim = new Pen(lightMode ? Color.FromArgb(210, 2, 132, 199) : Color.FromArgb(190, 125, 211, 252), 1.0f)) {
                        RectangleF hill = new RectangleF(14f, fy + 8f, Math.Max(40f, width - 28f), 11f);
                        g.FillEllipse(snowHill, hill);
                        g.DrawArc(hillRim, hill, 185f, 170f);
                    }
                    DrawSnowman(g, width * 0.50f, fy + 15f, 30f, sway * 0.7f, 245, lightMode);
                    DrawSnowflake(g, 28f, fy + 2f, 6.2f, phase * 14f, 232, lightMode);
                    DrawSnowflake(g, width - 28f, fy + 1f, 6.0f, -phase * 13f, 232, lightMode);
                    DrawSnowflake(g, width * 0.24f, fy - 11f, 4.4f, -phase * 17f, 215, lightMode);
                    DrawSnowDot(g, width * 0.74f + drift, fy - 10f, 4.4f, 210, lightMode);
                    DrawSnowDot(g, width * 0.16f - drift, fy + 11f, 4.2f, 205, lightMode);
                    break;

                case 4: // Hoa Huong Duong
                    using (Pen fbPen = new Pen(Color.FromArgb(215, 21, 128, 61), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 6f, width * 0.36f, fy - 4f, width * 0.66f, fy + 8f, width - 16f, fy - 4f);
                    }
                    DrawSunflowerBud(g, 22f, fy + 8f, 4.8f, 115f + sway, 225, lightMode);
                    DrawSunflower(g, width * 0.30f, fy + 1f, 6.6f, -15f + sway, 236, lightMode);
                    DrawSunflower(g, width * 0.56f, fy + 2f, 7.6f, 14f - sway, 242, lightMode);
                    DrawSunflower(g, width - 26f, fy - 2f, 6.0f, 24f + sway, 232, lightMode);
                    DrawSummerLeaf(g, width * 0.42f, fy + 10f, 4.8f, 42f, 215, lightMode);
                    DrawSunflowerPetal(g, width * 0.19f + drift, fy - 8f, 5.0f, -35f, 210, lightMode);
                    DrawSunflowerPetal(g, width * 0.76f - drift, fy + 10f, 4.8f, 44f, 210, lightMode);
                    break;

                case 5: // Nguyen to Lua
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 220, 38, 38) : Color.FromArgb(215, 249, 115, 22), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 6f, width * 0.36f, fy - 4f, width * 0.66f, fy + 8f, width - 16f, fy - 4f);
                    }
                    DrawFireFlame(g, width * 0.28f, fy + 1f, 6.6f, -12f + sway, 236, lightMode);
                    DrawFireFlame(g, width * 0.54f, fy + 2f, 7.6f, 12f - sway, 242, lightMode);
                    DrawFireFlame(g, width - 26f, fy - 1f, 6.2f, -16f + sway, 232, lightMode);
                    DrawFireEmber(g, 24f + drift, fy - 7f, 4.8f, -20f, 215, lightMode);
                    DrawFireEmber(g, width * 0.75f - drift, fy + 10f, 4.8f, 26f, 215, lightMode);
                    break;

                case 6: // Nguyen to Sam Chop
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 124, 58, 237) : Color.FromArgb(215, 56, 189, 248), 1.8f)) {
                        fbPen.LineJoin = LineJoin.Round; fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawLines(fbPen, new PointF[] {
                            new PointF(16f, fy + 5f), new PointF(width * 0.34f, fy - 4f), new PointF(width * 0.52f, fy + 7f), new PointF(width * 0.72f, fy - 5f), new PointF(width - 16f, fy + 4f)
                        });
                    }
                    DrawLightningBoltIcon(g, width * 0.30f, fy + 1f, 6.8f, -14f + sway, 238, lightMode);
                    DrawLightningBoltIcon(g, width * 0.56f, fy + 1f, 7.6f, 14f - sway, 242, lightMode);
                    DrawLightningBoltIcon(g, width - 26f, fy - 1f, 6.2f, -12f + sway, 232, lightMode);
                    DrawLightningSpark(g, 24f, fy - 7f, 4.8f, phase * 32f, 220, lightMode);
                    DrawLightningSpark(g, width * 0.76f, fy + 10f, 4.6f, -phase * 30f, 215, lightMode);
                    break;

                case 7: // Nguyen to Loc Xoay
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 13, 148, 136) : Color.FromArgb(215, 45, 212, 191), 1.8f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 5f, width * 0.36f, fy - 5f, width * 0.66f, fy + 7f, width - 16f, fy - 4f);
                    }
                    DrawTornadoFunnel(g, width * 0.50f, fy + 14f, 26f, phase, 242, lightMode);
                    DrawTornadoVortex(g, 28f, fy + 2f, 6.2f, phase * 65f, 235, lightMode);
                    DrawTornadoVortex(g, width - 28f, fy + 1f, 6.0f, -phase * 60f, 235, lightMode);
                    DrawWindSwirlSpeck(g, width * 0.24f + drift, fy - 10f, 4.8f, -20f, 215, lightMode);
                    DrawWindSwirlSpeck(g, width * 0.75f - drift, fy + 10f, 4.6f, 32f, 210, lightMode);
                    break;

                case 8: // Nguyen to Song Than
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 3, 105, 161) : Color.FromArgb(215, 14, 165, 233), 2.1f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 6f, width * 0.36f, fy - 5f, width * 0.66f, fy + 8f, width - 16f, fy - 4f);
                    }
                    DrawTsunamiWaveIcon(g, width * 0.30f, fy + 1f, 6.8f, -8f + sway, 238, lightMode);
                    DrawTsunamiWaveIcon(g, width * 0.56f, fy + 1f, 7.8f, 8f - sway, 242, lightMode);
                    DrawTsunamiWaveIcon(g, width - 26f, fy - 1f, 6.4f, -6f + sway, 235, lightMode);
                    DrawSeaFoamDrop(g, 22f + drift, fy + 8f, 4.6f, 0f, 215, lightMode);
                    DrawSeaFoamDrop(g, width * 0.76f - drift, fy + 10f, 4.6f, 0f, 215, lightMode);
                    break;

                case 9: // Thien Thach (Meteor)
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 234, 88, 12) : Color.FromArgb(215, 249, 115, 22), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 5f, width * 0.36f, fy - 4f, width * 0.66f, fy + 7f, width - 16f, fy - 4f);
                    }
                    DrawMeteorIcon(g, width * 0.30f, fy + 1f, 5.8f, 16f + sway * 0.4f, 238, lightMode);
                    DrawMeteorIcon(g, width * 0.56f, fy + 1f, 6.8f, 20f - sway * 0.4f, 242, lightMode);
                    DrawMeteorIcon(g, width - 26f, fy - 1f, 5.6f, 18f + sway * 0.4f, 234, lightMode);
                    DrawFireEmber(g, 22f + drift, fy + 8f, 4.4f, -18f, 215, lightMode);
                    DrawFourPointStar(g, width * 0.76f - drift, fy + 10f, 2.5f, lightMode ? Color.FromArgb(109, 40, 217) : Color.FromArgb(254, 240, 138), 215, lightMode);
                    break;

                case 10: // Sao Bang (Shooting Star)
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 67, 56, 202) : Color.FromArgb(215, 125, 211, 252), 1.8f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 5f, width * 0.36f, fy - 4f, width * 0.66f, fy + 7f, width - 16f, fy - 4f);
                    }
                    DrawShootingStarIcon(g, width * 0.28f, fy + 1f, 6.0f, 14f, 238, lightMode);
                    DrawStarlightCrescent(g, width * 0.54f, fy + 1f, 5.8f, -18f + sway, 242, lightMode);
                    DrawShootingStarIcon(g, width - 26f, fy - 1f, 5.8f, 18f, 236, lightMode);
                    DrawFourPointStar(g, 24f + drift, fy - 7f, 2.5f, lightMode ? Color.FromArgb(2, 132, 199) : Color.FromArgb(125, 211, 252), 215, lightMode);
                    DrawFourPointStar(g, width * 0.76f - drift, fy + 10f, 2.5f, lightMode ? Color.FromArgb(217, 119, 6) : Color.FromArgb(254, 240, 138), 215, lightMode);
                    break;

                case 11: // Gio (Wind)
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 5, 150, 105) : Color.FromArgb(215, 110, 231, 183), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 5f, width * 0.36f, fy - 4f, width * 0.66f, fy + 7f, width - 16f, fy - 4f);
                    }
                    DrawWindGustIcon(g, width * 0.30f, fy + 1f, 6.4f, -6f + sway, 238, lightMode);
                    DrawWindGustIcon(g, width * 0.56f, fy + 1f, 7.2f, 8f - sway, 242, lightMode);
                    DrawWindGustIcon(g, width - 26f, fy - 1f, 6.2f, -6f + sway, 234, lightMode);
                    DrawWindSwirlSpeck(g, 24f + drift, fy - 7f, 4.6f, -18f, 215, lightMode);
                    DrawWindSwirlSpeck(g, width * 0.76f - drift, fy + 10f, 4.6f, 28f, 215, lightMode);
                    break;

                case 12: // Tia Nang (Sunbeams)
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 217, 119, 6) : Color.FromArgb(215, 250, 204, 21), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 5f, width * 0.36f, fy - 4f, width * 0.66f, fy + 7f, width - 16f, fy - 4f);
                    }
                    DrawSummerSun(g, width * 0.30f, fy + 1f, 6.4f, phase * 18f, 238, lightMode);
                    DrawSummerSun(g, width * 0.56f, fy + 1f, 7.4f, -phase * 15f, 242, lightMode);
                    DrawSummerSun(g, width - 26f, fy - 1f, 6.2f, phase * 16f, 234, lightMode);
                    DrawBokehMoteIcon(g, 22f + drift, fy + 8f, 4.4f, 215, lightMode);
                    DrawBokehMoteIcon(g, width * 0.76f - drift, fy + 10f, 4.6f, 215, lightMode);
                    break;

                case 13: // Mua (Rain)
                    using (Pen fbPen = new Pen(lightMode ? Color.FromArgb(215, 2, 132, 199) : Color.FromArgb(215, 125, 211, 252), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 5f, width * 0.36f, fy - 4f, width * 0.66f, fy + 7f, width - 16f, fy - 4f);
                    }
                    DrawRaindropIcon(g, width * 0.30f, fy + 1f, 5.2f, 12f + sway * 0.4f, 238, lightMode);
                    DrawRaindropIcon(g, width * 0.56f, fy + 1f, 6.0f, 10f - sway * 0.4f, 242, lightMode);
                    DrawRaindropIcon(g, width - 26f, fy - 1f, 5.2f, 14f + sway * 0.4f, 234, lightMode);
                    DrawRainRippleIcon(g, 24f + drift, fy + 8f, 4.6f, 215, lightMode);
                    DrawRainRippleIcon(g, width * 0.76f - drift, fy + 10f, 4.6f, 215, lightMode);
                    break;

                default: // Mua Xuan: Hoa Anh Dao (giu nguyen goc)
                    using (Pen fbPen = new Pen(Color.FromArgb(215, 94, 40, 66), 1.9f)) {
                        fbPen.StartCap = LineCap.Round; fbPen.EndCap = LineCap.Round;
                        g.DrawBezier(fbPen, 16f, fy + 6f, width * 0.36f, fy - 4f, width * 0.66f, fy + 8f, width - 16f, fy - 4f);
                    }
                    DrawSakuraBud(g, 24f, fy + 10f, 4.6f, 115f + sway, 220, lightMode);
                    DrawSakuraFlower(g, width * 0.32f, fy + 1f, 5.8f, -15f + sway, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), 230, lightMode);
                    DrawSakuraFlower(g, width * 0.56f, fy + 2f, 7.2f, 14f - sway, Color.FromArgb(255, 142, 194), Color.White, Color.FromArgb(225, 29, 72), 235, lightMode);
                    DrawSakuraFlower(g, width - 28f, fy - 3f, 5.2f, 28f + sway, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), 225, lightMode);
                    DrawSakuraPetal(g, width * 0.20f + drift, fy - 8f, 4.8f, -35f, warmCol, 205, lightMode);
                    DrawSakuraPetal(g, width * 0.78f - drift, fy + 11f, 4.6f, 44f, Color.FromArgb(255, 166, 206), 205, lightMode);
                    break;
            }
        }

        private static void DrawButtonOrnaments(Graphics g, RectangleF pill, float rad, int borderStyle, float phase, float hoverVisual, float pressClamp, bool enabled, int ornamentMode, bool lightBg, int ornamentSeason) {
            if (ornamentMode <= 0 || pill.Width < 24f || pill.Height < 14f) return;
            Color warmCol, coolCol;
            GetSeasonalOrnamentColors(ornamentSeason, borderStyle, lightBg, out warmCol, out coolCol);
            Color cCenter = Color.FromArgb(219, 39, 119);

            if (!enabled) {
                if (ornamentSeason == 0) {
                    DrawSakuraFlower(g, pill.X + 6.2f, pill.Y + 6.2f, 3.8f, -12f, warmCol, coolCol, cCenter, lightBg ? 105 : 85, lightBg);
                } else {
                    DrawSeasonEmblem(g, ornamentSeason, pill.X + 6.2f, pill.Y + 6.2f, 3.8f, -12f, warmCol, coolCol, lightBg ? 105 : 85, lightBg);
                }
                return;
            }

            int a = Math.Max(0, Math.Min(255, (int)Math.Round(210 + hoverVisual * 45 - pressClamp * 24)));
            float hs = 1f + 0.08f * hoverVisual;
            float sway = (float)Math.Sin(phase * 1.1) * 4.5f;
            float drift = (float)Math.Sin(phase * 0.9) * 1.6f;

            if (ornamentSeason != 0) {
                Color sTwigCol = GetSeasonTwigColor(ornamentSeason, lightBg, (int)(a * 0.85f));
                Color sStarCol = GetSeasonStarColor(ornamentSeason, lightBg);

                using (Pen twig = new Pen(sTwigCol, 1.35f)) {
                    twig.StartCap = LineCap.Round;
                    twig.EndCap = LineCap.Round;
                    g.DrawArc(twig, pill.X, pill.Y, Math.Max(8f, rad * 2f), Math.Max(8f, rad * 2f), 182f, 82f);
                }
                DrawSeasonEmblem(g, ornamentSeason, pill.X + 6.4f, pill.Y + 6.4f, Math.Min(5.2f, Math.Max(3.6f, pill.Height * 0.16f)) * hs, -15f + sway, warmCol, coolCol, a, lightBg);
                if (pill.Width >= 82f) {
                    DrawSeasonBud(g, ornamentSeason, pill.X + 13.8f, pill.Y + 3.6f, 3.8f * hs, 64f + sway, (int)(a * 0.92f), lightBg);
                }
                if (ornamentMode == 1) {
                    if (pill.Width >= 110f) {
                        DrawSeasonBud(g, ornamentSeason, pill.Right - 22f, pill.Y + 3.6f, 3.8f, 115f, (int)(a * 0.88f), lightBg);
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 32f + drift, pill.Y + 5.5f, 4.6f, -32f + sway, warmCol, (int)(a * 0.90f), lightBg);
                    }
                } else if (ornamentMode == 2) {
                    if (pill.Width >= 145f) {
                        using (Pen rTwig = new Pen(sTwigCol, 1.55f)) {
                            rTwig.StartCap = LineCap.Round;
                            rTwig.EndCap = LineCap.Round;
                            g.DrawBezier(rTwig, pill.Right - 42f, pill.Y + 1.5f, pill.Right - 22f, pill.Y + 5.5f, pill.Right - 9f, pill.Y + 2.5f, pill.Right - 2.5f, pill.Y + 14.5f);
                        }
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 38f + drift, pill.Y + 6.8f, 4.5f * hs, -38f + sway, warmCol, (int)(a * 0.88f), lightBg);
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 27f - drift * 0.6f, pill.Y + 4.0f, 4.8f * hs, 24f - sway, warmCol, (int)(a * 0.92f), lightBg);
                        DrawSeasonBud(g, ornamentSeason, pill.Right - 20f, pill.Y + 8.5f, 4.0f * hs, 132f + sway, a, lightBg);
                        DrawSeasonEmblem(g, ornamentSeason, pill.Right - 14f, pill.Y + 5.5f, 5.2f * hs, 14f - sway, warmCol, coolCol, a, lightBg);
                        DrawSeasonEmblem(g, ornamentSeason, pill.Right - 5.5f, pill.Y + 12.5f, 4.0f * hs, 32f + sway, warmCol, coolCol, a, lightBg);
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 9f + drift * 0.4f, pill.Bottom - 4.8f, 4.3f * hs, 46f, warmCol, (int)(a * 0.85f), lightBg);
                        DrawFourPointStar(g, pill.Right - 18f, pill.Bottom - 4.2f, 2.2f, sStarCol, (int)(a * 0.82f), lightBg);
                    } else if (pill.Width >= 82f) {
                        using (Pen mTwig = new Pen(sTwigCol, 1.4f)) {
                            mTwig.StartCap = LineCap.Round;
                            mTwig.EndCap = LineCap.Round;
                            g.DrawBezier(mTwig, pill.Right - 24f, pill.Y + 2f, pill.Right - 13f, pill.Y + 5f, pill.Right - 6f, pill.Y + 3f, pill.Right - 2.5f, pill.Y + 12f);
                        }
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 21f + drift, pill.Y + 4.5f, 4.4f * hs, -34f + sway, warmCol, (int)(a * 0.90f), lightBg);
                        DrawSeasonEmblem(g, ornamentSeason, pill.Right - 9.5f, pill.Y + 5.5f, 4.8f * hs, 18f - sway, warmCol, coolCol, a, lightBg);
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 9f, pill.Bottom - 4.5f, 4.0f * hs, 42f, warmCol, (int)(a * 0.84f), lightBg);
                    } else {
                        using (Pen sTwig = new Pen(sTwigCol, 1.2f)) {
                            sTwig.StartCap = LineCap.Round;
                            sTwig.EndCap = LineCap.Round;
                            g.DrawArc(sTwig, pill.Right - 14f, pill.Y, 13f, 11f, 275f, 80f);
                        }
                        DrawSeasonDrift(g, ornamentSeason, pill.Right - 6.8f, pill.Y + 5.2f, 4.2f * hs, 28f + sway, warmCol, a, lightBg);
                        DrawFourPointStar(g, pill.Right - 6f, pill.Bottom - 4.5f, 2.0f, sStarCol, (int)(a * 0.85f), lightBg);
                    }
                }
                return;
            }

            // Top-left delicate sakura corner twig + blossom
            using (Pen twig = new Pen(Color.FromArgb((int)(a * 0.85f), 94, 40, 66), 1.35f)) {
                twig.StartCap = LineCap.Round;
                twig.EndCap = LineCap.Round;
                g.DrawArc(twig, pill.X, pill.Y, Math.Max(8f, rad * 2f), Math.Max(8f, rad * 2f), 182f, 82f);
            }
            DrawSakuraFlower(g, pill.X + 6.4f, pill.Y + 6.4f, Math.Min(5.2f, Math.Max(3.6f, pill.Height * 0.16f)) * hs, -15f + sway, warmCol, Color.FromArgb(255, 242, 248), cCenter, a, lightBg);
            if (pill.Width >= 82f) {
                DrawSakuraBud(g, pill.X + 13.8f, pill.Y + 3.2f, 4.0f * hs, 64f + sway, (int)(a * 0.92f), lightBg);
            }

            Color starCol = lightBg ? Color.FromArgb(234, 158, 12) : Color.FromArgb(253, 224, 71);
            if (ornamentMode == 1) {
                if (pill.Width >= 110f) {
                    DrawSakuraBud(g, pill.Right - 22f, pill.Y + 3.2f, 4.0f, 115f, (int)(a * 0.88f), lightBg);
                    DrawSakuraPetal(g, pill.Right - 32f + drift, pill.Y + 5.5f, 4.6f, -32f + sway, warmCol, (int)(a * 0.90f), lightBg);
                }
            } else if (ornamentMode == 2) {
                if (pill.Width >= 145f) {
                    using (Pen rTwig = new Pen(Color.FromArgb((int)(a * 0.88f), 94, 40, 66), 1.55f)) {
                        rTwig.StartCap = LineCap.Round;
                        rTwig.EndCap = LineCap.Round;
                        g.DrawBezier(rTwig, pill.Right - 42f, pill.Y + 1.5f, pill.Right - 22f, pill.Y + 5.5f, pill.Right - 9f, pill.Y + 2.5f, pill.Right - 2.5f, pill.Y + 14.5f);
                    }
                    DrawSakuraPetal(g, pill.Right - 38f + drift, pill.Y + 6.8f, 4.5f * hs, -38f + sway, warmCol, (int)(a * 0.88f), lightBg);
                    DrawSakuraPetal(g, pill.Right - 27f - drift * 0.6f, pill.Y + 4.0f, 4.8f * hs, 24f - sway, Color.FromArgb(255, 166, 206), (int)(a * 0.92f), lightBg);
                    DrawSakuraBud(g, pill.Right - 20f, pill.Y + 8.5f, 4.2f * hs, 132f + sway, a, lightBg);
                    DrawSakuraFlower(g, pill.Right - 14f, pill.Y + 5.5f, 5.4f * hs, 14f - sway, warmCol, Color.FromArgb(255, 245, 250), cCenter, a, lightBg);
                    DrawSakuraFlower(g, pill.Right - 5.5f, pill.Y + 12.5f, 4.1f * hs, 32f + sway, Color.FromArgb(255, 152, 200), Color.White, cCenter, a, lightBg);
                    DrawSakuraPetal(g, pill.Right - 9f + drift * 0.4f, pill.Bottom - 4.8f, 4.3f * hs, 46f, warmCol, (int)(a * 0.85f), lightBg);
                    DrawFourPointStar(g, pill.Right - 18f, pill.Bottom - 4.2f, 2.2f, starCol, (int)(a * 0.82f), lightBg);
                } else if (pill.Width >= 82f) {
                    using (Pen mTwig = new Pen(Color.FromArgb((int)(a * 0.86f), 94, 40, 66), 1.4f)) {
                        mTwig.StartCap = LineCap.Round;
                        mTwig.EndCap = LineCap.Round;
                        g.DrawBezier(mTwig, pill.Right - 24f, pill.Y + 2f, pill.Right - 13f, pill.Y + 5f, pill.Right - 6f, pill.Y + 3f, pill.Right - 2.5f, pill.Y + 12f);
                    }
                    DrawSakuraPetal(g, pill.Right - 21f + drift, pill.Y + 4.5f, 4.4f * hs, -34f + sway, warmCol, (int)(a * 0.90f), lightBg);
                    DrawSakuraFlower(g, pill.Right - 9.5f, pill.Y + 5.5f, 5.0f * hs, 18f - sway, warmCol, Color.FromArgb(255, 242, 248), cCenter, a, lightBg);
                    DrawSakuraPetal(g, pill.Right - 9f, pill.Bottom - 4.5f, 4.0f * hs, 42f, Color.FromArgb(255, 166, 206), (int)(a * 0.84f), lightBg);
                } else {
                    using (Pen sTwig = new Pen(Color.FromArgb((int)(a * 0.85f), 94, 40, 66), 1.2f)) {
                        sTwig.StartCap = LineCap.Round;
                        sTwig.EndCap = LineCap.Round;
                        g.DrawArc(sTwig, pill.Right - 14f, pill.Y, 13f, 11f, 275f, 80f);
                    }
                    DrawSakuraPetal(g, pill.Right - 6.8f, pill.Y + 5.2f, 4.2f * hs, 28f + sway, warmCol, a, lightBg);
                    DrawFourPointStar(g, pill.Right - 6f, pill.Bottom - 4.5f, 2.0f, starCol, (int)(a * 0.85f), lightBg);
                }
            }
        }

        public static GraphicsPath CreateRoundedRect(RectangleF r, float radius) {
            GraphicsPath path = new GraphicsPath();
            float w = Math.Max(1f, r.Width);
            float h = Math.Max(1f, r.Height);
            float rad = Math.Max(0.5f, Math.Min(radius, Math.Min(w, h) * 0.5f));
            float d = rad * 2f;
            path.AddArc(r.X, r.Y, d, d, 180f, 90f);
            path.AddArc(r.X + w - d, r.Y, d, d, 270f, 90f);
            path.AddArc(r.X + w - d, r.Y + h - d, d, d, 0f, 90f);
            path.AddArc(r.X, r.Y + h - d, d, d, 90f, 90f);
            path.CloseFigure();
            return path;
        }

        public static LinearGradientBrush CreateGradientBrush(RectangleF r, Color c1, Color c2, Color c3, int alpha) {
            RectangleF safe = new RectangleF(r.X - 1f, r.Y - 1f, Math.Max(4f, r.Width + 2f), Math.Max(4f, r.Height + 2f));
            LinearGradientBrush br = new LinearGradientBrush(safe, Color.FromArgb(alpha, c1), Color.FromArgb(alpha, c3), LinearGradientMode.Horizontal);
            ColorBlend cb = new ColorBlend(3);
            cb.Positions = new float[] { 0f, 0.5f, 1f };
            cb.Colors = new Color[] { Color.FromArgb(alpha, c1), Color.FromArgb(alpha, c2), Color.FromArgb(alpha, c3) };
            br.InterpolationColors = cb;
            return br;
        }

        private static Color BlendWithWhite(Color c, float amount) {
            float t = Math.Max(0f, Math.Min(1f, amount));
            int r = (int)Math.Round(c.R + (255 - c.R) * t);
            int g = (int)Math.Round(c.G + (255 - c.G) * t);
            int b = (int)Math.Round(c.B + (255 - c.B) * t);
            return Color.FromArgb(255, Math.Max(0, Math.Min(255, r)), Math.Max(0, Math.Min(255, g)), Math.Max(0, Math.Min(255, b)));
        }

        private static Color DarkenColor(Color c, float amount) {
            float t = Math.Max(0f, Math.Min(1f, 1f - amount));
            int r = (int)Math.Round(c.R * t);
            int g = (int)Math.Round(c.G * t);
            int b = (int)Math.Round(c.B * t);
            return Color.FromArgb(255, Math.Max(0, Math.Min(255, r)), Math.Max(0, Math.Min(255, g)), Math.Max(0, Math.Min(255, b)));
        }

        private static void DrawHoverFxOverlay(Graphics g, GraphicsPath clipPath, RectangleF pill, Color accentColor, float hoverT, float pressClamp, ButtonAnimState anim, bool lightMode) {
            if (pill.Width < 4f || pill.Height < 4f) return;
            float vis = 1f - pressClamp * 0.78f;
            if ((hoverT <= 0.02f && (anim == null || !anim.HoverSweepActive)) || vis <= 0.05f) return;

            GraphicsState gs = g.Save();
            try {
                g.SetClip(clipPath, CombineMode.Intersect);
                if (hoverT > 0.02f && anim != null && anim.HasHoverPos) {
                    float r = Math.Max(14f, Math.Min(Math.Max(pill.Width, pill.Height) * 0.65f, 88f));
                    float cx = Math.Max(pill.X, Math.Min(pill.Right, anim.HoverPos.X));
                    float cy = Math.Max(pill.Y, Math.Min(pill.Bottom, anim.HoverPos.Y));
                    int a = Math.Max(0, Math.Min(255, (int)Math.Round(hoverT * vis * (lightMode ? 58f : 78f))));
                    if (a > 2) {
                        RectangleF spotRect = new RectangleF(cx - r, cy - r, r * 2f, r * 2f);
                        using (GraphicsPath sp = new GraphicsPath()) {
                            sp.AddEllipse(spotRect);
                            using (PathGradientBrush pgb = new PathGradientBrush(sp)) {
                                pgb.CenterPoint = new PointF(cx, cy);
                                Color spotCol = lightMode ? accentColor : BlendWithWhite(accentColor, 0.65f);
                                pgb.CenterColor = Color.FromArgb(a, spotCol);
                                pgb.SurroundColors = new Color[] { Color.FromArgb(0, accentColor) };
                                g.FillPath(pgb, sp);
                            }
                        }
                    }
                }
                if (anim != null && anim.HoverSweepActive && anim.HoverSweepT < 1f) {
                    float fade = (float)Math.Sin(anim.HoverSweepT * Math.PI);
                    int sa = Math.Max(0, Math.Min(255, (int)Math.Round(fade * vis * (lightMode ? 72f : 86f))));
                    if (sa > 2) {
                        float bandW = Math.Max(18f, pill.Width * 0.26f);
                        float sx = pill.X - bandW + anim.HoverSweepT * (pill.Width + bandW * 2f);
                        float skew = pill.Height * 0.42f;
                        PointF[] poly = new PointF[] {
                            new PointF(sx + skew, pill.Y - 2f),
                            new PointF(sx + bandW + skew, pill.Y - 2f),
                            new PointF(sx + bandW, pill.Bottom + 2f),
                            new PointF(sx, pill.Bottom + 2f)
                        };
                        Color sweepCol = lightMode ? BlendWithWhite(accentColor, 0.18f) : Color.White;
                        using (LinearGradientBrush sbr = new LinearGradientBrush(new PointF(sx, pill.Y), new PointF(sx + bandW, pill.Y), Color.FromArgb(0, sweepCol), Color.FromArgb(0, sweepCol))) {
                            ColorBlend cb = new ColorBlend(3);
                            cb.Positions = new float[] { 0f, 0.5f, 1f };
                            cb.Colors = new Color[] { Color.FromArgb(0, sweepCol), Color.FromArgb(sa, sweepCol), Color.FromArgb(0, sweepCol) };
                            sbr.InterpolationColors = cb;
                            g.FillPolygon(sbr, poly);
                        }
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        private static void DrawPressRecessOverlay(Graphics g, GraphicsPath clipPath, RectangleF pill, float pressClamp, bool lightMode) {
            if (pressClamp <= 0.01f || pill.Width < 4f || pill.Height < 4f) return;
            GraphicsState gs = g.Save();
            try {
                g.SetClip(clipPath, CombineMode.Intersect);
                int darkA = Math.Max(0, Math.Min(255, (int)Math.Round(pressClamp * (lightMode ? 30f : 56f))));
                if (darkA > 1) {
                    using (SolidBrush dbr = new SolidBrush(Color.FromArgb(darkA, 0, 0, 0))) {
                        g.FillRectangle(dbr, pill);
                    }
                }
                float shadowH = Math.Max(2.5f, Math.Min(pill.Height * 0.45f, 7.5f));
                int topShA = Math.Max(0, Math.Min(255, (int)Math.Round(pressClamp * (lightMode ? 90f : 148f))));
                if (topShA > 2) {
                    using (LinearGradientBrush tsh = new LinearGradientBrush(new PointF(pill.X, pill.Y), new PointF(pill.X, pill.Y + shadowH), Color.FromArgb(topShA, 0, 0, 0), Color.FromArgb(0, 0, 0, 0))) {
                        g.FillRectangle(tsh, pill.X, pill.Y, pill.Width, shadowH);
                    }
                }
                float sideW = Math.Max(2f, Math.Min(pill.Width * 0.14f, 4.5f));
                int sideA = Math.Max(0, Math.Min(255, (int)Math.Round(pressClamp * (lightMode ? 42f : 72f))));
                if (sideA > 2) {
                    using (LinearGradientBrush ssh = new LinearGradientBrush(new PointF(pill.X, pill.Y), new PointF(pill.X + sideW, pill.Y), Color.FromArgb(sideA, 0, 0, 0), Color.FromArgb(0, 0, 0, 0))) {
                        g.FillRectangle(ssh, pill.X, pill.Y, sideW, pill.Height);
                    }
                }
                if (pill.Width > 10f) {
                    int lipA = Math.Max(0, Math.Min(255, (int)Math.Round(pressClamp * (lightMode ? 35f : 52f))));
                    if (lipA > 2) {
                        using (Pen lp = new Pen(Color.FromArgb(lipA, 255, 255, 255), 1f)) {
                            g.DrawLine(lp, pill.X + 4f, pill.Bottom - 1f, pill.Right - 4f, pill.Bottom - 1f);
                        }
                    }
                }
            } finally {
                g.Restore(gs);
            }
        }

        public static void DrawGlowingPill(Graphics g, Rectangle bounds, Color c1, Color c2, Color c3, Color fillTop, Color fillBot, float radius, bool hovered, bool pressed, bool doubleInnerGold, bool enabled) {
            DrawGlowingPill(g, bounds, c1, c2, c3, fillTop, fillBot, radius, hovered ? 1f : 0f, pressed ? 1f : 0f, doubleInnerGold, enabled, null, 0, 0f, 0, false, 0);
        }

        public static void DrawGlowingPill(Graphics g, Rectangle bounds, Color c1, Color c2, Color c3, Color fillTop, Color fillBot, float radius, bool hovered, bool pressed, bool doubleInnerGold, bool enabled, int borderStyle, float phase, int ornamentMode) {
            DrawGlowingPill(g, bounds, c1, c2, c3, fillTop, fillBot, radius, hovered ? 1f : 0f, pressed ? 1f : 0f, doubleInnerGold, enabled, null, borderStyle, phase, ornamentMode, false, 0);
        }

        public static void DrawGlowingPill(Graphics g, Rectangle bounds, Color c1, Color c2, Color c3, Color fillTop, Color fillBot, float radius, bool hovered, bool pressed, bool doubleInnerGold, bool enabled, int borderStyle, float phase, int ornamentMode, bool lightMode) {
            DrawGlowingPill(g, bounds, c1, c2, c3, fillTop, fillBot, radius, hovered ? 1f : 0f, pressed ? 1f : 0f, doubleInnerGold, enabled, null, borderStyle, phase, ornamentMode, lightMode, 0);
        }

        public static void DrawGlowingPill(Graphics g, Rectangle bounds, Color c1, Color c2, Color c3, Color fillTop, Color fillBot, float radius, bool hovered, bool pressed, bool doubleInnerGold, bool enabled, int borderStyle, float phase, int ornamentMode, bool lightMode, int ornamentSeason) {
            DrawGlowingPill(g, bounds, c1, c2, c3, fillTop, fillBot, radius, hovered ? 1f : 0f, pressed ? 1f : 0f, doubleInnerGold, enabled, null, borderStyle, phase, ornamentMode, lightMode, ornamentSeason);
        }

        private static void DrawGlowingPill(Graphics g, Rectangle bounds, Color c1, Color c2, Color c3, Color fillTop, Color fillBot, float radius, float hoverT, float pressDepth, bool doubleInnerGold, bool enabled, ButtonAnimState anim, int borderStyle, float phase, int ornamentMode, bool lightMode, int ornamentSeason) {
            if (bounds.Width <= 4 || bounds.Height <= 4) return;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;

            float pressClamp = Math.Max(0f, Math.Min(1f, pressDepth));
            float hoverVisual = hoverT * (1f - pressClamp * 0.78f);
            float hoverLiftY = -0.85f * hoverVisual;
            float squishX = pressDepth * 2.1f;
            float squishY = pressDepth * 1.4f;
            float pressOffsetY = pressDepth * 2.15f;

            float pillX = Math.Max(bounds.X + 1.0f, bounds.X + 2f + squishX);
            float pillY = Math.Max(bounds.Y + 0.8f, bounds.Y + 2f + hoverLiftY + squishY + pressOffsetY);
            float maxW = Math.Max(4f, bounds.Width - 2.5f);
            float maxH = Math.Max(4f, bounds.Height - 2.5f);
            float pillW = Math.Max(4f, Math.Min(maxW, bounds.Width - 5f - squishX * 2f));
            float pillH = Math.Max(4f, Math.Min(maxH, bounds.Height - 5f - squishY * 2f));
            RectangleF pill = new RectangleF(pillX, pillY, pillW, pillH);
            float rad = Math.Max(1f, radius - pressClamp * 1.1f);

            if (enabled) {
                int glow1Alpha = Math.Max(0, Math.Min(255, (int)Math.Round((lightMode ? 28 : 32) + hoverVisual * (lightMode ? 58 : 70) - pressClamp * 12)));
                int glow2Alpha = Math.Max(0, Math.Min(255, (int)Math.Round((lightMode ? 52 : 60) + hoverVisual * (lightMode ? 88 : 102) - pressClamp * 18)));
                float pw1 = Math.Max(1.0f, 4.6f + hoverVisual * 1.5f - pressClamp * 1.2f);
                float pw2 = Math.Max(1.0f, 2.6f + hoverVisual * 0.8f - pressClamp * 0.5f);
                using (GraphicsPath gp = CreateRoundedRect(pill, rad)) {
                    using (LinearGradientBrush gb1 = CreateGradientBrush(pill, c1, c2, c3, glow1Alpha))
                    using (Pen p1 = new Pen(gb1, pw1)) {
                        p1.LineJoin = LineJoin.Round;
                        g.DrawPath(p1, gp);
                    }
                    using (LinearGradientBrush gb2 = CreateGradientBrush(pill, c1, c2, c3, glow2Alpha))
                    using (Pen p2 = new Pen(gb2, pw2)) {
                        p2.LineJoin = LineJoin.Round;
                        g.DrawPath(p2, gp);
                    }
                }
            }

            using (GraphicsPath fp = CreateRoundedRect(pill, rad)) {
                using (LinearGradientBrush fillBr = new LinearGradientBrush(new RectangleF(pill.X, pill.Y - 1f, pill.Width, pill.Height + 2f), fillTop, fillBot, LinearGradientMode.Vertical)) {
                    g.FillPath(fillBr, fp);
                }
                if (enabled) {
                    int sheenAlpha = Math.Max(0, Math.Min(255, (int)Math.Round((lightMode ? 34 : 24) + hoverVisual * (lightMode ? 46 : 42) - pressClamp * 14)));
                    Color sheenCol = lightMode ? Color.FromArgb(sheenAlpha, c2) : Color.FromArgb(sheenAlpha, BlendWithWhite(c2, 0.35f));
                    RectangleF innerSheen = new RectangleF(pill.X + 1.2f, pill.Y + 1.2f, Math.Max(2f, pill.Width - 2.4f), Math.Max(2f, pill.Height - 2.4f));
                    using (GraphicsPath sp = CreateRoundedRect(innerSheen, Math.Max(1f, rad - 1.2f)))
                    using (Pen sheenPen = new Pen(sheenCol, 1f)) {
                        g.DrawPath(sheenPen, sp);
                    }
                    int igBase = (doubleInnerGold || ornamentSeason == 2) ? 94 : 78;
                    int igAlpha = Math.Max(0, Math.Min(255, (int)Math.Round(igBase + hoverVisual * 60 - pressClamp * 25)));
                    Color innerCol = lightMode
                        ? Color.FromArgb(igAlpha, c1)
                        : Color.FromArgb(igAlpha, BlendWithWhite(c2, 0.25f));
                    RectangleF innerGold = new RectangleF(pill.X + 2.6f, pill.Y + 2.6f, Math.Max(2f, pill.Width - 5.2f), Math.Max(2f, pill.Height - 5.2f));
                    using (GraphicsPath igp = CreateRoundedRect(innerGold, Math.Max(1f, rad - 2.5f)))
                    using (Pen igPen = new Pen(innerCol, 1f)) {
                        g.DrawPath(igPen, igp);
                    }
                    DrawHoverFxOverlay(g, fp, pill, c2, hoverT, pressClamp, anim, lightMode);
                    DrawPressRecessOverlay(g, fp, pill, pressClamp, lightMode);
                }
                int borderAlpha = enabled
                    ? Math.Max(0, Math.Min(255, (int)Math.Round((lightMode ? 235 : 230) + hoverVisual * (lightMode ? 20 : 25) - pressClamp * 24)))
                    : (lightMode ? 145 : 95);
                using (LinearGradientBrush gb = CreateGradientBrush(pill, c1, c2, c3, borderAlpha))
                using (Pen borderPen = new Pen(gb, 1.65f + hoverVisual * 0.40f)) {
                    borderPen.LineJoin = LineJoin.Round;
                    g.DrawPath(borderPen, fp);
                }
            }
            if (ornamentMode > 0) {
                DrawButtonOrnaments(g, pill, rad, borderStyle, phase, hoverVisual, pressClamp, enabled, ornamentMode, lightMode, ornamentSeason);
            }
        }

        private int GetLayerModeForControl(Control ctrl) {
            if (ctrl == null || ctrl == _form) return 0;
            if (_navLeaves.Contains(ctrl)) return 2;
            if (ctrl.Parent == _form) return 0;
            if (ctrl.Parent != null && _navContainers.Contains(ctrl.Parent)) return 2;
            return 1;
        }

        public void PaintAlignedLayer(Graphics g, Control ctrl, bool useNavLayer) {
            PaintAlignedLayerMode(g, ctrl, useNavLayer ? 2 : 1);
        }

        public void PaintAlignedParentLayer(Graphics g, Control ctrl) {
            PaintAlignedLayerMode(g, ctrl, GetLayerModeForControl(ctrl));
        }

        public void PaintAlignedLayerMode(Graphics g, Control ctrl, int layerMode) {
            if (!_isActive || _form == null || !_form.IsHandleCreated || !ctrl.IsHandleCreated) return;
            Point pt = Point.Empty;
            try {
                if (ctrl != _form) {
                    pt = _form.PointToClient(ctrl.PointToScreen(Point.Empty));
                }
            } catch {
                pt = Point.Empty;
            }

            lock (_frameLock) {
                Bitmap bmp = (layerMode == 0) ? _layerRaw : ((layerMode == 2) ? _layerNav : _layerPanel);
                if (bmp == null) bmp = _layerRaw;
                if (bmp == null) return;
                Rectangle bounds = new Rectangle(0, 0, bmp.Width, bmp.Height);
                Rectangle req = new Rectangle(pt.X, pt.Y, ctrl.Width, ctrl.Height);
                Rectangle src = Rectangle.Intersect(bounds, req);
                if (src.IsEmpty) {
                    using (SolidBrush fb = new SolidBrush(Color.FromArgb(15, 23, 42))) {
                        g.FillRectangle(fb, 0, 0, ctrl.Width, ctrl.Height);
                    }
                    return;
                }
                if (src.Width != ctrl.Width || src.Height != ctrl.Height) {
                    using (SolidBrush fb = new SolidBrush(Color.FromArgb(15, 23, 42))) {
                        g.FillRectangle(fb, 0, 0, ctrl.Width, ctrl.Height);
                    }
                }
                Rectangle dst = new Rectangle(src.X - pt.X, src.Y - pt.Y, src.Width, src.Height);
                g.CompositingMode = CompositingMode.SourceCopy;
                g.DrawImage(bmp, dst, src, GraphicsUnit.Pixel);
                g.CompositingMode = CompositingMode.SourceOver;
            }
        }

        private void OnFormPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, _form);
            } else {
                lock (_frameLock) {
                    if (_layerRaw == null) return;
                    e.Graphics.CompositingMode = CompositingMode.SourceCopy;
                    e.Graphics.DrawImageUnscaled(_layerRaw, 0, 0);
                    e.Graphics.CompositingMode = CompositingMode.SourceOver;
                }
                PaintParticlesOverlay(e.Graphics, _form, false);
            }
            if (_showOrnaments && _form.ClientSize.Width > 80 && _form.ClientSize.Height > 40) {
                e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
                float phase = GetAmbientPhase();
                Color c1, c2, c3, warmCol, coolCol;
                GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
                GetSeasonalOrnamentColors(_ornamentSeason, _borderStyle, lightMode, out warmCol, out coolCol);
                float yLine = _form.ClientSize.Height - 23f;
                RectangleF hr = new RectangleF(12f, yLine - 2f, Math.Max(12f, _form.ClientSize.Width - 24f), 4f);
                using (LinearGradientBrush gbGlow = CreateGradientBrush(hr, c1, c2, c3, lightMode ? 48 : 55))
                using (Pen gPen = new Pen(gbGlow, 2.8f)) {
                    e.Graphics.DrawLine(gPen, 16f, yLine, _form.ClientSize.Width - 16f, yLine);
                }
                using (LinearGradientBrush gb = CreateGradientBrush(hr, c1, c2, c3, lightMode ? 185 : 170))
                using (Pen hPen = new Pen(gb, 1.4f)) {
                    e.Graphics.DrawLine(hPen, 16f, yLine, _form.ClientSize.Width - 16f, yLine);
                }
                float drift = (float)Math.Sin(phase * 0.9) * 2.0f;
                if (_ornamentSeason == 0) {
                    DrawSakuraFlower(e.Graphics, 18f, yLine, 4.2f, -12f, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), 225, lightMode);
                    DrawSakuraFlower(e.Graphics, _form.ClientSize.Width - 18f, yLine, 4.2f, 18f, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), 225, lightMode);
                    DrawSakuraPetal(e.Graphics, 32f + drift, yLine - 3f, 4.4f, -35f, warmCol, 200, lightMode);
                    DrawSakuraPetal(e.Graphics, _form.ClientSize.Width - 32f - drift, yLine + 2f, 4.4f, 42f, Color.FromArgb(255, 166, 206), 200, lightMode);
                } else {
                    DrawSeasonEmblem(e.Graphics, _ornamentSeason, 18f, yLine, 4.4f, -12f, warmCol, coolCol, 225, lightMode);
                    DrawSeasonEmblem(e.Graphics, _ornamentSeason, _form.ClientSize.Width - 18f, yLine, 4.4f, 18f, warmCol, coolCol, 225, lightMode);
                    DrawSeasonDrift(e.Graphics, _ornamentSeason, 32f + drift, yLine - 3f, 4.4f, -35f, warmCol, 200, lightMode);
                    DrawSeasonDrift(e.Graphics, _ornamentSeason, _form.ClientSize.Width - 32f - drift, yLine + 2f, 4.4f, 42f, warmCol, 200, lightMode);
                }
            }
        }

        private void OnGlassContainerPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            Control c = sender as Control;
            if (c == null) return;

            bool lightMode = !_isActive;
            float phase = GetAmbientPhase();
            Color c1, c2, c3, warmCol, coolCol;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
            GetSeasonalOrnamentColors(_ornamentSeason, _borderStyle, lightMode, out warmCol, out coolCol);

            if (c is TabPage && c.Parent == _mainTabs) {
                if (lightMode) {
                    PaintWhiteBackdropWithParticles(e.Graphics, c);
                } else {
                    PaintAlignedLayerMode(e.Graphics, c, 0);
                    PaintParticlesOverlay(e.Graphics, c, false);
                }
                RectangleF cardRect = _showOrnaments
                    ? new RectangleF(2f, 5f, Math.Max(4f, c.Width - 5f), Math.Max(4f, c.Height - 7f))
                    : new RectangleF(1f, 1f, Math.Max(4f, c.Width - 3f), Math.Max(4f, c.Height - 3f));
                e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
                using (GraphicsPath path = CreateRoundedRect(cardRect, 12f)) {
                    if (!lightMode) {
                        GraphicsState gs = e.Graphics.Save();
                        try {
                            e.Graphics.SetClip(path, CombineMode.Intersect);
                            PaintAlignedLayerMode(e.Graphics, c, 1);
                            PaintParticlesOverlay(e.Graphics, c, false);
                        } finally {
                            e.Graphics.Restore(gs);
                        }
                    }

                    using (LinearGradientBrush gbGlow = CreateGradientBrush(cardRect, c1, c2, c3, lightMode ? 55 : 65))
                    using (Pen glowPen = new Pen(gbGlow, 4.4f)) {
                        glowPen.LineJoin = LineJoin.Round;
                        e.Graphics.DrawPath(glowPen, path);
                    }
                    using (LinearGradientBrush gb = CreateGradientBrush(cardRect, c1, c2, c3, lightMode ? 225 : 215))
                    using (Pen border = new Pen(gb, 1.8f)) {
                        border.LineJoin = LineJoin.Round;
                        e.Graphics.DrawPath(border, path);
                    }
                    if (cardRect.Width > 20f && cardRect.Height > 20f) {
                        RectangleF innerRim = new RectangleF(cardRect.X + 2.5f, cardRect.Y + 2.5f, cardRect.Width - 5f, cardRect.Height - 5f);
                        using (GraphicsPath iPath = CreateRoundedRect(innerRim, 9.5f))
                        using (Pen iPen = new Pen(lightMode ? Color.FromArgb(74, c2) : Color.FromArgb(65, c2), 1f)) {
                            e.Graphics.DrawPath(iPen, iPath);
                        }
                    }
                }
                if (_showOrnaments) {
                    if (cardRect.Width >= 140f) {
                        DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, cardRect.Right - 6f, cardRect.Y + 6f, 1.05f, false, false, phase, 240, false, lightMode);
                    }
                    DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, cardRect.X + 6f, cardRect.Y + 6f, 0.72f, true, false, phase + 0.8f, 225, true, lightMode);
                    DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, cardRect.X + 6f, cardRect.Bottom - 6f, 0.68f, true, true, phase + 1.6f, 215, true, lightMode);
                    DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, cardRect.Right - 6f, cardRect.Bottom - 6f, 0.68f, false, true, phase + 2.4f, 215, true, lightMode);
                }
                return;
            }

            if (object.Equals(c.Tag, "QuickCard")) {
                if (lightMode) {
                    PaintWhiteBackdropWithParticles(e.Graphics, c);
                } else {
                    PaintAlignedLayerMode(e.Graphics, c, 1);
                    PaintParticlesOverlay(e.Graphics, c, false);
                }
                RectangleF cardRect = new RectangleF(1f, 1f, Math.Max(4f, c.Width - 3f), Math.Max(4f, c.Height - 3f));
                e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
                using (GraphicsPath path = CreateRoundedRect(cardRect, 10f)) {
                    if (!lightMode) {
                        GraphicsState gs = e.Graphics.Save();
                        try {
                            e.Graphics.SetClip(path, CombineMode.Intersect);
                            PaintAlignedLayerMode(e.Graphics, c, 2);
                            PaintParticlesOverlay(e.Graphics, c, false);
                        } finally {
                            e.Graphics.Restore(gs);
                        }
                    }

                    using (LinearGradientBrush gbGlow = CreateGradientBrush(cardRect, c1, c2, c3, lightMode ? 48 : 56))
                    using (Pen gPen = new Pen(gbGlow, 3.6f)) {
                        e.Graphics.DrawPath(gPen, path);
                    }
                    using (LinearGradientBrush gb = CreateGradientBrush(cardRect, c1, c2, c3, lightMode ? 225 : 210))
                    using (Pen border = new Pen(gb, 1.6f)) {
                        e.Graphics.DrawPath(border, path);
                    }
                }
                if (_showOrnaments) {
                    if (cardRect.Width >= 120f) {
                        DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, cardRect.Right - 4f, cardRect.Y + 5f, 0.66f, false, false, phase, 225, true, lightMode);
                    }
                    DrawSeasonDrift(e.Graphics, _ornamentSeason, cardRect.Right - 14f, cardRect.Bottom - 7f, 5.2f, 38f, warmCol, 210, lightMode);
                }
                return;
            }

            bool isNav = _navContainers.Contains(c);
            int mode = isNav ? 2 : ((c.Parent == _form) ? 0 : 1);
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, c);
            } else {
                PaintAlignedLayerMode(e.Graphics, c, mode);
                PaintParticlesOverlay(e.Graphics, c, false);
            }
            if (isNav) {
                e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
                if (object.Equals(c.Tag, "HeaderBar")) {
                    RectangleF botRect = new RectangleF(0f, Math.Max(0f, c.Height - 4f), Math.Max(4f, c.Width), 4f);
                    using (LinearGradientBrush gbGlow = CreateGradientBrush(botRect, c1, c2, c3, lightMode ? 65 : 75))
                    using (Pen gPen = new Pen(gbGlow, 4.5f)) {
                        e.Graphics.DrawLine(gPen, 0f, c.Height - 2.0f, c.Width, c.Height - 2.0f);
                    }
                    using (LinearGradientBrush gb = CreateGradientBrush(botRect, c1, c2, c3, lightMode ? 235 : 225))
                    using (Pen pen = new Pen(gb, 1.8f)) {
                        e.Graphics.DrawLine(pen, 0f, c.Height - 1.3f, c.Width, c.Height - 1.3f);
                    }
                    if (_showOrnaments) {
                        Color hTwigCol = GetSeasonTwigColor(_ornamentSeason, lightMode, 200);
                        using (Pen hTwig = new Pen(hTwigCol, 1.6f)) {
                            hTwig.StartCap = LineCap.Round;
                            hTwig.EndCap = LineCap.Round;
                            e.Graphics.DrawArc(hTwig, 1f, 1f, 20f, 16f, 180f, 88f);
                        }
                        if (_ornamentSeason == 0) {
                            DrawSakuraFlower(e.Graphics, 8.5f, 8.5f, 5.0f, -15f, warmCol, Color.FromArgb(255, 244, 250), Color.FromArgb(219, 39, 119), 230, lightMode);
                        } else {
                            DrawSeasonEmblem(e.Graphics, _ornamentSeason, 8.5f, 8.5f, 5.0f, -15f, warmCol, coolCol, 230, lightMode);
                        }
                        float bannerRightX = Math.Min(c.Width - 396f, 706f);
                        if (bannerRightX > 590f) {
                            DrawSeasonHeaderBanner(e.Graphics, _ornamentSeason, 496f, bannerRightX - 8f, phase, warmCol, lightMode);
                        }
                    }
                } else if (object.Equals(c.Tag, "NavSidebar")) {
                    RectangleF edgeRect = new RectangleF(Math.Max(0f, c.Width - 4f), 0f, 4f, Math.Max(8f, c.Height));
                    using (LinearGradientBrush edgeGlow = new LinearGradientBrush(edgeRect, c1, c3, LinearGradientMode.Vertical)) {
                        ColorBlend cbGlow = new ColorBlend(3);
                        cbGlow.Positions = new float[] { 0f, 0.5f, 1f };
                        cbGlow.Colors = new Color[] { Color.FromArgb(lightMode ? 58 : 68, c1), Color.FromArgb(lightMode ? 58 : 68, c2), Color.FromArgb(lightMode ? 58 : 68, c3) };
                        edgeGlow.InterpolationColors = cbGlow;
                        using (Pen pGlow = new Pen(edgeGlow, 4.0f)) {
                            e.Graphics.DrawLine(pGlow, c.Width - 1.8f, 0f, c.Width - 1.8f, c.Height);
                        }
                    }
                    using (LinearGradientBrush edgeCore = new LinearGradientBrush(edgeRect, c1, c3, LinearGradientMode.Vertical)) {
                        ColorBlend cbCore = new ColorBlend(3);
                        cbCore.Positions = new float[] { 0f, 0.5f, 1f };
                        cbCore.Colors = new Color[] { Color.FromArgb(lightMode ? 225 : 215, c1), Color.FromArgb(lightMode ? 225 : 215, c2), Color.FromArgb(lightMode ? 225 : 215, c3) };
                        edgeCore.InterpolationColors = cbCore;
                        using (Pen pCore = new Pen(edgeCore, 1.7f)) {
                            e.Graphics.DrawLine(pCore, c.Width - 1.2f, 0f, c.Width - 1.2f, c.Height);
                        }
                    }
                    if (_showOrnaments) {
                        Color nTwigCol = GetSeasonTwigColor(_ornamentSeason, lightMode, 200);
                        using (Pen nTwig = new Pen(nTwigCol, 1.5f)) {
                            nTwig.StartCap = LineCap.Round; nTwig.EndCap = LineCap.Round;
                            e.Graphics.DrawArc(nTwig, 1f, 1f, 18f, 16f, 180f, 88f);
                        }
                        if (_ornamentSeason == 0) {
                            DrawSakuraFlower(e.Graphics, 8.5f, 8.5f, 4.6f, -12f, warmCol, Color.FromArgb(255, 244, 250), Color.FromArgb(219, 39, 119), 225, lightMode);
                        } else {
                            DrawSeasonEmblem(e.Graphics, _ornamentSeason, 8.5f, 8.5f, 4.6f, -12f, warmCol, coolCol, 225, lightMode);
                        }
                        int maxBottom = 0;
                        foreach (Control ch in c.Controls) {
                            if (ch != null && ch.Visible && ch.Bottom > maxBottom) maxBottom = ch.Bottom;
                        }
                        if (c.Height - maxBottom >= 48 && c.Width >= 90) {
                            DrawSeasonSidebarFooter(e.Graphics, _ornamentSeason, c.Width, c.Height - 28f, phase, c1, c2, c3, warmCol, lightMode);
                        }
                    }
                } else {
                    using (Pen pen = new Pen(lightMode ? Color.FromArgb(203, 213, 225) : Color.FromArgb(40, 255, 255, 255), 1)) {
                        e.Graphics.DrawLine(pen, c.Width - 1, 0, c.Width - 1, c.Height);
                        e.Graphics.DrawLine(pen, 0, c.Height - 1, c.Width, c.Height - 1);
                    }
                }
            }
        }

        private void OnGroupBoxPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            GroupBox gb = sender as GroupBox;
            if (gb == null) return;
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, gb);
            } else {
                PaintAlignedLayerMode(e.Graphics, gb, 0);
                PaintParticlesOverlay(e.Graphics, gb, false);
            }

            Size txtSz = TextRenderer.MeasureText(e.Graphics, gb.Text, gb.Font, new Size(Math.Max(10, gb.Width - 24), 30), TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
            int topY = Math.Max(8, txtSz.Height / 2);
            RectangleF boxRect = new RectangleF(1f, topY, Math.Max(8f, gb.Width - 3f), Math.Max(8f, gb.Height - topY - 2f));
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;

            float phase = GetAmbientPhase();
            Color c1, c2, c3, warmCol, coolCol;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
            GetSeasonalOrnamentColors(_ornamentSeason, _borderStyle, lightMode, out warmCol, out coolCol);

            using (GraphicsPath path = CreateRoundedRect(boxRect, 12f)) {
                if (!lightMode) {
                    GraphicsState gs = e.Graphics.Save();
                    try {
                        e.Graphics.SetClip(path, CombineMode.Intersect);
                        PaintAlignedLayerMode(e.Graphics, gb, 1);
                        PaintParticlesOverlay(e.Graphics, gb, false);
                    } finally {
                        e.Graphics.Restore(gs);
                    }
                }

                using (LinearGradientBrush gbrGlow = CreateGradientBrush(boxRect, c1, c2, c3, lightMode ? 52 : 60))
                using (Pen glowPen = new Pen(gbrGlow, 4.0f)) {
                    glowPen.LineJoin = LineJoin.Round;
                    e.Graphics.DrawPath(glowPen, path);
                }
                using (LinearGradientBrush gbr = CreateGradientBrush(boxRect, c1, c2, c3, lightMode ? 225 : 210))
                using (Pen pen = new Pen(gbr, 1.7f)) {
                    pen.LineJoin = LineJoin.Round;
                    e.Graphics.DrawPath(pen, path);
                }
                if (boxRect.Width > 20f && boxRect.Height > 20f) {
                    RectangleF innerRim = new RectangleF(boxRect.X + 2.5f, boxRect.Y + 2.5f, boxRect.Width - 5f, boxRect.Height - 5f);
                    using (GraphicsPath iPath = CreateRoundedRect(innerRim, 9.5f))
                    using (Pen iPen = new Pen(lightMode ? Color.FromArgb(70, c2) : Color.FromArgb(58, c2), 1f)) {
                        e.Graphics.DrawPath(iPen, iPath);
                    }
                }
            }

            Rectangle notch = new Rectangle(10, 0, Math.Min(gb.Width - 20, txtSz.Width + 8), txtSz.Height + 2);
            GraphicsState gsNotch = e.Graphics.Save();
            try {
                e.Graphics.SetClip(notch, CombineMode.Intersect);
                if (lightMode) {
                    PaintWhiteBackdropWithParticles(e.Graphics, gb);
                } else {
                    PaintAlignedLayerMode(e.Graphics, gb, 0);
                    PaintParticlesOverlay(e.Graphics, gb, false);
                }
            } finally {
                e.Graphics.Restore(gsNotch);
            }

            if (_showOrnaments) {
                if (boxRect.Width >= 140f) {
                    DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, boxRect.Right - 6f, boxRect.Y + 6f, 0.86f, false, false, phase + 0.4f, 235, (boxRect.Width < 210f), lightMode);
                }
                DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, boxRect.X + 6f, boxRect.Bottom - 6f, 0.58f, true, true, phase + 1.2f, 210, true, lightMode);
                DrawSeasonBranchCorner(e.Graphics, _ornamentSeason, boxRect.Right - 6f, boxRect.Bottom - 6f, 0.58f, false, true, phase + 2.0f, 210, true, lightMode);
            }

            Rectangle titleRect = new Rectangle(12, 0, Math.Max(10, gb.Width - 20), txtSz.Height + 2);
            TextFormatFlags titleFlags = TextFormatFlags.Left | TextFormatFlags.Top | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
            Color gbBaseFg = (lightMode && (gb.ForeColor == SystemColors.ControlText || gb.ForeColor == Color.Black)) ? Color.FromArgb(30, 58, 95) : gb.ForeColor;
            DrawModeText(e.Graphics, gb.Text, gb.Font, titleRect, gbBaseFg, true, titleFlags, _textPreset, lightMode, _strongTextOutline);
        }

        private void OnLabelPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            Label lbl = sender as Label;
            if (lbl == null) return;
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, lbl);
            } else {
                PaintAlignedParentLayer(e.Graphics, lbl);
                PaintParticlesOverlay(e.Graphics, lbl, false);
            }

            if (string.IsNullOrEmpty(lbl.Text)) return;

            Padding pad = lbl.Padding;
            Rectangle rect = new Rectangle(pad.Left, pad.Top, Math.Max(1, lbl.Width - pad.Horizontal), Math.Max(1, lbl.Height - pad.Vertical));
            TextFormatFlags flags = AlignmentToFlags(lbl.TextAlign);
            if (!lbl.UseMnemonic) flags |= TextFormatFlags.NoPrefix;
            if (lbl.AutoEllipsis && lbl.Height <= 26) {
                flags |= TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis;
            } else {
                flags |= TextFormatFlags.WordBreak;
                if (lbl.AutoEllipsis) flags |= TextFormatFlags.EndEllipsis;
            }

            if (!lbl.Enabled) {
                TextRenderer.DrawText(e.Graphics, lbl.Text, lbl.Font, rect, Color.FromArgb(148, 163, 184), flags);
                return;
            }
            Color baseFg = lbl.ForeColor;
            if (lightMode && _textPreset == 0 && ((object.Equals(lbl.Tag, "HomeTip") && lbl.ForeColor.R < 150) || object.Equals(lbl.Tag, "SeasonAccent"))) {
                Color sc1, sc2, sc3;
                GetBorderColorsForMode(_ornamentSeason, true, out sc1, out sc2, out sc3);
                baseFg = DarkenColor(sc1, 0.24f);
            }
            DrawModeText(e.Graphics, lbl.Text, lbl.Font, rect, baseFg, lbl.Font.Bold, flags, _textPreset, lightMode, _strongTextOutline);
        }

        private void OnModeBadgePaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            Label lbl = sender as Label;
            if (lbl == null) return;
            ButtonAnimState anim = GetAnimStateOrNull(lbl);
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, lbl);
            } else {
                PaintAlignedLayerMode(e.Graphics, lbl, 2);
                PaintParticlesOverlay(e.Graphics, lbl, false);
            }

            bool isLive = (lbl.BackColor.R > lbl.BackColor.B);
            float hoverT = (anim != null) ? anim.HoverT : (_hoveredControls.Contains(lbl) ? 1f : 0f);
            float pressDepth = (anim != null) ? anim.PressDepth : (_pressedControls.Contains(lbl) ? 1f : 0f);
            float pressClamp = Math.Max(0f, Math.Min(1f, pressDepth));
            float hoverVisual = hoverT * (1f - pressClamp * 0.78f);

            Color c1, c2, c3;
            if (isLive) {
                c1 = Color.FromArgb(239, 68, 68);
                c2 = Color.FromArgb(249, 115, 22);
                c3 = Color.FromArgb(220, 38, 38);
            } else {
                GetBorderColorsForMode(_ornamentSeason, lightMode, out c1, out c2, out c3);
            }
            Color topFill, botFill;
            if (lightMode) {
                topFill = Color.White;
                botFill = isLive ? Color.FromArgb(255, 255, 232, 236) : BlendWithWhite(c1, 0.84f);
            } else {
                int topA = Math.Max(0, Math.Min(255, (int)Math.Round(215 + hoverVisual * 26)));
                int botA = Math.Max(0, Math.Min(255, (int)Math.Round(210 + hoverVisual * 26)));
                if (isLive) {
                    topFill = Color.FromArgb(topA, 74, 14, 22);
                    botFill = Color.FromArgb(botA, 110, 22, 30);
                } else {
                    Color d1 = DarkenColor(c1, 0.72f);
                    Color d2 = DarkenColor(c3, 0.66f);
                    topFill = Color.FromArgb(topA, d1);
                    botFill = Color.FromArgb(botA, d2);
                }
            }

            float rad = Math.Min(12f, Math.Max(7f, (lbl.Height - 4) * 0.42f));
            DrawGlowingPill(e.Graphics, new Rectangle(0, 0, lbl.Width, lbl.Height), c1, c2, c3, topFill, botFill, rad, hoverT, pressDepth, false, true, anim, _borderStyle, GetAmbientPhase(), _showOrnaments ? 2 : 0, lightMode, _ornamentSeason);
            int textShiftY = (int)Math.Round(pressDepth * 2.0f - hoverVisual * 0.7f);
            Rectangle rect = new Rectangle(6, textShiftY, Math.Max(4, lbl.Width - 12), Math.Max(4, lbl.Height - 1));
            TextFormatFlags bFlags = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
            if (isLive) {
                if (lightMode) {
                    TextRenderer.DrawText(e.Graphics, lbl.Text, lbl.Font, rect, Color.FromArgb(185, 28, 28), bFlags);
                } else {
                    DrawProminentText(e.Graphics, lbl.Text, lbl.Font, rect, Color.White, bFlags, _strongTextOutline || (_textPreset == 3));
                }
            } else {
                Color badgeBase = lightMode ? Color.FromArgb(15, 23, 42) : Color.White;
                DrawModeText(e.Graphics, lbl.Text, lbl.Font, rect, badgeBase, lbl.Font.Bold, bFlags, _textPreset, lightMode, _strongTextOutline);
            }
        }

        private void OnCheckBoxPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            CheckBox chk = sender as CheckBox;
            if (chk == null) return;
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, chk);
            } else {
                PaintAlignedParentLayer(e.Graphics, chk);
                PaintParticlesOverlay(e.Graphics, chk, false);
            }

            Color c1, c2, c3;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
            int boxY = Math.Max(1, (chk.Height - 15) / 2);
            RectangleF box = new RectangleF(1f, boxY, 15f, 15f);
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath bp = CreateRoundedRect(box, 4f)) {
                if (chk.Checked) {
                    using (LinearGradientBrush fill = CreateGradientBrush(box, c1, c2, c3, chk.Enabled ? (lightMode ? 245 : 230) : 120)) {
                        e.Graphics.FillPath(fill, bp);
                    }
                    using (Pen border = new Pen(lightMode ? Color.FromArgb(190, c1) : Color.FromArgb(220, 255, 255, 255), 1f)) {
                        e.Graphics.DrawPath(border, bp);
                    }
                    using (Pen tick = new Pen(lightMode ? Color.White : Color.FromArgb(8, 14, 28), 2.1f)) {
                        tick.StartCap = LineCap.Round;
                        tick.EndCap = LineCap.Round;
                        e.Graphics.DrawLines(tick, new PointF[] {
                            new PointF(box.X + 3.5f, box.Y + 8f),
                            new PointF(box.X + 6.5f, box.Y + 11f),
                            new PointF(box.X + 12f, box.Y + 4.2f)
                        });
                    }
                } else {
                    using (SolidBrush fill = new SolidBrush(lightMode ? Color.White : Color.FromArgb(205, 14, 22, 40))) {
                        e.Graphics.FillPath(fill, bp);
                    }
                    Color bdCol = chk.Enabled ? Color.FromArgb(lightMode ? 220 : 180, lightMode ? c1 : c2) : Color.FromArgb(lightMode ? 148 : 90, 148, 163, 184);
                    using (Pen border = new Pen(bdCol, 1.2f)) {
                        e.Graphics.DrawPath(border, bp);
                    }
                }
            }

            Rectangle rect = new Rectangle(21, 0, Math.Max(1, chk.Width - 22), chk.Height);
            TextFormatFlags flags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.WordBreak;
            if (!chk.UseMnemonic) flags |= TextFormatFlags.NoPrefix;
            if (!chk.Enabled) {
                TextRenderer.DrawText(e.Graphics, chk.Text, chk.Font, rect, Color.FromArgb(148, 163, 184), flags);
                return;
            }
            Color chkBaseFg = (lightMode && _textPreset == 0 && object.Equals(chk.Tag, "DryCheck") && chk.Checked)
                ? DarkenColor(c1, 0.24f)
                : chk.ForeColor;
            DrawModeText(e.Graphics, chk.Text, chk.Font, rect, chkBaseFg, chk.Font.Bold, flags, _textPreset, lightMode, _strongTextOutline);
        }

        private void OnRadioButtonPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            RadioButton rdo = sender as RadioButton;
            if (rdo == null) return;
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, rdo);
            } else {
                PaintAlignedParentLayer(e.Graphics, rdo);
                PaintParticlesOverlay(e.Graphics, rdo, false);
            }

            Color c1, c2, c3;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
            Color accent = lightMode ? c1 : c2;
            int y = Math.Max(1, (rdo.Height - 15) / 2);
            Rectangle circle = new Rectangle(1, y, 15, 15);
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            using (SolidBrush bg = new SolidBrush(lightMode ? Color.White : Color.FromArgb(205, 14, 22, 40))) {
                e.Graphics.FillEllipse(bg, circle);
            }
            using (Pen border = new Pen(rdo.Checked ? accent : Color.FromArgb(165, 148, 163, 184), 1.5f)) {
                e.Graphics.DrawEllipse(border, circle);
            }
            if (rdo.Checked) {
                using (SolidBrush dot = new SolidBrush(accent)) {
                    e.Graphics.FillEllipse(dot, circle.X + 4, circle.Y + 4, 7, 7);
                }
            }

            Rectangle rect = new Rectangle(21, 0, Math.Max(1, rdo.Width - 22), rdo.Height);
            TextFormatFlags flags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.WordBreak;
            if (!rdo.UseMnemonic) flags |= TextFormatFlags.NoPrefix;
            if (!rdo.Enabled) {
                TextRenderer.DrawText(e.Graphics, rdo.Text, rdo.Font, rect, Color.FromArgb(148, 163, 184), flags);
                return;
            }
            DrawModeText(e.Graphics, rdo.Text, rdo.Font, rect, rdo.ForeColor, rdo.Font.Bold, flags, _textPreset, lightMode, _strongTextOutline);
        }

        private void OnThemedButtonPaint(object sender, PaintEventArgs e) {
            if (!IsStyled) return;
            Button b = sender as Button;
            if (b == null) return;
            ButtonAnimState anim = GetAnimStateOrNull(b);
            bool lightMode = !_isActive;
            if (lightMode) {
                PaintWhiteBackdropWithParticles(e.Graphics, b);
            } else {
                PaintAlignedParentLayer(e.Graphics, b);
                PaintParticlesOverlay(e.Graphics, b, false);
            }

            string tag = (b.Tag != null) ? b.Tag.ToString() : "Secondary";
            float hoverT = (anim != null) ? anim.HoverT : (_hoveredControls.Contains(b) ? 1f : 0f);
            float pressDepth = (anim != null) ? anim.PressDepth : (_pressedControls.Contains(b) ? 1f : 0f);
            float pressClamp = Math.Max(0f, Math.Min(1f, pressDepth));
            float hoverVisual = hoverT * (1f - pressClamp * 0.78f);

            if (tag == "NavItem") {
                bool isSelected = object.ReferenceEquals(b, _activeNavBtn);
                Color c1, c2, c3;
                GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
                if (isSelected) {
                    Color tf, bf;
                    if (lightMode) {
                        tf = Color.White;
                        bf = BlendWithWhite(c1, 0.85f);
                    } else {
                        int tfA = Math.Max(0, Math.Min(255, (int)Math.Round(204 + hoverVisual * 28)));
                        int bfA = Math.Max(0, Math.Min(255, (int)Math.Round(196 + hoverVisual * 28)));
                        tf = Color.FromArgb(tfA, 18, 30, 56);
                        bf = Color.FromArgb(bfA, 26, 44, 78);
                    }
                    DrawGlowingPill(e.Graphics, new Rectangle(0, 0, b.Width, b.Height), c1, c2, c3, tf, bf, 9f, hoverT, pressDepth, (_borderStyle == 1 || _borderStyle == 4 || _borderStyle == 5 || _borderStyle == 9 || _borderStyle == 12), true, anim, _borderStyle, GetAmbientPhase(), _showOrnaments ? 2 : 0, lightMode, _ornamentSeason);
                } else if (hoverT > 0.01f || Math.Abs(pressDepth) > 0.01f || (anim != null && anim.HoverSweepActive)) {
                    float squish = pressDepth * 1.6f;
                    float hoverLift = -0.6f * hoverVisual;
                    float pressOffset = pressDepth * 1.8f;
                    float hrX = Math.Max(1.0f, 2f + squish);
                    float hrY = Math.Max(0.8f, 2f + hoverLift + squish + pressOffset);
                    float hrW = Math.Max(4f, Math.Min(Math.Max(4f, b.Width - 2.5f), b.Width - 5f - squish * 2f));
                    float hrH = Math.Max(4f, Math.Min(Math.Max(4f, b.Height - 2.5f), b.Height - 5f - squish * 2f));
                    RectangleF hr = new RectangleF(hrX, hrY, hrW, hrH);
                    using (GraphicsPath hp = CreateRoundedRect(hr, Math.Max(3f, 9f - pressClamp))) {
                        int fillA = Math.Max(0, Math.Min(255, (int)Math.Round(hoverVisual * (lightMode ? 210f : 52f))));
                        if (fillA > 1) {
                            Color hovFill = lightMode ? Color.FromArgb(fillA, BlendWithWhite(c2, 0.78f)) : Color.FromArgb(fillA, 255, 255, 255);
                            using (SolidBrush hbr = new SolidBrush(hovFill)) {
                                e.Graphics.FillPath(hbr, hp);
                            }
                        }
                        DrawHoverFxOverlay(e.Graphics, hp, hr, c2, hoverT, pressClamp, anim, lightMode);
                        DrawPressRecessOverlay(e.Graphics, hp, hr, pressClamp, lightMode);
                        int borderA = Math.Max(0, Math.Min(255, (int)Math.Round(hoverVisual * (lightMode ? 175f : 125f) + pressClamp * (lightMode ? 65f : 55f))));
                        if (borderA > 2) {
                            using (Pen hpen = new Pen(Color.FromArgb(borderA, lightMode ? c1 : c2), 1.15f)) {
                                e.Graphics.DrawPath(hpen, hp);
                            }
                        }
                    }
                    if (_showOrnaments && hoverVisual > 0.05f) {
                        Color warmCol, coolCol;
                        GetSeasonalOrnamentColors(_ornamentSeason, _borderStyle, lightMode, out warmCol, out coolCol);
                        int navOrnA = Math.Max(0, Math.Min(255, (int)Math.Round(hoverVisual * 215f)));
                        if (_ornamentSeason == 0) {
                            DrawSakuraFlower(e.Graphics, hr.X + 6.5f, hr.Y + 6.5f, 4.2f, -15f, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), navOrnA, lightMode);
                            DrawSakuraPetal(e.Graphics, hr.Right - 10f, hr.Y + 6.0f, 4.4f, 30f, warmCol, navOrnA, lightMode);
                        } else {
                            DrawSeasonEmblem(e.Graphics, _ornamentSeason, hr.X + 6.5f, hr.Y + 6.5f, 4.2f, -15f, warmCol, coolCol, navOrnA, lightMode);
                            DrawSeasonDrift(e.Graphics, _ornamentSeason, hr.Right - 10f, hr.Y + 6.0f, 4.4f, 30f, warmCol, navOrnA, lightMode);
                        }
                    }
                }
                int navShiftY = (int)Math.Round(pressDepth * 1.8f - hoverVisual * 0.6f);
                Rectangle nRect = new Rectangle(14, navShiftY, Math.Max(1, b.Width - 18), Math.Max(4, b.Height - 1));
                TextFormatFlags nFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
                Color nBaseFg = lightMode
                    ? (isSelected ? Color.FromArgb(15, 23, 42) : ((hoverVisual > 0.25f) ? Color.FromArgb(15, 23, 42) : Color.FromArgb(51, 65, 85)))
                    : (isSelected ? Color.White : Color.FromArgb(241, 245, 249));
                DrawModeText(e.Graphics, b.Text, b.Font, nRect, nBaseFg, isSelected || b.Font.Bold, nFlags, _textPreset, lightMode, _strongTextOutline);
                return;
            }

            Color b1, b2, b3;
            GetBorderColorsForMode(_borderStyle, lightMode, out b1, out b2, out b3);
            Color topFill, botFill, fg;
            bool doubleGold = (_borderStyle == 1 || _borderStyle == 4 || _borderStyle == 5 || _borderStyle == 9 || _borderStyle == 12);

            if (lightMode) {
                if (!b.Enabled) {
                    topFill = Color.FromArgb(248, 250, 252);
                    botFill = Color.FromArgb(241, 245, 249);
                    b1 = Color.FromArgb(190, 202, 218);
                    b2 = Color.FromArgb(206, 216, 228);
                    b3 = Color.FromArgb(190, 202, 218);
                    doubleGold = false;
                    fg = Color.FromArgb(148, 163, 184);
                } else if (tag == "Danger") {
                    b1 = Color.FromArgb(220, 38, 38);
                    b2 = Color.FromArgb(244, 63, 94);
                    b3 = Color.FromArgb(185, 28, 28);
                    topFill = Color.White;
                    botFill = Color.FromArgb(255, 254, 236, 238);
                    doubleGold = false;
                    fg = Color.FromArgb(185, 28, 28);
                } else if (tag == "Primary") {
                    topFill = Color.White;
                    botFill = BlendWithWhite(b1, 0.86f);
                    fg = Color.FromArgb(15, 23, 42);
                } else if (tag == "ThemeQuick") {
                    topFill = Color.White;
                    botFill = BlendWithWhite(b2, 0.84f);
                    fg = Color.FromArgb(15, 23, 42);
                } else {
                    topFill = Color.White;
                    botFill = Color.FromArgb(255, 247, 250, 255);
                    fg = Color.FromArgb(30, 41, 59);
                }
            } else {
                if (!b.Enabled) {
                    topFill = Color.FromArgb(148, 15, 22, 36);
                    botFill = Color.FromArgb(148, 22, 30, 48);
                    b1 = Color.FromArgb(100, 116, 139);
                    b2 = Color.FromArgb(148, 163, 184);
                    b3 = Color.FromArgb(100, 116, 139);
                    doubleGold = false;
                } else if (tag == "Danger") {
                    b1 = Color.FromArgb(239, 68, 68);
                    b2 = Color.FromArgb(251, 113, 133);
                    b3 = Color.FromArgb(220, 38, 38);
                    int tA = Math.Max(0, Math.Min(255, (int)Math.Round(208 + hoverVisual * 26)));
                    int bA = Math.Max(0, Math.Min(255, (int)Math.Round(196 + hoverVisual * 26)));
                    topFill = Color.FromArgb(tA, 44, 12, 20);
                    botFill = Color.FromArgb(bA, 28, 10, 18);
                    doubleGold = false;
                } else if (tag == "Primary") {
                    int tA = Math.Max(0, Math.Min(255, (int)Math.Round(216 + hoverVisual * 24)));
                    int bA = Math.Max(0, Math.Min(255, (int)Math.Round(204 + hoverVisual * 26)));
                    topFill = Color.FromArgb(tA, 20, 38, 76);
                    botFill = Color.FromArgb(bA, 30, 54, 102);
                } else if (tag == "ThemeQuick") {
                    int tA = Math.Max(0, Math.Min(255, (int)Math.Round(208 + hoverVisual * 26)));
                    int bA = Math.Max(0, Math.Min(255, (int)Math.Round(196 + hoverVisual * 26)));
                    topFill = Color.FromArgb(tA, 14, 24, 52);
                    botFill = Color.FromArgb(bA, 22, 38, 74);
                } else {
                    int tA = Math.Max(0, Math.Min(255, (int)Math.Round(202 + hoverVisual * 26)));
                    int bA = Math.Max(0, Math.Min(255, (int)Math.Round(190 + hoverVisual * 26)));
                    topFill = Color.FromArgb(tA, 11, 16, 28);
                    botFill = Color.FromArgb(bA, 18, 25, 42);
                }
                fg = b.Enabled ? Color.White : Color.FromArgb(148, 163, 184);
            }

            float rad = Math.Min(11f, Math.Max(7f, (b.Height - 4) * 0.38f));
            DrawGlowingPill(e.Graphics, new Rectangle(0, 0, b.Width, b.Height), b1, b2, b3, topFill, botFill, rad, hoverT, pressDepth, doubleGold, b.Enabled, anim, _borderStyle, GetAmbientPhase(), _showOrnaments ? 2 : 0, lightMode, _ornamentSeason);

            int txtShiftY = (int)Math.Round(pressDepth * 2.0f - hoverVisual * 0.7f);
            Rectangle txtRect = new Rectangle(6, txtShiftY, Math.Max(4, b.Width - 12), Math.Max(4, b.Height - 2));
            TextFormatFlags btnFlags = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
            if (!b.Enabled) {
                TextRenderer.DrawText(e.Graphics, b.Text, b.Font, txtRect, fg, btnFlags);
            } else if (tag == "Danger") {
                if (lightMode) {
                    TextRenderer.DrawText(e.Graphics, b.Text, b.Font, txtRect, fg, btnFlags);
                } else {
                    DrawProminentText(e.Graphics, b.Text, b.Font, txtRect, fg, btnFlags, _strongTextOutline || (_textPreset == 3));
                }
            } else {
                bool isBoldBtn = b.Font.Bold || tag == "Primary" || tag == "ThemeQuick";
                DrawModeText(e.Graphics, b.Text, b.Font, txtRect, fg, isBoldBtn, btnFlags, _textPreset, lightMode, _strongTextOutline);
            }
        }

        private void OnSubTabDrawItem(object sender, DrawItemEventArgs e) {
            TabControl tc = sender as TabControl;
            if (tc == null || e.Index < 0 || e.Index >= tc.TabPages.Count) return;
            if (!IsStyled) return;

            bool lightMode = !_isActive;
            bool isSel = (e.Index == tc.SelectedIndex);
            Color c1, c2, c3;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);

            using (SolidBrush bg = new SolidBrush(lightMode ? Color.White : Color.FromArgb(14, 20, 36))) {
                e.Graphics.FillRectangle(bg, e.Bounds);
            }
            Rectangle pill = new Rectangle(e.Bounds.X + 1, e.Bounds.Y + 1, Math.Max(4, e.Bounds.Width - 3), Math.Max(4, e.Bounds.Height - 2));
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            RectangleF pillF = new RectangleF(pill.X, pill.Y, pill.Width, pill.Height);
            using (GraphicsPath gp = CreateRoundedRect(pillF, 6f)) {
                Color pillFill = lightMode
                    ? (isSel ? BlendWithWhite(c2, 0.86f) : Color.White)
                    : (isSel ? Color.FromArgb(24, 42, 80) : Color.FromArgb(16, 24, 42));
                using (SolidBrush fill = new SolidBrush(pillFill)) {
                    e.Graphics.FillPath(fill, gp);
                }
                if (isSel) {
                    using (LinearGradientBrush gb = CreateGradientBrush(pillF, c1, c2, c3, 235))
                    using (Pen bp = new Pen(gb, 1.3f)) {
                        e.Graphics.DrawPath(bp, gp);
                    }
                    if (_showOrnaments && pillF.Width >= 40f) {
                        Color warmCol, coolCol;
                        GetSeasonalOrnamentColors(_ornamentSeason, _borderStyle, lightMode, out warmCol, out coolCol);
                        if (_ornamentSeason == 0) {
                            DrawSakuraFlower(e.Graphics, pillF.Right - 7.5f, pillF.Y + 6.5f, 3.8f, 12f, warmCol, Color.FromArgb(255, 245, 250), Color.FromArgb(219, 39, 119), 235, lightMode);
                        } else {
                            DrawSeasonEmblem(e.Graphics, _ornamentSeason, pillF.Right - 7.5f, pillF.Y + 6.5f, 3.8f, 12f, warmCol, coolCol, 235, lightMode);
                        }
                    }
                } else {
                    using (Pen bp = new Pen(lightMode ? Color.FromArgb(215, 224, 236) : Color.FromArgb(55, 75, 110), 1f)) {
                        e.Graphics.DrawPath(bp, gp);
                    }
                }
            }

            string txt = tc.TabPages[e.Index].Text.Trim();
            Font fnt = isSel ? new Font(tc.Font, FontStyle.Bold) : tc.Font;
            try {
                TextFormatFlags tFlags = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix;
                Color baseFg = lightMode
                    ? (isSel ? Color.FromArgb(15, 23, 42) : Color.FromArgb(71, 85, 105))
                    : (isSel ? Color.White : Color.FromArgb(203, 213, 225));
                DrawModeText(e.Graphics, txt, fnt, e.Bounds, baseFg, isSel, tFlags, _textPreset, lightMode, _strongTextOutline);
            } finally {
                if (isSel) fnt.Dispose();
            }
        }

        private void OnComboDrawItem(object sender, DrawItemEventArgs e) {
            ComboBox cbo = sender as ComboBox;
            if (cbo == null || !IsStyled) return;
            if (e.Index < 0 || e.Index >= cbo.Items.Count) return;

            bool lightMode = !_isActive;
            bool sel = ((e.State & DrawItemState.Selected) != 0);
            Color c1, c2, c3;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);
            Color bgCol = lightMode
                ? (sel ? BlendWithWhite(c2, 0.80f) : Color.White)
                : (sel ? Color.FromArgb(28, 52, 98) : Color.FromArgb(14, 22, 40));
            using (SolidBrush bg = new SolidBrush(bgCol)) {
                e.Graphics.FillRectangle(bg, e.Bounds);
            }
            if (sel) {
                using (SolidBrush bar = new SolidBrush(lightMode ? c1 : c2)) {
                    e.Graphics.FillRectangle(bar, e.Bounds.X, e.Bounds.Y + 2, 3, Math.Max(2, e.Bounds.Height - 4));
                }
            }
            string txt = cbo.GetItemText(cbo.Items[e.Index]);
            Rectangle r = new Rectangle(e.Bounds.X + 8, e.Bounds.Y, Math.Max(4, e.Bounds.Width - 12), e.Bounds.Height);
            TextFormatFlags dFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
            Color baseFg = lightMode ? Color.FromArgb(15, 23, 42) : Color.White;
            DrawModeText(e.Graphics, txt, cbo.Font, r, baseFg, sel, dFlags, _textPreset, lightMode, _strongTextOutline);
        }

        private void OnListViewDrawColumnHeader(object sender, DrawListViewColumnHeaderEventArgs e) {
            if (!IsStyled) { e.DrawDefault = true; return; }
            bool lightMode = !_isActive;
            using (SolidBrush bg = new SolidBrush(lightMode ? Color.White : Color.FromArgb(18, 28, 48))) {
                e.Graphics.FillRectangle(bg, e.Bounds);
            }
            using (Pen sep = new Pen(lightMode ? Color.FromArgb(226, 232, 240) : Color.FromArgb(55, 76, 110), 1)) {
                e.Graphics.DrawLine(sep, e.Bounds.Right - 1, e.Bounds.Top + 3, e.Bounds.Right - 1, e.Bounds.Bottom - 3);
                if (!lightMode) {
                    e.Graphics.DrawLine(sep, e.Bounds.Left, e.Bounds.Bottom - 1, e.Bounds.Right, e.Bounds.Bottom - 1);
                }
            }
            if (lightMode) {
                Color c1, c2, c3;
                GetBorderColorsForMode(_borderStyle, true, out c1, out c2, out c3);
                RectangleF bRect = new RectangleF(e.Bounds.Left, Math.Max(0, e.Bounds.Bottom - 2), Math.Max(4, e.Bounds.Width), 2);
                using (LinearGradientBrush gb = CreateGradientBrush(bRect, c1, c2, c3, 180))
                using (Pen bPen = new Pen(gb, 1f)) {
                    e.Graphics.DrawLine(bPen, e.Bounds.Left, e.Bounds.Bottom - 1, e.Bounds.Right, e.Bounds.Bottom - 1);
                }
            }
            Rectangle tr = new Rectangle(e.Bounds.X + 6, e.Bounds.Y, Math.Max(4, e.Bounds.Width - 10), e.Bounds.Height);
            Font fnt = (e.Font != null) ? new Font(e.Font, FontStyle.Bold) : SystemFonts.DefaultFont;
            try {
                TextFormatFlags hFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
                Color hBaseFg = lightMode ? Color.FromArgb(30, 41, 59) : Color.White;
                DrawModeText(e.Graphics, e.Header.Text, fnt, tr, hBaseFg, true, hFlags, _textPreset, lightMode, _strongTextOutline);
            } finally {
                if (e.Font != null) fnt.Dispose();
            }
        }

        private void OnListViewDrawItem(object sender, DrawListViewItemEventArgs e) {
            if (!IsStyled) { e.DrawDefault = true; return; }
            ListView lv = sender as ListView;
            if (lv != null && lv.View != View.Details) {
                e.DrawDefault = true;
            }
        }

        private void OnListViewDrawSubItem(object sender, DrawListViewSubItemEventArgs e) {
            if (!IsStyled) { e.DrawDefault = true; return; }
            ListView lv = sender as ListView;
            bool lightMode = !_isActive;
            bool sel = (e.Item != null && e.Item.Selected);
            Color c1, c2, c3;
            GetBorderColorsForMode(_borderStyle, lightMode, out c1, out c2, out c3);

            Color rowBg = lightMode
                ? (sel ? BlendWithWhite(c2, 0.82f) : ((e.ItemIndex % 2 == 0) ? Color.White : Color.FromArgb(249, 251, 255)))
                : (sel ? Color.FromArgb(26, 48, 92) : ((e.ItemIndex % 2 == 0) ? Color.FromArgb(12, 19, 34) : Color.FromArgb(16, 25, 44)));
            using (SolidBrush br = new SolidBrush(rowBg)) {
                e.Graphics.FillRectangle(br, e.Bounds);
            }
            if (sel && e.ColumnIndex == 0) {
                using (SolidBrush bar = new SolidBrush(lightMode ? c1 : c2)) {
                    e.Graphics.FillRectangle(bar, e.Bounds.X, e.Bounds.Y + 2, 3, Math.Max(2, e.Bounds.Height - 4));
                }
            }

            int xOff = 6;
            if (lv != null && lv.CheckBoxes && e.ColumnIndex == 0 && e.Item != null) {
                int by = e.Bounds.Y + Math.Max(1, (e.Bounds.Height - 13) / 2);
                RectangleF cbRect = new RectangleF(e.Bounds.X + 7f, by, 13f, 13f);
                e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
                using (GraphicsPath cp = CreateRoundedRect(cbRect, 3f)) {
                    if (e.Item.Checked) {
                        if (lightMode) {
                            using (LinearGradientBrush cbFill = CreateGradientBrush(cbRect, c1, c2, c3, 245)) { e.Graphics.FillPath(cbFill, cp); }
                        } else {
                            using (SolidBrush cbFill = new SolidBrush(c2)) { e.Graphics.FillPath(cbFill, cp); }
                        }
                        using (Pen tk = new Pen(lightMode ? Color.White : Color.FromArgb(8, 14, 28), 1.8f)) {
                            tk.StartCap = LineCap.Round; tk.EndCap = LineCap.Round;
                            e.Graphics.DrawLines(tk, new PointF[] {
                                new PointF(cbRect.X + 3f, cbRect.Y + 7f),
                                new PointF(cbRect.X + 5.5f, cbRect.Y + 9.5f),
                                new PointF(cbRect.X + 10.2f, cbRect.Y + 3.8f)
                            });
                        }
                    } else {
                        using (SolidBrush cbFill = new SolidBrush(lightMode ? Color.White : Color.FromArgb(10, 16, 30))) { e.Graphics.FillPath(cbFill, cp); }
                        using (Pen cbPen = new Pen(Color.FromArgb(148, 163, 184), 1.1f)) { e.Graphics.DrawPath(cbPen, cp); }
                    }
                }
                xOff = 25;
            }

            Rectangle tr = new Rectangle(e.Bounds.X + xOff, e.Bounds.Y, Math.Max(4, e.Bounds.Width - xOff - 4), e.Bounds.Height);
            Font fnt = (e.SubItem != null && e.SubItem.Font != null) ? e.SubItem.Font : ((lv != null) ? lv.Font : SystemFonts.DefaultFont);
            TextFormatFlags sFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix;
            Color baseFg = (e.Item != null) ? e.Item.ForeColor : (lightMode ? Color.FromArgb(15, 23, 42) : Color.White);
            if (lightMode) {
                if (sel) {
                    double luma = 0.299 * baseFg.R + 0.587 * baseFg.G + 0.114 * baseFg.B;
                    if (luma > 105.0) baseFg = Color.FromArgb(15, 23, 42);
                }
            } else if (sel) {
                baseFg = Color.White;
            }
            DrawModeText(e.Graphics, e.SubItem.Text, fnt, tr, baseFg, fnt.Bold || sel, sFlags, _textPreset, lightMode, _strongTextOutline);
        }

        public static void DrawProminentText(Graphics g, string text, Font font, Rectangle rect, Color foreColor, TextFormatFlags flags, bool strongOutline) {
            DrawProminentText(g, text, font, rect, foreColor, flags, strongOutline, Color.FromArgb(6, 10, 20));
        }

        public static void DrawProminentText(Graphics g, string text, Font font, Rectangle rect, Color foreColor, TextFormatFlags flags, bool strongOutline, Color outlineColor) {
            if (string.IsNullOrEmpty(text) || rect.Width <= 0 || rect.Height <= 0) return;
            if (strongOutline) {
                for (int i = 0; i < s_outlineOffsets.Length; i++) {
                    Point p = s_outlineOffsets[i];
                    Rectangle r = new Rectangle(rect.X + p.X, rect.Y + p.Y, rect.Width, rect.Height);
                    TextRenderer.DrawText(g, text, font, r, outlineColor, flags);
                }
            }
            TextRenderer.DrawText(g, text, font, rect, foreColor, flags);
        }

        private static bool ClassifySemanticColor(Color c, out Color darkEquivalent) {
            int r = c.R, g = c.G, b = c.B;
            if (r >= 150 && g <= 90 && b <= 90) {
                darkEquivalent = Color.FromArgb(255, 107, 107);
                return true;
            }
            if (g >= 90 && r <= 70 && b <= 90) {
                darkEquivalent = Color.FromArgb(74, 222, 128);
                return true;
            }
            if (r >= 180 && g >= 110 && b <= 70) {
                darkEquivalent = Color.FromArgb(250, 204, 21);
                return true;
            }
            if (b >= 130 && r <= 90) {
                darkEquivalent = Color.FromArgb(56, 189, 248);
                return true;
            }
            darkEquivalent = c;
            return false;
        }

        public static Color ResolveForeColorForMode(Color c, bool isBold, int preset, bool lightMode, bool strongOutline) {
            int p = Math.Max(0, Math.Min(6, preset));
            Color darkSem;
            if (ClassifySemanticColor(c, out darkSem)) {
                return lightMode ? c : darkSem;
            }
            int r = c.R, g = c.G, b = c.B;
            double luma = 0.299 * r + 0.587 * g + 0.114 * b;
            bool nearWhite = (r >= 245 && g >= 245 && b >= 245);
            if (luma > 185.0 && !nearWhite) {
                return c;
            }
            bool mutedGray = (Math.Abs(r - g) <= 22 && Math.Abs(g - b) <= 22 && luma >= 85.0 && luma <= 185.0);
            if (mutedGray) {
                switch (p) {
                    case 1: return lightMode ? Color.FromArgb(146, 64, 14) : Color.FromArgb(254, 243, 199);
                    case 2: return lightMode ? Color.FromArgb(14, 116, 144) : Color.FromArgb(224, 242, 254);
                    case 3: return Color.FromArgb(241, 245, 249);
                    case 4: return lightMode ? Color.FromArgb(157, 23, 77) : Color.FromArgb(252, 231, 243);
                    case 5: return lightMode ? Color.FromArgb(6, 95, 70) : Color.FromArgb(209, 250, 229);
                    case 6: return lightMode ? Color.FromArgb(159, 18, 57) : Color.FromArgb(255, 228, 230);
                    default: return lightMode ? c : Color.FromArgb(226, 232, 240);
                }
            }
            if (lightMode) {
                switch (p) {
                    case 1: return isBold ? (strongOutline ? Color.FromArgb(250, 204, 21) : Color.FromArgb(180, 83, 9)) : Color.FromArgb(161, 98, 7);
                    case 2: return isBold ? (strongOutline ? Color.FromArgb(56, 189, 248) : Color.FromArgb(2, 132, 199)) : Color.FromArgb(3, 105, 161);
                    case 3: return Color.White;
                    case 4: return isBold ? (strongOutline ? Color.FromArgb(244, 114, 182) : Color.FromArgb(219, 39, 119)) : Color.FromArgb(190, 24, 93);
                    case 5: return isBold ? (strongOutline ? Color.FromArgb(52, 211, 153) : Color.FromArgb(5, 150, 105)) : Color.FromArgb(4, 120, 87);
                    case 6: return isBold ? (strongOutline ? Color.FromArgb(251, 113, 133) : Color.FromArgb(220, 38, 38)) : Color.FromArgb(185, 28, 28);
                    default: return (luma > 200.0) ? Color.FromArgb(15, 23, 42) : c;
                }
            } else {
                switch (p) {
                    case 1: return isBold ? Color.FromArgb(253, 224, 71) : Color.White;
                    case 2: return isBold ? Color.FromArgb(56, 189, 248) : Color.FromArgb(248, 250, 252);
                    case 3: return Color.White;
                    case 4: return isBold ? Color.FromArgb(244, 114, 182) : Color.FromArgb(252, 231, 243);
                    case 5: return isBold ? Color.FromArgb(52, 211, 153) : Color.FromArgb(236, 253, 245);
                    case 6: return isBold ? Color.FromArgb(251, 113, 133) : Color.FromArgb(255, 241, 242);
                    default: return Color.White;
                }
            }
        }

        public static void DrawModeText(Graphics g, string text, Font font, Rectangle rect, Color baseColor, bool isBold, TextFormatFlags flags, int preset, bool lightMode, bool strongOutline) {
            if (string.IsNullOrEmpty(text) || rect.Width <= 0 || rect.Height <= 0) return;
            int p = Math.Max(0, Math.Min(6, preset));
            Color darkSem;
            bool isSemantic = ClassifySemanticColor(baseColor, out darkSem);
            Color fg = ResolveForeColorForMode(baseColor, isBold, p, lightMode, strongOutline);
            bool useOutline;
            Color outlineCol;
            if (!lightMode) {
                useOutline = strongOutline || (p == 3);
                outlineCol = Color.FromArgb(6, 10, 20);
            } else {
                if (isSemantic) {
                    useOutline = false;
                    outlineCol = Color.Empty;
                } else if (p == 3) {
                    useOutline = true;
                    outlineCol = Color.FromArgb(15, 23, 42);
                } else if (p != 0 && strongOutline && isBold) {
                    useOutline = true;
                    outlineCol = Color.FromArgb(30, 41, 59);
                } else {
                    useOutline = false;
                    outlineCol = Color.Empty;
                }
            }
            DrawProminentText(g, text, font, rect, fg, flags, useOutline, outlineCol);
        }

        public static Color ResolveThemedForeColor(Color c, bool isBold, int preset) {
            return ResolveForeColorForMode(c, isBold, preset, false, true);
        }

        private static TextFormatFlags AlignmentToFlags(ContentAlignment align) {
            TextFormatFlags f = TextFormatFlags.Default;
            switch (align) {
                case ContentAlignment.TopLeft:      f = TextFormatFlags.Left | TextFormatFlags.Top; break;
                case ContentAlignment.TopCenter:    f = TextFormatFlags.HorizontalCenter | TextFormatFlags.Top; break;
                case ContentAlignment.TopRight:     f = TextFormatFlags.Right | TextFormatFlags.Top; break;
                case ContentAlignment.MiddleLeft:   f = TextFormatFlags.Left | TextFormatFlags.VerticalCenter; break;
                case ContentAlignment.MiddleCenter: f = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter; break;
                case ContentAlignment.MiddleRight:  f = TextFormatFlags.Right | TextFormatFlags.VerticalCenter; break;
                case ContentAlignment.BottomLeft:   f = TextFormatFlags.Left | TextFormatFlags.Bottom; break;
                case ContentAlignment.BottomCenter: f = TextFormatFlags.HorizontalCenter | TextFormatFlags.Bottom; break;
                case ContentAlignment.BottomRight:  f = TextFormatFlags.Right | TextFormatFlags.Bottom; break;
            }
            return f;
        }

        public void Dispose() {
            if (_disposed) return;
            _disposed = true;
            _isAttached = false;
            _formCanAnimate = false;
            Interlocked.Increment(ref _workerGen);
            try { _workerWake.Set(); } catch { }
            if (_animTimer != null) {
                try { _animTimer.Stop(); _animTimer.Dispose(); } catch { }
                _animTimer = null;
            }
            if (_ambientTimer != null) {
                try { _ambientTimer.Stop(); _ambientTimer.Dispose(); } catch { }
                _ambientTimer = null;
            }
            if (_resizeTimer != null) {
                try { _resizeTimer.Stop(); _resizeTimer.Dispose(); } catch { }
                _resizeTimer = null;
            }
            _activeAnims.Clear();
            ClearTheme();
            DisposeParticleSprites();
            try { _workerWake.Close(); } catch { }
        }
    }
}
'@
}

