$script:OUSet         = @{}         # DN(chữ thường) -> tên OU
$script:OUByName      = @{}         # tên(chữ thường) -> danh sách DN
$script:NodeMap       = @{}         # DN(chữ thường) -> node trên sơ đồ
$script:NewDN         = @{}         # OU mới phát hiện ở lần làm mới gần nhất
