$script:LogHistory    = New-Object 'System.Collections.Generic.List[object]'
$script:QuickCards    = @()
$script:ExcludedThemeControls = @()

function Get-AppBaseDir {
    if ($PSScriptRoot) { return $PSScriptRoot }
    if ($PSCommandPath) { return (Split-Path -Parent $PSCommandPath) }
    $base = [System.AppDomain]::CurrentDomain.BaseDirectory
    if ($base) { return $base.TrimEnd('\') }
    return (Get-Location).Path
}

function Get-ThemeDir {
    param([switch]$Ensure)
    $dir = Join-Path (Get-AppBaseDir) "Theme"
    if ($Ensure -and -not (Test-Path -LiteralPath $dir)) {
        try { [void](New-Item -ItemType Directory -Path $dir -Force) } catch { }
    }
    return $dir
}

function New-DesktopShortcut {
    param(
        [string]$DestinationPath = "",
        [switch]$Quiet
    )
    $wsh = $null
    $sc  = $null
    try {
        if ([string]::IsNullOrWhiteSpace($DestinationPath)) {
            $deskDir = [Environment]::GetFolderPath('Desktop')
            if (-not $deskDir -or -not (Test-Path -LiteralPath $deskDir)) {
                $deskDir = Join-Path $env:USERPROFILE 'Desktop'
            }
            if (-not (Test-Path -LiteralPath $deskDir)) {
                [void](New-Item -ItemType Directory -Path $deskDir -Force)
            }
            $DestinationPath = Join-Path $deskDir 'Jebtool.lnk'
        }

        $procExe = ""
        try { $procExe = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { }
        $baseDir = Get-AppBaseDir
        $candExe = Join-Path $baseDir "Jebtool.exe"
        $candPs1 = Join-Path $baseDir "Jebtool.ps1"
        $candIco = Join-Path $baseDir "Jebtool.ico"
        if (-not (Test-Path -LiteralPath $candExe) -and -not (Test-Path -LiteralPath $candPs1)) {
            $cwd = (Get-Location).Path
            if ((Test-Path -LiteralPath (Join-Path $cwd "Jebtool.exe")) -or (Test-Path -LiteralPath (Join-Path $cwd "Jebtool.ps1"))) {
                $baseDir = $cwd
                $candExe = Join-Path $baseDir "Jebtool.exe"
                $candPs1 = Join-Path $baseDir "Jebtool.ps1"
                $candIco = Join-Path $baseDir "Jebtool.ico"
            }
        }

        $targetPath = ""
        $targetArgs = ""
        $workDir    = $baseDir
        $iconLoc    = ""

        if ($procExe -and $procExe.EndsWith('.exe', [System.StringComparison]::OrdinalIgnoreCase) -and
            ([System.IO.Path]::GetFileNameWithoutExtension($procExe) -notmatch '^(?i)(powershell|pwsh|powershell_ise)$') -and
            (Test-Path -LiteralPath $procExe)) {
            $targetPath = $procExe
            $workDir    = Split-Path -Parent $procExe
            $iconLoc    = "$procExe,0"
        } elseif (Test-Path -LiteralPath $candExe) {
            $targetPath = $candExe
            $iconLoc    = "$candExe,0"
        } elseif (Test-Path -LiteralPath $candPs1) {
            $psExe = Join-Path $env:WINDIR "System32\WindowsPowerShell\v1.0\powershell.exe"
            if (-not (Test-Path -LiteralPath $psExe)) { $psExe = "powershell.exe" }
            $targetPath = $psExe
            $targetArgs = "-ExecutionPolicy Bypass -WindowStyle Hidden -File `"$candPs1`""
            $iconLoc    = if (Test-Path -LiteralPath $candIco) { "$candIco,0" } else { "$env:WINDIR\System32\shell32.dll,21" }
        } else {
            throw "Không tìm thấy Jebtool.exe hoặc Jebtool.ps1 để tạo shortcut."
        }

        $wsh = New-Object -ComObject WScript.Shell
        $sc  = $wsh.CreateShortcut($DestinationPath)
        $sc.TargetPath       = $targetPath
        $sc.Arguments        = $targetArgs
        $sc.WorkingDirectory = $workDir
        $sc.IconLocation     = $iconLoc
        $sc.Description      = "Jebtool — Quản trị Active Directory & Windows Server"
        $sc.Save()

        if (-not $Quiet) {
            Write-Log "[OK] Đã tạo biểu tượng Jebtool trên Desktop: $DestinationPath" "Green"
            Show-Msg "Đã đưa biểu tượng Jebtool ra Desktop!`r`n`r`nĐường dẫn shortcut:`r`n$DestinationPath" "Đưa icon ra Desktop" "Information"
        }
        return $DestinationPath
    } catch {
        $msg = $_.Exception.Message
        if (-not $Quiet) {
            Write-Log "[LỖI] Không thể đưa icon ra Desktop: $msg" "Red"
            Show-Msg "Không thể tạo shortcut trên Desktop.`r`nChi tiết: $msg" "Lỗi tạo shortcut" "Error"
        } else {
            throw
        }
    } finally {
        if ($null -ne $sc)  { try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($sc)  } catch { } }
        if ($null -ne $wsh) { try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($wsh) } catch { } }
    }
}

function Open-SysvolFolder {
    $candidates = New-Object 'System.Collections.Generic.List[string]'
    $candidates.Add("C:\Windows\SYSVOL")
    if ($script:Ready -and $script:DomainName) {
        try {
            $pdc = (Get-ADDomain -ErrorAction SilentlyContinue).PDCEmulator
            if ($pdc) { $candidates.Add("\\$pdc\SYSVOL") }
        } catch { }
        $candidates.Add("\\$($script:DomainName)\SYSVOL")
    }

    $target = ""
    foreach ($p in $candidates) {
        if ($p -and (Test-Path -LiteralPath $p)) {
            $target = $p
            break
        }
    }

    if (-not $target) {
        Write-Log "[CẢNH BÁO] Không tìm thấy thư mục C:\Windows\SYSVOL hoặc đường dẫn SYSVOL của Domain." "DarkOrange"
        Show-Msg "Không tìm thấy thư mục C:\Windows\SYSVOL trên máy này (thư mục này chỉ có trên Domain Controller hoặc khi đã kết nối Domain)." "Không tìm thấy SYSVOL" "Warning"
        return
    }

    try {
        Start-Process explorer.exe -ArgumentList "`"$target`""
        Write-Log "[OK] Đã mở thư mục SYSVOL: $target" "Green"
    } catch {
        Write-Log ("[LỖI] Không mở được SYSVOL ($target): " + $_.Exception.Message) "Red"
        Show-Msg ("Không thể mở thư mục SYSVOL:`r`n$target`r`n`r`nChi tiết: " + $_.Exception.Message) "Lỗi mở SYSVOL" "Error"
    }
}

function Get-NativePresetForeColor {
    param([bool]$IsThemed, [int]$Preset = 0)
    if ($IsThemed) {
        switch ($Preset) {
            1 { return [System.Drawing.Color]::FromArgb(253, 224, 71) }
            2 { return [System.Drawing.Color]::FromArgb(56, 189, 248) }
            4 { return [System.Drawing.Color]::FromArgb(244, 114, 182) }
            5 { return [System.Drawing.Color]::FromArgb(52, 211, 153) }
            6 { return [System.Drawing.Color]::FromArgb(251, 113, 133) }
            default { return [System.Drawing.Color]::FromArgb(248, 250, 252) }
        }
    } else {
        switch ($Preset) {
            1 { return [System.Drawing.Color]::FromArgb(146, 64, 14) }
            2 { return [System.Drawing.Color]::FromArgb(3, 105, 161) }
            4 { return [System.Drawing.Color]::FromArgb(190, 24, 93) }
            5 { return [System.Drawing.Color]::FromArgb(4, 120, 87) }
            6 { return [System.Drawing.Color]::FromArgb(185, 28, 28) }
            default { return [System.Drawing.Color]::FromArgb(15, 23, 42) }
        }
    }
}

function Get-ThemeColor {
    param([string]$ColorName = "Black")
    $isThemed = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive)
    $preset = if ($null -ne $script:ThemeEngine) { [int]$script:ThemeEngine.TextPreset } elseif ($null -ne $cboThemeTextPreset -and $cboThemeTextPreset.SelectedIndex -ge 0) { [int]$cboThemeTextPreset.SelectedIndex } else { 0 }
    if ($ColorName -match '^(?i)(Black|ControlText|WindowText)$') {
        return (Get-NativePresetForeColor $isThemed $preset)
    }
    if ($isThemed) {
        switch -Regex ($ColorName) {
            '^(?i)(DimGray|Gray|SlateGray)$'       { return [System.Drawing.Color]::FromArgb(203, 213, 225) }
            '^(?i)(DarkBlue|SteelBlue|Blue)$'      { return [System.Drawing.Color]::FromArgb(96, 165, 250) }
            '^(?i)(ForestGreen|Green)$'            { return [System.Drawing.Color]::FromArgb(74, 222, 128) }
            '^(?i)DarkOrange$'                     { return [System.Drawing.Color]::FromArgb(251, 191, 36) }
            '^(?i)Goldenrod$'                      { return [System.Drawing.Color]::FromArgb(250, 204, 21) }
            '^(?i)(Red|Firebrick)$'                { return [System.Drawing.Color]::FromArgb(255, 107, 107) }
        }
    }
    $c = [System.Drawing.Color]::FromName($ColorName)
    if ($c.A -eq 0 -and $c.R -eq 0 -and $c.G -eq 0 -and $c.B -eq 0) {
        return (Get-NativePresetForeColor $isThemed $preset)
    }
    return $c
}

# ---------------------------------------------------------------
#  Hàm dùng chung
# ---------------------------------------------------------------
function Show-Msg {
    param([string]$Text, [string]$Title = "Thông báo", [string]$Icon = "Information")
    if ($null -ne $form -and $form.IsHandleCreated -and -not $form.IsDisposed) {
        [void][System.Windows.Forms.MessageBox]::Show($form, $Text, $Title, "OK", $Icon)
    }
    else {
        [void][System.Windows.Forms.MessageBox]::Show($Text, $Title, "OK", $Icon)
    }
}

function Confirm-Msg {
    param([string]$Text, [string]$Title = "Xác nhận", [string]$Icon = "Question")
    $r = if ($null -ne $form -and $form.IsHandleCreated -and -not $form.IsDisposed) {
        [System.Windows.Forms.MessageBox]::Show($form, $Text, $Title, "YesNo", $Icon)
    }
    else {
        [System.Windows.Forms.MessageBox]::Show($Text, $Title, "YesNo", $Icon)
    }
    return ($r -eq [System.Windows.Forms.DialogResult]::Yes)
}

function Resolve-DryRunBeforeCreate {
    param([string]$Summary)
    if (-not $chkDry.Checked) { return "live" }
    $msg = "Tool đang bật chế độ CHẠY THỬ (chỉ xem trước, chưa thực hiện thật trên hệ thống / Active Directory).`r`n`r`n" +
           "Thao tác: $Summary`r`n`r`n" +
           "• Bấm YES: Tắt 'Chạy thử' và THỰC HIỆN THẬT ngay bây giờ.`r`n" +
           "• Bấm NO: Chỉ ghi nhật ký xem trước ([CHẠY THỬ]), chưa thay đổi hệ thống."
    if (Confirm-Msg $msg "Đang bật chế độ Chạy thử" "Information") {
        $chkDry.Checked = $false
        return "switched"
    }
    return "dry"
}

function Write-Log {
    param([string]$Msg, [string]$Color = "Black")
    $time = Get-Date -Format "HH:mm:ss"
    $script:LogHistory.Add([pscustomobject]@{ Time = $time; Msg = $Msg; Color = $Color })
    if ($script:LogHistory.Count -gt 500) {
        $script:LogHistory.RemoveAt(0)
    }
    $txtLog.SelectionStart  = $txtLog.TextLength
    $txtLog.SelectionLength = 0
    $txtLog.SelectionColor  = (Get-ThemeColor $Color)
    $txtLog.AppendText("[$time] $Msg`r`n")
    $txtLog.ScrollToCaret()
    $txtLog.Refresh()
}

function Rebuild-LogColors {
    if ($null -eq $txtLog -or $txtLog.IsDisposed) { return }
    $txtLog.SuspendLayout()
    try {
        $txtLog.Clear()
        foreach ($entry in $script:LogHistory) {
            $txtLog.SelectionStart  = $txtLog.TextLength
            $txtLog.SelectionLength = 0
            $txtLog.SelectionColor  = (Get-ThemeColor $entry.Color)
            $txtLog.AppendText("[$($entry.Time)] $($entry.Msg)`r`n")
        }
        $txtLog.ScrollToCaret()
    } finally {
        $txtLog.ResumeLayout()
    }
}

function Initialize-Env {
    $missing = @()
    foreach ($m in 'ActiveDirectory', 'GroupPolicy') {
        if (-not (Get-Module -ListAvailable -Name $m)) { $missing += $m }
    }
    if ($missing.Count -gt 0) {
        $missText = $missing -join ', '
        Write-Log "[CẢNH BÁO] Thiếu module RSAT ($missText). Các tab AD/OU/GPO sẽ bị khóa; tab Ổ đĩa/Share/Giờ máy vẫn dùng được." "DarkOrange"
        Show-Msg ("Máy này chưa cài đủ công cụ quản trị RSAT (thiếu: $missText).`r`n`r`n" +
                  "Cách cài: Settings > Apps > Optional features > Add a feature, rồi cài:`r`n" +
                  "  - RSAT: Active Directory Domain Services and Lightweight Directory Services Tools`r`n" +
                  "  - RSAT: Group Policy Management Tools`r`n`r`n" +
                  "Hoặc chạy tool này trực tiếp trên Domain Controller.`r`n(Bạn vẫn có thể dùng các tab Ổ đĩa, Share và Giờ máy.)") "Thiếu RSAT" "Warning"
        return $false
    }
    try {
        Import-Module ActiveDirectory, GroupPolicy -ErrorAction Stop
        $d = Get-ADDomain -ErrorAction Stop
        $script:DomainDN      = $d.DistinguishedName
        $script:DomainControllersDN = $d.DomainControllersContainer
        $script:DomainName    = $d.DNSRoot
        $script:DomainNetBIOS = $d.NetBIOSName
        return $true
    }
    catch {
        $errMsg = $_.Exception.Message
        Write-Log ("[LỖI] Không kết nối được tới domain: " + $errMsg) "Red"
        Show-Msg ("Không kết nối được tới domain.`r`nChi tiết: $errMsg`r`n`r`n" +
                  "Hãy kiểm tra:`r`n" +
                  "  - Máy đã tham gia domain chưa`r`n" +
                  "  - Đang đăng nhập bằng tài khoản domain có quyền quản trị`r`n" +
                  "  - Máy kết nối mạng được tới Domain Controller") "Không kết nối được domain" "Warning"
        return $false
    }
}

function New-FolderIcon {
    param([System.Drawing.Color]$Color, [bool]$Plus = $false, [bool]$Globe = $false)
    $bmp = New-Object System.Drawing.Bitmap 16, 16
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = "AntiAlias"
    $br = New-Object System.Drawing.SolidBrush $Color
    if ($Globe) { $g.FillEllipse($br, 1, 1, 14, 14) }
    else { $g.FillRectangle($br, 1, 2, 6, 3); $g.FillRectangle($br, 1, 4, 14, 10) }
    if ($Plus) {
        $pen = New-Object System.Drawing.Pen ([System.Drawing.Color]::White), 2
        $g.DrawLine($pen, 8, 6, 8, 12); $g.DrawLine($pen, 5, 9, 11, 9)
        $pen.Dispose()
    }
    $br.Dispose(); $g.Dispose()
    return $bmp
}


function New-PersonIcon {
    param([System.Drawing.Color]$Color, [bool]$Group = $false)
    $bmp = New-Object System.Drawing.Bitmap 16, 16
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = "AntiAlias"
    $br = New-Object System.Drawing.SolidBrush $Color
    if ($Group) {
        $lt = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(150, $Color))
        $g.FillEllipse($lt, 1, 3, 5, 5); $g.FillPie($lt, 0, 9, 8, 10, 180, 180)
        $g.FillEllipse($br, 6, 1, 6, 6); $g.FillPie($br, 3, 8, 12, 14, 180, 180)
        $lt.Dispose()
    }
    else {
        $g.FillEllipse($br, 4, 1, 8, 8)
        $g.FillPie($br, 1, 10, 14, 12, 180, 180)
    }
    $br.Dispose(); $g.Dispose()
    return $bmp
}

# Dữ liệu dùng chung về group/user (cập nhật mỗi lần đọc AD)
$script:GroupSAM = @{}
$script:UserSAM  = @{}
$script:AllDN    = @{}
$script:ObjSet   = @{}
$script:NewObj   = @{}
$script:SamTouched = $false
$script:SamSetting = $false

function Remove-Diacritics {
    param([string]$s)
    $groups = @{
        'a' = 'àáảãạăằắẳẵặâầấẩẫậ'; 'e' = 'èéẻẽẹêềếểễệ'; 'i' = 'ìíỉĩị'
        'o' = 'òóỏõọôồốổỗộơờớởỡợ'; 'u' = 'ùúủũụưừứửữự'; 'y' = 'ỳýỷỹỵ'; 'd' = 'đ'
    }
    $map = @{}
    foreach ($k in $groups.Keys) { foreach ($c in $groups[$k].ToCharArray()) { $map[[string]$c] = $k } }
    $sb = New-Object System.Text.StringBuilder
    foreach ($c in $s.ToLowerInvariant().ToCharArray()) {
        if ([System.Globalization.CharUnicodeInfo]::GetUnicodeCategory($c) -eq [System.Globalization.UnicodeCategory]::NonSpacingMark) { continue }
        $ch = [string]$c
        if ($map.ContainsKey($ch)) { [void]$sb.Append($map[$ch]) } else { [void]$sb.Append($ch) }
    }
    return $sb.ToString()
}

# "Nguyễn Văn An" -> "an.nv", "user 1" -> "user1", "Nguyễn Văn An 1" -> "an.nv1"
function Get-SamFromName {
    param([string]$Name)
    $t = @((Remove-Diacritics $Name).ToLower() -split '\s+' | ForEach-Object { $_ -replace '[^a-z0-9]', '' } | Where-Object { $_ })
    if ($t.Count -eq 0) { return "" }
    $num = ""
    if ($t.Count -ge 2 -and $t[$t.Count - 1] -match '^\d+$') {
        $num = $t[$t.Count - 1]
        $t = @($t[0..($t.Count - 2)])
    }
    if ($t.Count -eq 1) {
        $r = $t[0]
    }
    else {
        $r = $t[$t.Count - 1]
        $ini = ""
        for ($i = 0; $i -lt $t.Count - 1; $i++) { $ini += $t[$i].Substring(0, 1) }
        if ($ini) { $r = $r + '.' + $ini }
    }
    if ($num) {
        $headMax = 20 - $num.Length
        if ($headMax -gt 0 -and $r.Length -gt $headMax) { $r = $r.Substring(0, $headMax) }
        $r = $r + $num
    }
    if ($r.Length -gt 20) { $r = $r.Substring(0, 20) }
    return $r
}

function Split-NumberedBase {
    param([string]$Text)
    $s = [string]$Text
    if ($s -match '^(.*?)(\d+)$') {
        $dStr = $matches[2]
        $pad = if ($dStr.Length -gt 1 -and $dStr.StartsWith('0')) { $dStr.Length } else { 0 }
        return @{ Prefix = $matches[1]; Start = [int64]$dStr; Pad = $pad; HasNum = $true }
    }
    return @{ Prefix = $s; Start = [int64]1; Pad = 0; HasNum = $false }
}

function Get-DesiredUsrCount {
    if ($null -eq $numUsrCount) { return 1 }
    $txt = $numUsrCount.Text.Trim()
    if ($txt -match '^\d+$') {
        $v = [int64]$txt
        if ($v -lt 1) { return 1 }
        if ($v -gt [int64]$numUsrCount.Maximum) { return [int]$numUsrCount.Maximum }
        return [int]$v
    }
    return [int]$numUsrCount.Value
}

function Get-UserBatchPlan {
    param([string]$BaseName, [string]$BaseSam, [string]$Path, [int]$Count)
    $nb = Split-NumberedBase $BaseName
    $sb = Split-NumberedBase $BaseSam
    $namePref = if ($nb.HasNum) { $nb.Prefix } elseif ($BaseName -match '[\s_\-]$') { $BaseName } else { "$BaseName " }
    $samPref  = $sb.Prefix
    $startIdx = if ($nb.HasNum) { $nb.Start } elseif ($sb.HasNum) { $sb.Start } else { [int64]1 }
    $samDelta = if ($nb.HasNum -and $sb.HasNum) { $sb.Start - $nb.Start } else { [int64]0 }

    $items = New-Object 'System.Collections.Generic.List[object]'
    $skipped = 0
    $maxProbe = $Count + 20000
    for ($step = 0; $step -lt $maxProbe -and $items.Count -lt $Count; $step++) {
        $nVal = $startIdx + $step
        $sVal = $nVal + $samDelta
        if ($sVal -lt 0) { continue }
        $nNumStr = if ($nb.Pad -gt 0) { $nVal.ToString("D$($nb.Pad)") } else { [string]$nVal }
        $sNumStr = if ($sb.Pad -gt 0) { $sVal.ToString("D$($sb.Pad)") } else { [string]$sVal }
        $candName = $namePref + $nNumStr
        $candSam  = $samPref  + $sNumStr
        if ($candName.Length -gt 64) {
            return @{ Ok = $false; Err = "Tên user vượt 64 ký tự tại '$candName'." }
        }
        if ($candSam.Length -gt 20) {
            return @{ Ok = $false; Err = "Tên đăng nhập vượt 20 ký tự tại '$candSam'." }
        }
        $samKey = $candSam.ToLowerInvariant()
        $dnLow  = ("CN=" + ($candName -replace ',', '\,') + "," + $Path).ToLowerInvariant()
        if ($script:UserSAM.ContainsKey($samKey) -or $script:GroupSAM.ContainsKey($samKey) -or $script:AllDN.ContainsKey($dnLow)) {
            $skipped++
            continue
        }
        $items.Add([pscustomobject]@{ Name = $candName; Sam = $candSam })
    }
    if ($items.Count -lt $Count) {
        return @{ Ok = $false; Err = "Không tìm đủ $Count tên trống liên tiếp sau $maxProbe lần dò." }
    }
    $arr = $items.ToArray()
    return @{ Ok = $true; Items = $arr; Skipped = $skipped; First = $arr[0]; Last = $arr[$arr.Count - 1] }
}

function Test-IsProtectedADAccount {
    param([string]$Sam, [string]$DN, [string]$Sid = "", [bool]$IsCritical = $false, [string]$ObjectClass = "user")
    if ($IsCritical) {
        return "BỊ CHẶN: Không được phép xóa đối tượng hệ thống quan trọng ($Sam)."
    }
    if ($DN -match '(?i)(,CN=Builtin,|,OU=Domain Controllers,)') {
        return "BỊ CHẶN: Không được phép xóa đối tượng thuộc Builtin hoặc Domain Controllers ($DN)."
    }
    if ($Sid -match '-(500|501|502|512|513|514|515|516|518|519|520|521|526|527)$') {
        return "BỊ CHẶN: Không được phép xóa tài khoản/nhóm mặc định có SID bảo vệ ($Sam)."
    }
    $sLow = ([string]$Sam).Trim().ToLowerInvariant()
    if ($ObjectClass -eq 'user' -and $sLow -and $sLow -eq ([string]$env:USERNAME).Trim().ToLowerInvariant()) {
        return "BỊ CHẶN: Không được phép xóa tài khoản đang đăng nhập ($Sam)."
    }
    $protNames = @(
        'administrator', 'guest', 'krbtgt',
        'domain admins', 'enterprise admins', 'schema admins', 'domain controllers',
        'domain users', 'domain guests', 'domain computers', 'administrators', 'users',
        'guests', 'backup operators', 'account operators', 'server operators',
        'print operators', 'group policy creator owners', 'cert publishers',
        'dnsadmins', 'protected users', 'key admins', 'enterprise key admins'
    )
    if ($sLow -and ($sLow -in $protNames)) {
        return "BỊ CHẶN: Không được phép xóa tài khoản/nhóm hệ thống mặc định ($Sam)."
    }
    return $null
}

function Get-UserDeleteBatchPlan {
    param([string]$BaseName, [string]$BaseSam, [string]$OUPath, [int]$Count)
    $bn = ([string]$BaseName).Trim()
    $bs = ([string]$BaseSam).Trim()
    if ($Count -lt 1) { $Count = 1 }

    if (-not $bn -and -not $bs) {
        if (-not $OUPath -or $OUPath -eq $script:DomainDN) {
            return @{ Ok = $false; Err = "Hãy nhập tên User hoặc chọn một OU cụ thể (không phải gốc domain)." }
        }
        if (Test-IsDomainControllersOU $OUPath) {
            return @{ Ok = $false; Err = "BỊ CHẶN: Không được phép xóa hàng loạt User trong OU Domain Controllers." }
        }
        try {
            $raw = @(Get-ADUser -SearchBase $OUPath -SearchScope OneLevel -Filter * -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction Stop)
        }
        catch {
            return @{ Ok = $false; Err = "Không đọc được User trong OU '$OUPath': $($_.Exception.Message)" }
        }
        $cands = New-Object 'System.Collections.Generic.List[object]'
        $skippedProt = 0
        $lastBlock = ""
        foreach ($u in $raw) {
            $sidVal = if ($u.SID) { $u.SID.Value } else { "" }
            $blk = Test-IsProtectedADAccount $u.SamAccountName $u.DistinguishedName $sidVal ([bool]$u.isCriticalSystemObject) 'user'
            if ($blk) { $skippedProt++; $lastBlock = $blk; continue }
            $sn = if ($u.Name -match '(\d+)$') { [int64]$matches[1] } elseif ($u.SamAccountName -match '(\d+)$') { [int64]$matches[1] } else { [int64]::MaxValue }
            $cands.Add([pscustomobject]@{ Name = $u.Name; Sam = $u.SamAccountName; DN = $u.DistinguishedName; Protected = [bool]$u.ProtectedFromAccidentalDeletion; SortNum = $sn })
        }
        if ($cands.Count -eq 0) {
            if ($lastBlock) { return @{ Ok = $false; Err = $lastBlock } }
            return @{ Ok = $false; Err = "OU này không có User nào để xóa." }
        }
        $sorted = @($cands | Sort-Object SortNum, Name, Sam | Select-Object -First $Count)
        return @{ Ok = $true; Items = $sorted; SkippedProtected = $skippedProt; Requested = $Count; First = $sorted[0]; Last = $sorted[$sorted.Count - 1] }
    }

    if ($Count -le 1) {
        $u = $null
        if ($OUPath -and $OUPath -ne $script:DomainDN) {
            try {
                $oneUsers = @(Get-ADUser -SearchBase $OUPath -SearchScope OneLevel -Filter * -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction Stop)
                $u = $oneUsers | Where-Object {
                    ($bs -and $_.SamAccountName -ieq $bs) -or
                    ($bn -and ($_.Name -ieq $bn -or $_.SamAccountName -ieq $bn))
                } | Select-Object -First 1
            } catch {}
        }
        if ($null -eq $u) {
            $clauses = @()
            if ($bs) { $bsEsc = $bs -replace "'", "''"; $clauses += "SamAccountName -eq '$bsEsc'" }
            if ($bn) {
                $bnEsc = $bn -replace "'", "''"
                $clauses += "Name -eq '$bnEsc'"
                if (-not $bs) { $clauses += "SamAccountName -eq '$bnEsc'" }
            }
            if ($clauses.Count -gt 0) {
                $flt = $clauses -join ' -or '
                try { $u = Get-ADUser -Filter $flt -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction SilentlyContinue | Select-Object -First 1 } catch {}
            }
        }
        if ($null -eq $u) {
            $disp = if ($bn) { $bn } else { $bs }
            return @{ Ok = $false; Err = "Không tìm thấy User '$disp' trên Active Directory." }
        }
        $sidVal = if ($u.SID) { $u.SID.Value } else { "" }
        $blk = Test-IsProtectedADAccount $u.SamAccountName $u.DistinguishedName $sidVal ([bool]$u.isCriticalSystemObject) 'user'
        if ($blk) { return @{ Ok = $false; Err = $blk } }
        $it = [pscustomobject]@{ Name = $u.Name; Sam = $u.SamAccountName; DN = $u.DistinguishedName; Protected = [bool]$u.ProtectedFromAccidentalDeletion; SortNum = [int64]0 }
        return @{ Ok = $true; Items = @($it); SkippedProtected = 0; Requested = 1; First = $it; Last = $it }
    }

    if (-not $OUPath -or $OUPath -eq $script:DomainDN) {
        return @{ Ok = $false; Err = "Hãy chọn một OU cụ thể để xóa nhiều User (không xóa trực tiếp ở gốc domain)." }
    }
    if (Test-IsDomainControllersOU $OUPath) {
        return @{ Ok = $false; Err = "BỊ CHẶN: Không được phép xóa hàng loạt User trong OU Domain Controllers." }
    }
    try {
        $raw = @(Get-ADUser -SearchBase $OUPath -SearchScope OneLevel -Filter * -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction Stop)
    }
    catch {
        return @{ Ok = $false; Err = "Không đọc được User trong OU '$OUPath': $($_.Exception.Message)" }
    }
    $nb = if ($bn) { Split-NumberedBase $bn } else { @{ Prefix = ""; Start = [int64]1; Pad = 0; HasNum = $false } }
    $sb = if ($bs) { Split-NumberedBase $bs } else { @{ Prefix = ""; Start = [int64]1; Pad = 0; HasNum = $false } }

    $cands = New-Object 'System.Collections.Generic.List[object]'
    $skippedProt = 0
    $lastBlock = ""
    foreach ($u in $raw) {
        $matched = $false
        $sortNum = [int64]::MaxValue
        if ($bn -and $nb.HasNum) {
            if ($u.Name -match ('^(?i)' + [regex]::Escape($nb.Prefix) + '(\d+)$')) {
                $numVal = [int64]$matches[1]
                if ($numVal -ge $nb.Start) { $matched = $true; $sortNum = $numVal }
            }
        }
        if (-not $matched -and $bs -and $sb.HasNum) {
            if ($u.SamAccountName -match ('^(?i)' + [regex]::Escape($sb.Prefix) + '(\d+)$')) {
                $numVal = [int64]$matches[1]
                if ($numVal -ge $sb.Start) { $matched = $true; $sortNum = $numVal }
            }
        }
        if (-not $matched -and -not $nb.HasNum -and -not $sb.HasNum) {
            if ($bn -and ($u.Name.StartsWith($bn, [System.StringComparison]::OrdinalIgnoreCase) -or $u.SamAccountName.StartsWith($bn, [System.StringComparison]::OrdinalIgnoreCase))) {
                $matched = $true
                if ($u.Name -match '(\d+)$') { $sortNum = [int64]$matches[1] } elseif ($u.SamAccountName -match '(\d+)$') { $sortNum = [int64]$matches[1] }
            }
            elseif ($bs -and $u.SamAccountName.StartsWith($bs, [System.StringComparison]::OrdinalIgnoreCase)) {
                $matched = $true
                if ($u.SamAccountName -match '(\d+)$') { $sortNum = [int64]$matches[1] }
            }
        }
        if (-not $matched) { continue }
        $sidVal = if ($u.SID) { $u.SID.Value } else { "" }
        $blk = Test-IsProtectedADAccount $u.SamAccountName $u.DistinguishedName $sidVal ([bool]$u.isCriticalSystemObject) 'user'
        if ($blk) { $skippedProt++; $lastBlock = $blk; continue }
        $cands.Add([pscustomobject]@{ Name = $u.Name; Sam = $u.SamAccountName; DN = $u.DistinguishedName; Protected = [bool]$u.ProtectedFromAccidentalDeletion; SortNum = $sortNum })
    }
    if ($cands.Count -eq 0) {
        if ($lastBlock) { return @{ Ok = $false; Err = $lastBlock } }
        $hint = if ($bn) { $bn } else { $bs }
        return @{ Ok = $false; Err = "Không tìm thấy User nào khớp '$hint' trong OU đã chọn." }
    }
    $sorted = @($cands | Sort-Object SortNum, Name, Sam | Select-Object -First $Count)
    return @{ Ok = $true; Items = $sorted; SkippedProtected = $skippedProt; Requested = $Count; First = $sorted[0]; Last = $sorted[$sorted.Count - 1] }
}

function Invoke-DeleteOU {
    param([string]$OuDn, [bool]$Recursive = $false)
    if (-not $script:Ready -or [string]::IsNullOrWhiteSpace($OuDn) -or $OuDn -eq $script:DomainDN) {
        Show-Msg "Hãy chọn một OU cụ thể cần xóa (không phải gốc domain)." "Chưa hợp lệ" "Warning"
        return $false
    }
    if (Test-IsDomainControllersOU $OuDn) {
        Show-Msg "BỊ CHẶN: Không được phép xóa OU hệ thống 'Domain Controllers'." "Bị chặn" "Warning"
        return $false
    }
    $script:Working = $true
    try {
        $ou = $null
        try {
            $ou = Get-ADOrganizationalUnit -Identity $OuDn -Properties ProtectedFromAccidentalDeletion, isCriticalSystemObject -ErrorAction Stop
        }
        catch {
            Show-Msg "Không tìm thấy OU '$OuDn' trên Active Directory." "Không tìm thấy OU" "Warning"
            return $false
        }
        if ([bool]$ou.isCriticalSystemObject) {
            Show-Msg "BỊ CHẶN: Không được phép xóa OU hệ thống ($OuDn)." "Bị chặn" "Warning"
            return $false
        }
        $children = @(Get-ADObject -SearchBase $OuDn -SearchScope OneLevel -Filter * -ErrorAction Stop | Where-Object { $_.DistinguishedName -ne $OuDn })
        if ($children.Count -gt 0 -and -not $Recursive) {
            Show-Msg "OU '$($ou.Name)' đang chứa $($children.Count) đối tượng con (OU con / Group / User / Computer).`r`nHãy tick 'Xóa tự động cả đối tượng con' nếu muốn xóa toàn bộ nhánh OU này, hoặc di chuyển/xóa các đối tượng con trước." "OU không trống" "Warning"
            return $false
        }
        if ($children.Count -gt 0 -and $Recursive) {
            $sub = @(Get-ADObject -SearchBase $OuDn -SearchScope Subtree -Filter * -Properties ObjectClass, SamAccountName, isCriticalSystemObject, objectSid, ProtectedFromAccidentalDeletion -ErrorAction Stop)
            foreach ($item in $sub) {
                if ($item.ObjectClass -eq 'organizationalUnit' -and (Test-IsDomainControllersOU $item.DistinguishedName)) {
                    Show-Msg "BỊ CHẶN: Nhánh OU chứa 'Domain Controllers' — không thể xóa." "Bị chặn" "Warning"
                    return $false
                }
                if ([bool]$item.isCriticalSystemObject) {
                    Show-Msg "BỊ CHẶN: Nhánh OU có chứa đối tượng hệ thống quan trọng ($($item.DistinguishedName))." "Bị chặn" "Warning"
                    return $false
                }
                if ($item.ObjectClass -in @('user', 'group')) {
                    $sidVal = if ($item.objectSid) { $item.objectSid.Value } else { "" }
                    $blk = Test-IsProtectedADAccount $item.SamAccountName $item.DistinguishedName $sidVal ([bool]$item.isCriticalSystemObject) $item.ObjectClass
                    if ($blk) { Show-Msg $blk "Bị chặn" "Warning"; return $false }
                }
            }
            $ouCnt  = @($sub | Where-Object { $_.ObjectClass -eq 'organizationalUnit' }).Count
            $grpCnt = @($sub | Where-Object { $_.ObjectClass -eq 'group' }).Count
            $usrCnt = @($sub | Where-Object { $_.ObjectClass -eq 'user' }).Count
            if ($chkDry.Checked) {
                Write-Log "[CHẠY THỬ] Sẽ XÓA TỰ ĐỘNG nhánh OU '$OuDn' gồm $ouCnt OU, $grpCnt Group, $usrCnt User (tự tắt chống xóa nhầm trước khi xóa)." "Blue"
                return $false
            }
            if (-not (Confirm-Msg "XÓA TỰ ĐỘNG VĨNH VIỄN nhánh OU:`r`n$OuDn`r`n`r`nBao gồm: $ouCnt OU, $grpCnt Group, $usrCnt User (tổng $($sub.Count) đối tượng).`r`nTool sẽ tự tắt bảo vệ chống xóa nhầm và xóa sạch toàn bộ nhánh này.`r`n`r`nBạn có CHẮC CHẮN muốn xóa?" "Cảnh báo xóa tự động nhánh OU" "Warning")) {
                return $false
            }
            Invoke-WithBusy {
                foreach ($item in @($sub | Sort-Object { $_.DistinguishedName.Length } -Descending)) {
                    if ([bool]$item.ProtectedFromAccidentalDeletion) {
                        Set-ADObject -Identity $item.DistinguishedName -ProtectedFromAccidentalDeletion $false -ErrorAction Stop
                    }
                }
                Remove-ADOrganizationalUnit -Identity $OuDn -Recursive -Confirm:$false -ErrorAction Stop
            } "Đang xóa tự động nhánh OU ($($sub.Count) đối tượng)..."
            foreach ($item in $sub) {
                $dnLow = $item.DistinguishedName.ToLower()
                $script:ExpectedRemoved[$dnLow] = $true
                if ($script:AllDN.ContainsKey($dnLow)) { $script:AllDN.Remove($dnLow) }
                if ($item.SamAccountName) {
                    $sk = ([string]$item.SamAccountName).ToLowerInvariant()
                    if ($script:UserSAM.ContainsKey($sk))  { $script:UserSAM.Remove($sk) }
                    if ($script:GroupSAM.ContainsKey($sk)) { $script:GroupSAM.Remove($sk) }
                }
            }
            Write-Log "[OK] Đã xóa tự động nhánh OU ($($sub.Count) đối tượng): $OuDn" "Green"
            $script:Working = $false
            Update-OUList -Force
            return $true
        }

        if ($ou.ProtectedFromAccidentalDeletion) {
            if ($chkDry.Checked) { Write-Log "[CHẠY THỬ] OU '$($ou.Name)' đang bật chống xóa nhầm (Protected). Sẽ tắt bảo vệ và XÓA OU: $OuDn" "Blue"; return $false }
            if (-not (Confirm-Msg "OU '$($ou.Name)' đang BẬT bảo vệ chống xóa nhầm.`r`nTắt bảo vệ và XÓA OU '$OuDn'?" "Cảnh báo xóa OU" "Warning")) { return $false }
        }
        else {
            if ($chkDry.Checked) { Write-Log "[CHẠY THỬ] Sẽ XÓA OU rỗng: $OuDn" "Blue"; return $false }
            if (-not (Confirm-Msg "Xóa vĩnh viễn OU '$OuDn'?" "Cảnh báo xóa OU" "Warning")) { return $false }
        }
        Invoke-WithBusy {
            if ($ou.ProtectedFromAccidentalDeletion) { Set-ADOrganizationalUnit -Identity $OuDn -ProtectedFromAccidentalDeletion $false -ErrorAction Stop }
            try {
                Remove-ADOrganizationalUnit -Identity $OuDn -Confirm:$false -ErrorAction Stop
            }
            catch {
                if ($ou.ProtectedFromAccidentalDeletion) {
                    try { Set-ADOrganizationalUnit -Identity $OuDn -ProtectedFromAccidentalDeletion $true -ErrorAction Stop } catch {}
                }
                throw
            }
        } "Đang xóa OU..."
        $dnLow = $OuDn.ToLower()
        $script:ExpectedRemoved[$dnLow] = $true
        if ($script:AllDN.ContainsKey($dnLow)) { $script:AllDN.Remove($dnLow) }
        Write-Log "[OK] Đã xóa OU: $OuDn" "Green"
        $script:Working = $false
        Update-OUList -Force
        return $true
    }
    catch {
        Write-Log ("[LỖI] Xóa OU: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi xóa OU" "Error"
        return $false
    }
    finally { $script:Working = $false }
}

function Invoke-DeleteADGroup {
    param([string[]]$Identities, [string]$PreferredOU = "")
    if (-not $script:Ready) { return $false }
    $clean = @($Identities | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ } | Select-Object -Unique)
    if ($clean.Count -eq 0) {
        Show-Msg "Hãy nhập tên Group (có thể nhiều tên cách nhau dấu ;) hoặc chọn Group trên sơ đồ cây để xóa." "Chưa hợp lệ" "Warning"
        return $false
    }
    $script:Working = $true
    try {
        $targets = New-Object 'System.Collections.Generic.List[object]'
        $seenDN = @{}
        foreach ($id in $clean) {
            $g = $null
            if ($id -match '^(?i)(CN|OU|DC)=') {
                $g = Get-ADGroup -Identity $id -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction SilentlyContinue
            }
            else {
                $esc = $id -replace "'", "''"
                if ($PreferredOU -and $PreferredOU -ne $script:DomainDN) {
                    try {
                        $g = Get-ADGroup -SearchBase $PreferredOU -SearchScope OneLevel -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction SilentlyContinue | Select-Object -First 1
                    } catch {}
                }
                if ($null -eq $g) {
                    $g = Get-ADGroup -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction SilentlyContinue | Select-Object -First 1
                }
            }
            if ($null -eq $g) {
                Show-Msg "Không tìm thấy Group '$id' trên Active Directory." "Không tìm thấy Group" "Warning"
                return $false
            }
            $sidVal = if ($g.SID) { $g.SID.Value } else { "" }
            $blk = Test-IsProtectedADAccount $g.SamAccountName $g.DistinguishedName $sidVal ([bool]$g.isCriticalSystemObject) 'group'
            if ($blk) {
                Show-Msg $blk "Bị chặn" "Warning"
                return $false
            }
            $dl = $g.DistinguishedName.ToLower()
            if (-not $seenDN.ContainsKey($dl)) {
                $seenDN[$dl] = $true
                $targets.Add([pscustomobject]@{ Name = $g.Name; Sam = $g.SamAccountName; DN = $g.DistinguishedName; Protected = [bool]$g.ProtectedFromAccidentalDeletion })
            }
        }
        if ($chkDry.Checked) {
            foreach ($tg in $targets) {
                Write-Log "[CHẠY THỬ] Sẽ XÓA Group: $($tg.Name) ($($tg.DN))" "Blue"
            }
            return $false
        }
        $summary = if ($targets.Count -eq 1) {
            "Xóa vĩnh viễn Group:`r`n$($targets[0].Name) ($($targets[0].DN))?"
        } else {
            $preview = (($targets | Select-Object -First 5 | ForEach-Object { $_.Name }) -join ', ')
            if ($targets.Count -gt 5) { $preview += ", ... (tổng $($targets.Count) Group)" }
            "Xóa tự động $($targets.Count) Group:`r`n$preview`r`n`r`nTiếp tục?"
        }
        if (-not (Confirm-Msg $summary "Cảnh báo xóa Group" "Warning")) { return $false }

        $res = Invoke-WithBusy {
            $okCnt = 0; $failCnt = 0
            $removedList = New-Object 'System.Collections.Generic.List[object]'
            foreach ($tg in $targets) {
                try {
                    if ($tg.Protected) { Set-ADObject -Identity $tg.DN -ProtectedFromAccidentalDeletion $false -ErrorAction Stop }
                    Remove-ADGroup -Identity $tg.DN -Confirm:$false -ErrorAction Stop
                    $removedList.Add($tg)
                    $okCnt++
                }
                catch {
                    $failCnt++
                    Write-Log ("[LỖI] Xóa Group '$($tg.Name)': " + $_.Exception.Message) "Red"
                }
            }
            @{ Ok = $okCnt; Fail = $failCnt; Removed = $removedList.ToArray() }
        } "Đang xóa Group..."

        foreach ($rm in @($res.Removed)) {
            $dl = $rm.DN.ToLower()
            $script:ExpectedRemoved[$dl] = $true
            if ($script:AllDN.ContainsKey($dl)) { $script:AllDN.Remove($dl) }
            if ($rm.Sam) {
                $sk = $rm.Sam.ToLowerInvariant()
                if ($script:GroupSAM.ContainsKey($sk)) { $script:GroupSAM.Remove($sk) }
            }
            Write-Log "[OK] Đã xóa group: $($rm.DN)" "Green"
        }
        if ($res.Ok -gt 0) {
            $script:Working = $false
            Update-OUList -Force
            return $true
        }
        return $false
    }
    catch {
        Write-Log ("[LỖI] Xóa Group: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi xóa Group" "Error"
        return $false
    }
    finally { $script:Working = $false }
}

function Invoke-DeleteADUsers {
    param([string]$BaseName, [string]$BaseSam, [string]$OUPath, [int]$Count, [string]$ExactDN = "")
    if (-not $script:Ready) { return $false }
    $script:Working = $true
    try {
        $items = @()
        $skippedProt = 0
        if ($ExactDN) {
            $u = $null
            try { $u = Get-ADUser -Identity $ExactDN -Properties isCriticalSystemObject, ProtectedFromAccidentalDeletion, SID -ErrorAction Stop } catch {}
            if ($null -eq $u) { Show-Msg "Không tìm thấy User '$ExactDN' trên AD." "Không tìm thấy User" "Warning"; return $false }
            $sidVal = if ($u.SID) { $u.SID.Value } else { "" }
            $blk = Test-IsProtectedADAccount $u.SamAccountName $u.DistinguishedName $sidVal ([bool]$u.isCriticalSystemObject) 'user'
            if ($blk) { Show-Msg $blk "Bị chặn" "Warning"; return $false }
            $items = @([pscustomobject]@{ Name = $u.Name; Sam = $u.SamAccountName; DN = $u.DistinguishedName; Protected = [bool]$u.ProtectedFromAccidentalDeletion })
        }
        else {
            $plan = Get-UserDeleteBatchPlan $BaseName $BaseSam $OUPath $Count
            if (-not $plan.Ok) {
                $title = if ($plan.Err -like 'BỊ CHẶN:*') { "Bị chặn" } else { "Không xóa được User" }
                Show-Msg $plan.Err $title "Warning"
                return $false
            }
            $items = @($plan.Items)
            $skippedProt = [int]$plan.SkippedProtected
        }

        $total = $items.Count
        $first = $items[0]; $last = $items[$total - 1]
        $rangeTxt = if ($total -eq 1) { "$($first.Name) ($($first.Sam))" } else { "$($first.Name) ($($first.Sam)) -> $($last.Name) ($($last.Sam))" }
        if ($chkDry.Checked) {
            $prevN = [Math]::Min(5, $total)
            for ($i = 0; $i -lt $prevN; $i++) {
                $it = $items[$i]
                Write-Log "[CHẠY THỬ] Sẽ XÓA user: $($it.Name) ($($it.Sam)) [$($it.DN)]" "Blue"
            }
            if ($total -gt 6) {
                Write-Log "[CHẠY THỬ] ... (và $($total - 6) user ở giữa tới trước $($last.Name)) ..." "Blue"
            }
            if ($total -gt 5) {
                Write-Log "[CHẠY THỬ] Sẽ XÓA user: $($last.Name) ($($last.Sam)) [$($last.DN)]" "Blue"
            }
            $skipMsg = if ($skippedProt -gt 0) { " (đã bỏ qua $skippedProt tài khoản hệ thống được bảo vệ)" } else { "" }
            Write-Log "[CHẠY THỬ] Tổng cộng sẽ xóa $total User: $rangeTxt$skipMsg" "Blue"
            return $false
        }

        $skipNote = if ($skippedProt -gt 0) { "`r`n(Đã tự động bỏ qua $skippedProt tài khoản hệ thống được bảo vệ)" } else { "" }
        $confirmText = if ($total -eq 1) {
            "Xóa vĩnh viễn User:`r`n$($first.Name) ($($first.Sam))`r`nDN: $($first.DN)$skipNote`r`n`r`nTiếp tục?"
        } else {
            "XÓA TỰ ĐỘNG $total User:`r`n$rangeTxt`r`nOU: $OUPath$skipNote`r`n`r`nBạn có CHẮC CHẮN muốn xóa?"
        }
        if (-not (Confirm-Msg $confirmText "Cảnh báo xóa User" "Warning")) { return $false }

        $res = Invoke-WithBusy {
            $okCnt = 0; $failCnt = 0
            $removed = New-Object 'System.Collections.Generic.List[object]'
            for ($i = 0; $i -lt $total; $i++) {
                $it = $items[$i]
                if (($i % 10) -eq 0 -or $i -eq ($total - 1)) {
                    $lblStatus.Text = "Đang xóa user $($i + 1)/$total ($($it.Sam))..."
                    $lblStatus.Refresh()
                }
                try {
                    if ($it.Protected) { Set-ADObject -Identity $it.DN -ProtectedFromAccidentalDeletion $false -ErrorAction Stop }
                    Remove-ADUser -Identity $it.DN -Confirm:$false -ErrorAction Stop
                    $removed.Add($it)
                    $okCnt++
                }
                catch {
                    $failCnt++
                    Write-Log ("[LỖI] Xóa User '$($it.Name)' ($($it.Sam)): " + $_.Exception.Message) "Red"
                }
            }
            @{ Ok = $okCnt; Fail = $failCnt; Removed = $removed.ToArray() }
        } "Đang xóa $total User..."

        foreach ($rm in @($res.Removed)) {
            $dl = $rm.DN.ToLower()
            $script:ExpectedRemoved[$dl] = $true
            if ($script:AllDN.ContainsKey($dl)) { $script:AllDN.Remove($dl) }
            if ($rm.Sam) {
                $sk = $rm.Sam.ToLowerInvariant()
                if ($script:UserSAM.ContainsKey($sk)) { $script:UserSAM.Remove($sk) }
            }
        }
        if ($res.Ok -gt 0) {
            Write-Log "[OK] Đã xóa $($res.Ok)/$total User ($rangeTxt)" "Green"
            $script:Working = $false
            Update-OUList -Force
            return $true
        }
        Show-Msg "Xóa User thất bại ($($res.Fail)/$total lỗi). Xem chi tiết ở nhật ký bên dưới." "Lỗi xóa User" "Error"
        return $false
    }
    catch {
        Write-Log ("[LỖI] Xóa User: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi xóa User" "Error"
        return $false
    }
    finally { $script:Working = $false }
}

function Get-RndInt {
    param([int]$Max)
    $b = New-Object byte[] 4
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    $rng.GetBytes($b); $rng.Dispose()
    return [int]([BitConverter]::ToUInt32($b, 0) % [uint32]$Max)
}

function New-RandomPassword {
    param([int]$Len = 14)
    $sets = @('ABCDEFGHJKLMNPQRSTUVWXYZ', 'abcdefghijkmnopqrstuvwxyz', '23456789', '!@#$%&*?')
    $all = $sets -join ''
    $chars = New-Object System.Collections.ArrayList
    foreach ($st in $sets) { [void]$chars.Add($st[(Get-RndInt $st.Length)]) }
    while ($chars.Count -lt $Len) { [void]$chars.Add($all[(Get-RndInt $all.Length)]) }
    for ($i = $chars.Count - 1; $i -gt 0; $i--) {
        $j = Get-RndInt ($i + 1)
        $t = $chars[$i]; $chars[$i] = $chars[$j]; $chars[$j] = $t
    }
    return (-join $chars)
}

function Test-SamName {
    param([string]$n, [int]$Max = 20)
    if ([string]::IsNullOrWhiteSpace($n)) { return "Chưa nhập tên." }
    if ($n -ne $n.Trim() -or $n.EndsWith('.')) { return "Không được bắt đầu/kết thúc bằng dấu cách, không kết thúc bằng dấu chấm." }
    if ($n.Length -gt $Max) { return "Tối đa $Max ký tự." }
    if ($n -match '["/\\\[\]:;|=,+*?<>@]') { return 'Không được chứa các ký tự  " / \ [ ] : ; | = , + * ? < > @' }
    return $null
}

function Test-CnName {
    param([string]$n)
    if ([string]::IsNullOrWhiteSpace($n)) { return "Chưa nhập họ tên." }
    if ($n -ne $n.Trim()) { return "Không được bắt đầu/kết thúc bằng dấu cách." }
    if ($n -match '[,\+"\\<>;=/#]') { return 'Không được chứa các ký tự:  , + " \ < > ; = / #' }
    if ($n.Length -gt 64) { return "Tên quá dài (tối đa 64 ký tự)." }
    return $null
}

function Update-GrpCheck {
    $n = $txtGrpName.Text
    $lblGrpCheck.Text = ""
    if ([string]::IsNullOrWhiteSpace($n) -or -not $script:Ready) { $btnCreateGrp.Enabled = $script:Ready; return }
    $err = Test-SamName $n 64
    if (-not $err) { $err = Test-CnName $n }
    if ($err) { $lblGrpCheck.ForeColor = [System.Drawing.Color]::Firebrick; $lblGrpCheck.Text = "✖ Tên chưa hợp lệ"; $btnCreateGrp.Enabled = $false; return }
    if ($script:GroupSAM.ContainsKey($n.ToLower()) -or $script:UserSAM.ContainsKey($n.ToLower())) {
        $lblGrpCheck.ForeColor = [System.Drawing.Color]::Firebrick; $lblGrpCheck.Text = "⚠ Đã có tên này trong domain"; $btnCreateGrp.Enabled = $false
    }
    else {
        $lblGrpCheck.ForeColor = [System.Drawing.Color]::ForestGreen; $lblGrpCheck.Text = "✔ Chưa có, tạo được"; $btnCreateGrp.Enabled = $true
    }
}

function Update-UsrButtonText {
    if (-not $btnCreateUsr) { return }
    $cnt = Get-DesiredUsrCount
    if ($cnt -gt 1) {
        $btnCreateUsr.Text = if ($chkDry -and $chkDry.Checked) { "Tạo $cnt User (Thử)" } else { "Tạo $cnt User" }
        if ($btnDeleteUsr) { $btnDeleteUsr.Text = if ($chkDry -and $chkDry.Checked) { "Xóa $cnt User (Thử)" } else { "Xóa $cnt User" } }
    }
    else {
        $btnCreateUsr.Text = if ($chkDry -and $chkDry.Checked) { "Tạo User (Thử)" } else { "Tạo User" }
        if ($btnDeleteUsr) { $btnDeleteUsr.Text = if ($chkDry -and $chkDry.Checked) { "Xóa User (Thử)" } else { "Xóa User" } }
    }
}

function Update-UsrCheck {
    $n = $txtUsrName.Text.Trim(); $sam = $txtUsrSam.Text.Trim()
    $cnt = Get-DesiredUsrCount
    $lblUsrCheck.Text = ""
    if ([string]::IsNullOrWhiteSpace($n) -or -not $script:Ready) { $btnCreateUsr.Enabled = $script:Ready; return }
    $err = Test-CnName $n
    if (-not $err) { $err = Test-SamName $sam 20 }
    if ($err) { $lblUsrCheck.ForeColor = [System.Drawing.Color]::Firebrick; $lblUsrCheck.Text = "✖ " + $err; $btnCreateUsr.Enabled = $false; return }
    if ($cnt -gt 1) {
        $targetPath = if ($cboUsrOU.SelectedIndex -ge 0 -and $cboUsrOU.SelectedIndex -lt $script:OUDN.Count) { $script:OUDN[$cboUsrOU.SelectedIndex] } else { $script:DomainDN }
        $plan = Get-UserBatchPlan $n $sam $targetPath $cnt
        if (-not $plan.Ok) {
            $lblUsrCheck.ForeColor = [System.Drawing.Color]::Firebrick
            $lblUsrCheck.Text = "✖ " + $plan.Err
            $btnCreateUsr.Enabled = $false
            return
        }
        $lblUsrCheck.ForeColor = [System.Drawing.Color]::ForestGreen
        $rangeTxt = "$($plan.First.Name) ($($plan.First.Sam)) -> $($plan.Last.Name) ($($plan.Last.Sam))"
        $lblUsrCheck.Text = if ($plan.Skipped -gt 0) {
            "✔ Bỏ qua $($plan.Skipped) trùng -> tạo $($cnt): $rangeTxt"
        } else {
            "✔ Tạo $($cnt) user: $rangeTxt"
        }
        $btnCreateUsr.Enabled = $true
        return
    }
    if ($script:UserSAM.ContainsKey($sam.ToLower()) -or $script:GroupSAM.ContainsKey($sam.ToLower())) {
        $lblUsrCheck.ForeColor = [System.Drawing.Color]::Firebrick; $lblUsrCheck.Text = "⚠ Tên đăng nhập đã tồn tại"; $btnCreateUsr.Enabled = $false; return
    }
    if ($cboUsrOU.SelectedIndex -ge 0) {
        $dnu = ("CN=" + ($n -replace ',', '\,') + "," + $script:OUDN[$cboUsrOU.SelectedIndex]).ToLower()
        if ($script:AllDN.ContainsKey($dnu)) {
            $lblUsrCheck.ForeColor = [System.Drawing.Color]::Firebrick; $lblUsrCheck.Text = "⚠ Đã có đối tượng trùng họ tên trong OU này"; $btnCreateUsr.Enabled = $false; return
        }
    }
    $lblUsrCheck.ForeColor = [System.Drawing.Color]::ForestGreen; $lblUsrCheck.Text = "✔ Chưa có, tạo được"; $btnCreateUsr.Enabled = $true
}

function New-OneGroup {
    param([string]$Name, [string]$Path, [string]$Scope, [string]$Cat, [string]$Desc)
    $script:LastCreateErr = ""
    $err = Test-SamName $Name 64
    if (-not $err) { $err = Test-CnName $Name }
    if ($err) { $script:LastCreateErr = "Group '$Name': $err"; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ($Path -eq $script:DomainDN) { $script:LastCreateErr = "Không thể tạo Group trực tiếp ở gốc domain. Hãy chọn một OU hoặc Container."; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    try { Get-ADObject -Identity $Path -ErrorAction Stop | Out-Null }
    catch { $script:LastCreateErr = "Không tìm thấy nơi chứa: $Path"; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ($script:GroupSAM.ContainsKey($Name.ToLower()) -or $script:UserSAM.ContainsKey($Name.ToLower())) { Write-Log "[BỎ QUA] Đã có tên '$Name' trong domain." "DarkOrange"; return "skip" }
    $dng = ("CN=" + ($Name -replace ',', '\,') + "," + $Path).ToLower()
    if ($script:AllDN.ContainsKey($dng)) { Write-Log "[BỎ QUA] Đã có đối tượng '$Name' trong $Path" "DarkOrange"; return "skip" }
    if ($chkDry.Checked) { Write-Log ("[CHẠY THỬ] Sẽ tạo group: " + $Name + " (" + $Cat + " / " + $Scope + ") trong " + $Path) "Blue"; return "dry" }
    try {
        $p = @{ Name = $Name; SamAccountName = $Name; GroupScope = $Scope; GroupCategory = $Cat; Path = $Path; PassThru = $true; ErrorAction = 'Stop' }
        if (-not [string]::IsNullOrWhiteSpace($Desc)) { $p.Description = $Desc }
        $g = New-ADGroup @p
        $dnLow = $g.DistinguishedName.ToLower()
        $script:Created[$dnLow] = $true
        $script:AllDN[$dnLow]   = $true
        $script:GroupSAM[$Name.ToLower()] = $true
        Write-Log ("[OK] Đã tạo group: " + $g.DistinguishedName) "Green"
        return "ok"
    }
    catch { $script:LastCreateErr = "Group '" + $Name + "': " + $_.Exception.Message; Write-Log ("[LỖI] " + $script:LastCreateErr) "Red"; return "fail" }
}

function New-OneUser {
    param([string]$FullName, [string]$Sam, [string]$Pwd, [string]$Path, [string]$Desc, [bool]$Change, [bool]$Never, [bool]$Enabled, [string]$Groups, [bool]$CannotChange = $false)
    $script:LastCreateErr = ""
    $err = Test-CnName $FullName
    if (-not $err) { $err = Test-SamName $Sam 20 }
    if ($err) { $script:LastCreateErr = "User '$FullName' ($Sam): $err"; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ($Path -eq $script:DomainDN) { $script:LastCreateErr = "Không thể tạo User trực tiếp ở gốc domain. Hãy chọn một OU hoặc Container."; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ([string]::IsNullOrEmpty($Pwd)) { $script:LastCreateErr = "User '$FullName': chưa có mật khẩu."; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ($Change -and $Never) { $script:LastCreateErr = "User '$FullName': không thể vừa bắt đổi mật khẩu vừa đặt không hết hạn."; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ($Change -and $CannotChange) { $script:LastCreateErr = "User '$FullName': không thể vừa bắt đổi mật khẩu vừa không cho user tự đổi mật khẩu."; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    try { Get-ADObject -Identity $Path -ErrorAction Stop | Out-Null }
    catch { $script:LastCreateErr = "Không tìm thấy nơi chứa: $Path"; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    if ($script:UserSAM.ContainsKey($Sam.ToLower()) -or $script:GroupSAM.ContainsKey($Sam.ToLower())) { Write-Log "[BỎ QUA] Tên đăng nhập '$Sam' đã tồn tại." "DarkOrange"; return "skip" }
    $dnu = ("CN=" + ($FullName -replace ',', '\,') + "," + $Path).ToLower()
    if ($script:AllDN.ContainsKey($dnu)) { Write-Log "[BỎ QUA] Đã có đối tượng '$FullName' trong $Path" "DarkOrange"; return "skip" }
    $gl = @(([string]$Groups) -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    $unknown = @($gl | Where-Object { -not $script:GroupSAM.ContainsKey($_.ToLower()) })
    if ($unknown.Count -gt 0) { $script:LastCreateErr = "User '" + $FullName + "': không tìm thấy group: " + ($unknown -join ', '); Write-Log ("[LỖI] " + $script:LastCreateErr) "Red"; return "fail" }
    if ($chkDry.Checked) {
        $x = "Sẽ tạo user: " + $FullName + " (" + $Sam + ") trong " + $Path
        if (-not $Change) { $x += "; không bắt đổi pass" }
        if ($CannotChange) { $x += "; không cho tự đổi pass" }
        if ($Never) { $x += "; pass không hết hạn" }
        if ($gl.Count -gt 0) { $x += "; thêm vào group: " + ($gl -join ', ') }
        Write-Log ("[CHẠY THỬ] " + $x) "Blue"; return "dry"
    }
    try {
        $parts = @($FullName -split '\s+' | Where-Object { $_ })
        $p = @{
            Name = $FullName; DisplayName = $FullName; SamAccountName = $Sam
            UserPrincipalName = ($Sam + '@' + $script:DomainName); Path = $Path
            AccountPassword = (ConvertTo-SecureString $Pwd -AsPlainText -Force)
            Enabled = $Enabled; ChangePasswordAtLogon = $Change; PasswordNeverExpires = $Never; CannotChangePassword = $CannotChange
            PassThru = $true; ErrorAction = 'Stop'
        }
        if ($parts.Count -ge 2) { $p.GivenName = $parts[$parts.Count - 1]; $p.Surname = ($parts[0..($parts.Count - 2)] -join ' ') }
        if (-not [string]::IsNullOrWhiteSpace($Desc)) { $p.Description = $Desc }
        $u = New-ADUser @p
        $dnLow = $u.DistinguishedName.ToLower()
        $script:Created[$dnLow] = $true
        $script:AllDN[$dnLow]   = $true
        $script:UserSAM[$Sam.ToLower()] = $true
        Write-Log ("[OK] Đã tạo user: " + $u.DistinguishedName + $(if ($Enabled) { "" } else { "  (đang tắt)" })) "Green"
        foreach ($gn in $gl) {
            try { Add-ADGroupMember -Identity $gn -Members $u.DistinguishedName -ErrorAction Stop; Write-Log ("      Đã thêm vào group: " + $gn) "DimGray" }
            catch { Write-Log ("      [LỖI] Không thêm được vào group '" + $gn + "': " + $_.Exception.Message) "Red" }
        }
        return "ok"
    }
    catch {
        $m = $_.Exception.Message
        if ($m -match '(?i)password|mật khẩu') { $m += "  -> Mật khẩu chưa đạt chính sách mật khẩu của domain (độ dài/độ phức tạp)." }
        $script:LastCreateErr = "User '" + $FullName + "': " + $m
        Write-Log ("[LỖI] " + $script:LastCreateErr) "Red"
        return "fail"
    }
}

# Khối lệnh bật/tắt tự đồng bộ giờ (chạy trên máy đích)
$script:TimeOffText = @'
Stop-Service w32time -Force -ErrorAction SilentlyContinue
Set-Service w32time -StartupType Disabled -ErrorAction SilentlyContinue
if (Get-Service vmictimesync -ErrorAction SilentlyContinue) {
    Stop-Service vmictimesync -Force -ErrorAction SilentlyContinue
    Set-Service vmictimesync -StartupType Disabled -ErrorAction SilentlyContinue
}
$vt = Join-Path $env:ProgramFiles 'VMware\VMware Tools\VMwareToolboxCmd.exe'
if (Test-Path -LiteralPath $vt) { & $vt timesync disable | Out-Null }
'@
$script:TimeOnText = @'
Set-Service w32time -StartupType Automatic -ErrorAction SilentlyContinue
Start-Service w32time -ErrorAction SilentlyContinue
if (Get-Service vmictimesync -ErrorAction SilentlyContinue) {
    Set-Service vmictimesync -StartupType Manual -ErrorAction SilentlyContinue
    Start-Service vmictimesync -ErrorAction SilentlyContinue
}
$vt = Join-Path $env:ProgramFiles 'VMware\VMware Tools\VMwareToolboxCmd.exe'
if (Test-Path -LiteralPath $vt) { & $vt timesync enable | Out-Null }
'@

function Get-LinkedGpoNames {
    param($GpLink, $Map)
    $names = @()
    if (-not $GpLink) { return $names }
    $matches = @([regex]::Matches([string]$GpLink, '\{([0-9A-Fa-f\-]{36})\},[^;\]]*;(\d+)'))
    # gPLink lưu ngược thứ tự ưu tiên; đảo ngược để khớp Link Order trong GPMC
    [array]::Reverse($matches)
    foreach ($m in $matches) {
        $id  = $m.Groups[1].Value.ToLower()
        $opt = [int]$m.Groups[2].Value
        $nm  = if ($Map.ContainsKey($id)) { $Map[$id] } else { $id }
        if ($opt -band 1) { $nm += " (đang tắt)" }
        if ($opt -band 2) { $nm += " (Enforced)" }
        $names += $nm
    }
    return $names
}

function Test-IsDomainControllersOU {
    param([string]$DN)
    return ($script:DomainControllersDN -and [string]::Equals($DN, $script:DomainControllersDN, 'OrdinalIgnoreCase'))
}

function Find-DNIndex {
    param([string]$DN)
    for ($i = 0; $i -lt $script:OUDN.Count; $i++) {
        if ([string]::Equals($script:OUDN[$i], $DN, 'OrdinalIgnoreCase')) { return $i }
    }
    return -1
}

function Get-ActiveCombo {
    if ($tabs.SelectedTab -eq $tabGPO) { return $cboGPOTarget }
    elseif ($tabs.SelectedTab -eq $tabLib) { return $cboLibTarget }
    elseif ($tabs.SelectedTab -eq $tabOU) {
        if ($subTabs.SelectedTab -eq $pgGrp) { return $cboGrpOU }
        elseif ($subTabs.SelectedTab -eq $pgUsr) { return $cboUsrOU }
        elseif ($subTabs.SelectedTab -eq $pgOUMgmt) { return $cboMgmtOU }
        else { return $cboOUParent }
    }
    elseif ($tabs.SelectedTab -eq $tabQuota) {
        if ($subQuotaTabs.SelectedTab -eq $pgShare) { return $cboShOU }
        else { return $cboQuotaTarget }
    }
    elseif ($tabs.SelectedTab -eq $tabDeploy) { return $cboDeployTarget }
    else { return $null }
}

function Set-TreeSelectionFromCombo {
    $c = Get-ActiveCombo
    if ($null -eq $c) { return }
    if ($c.SelectedIndex -lt 0 -or $c.SelectedIndex -ge $script:OUDN.Count) { return }
    $k = $script:OUDN[$c.SelectedIndex].ToLower()
    if ($script:NodeMap.ContainsKey($k)) { $tree.SelectedNode = $script:NodeMap[$k] }
}

function Update-NameCheck {
    $n = $txtOUName.Text
    $lblOUCheck.Text = ""
    if ([string]::IsNullOrWhiteSpace($n) -or -not $script:Ready) {
        $btnCreateOU.Enabled = $script:Ready
        return
    }
    $err = Test-OUName $n
    if ($err) {
        $lblOUCheck.ForeColor = [System.Drawing.Color]::Firebrick
        $lblOUCheck.Text = "✖ Tên chưa hợp lệ"
        $btnCreateOU.Enabled = $false
        return
    }
    if ($cboOUParent.SelectedIndex -lt 0) { return }
    $parent = $script:OUDN[$cboOUParent.SelectedIndex]
    $key = ("OU=$n,$parent").ToLower()
    if ($script:OUSet.ContainsKey($key)) {
        $lblOUCheck.ForeColor = [System.Drawing.Color]::Firebrick
        $lblOUCheck.Text = "⚠ Đã có OU này ở đây rồi"
        $btnCreateOU.Enabled = $false
    }
    else {
        $others = $script:OUByName[$n.ToLower()]
        if ($others) {
            $lblOUCheck.ForeColor = [System.Drawing.Color]::DarkOrange
            $lblOUCheck.Text = "ℹ Cùng tên đã có ở " + @($others).Count + " nơi khác"
        }
        else {
            $lblOUCheck.ForeColor = [System.Drawing.Color]::ForestGreen
            $lblOUCheck.Text = "✔ Chưa có, tạo được"
        }
        $btnCreateOU.Enabled = $true
    }
}

# Vẽ các OU "sẽ tạo" (xem trước) lên sơ đồ
function Update-Ghosts {
    if (-not $script:Ready) { return }
    $tree.BeginUpdate()
    foreach ($g in @($script:GhostNodes)) { if ($g.Parent) { $g.Remove() } }
    $script:GhostNodes = @()

    $items = @()
    foreach ($c in $script:CsvPreview) { $items += $c }
    $n = $txtOUName.Text
    if (-not [string]::IsNullOrWhiteSpace($n) -and $null -eq (Test-OUName $n) -and $cboOUParent.SelectedIndex -ge 0) {
        $items += @{ Name = $n; Path = $script:OUDN[$cboOUParent.SelectedIndex] }
    }

    $local = @{}
    foreach ($it in $items) {
        if (Test-OUName ([string]$it.Name)) { continue }
        $dn = "OU=" + $it.Name + "," + $it.Path
        $k  = $dn.ToLower()
        if ($script:OUSet.ContainsKey($k) -or $local.ContainsKey($k)) { continue }
        $pk = ([string]$it.Path).ToLower()
        $pn = $null
        if ($script:NodeMap.ContainsKey($pk)) { $pn = $script:NodeMap[$pk] }
        elseif ($local.ContainsKey($pk))      { $pn = $local[$pk] }
        if ($null -eq $pn) { continue }
        $node = New-Object System.Windows.Forms.TreeNode ("+ " + $it.Name + "  (sẽ tạo)")
        $node.Tag = "G:" + $dn
        $node.ForeColor = Get-ThemeColor "ForestGreen"
        $node.NodeFont  = $fontItalic
        $node.ImageIndex = 2; $node.SelectedImageIndex = 2
        [void]$pn.Nodes.Add($node)
        $pn.Expand()
        $local[$k] = $node
        $script:GhostNodes += $node
    }
    $tree.EndUpdate()
}

function Select-OUFromTree {
    param([string]$DN, [bool]$IsDirectOU = $true)
    $c = Get-ActiveCombo
    if ($null -eq $c) { return }
    $idx = Find-DNIndex $DN
    if ($idx -lt 0) { return }
    $script:Sync = $true
    $c.SelectedIndex = $idx
    if ($IsDirectOU) {
        if ($tabs.SelectedTab -eq $tabDeploy) {
            if ($DN -ieq $script:DomainDN) { $rdoDAll.Checked = $true } else { $rdoDOU.Checked = $true }
            $chkDGroup.Checked = $false
            $txtDGroup.Clear()
        }
        if ($c -eq $cboShOU) {
            if ($DN -ieq $script:DomainDN) { $cboShTargetType.SelectedIndex = 0 } else { $cboShTargetType.SelectedIndex = 1 }
            $txtShPrincipal.Clear()
        }
        if ($tabs.SelectedTab -eq $tabGPO) {
            $cboGpoScopeType.SelectedIndex = 0
            $txtGpoScopeTarget.Clear()
        }
        if ($tabs.SelectedTab -eq $tabLib) {
            $cboLibScopeType.SelectedIndex = 0
            $txtLibScopeTarget.Clear()
        }
        if ($tabs.SelectedTab -eq $tabQuota -and $subQuotaTabs.SelectedTab -eq $pgQuota) {
            $cboQuotaScopeType.SelectedIndex = 0
            $txtQuotaScopeTarget.Clear()
        }
    }
    $script:Sync = $false
    Update-Ghosts
    Update-NameCheck
    Update-GrpCheck
    Update-UsrCheck
}

# Đọc lại AD, tự phát hiện OU mới/xóa (kể cả tạo tay), vẽ lại sơ đồ khi có thay đổi
function Update-OUList {
    param([switch]$Force)
    if ((-not $Force -and $script:Working) -or $script:Refreshing) { return }
    $script:Refreshing = $true
    try {
        $rootLink = ""
        try { $rootLink = (Get-ADObject -Identity $script:DomainDN -Properties gPLink -ErrorAction Stop).gPLink } catch {}

        $ousList = New-Object 'System.Collections.Generic.List[object]'
        foreach ($ouObj in @(Get-ADOrganizationalUnit -Filter * -Properties Description, gPLink, gPOptions -ErrorAction Stop)) {
            $parts = [regex]::Split($ouObj.DistinguishedName, '(?<!\\),')
            [array]::Reverse($parts)
            $ousList.Add([pscustomobject]@{
                DN         = $ouObj.DistinguishedName
                Name       = $ouObj.Name
                Desc       = $ouObj.Description
                GpLink     = $ouObj.gPLink
                GpoOptions = [int]($ouObj.gPOptions)
                Key        = ($parts -join [char]1).ToLowerInvariant()
                Depth      = ([regex]::Matches($ouObj.DistinguishedName, '(?i)(^|(?<!\\),)OU=')).Count
            })
        }
        $ousList.Sort([System.Comparison[object]]{ param($a, $b) [string]::CompareOrdinal($a.Key, $b.Key) })
        $ous = $ousList.ToArray()

        # --- Group / User ---
        $grps = @(); $usrs = @(); $objLoadOk = $true
        try {
            $grps = @(Get-ADGroup -Filter * -Properties Description, member -ErrorAction Stop | ForEach-Object {
                $memList = @($_.member | Where-Object { $_ } | ForEach-Object { [string]$_ })
                [pscustomobject]@{ Kind = 'GR'; DN = $_.DistinguishedName; Name = $_.Name; Sam = $_.SamAccountName; Desc = $_.Description
                                   Scope = [string]$_.GroupScope; Cat = [string]$_.GroupCategory; Members = $memList.Count; MemberDNs = $memList; Enabled = $true
                                   Extra = ($memList.Count.ToString() + ':' + (($memList | Sort-Object) -join '|')) } })
            $usrs = @(Get-ADUser -Filter * -Properties Description, Enabled -ErrorAction Stop | ForEach-Object {
                [pscustomobject]@{ Kind = 'US'; DN = $_.DistinguishedName; Name = $_.Name; Sam = $_.SamAccountName; Desc = $_.Description
                                   Scope = ''; Cat = ''; Members = 0; MemberDNs = @(); Enabled = [bool]$_.Enabled; Extra = [string][bool]$_.Enabled } })
        }
        catch {
            $objLoadOk = $false
            if (-not $script:Loaded) {
                $script:GroupSAM = @{}; $script:UserSAM = @{}; $script:AllDN = @{}
            }
            Write-Log ("[CẢNH BÁO] Không đọc được danh sách Group/User từ AD (giữ dữ liệu cũ): " + $_.Exception.Message) "DarkOrange"
        }

        $ouKeys = @{}
        foreach ($o in $ous) { $ouKeys[$o.DN.ToLower()] = $o.Name }
        $objs = @()
        if ($objLoadOk) {
            $script:GroupSAM = @{}; $script:UserSAM = @{}; $script:AllDN = @{}
            $script:ObjByDN = @{}; $script:LastAllUsersByDN = @{}; $script:LastAllGroupsByDN = @{}
            foreach ($g in $grps) {
                $dl = $g.DN.ToLower()
                $script:GroupSAM[([string]$g.Sam).ToLower()] = $true
                $script:AllDN[$dl] = $true
                $script:ObjByDN[$dl] = $g
                $script:LastAllGroupsByDN[$dl] = $g
            }
            foreach ($u in $usrs) {
                $dl = $u.DN.ToLower()
                $script:UserSAM[([string]$u.Sam).ToLower()] = $true
                $script:AllDN[$dl] = $true
                $script:ObjByDN[$dl] = $u
                $script:LastAllUsersByDN[$dl] = $u
            }
            foreach ($o in (@($grps) + @($usrs))) {
                $pdn = ($o.DN -split '(?<!\\)(?:\\\\)*,', 2)[1]
                if ($pdn -and $ouKeys.ContainsKey($pdn.ToLower())) {
                    $o | Add-Member -NotePropertyName ParentDN -NotePropertyValue $pdn -Force
                    $o | Add-Member -NotePropertyName ParentName -NotePropertyValue $ouKeys[$pdn.ToLower()] -Force
                    $objs += $o
                }
            }
            $script:LastObjs = $objs
        }
        elseif ($null -ne $script:LastObjs) {
            $objs = @($script:LastObjs)
        }

        # --- Bản đồ GPO ---
        $gpoMap = @{}
        try { Get-GPO -All -ErrorAction Stop | ForEach-Object { $gpoMap[$_.Id.ToString().ToLower()] = $_.DisplayName } } catch {}
        $gpoMapSig = (($gpoMap.Keys | Sort-Object | ForEach-Object { $_ + '=' + $gpoMap[$_] }) -join ';')

        $sig = $rootLink + "`n" + (($ous | ForEach-Object { $_.DN + '|' + $_.GpLink + '|' + $_.Desc + '|' + $_.GpoOptions }) -join "`n") + "`n" + (($objs | ForEach-Object { $_.Kind + $_.DN + '|' + $_.Extra }) -join "`n") + "`n" + $gpoMapSig + "`n" + [string]$chkShowObj.Checked
        if (-not $Force -and $sig -eq $script:OUSig) { return }
        $script:OUSig = $sig

        # --- Phát hiện thay đổi so với lần trước ---
        $newSet = @{}
        $byName = @{}
        foreach ($o in $ous) {
            $newSet[$o.DN.ToLower()] = $o.Name
            $nk = $o.Name.ToLower()
            if (-not $byName.ContainsKey($nk)) { $byName[$nk] = @() }
            $byName[$nk] += $o.DN
        }
        $script:NewDN = @{}
        if ($script:Loaded) {
            foreach ($k in $newSet.Keys) {
                if (-not $script:OUSet.ContainsKey($k)) {
                    if ($script:Created.ContainsKey($k)) { $script:Created.Remove($k) }
                    else {
                        $script:NewDN[$k] = $true
                        Write-Log ("[PHÁT HIỆN] OU mới (tạo ngoài tool): " + $newSet[$k]) "DarkOrange"
                    }
                }
            }
            foreach ($k in $script:OUSet.Keys) {
                if (-not $newSet.ContainsKey($k)) {
                    if ($script:ExpectedRemoved.ContainsKey($k)) { $script:ExpectedRemoved.Remove($k) }
                    else { Write-Log ("[PHÁT HIỆN] OU đã bị xóa hoặc đổi tên: " + $script:OUSet[$k]) "DarkOrange" }
                }
            }
        }
        # --- Phát hiện group/user mới hoặc mất ---
        if ($objLoadOk) {
            $newObj = @{}
            foreach ($o in $objs) { $newObj[$o.DN.ToLower()] = $o }
            $script:NewObj = @{}
            if ($script:Loaded) {
                foreach ($k in $newObj.Keys) {
                    if (-not $script:ObjSet.ContainsKey($k)) {
                        if ($script:Created.ContainsKey($k)) { $script:Created.Remove($k) }
                        else {
                            $script:NewObj[$k] = $true
                            $kind = if ($newObj[$k].Kind -eq 'GR') { 'Group' } else { 'User' }
                            Write-Log ("[PHÁT HIỆN] " + $kind + " mới (tạo ngoài tool): " + $newObj[$k].Name + "  (trong OU " + $newObj[$k].ParentName + ")") "DarkOrange"
                        }
                    }
                }
                foreach ($k in $script:ObjSet.Keys) {
                    if (-not $newObj.ContainsKey($k)) {
                        if ($script:ExpectedRemoved.ContainsKey($k)) { $script:ExpectedRemoved.Remove($k) }
                        else { Write-Log ("[PHÁT HIỆN] Group/User đã bị xóa, di chuyển hoặc đổi tên: " + $script:ObjSet[$k]) "DarkOrange" }
                    }
                }
            }
            $script:ObjSet = @{}
            foreach ($k in $newObj.Keys) { $script:ObjSet[$k] = $newObj[$k].Name }
        }

        $firstLoad       = (-not $script:Loaded)
        $script:OUSet    = $newSet
        $script:OUByName = $byName
        $script:Loaded   = $true

        $prevOU  = ""; if ($cboOUParent.SelectedIndex  -ge 0 -and $cboOUParent.SelectedIndex  -lt $script:OUDN.Count) { $prevOU  = $script:OUDN[$cboOUParent.SelectedIndex] }
        $prevGPO = ""; if ($cboGPOTarget.SelectedIndex -ge 0 -and $cboGPOTarget.SelectedIndex -lt $script:OUDN.Count) { $prevGPO = $script:OUDN[$cboGPOTarget.SelectedIndex] }
        $prevLib = ""; if ($cboLibTarget.SelectedIndex -ge 0 -and $cboLibTarget.SelectedIndex -lt $script:OUDN.Count) { $prevLib = $script:OUDN[$cboLibTarget.SelectedIndex] }
        $prevQuota  = ""; if ($cboQuotaTarget.SelectedIndex  -ge 0 -and $cboQuotaTarget.SelectedIndex  -lt $script:OUDN.Count) { $prevQuota  = $script:OUDN[$cboQuotaTarget.SelectedIndex] }
        $prevDeploy = ""; if ($cboDeployTarget.SelectedIndex -ge 0 -and $cboDeployTarget.SelectedIndex -lt $script:OUDN.Count) { $prevDeploy = $script:OUDN[$cboDeployTarget.SelectedIndex] }
        $prevGrp = ""; if ($cboGrpOU.SelectedIndex -ge 0 -and $cboGrpOU.SelectedIndex -lt $script:OUDN.Count) { $prevGrp = $script:OUDN[$cboGrpOU.SelectedIndex] }
        $prevUsr = ""; if ($cboUsrOU.SelectedIndex -ge 0 -and $cboUsrOU.SelectedIndex -lt $script:OUDN.Count) { $prevUsr = $script:OUDN[$cboUsrOU.SelectedIndex] }
        $prevShOU = ""; if ($cboShOU.SelectedIndex -ge 0 -and $cboShOU.SelectedIndex -lt $script:OUDN.Count) { $prevShOU = $script:OUDN[$cboShOU.SelectedIndex] }
        $prevMgmtOU = ""; if ($cboMgmtOU.SelectedIndex -ge 0 -and $cboMgmtOU.SelectedIndex -lt $script:OUDN.Count) { $prevMgmtOU = $script:OUDN[$cboMgmtOU.SelectedIndex] }

        # --- Danh sách thả xuống ---
        $script:Sync = $true
        $script:OUDN = @($script:DomainDN)
        $labels = @("(Gốc của domain) " + $script:DomainName)
        foreach ($o in $ous) {
            $script:OUDN += $o.DN
            $labels += (("    " * ($o.Depth - 1)) + "└ " + $o.Name)
        }
        $requireOuCombos = @($cboGrpOU, $cboUsrOU, $cboMgmtOU, $cboShOU, $cboGPOTarget, $cboLibTarget, $cboQuotaTarget, $cboDeployTarget)
        foreach ($pair in @(@($cboOUParent, $prevOU), @($cboGPOTarget, $prevGPO), @($cboLibTarget, $prevLib), @($cboQuotaTarget, $prevQuota), @($cboDeployTarget, $prevDeploy), @($cboGrpOU, $prevGrp), @($cboUsrOU, $prevUsr), @($cboShOU, $prevShOU), @($cboMgmtOU, $prevMgmtOU))) {
            $c = $pair[0]
            $c.Items.Clear()
            $c.Items.AddRange([object[]]$labels)
            $isReqOu = (@($requireOuCombos | Where-Object { [object]::ReferenceEquals($_, $c) }).Count -gt 0)
            $i = -1
            if ($pair[1]) {
                $j = Find-DNIndex $pair[1]
                if ($j -ge 0) { $i = $j }
            }
            if ($i -lt 0) {
                $i = 0
                if ($isReqOu -and $script:OUDN.Count -gt 1) {
                    for ($k = 1; $k -lt $script:OUDN.Count; $k++) {
                        if (-not (Test-IsDomainControllersOU $script:OUDN[$k])) { $i = $k; break }
                    }
                }
            }
            $c.SelectedIndex = $i
        }

        # --- Sơ đồ cây ---
        $collapsed = @{}
        $stack = New-Object System.Collections.Stack
        foreach ($rn in $tree.Nodes) { $stack.Push($rn) }
        while ($stack.Count -gt 0) {
            $nd = $stack.Pop()
            if ($nd.Nodes.Count -gt 0 -and -not $nd.IsExpanded -and ($nd.Tag -notlike "G:*")) { $collapsed[[string]$nd.Tag] = $true }
            foreach ($ch in $nd.Nodes) { $stack.Push($ch) }
        }

        $tree.BeginUpdate()
        $tree.Nodes.Clear()
        $script:NodeMap = @{}
        $script:GhostNodes = @()

        $root = New-Object System.Windows.Forms.TreeNode $script:DomainName
        $root.Tag = $script:DomainDN
        $root.NodeFont = $fontBold
        $root.ImageIndex = 0; $root.SelectedImageIndex = 0
        $rg = Get-LinkedGpoNames $rootLink $gpoMap
        if ($rg.Count -gt 0) { $root.Text += "  [GPO: " + $rg.Count + "]"; $root.ToolTipText = "GPO liên kết: " + ($rg -join ", ") }
        [void]$tree.Nodes.Add($root)
        $script:NodeMap[$script:DomainDN.ToLower()] = $root

        foreach ($o in $ous) {
            $pdn = ($o.DN -split '(?<!\\),', 2)[1]
            $pn = $root
            if ($pdn -and $script:NodeMap.ContainsKey($pdn.ToLower())) { $pn = $script:NodeMap[$pdn.ToLower()] }
            $node = New-Object System.Windows.Forms.TreeNode $o.Name
            $node.Tag = $o.DN
            $node.ImageIndex = 1; $node.SelectedImageIndex = 1
            $gl = Get-LinkedGpoNames $o.GpLink $gpoMap
            if ($gl.Count -gt 0) { $node.Text += "  [GPO: " + $gl.Count + "]" }
            if ($o.GpoOptions -band 1) { $node.Text += "  [Chặn KT]" }
            $tip = "Đường dẫn: " + $o.DN
            if ($o.Desc) { $tip += "`r`nMô tả: " + $o.Desc }
            if ($o.GpoOptions -band 1) { $tip += "`r`nKế thừa: Đang BẬT Block Inheritance" }
            if ($gl.Count -gt 0) { $tip += "`r`nGPO liên kết: " + ($gl -join ", ") }
            $node.ToolTipText = $tip
            if ($script:NewDN.ContainsKey($o.DN.ToLower())) {
                $node.ForeColor = Get-ThemeColor "DarkOrange"
                $node.NodeFont  = $fontBold
                $node.ImageIndex = 3; $node.SelectedImageIndex = 3
                $node.Text += "  (mới phát hiện)"
            }
            [void]$pn.Nodes.Add($node)
            $script:NodeMap[$o.DN.ToLower()] = $node
        }
        # --- Group / User trên sơ đồ (nhóm User vào đúng Group chứa nó) ---
        if ($chkShowObj.Checked) {
            $allUsersByDN  = if ($script:LastAllUsersByDN)  { $script:LastAllUsersByDN }  else { @{} }
            $allGroupsByDN = if ($script:LastAllGroupsByDN) { $script:LastAllGroupsByDN } else { @{} }
            $placedInOu = @{}

            $newUserNode = {
                param($uObj, $contextOuDn)
                $lbl = $uObj.Name
                if ($uObj.Sam) { $lbl += "  (" + $uObj.Sam + ")" }
                if (-not $uObj.Enabled) { $lbl += "  [tắt]" }
                $un = New-Object System.Windows.Forms.TreeNode $lbl
                $un.ImageIndex = 5; $un.SelectedImageIndex = 5
                $uTip = "User: " + $uObj.Name + "`r`nTên đăng nhập: " + $uObj.Sam + "`r`nTrạng thái: " + $(if ($uObj.Enabled) { "đang bật" } else { "đang tắt" })
                $uPdn = ($uObj.DN -split '(?<!\\)(?:\\\\)*,', 2)[1]
                if ($uPdn -and $contextOuDn -and ($uPdn -ine $contextOuDn)) {
                    $uOuLbl = if ($ouKeys.ContainsKey($uPdn.ToLower())) { $ouKeys[$uPdn.ToLower()] } else { $uPdn }
                    $uTip += "`r`nOU chứa user: " + $uOuLbl
                }
                if ($uObj.Desc) { $uTip += "`r`nMô tả: " + $uObj.Desc }
                if (-not $uObj.Enabled) { $un.ForeColor = Get-ThemeColor "Gray" }
                $un.Tag = "US:" + $uObj.DN
                $un.ToolTipText = $uTip
                if ($script:NewObj.ContainsKey($uObj.DN.ToLower())) {
                    $un.ForeColor = Get-ThemeColor "DarkOrange"
                    $un.NodeFont  = $fontBold
                    $un.Text += "  (mới phát hiện)"
                }
                return $un
            }

            foreach ($o in @($objs | Where-Object { $_.Kind -eq 'GR' } | Sort-Object Name)) {
                $pk = ([string]$o.ParentDN).ToLower()
                if (-not $script:NodeMap.ContainsKey($pk)) { continue }
                $pn = $script:NodeMap[$pk]
                $node = New-Object System.Windows.Forms.TreeNode ($o.Name + "  [" + $o.Members + " thành viên]")
                $node.ImageIndex = 4; $node.SelectedImageIndex = 4
                $tip = "Group: " + $o.Name + "`r`nLoại: " + $o.Cat + " / " + $o.Scope + "`r`nSố thành viên: " + $o.Members
                if ($o.Desc) { $tip += "`r`nMô tả: " + $o.Desc }
                $node.Tag = "GR:" + $o.DN
                $node.ToolTipText = $tip
                if ($script:NewObj.ContainsKey($o.DN.ToLower())) {
                    $node.ForeColor = Get-ThemeColor "DarkOrange"
                    $node.NodeFont  = $fontBold
                    $node.Text += "  (mới phát hiện)"
                }
                [void]$pn.Nodes.Add($node)
                $script:NodeMap[("gr:" + $o.DN).ToLower()] = $node

                $memUsers = @(); $memSubGroups = @()
                foreach ($mDn in @($o.MemberDNs)) {
                    $ml = ([string]$mDn).ToLower()
                    if ($allUsersByDN.ContainsKey($ml)) { $memUsers += $allUsersByDN[$ml] }
                    elseif ($allGroupsByDN.ContainsKey($ml)) { $memSubGroups += $allGroupsByDN[$ml] }
                }
                foreach ($mu in @($memUsers | Sort-Object Name)) {
                    $uNode = & $newUserNode $mu $o.ParentDN
                    [void]$node.Nodes.Add($uNode)
                    $placedInOu[($pk + "|" + $mu.DN.ToLower())] = $true
                }
                foreach ($mg in @($memSubGroups | Sort-Object Name)) {
                    $gnNode = New-Object System.Windows.Forms.TreeNode ("↳ " + $mg.Name + "  [nhóm]")
                    $gnNode.ImageIndex = 4; $gnNode.SelectedImageIndex = 4
                    $gnNode.Tag = "GR:" + $mg.DN
                    $gnNode.ToolTipText = "Group con: " + $mg.Name + " (" + $mg.Members + " thành viên)"
                    [void]$node.Nodes.Add($gnNode)
                }
            }

            foreach ($o in @($objs | Where-Object { $_.Kind -eq 'US' } | Sort-Object Name)) {
                $pk = ([string]$o.ParentDN).ToLower()
                if (-not $script:NodeMap.ContainsKey($pk)) { continue }
                if ($placedInOu.ContainsKey(($pk + "|" + $o.DN.ToLower()))) { continue }
                $pn = $script:NodeMap[$pk]
                $uNode = & $newUserNode $o $o.ParentDN
                [void]$pn.Nodes.Add($uNode)
            }
        }
        $tree.ExpandAll()
        foreach ($k in $collapsed.Keys) {
            if ($script:NodeMap.ContainsKey($k.ToLower())) { $script:NodeMap[$k.ToLower()].Collapse() }
        }
        $tree.EndUpdate()
        $grCnt = @($objs | Where-Object { $_.Kind -eq 'GR' }).Count
        $usCnt = @($objs | Where-Object { $_.Kind -eq 'US' }).Count
        $lblCount.Text = "$($ous.Count) OU, $grCnt group, $usCnt user"

        Set-TreeSelectionFromCombo
        $script:Sync = $false
        Update-Ghosts
        Update-NameCheck
        Update-GrpCheck
        Update-UsrCheck
        $script:LastOURefresh = Get-Date
        if ($Force -or $firstLoad) { Write-Log ("Đã tải sơ đồ (" + $ous.Count + " OU).") "Black" }
    }
    catch {
        $script:Sync = $false
        try { $tree.EndUpdate() } catch {}
        Write-Log ("[LỖI] Không tải được danh sách OU: " + $_.Exception.Message) "Red"
    }
    finally { $script:Refreshing = $false }
}

function Test-OUName {
    param([string]$n)
    if ([string]::IsNullOrWhiteSpace($n)) { return "Bạn chưa nhập tên OU." }
    if ($n -ne $n.Trim())                 { return "Tên OU không được bắt đầu hoặc kết thúc bằng dấu cách." }
    if ($n -match '[,\+"\\<>;=/#]')       { return 'Tên OU không được chứa các ký tự:  , + " \ < > ; = / #' }
    if ($n.Length -gt 64)                 { return "Tên OU quá dài (tối đa 64 ký tự)." }
    return $null
}

function New-OneOU {
    param([string]$Name, [string]$Path, [string]$Desc, [hashtable]$DryPlanned = $null)
    $script:LastCreateErr = ""

    $err = Test-OUName $Name
    if ($err) { $script:LastCreateErr = "'$Name': $err"; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }

    $pathExists = ($null -ne $DryPlanned -and $chkDry.Checked -and $DryPlanned.ContainsKey($Path.ToLower()))
    if (-not $pathExists) {
        try {
            $pObj = Get-ADObject -Identity $Path -ErrorAction Stop
            if ($pObj.ObjectClass -notin @('domainDNS', 'organizationalUnit')) {
                $script:LastCreateErr = "Không thể tạo OU bên trong đối tượng loại '$($pObj.ObjectClass)': $Path"
                Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail"
            }
        }
        catch { $script:LastCreateErr = "Không tìm thấy nơi chứa: $Path"; Write-Log "[LỖI] $($script:LastCreateErr)" "Red"; return "fail" }
    }

    $dn = "OU=$Name,$Path"
    if ($chkDry.Checked -and $null -ne $DryPlanned -and $DryPlanned.ContainsKey($dn.ToLower())) {
        Write-Log "[BỎ QUA] Trùng trong danh sách sẽ tạo: $dn" "DarkOrange"; return "skip"
    }
    $exists = $null
    try { $exists = Get-ADOrganizationalUnit -Identity $dn -ErrorAction Stop } catch {}
    if ($exists) { Write-Log "[BỎ QUA] Đã có sẵn: $dn" "DarkOrange"; return "skip" }

    if ($chkDry.Checked) {
        if ($null -ne $DryPlanned) { $DryPlanned[$dn.ToLower()] = $true }
        Write-Log "[CHẠY THỬ] Sẽ tạo OU: $dn" "Blue"; return "dry"
    }

    try {
        $p = @{ Name = $Name; Path = $Path; ProtectedFromAccidentalDeletion = $chkProtect.Checked; PassThru = $true; ErrorAction = 'Stop' }
        if (-not [string]::IsNullOrWhiteSpace($Desc)) { $p.Description = $Desc }
        $ou = New-ADOrganizationalUnit @p
        $script:Created[$ou.DistinguishedName.ToLower()] = $true
        Write-Log "[OK] Đã tạo OU: $($ou.DistinguishedName)" "Green"
        return "ok"
    }
    catch {
        $script:LastCreateErr = $dn + " : " + $_.Exception.Message
        Write-Log ("[LỖI] " + $script:LastCreateErr) "Red"
        return "fail"
    }
}

function Set-Pol {
    param($GpoName, $Key, $ValueName, $Type, $Value)
    Set-GPRegistryValue -Name $GpoName -Key $Key -ValueName $ValueName -Type $Type -Value $Value -ErrorAction Stop | Out-Null
}

function Set-GpoScopeFilter {
    param([string]$GpoName, [string]$ScopeType, [string]$TargetPrincipal, [string]$Server = "")
    if ($ScopeType -notin @('Group', 'User') -or -not $TargetPrincipal) { return }
    # Cấp GpoApply cho Group/User TRƯỚC, rồi mới hạ Authenticated Users xuống GpoRead (MS16-072) để tránh GPO bị khóa quyền nửa chừng nếu tên sai
    $authName = try {
        (New-Object System.Security.Principal.SecurityIdentifier 'S-1-5-11').Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
    } catch { 'Authenticated Users' }
    if ($TargetPrincipal -ieq $authName -or $TargetPrincipal -ieq 'Authenticated Users' -or $TargetPrincipal -ieq 'S-1-5-11') {
        throw "Không chọn '$TargetPrincipal' làm bộ lọc riêng (đây là nhóm mặc định). Hãy chọn 'Toàn bộ OU'."
    }
    $pApply = @{ Name = $GpoName; TargetName = $TargetPrincipal; TargetType = $ScopeType; PermissionLevel = 'GpoApply'; Confirm = $false; ErrorAction = 'Stop' }
    $pAuth  = @{ Name = $GpoName; TargetName = $authName; TargetType = 'Group'; PermissionLevel = 'GpoRead'; Replace = $true; Confirm = $false; ErrorAction = 'Stop' }
    if ($Server) { $pApply.Server = $Server; $pAuth.Server = $Server }
    Set-GPPermission @pApply | Out-Null
    Set-GPPermission @pAuth  | Out-Null
}

function New-ShareLogonScriptGpo {
    param(
        [string]$ServerName,
        [string]$ShareName,
        [string]$TargetType,
        [string]$TargetOU = "",
        [string]$TargetPrincipal = "",
        [string]$DriveLetter = "*",
        [string]$GpoName = ""
    )
    $pdc = (Get-ADDomain -ErrorAction Stop).PDCEmulator
    $dom = $script:DomainName
    $hostName = if ($ServerName -and $ServerName -notin @('.', 'localhost', '127.0.0.1', '::1')) { $ServerName.Trim() } else { $env:COMPUTERNAME }
    $uncPath = "\\$hostName\$ShareName"
    $safeShare = ($ShareName -replace '[^\w\-]', '_')
    if (-not $safeShare) { $safeShare = 'Share' }
    if ([string]::IsNullOrWhiteSpace($GpoName)) {
        $GpoName = "VN-MapShare-" + ($ShareName -replace '[\\/:*?"<>|]', '-')
    }

    $linkTarget = $script:DomainDN
    $scopeKind  = 'OU'
    $scopeSam   = ''
    $tagSuffix  = 'Everyone'
    $scopeDesc  = 'Everyone (mọi người dùng trong domain đều thấy)'

    switch ($TargetType) {
        'Everyone' {
            $linkTarget = $script:DomainDN
            $scopeKind  = 'OU'
            $scopeSam   = ''
            $tagSuffix  = 'Everyone'
            $scopeDesc  = 'Everyone (mọi người dùng trong domain đều thấy)'
        }
        'OU' {
            if (-not $TargetOU) { throw "Chưa chỉ định OU cho script SYSVOL." }
            $linkTarget = $TargetOU
            $scopeKind  = 'OU'
            $scopeSam   = ''
            $ouShort = (($TargetOU -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)OU=', '' -replace '[^\w\-]', '_')
            if (-not $ouShort) { $ouShort = 'OU' }
            $tagSuffix = "OU_$ouShort"
            $scopeDesc = "Chỉ người dùng trong OU: $TargetOU"
        }
        'Group' {
            $lookup = ([string]$TargetPrincipal).Trim()
            if ($lookup -match '^[^\\]+\\(.+)$') { $lookup = $Matches[1] }
            elseif ($lookup -match '^([^@]+)@') { $lookup = $Matches[1] }
            $esc = $lookup -replace "'", "''"
            $hits = @(Get-ADGroup -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -Properties member -ErrorAction Stop)
            if ($hits.Count -eq 0) { throw "Không tìm thấy Security Group '$TargetPrincipal' trong AD để gán script SYSVOL." }
            if ($hits.Count -gt 1) { throw "Có $($hits.Count) Group trùng tên '$TargetPrincipal'. Hãy nhập chính xác SamAccountName." }
            $gObj = $hits[0]
            if ($gObj.GroupCategory -ne 'Security') { throw "Group '$($gObj.Name)' là Distribution Group, không dùng lọc GPO được. Hãy chọn Security Group." }
            $scopeKind = 'Group'
            $scopeSam  = $gObj.SamAccountName
            $tagSuffix = ($scopeSam -replace '[^\w\-]', '_')
            $gParent   = ($gObj.DistinguishedName -split '(?<!\\)(?:\\\\)*,', 2)[1]
            $memDns    = @($gObj.member | Where-Object { $_ } | ForEach-Object { [string]$_ })
            $allInParent = ($gParent -match '^(?i)OU=')
            if ($allInParent -and $memDns.Count -gt 0) {
                $suf = "," + $gParent
                foreach ($mDn in $memDns) {
                    if (-not $mDn.EndsWith($suf, [System.StringComparison]::OrdinalIgnoreCase)) { $allInParent = $false; break }
                }
            }
            $linkTarget = if ($allInParent) { $gParent } else { $script:DomainDN }
            $scopeDesc  = "Chỉ Group '$scopeSam' (người ngoài group không thấy)"
        }
        'User' {
            $lookup = ([string]$TargetPrincipal).Trim()
            if ($lookup -match '^[^\\]+\\(.+)$') { $lookup = $Matches[1] }
            elseif ($lookup -match '^([^@]+)@') { $lookup = $Matches[1] }
            $esc = $lookup -replace "'", "''"
            $hits = @(Get-ADUser -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction Stop)
            if ($hits.Count -eq 0) { throw "Không tìm thấy User '$TargetPrincipal' trong AD để gán script SYSVOL." }
            if ($hits.Count -gt 1) { throw "Có $($hits.Count) User trùng tên '$TargetPrincipal'. Hãy nhập chính xác SamAccountName." }
            $uObj = $hits[0]
            $scopeKind = 'User'
            $scopeSam  = $uObj.SamAccountName
            $tagSuffix = ($scopeSam -replace '[^\w\-]', '_')
            $uParent   = ($uObj.DistinguishedName -split '(?<!\\)(?:\\\\)*,', 2)[1]
            $linkTarget = if ($uParent -match '^(?i)OU=') { $uParent } else { $script:DomainDN }
            $scopeDesc  = "Chỉ User '$scopeSam' (người khác không thấy)"
        }
        default {
            throw "Loại đối tượng không hợp lệ cho script SYSVOL: $TargetType"
        }
    }

    if (-not $tagSuffix) { $tagSuffix = 'Target' }
    $batName = "MapShare_${safeShare}_${tagSuffix}.bat"
    $uncBat  = $uncPath -replace '%', '%%'
    $drvNorm = ([string]$DriveLetter).Trim()
    if ($drvNorm -match '^([A-Za-z]):?$') {
        $dl = $Matches[1].ToUpper() + ':'
        $batLines = @(
            '@echo off',
            'chcp 65001 >nul',
            "net use $dl /delete /y >nul 2>&1",
            "net use $dl `"$uncBat`" /persistent:yes"
        )
    }
    else {
        $batLines = @(
            '@echo off',
            'chcp 65001 >nul',
            "net use | find /i `"$uncBat`" >nul && exit /b 0",
            "net use * `"$uncBat`" /persistent:yes"
        )
    }
    $batBody = ($batLines -join "`r`n") + "`r`n"
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)

    $sysvolScriptsDir = "\\$pdc\SYSVOL\$dom\scripts"
    if (-not (Test-Path -LiteralPath $sysvolScriptsDir)) {
        New-Item -ItemType Directory -Path $sysvolScriptsDir -Force -ErrorAction Stop | Out-Null
    }
    $sysvolBat = Join-Path $sysvolScriptsDir $batName
    [System.IO.File]::WriteAllText($sysvolBat, $batBody, $utf8NoBom)

    $isNew = $false
    $gpo = Get-GPO -Name $GpoName -Server $pdc -ErrorAction SilentlyContinue
    if (-not $gpo) {
        $gpo = New-GPO -Name $GpoName -Comment ("Jebtool: ánh xạ Share $uncPath ($scopeDesc)") -Server $pdc -ErrorAction Stop
        $isNew = $true
    }
    try {
        $guid = '{' + $gpo.Id.ToString().ToUpper() + '}'
        Set-GPRegistryValue -Name $GpoName -Server $pdc -Key 'HKCU\Software\Policies\Microsoft\Jebtool\ShareScripts' -ValueName $safeShare -Type String -Value $uncPath -ErrorAction Stop | Out-Null

        $gpt       = "\\$pdc\SYSVOL\$dom\Policies\$guid"
        $logonDir  = "$gpt\User\Scripts\Logon"
        $logoffDir = "$gpt\User\Scripts\Logoff"
        New-Item -ItemType Directory -Path $logonDir  -Force -ErrorAction Stop | Out-Null
        New-Item -ItemType Directory -Path $logoffDir -Force -ErrorAction Stop | Out-Null

        $gpoBat = Join-Path $logonDir $batName
        [System.IO.File]::WriteAllText($gpoBat, $batBody, $utf8NoBom)

        $ini = "`r`n[Logon]`r`n0CmdLine=$batName`r`n0Parameters=`r`n"
        Set-Content -Path ("$gpt\User\Scripts\scripts.ini") -Value $ini -Encoding Unicode -ErrorAction Stop

        $dn  = "CN=$guid,CN=Policies,CN=System," + $script:DomainDN
        $obj = Get-ADObject -Identity $dn -Server $pdc -Properties gPCUserExtensionNames, versionNumber -ErrorAction Stop
        $ext = Add-GpoMachineExt $obj.gPCUserExtensionNames '{42B5FAAE-6536-11D2-AE5A-0000F87571E3}' '{40B66650-4972-11D1-A7CA-0000F87571E3}'
        $ver = [int]$obj.versionNumber + 65536
        Set-ADObject -Identity $dn -Server $pdc -Replace @{ gPCUserExtensionNames = $ext; versionNumber = $ver } -ErrorAction Stop
        $gptIni = "$gpt\GPT.INI"
        if (Test-Path -LiteralPath $gptIni) {
            $txt = [System.IO.File]::ReadAllText($gptIni, [System.Text.Encoding]::Default)
            if ($txt -match '(?im)^Version=\d+') { $txt = [regex]::Replace($txt, '(?im)^Version=\d+', ('Version=' + $ver)) }
            else { $txt = $txt.TrimEnd() + "`r`nVersion=" + $ver + "`r`n" }
            [System.IO.File]::WriteAllText($gptIni, $txt, [System.Text.Encoding]::Default)
        }

        if ($scopeKind -in @('Group', 'User')) {
            Set-GpoScopeFilter -GpoName $GpoName -ScopeType $scopeKind -TargetPrincipal $scopeSam -Server $pdc
        }
        elseif ($TargetType -eq 'Everyone' -and -not $isNew) {
            $authName = try {
                (New-Object System.Security.Principal.SecurityIdentifier 'S-1-5-11').Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
            } catch { 'Authenticated Users' }
            Set-GPPermission -Name $GpoName -Server $pdc -TargetName $authName -TargetType Group -PermissionLevel GpoApply -Replace -Confirm:$false -ErrorAction Stop | Out-Null
        }

        $linked = $false
        try {
            $inh = Get-GPInheritance -Target $linkTarget -Server $pdc -ErrorAction Stop
            if (@($inh.GpoLinks | Where-Object { $_.GpoId -eq $gpo.Id }).Count -gt 0) { $linked = $true }
        } catch {}
        if (-not $linked) {
            New-GPLink -Name $GpoName -Target $linkTarget -LinkEnabled Yes -Server $pdc -ErrorAction Stop | Out-Null
        }

        return @{
            GpoName          = $GpoName
            BatName          = $batName
            SysvolScriptPath = $sysvolBat
            GpoScriptPath    = $gpoBat
            LinkTarget       = $linkTarget
            ScopeDesc        = $scopeDesc
        }
    }
    catch {
        if ($isNew -and $GpoName) {
            try { Remove-GPO -Name $GpoName -Server $pdc -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        }
        throw
    }
}

# ---------------------------------------------------------------
#  Thư viện 50 GPO
# ---------------------------------------------------------------
$script:KUSys = 'HKCU\Software\Microsoft\Windows\CurrentVersion\Policies\System'
$script:KUExp = 'HKCU\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer'
$script:KMSys = 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
$script:KFW   = 'HKLM\SOFTWARE\Policies\Microsoft\WindowsFirewall'
$script:KWU   = 'HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
$script:KDef  = 'HKLM\SOFTWARE\Policies\Microsoft\Windows Defender'
$script:KOff  = 'HKCU\Software\Policies\Microsoft\Office\16.0'
$script:KCP   = 'HKCU\Software\Policies\Microsoft\Windows\Control Panel\Desktop'

function New-PV {
    param($Key, $Name, $Type, $Value)
    if ($Type -eq 'DWord') { $Value = [int]$Value } else { $Value = [string]$Value }
    return @{ Key = $Key; Name = $Name; Type = $Type; Value = $Value }
}

function Get-GpoCatalog {
    $c = @()
    $catA = 'A. Password & Logon — Mật khẩu & Đăng nhập'
    $catB = 'B. System Security — Bảo mật hệ thống'
    $catC = 'C. User Restrictions — Hạn chế người dùng'
    $catD = 'D. Desktop & UI — Giao diện đồng bộ'
    $catE = 'E. Network & Folders — Mạng & Thư mục'
    $catF = 'F. Updates & Software — Cập nhật & Phần mềm'
    $catG = 'G. Operations & Audit — Vận hành & Nhật ký'

    # ---- A. Mật khẩu và đăng nhập ----
    $c += @{ Id=1; Cat=$catA; Kind='Domain'; Scope='D'; Short='Pwd-Length'
        NameEn='Minimum Password Length & Complexity'
        Name='Mật khẩu tối thiểu N ký tự, bắt buộc độ phức tạp'
        Desc='Đổi chính sách mật khẩu MẶC ĐỊNH của cả domain (không phải GPO gắn OU). Ảnh hưởng mọi tài khoản.'
        Params=@(@{Id='len'; Label='Độ dài tối thiểu'; Default='12'; Num=$true; Min=1; Max=14}) }
    $c += @{ Id=2; Cat=$catA; Kind='Domain'; Scope='D'; Short='Lockout'
        NameEn='Account Lockout Threshold & Duration'
        Name='Khóa tài khoản sau N lần sai, tự mở sau M phút'
        Desc='Đổi chính sách khóa tài khoản MẶC ĐỊNH của cả domain.'
        Params=@(@{Id='thr'; Label='Số lần nhập sai'; Default='5'; Num=$true; Min=1; Max=999}, @{Id='mins'; Label='Số phút khóa'; Default='15'; Num=$true; Min=1; Max=99999}) }
    $c += @{ Id=3; Cat=$catA; Kind='Domain'; Scope='D'; Short='Pwd-Age'
        NameEn='Maximum Password Age & Password History'
        Name='Mật khẩu hết hạn sau N ngày, nhớ M mật khẩu cũ'
        Desc='Đổi chính sách thời hạn mật khẩu MẶC ĐỊNH của cả domain.'
        Params=@(@{Id='days'; Label='Số ngày hết hạn'; Default='90'; Num=$true; Min=1; Max=999}, @{Id='hist'; Label='Số mật khẩu cũ được nhớ'; Default='24'; Num=$true; Min=0; Max=24}) }
    $c += @{ Id=4; Cat=$catA; Kind='Gpo'; Scope='U'; Short='ScreenLock'
        NameEn='Screen Saver Timeout & Password Lock'
        Name='Tự khóa màn hình sau N phút'
        Params=@(@{Id='min'; Label='Số phút'; Default='10'; Num=$true; Min=1; Max=999})
        Build={ param($P)
            New-PV $script:KCP 'ScreenSaveActive' 'String' '1'
            New-PV $script:KCP 'ScreenSaverIsSecure' 'String' '1'
            New-PV $script:KCP 'SCRNSAVE.EXE' 'String' 'scrnsave.scr'
            New-PV $script:KCP 'ScreenSaveTimeOut' 'String' ([int]$P.min * 60) } }
    $c += @{ Id=5; Cat=$catA; Kind='Gpo'; Scope='M'; Short='Require-CAD'
        NameEn='Interactive Logon: Require Ctrl+Alt+Del'
        Name='Bắt buộc nhấn Ctrl+Alt+Del để đăng nhập'
        Build={ param($P) New-PV $script:KMSys 'DisableCAD' 'DWord' 0 } }
    $c += @{ Id=6; Cat=$catA; Kind='Gpo'; Scope='M'; Short='Hide-LastUser'
        NameEn='Interactive Logon: Do Not Display Last User'
        Name='Ẩn tên người dùng đăng nhập gần nhất'
        Build={ param($P) New-PV $script:KMSys 'DontDisplayLastUserName' 'DWord' 1 } }
    $c += @{ Id=7; Cat=$catA; Kind='Gpo'; Scope='M'; Short='Logon-Banner'
        NameEn='Interactive Logon: Legal Notice Banner'
        Name='Hiện thông báo chính sách công ty trước khi đăng nhập'
        Params=@(@{Id='title'; Label='Tiêu đề'; Default='Thông báo'}, @{Id='text'; Label='Nội dung'; Default='Hệ thống chỉ dành cho người được phép. Mọi hoạt động có thể bị giám sát.'})
        Build={ param($P)
            New-PV $script:KMSys 'legalnoticecaption' 'String' $P.title
            New-PV $script:KMSys 'legalnoticetext' 'String' $P.text } }
    $c += @{ Id=8; Cat=$catA; Kind='Manual'; Scope='M'; Short='Admin-Guest'
        NameEn='Rename Local Administrator & Disable Guest'
        Name='Đổi tên Administrator cục bộ, tắt tài khoản Guest'
        Hint='GPMC > Computer Configuration > Windows Settings > Security Settings > Local Policies > Security Options: "Accounts: Rename administrator account" và "Accounts: Guest account status".' }

    # ---- B. Bảo mật hệ thống ----
    $c += @{ Id=9; Cat=$catB; Kind='Gpo'; Scope='M'; Short='Firewall-On'
        NameEn='Windows Firewall: Enable All Profiles'
        Name='Bật Windows Firewall cho mọi profile'
        Build={ param($P) foreach ($pf in 'DomainProfile','PrivateProfile','PublicProfile') { New-PV ($script:KFW + '\' + $pf) 'EnableFirewall' 'DWord' 1 } } }
    $c += @{ Id=10; Cat=$catB; Kind='Gpo'; Scope='M'; Short='Firewall-Log'
        NameEn='Windows Firewall: Log Dropped Packets'
        Name='Ghi log các kết nối bị tường lửa chặn'
        Build={ param($P) foreach ($pf in 'DomainProfile','PrivateProfile','PublicProfile') {
            $k = $script:KFW + '\' + $pf + '\Logging'
            New-PV $k 'LogDroppedPackets' 'DWord' 1
            New-PV $k 'LogFileSize' 'DWord' 16384
            New-PV $k 'LogFilePath' 'String' '%SystemRoot%\System32\LogFiles\Firewall\pfirewall.log' } } }
    $c += @{ Id=11; Cat=$catB; Kind='Gpo'; Scope='M'; Short='BitLocker-OS'
        NameEn='BitLocker Drive Encryption (OS, XTS-AES 256, AD Backup)'
        Name='Cấu hình BitLocker ổ hệ điều hành (XTS-AES 256, lưu khóa vào AD)'
        Desc='Chỉ CẤU HÌNH chính sách BitLocker; việc bật mã hóa trên từng máy vẫn cần thực hiện (thủ công hoặc MBAM/Intune).'
        Build={ param($P)
            $k = 'HKLM\SOFTWARE\Policies\Microsoft\FVE'
            New-PV $k 'EncryptionMethodWithXtsOs' 'DWord' 7
            New-PV $k 'UseAdvancedStartup' 'DWord' 1
            New-PV $k 'UseTPM' 'DWord' 2
            New-PV $k 'OSRecovery' 'DWord' 1
            New-PV $k 'OSRecoveryPassword' 'DWord' 2
            New-PV $k 'OSRecoveryKey' 'DWord' 2
            New-PV $k 'OSActiveDirectoryBackup' 'DWord' 1
