    $c += @{ Id=16; Cat=$catB; Kind='Gpo'; Scope='M'; Short='Defender-ASR'
        NameEn='Microsoft Defender Real-Time & ASR Rules'
        Name='Bật Defender thời gian thực và các luật ASR cơ bản'
        Desc='Chế độ ASR: 1 = Chặn, 2 = Chỉ ghi nhận (khuyên dùng 2 trước để xem có chặn nhầm phần mềm không).'
        Params=@(@{Id='mode'; Label='Chế độ ASR (1=Chặn, 2=Ghi nhận)'; Default='2'; Num=$true; Min=1; Max=2})
        Build={ param($P)
            $m = if ($P.mode) { $P.mode } else { '2' }
            New-PV ($script:KDef + '\Real-Time Protection') 'DisableRealtimeMonitoring' 'DWord' 0
            $asr = $script:KDef + '\Windows Defender Exploit Guard\ASR'
            New-PV $asr 'ExploitGuard_ASR_Rules' 'DWord' 1
            foreach ($g in 'BE9BA2D9-53EA-4CDC-84E5-9B1EEEE46550','D4F940AB-401B-4EFC-AADC-AD5F3C50688A','3B576869-A4EC-4529-8536-B80A7769E899','75668C1F-73B5-4CF0-BB93-3ECF5CB7CC84','5BEB7EFE-FD9A-4556-801D-275E5FFC04CC','D3E037E1-3EB8-44C8-A917-57927947596D','9E6C4E1F-7D60-472F-BA1A-A39EF669E4B2') {
