$script:LibCustomParams = @{}

function Get-LibItemParams {
    param($Item)
    $p = @{}
    if (-not $Item -or -not $Item.Params) { return $p }
    $custom = $script:LibCustomParams[[string]$Item.Id]
    foreach ($pm in $Item.Params) {
        if ($custom -and $custom.ContainsKey($pm.Id) -and $null -ne $custom[$pm.Id]) {
            $p[$pm.Id] = [string]$custom[$pm.Id]
        }
        else {
            $p[$pm.Id] = [string]$pm.Default
        }
    }
    return $p
}

function Format-LibItemSubtitle {
    param($Item)
    if (-not $Item) { return "" }
    if (-not $Item.Params -or $Item.Params.Count -eq 0) { return $Item.Name }
    $p = Get-LibItemParams $Item
    $isCustom = $script:LibCustomParams.ContainsKey([string]$Item.Id)
    switch ([int]$Item.Id) {
        1  { return "Mật khẩu tối thiểu $($p.len) ký tự, bắt buộc độ phức tạp" }
        2  { return "Khóa tài khoản sau $($p.thr) lần sai, tự mở sau $($p.mins) phút" }
        3  { return "Mật khẩu hết hạn sau $($p.days) ngày, nhớ $($p.hist) mật khẩu cũ" }
        4  { return "Tự khóa màn hình sau $($p.min) phút" }
        16 { return "Bật Defender thời gian thực & ASR (chế độ $($p.mode))" }
        41 { return "Windows Update: tự cài lúc $($p.hour)h, không tự khởi động lại" }
        44 { return "Trì hoãn cập nhật tính năng $($p.days) ngày" }
        45 { return "Giới hạn băng thông Delivery Optimization ($($p.pct)%)" }
        46 { return "Power plan: tắt màn hình $($p.disp) phút, ngủ $($p.sleep) phút" }
        50 { return "Tăng Event Log ($($p.mb) MB) và giới hạn telemetry" }
        default {
            if ($isCustom) {
                $vals = ($Item.Params | ForEach-Object { $p[$_.Id] }) -join ', '
                return ($Item.Name + " (" + $vals + ")")
            }
            return $Item.Name
        }
    }
}

function Format-LibItemParamSummary {
    param($Item)
    if (-not $Item -or -not $Item.Params -or $Item.Params.Count -eq 0) { return "" }
    $p = Get-LibItemParams $Item
    $parts = @()
    foreach ($pm in $Item.Params) {
        $parts += ("{0} = {1}" -f $pm.Label, $p[$pm.Id])
    }
    $txt = ($parts -join ', ')
    if ($script:LibCustomParams.ContainsKey([string]$Item.Id)) { $txt += " [Đã tùy chỉnh]" }
    return $txt
}

function Update-LibDescLabel {
    param($Item)
    if ($null -eq $lblLibDesc -or $null -eq $Item) { return }
    $subVi = Format-LibItemSubtitle $Item
    $hdrTxt = "[EN] $($Item.NameEn)  |  [VI] $subVi"
    if ($Item.Kind -eq 'Manual') {
        $lblLibDesc.ForeColor = [System.Drawing.Color]::Firebrick
        $lblLibDesc.Text = $hdrTxt + "`r`nChưa tạo tự động (cần Preferences/Security Settings). Làm thủ công: " + $Item.Hint
    }
    elseif ($Item.Params -and $Item.Params.Count -gt 0) {
        $pSum = Format-LibItemParamSummary $Item
        $extra = if ($Item.Desc) { " — " + $Item.Desc } else { "" }
        $lblLibDesc.ForeColor = if ($script:LibCustomParams.ContainsKey([string]$Item.Id)) { [System.Drawing.Color]::DarkBlue } else { [System.Drawing.Color]::DimGray }
        $lblLibDesc.Text = $hdrTxt + "`r`nTham số: " + $pSum + "  (Chuột phải để sửa)" + $extra
    }
    elseif ($Item.Desc) {
        $lblLibDesc.ForeColor = [System.Drawing.Color]::DimGray
        $lblLibDesc.Text = $hdrTxt + "`r`n" + $Item.Desc
    }
    elseif ($Item.Scope -eq 'M') {
        $lblLibDesc.ForeColor = [System.Drawing.Color]::DimGray
        $lblLibDesc.Text = $hdrTxt + "`r`nThiết lập cho MÁY TÍNH (Computer Configuration): áp dụng cho máy trong OU được liên kết."
    }
    elseif ($Item.Scope -eq 'B') {
        $lblLibDesc.ForeColor = [System.Drawing.Color]::DimGray
        $lblLibDesc.Text = $hdrTxt + "`r`nThiết lập cho CẢ MÁY TÍNH & NGƯỜI DÙNG trong OU được liên kết."
    }
    else {
        $lblLibDesc.ForeColor = [System.Drawing.Color]::DimGray
        $lblLibDesc.Text = $hdrTxt + "`r`nThiết lập cho NGƯỜI DÙNG (User Configuration): áp dụng cho tài khoản trong OU được liên kết."
    }
}

function Update-LibListRow {
    param($ListItem)
    if ($null -eq $ListItem -or $null -eq $ListItem.Tag -or $ListItem.SubItems.Count -lt 4) { return }
    $it = $ListItem.Tag
    $isCustom = $script:LibCustomParams.ContainsKey([string]$it.Id)
    $subVi = Format-LibItemSubtitle $it
    $statusBase = switch ($it.Kind) { 'Gpo' { "Tự động" } 'Domain' { "Domain" } default { "Thủ công" } }
    $ListItem.SubItems[1].Text = $subVi
    $ListItem.SubItems[3].Text = if ($isCustom) { "$statusBase *" } else { $statusBase }
    $tip = ("{0:00}. {1}`r`nPhụ đề: {2}" -f $it.Id, $it.NameEn, $subVi)
    if ($it.Params -and $it.Params.Count -gt 0) {
        $tip += "`r`nTham số: $(Format-LibItemParamSummary $it)`r`n(Chuột phải vào dòng này để tùy chỉnh số / tham số)"
    }
    $ListItem.ToolTipText = $tip
    if ($ListItem.Selected -and (Get-Variable -Name 'lblLibDesc' -ErrorAction SilentlyContinue)) {
        Update-LibDescLabel $it
    }
}

function Show-ParamDialog {
    param($Items, [string]$DialogTitle = '')
    $rows = @()
    foreach ($it in $Items) { if ($it.Params) { foreach ($p in $it.Params) { $rows += @{ Item = $it; P = $p } } } }
    if ($rows.Count -eq 0) { return @{} }

    $nItems = @($Items | Where-Object { $_.Params }).Count
    $h = [Math]::Min(20 + ($rows.Count * 34) + ($nItems * 26), 520)

    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = if ($DialogTitle) { $DialogTitle } else { "Tùy chỉnh tham số (đã có giá trị mặc định, sửa nếu cần)" }
    $dlg.StartPosition = "CenterParent"
    $dlg.FormBorderStyle = "FixedDialog"
    $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
    $dlg.Font = $fontMain
    $dlg.ClientSize = New-Object System.Drawing.Size(660, ($h + 56))

    $pnl = New-Object System.Windows.Forms.Panel
    $pnl.Location = New-Object System.Drawing.Point(0, 0)
    $pnl.Size = New-Object System.Drawing.Size(660, $h)
    $pnl.AutoScroll = $true
    $dlg.Controls.Add($pnl)

    $y = 10; $boxes = @(); $lastId = $null
    foreach ($r in $rows) {
        if ($lastId -ne $r.Item.Id) {
            $l = New-Object System.Windows.Forms.Label
            $l.Text = ("{0:00}. {1} — {2}" -f $r.Item.Id, $r.Item.NameEn, (Format-LibItemSubtitle $r.Item))
            $l.UseMnemonic = $false
            $l.Font = $fontBold
            $l.AutoEllipsis = $true
            $l.Location = New-Object System.Drawing.Point(10, $y)
            $l.Size = New-Object System.Drawing.Size(624, 22)
            $pnl.Controls.Add($l)
            $y += 26; $lastId = $r.Item.Id
        }
        $l2 = New-Object System.Windows.Forms.Label
        $l2.Text = $r.P.Label
        $l2.UseMnemonic = $false
        $l2.AutoEllipsis = $true
        $l2.Location = New-Object System.Drawing.Point(24, ($y + 3))
        $l2.Size = New-Object System.Drawing.Size(268, 22)
        $pnl.Controls.Add($l2)

        $curParams = Get-LibItemParams $r.Item
        $curVal = $curParams[$r.P.Id]

        if ($r.P.Num) {
            $nud = New-Object System.Windows.Forms.NumericUpDown
            $nud.Location = New-Object System.Drawing.Point(298, $y)
            $nud.Size = New-Object System.Drawing.Size(116, 26)
            $minD = if ($null -ne $r.P.Min) { [decimal]$r.P.Min } else { [decimal]0 }
            $maxD = if ($null -ne $r.P.Max) { [decimal]$r.P.Max } else { [decimal]999999 }
            $nud.Minimum = $minD
            $nud.Maximum = $maxD
            $nud.DecimalPlaces = 0
            $nud.ThousandsSeparator = $false
            $valD = $minD
            try { $valD = [decimal][int64]$curVal } catch { $valD = [decimal]$r.P.Default }
            if ($valD -lt $minD) { $valD = $minD }
            if ($valD -gt $maxD) { $valD = $maxD }
            $nud.Value = $valD
            $pnl.Controls.Add($nud)

            $lRng = New-Object System.Windows.Forms.Label
            $lRng.Text = ("(Từ {0} đến {1}, mặc định: {2})" -f $minD, $maxD, $r.P.Default)
            $lRng.Font = $fontSmall
            $lRng.ForeColor = [System.Drawing.Color]::DimGray
            $lRng.UseMnemonic = $false
            $lRng.AutoEllipsis = $true
            $lRng.Location = New-Object System.Drawing.Point(422, ($y + 4))
            $lRng.Size = New-Object System.Drawing.Size(212, 20)
            $pnl.Controls.Add($lRng)

            $boxes += @{ Item = $r.Item; P = $r.P; Box = $nud; IsNum = $true }
        }
        else {
            $tb = New-Object System.Windows.Forms.TextBox
            $tb.Location = New-Object System.Drawing.Point(298, $y)
            $tb.Size = New-Object System.Drawing.Size(336, 26)
            $tb.Text = [string]$curVal
            $pnl.Controls.Add($tb)
            $boxes += @{ Item = $r.Item; P = $r.P; Box = $tb; IsNum = $false }
        }
        $y += 34
    }

    $btnReset = New-Object System.Windows.Forms.Button
    $btnReset.Text = "Đặt lại mặc định"
    $btnReset.UseMnemonic = $false
    $btnReset.Location = New-Object System.Drawing.Point(12, ($h + 10))
    $btnReset.Size = New-Object System.Drawing.Size(136, 34)
    $btnReset.Tag = $boxes
    $btnReset.Add_Click({
        foreach ($bx in @($this.Tag)) {
            if ($bx.IsNum) { $bx.Box.Value = [decimal]$bx.P.Default }
            else { $bx.Box.Text = [string]$bx.P.Default }
        }
    })
    $dlg.Controls.Add($btnReset)

    $btnOk = New-Object System.Windows.Forms.Button
    $btnOk.Text = "OK"; $btnOk.Font = $fontBold; $btnOk.DialogResult = "OK"
    $btnOk.Location = New-Object System.Drawing.Point(460, ($h + 10))
    $btnOk.Size = New-Object System.Drawing.Size(90, 34)
    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = "Hủy"; $btnCancel.DialogResult = "Cancel"
    $btnCancel.Location = New-Object System.Drawing.Point(560, ($h + 10))
    $btnCancel.Size = New-Object System.Drawing.Size(90, 34)
    $dlg.Controls.Add($btnOk); $dlg.Controls.Add($btnCancel)
    $dlg.AcceptButton = $btnOk; $dlg.CancelButton = $btnCancel
    if (Get-Command Set-ModernButtons -ErrorAction SilentlyContinue) { Set-ModernButtons $dlg }

    $dialogOk = ($dlg.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK)
    if (-not $dialogOk) { $dlg.Dispose(); return $null }

    $res = @{}
    foreach ($b in $boxes) {
        $id = [string]$b.Item.Id
        if (-not $res.ContainsKey($id)) { $res[$id] = @{} }
        if ($b.IsNum) {
            $val = [string][int64]$b.Box.Value
        }
        else {
            $val = $b.Box.Text.Trim()
            if ([string]::IsNullOrWhiteSpace($val)) {
                Show-Msg ("Ô '" + $b.P.Label + "' (mục " + $b.Item.Id + ") không được để trống.") "Sai giá trị" "Warning"
                $dlg.Dispose(); return $null
            }
        }
        $res[$id][$b.P.Id] = $val
    }
    $dlg.Dispose()
    return $res
}

function Get-LibGpoName {
    param($Item)
    return ($txtLibPrefix.Text.Trim() + ("{0:00}" -f [int]$Item.Id) + "-" + $Item.Short)
}

function Invoke-GpoItem {
    param([string]$GpoName, $Item, $P, [switch]$SkipMachine)
    foreach ($v in @(& $Item.Build $P)) {
        if ($SkipMachine -and $v.Key -like 'HKLM\*') { continue }
        Set-Pol $GpoName $v.Key $v.Name $v.Type $v.Value
    }
}

function Invoke-DomainItem {
    param($Item, $P)
    $d = $script:DomainName
    switch ([int]$Item.Id) {
        1 { Set-ADDefaultDomainPasswordPolicy -Identity $d -MinPasswordLength ([int]$P.len) -ComplexityEnabled $true -ErrorAction Stop }
        2 { Set-ADDefaultDomainPasswordPolicy -Identity $d -LockoutThreshold ([int]$P.thr) `
                -LockoutDuration (New-TimeSpan -Minutes ([int]$P.mins)) `
                -LockoutObservationWindow (New-TimeSpan -Minutes ([int]$P.mins)) -ErrorAction Stop }
        3 { Set-ADDefaultDomainPasswordPolicy -Identity $d -MaxPasswordAge (New-TimeSpan -Days ([int]$P.days)) `
                -PasswordHistoryCount ([int]$P.hist) -ErrorAction Stop }
    }
}

# ---------------------------------------------------------------
#  Giờ hệ thống
# ---------------------------------------------------------------
$script:IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
$script:IsLocalDC = try {
    $pt = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ProductOptions' -ErrorAction SilentlyContinue).ProductType
    $csLocal = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
    ($pt -eq 'LanmanNT') -or ($null -ne $csLocal -and $csLocal.DomainRole -in 4, 5)
} catch { $false }

function Restart-AsAdmin {
    try {
        $exe = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if ($exe -match '(?i)\\(powershell|pwsh)(_ise)?\.exe$') {
            $targetExe = if ($exe -match '(?i)_ise\.exe$') { $exe -replace '(?i)_ise\.exe$', '.exe' } else { $exe }
            $path = $PSCommandPath
            if (-not $path) { $path = $MyInvocation.MyCommand.Path }
            if (-not $path) { throw "Không xác định được đường dẫn script .ps1 để mở lại." }
            Start-Process -FilePath $targetExe -Verb RunAs -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA', '-WindowStyle', 'Hidden', '-File', ('"' + $path + '"'))
        }
        else {
            Start-Process -FilePath $exe -Verb RunAs
        }
        $form.Close()
    }
    catch { Show-Msg ("Không mở lại được bằng quyền Admin: " + $_.Exception.Message) "Có lỗi" "Warning" }
}

# Chạy lệnh trên máy này, hoặc trên máy khác nếu có nhập tên máy (cần WinRM)
function Invoke-TimeCmd {
    param([scriptblock]$Script, [object[]]$ArgList = @())
    $pc = $txtTimePC.Text.Trim()
    if ($pc) { return Invoke-Command -ComputerName $pc -ScriptBlock $Script -ArgumentList $ArgList -ErrorAction Stop }
    return (& $Script @ArgList)
}

function Update-TimeInfo {
    try {
        $r = Invoke-WithBusy { Invoke-TimeCmd { "{0}|{1}|{2}" -f (Get-Date).ToString('dd/MM/yyyy HH:mm:ss'), [System.TimeZoneInfo]::Local.DisplayName, ((& w32tm /query /source 2>&1) | Out-String).Trim() } } "Đang đọc giờ máy đích..."
        $p = ([string]$r).Split('|', 3)
        $who = $txtTimePC.Text.Trim(); if (-not $who) { $who = "Máy này" }
        $lblTarget.ForeColor = [System.Drawing.Color]::DimGray
        $lblTarget.Text = $who + ":  " + $p[0] + "  |  " + $p[1] + "  |  Nguồn giờ: " + $p[2]
    }
    catch {
        $lblTarget.ForeColor = [System.Drawing.Color]::Firebrick
        $lblTarget.Text = "Không đọc được giờ máy đích: " + $_.Exception.Message
    }
}

function Invoke-TimeAction {
    param([string]$Title, [string]$Plan, [scriptblock]$Script, [object[]]$ArgList = @())
    $pc = $txtTimePC.Text.Trim()
    if ($pc -and $pc -notmatch '^[A-Za-z0-9\.\-_]+$') { Show-Msg "Tên máy không hợp lệ." "Chưa hợp lệ" "Warning"; return }
    $who = if ($pc) { $pc } else { "máy này" }

    $tSwitched = $false
    if ($chkDry.Checked) {
        $tMode = Resolve-DryRunBeforeCreate ($Title + " trên " + $who + ":`r`n" + $Plan)
        if ($tMode -eq "dry") { Write-Log ("[CHẠY THỬ] " + $Title + " trên " + $who + ": " + $Plan) "Blue"; return }
        $tSwitched = ($tMode -eq "switched")
    }

    if (-not $pc -and -not $script:IsAdmin) {
        if (Confirm-Msg "Đổi giờ máy này cần quyền Administrator.`r`n`r`nMở lại tool bằng quyền Admin ngay?") { Restart-AsAdmin }
        return
    }
    if (-not $tSwitched) {
        if (-not (Confirm-Msg ($Title + " trên " + $who + ":`r`n" + $Plan + "`r`n`r`nTiếp tục?"))) { return }
    }

    try {
        $out = Invoke-WithBusy { Invoke-TimeCmd $Script $ArgList } ("Đang thực hiện: " + $Title + "...")
        Write-Log ("[OK] " + $Title + " trên " + $who) "Green"
        foreach ($ln in @(([string]($out | Out-String)) -split "`r?`n")) {
            if ($ln.Trim()) { Write-Log ("      " + $ln.Trim()) "DimGray" }
        }
    }
    catch { Write-Log ("[LỖI] " + $Title + " trên " + $who + ": " + $_.Exception.Message) "Red" }
    Update-TimeInfo
}


# ---------------------------------------------------------------
#  Quota và triển khai tệp (dùng chung)
# ---------------------------------------------------------------
function Invoke-WithBusy {
    param([scriptblock]$Body, [string]$BusyText = "Đang xử lý, vui lòng chờ...")
    $prevStatus = $lblStatus.Text
    $prevCursor = $form.UseWaitCursor
    $prevWorking = $script:Working
    try {
        $script:Working = $true
        $form.UseWaitCursor = $true
        $lblStatus.Text = $BusyText
        $lblStatus.Refresh()
        return (& $Body)
    }
    finally {
        $script:Working = $prevWorking
        $form.UseWaitCursor = $prevCursor
        $lblStatus.Text = $prevStatus
    }
}

function Invoke-OnPC {
    param([string]$PC, [scriptblock]$Script, [object[]]$ArgList = @())
    $PC = ([string]$PC).Trim()
    $isLocal = (-not $PC) -or ($PC -in @('.', 'localhost', '127.0.0.1', '::1', $env:COMPUTERNAME))
    if (-not $isLocal) { return Invoke-Command -ComputerName $PC -ScriptBlock $Script -ArgumentList $ArgList -ErrorAction Stop }
    return (& $Script @ArgList)
}

function Invoke-PCAction {
    param([string]$PC, [string]$Title, [string]$Plan, [scriptblock]$Script, [object[]]$ArgList = @(), [switch]$ReadOnly, [switch]$RequireAdmin, [switch]$Danger, [switch]$SkipConfirm, [switch]$PromptDryRun)
    $PC = $PC.Trim()
    if ($PC -and $PC -notmatch '^[A-Za-z0-9\.\-_]+$') { Show-Msg "Tên máy không hợp lệ." "Chưa hợp lệ" "Warning"; return $false }
    $isLocal = (-not $PC) -or ($PC -in @('.', 'localhost', '127.0.0.1', '::1', $env:COMPUTERNAME))
    $who = if ($isLocal) { "máy này" } else { $PC }

    $switchedFromDry = $false
    if (-not $ReadOnly -and $chkDry.Checked) {
        if ($isLocal -and $script:IsLocalDC -and $Title -match 'Local|Account Lockout') {
            Write-Log ("[CẢNH BÁO - DC] '" + $Title + "' sẽ BỊ CHẶN khi chạy thật vì máy này là Domain Controller (không có Local User/Group). Hãy nhập tên Member Server vào 'Máy chủ'.") "DarkOrange"
            return $false
        }
        if ($PromptDryRun) {
            $dMode = Resolve-DryRunBeforeCreate ($Title + " trên " + $who + ":`r`n" + $Plan)
            if ($dMode -eq "dry") {
                Write-Log ("[CHẠY THỬ] " + $Title + " trên " + $who + ": " + $Plan) "Blue"
                return $false
            }
            $switchedFromDry = ($dMode -eq "switched")
        }
        else {
            Write-Log ("[CHẠY THỬ] " + $Title + " trên " + $who + ": " + $Plan) "Blue"
            return $true
        }
    }
    if ($isLocal -and (-not $ReadOnly -or $RequireAdmin) -and -not $script:IsAdmin) {
        if (Confirm-Msg "Thao tác '$Title' trên máy này cần quyền Administrator.`r`n`r`nMở lại tool bằng quyền Admin ngay?") { Restart-AsAdmin }
        return $false
    }
    if (-not $ReadOnly -and -not $SkipConfirm -and -not $switchedFromDry) {
        $icon = if ($Danger) { "Warning" } else { "Question" }
        if (-not (Confirm-Msg ($Title + " trên " + $who + ":`r`n" + $Plan + "`r`n`r`nTiếp tục?") "Xác nhận" $icon)) { return $false }
    }
    try {
        $out = Invoke-WithBusy { Invoke-OnPC $PC $Script $ArgList } ("Đang thực hiện: " + $Title + "...")
        Write-Log ("[OK] " + $Title + " trên " + $who) "Green"
        foreach ($ln in @(([string]($out | Out-String)) -split "`r?`n")) {
            if ($ln.TrimEnd()) { Write-Log ("      " + $ln.TrimEnd()) "DimGray" }
        }
        return $true
    }
    catch {
        $errTxt = $_.Exception.Message
        Write-Log ("[LỖI] " + $Title + " trên " + $who + ": " + $errTxt) "Red"
        if (-not $ReadOnly) { Show-Msg $errTxt ("Lỗi: " + $Title) "Error" }
        return $false
    }
}

# Khối lệnh đảm bảo có module FSRM (chạy trên máy đích)
$script:FsrmEnsure = {
    if (-not (Get-Module -ListAvailable -Name FileServerResourceManager)) {
        if (Get-Command Install-WindowsFeature -ErrorAction SilentlyContinue) {
            Install-WindowsFeature FS-Resource-Manager -IncludeManagementTools | Out-Null
        }
        else { throw "Máy đích không phải Windows Server hoặc chưa có vai trò File Server Resource Manager (FSRM)." }
    }
    Import-Module FileServerResourceManager -ErrorAction Stop
}

function Get-UnitBytes {
    param([string]$Unit)
    switch ($Unit) { 'MB' { return [int64]1MB } 'GB' { return [int64]1GB } 'TB' { return [int64]1TB } default { return [int64]1GB } }
}

function Get-FileTypeIndex {
    param([string]$Path)
    switch -Regex ([System.IO.Path]::GetExtension($Path).ToLower()) {
        '^\.msi$'              { return 0 }
        '^\.exe$'              { return 1 }
        '^\.(bat|cmd|ps1)$'    { return 2 }
        default                { return 3 }
    }
}

# Thêm 1 cặp CSE vào gPCMachineExtensionNames (gộp Tool GUID nếu cùng CSE, sắp ordinal như GPMC)
function Add-GpoMachineExt {
    param([string]$Current, [string]$Cse, [string]$Tool)
    $map = @{}
    foreach ($m in [regex]::Matches([string]$Current, '\[([^\]]+)\]')) {
        $guids = @([regex]::Matches($m.Groups[1].Value, '\{[0-9A-Fa-f\-]{36}\}') | ForEach-Object { $_.Value.ToUpperInvariant() })
        if ($guids.Count -ge 1) {
            $c = $guids[0]
            if (-not $map.ContainsKey($c)) { $map[$c] = New-Object 'System.Collections.Generic.List[string]' }
            for ($i = 1; $i -lt $guids.Count; $i++) {
                if (-not $map[$c].Contains($guids[$i])) { $map[$c].Add($guids[$i]) }
            }
        }
    }
    $cUp = $Cse.ToUpperInvariant(); $tUp = $Tool.ToUpperInvariant()
    if (-not $map.ContainsKey($cUp)) { $map[$cUp] = New-Object 'System.Collections.Generic.List[string]' }
    if (-not $map[$cUp].Contains($tUp)) { $map[$cUp].Add($tUp) }
    $cseKeys = @($map.Keys | Sort-Object { $_ })
    $out = foreach ($ck in $cseKeys) {
        $tools = $map[$ck].ToArray()
        [array]::Sort($tools, [System.StringComparer]::Ordinal)
        '[' + $ck + ($tools -join '') + ']'
    }
    return ($out -join '')
}

