function Add-NavItem {
    param([string]$Text, [int]$Y, $TargetTab)
    $b = New-Object System.Windows.Forms.Button
    $b.Text        = $Text
    $b.Tag         = 'NavItem'
    $b.UseMnemonic = $false
    $b.FlatStyle   = [System.Windows.Forms.FlatStyle]::Flat
    $b.FlatAppearance.BorderSize = 0
    $b.TextAlign   = [System.Drawing.ContentAlignment]::MiddleLeft
    $b.Padding     = New-Object System.Windows.Forms.Padding(12, 0, 4, 0)
    $b.Cursor      = [System.Windows.Forms.Cursors]::Hand
    $b.TabStop     = $false
    $b.Location    = New-Object System.Drawing.Point(6, $Y)
    $b.Size        = New-Object System.Drawing.Size(153, 34)
    $targetPage = $TargetTab
    $b.Add_Click({ $tabs.SelectedTab = $targetPage }.GetNewClosure())
    $pnlNav.Controls.Add($b)
    $script:NavItems += @{ Tab = $TargetTab; Btn = $b }
}

function Update-NavSelection {
    if (-not $script:NavItems) { return }
    $curTab = $tabs.SelectedTab
    if (-not $curTab -and $tabs.TabPages.Count -gt 0) { $curTab = $tabs.TabPages[0] }
    $script:ActiveNavBtn = $null
    $isStyled = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsStyled)
    $isThemed = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive)
    foreach ($it in $script:NavItems) {
        $b = $it.Btn
        if ($it.Tab -eq $curTab) {
            $script:ActiveNavBtn = $b
            $b.Font = $fontBold
            if (-not $isThemed) {
                if ($isStyled) {
                    $b.BackColor = [System.Drawing.Color]::White
                    $b.ForeColor = [System.Drawing.Color]::FromArgb(15, 23, 42)
                    $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::White
                    $b.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::White
                } else {
                    $b.BackColor = [System.Drawing.Color]::FromArgb(219, 234, 254)
                    $b.ForeColor = [System.Drawing.Color]::FromArgb(29, 78, 216)
                    $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(219, 234, 254)
                    $b.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(191, 219, 254)
                }
            }
        }
        else {
            $b.Font = $fontMain
            if (-not $isThemed) {
                if ($isStyled) {
                    $b.BackColor = [System.Drawing.Color]::White
                    $b.ForeColor = [System.Drawing.Color]::FromArgb(51, 65, 85)
                    $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::White
                    $b.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::White
                } else {
                    $b.BackColor = [System.Drawing.Color]::FromArgb(248, 250, 252)
                    $b.ForeColor = [System.Drawing.Color]::FromArgb(51, 65, 85)
                    $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(226, 232, 240)
                    $b.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(203, 213, 225)
                }
            }
        }
        $b.Invalidate()
    }
    if ($null -ne $script:ThemeEngine) {
        $script:ThemeEngine.ActiveNavButton = $script:ActiveNavBtn
    }
}

