$libGroups = @{}
foreach ($it in (Get-GpoCatalog)) {
    if (-not $libGroups.ContainsKey($it.Cat)) {
        $grp = New-Object System.Windows.Forms.ListViewGroup $it.Cat
        [void]$lvLib.Groups.Add($grp)
        $libGroups[$it.Cat] = $grp
    }
    $li = New-Object System.Windows.Forms.ListViewItem ("{0:00}. {1}" -f $it.Id, $it.NameEn)
    $scopeText = switch ($it.Scope) { 'M' { "Computer" } 'U' { "User" } 'B' { "Comp+User" } 'D' { "Domain" } default { "-" } }
    $statusText = switch ($it.Kind) { 'Gpo' { "Tự động" } 'Domain' { "Domain" } default { "Thủ công" } }
    [void]$li.SubItems.Add("")
    [void]$li.SubItems.Add($scopeText)
    [void]$li.SubItems.Add($statusText)
    $li.Group = $libGroups[$it.Cat]
    $li.Tag = $it
    Update-LibListRow $li
    if ($it.Kind -eq 'Manual') { $li.ForeColor = [System.Drawing.Color]::Gray }
    elseif ($it.Kind -eq 'Domain') { $li.ForeColor = [System.Drawing.Color]::Firebrick }
    [void]$lvLib.Items.Add($li)
}

