$script:FontDiskLegend = New-Object System.Drawing.Font("Segoe UI", 8)
$script:FontDiskBold   = New-Object System.Drawing.Font("Segoe UI", 8, [System.Drawing.FontStyle]::Bold)
$script:FontDiskReg    = New-Object System.Drawing.Font("Segoe UI", 7.75)

$pnlDiskLegend = New-Object System.Windows.Forms.Panel
$pnlDiskLegend.Location  = New-Object System.Drawing.Point(10, 390)
$pnlDiskLegend.Size      = New-Object System.Drawing.Size(608, 22)
$pnlDiskLegend.BackColor = [System.Drawing.Color]::Transparent
$script:ExcludedThemeControls += @($pnlDiskVisual, $pnlDiskLegend)
$pnlDiskLegend.Add_Paint({
    param($sender, $e)
    $isThemed = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive)
    if ($isThemed) {
        $script:ThemeEngine.PaintAlignedLayer($e.Graphics, $sender, $false)
    }
    $items = @(
        @{ Text = "Unallocated"; Color = [System.Drawing.Color]::FromArgb(0, 0, 0) },
        @{ Text = "Primary";     Color = [System.Drawing.Color]::FromArgb(0, 0, 128) },
        @{ Text = "Simple";      Color = [System.Drawing.Color]::FromArgb(128, 128, 0) },
        @{ Text = "Spanned";     Color = [System.Drawing.Color]::FromArgb(128, 0, 128) },
        @{ Text = "Striped";     Color = [System.Drawing.Color]::FromArgb(0, 128, 128) },
        @{ Text = "Mirrored";    Color = [System.Drawing.Color]::FromArgb(128, 0, 0) },
        @{ Text = "RAID-5";      Color = [System.Drawing.Color]::FromArgb(51, 153, 204) }
    )
    $x = 2
    $fnt = $script:FontDiskLegend
    $penColor = if ($isThemed) { [System.Drawing.Color]::FromArgb(148, 163, 184) } else { [System.Drawing.Color]::FromArgb(100, 100, 100) }
    $pen = New-Object System.Drawing.Pen($penColor)
    try {
        foreach ($it in $items) {
            $br = New-Object System.Drawing.SolidBrush($it.Color)
            $e.Graphics.FillRectangle($br, $x, 4, 11, 11)
            $e.Graphics.DrawRectangle($pen, $x, 4, 11, 11)
            $br.Dispose()
            $x += 15
            $sz = [System.Windows.Forms.TextRenderer]::MeasureText($it.Text, $fnt)
            $tFlags = [System.Windows.Forms.TextFormatFlags]::Left -bor [System.Windows.Forms.TextFormatFlags]::Top -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
            $tRect = New-Object System.Drawing.Rectangle($x, 2, ($sz.Width + 6), 18)
            $preset = if ($null -ne $script:ThemeEngine) { [int]$script:ThemeEngine.TextPreset } else { 0 }
            $strongOut = if ($null -ne $script:ThemeEngine) { [bool]$script:ThemeEngine.StrongTextOutline } else { $true }
            $baseFg = if ($isThemed) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(30, 41, 59) }
            [JebtoolTheme.ThemeSurfaceEngine]::DrawModeText($e.Graphics, $it.Text, $fnt, $tRect, $baseFg, $false, $tFlags, $preset, (-not $isThemed), $strongOut)
            $x += $sz.Width + 8
        }
    }
    finally {
        $pen.Dispose()
    }
})
$tabDisk.Controls.Add($pnlDiskLegend)

