function Invoke-TreeSearch {
    $q = $txtTreeSearch.Text.Trim()
    if (-not $q) { return }
    try {
        $hits = New-Object 'System.Collections.Generic.List[System.Windows.Forms.TreeNode]'
        $stack = New-Object System.Collections.Stack
        for ($i = $tree.Nodes.Count - 1; $i -ge 0; $i--) { $stack.Push($tree.Nodes[$i]) }
        while ($stack.Count -gt 0) {
            $nd = $stack.Pop()
            $tagStr = [string]$nd.Tag
            if ($nd.Text.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -or
                ($tagStr -and $tagStr.IndexOf($q, [System.StringComparison]::OrdinalIgnoreCase) -ge 0)) {
                $hits.Add($nd)
            }
            for ($i = $nd.Nodes.Count - 1; $i -ge 0; $i--) { $stack.Push($nd.Nodes[$i]) }
        }
        if ($hits.Count -eq 0) {
            Write-Log "[INFO] Không tìm thấy '$q' trên sơ đồ OU." "DarkOrange"
            return
        }
        $nextIdx = 0
        if ($null -ne $tree.SelectedNode) {
            $curIdx = $hits.IndexOf($tree.SelectedNode)
            if ($curIdx -ge 0) { $nextIdx = ($curIdx + 1) % $hits.Count }
        }
        $pick = $hits[$nextIdx]
        $tree.SelectedNode = $pick
        $pick.EnsureVisible()
        $tree.Focus()
        if ($hits.Count -gt 1) { Write-Log ("[INFO] Tìm thấy '$q' (kết quả $($nextIdx + 1)/$($hits.Count)): $($pick.Text)") "DimGray" }
    }
    catch { Write-Log ("[LỖI] Tìm trên sơ đồ: " + $_.Exception.Message) "Red" }
}
$btnTreeFind.Add_Click({ Invoke-TreeSearch })
$txtTreeSearch.Add_KeyDown({ if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $_.SuppressKeyPress = $true; Invoke-TreeSearch } })

function Invoke-TreeNodeSelection {
    param($Node)
    if ($null -eq $Node -or $script:Sync) { return }
    $t = [string]$Node.Tag
    if (-not $t -or $t -like "G:*") { return }

    if ($t -like "GR:*") {
        $objDn = $t.Substring(3)
        $parentDn = ($objDn -split '(?<!\\)(?:\\\\)*,', 2)[1]
        $meta = if ($script:ObjByDN -and $script:ObjByDN.ContainsKey($objDn.ToLower())) { $script:ObjByDN[$objDn.ToLower()] } else { $null }
        $grpName = if ($meta) { [string]$meta.Name } else { ($objDn -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)CN=', '' -replace '\\([,+="\\<>;# ])', '$1' }
        $grpSam  = if ($meta -and $meta.Sam) { [string]$meta.Sam } else { $grpName }

        Select-OUFromTree $parentDn $false

        if ($tabs.SelectedTab -eq $tabOU -and $subTabs.SelectedTab -eq $pgGrp) {
            $txtGrpName.Text = $grpName
        }
        elseif ($tabs.SelectedTab -eq $tabOU -and $subTabs.SelectedTab -eq $pgUsr) {
            $isCtrl = (([System.Windows.Forms.Control]::ModifierKeys -band [System.Windows.Forms.Keys]::Control) -ne 0)
            if ($isCtrl) {
                $cur = @($txtUsrGroups.Text -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
                $exists = @($cur | Where-Object { $_ -ieq $grpSam }).Count -gt 0
                if ($exists) {
                    $cur = @($cur | Where-Object { $_ -ine $grpSam })
                } else {
                    $cur += $grpSam
                }
                $txtUsrGroups.Text = ($cur -join '; ')
            } else {
                $txtUsrGroups.Text = $grpSam
            }
            Update-UsrCheck
        }
        elseif ($tabs.SelectedTab -eq $tabGPO) {
            $cboGpoScopeType.SelectedIndex = 1
            $txtGpoScopeTarget.Text = $grpSam
        }
        elseif ($tabs.SelectedTab -eq $tabLib) {
            $cboLibScopeType.SelectedIndex = 1
            $txtLibScopeTarget.Text = $grpSam
        }
        elseif ($tabs.SelectedTab -eq $tabQuota -and $subQuotaTabs.SelectedTab -eq $pgQuota) {
            $cboQuotaScopeType.SelectedIndex = 1
            $txtQuotaScopeTarget.Text = $grpSam
        }
        elseif ($tabs.SelectedTab -eq $tabQuota -and $subQuotaTabs.SelectedTab -eq $pgShare) {
            $cboShTargetType.SelectedIndex = 2
            $txtShPrincipal.Text = $grpSam
        }
        elseif ($tabs.SelectedTab -eq $tabDeploy) {
            $rdoDOU.Checked = $true
            $chkDGroup.Checked = $true
            $txtDGroup.Text = $grpSam
        }
        return
    }

    if ($t -like "US:*") {
        $objDn = $t.Substring(3)
        $parentDn = ($objDn -split '(?<!\\)(?:\\\\)*,', 2)[1]
        $meta = if ($script:ObjByDN -and $script:ObjByDN.ContainsKey($objDn.ToLower())) { $script:ObjByDN[$objDn.ToLower()] } else { $null }
        $cn = if ($meta) { [string]$meta.Name } else { ($objDn -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)CN=', '' -replace '\\([,+="\\<>;# ])', '$1' }
        $samParsed = if ($meta -and $meta.Sam) { [string]$meta.Sam } else { "" }
        if (-not $samParsed -and $Node.Text -match '^.+?\s+\(([^)\s]+)\)(?:\s+\[tắt\])?(?:\s+\(mới phát hiện\))?$') {
            $samParsed = $Matches[1]
        }
        $usrSam = if ($samParsed) { $samParsed } else { Get-SamFromName $cn }

        Select-OUFromTree $parentDn $false

        if ($tabs.SelectedTab -eq $tabOU -and $subTabs.SelectedTab -eq $pgUsr) {
            $script:SamSetting = $true
            $txtUsrName.Text = $cn
            $txtUsrSam.Text  = $usrSam
            $script:SamSetting = $false
            $script:SamTouched = $false
            Update-UsrCheck
        }
        elseif ($tabs.SelectedTab -eq $tabGPO) {
            $cboGpoScopeType.SelectedIndex = 2
            $txtGpoScopeTarget.Text = $usrSam
        }
        elseif ($tabs.SelectedTab -eq $tabLib) {
            $cboLibScopeType.SelectedIndex = 2
            $txtLibScopeTarget.Text = $usrSam
        }
        elseif ($tabs.SelectedTab -eq $tabQuota -and $subQuotaTabs.SelectedTab -eq $pgQuota) {
            $cboQuotaScopeType.SelectedIndex = 2
            $txtQuotaScopeTarget.Text = $usrSam
        }
        elseif ($tabs.SelectedTab -eq $tabQuota -and $subQuotaTabs.SelectedTab -eq $pgShare) {
            $cboShTargetType.SelectedIndex = 3
            $txtShPrincipal.Text = $usrSam
        }
        elseif ($tabs.SelectedTab -eq $tabDeploy -and $cboDType.SelectedIndex -eq 4) {
            $rdoDOU.Checked = $true
            $chkDGroup.Checked = $true
            $txtDGroup.Text = $usrSam
        }
        return
    }

    Select-OUFromTree $t $true
}

