$tree.Add_AfterSelect({
    if ($script:Sync) { return }
    $script:TreeHandledBySelect = $true
    Invoke-TreeNodeSelection $_.Node
})

$treeCtx = New-Object System.Windows.Forms.ContextMenuStrip
$tree.ContextMenuStrip = $treeCtx
$tree.Add_NodeMouseClick({
    if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Right -and $_.Node) {
        $tree.SelectedNode = $_.Node
    }
    elseif ($_.Button -eq [System.Windows.Forms.MouseButtons]::Left -and -not $script:TreeHandledBySelect -and $_.Node) {
        $ht = $tree.HitTest($_.Location)
        if ($ht.Location -in @([System.Windows.Forms.TreeViewHitTestLocations]::Label, [System.Windows.Forms.TreeViewHitTestLocations]::Image)) {
            Invoke-TreeNodeSelection $_.Node
        }
    }
})
$treeCtx.Add_Opening({
    param($s, $e)
    $treeCtx.Items.Clear()
    $nd = $tree.SelectedNode
    if (-not $nd -or -not $script:Ready) { $e.Cancel = $true; return }
    $t = [string]$nd.Tag
    if (-not $t -or $t -like "G:*") { $e.Cancel = $true; return }

    if ($t -like "GR:*") {
        $gdn = $t.Substring(3)
        $meta = if ($script:ObjByDN -and $script:ObjByDN.ContainsKey($gdn.ToLower())) { $script:ObjByDN[$gdn.ToLower()] } else { $null }
        $cn = if ($meta) { [string]$meta.Name } else { ($gdn -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)CN=', '' -replace '\\([,+="\\<>;# ])', '$1' }
        $gSam = if ($meta -and $meta.Sam) { [string]$meta.Sam } else { $cn }
        if ($tabs.SelectedTab -eq $tabOU -and $subTabs.SelectedTab -eq $pgUsr) {
            $miAdd = New-Object System.Windows.Forms.ToolStripMenuItem("Thêm '$cn' vào ô Group tạo User")
            $miAdd.Add_Click({
                $cur = @($txtUsrGroups.Text -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
                if (@($cur | Where-Object { $_ -ieq $gSam }).Count -eq 0) { $cur += $gSam }
                $txtUsrGroups.Text = ($cur -join '; ')
                Update-UsrCheck
            }.GetNewClosure())
            [void]$treeCtx.Items.Add($miAdd)
            [void]$treeCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        }
        $mi = New-Object System.Windows.Forms.ToolStripMenuItem("Xóa Group '$cn'")
        $mi.ForeColor = [System.Drawing.Color]::Firebrick
        $mi.Add_Click({ [void](Invoke-DeleteADGroup @($gdn)) }.GetNewClosure())
        [void]$treeCtx.Items.Add($mi)
    }
    elseif ($t -like "US:*") {
        $udn = $t.Substring(3)
        $cn = ($udn -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)CN=', '' -replace '\\([,+="\\<>;# ])', '$1'
        if ($nd.Parent -and ([string]$nd.Parent.Tag) -like "GR:*") {
            $pGrpDn = ([string]$nd.Parent.Tag).Substring(3)
            $pMeta  = if ($script:ObjByDN -and $script:ObjByDN.ContainsKey($pGrpDn.ToLower())) { $script:ObjByDN[$pGrpDn.ToLower()] } else { $null }
            $pGrpCn = if ($pMeta) { [string]$pMeta.Name } else { ($pGrpDn -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)CN=', '' -replace '\\([,+="\\<>;# ])', '$1' }
            $miRem = New-Object System.Windows.Forms.ToolStripMenuItem("Gỡ '$cn' khỏi Group '$pGrpCn'")
            $miRem.Add_Click({
                if ($chkDry.Checked) { Write-Log "[CHẠY THỬ] Sẽ gỡ User '$cn' khỏi Group '$pGrpCn'" "Blue"; return }
                if (-not (Confirm-Msg "Gỡ User '$cn' khỏi Group '$pGrpCn'?")) { return }
                try {
                    Invoke-WithBusy { Remove-ADGroupMember -Identity $pGrpDn -Members $udn -Confirm:$false -ErrorAction Stop } "Đang gỡ khỏi Group..."
                    Write-Log "[OK] Đã gỡ '$cn' khỏi Group '$pGrpCn'." "Green"
                    Update-OUList -Force
                }
                catch { Write-Log ("[LỖI] Gỡ khỏi Group: " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Lỗi gỡ khỏi Group" "Error" }
            }.GetNewClosure())
            [void]$treeCtx.Items.Add($miRem)
            [void]$treeCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        }
        $mi = New-Object System.Windows.Forms.ToolStripMenuItem("Xóa User '$cn'")
        $mi.ForeColor = [System.Drawing.Color]::Firebrick
        $mi.Add_Click({ [void](Invoke-DeleteADUsers "" "" "" 1 $udn) }.GetNewClosure())
        [void]$treeCtx.Items.Add($mi)
    }
    elseif ($t -ne $script:DomainDN -and -not (Test-IsDomainControllersOU $t)) {
        $mi1 = New-Object System.Windows.Forms.ToolStripMenuItem("Xóa OU này (chỉ khi rỗng)")
        $mi1.Add_Click({ [void](Invoke-DeleteOU $t $false) }.GetNewClosure())
        $mi2 = New-Object System.Windows.Forms.ToolStripMenuItem("Xóa tự động OU này && toàn bộ đối tượng con...")
        $mi2.ForeColor = [System.Drawing.Color]::Firebrick
        $mi2.Add_Click({ [void](Invoke-DeleteOU $t $true) }.GetNewClosure())
        $mi3 = New-Object System.Windows.Forms.ToolStripMenuItem("Xóa tự động toàn bộ User trong OU này...")
        $mi3.ForeColor = [System.Drawing.Color]::Firebrick
        $mi3.Add_Click({ [void](Invoke-DeleteADUsers "" "" $t 5000) }.GetNewClosure())
        $mi4 = New-Object System.Windows.Forms.ToolStripMenuItem("Xóa tự động toàn bộ Group trong OU này...")
        $mi4.Add_Click({
            try {
                $gs = @(Get-ADGroup -SearchBase $t -SearchScope OneLevel -Filter * -ErrorAction Stop)
                if ($gs.Count -eq 0) { Show-Msg "OU này không có Group nào." "Thông báo" "Information"; return }
                [void](Invoke-DeleteADGroup @($gs | ForEach-Object { $_.DistinguishedName }) $t)
            }
            catch { Show-Msg $_.Exception.Message "Lỗi đọc Group" "Error" }
        }.GetNewClosure())
        [void]$treeCtx.Items.Add($mi1)
        [void]$treeCtx.Items.Add($mi2)
        [void]$treeCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        [void]$treeCtx.Items.Add($mi3)
        [void]$treeCtx.Items.Add($mi4)
        [void]$treeCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        $miGpo = New-Object System.Windows.Forms.ToolStripMenuItem("DS & Xóa GPO...")
        $miGpo.Add_Click({ $btnGpoMgr.PerformClick() })
        [void]$treeCtx.Items.Add($miGpo)
    }
    else {
        $miDis = New-Object System.Windows.Forms.ToolStripMenuItem("(Đối tượng gốc / Domain Controllers — không được xóa)")
        $miDis.Enabled = $false
        [void]$treeCtx.Items.Add($miDis)
    }
})

