$btnCreateOU.Add_Click({
    $prevPath = if ($cboOUParent.SelectedIndex -ge 0 -and $cboOUParent.SelectedIndex -lt $script:OUDN.Count) { $script:OUDN[$cboOUParent.SelectedIndex] } else { "" }
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        if ($prevPath -and (Find-DNIndex $prevPath) -lt 0) {
            Show-Msg "OU cha '$prevPath' không còn tồn tại trên AD.`r`nHãy chọn lại OU cha." "Không tìm thấy OU cha" "Warning"; return
        }
        $name = $txtOUName.Text
        $err  = Test-OUName $name
        if ($err) { Show-Msg $err "Chưa hợp lệ" "Warning"; return }
        if ($cboOUParent.SelectedIndex -lt 0 -or $cboOUParent.SelectedIndex -ge $script:OUDN.Count) { Show-Msg "Chưa chọn OU cha." "Chưa hợp lệ" "Warning"; return }

        $path = $script:OUDN[$cboOUParent.SelectedIndex]
        $mode = Resolve-DryRunBeforeCreate "Tạo OU '$name' trong: $path"
        if ($mode -eq "live") {
            if (-not (Confirm-Msg "Tạo OU '$name' trong:`r`n$path`r`n`r`nTiếp tục?")) { return }
        }
        if ($mode -ne "dry") { $script:CsvPreview = @() }
        $res = Invoke-WithBusy { New-OneOU -Name $name -Path $path -Desc $txtOUDesc.Text } "Đang tạo OU..."
        if ($res -eq "ok") { $txtOUName.Clear(); $txtOUDesc.Clear(); $script:Working = $false; Update-OUList -Force }
        elseif ($res -eq "fail" -and $script:LastCreateErr) { Show-Msg $script:LastCreateErr "Không tạo được OU" "Error" }
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

$btnDeleteOUQuick.Add_Click({
    if (-not $script:Ready) { return }
    $parentDn = if ($cboOUParent.SelectedIndex -ge 0 -and $cboOUParent.SelectedIndex -lt $script:OUDN.Count) { $script:OUDN[$cboOUParent.SelectedIndex] } else { "" }
    $rawName  = $txtOUName.Text.Trim()
    if ($rawName) {
        $err = Test-OUName $rawName
        if ($err) { Show-Msg $err "Chưa hợp lệ" "Warning"; return }
        if (-not $parentDn) { Show-Msg "Chưa chọn OU cha." "Chưa hợp lệ" "Warning"; return }
        $targetDn = "OU=" + ($rawName -replace ',', '\,') + "," + $parentDn
    }
    elseif ($cboOUParent.SelectedIndex -gt 0 -and $parentDn) {
        $targetDn = $parentDn
    }
    else {
        Show-Msg "Nhập tên OU muốn xóa hoặc chọn một OU cụ thể ở mục 1 (không thể xóa gốc domain)." "Chưa hợp lệ" "Warning"
        return
    }
    if (Invoke-DeleteOU $targetDn $chkOUQuickRecurse.Checked) {
        $txtOUName.Clear(); $txtOUDesc.Clear()
    }
})

$btnSample.Add_Click({
    try {
        $dlg = New-Object System.Windows.Forms.SaveFileDialog
        $dlg.Filter   = "File CSV (*.csv)|*.csv"
        $dlg.FileName = "ou_list.csv"
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $dn = $script:DomainDN
        $lines = @(
            "Name,Path,Description",
            "KeToan,""$dn"",Phòng Kế toán",
            "NhanSu,""$dn"",Phòng Nhân sự",
            "NhanVien,""OU=KeToan,$dn"",Nhân viên kế toán",
            "MayTinh,""OU=KeToan,$dn"",Máy tính phòng kế toán"
        )
        Set-Content -Path $dlg.FileName -Value $lines -Encoding UTF8
        Write-Log "Đã lưu file mẫu: $($dlg.FileName)" "Green"
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red" }
})

$btnCsv.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        $dlg = New-Object System.Windows.Forms.OpenFileDialog
        $dlg.Filter = "File CSV (*.csv)|*.csv"
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }

        $rows = @(Import-Csv -Path $dlg.FileName -Encoding UTF8)
        if ($rows.Count -eq 0 -or -not ($rows[0].PSObject.Properties.Name -contains 'Name')) {
            Show-Msg "File CSV phải có dòng đầu là:  Name,Path,Description`r`nBấm 'Lưu file CSV mẫu' để lấy file mẫu." "File CSV chưa đúng" "Warning"
            return
        }
        # Vẽ xem trước lên sơ đồ
        $script:CsvPreview = @()
        $willNew = 0; $already = 0; $badRows = 0; $seenCsv = @{}
        foreach ($r in $rows) {
            $p = $r.Path; if ([string]::IsNullOrWhiteSpace($p)) { $p = $script:DomainDN }
            $nm = ([string]$r.Name).Trim(); $p = $p.Trim()
            if (Test-OUName $nm) { $badRows++; continue }
            $k = ("OU=$nm,$p").ToLower()
            if ($script:OUSet.ContainsKey($k) -or $seenCsv.ContainsKey($k)) { $already++ }
            else { $willNew++; $seenCsv[$k] = $true; $script:CsvPreview += @{ Name = $nm; Path = $p } }
        }
        Update-Ghosts
        Write-Log ("Xem trước trên sơ đồ: $willNew OU sẽ tạo mới, $already OU đã có/trùng, $badRows dòng tên không hợp lệ.") "Blue"

        if (-not $chkDry.Checked) {
            if (-not (Confirm-Msg ("File CSV có " + $rows.Count + " dòng: " + $willNew + " OU mới, " + $already + " OU đã có/trùng (bỏ qua)" + $(if ($badRows -gt 0) { ", $badRows dòng lỗi tên" } else { "" }) + ".`r`n`r`nTiếp tục tạo?"))) { $script:CsvPreview = @(); Update-Ghosts; return }
        }
        $count = @{ ok = 0; skip = 0; fail = 0; dry = 0 }
        $dryPlanned = @{}
        Invoke-WithBusy {
            foreach ($r in $rows) {
                $p = $r.Path
                if ([string]::IsNullOrWhiteSpace($p)) { $p = $script:DomainDN }
                $res = New-OneOU -Name ([string]$r.Name).Trim() -Path $p.Trim() -Desc $r.Description -DryPlanned $dryPlanned
                $count[$res]++
            }
        } "Đang xử lý danh sách OU từ CSV..."
        Write-Log ("Xong: tạo " + $count.ok + ", bỏ qua " + $count.skip + ", lỗi " + $count.fail + ", chạy thử " + $count.dry) "Black"
        $script:Working = $false
        if (-not $chkDry.Checked) {
            $script:CsvPreview = @()
            Update-OUList -Force
            Update-Ghosts
        }
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

function Test-GpoScopeTarget {
    param([string]$ScopeKind, [string]$ScopeObj, [bool]$HasMachineSettings, [bool]$HasUserSettings)
    if ($ScopeKind -eq 'OU') { return @{ Ok = $true; Sam = ''; SkipMachine = $false } }
    if (-not $ScopeObj) {
        Show-Msg ("Bạn đã chọn áp dụng cho " + $ScopeKind + " nhưng chưa nhập tên " + $ScopeKind + ".") "Chưa hợp lệ" "Warning"
        return @{ Ok = $false; Sam = ''; SkipMachine = $false }
    }
    $esc = $ScopeObj -replace "'", "''"
    $resolvedSam = ""
    $skipM = $false
    if ($ScopeKind -eq 'User') {
        $u = @(Get-ADUser -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction SilentlyContinue)
        if ($u.Count -eq 0) { Show-Msg "Không tìm thấy User '$ScopeObj' trong AD." "Không tìm thấy" "Warning"; return @{ Ok = $false; Sam = ''; SkipMachine = $false } }
        if ($u.Count -gt 1) { Show-Msg "Có $($u.Count) User trùng tên '$ScopeObj'. Hãy nhập chính xác SamAccountName." "Trùng nhiều User" "Warning"; return @{ Ok = $false; Sam = ''; SkipMachine = $false } }
        $resolvedSam = $u[0].SamAccountName
        if ($HasMachineSettings) {
            $msg = "Bạn đang chọn thiết lập cho MÁY TÍNH (Computer Configuration) nhưng lọc phạm vi 'Chỉ User'.`r`nChính sách Computer sẽ KHÔNG áp dụng cho bất kỳ máy nào vì bị lọc mất quyền Computer!"
            if ($HasUserSettings) {
                if (-not (Confirm-Msg ($msg + "`r`n`r`nChỉ áp dụng phần User cho '$resolvedSam' và bỏ qua phần Computer?"))) { return @{ Ok = $false; Sam = ''; SkipMachine = $false } }
                $skipM = $true
            }
            else {
                Show-Msg $msg "Sai phạm vi" "Warning"; return @{ Ok = $false; Sam = ''; SkipMachine = $false }
            }
        }
    }
    else {
        $authName = try { (New-Object System.Security.Principal.SecurityIdentifier 'S-1-5-11').Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1] } catch { 'Authenticated Users' }
        if ($ScopeObj -ieq 'Authenticated Users' -or $ScopeObj -ieq $authName -or $ScopeObj -ieq 'S-1-5-11') {
            Show-Msg "Không chọn '$ScopeObj' làm bộ lọc riêng vì đây là nhóm mặc định cho toàn bộ OU. Hãy chọn 'Toàn bộ OU'." "Chưa hợp lệ" "Warning"
            return @{ Ok = $false; Sam = ''; SkipMachine = $false }
        }
        $g = @(Get-ADGroup -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction SilentlyContinue)
        if ($g.Count -eq 0) { Show-Msg "Không tìm thấy Group '$ScopeObj' trong AD." "Không tìm thấy" "Warning"; return @{ Ok = $false; Sam = ''; SkipMachine = $false } }
        if ($g.Count -gt 1) { Show-Msg "Có $($g.Count) Group trùng tên '$ScopeObj'. Hãy nhập chính xác SamAccountName." "Trùng nhiều Group" "Warning"; return @{ Ok = $false; Sam = ''; SkipMachine = $false } }
        if ($g[0].GroupCategory -ne 'Security') { Show-Msg "Group '$($g[0].Name)' là nhóm Distribution, không dùng được cho Security Filtering. Hãy chọn Security Group." "Chưa hợp lệ" "Warning"; return @{ Ok = $false; Sam = ''; SkipMachine = $false } }
        $resolvedSam = $g[0].SamAccountName
        if ($HasMachineSettings) {
            Write-Log "[LƯU Ý] GPO có thiết lập MÁY TÍNH đang lọc cho Group '$resolvedSam': nhóm này phải chứa tài khoản MÁY TÍNH (Computer) thì phần máy tính mới có tác dụng." "DarkOrange"
        }
    }
    return @{ Ok = $true; Sam = $resolvedSam; SkipMachine = $skipM }
}

$btnCreateGPO.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    $name = ""
    try {
        $name = $txtGPOName.Text.Trim()
        if (-not $name) { Show-Msg "Bạn chưa nhập tên GPO." "Chưa hợp lệ" "Warning"; return }
        if ($name -match '[\\/:*?"<>|]') { Show-Msg 'Tên GPO không được chứa các ký tự:  \ / : * ? " < > |' "Chưa hợp lệ" "Warning"; return }
        $cmt = $txtGPOComment.Text.Trim()
        if ($cmt.Length -gt 2048) { Show-Msg "Ghi chú GPO tối đa 2048 ký tự." "Chưa hợp lệ" "Warning"; return }
        if ($cboGPOTarget.SelectedIndex -lt 0 -or $cboGPOTarget.SelectedIndex -ge $script:OUDN.Count) { Show-Msg "Chưa chọn OU đích." "Chưa hợp lệ" "Warning"; return }

        $anySetting = $chkLock.Checked -or $chkNoCP.Checked -or $chkNoCMD.Checked -or $chkUSB.Checked
        if (-not $anySetting) {
            if (-not (Confirm-Msg "Bạn chưa tick thiết lập nào.`r`nGPO sẽ được tạo rỗng. Tiếp tục?")) { return }
        }

        $target = $script:OUDN[$cboGPOTarget.SelectedIndex]
        $scopeIdx = $cboGpoScopeType.SelectedIndex
        $scopeKind = if ($scopeIdx -eq 1) { 'Group' } elseif ($scopeIdx -eq 2) { 'User' } else { 'OU' }
        $scopeObj = $txtGpoScopeTarget.Text.Trim()
        $hasUser = $chkLock.Checked -or $chkNoCP.Checked -or $chkNoCMD.Checked
        $scopeRes = Test-GpoScopeTarget $scopeKind $scopeObj $chkUSB.Checked $hasUser
        if (-not $scopeRes.Ok) { return }
        $scopeSam = if ($scopeRes.Sam) { $scopeRes.Sam } else { $scopeObj }
        $applyUsb = $chkUSB.Checked -and (-not $scopeRes.SkipMachine)

        $existing = Get-GPO -Name $name -ErrorAction SilentlyContinue
        if ($existing) {
            Show-Msg "Đã có GPO tên '$name'.`r`nHãy đặt tên khác để tránh ghi đè." "Trùng tên" "Warning"
            return
        }

        # Danh sách việc sẽ làm
        $todo = @()
        if ($chkLock.Checked)  { $todo += ("Tự khóa màn hình sau " + $numMin.Value + " phút") }
        if ($chkNoCP.Checked)  { $todo += "Ẩn Control Panel và Settings" }
        if ($chkNoCMD.Checked) { $todo += "Chặn Command Prompt" }
        if ($applyUsb)         { $todo += "Chặn ổ USB lưu trữ (Removable Storage)" }
        elseif ($chkUSB.Checked -and $scopeRes.SkipMachine) { $todo += "(Bỏ qua Chặn USB vì lọc 'Chỉ User')" }
        $summary = if ($todo.Count) { ($todo -join "; ") } else { "(không có thiết lập)" }

        $domRootWarn = if ($chkLink.Checked -and $target -ieq $script:DomainDN) { "`r`n⚠ CẢNH BÁO: Đang liên kết vào GỐC DOMAIN (áp dụng toàn bộ domain, kể cả Admin & DC)." } else { "" }
        $gpoPlan = "Tạo GPO '$name' ($summary)" +
                   $(if ($chkLink.Checked) { "`r`nLiên kết vào: $target" } else { "`r`n(Chưa liên kết vào OU nào)" }) +
                   $(if ($scopeKind -ne 'OU') { "`r`nChỉ áp dụng cho ${scopeKind}: $scopeSam" } else { "" }) + $domRootWarn

        $mode = Resolve-DryRunBeforeCreate $gpoPlan
        if ($mode -eq "dry") {
            Write-Log "[CHẠY THỬ] Sẽ tạo GPO: $name" "Blue"
            Write-Log "[CHẠY THỬ]   Thiết lập: $summary" "Blue"
            if ($chkLink.Checked) { Write-Log "[CHẠY THỬ]   Sẽ liên kết vào: $target" "Blue" }
            else { Write-Log "[CHẠY THỬ]   (Chưa liên kết vào OU nào)" "Blue" }
            if ($scopeKind -ne 'OU') { Write-Log "[CHẠY THỬ]   Lọc bảo mật (Security Filtering): chỉ áp dụng cho $scopeKind '$scopeSam'" "Blue" }
            return
        }

        if ($mode -eq "live") {
            $msg = "Tạo GPO '$name'`r`nThiết lập: $summary"
            if ($chkLink.Checked) { $msg += "`r`nLiên kết vào: $target" }
            else { $msg += "`r`n(Chưa liên kết vào OU nào)" }
            if ($scopeKind -ne 'OU') { $msg += "`r`nChỉ áp dụng cho ${scopeKind}: $scopeSam" }
            $msg += $domRootWarn
            if (-not (Confirm-Msg ($msg + "`r`n`r`nTiếp tục?"))) { return }
        }

        Invoke-WithBusy {
            $newParams = @{ Name = $name; ErrorAction = 'Stop' }
            if ($cmt) { $newParams.Comment = $cmt }
            New-GPO @newParams | Out-Null
            $script:TmpCreated = $true
            Write-Log "[OK] Đã tạo GPO: $name" "Green"

            if ($chkLock.Checked) {
                $k = 'HKCU\Software\Policies\Microsoft\Windows\Control Panel\Desktop'
                Set-Pol $name $k 'ScreenSaveActive'   'String' '1'
                Set-Pol $name $k 'ScreenSaverIsSecure' 'String' '1'
                Set-Pol $name $k 'SCRNSAVE.EXE'       'String' 'scrnsave.scr'
                Set-Pol $name $k 'ScreenSaveTimeOut'  'String' ([string]([int]$numMin.Value * 60))
                Write-Log "[OK]   Tự khóa màn hình sau $($numMin.Value) phút" "Green"
            }
            if ($chkNoCP.Checked) {
                Set-Pol $name 'HKCU\Software\Microsoft\Windows\CurrentVersion\Policies\Explorer' 'NoControlPanel' 'DWord' 1
                Write-Log "[OK]   Ẩn Control Panel và Settings" "Green"
            }
            if ($chkNoCMD.Checked) {
                Set-Pol $name 'HKCU\Software\Policies\Microsoft\Windows\System' 'DisableCMD' 'DWord' 2
                Write-Log "[OK]   Chặn Command Prompt (cho phép chạy .bat/.cmd)" "Green"
            }
            if ($applyUsb) {
                $uk = 'HKLM\SOFTWARE\Policies\Microsoft\Windows\RemovableStorageDevices\{53f5630d-b6bf-11d0-94f2-00a0c91efb8b}'
                Set-Pol $name $uk 'Deny_Read' 'DWord' 1
                Set-Pol $name $uk 'Deny_Write' 'DWord' 1
                Set-Pol $name $uk 'Deny_Execute' 'DWord' 1
                Write-Log "[OK]   Chặn ổ USB lưu trữ (Removable Storage)" "Green"
            }
            elseif ($chkUSB.Checked -and $scopeRes.SkipMachine) {
                Write-Log "[BỎ QUA] Đã bỏ qua phần Computer 'Chặn USB' vì GPO lọc 'Chỉ User'." "DarkOrange"
            }
            if ($scopeKind -ne 'OU') {
                Set-GpoScopeFilter $name $scopeKind $scopeSam
                Write-Log "[OK]   Đã lọc bảo mật: chỉ áp dụng cho $scopeKind '$scopeSam'" "Green"
            }
            if ($chkLink.Checked) {
                New-GPLink -Name $name -Target $target -LinkEnabled Yes -ErrorAction Stop | Out-Null
                Write-Log "[OK]   Đã liên kết vào: $target" "Green"
            }
            $script:TmpCreated = $false
        } "Đang tạo Group Policy..."
        if ($chkLink.Checked) {
            Write-Log "Hoàn tất tạo & liên kết GPO. Chính sách chỉ có hiệu lực sau khi máy đích nhận GPO (~90 phút hoặc chạy: gpupdate /force)." "Black"
        } else {
            Write-Log "Đã tạo GPO (CHƯA liên kết vào OU nào — chính sách sẽ CHƯA áp dụng cho đến khi bạn liên kết trong 'Quản lý GPO...')." "DarkOrange"
        }
        $script:Working = $false
        Update-OUList -Force
    }
    catch {
        Write-Log ("[LỖI] " + $_.Exception.Message) "Red"
        if ($script:TmpCreated -and $name) {
            try { Remove-GPO -Name $name -Confirm:$false -ErrorAction Stop; Write-Log ("      Đã dọn GPO lỗi dở dang: " + $name) "DarkOrange" }
            catch { Write-Log ("      Không dọn được GPO dở dang '" + $name + "', hãy xóa tay trong GPMC.") "Red" }
            $script:TmpCreated = $false
        }
        Show-Msg $_.Exception.Message "Có lỗi" "Error"
    }
    finally { $script:TmpCreated = $false; $script:Working = $false }
})

$btnGpoMgr.Add_Click({
    if (-not $script:Ready) { Show-Msg "Chưa kết nối Active Directory." "Chưa sẵn sàng" "Warning"; return }
    $prevWorkMgr = $script:Working
    $script:Working = $true
    $dlg = New-Object System.Windows.Forms.Form
    try {
        $dlg.Text = "Quản lý danh sách GPO trong Domain"
        $dlg.ClientSize = New-Object System.Drawing.Size(820, 445)
        $dlg.StartPosition = "CenterParent"
        $dlg.FormBorderStyle = "FixedDialog"
        $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
        $dlg.Font = $fontMain

        $lv = New-Object System.Windows.Forms.ListView
        $lv.Location = New-Object System.Drawing.Point(12, 12)
        $lv.Size     = New-Object System.Drawing.Size(796, 260)
        $lv.View = "Details"; $lv.CheckBoxes = $true; $lv.FullRowSelect = $true; $lv.HideSelection = $false; $lv.MultiSelect = $false
        [void]$lv.Columns.Add("Tên GPO", 220)
        [void]$lv.Columns.Add("Trạng thái (GpoStatus)", 185)
        [void]$lv.Columns.Add("Liên kết OU", 255)
        [void]$lv.Columns.Add("Cập nhật", 110)
        $dlg.Controls.Add($lv)

        $gpoDlgCtx = New-Object System.Windows.Forms.ContextMenuStrip
        $lv.ContextMenuStrip = $gpoDlgCtx
        $lv.Add_MouseDown({
            if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Right) {
                $hit = $this.HitTest($_.Location)
                if ($hit -and $hit.Item) {
                    $this.SelectedItems.Clear()
                    $hit.Item.Selected = $true
                    $hit.Item.Focused  = $true
                }
                else { $this.SelectedItems.Clear() }
            }
        })

        $statItems = @(
            @{ Code = 'AllSettingsEnabled';       Label = 'Bật toàn bộ (AllEnabled)' },
            @{ Code = 'UserSettingsDisabled';     Label = 'Tắt phần User (UserDisabled)' },
            @{ Code = 'ComputerSettingsDisabled'; Label = 'Tắt phần Computer (CompDisabled)' },
            @{ Code = 'AllSettingsDisabled';      Label = 'Tắt toàn bộ (AllDisabled)' }
        )

        [void](Add-Label $dlg "OU thao tác:" 12 285 94 $true)
        $cboDlgOU = New-Object System.Windows.Forms.ComboBox
        $cboDlgOU.Location = New-Object System.Drawing.Point(108, 282)
        $cboDlgOU.Size     = New-Object System.Drawing.Size(346, 26)
        $cboDlgOU.DropDownStyle = "DropDownList"
        $dlgOuDns = @($script:OUDN)
        foreach ($it in $cboGPOTarget.Items) { [void]$cboDlgOU.Items.Add($it) }
        if ($cboGPOTarget.SelectedIndex -ge 0 -and $cboGPOTarget.SelectedIndex -lt $dlgOuDns.Count) { $cboDlgOU.SelectedIndex = $cboGPOTarget.SelectedIndex }
        $dlg.Controls.Add($cboDlgOU)

        $cboDlgStat = New-Object System.Windows.Forms.ComboBox
        $cboDlgStat.Location = New-Object System.Drawing.Point(462, 282)
        $cboDlgStat.Size     = New-Object System.Drawing.Size(214, 26)
        $cboDlgStat.DropDownStyle = "DropDownList"
        foreach ($si in $statItems) { [void]$cboDlgStat.Items.Add($si.Label) }
        $cboDlgStat.SelectedIndex = 0
        $dlg.Controls.Add($cboDlgStat)
        $btnDlgSetStat = Add-Button $dlg "Đổi trạng thái" 684 281 124 28
        $btnDlgSetStat.Font = $fontBold

        $btnDlgLink   = Add-Button $dlg "Liên kết vào OU" 12 322 132 32
        $btnDlgUnlink = Add-Button $dlg "Gỡ khỏi OU" 150 322 110 32
        $btnDlgEnf    = Add-Button $dlg "Bật/Tắt Enforced" 266 322 136 32
        $btnDlgEnLink = Add-Button $dlg "Bật/Tắt Link" 408 322 116 32
        $btnDlgDel    = Add-Button $dlg "Xóa GPO" 530 322 104 32
        $btnDlgRef    = Add-Button $dlg "Làm mới" 640 322 78 32
        $btnDlgClose  = Add-Button $dlg "Đóng" 724 322 84 32
        $btnDlgClose.DialogResult = "Cancel"

        $lblDlgStatus = New-Object System.Windows.Forms.Label
        $lblDlgStatus.Location    = New-Object System.Drawing.Point(12, 366)
        $lblDlgStatus.Size        = New-Object System.Drawing.Size(796, 68)
        $lblDlgStatus.UseMnemonic = $false
        $lblDlgStatus.ForeColor   = [System.Drawing.Color]::FromArgb(30, 58, 95)
        $lblDlgStatus.BackColor = [System.Drawing.Color]::FromArgb(248, 250, 252)
        $lblDlgStatus.BorderStyle = "FixedSingle"
        $lblDlgStatus.Padding   = New-Object System.Windows.Forms.Padding(8, 6, 8, 6)
        $lblDlgStatus.Text      = "Chọn 1 GPO trong danh sách để xem liên kết hoặc thao tác."
        $dlg.Controls.Add($lblDlgStatus)

        $setDlgStat = {
            param([string]$Txt, [System.Drawing.Color]$Col)
            $lblDlgStatus.ForeColor = $Col
            $lblDlgStatus.Text = $Txt
        }

        $loadGpos = {
            $dlg.UseWaitCursor = $true
            $lv.Items.Clear()
            try {
                $linkMap = @{}
                $targetsToScan = @([pscustomobject]@{ Name = $script:DomainName; DN = $script:DomainDN; GpLink = (Get-ADObject -Identity $script:DomainDN -Properties gPLink -ErrorAction SilentlyContinue).gPLink })
                foreach ($ouRec in @(Get-ADOrganizationalUnit -Filter * -Properties gPLink -ErrorAction SilentlyContinue)) {
                    $targetsToScan += [pscustomobject]@{ Name = $ouRec.Name; DN = $ouRec.DistinguishedName; GpLink = $ouRec.gPLink }
                }
                foreach ($tObj in $targetsToScan) {
                    if (-not $tObj.GpLink) { continue }
                    foreach ($m in [regex]::Matches([string]$tObj.GpLink, '\{([0-9A-Fa-f\-]{36})\},[^;\]]*;(\d+)')) {
                        $gid = $m.Groups[1].Value.ToLower()
                        $opt = [int]$m.Groups[2].Value
                        $flags = @()
                        if ($opt -band 1) { $flags += 'Tắt' }
                        if ($opt -band 2) { $flags += 'Enforced' }
                        $lbl = $tObj.Name + $(if ($flags.Count -gt 0) { " [" + ($flags -join ',') + "]" } else { "" })
                        if (-not $linkMap.ContainsKey($gid)) { $linkMap[$gid] = New-Object 'System.Collections.Generic.List[string]' }
                        $linkMap[$gid].Add($lbl)
                    }
                }
                foreach ($g in @(Get-GPO -All -ErrorAction Stop | Sort-Object DisplayName)) {
                    $gid = $g.Id.ToString().ToLower()
                    $lnkTxt = if ($linkMap.ContainsKey($gid)) { ($linkMap[$gid] -join '; ') } else { "(Chưa liên kết)" }
                    $li = New-Object System.Windows.Forms.ListViewItem $g.DisplayName
                    [void]$li.SubItems.Add([string]$g.GpoStatus)
                    [void]$li.SubItems.Add($lnkTxt)
                    [void]$li.SubItems.Add($g.ModificationTime.ToString("dd/MM/yyyy HH:mm"))
                    $li.Tag = $g
                    [void]$lv.Items.Add($li)
                }
                & $setDlgStat ("Đã tải $($lv.Items.Count) GPO trong domain.") ([System.Drawing.Color]::FromArgb(30, 58, 95))
            }
            catch {
                & $setDlgStat ("[LỖI] Không đọc được GPO: " + $_.Exception.Message) ([System.Drawing.Color]::Firebrick)
                Show-Msg $_.Exception.Message "Lỗi đọc GPO" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        }

        $lv.Add_SelectedIndexChanged({
            if ($lv.SelectedItems.Count -eq 0) { return }
            $g = $lv.SelectedItems[0].Tag
            for ($idx = 0; $idx -lt $statItems.Count; $idx++) {
                if ($statItems[$idx].Code -eq [string]$g.GpoStatus) { $cboDlgStat.SelectedIndex = $idx; break }
            }
            & $setDlgStat ("Đang chọn: '$($g.DisplayName)'  |  Trạng thái: $($g.GpoStatus)  |  Liên kết: $($lv.SelectedItems[0].SubItems[2].Text)") ([System.Drawing.Color]::FromArgb(30, 58, 95))
        })

        $getSelGpo = {
            if ($lv.SelectedItems.Count -eq 0) { Show-Msg "Hãy chọn 1 GPO trong danh sách." "Chưa chọn" "Warning"; return $null }
            return $lv.SelectedItems[0].Tag
        }
        $defaultGpoGuids = @('31b2f340-016d-11d2-945f-00c04fb984f9', '6ac1786c-016f-11d2-945f-00c04fb984f9')

        $btnDlgRef.Add_Click({ & $loadGpos })

        $btnDlgLink.Add_Click({
            $g = & $getSelGpo; if (-not $g -or $cboDlgOU.SelectedIndex -lt 0 -or $cboDlgOU.SelectedIndex -ge $dlgOuDns.Count) { return }
            $dn = $dlgOuDns[$cboDlgOU.SelectedIndex]
            $dlg.UseWaitCursor = $true
            try {
                $curLnk = (Get-GPInheritance -Target $dn -ErrorAction Stop).GpoLinks | Where-Object { $_.GpoId -eq $g.Id }
                if ($curLnk) {
                    $m = "GPO '$($g.DisplayName)' đã được liên kết vào '$dn' rồi."
                    & $setDlgStat ("[CẢNH BÁO] " + $m) ([System.Drawing.Color]::DarkOrange)
                    Show-Msg $m "Đã liên kết" "Warning"; return
                }
                if ($chkDry.Checked) {
                    $m = "[CHẠY THỬ] Sẽ liên kết GPO '$($g.DisplayName)' vào '$dn'"
                    Write-Log $m "Blue"; & $setDlgStat $m ([System.Drawing.Color]::RoyalBlue); return
                }
                if (-not (Confirm-Msg "Liên kết GPO '$($g.DisplayName)' vào:`r`n$dn`r`n`r`nTiếp tục?")) { return }
                New-GPLink -Guid $g.Id -Target $dn -LinkEnabled Yes -ErrorAction Stop | Out-Null
                $m = "[OK] Đã liên kết '$($g.DisplayName)' vào '$dn'"
                Write-Log $m "Green"; & $loadGpos; & $setDlgStat $m ([System.Drawing.Color]::ForestGreen)
            }
            catch {
                $m = "[LỖI] Liên kết GPO: " + $_.Exception.Message
                Write-Log $m "Red"; & $setDlgStat $m ([System.Drawing.Color]::Firebrick); Show-Msg $_.Exception.Message "Lỗi liên kết GPO" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        })

        $btnDlgUnlink.Add_Click({
            $g = & $getSelGpo; if (-not $g -or $cboDlgOU.SelectedIndex -lt 0 -or $cboDlgOU.SelectedIndex -ge $dlgOuDns.Count) { return }
            $dn = $dlgOuDns[$cboDlgOU.SelectedIndex]
            $isDef = ($g.Id.ToString().ToLower() -in $defaultGpoGuids)
            if ($chkDry.Checked) {
                $m = "[CHẠY THỬ] Sẽ gỡ liên kết GPO '$($g.DisplayName)' khỏi '$dn'"
                Write-Log $m "Blue"; & $setDlgStat $m ([System.Drawing.Color]::RoyalBlue); return
            }
            $warnDef = if ($isDef) { "`r`n`r`n⚠ CẢNH BÁO: Đây là GPO MẶC ĐỊNH CỦA HỆ THỐNG! Gỡ liên kết có thể làm hỏng đăng nhập/bảo mật domain!" } else { "" }
            if (-not (Confirm-Msg "Gỡ liên kết GPO '$($g.DisplayName)' khỏi:`r`n$dn?$warnDef" "Xác nhận" "Warning")) { return }
            $dlg.UseWaitCursor = $true
            try {
                Remove-GPLink -Guid $g.Id -Target $dn -Confirm:$false -ErrorAction Stop | Out-Null
                $m = "[OK] Đã gỡ liên kết '$($g.DisplayName)' khỏi '$dn'"
                Write-Log $m "Green"; & $loadGpos; & $setDlgStat $m ([System.Drawing.Color]::ForestGreen)
            }
            catch {
                $m = "[LỖI] Gỡ liên kết GPO: " + $_.Exception.Message
                Write-Log $m "Red"; & $setDlgStat $m ([System.Drawing.Color]::Firebrick); Show-Msg $_.Exception.Message "Lỗi gỡ liên kết" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        })

        $btnDlgEnf.Add_Click({
            $g = & $getSelGpo; if (-not $g -or $cboDlgOU.SelectedIndex -lt 0 -or $cboDlgOU.SelectedIndex -ge $dlgOuDns.Count) { return }
            $dn = $dlgOuDns[$cboDlgOU.SelectedIndex]
            $dlg.UseWaitCursor = $true
            try {
                $lnk = (Get-GPInheritance -Target $dn -ErrorAction Stop).GpoLinks | Where-Object { $_.GpoId -eq $g.Id }
                if (-not $lnk) {
                    $m = "GPO '$($g.DisplayName)' chưa được liên kết vào '$dn'."
                    & $setDlgStat ("[CẢNH BÁO] " + $m) ([System.Drawing.Color]::DarkOrange); Show-Msg $m "Chưa liên kết" "Warning"; return
                }
                $next = if ($lnk.Enforced) { 'No' } else { 'Yes' }
                if ($chkDry.Checked) {
                    $m = "[CHẠY THỬ] Sẽ đặt Enforced=$next cho GPO '$($g.DisplayName)' tại '$dn'"
                    Write-Log $m "Blue"; & $setDlgStat $m ([System.Drawing.Color]::RoyalBlue); return
                }
                if (-not (Confirm-Msg "Đặt Enforced = $next cho GPO '$($g.DisplayName)' tại:`r`n$dn`r`n`r`nTiếp tục?")) { return }
                Set-GPLink -Guid $g.Id -Target $dn -Enforced $next -ErrorAction Stop | Out-Null
                $m = "[OK] Đã đặt Enforced=$next cho '$($g.DisplayName)' tại '$dn'"
                Write-Log $m "Green"; & $loadGpos; & $setDlgStat $m ([System.Drawing.Color]::ForestGreen)
            }
            catch {
                $m = "[LỖI] Enforced GPO: " + $_.Exception.Message
                Write-Log $m "Red"; & $setDlgStat $m ([System.Drawing.Color]::Firebrick); Show-Msg $_.Exception.Message "Lỗi Enforced" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        })

        $btnDlgEnLink.Add_Click({
            $g = & $getSelGpo; if (-not $g -or $cboDlgOU.SelectedIndex -lt 0 -or $cboDlgOU.SelectedIndex -ge $dlgOuDns.Count) { return }
            $dn = $dlgOuDns[$cboDlgOU.SelectedIndex]
            $isDef = ($g.Id.ToString().ToLower() -in $defaultGpoGuids)
            $dlg.UseWaitCursor = $true
            try {
                $lnk = (Get-GPInheritance -Target $dn -ErrorAction Stop).GpoLinks | Where-Object { $_.GpoId -eq $g.Id }
                if (-not $lnk) {
                    $m = "GPO '$($g.DisplayName)' chưa được liên kết vào '$dn'."
                    & $setDlgStat ("[CẢNH BÁO] " + $m) ([System.Drawing.Color]::DarkOrange); Show-Msg $m "Chưa liên kết" "Warning"; return
                }
                $next = if ($lnk.Enabled) { 'No' } else { 'Yes' }
                if ($chkDry.Checked) {
                    $m = "[CHẠY THỬ] Sẽ đặt LinkEnabled=$next cho GPO '$($g.DisplayName)' tại '$dn'"
                    Write-Log $m "Blue"; & $setDlgStat $m ([System.Drawing.Color]::RoyalBlue); return
                }
                $warnDef = if ($isDef -and $next -eq 'No') { "`r`n`r`n⚠ CẢNH BÁO: Đây là GPO MẶC ĐỊNH CỦA HỆ THỐNG!" } else { "" }
                if (-not (Confirm-Msg "Đặt LinkEnabled = $next cho GPO '$($g.DisplayName)' tại:`r`n$dn$warnDef`r`n`r`nTiếp tục?" "Xác nhận" $(if ($isDef) { "Warning" } else { "Question" }))) { return }
                Set-GPLink -Guid $g.Id -Target $dn -LinkEnabled $next -ErrorAction Stop | Out-Null
                $m = "[OK] Đã đặt LinkEnabled=$next cho '$($g.DisplayName)' tại '$dn'"
                Write-Log $m "Green"; & $loadGpos; & $setDlgStat $m ([System.Drawing.Color]::ForestGreen)
            }
            catch {
                $m = "[LỖI] LinkEnabled GPO: " + $_.Exception.Message
                Write-Log $m "Red"; & $setDlgStat $m ([System.Drawing.Color]::Firebrick); Show-Msg $_.Exception.Message "Lỗi LinkEnabled" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        })

        $btnDlgSetStat.Add_Click({
            $g = & $getSelGpo; if (-not $g -or $cboDlgStat.SelectedIndex -lt 0) { return }
            $st = $statItems[$cboDlgStat.SelectedIndex].Code
            $isDef = ($g.Id.ToString().ToLower() -in $defaultGpoGuids)
            if ($chkDry.Checked) {
                $m = "[CHẠY THỬ] Sẽ đổi GpoStatus của '$($g.DisplayName)' thành '$st'"
                Write-Log $m "Blue"; & $setDlgStat $m ([System.Drawing.Color]::RoyalBlue); return
            }
            $warnDef = if ($isDef -and $st -ne 'AllSettingsEnabled') { "`r`n`r`n⚠ CẢNH BÁO: Đang tắt cài đặt trên GPO MẶC ĐỊNH CỦA HỆ THỐNG!" } else { "" }
            if (-not (Confirm-Msg "Đổi trạng thái (GpoStatus) của '$($g.DisplayName)' thành '$st'?$warnDef" "Xác nhận" $(if ($isDef) { "Warning" } else { "Question" }))) { return }
            $dlg.UseWaitCursor = $true
            try {
                $g.GpoStatus = $st
                $m = "[OK] Đã đổi GpoStatus của '$($g.DisplayName)' -> $st"
                Write-Log $m "Green"; & $loadGpos; & $setDlgStat $m ([System.Drawing.Color]::ForestGreen)
            }
            catch {
                $m = "[LỖI] Đổi trạng thái GPO: " + $_.Exception.Message
                Write-Log $m "Red"; & $setDlgStat $m ([System.Drawing.Color]::Firebrick); Show-Msg $_.Exception.Message "Lỗi đổi trạng thái" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        })

        $btnDlgDel.Add_Click({
            $targets = if ($lv.CheckedItems.Count -gt 0) {
                @($lv.CheckedItems | ForEach-Object { $_.Tag })
            } elseif ($lv.SelectedItems.Count -gt 0) {
                @($lv.SelectedItems[0].Tag)
            } else { @() }
            if ($targets.Count -eq 0) {
                Show-Msg "Hãy chọn (hoặc tick) ít nhất 1 GPO cần xóa." "Chưa chọn" "Warning"; return
            }
            $defHit = $targets | Where-Object { $_.Id.ToString().ToLower() -in $defaultGpoGuids } | Select-Object -First 1
            if ($defHit) {
                Show-Msg "Không được phép xóa GPO mặc định của hệ thống ($($defHit.DisplayName))." "Bị chặn" "Warning"; return
            }
            $namesStr = ($targets | ForEach-Object { $_.DisplayName }) -join ', '
            $delMode = Resolve-DryRunBeforeCreate ("Xóa vĩnh viễn $($targets.Count) GPO: $namesStr")
            if ($delMode -eq "dry") {
                $m = "[CHẠY THỬ] Sẽ XÓA $($targets.Count) GPO: $namesStr"
                Write-Log $m "Blue"; & $setDlgStat $m ([System.Drawing.Color]::RoyalBlue); return
            }
            if ($delMode -eq "live") {
                $qMsg = if ($targets.Count -eq 1) {
                    "Xóa vĩnh viễn GPO '$namesStr'?`r`nHành động này gỡ bỏ mọi cài đặt và liên kết của GPO!"
                } else {
                    "Xóa vĩnh viễn $($targets.Count) GPO đã tick?`r`n$namesStr`r`n`r`nHành động này gỡ bỏ mọi cài đặt và liên kết của các GPO này!"
                }
                if (-not (Confirm-Msg $qMsg "Cảnh báo xóa GPO" "Warning")) { return }
            }
            $dlg.UseWaitCursor = $true
            try {
                $delNames = New-Object 'System.Collections.Generic.List[string]'
                foreach ($tg in $targets) {
                    Remove-GPO -Guid $tg.Id -Confirm:$false -ErrorAction Stop
                    $delNames.Add($tg.DisplayName)
                }
                $m = "[OK] Đã xóa $($delNames.Count) GPO: " + ($delNames -join ', ')
                Write-Log $m "Green"; & $loadGpos; & $setDlgStat $m ([System.Drawing.Color]::ForestGreen)
                Update-OUList -Force
            }
            catch {
                $m = "[LỖI] Xóa GPO: " + $_.Exception.Message
                Write-Log $m "Red"; & $setDlgStat $m ([System.Drawing.Color]::Firebrick); Show-Msg $_.Exception.Message "Lỗi xóa GPO" "Error"
            }
            finally { $dlg.UseWaitCursor = $false }
        })

        $gpoDlgCtx.Add_Opening({
            param($cs, $ce)
            $cs.Items.Clear()
            if ($lv.SelectedItems.Count -eq 0 -and $lv.CheckedItems.Count -eq 0) { $ce.Cancel = $true; return }
            $miDelG = New-Object System.Windows.Forms.ToolStripMenuItem($(if ($lv.CheckedItems.Count -gt 1) { "Xóa $($lv.CheckedItems.Count) GPO đã tick (vĩnh viễn)" } else { "Xóa GPO này (vĩnh viễn)" }))
            $miDelG.ForeColor = [System.Drawing.Color]::Firebrick
            $miDelG.Tag = $btnDlgDel
            $miDelG.Add_Click({ $this.Tag.PerformClick() })
            $miUnlG = New-Object System.Windows.Forms.ToolStripMenuItem("Gỡ liên kết khỏi OU đang chọn")
            $miUnlG.Tag = $btnDlgUnlink
            $miUnlG.Add_Click({ $this.Tag.PerformClick() })
            $miLnkG = New-Object System.Windows.Forms.ToolStripMenuItem("Liên kết vào OU đang chọn")
            $miLnkG.Tag = $btnDlgLink
            $miLnkG.Add_Click({ $this.Tag.PerformClick() })
            $miRefG = New-Object System.Windows.Forms.ToolStripMenuItem("Làm mới danh sách")
            $miRefG.Tag = $btnDlgRef
            $miRefG.Add_Click({ $this.Tag.PerformClick() })
            [void]$cs.Items.AddRange(@($miDelG, (New-Object System.Windows.Forms.ToolStripSeparator), $miUnlG, $miLnkG, (New-Object System.Windows.Forms.ToolStripSeparator), $miRefG))
        })

        $btnDlgUnlink.Tag = 'Danger'
        $btnDlgDel.Tag    = 'Danger'
        $btnDlgSetStat.Tag = 'Primary'
        if (Get-Command Set-ModernButtons -ErrorAction SilentlyContinue) { Set-ModernButtons $dlg }
        & $loadGpos
        [void]$dlg.ShowDialog($form)
    }
    finally {
        $dlg.Dispose()
        $script:Working = $prevWorkMgr
        Update-OUList -Force
    }
})

$cboLibTarget.Add_SelectedIndexChanged({
    if ($script:Sync) { return }
    $script:Sync = $true; Set-TreeSelectionFromCombo; $script:Sync = $false
})

$lvLib.Add_ItemCheck({
    $li = $lvLib.Items[$_.Index]
    if ($li.Tag.Kind -eq 'Manual' -and $_.NewValue -eq [System.Windows.Forms.CheckState]::Checked) {
        $_.NewValue = [System.Windows.Forms.CheckState]::Unchecked
        $lblLibDesc.ForeColor = [System.Drawing.Color]::Firebrick
        $lblLibDesc.Text = "[EN] $($li.Tag.NameEn)  |  [VI] $($li.Tag.Name)`r`nChưa tạo tự động — Làm thủ công: " + $li.Tag.Hint
    }
})
$lvLib.Add_ItemChecked({ $lblLibCount.Text = "Đã chọn: " + $lvLib.CheckedItems.Count })
$lvLib.Add_SelectedIndexChanged({
    if ($lvLib.SelectedItems.Count -eq 0) { return }
    Update-LibDescLabel $lvLib.SelectedItems[0].Tag
})

function Build-LibContextMenu {
    param($ListItem)
    $libCtx.Items.Clear()
    if ($null -eq $ListItem -or $null -eq $ListItem.Tag) { return }
    $it = $ListItem.Tag
    $idKey = [string]$it.Id

    if ($it.Params -and $it.Params.Count -gt 0) {
        $miEdit = New-Object System.Windows.Forms.ToolStripMenuItem ("Tùy chỉnh số / tham số... (Mục {0:00})" -f $it.Id)
        $miEdit.Font = New-Object System.Drawing.Font($libCtx.Font, [System.Drawing.FontStyle]::Bold)
        $miEdit.Tag = $ListItem
        $miEdit.Add_Click({
            $row = $this.Tag
            if ($null -eq $row -or $null -eq $row.Tag) { return }
            $item = $row.Tag
            $res = Show-ParamDialog @($item) ("Tùy chỉnh tham số — {0:00}. {1}" -f $item.Id, $item.NameEn)
            if ($null -ne $res -and $res.ContainsKey([string]$item.Id)) {
                $script:LibCustomParams[[string]$item.Id] = $res[[string]$item.Id]
                $row.Selected = $true
                Update-LibListRow $row
                Update-LibDescLabel $item
                Write-Log ("[INFO] Đã tùy chỉnh tham số mục {0:00} ({1}): {2}" -f $item.Id, $item.NameEn, (Format-LibItemSubtitle $item)) "Blue"
            }
        })
        [void]$libCtx.Items.Add($miEdit)

        $miResetOne = New-Object System.Windows.Forms.ToolStripMenuItem "Đặt lại số mặc định"
        $miResetOne.Enabled = $script:LibCustomParams.ContainsKey($idKey)
        $miResetOne.Tag = $ListItem
        $miResetOne.Add_Click({
            $row = $this.Tag
            if ($null -eq $row -or $null -eq $row.Tag) { return }
            $item = $row.Tag
            [void]$script:LibCustomParams.Remove([string]$item.Id)
            $row.Selected = $true
            Update-LibListRow $row
            Update-LibDescLabel $item
            Write-Log ("[INFO] Đã đặt lại tham số mặc định cho mục {0:00} ({1})." -f $item.Id, $item.NameEn) "DarkOrange"
        })
        [void]$libCtx.Items.Add($miResetOne)
        [void]$libCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    }
    elseif ($it.Kind -eq 'Manual') {
        $miHint = New-Object System.Windows.Forms.ToolStripMenuItem "Xem hướng dẫn làm thủ công (GPMC)..."
        $miHint.Tag = $it
        $miHint.Add_Click({
            $item = $this.Tag
            if ($null -eq $item) { return }
            Show-Msg ("[EN] $($item.NameEn)`r`n[VI] $($item.Name)`r`n`r`nHướng dẫn làm thủ công:`r`n$($item.Hint)") "Hướng dẫn cấu hình thủ công" "Information"
        })
        [void]$libCtx.Items.Add($miHint)
    }
    else {
        $miNone = New-Object System.Windows.Forms.ToolStripMenuItem "(Mục này không có số/tham số cần tùy chỉnh)"
        $miNone.Enabled = $false
        [void]$libCtx.Items.Add($miNone)
        [void]$libCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    }

    if ($it.Kind -ne 'Manual') {
        $chkTxt = if ($ListItem.Checked) { "Bỏ tick chọn mục này" } else { "Tick chọn mục này" }
        $miChk = New-Object System.Windows.Forms.ToolStripMenuItem $chkTxt
        $miChk.Tag = $ListItem
        $miChk.Add_Click({
            $row = $this.Tag
            if ($null -ne $row) { $row.Checked = (-not $row.Checked) }
        })
        [void]$libCtx.Items.Add($miChk)
    }

    if ($script:LibCustomParams.Count -gt 0) {
        [void]$libCtx.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        $miResetAll = New-Object System.Windows.Forms.ToolStripMenuItem ("Đặt lại tất cả tham số đã chỉnh (" + $script:LibCustomParams.Count + ")")
        $miResetAll.Add_Click({
            $script:LibCustomParams.Clear()
            foreach ($row in $lvLib.Items) {
                if ($row.Tag.Params) { Update-LibListRow $row }
            }
            if ($lvLib.SelectedItems.Count -gt 0) { Update-LibDescLabel $lvLib.SelectedItems[0].Tag }
            Write-Log "[INFO] Đã đặt lại toàn bộ tham số tùy chỉnh trong Thư viện GPO về mặc định." "DarkOrange"
        })
        [void]$libCtx.Items.Add($miResetAll)
    }
}

$lvLib.Add_MouseDown({
    if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Right) {
        $hit = $lvLib.HitTest($_.Location)
        if ($hit -and $hit.Item) {
            $lvLib.SelectedItems.Clear()
            $hit.Item.Selected = $true
            $hit.Item.Focused = $true
        }
        else {
            $lvLib.SelectedItems.Clear()
        }
    }
})

$libCtx.Add_Opening({
    if ($lvLib.SelectedItems.Count -eq 0) { $_.Cancel = $true; return }
    Build-LibContextMenu $lvLib.SelectedItems[0]
})

$rdoLibSep.Add_CheckedChanged({
    $txtLibPrefix.Enabled  = $rdoLibSep.Checked
    $txtLibGpoName.Enabled = $rdoLibOne.Checked
})
$rdoLibOne.Add_CheckedChanged({
    $txtLibPrefix.Enabled  = $rdoLibSep.Checked
    $txtLibGpoName.Enabled = $rdoLibOne.Checked
})

$btnLibNone.Add_Click({ foreach ($li in $lvLib.Items) { $li.Checked = $false } })
$btnLibAll.Add_Click({ foreach ($li in $lvLib.Items) { if ($li.Tag.Kind -eq 'Gpo') { $li.Checked = $true } } })
$btnLibSafe.Add_Click({
    $ids = 5, 6, 7, 9, 13, 17, 27, 33, 46
    foreach ($li in $lvLib.Items) { $li.Checked = ($ids -contains [int]$li.Tag.Id) }
})

$btnLibCreate.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        $sel = @()
        foreach ($li in $lvLib.CheckedItems) { $sel += , $li.Tag }
        if ($sel.Count -eq 0) { Show-Msg "Bạn chưa tick mục nào trong danh sách." "Chưa chọn" "Warning"; return }

        $gpoItems = @($sel | Where-Object { $_.Kind -eq 'Gpo' })
        $domItems = @($sel | Where-Object { $_.Kind -eq 'Domain' })
        $combine  = $rdoLibOne.Checked
        if ($gpoItems.Count -gt 0 -and ($cboLibTarget.SelectedIndex -lt 0 -or $cboLibTarget.SelectedIndex -ge $script:OUDN.Count)) {
            Show-Msg "Chưa chọn OU đích." "Chưa hợp lệ" "Warning"; return
        }
        $target   = if ($cboLibTarget.SelectedIndex -ge 0) { $script:OUDN[$cboLibTarget.SelectedIndex] } else { $script:DomainDN }
        $libScopeIdx  = $cboLibScopeType.SelectedIndex
        $libScopeKind = if ($libScopeIdx -eq 1) { 'Group' } elseif ($libScopeIdx -eq 2) { 'User' } else { 'OU' }
        $libScopeObj  = $txtLibScopeTarget.Text.Trim()
        $libScopeSam  = $libScopeObj
        $libSkipMach  = $false
        if ($gpoItems.Count -gt 0) {
            $hasM = @($gpoItems | Where-Object { $_.Scope -in @('M', 'B') }).Count -gt 0
            $hasU = @($gpoItems | Where-Object { $_.Scope -in @('U', 'B') }).Count -gt 0
            $libScopeRes = Test-GpoScopeTarget $libScopeKind $libScopeObj $hasM $hasU
            if (-not $libScopeRes.Ok) { return }
            if ($libScopeRes.Sam) { $libScopeSam = $libScopeRes.Sam }
            $libSkipMach = [bool]$libScopeRes.SkipMachine
            if ($libSkipMach) {
                $gpoItems = @($gpoItems | Where-Object { $_.Scope -ne 'M' })
            }
            if ($gpoItems.Count -eq 0 -and $domItems.Count -eq 0) {
                Show-Msg "Không còn mục GPO User nào sau khi bỏ qua các mục Computer." "Không có mục áp dụng" "Warning"; return
            }
            if ($combine -and $gpoItems.Count -gt 0) {
                $nm = $txtLibGpoName.Text.Trim()
                if (-not $nm -or $nm -match '[\\/:*?"<>|]') { Show-Msg "Tên GPO chưa hợp lệ." "Chưa hợp lệ" "Warning"; return }
                if (Get-GPO -Name $nm -ErrorAction SilentlyContinue) { Show-Msg "Đã có GPO tên '$nm'. Hãy đặt tên khác." "Trùng tên" "Warning"; return }
            }
            elseif ($gpoItems.Count -gt 0 -and $txtLibPrefix.Text -match '[\\/:*?"<>|]') { Show-Msg "Tiền tố tên GPO chứa ký tự không hợp lệ." "Chưa hợp lệ" "Warning"; return }
        }

        $allSelected = @($domItems) + @($gpoItems)
        $needPrompt = @($allSelected | Where-Object { $_.Params -and -not $script:LibCustomParams.ContainsKey([string]$_.Id) })
        if ($needPrompt.Count -gt 0) {
            $entered = Show-ParamDialog $needPrompt
            if ($null -eq $entered) { return }
            foreach ($k in $entered.Keys) { $script:LibCustomParams[$k] = $entered[$k] }
            foreach ($row in $lvLib.Items) {
                if ($entered.ContainsKey([string]$row.Tag.Id)) { Update-LibListRow $row }
            }
        }
        $params = @{}
        foreach ($it in $allSelected) {
            if ($it.Params) { $params[[string]$it.Id] = Get-LibItemParams $it }
        }

        # ----- Chạy thử / Xác nhận -----
        $libDomRootWarn = if ($gpoItems.Count -gt 0 -and $chkLibLink.Checked -and $target -ieq $script:DomainDN) { "`r`n⚠ CẢNH BÁO: Đang liên kết vào GỐC DOMAIN (áp dụng toàn bộ domain, kể cả Admin & DC)." } else { "" }
        $msg = if ($gpoItems.Count -gt 0) {
            "Sẽ tạo " + $(if ($combine) { "1 GPO gộp" } else { [string]$gpoItems.Count + " GPO riêng" }) + " (" + $gpoItems.Count + " mục)."
        } else {
            "Sẽ cập nhật chính sách mức domain (" + $domItems.Count + " mục)."
        }
        if ($chkLibLink.Checked -and $gpoItems.Count -gt 0) { $msg += "`r`nLiên kết vào: " + $target }
        if ($libScopeKind -ne 'OU' -and $gpoItems.Count -gt 0) { $msg += "`r`nChỉ áp dụng cho ${libScopeKind}: " + $libScopeSam }
        if ($domItems.Count -gt 0) { $msg += "`r`n`r`nCÓ " + $domItems.Count + " mục MỨC DOMAIN: sẽ đổi chính sách mật khẩu/khóa tài khoản của TOÀN BỘ domain." }
        $msg += $libDomRootWarn

        $mode = Resolve-DryRunBeforeCreate $msg
        if ($mode -eq "dry") {
            foreach ($it in $gpoItems) {
                $subTxt = Format-LibItemSubtitle $it
                $n = @(& $it.Build $params[[string]$it.Id] | Where-Object { -not $libSkipMach -or $_.Key -notlike 'HKLM\*' }).Count
                if ($combine) { Write-Log ("[CHẠY THỬ] Thêm vào GPO '" + $txtLibGpoName.Text.Trim() + "': " + $it.NameEn + " — " + $subTxt + " (" + $n + " giá trị)") "Blue" }
                else {
                    $gNm = Get-LibGpoName $it
                    $dup = if (Get-GPO -Name $gNm -ErrorAction SilentlyContinue) { "  (đã tồn tại -> sẽ bỏ qua)" } else { "" }
                    Write-Log ("[CHẠY THỬ] Sẽ tạo GPO '" + $gNm + "': " + $it.NameEn + " — " + $subTxt + " (" + $n + " giá trị)" + $dup) "Blue"
                }
            }
            foreach ($it in $domItems) { Write-Log ("[CHẠY THỬ] Sẽ đổi chính sách mức domain: " + $it.NameEn + " — " + (Format-LibItemSubtitle $it)) "Blue" }
            if ($chkLibLink.Checked -and $gpoItems.Count -gt 0) { Write-Log ("[CHẠY THỬ] Sẽ liên kết vào: " + $target) "Blue" }
            if ($libScopeKind -ne 'OU' -and $gpoItems.Count -gt 0) { Write-Log ("[CHẠY THỬ] Lọc bảo mật: chỉ áp dụng cho " + $libScopeKind + " '" + $libScopeSam + "'") "Blue" }
            return
        }

        if ($mode -eq "live" -or $domItems.Count -gt 0) {
            if (-not (Confirm-Msg ($msg + "`r`n`r`nTiếp tục?"))) { return }
        }

        $libCnt = @{ ok = 0; skip = 0; fail = 0 }

        Invoke-WithBusy {
            # ----- Mục mức domain -----
            foreach ($it in $domItems) {
                $subTxt = Format-LibItemSubtitle $it
                try { Invoke-DomainItem $it $params[[string]$it.Id]; Write-Log ("[OK] Mức domain: " + $subTxt) "Green"; $libCnt.ok++ }
                catch { Write-Log ("[LỖI] " + $subTxt + " : " + $_.Exception.Message) "Red"; $libCnt.fail++ }
            }

            # ----- Mục GPO -----
            if ($gpoItems.Count -gt 0) {
                if ($combine) {
                    $nm = $txtLibGpoName.Text.Trim()
                    if (Get-GPO -Name $nm -ErrorAction SilentlyContinue) {
                        Write-Log "[BỎ QUA] Đã có GPO tên '$nm'." "DarkOrange"
                        $libCnt.skip++
                    }
                    else {
                        $gpoCreated = $false
                        $gpoAdded = 0
                        try {
                            New-GPO -Name $nm -Comment "Tạo bằng Jebtool" -ErrorAction Stop | Out-Null
                            $gpoCreated = $true
                            Write-Log "[OK] Đã tạo GPO: $nm" "Green"
                            foreach ($it in $gpoItems) {
                                $subTxt = Format-LibItemSubtitle $it
                                try { Invoke-GpoItem $nm $it $params[[string]$it.Id] -SkipMachine:$libSkipMach; Write-Log ("[OK]   + " + $subTxt) "Green"; $gpoAdded++ }
                                catch { Write-Log ("[LỖI]   " + $subTxt + " : " + $_.Exception.Message) "Red"; $libCnt.fail++ }
                            }
                            if ($gpoAdded -eq 0) { throw "Không ghi được chính sách nào vào GPO '$nm'." }
                            if ($libScopeKind -ne 'OU') {
                                Set-GpoScopeFilter $nm $libScopeKind $libScopeSam
                                Write-Log ("[OK]   Đã lọc bảo mật: chỉ áp dụng cho " + $libScopeKind + " '" + $libScopeSam + "'") "Green"
                            }
                            if ($chkLibLink.Checked) {
                                New-GPLink -Name $nm -Target $target -LinkEnabled Yes -ErrorAction Stop | Out-Null
                                Write-Log "[OK]   Đã liên kết vào: $target" "Green"
                            }
                            $libCnt.ok += $gpoAdded
                        }
                        catch {
                            Write-Log ("[LỖI] " + $nm + " : " + $_.Exception.Message) "Red"
                            $libCnt.fail++
                            if ($gpoCreated) {
                                try { Remove-GPO -Name $nm -Confirm:$false -ErrorAction Stop; Write-Log ("      Đã dọn GPO lỗi: " + $nm) "DarkOrange" } catch {}
                            }
                        }
                    }
                }
                else {
                    foreach ($it in $gpoItems) {
                        $nm = Get-LibGpoName $it
                        $subTxt = Format-LibItemSubtitle $it
                        $gpoCreated = $false
                        try {
                            if (Get-GPO -Name $nm -ErrorAction SilentlyContinue) { Write-Log "[BỎ QUA] Đã có GPO: $nm" "DarkOrange"; $libCnt.skip++; continue }
                            New-GPO -Name $nm -Comment ("Jebtool: " + $it.NameEn + " — " + $subTxt) -ErrorAction Stop | Out-Null
                            $gpoCreated = $true
                            Invoke-GpoItem $nm $it $params[[string]$it.Id] -SkipMachine:$libSkipMach
                            if ($libScopeKind -ne 'OU') { Set-GpoScopeFilter $nm $libScopeKind $libScopeSam }
                            if ($chkLibLink.Checked) { New-GPLink -Name $nm -Target $target -LinkEnabled Yes -ErrorAction Stop | Out-Null }
                            Write-Log ("[OK] " + $nm + "  <-  " + $it.NameEn + " (" + $subTxt + ")") "Green"
                            $libCnt.ok++
                        }
                        catch {
                            Write-Log ("[LỖI] " + $nm + " : " + $_.Exception.Message) "Red"
                            $libCnt.fail++
                            if ($gpoCreated) {
                                try { Remove-GPO -Name $nm -Confirm:$false -ErrorAction Stop; Write-Log ("      Đã dọn GPO lỗi: " + $nm) "DarkOrange" } catch {}
                            }
                        }
                    }
                }
            }
        } "Đang tạo các GPO đã chọn..."
        $applyNote = if ($libCnt.ok -eq 0) { "" }
                     elseif ($gpoItems.Count -gt 0 -and -not $chkLibLink.Checked -and $domItems.Count -eq 0) { " (GPO CHƯA liên kết vào OU nào — vào 'Quản lý GPO...' để liên kết khi muốn áp dụng.)" }
                     else { " Máy trạm nhận chính sách sau ~90 phút hoặc chạy: gpupdate /force" }
        Write-Log ("Xong: thành công " + $libCnt.ok + ", bỏ qua " + $libCnt.skip + ", lỗi " + $libCnt.fail + "." + $applyNote) "Black"
        $script:Working = $false
        Update-OUList -Force
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

