        $dtp.Value = [datetime]::ParseExact(([string]$r).Trim(), 'yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture)
    }
    catch { $dtp.Value = Get-Date; Write-Log ("[LỖI] Không đọc được giờ máy đích: " + $_.Exception.Message) "Red" }
})
$btnAdmin.Add_Click({ Restart-AsAdmin })
