})

$btnSetTime.Add_Click({
    $iso  = $dtp.Value.ToString('o')
    $plan = "đặt giờ thành " + $dtp.Value.ToString('dd/MM/yyyy HH:mm:ss')
    if ($chkStopW32.Checked) { $plan += " và giữ giờ tay (tắt Windows Time + đồng bộ giờ máy ảo)" }
    $plan += ".`r`nLưu ý: máy trong domain lệch quá 5 phút so với Domain Controller sẽ lỗi đăng nhập (Kerberos)."
    Invoke-TimeAction "Đặt ngày giờ" $plan {
        param($iso, $stop, $off)
        if ($stop) { . ([scriptblock]::Create($off)) }
        $dt = [datetime]::Parse($iso, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind)
        Set-Date -Date $dt | Out-Null
        "Giờ mới: " + (Get-Date).ToString('dd/MM/yyyy HH:mm:ss')
    } @($iso, $chkStopW32.Checked, $script:TimeOffText)
})

function Invoke-TimeShift {
    param([int]$Sign)
    $n = [int]$numShift.Value * $Sign
    $mins = switch ($cboShiftUnit.SelectedIndex) { 0 { $n } 1 { $n * 60 } default { $n * 1440 } }
    $plan = $(if ($Sign -gt 0) { "cộng thêm " } else { "trừ bớt " }) + $numShift.Value + " " + [string]$cboShiftUnit.SelectedItem + " vào giờ hiện tại"
    if ($chkStopW32.Checked) { $plan += " và giữ giờ tay (tắt Windows Time + đồng bộ giờ máy ảo)" }
    $plan += ".`r`nLưu ý: máy trong domain lệch quá 5 phút so với Domain Controller sẽ lỗi đăng nhập (Kerberos)."
    Invoke-TimeAction "Chỉnh giờ nhanh" $plan {
        param($mins, $stop, $off)
        if ($stop) { . ([scriptblock]::Create($off)) }
        Set-Date -Adjust (New-TimeSpan -Minutes $mins) | Out-Null
        "Giờ mới: " + (Get-Date).ToString('dd/MM/yyyy HH:mm:ss')
    } @($mins, $chkStopW32.Checked, $script:TimeOffText)
}
$btnShiftPlus.Add_Click({ Invoke-TimeShift 1 })
$btnShiftMinus.Add_Click({ Invoke-TimeShift -1 })

$btnSyncRestore.Add_Click({
    Invoke-TimeAction "Bật lại tự đồng bộ giờ" "bật lại Windows Time (Automatic), đồng bộ giờ máy ảo, rồi đồng bộ lại giờ" {
        param($on)
        . ([scriptblock]::Create($on))
        @(& w32tm /resync /force 2>&1)
    } @($script:TimeOnText)
})

$btnSetTZ.Add_Click({
    if ($cboTZ.SelectedIndex -lt 0) { return }
    $id = $script:TZIds[$cboTZ.SelectedIndex]
    Invoke-TimeAction "Đổi múi giờ" ("đổi sang " + $cboTZ.SelectedItem) {
        param($id)
        & tzutil /s $id
        "Múi giờ hiện tại: " + (& tzutil /g)
    } @($id)
})

$btnSyncNTP.Add_Click({
    $srv = $txtNTP.Text.Trim()
    if (-not $srv -or $srv -notmatch '^[A-Za-z0-9\.\-_:]+$') { Show-Msg "Địa chỉ máy chủ NTP chưa hợp lệ." "Chưa hợp lệ" "Warning"; return }
    Invoke-TimeAction "Đồng bộ giờ với NTP" ("đồng bộ với " + $srv) {
        param($srv)
        Set-Service w32time -StartupType Automatic -ErrorAction SilentlyContinue
        Start-Service w32time -ErrorAction SilentlyContinue
        $o = @(& w32tm /config ("/manualpeerlist:" + $srv) /syncfromflags:manual /update 2>&1)
        $o += @(& w32tm /resync /force 2>&1)
        $o
    } @($srv)
})

$btnSyncDom.Add_Click({
    Invoke-TimeAction "Đồng bộ giờ theo domain" "đồng bộ lại theo Domain Controller" {
        Set-Service w32time -StartupType Automatic -ErrorAction SilentlyContinue
        Start-Service w32time -ErrorAction SilentlyContinue
        $o = @(& w32tm /config /syncfromflags:domhier /update 2>&1)
        $o += @(& w32tm /resync /force 2>&1)
        $o
    }
})

