    $script:UsrPwdFlagSync = $true
    try {
        if ($chkUsrChange.Checked) {
            $chkUsrNoForce.Checked = $false
            $chkUsrCannotChange.Checked = $false
            $chkUsrNever.Checked = $false
        } else {
            $chkUsrNoForce.Checked = $true
        }
    } finally { $script:UsrPwdFlagSync = $false }
})
$chkUsrNoForce.Add_CheckedChanged({
    if ($script:UsrPwdFlagSync) { return }
    $script:UsrPwdFlagSync = $true
    try {
        if ($chkUsrNoForce.Checked) {
            $chkUsrChange.Checked = $false
        } else {
            $chkUsrChange.Checked = $true
            $chkUsrCannotChange.Checked = $false
            $chkUsrNever.Checked = $false
        }
    } finally { $script:UsrPwdFlagSync = $false }
})
$chkUsrCannotChange.Add_CheckedChanged({
