$numUsrCount.Add_TextChanged({ Update-UsrButtonText; Update-UsrCheck })

$btnCreateGrp.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        if ($cboGrpOU.SelectedIndex -le 0 -or $cboGrpOU.SelectedIndex -ge $script:OUDN.Count) {
            Show-Msg "Hãy chọn một OU chứa group (không thể chọn gốc domain)." "Chưa hợp lệ" "Warning"; return
        }
        $path  = $script:OUDN[$cboGrpOU.SelectedIndex]
        $scope = @('Global', 'DomainLocal', 'Universal')[$cboGrpScope.SelectedIndex]
        $cat   = @('Security', 'Distribution')[$cboGrpCat.SelectedIndex]
        $name  = $txtGrpName.Text.Trim()
        $err = Test-SamName $name 64
        if (-not $err) { $err = Test-CnName $name }
        if ($err) { Show-Msg ("Tên Group chưa hợp lệ: " + $err) "Chưa hợp lệ" "Warning"; return }
        $mode = Resolve-DryRunBeforeCreate "Tạo group '$name' ($cat / $scope) trong: $path"
        if ($mode -eq "live") {
            if (-not (Confirm-Msg "Tạo group '$name' ($cat / $scope) trong:`r`n$path`r`n`r`nTiếp tục?")) { return }
        }
        $res = Invoke-WithBusy { New-OneGroup -Name $name -Path $path -Scope $scope -Cat $cat -Desc $txtGrpDesc.Text } "Đang tạo Group..."
        if ($res -eq "ok") { $txtGrpName.Clear(); $txtGrpDesc.Clear(); $script:Working = $false; Update-OUList -Force }
        elseif ($res -eq "fail" -and $script:LastCreateErr) { Show-Msg $script:LastCreateErr "Không tạo được Group" "Error" }
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

$btnDeleteGrp.Add_Click({
    if (-not $script:Ready) { return }
    $prefOU = if ($cboGrpOU.SelectedIndex -gt 0 -and $cboGrpOU.SelectedIndex -lt $script:OUDN.Count) { $script:OUDN[$cboGrpOU.SelectedIndex] } else { "" }
    $raw = $txtGrpName.Text.Trim()
    if ($raw) {
        $ids = @($raw -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
        if (Invoke-DeleteADGroup $ids $prefOU) { $txtGrpName.Clear(); $txtGrpDesc.Clear(); Update-GrpCheck }
        return
    }
    if ($tree.SelectedNode -and ([string]$tree.SelectedNode.Tag) -like "GR:*") {
        $gdn = ([string]$tree.SelectedNode.Tag).Substring(3)
        if (Invoke-DeleteADGroup @($gdn) $prefOU) { $txtGrpName.Clear(); $txtGrpDesc.Clear(); Update-GrpCheck }
        return
    }
    if ($prefOU -and -not (Test-IsDomainControllersOU $prefOU)) {
        try {
            $ouGrps = @(Get-ADGroup -SearchBase $prefOU -SearchScope OneLevel -Filter * -ErrorAction Stop)
            if ($ouGrps.Count -gt 0) {
                $dns = @($ouGrps | ForEach-Object { $_.DistinguishedName })
                if (Invoke-DeleteADGroup $dns $prefOU) { $txtGrpName.Clear(); $txtGrpDesc.Clear(); Update-GrpCheck }
                return
            }
            Show-Msg "OU '$prefOU' không có Group nào. Hãy nhập tên Group cần xóa (nhiều Group cách nhau dấu ;)." "OU không có Group" "Information"
            return
        }
        catch { Show-Msg $_.Exception.Message "Lỗi đọc Group" "Error"; return }
    }
    Show-Msg "Nhập tên Group cần xóa (hoặc chọn một OU có Group / bấm phải vào Group trên sơ đồ cây)." "Chưa hợp lệ" "Warning"
})

$btnGrpSample.Add_Click({
    try {
        $dlg = New-Object System.Windows.Forms.SaveFileDialog
        $dlg.Filter = "File CSV (*.csv)|*.csv"; $dlg.FileName = "group_list.csv"
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $dn = $script:DomainDN
        $lines = @(
            "Name,Path,Scope,Category,Description",
            "GG_KeToan,""OU=KeToan,$dn"",Global,Security,Nhóm nhân viên kế toán",
            "DL_Share_KeToan_RW,""OU=KeToan,$dn"",DomainLocal,Security,Quyền ghi thư mục kế toán"
        )
        Set-Content -Path $dlg.FileName -Value $lines -Encoding UTF8
        Write-Log "Đã lưu file mẫu: $($dlg.FileName)" "Green"
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red" }
})

$btnGrpCsv.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        $dlg = New-Object System.Windows.Forms.OpenFileDialog
        $dlg.Filter = "File CSV (*.csv)|*.csv"
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $rows = @(Import-Csv -Path $dlg.FileName -Encoding UTF8)
        if ($rows.Count -eq 0 -or -not ($rows[0].PSObject.Properties.Name -contains 'Name')) {
            Show-Msg "File CSV phải có dòng đầu là:  Name,Path,Scope,Category,Description`r`nBấm 'Lưu CSV mẫu' để lấy file mẫu." "File CSV chưa đúng" "Warning"; return
        }
        if (-not $chkDry.Checked) {
            if (-not (Confirm-Msg ("File CSV có " + $rows.Count + " dòng. Tạo group?`r`n(Dòng nào đã có sẽ bị bỏ qua.)"))) { return }
        }
        $count = @{ ok = 0; skip = 0; fail = 0; dry = 0 }
        Invoke-WithBusy {
            foreach ($r in $rows) {
                $pth = [string]$r.Path
                if ([string]::IsNullOrWhiteSpace($pth)) {
                    if ($cboGrpOU.SelectedIndex -le 0) { Write-Log "[LỖI] Group '$($r.Name)': chưa chỉ định OU đích (không thể tạo ở gốc domain)." "Red"; $count.fail++; continue }
                    $pth = $script:OUDN[$cboGrpOU.SelectedIndex]
                }
                $sc = ([string]$r.Scope).Trim(); if ($sc -notin @('Global', 'DomainLocal', 'Universal')) { $sc = 'Global' }
                $ct = ([string]$r.Category).Trim(); if ($ct -notin @('Security', 'Distribution')) { $ct = 'Security' }
                $res = New-OneGroup -Name ([string]$r.Name).Trim() -Path $pth.Trim() -Scope $sc -Cat $ct -Desc $r.Description
                $count[$res]++
            }
        } "Đang tạo danh sách Group từ CSV..."
        Write-Log ("Xong: tạo " + $count.ok + ", bỏ qua " + $count.skip + ", lỗi " + $count.fail + ", chạy thử " + $count.dry) "Black"
        $script:Working = $false
        Update-OUList -Force
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

$btnCreateUsr.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        if ($cboUsrOU.SelectedIndex -le 0 -or $cboUsrOU.SelectedIndex -ge $script:OUDN.Count) {
            Show-Msg "Hãy chọn một OU chứa user (không thể chọn gốc domain)." "Chưa hợp lệ" "Warning"; return
        }
        $path = $script:OUDN[$cboUsrOU.SelectedIndex]
        $name = $txtUsrName.Text.Trim(); $sam = $txtUsrSam.Text.Trim()
        $err = Test-CnName $name
        if (-not $err) { $err = Test-SamName $sam 20 }
        if ($err) { Show-Msg $err "Chưa hợp lệ" "Warning"; return }
        if ([string]::IsNullOrEmpty($txtUsrPwd.Text)) { Show-Msg "Bạn chưa nhập mật khẩu cho User." "Chưa hợp lệ" "Warning"; return }
        $cnt = Get-DesiredUsrCount

        if ($cnt -le 1) {
            $mode = Resolve-DryRunBeforeCreate "Tạo user '$name' ($sam) trong: $path"
            if ($mode -eq "live") {
                if (-not (Confirm-Msg "Tạo user '$name' ($sam) trong:`r`n$path`r`n`r`nTiếp tục?")) { return }
            }
            $res = Invoke-WithBusy { New-OneUser -FullName $name -Sam $sam -Pwd $txtUsrPwd.Text -Path $path -Desc $txtUsrDesc.Text `
                -Change $chkUsrChange.Checked -Never $chkUsrNever.Checked -Enabled $chkUsrEnable.Checked -Groups $txtUsrGroups.Text -CannotChange $chkUsrCannotChange.Checked } "Đang tạo User..."
            if ($res -eq "ok") {
                $script:SamTouched = $false
                $txtUsrName.Clear(); $txtUsrSam.Clear(); $txtUsrPwd.Clear(); $txtUsrDesc.Clear()
                $script:Working = $false; Update-OUList -Force
            }
            elseif ($res -eq "fail" -and $script:LastCreateErr) { Show-Msg $script:LastCreateErr "Không tạo được User" "Error" }
            return
        }

        $chg = $chkUsrChange.Checked; $nev = $chkUsrNever.Checked; $ena = $chkUsrEnable.Checked; $noChg = $chkUsrCannotChange.Checked
        if ($chg -and $nev) { Show-Msg "Không thể vừa bắt đổi mật khẩu vừa đặt không hết hạn." "Chưa hợp lệ" "Warning"; return }
        if ($chg -and $noChg) { Show-Msg "Không thể vừa bắt đổi mật khẩu vừa không cho user tự đổi mật khẩu." "Chưa hợp lệ" "Warning"; return }
        $grpRaw = $txtUsrGroups.Text.Trim()
        $gl = @($grpRaw -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
        $unknown = @($gl | Where-Object { -not $script:GroupSAM.ContainsKey($_.ToLower()) })
        if ($unknown.Count -gt 0) {
            Show-Msg ("Không tìm thấy group trong AD: " + ($unknown -join ', ')) "Không tìm thấy group" "Warning"; return
        }

        $plan = Get-UserBatchPlan $name $sam $path $cnt
        if (-not $plan.Ok) { Show-Msg $plan.Err "Không lập được danh sách" "Warning"; return }

        $rangeSummary = "$($plan.First.Name) ($($plan.First.Sam)) -> $($plan.Last.Name) ($($plan.Last.Sam))"
        $grpInfo = if ($gl.Count -gt 0) { "`r`nThêm vào group: $($gl -join ', ')" } else { "" }
        $mode = Resolve-DryRunBeforeCreate "Tạo hàng loạt $cnt user ($rangeSummary) trong: $path"
        if ($mode -eq "live") {
            if (-not (Confirm-Msg "Tạo hàng loạt $cnt user:`r`n$rangeSummary`r`ntrong OU: $path$grpInfo`r`n`r`nTiếp tục?")) { return }
        }
        elseif ($mode -eq "dry") {
            $previewN = [Math]::Min(5, $plan.Items.Count)
            for ($i = 0; $i -lt $previewN; $i++) {
                $it = $plan.Items[$i]
                Write-Log "[CHẠY THỬ] Sẽ tạo user: $($it.Name) ($($it.Sam)) trong $path" "Blue"
            }
            if ($plan.Items.Count -gt 6) {
                Write-Log ("[CHẠY THỬ] ... (và $($plan.Items.Count - 6) user ở giữa tới trước $($plan.Last.Name)) ...") "Blue"
            }
            if ($plan.Items.Count -gt 5) {
                Write-Log "[CHẠY THỬ] Sẽ tạo user: $($plan.Last.Name) ($($plan.Last.Sam)) trong $path" "Blue"
            }
            Write-Log ("[CHẠY THỬ] Tổng cộng sẽ tạo $cnt user: $rangeSummary" + $(if ($plan.Skipped -gt 0) { " (đã tự động bỏ qua $($plan.Skipped) tên trùng trước đó)" } else { "" })) "Blue"
            return
        }

        $pwPlain = $txtUsrPwd.Text
        $descTxt = $txtUsrDesc.Text
        $batchRes = Invoke-WithBusy {
            Get-ADObject -Identity $path -ErrorAction Stop | Out-Null
            $secPwd = ConvertTo-SecureString $pwPlain -AsPlainText -Force
            $okCnt = 0; $failCnt = 0; $abortMsg = ""
            $createdDns = New-Object 'System.Collections.Generic.List[string]'
            $total = $plan.Items.Count
            for ($i = 0; $i -lt $total; $i++) {
                $it = $plan.Items[$i]
                if (($i % 10) -eq 0 -or $i -eq ($total - 1)) {
                    $lblStatus.Text = "Đang tạo user $($i + 1)/$total ($($it.Sam))..."
                    $lblStatus.Refresh()
                }
                try {
                    $parts = @($it.Name -split '\s+' | Where-Object { $_ })
                    $p = @{
                        Name = $it.Name; DisplayName = $it.Name; SamAccountName = $it.Sam
                        UserPrincipalName = ($it.Sam + '@' + $script:DomainName); Path = $path
                        AccountPassword = $secPwd
                        Enabled = $ena; ChangePasswordAtLogon = $chg; PasswordNeverExpires = $nev; CannotChangePassword = $noChg
                        PassThru = $true; ErrorAction = 'Stop'
                    }
                    if ($parts.Count -ge 2) { $p.GivenName = $parts[$parts.Count - 1]; $p.Surname = ($parts[0..($parts.Count - 2)] -join ' ') }
                    if (-not [string]::IsNullOrWhiteSpace($descTxt)) { $p.Description = $descTxt }
                    $u = New-ADUser @p
                    $dnLow = $u.DistinguishedName.ToLower()
                    $script:Created[$dnLow] = $true
                    $script:AllDN[$dnLow]   = $true
                    $script:UserSAM[$it.Sam.ToLower()] = $true
                    $createdDns.Add($u.DistinguishedName)
                    $okCnt++
                }
                catch {
                    $failCnt++
                    $m = $_.Exception.Message
                    if ($m -match '(?i)password|mật khẩu') { $m += "  -> Mật khẩu chưa đạt chính sách mật khẩu của domain (độ dài/độ phức tạp)." }
                    Write-Log ("[LỖI] User '$($it.Name)' ($($it.Sam)): $m") "Red"
                    if ($okCnt -eq 0 -and $m -match '(?i)password|mật khẩu') {
                        $abortMsg = "User '$($it.Name)': $m"
                        break
                    }
                }
            }
            if ($createdDns.Count -gt 0 -and $gl.Count -gt 0) {
                $dnArr = $createdDns.ToArray()
                foreach ($gn in $gl) {
                    $lblStatus.Text = "Đang thêm $($dnArr.Count) user vào group '$gn'..."
                    $lblStatus.Refresh()
                    for ($off = 0; $off -lt $dnArr.Count; $off += 100) {
                        $end = [Math]::Min($off + 99, $dnArr.Count - 1)
                        $chunk = [string[]]$dnArr[$off..$end]
                        try {
                            Add-ADGroupMember -Identity $gn -Members $chunk -ErrorAction Stop
                        }
                        catch {
                            foreach ($oneDn in $chunk) {
                                try { Add-ADGroupMember -Identity $gn -Members $oneDn -ErrorAction Stop }
                                catch { Write-Log ("      [LỖI] Thêm vào group '$gn' ($oneDn): " + $_.Exception.Message) "Red" }
                            }
                        }
                    }
                }
            }
            @{ Ok = $okCnt; Fail = $failCnt; Abort = $abortMsg }
        } "Đang tạo $cnt User trên Active Directory..."

        if ($batchRes.Ok -gt 0) {
            Write-Log ("[OK] Hoàn tất tạo hàng loạt: thành công $($batchRes.Ok)/$cnt, lỗi $($batchRes.Fail) ($rangeSummary)" + $(if ($gl.Count -gt 0) { " | Group: $($gl -join ', ')" } else { "" })) "Green"
            $script:SamTouched = $false
            $txtUsrName.Clear(); $txtUsrSam.Clear(); $txtUsrPwd.Clear(); $txtUsrDesc.Clear()
            $numUsrCount.Value = 1
            $script:Working = $false; Update-OUList -Force
        }
        elseif ($batchRes.Abort) {
            Show-Msg $batchRes.Abort "Không tạo được User" "Error"
        }
        else {
            Show-Msg "Tạo hàng loạt thất bại ($($batchRes.Fail)/$cnt lỗi). Xem chi tiết ở nhật ký bên dưới." "Không tạo được User" "Error"
        }
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

$btnDeleteUsr.Add_Click({
    if (-not $script:Ready) { return }
    $path = if ($cboUsrOU.SelectedIndex -ge 0 -and $cboUsrOU.SelectedIndex -lt $script:OUDN.Count) { $script:OUDN[$cboUsrOU.SelectedIndex] } else { $script:DomainDN }
    $cnt  = Get-DesiredUsrCount
    $nm   = $txtUsrName.Text.Trim()
    $sam  = $txtUsrSam.Text.Trim()
    if (Invoke-DeleteADUsers $nm $sam $path $cnt) {
        $script:SamTouched = $false
        $txtUsrName.Clear(); $txtUsrSam.Clear(); $txtUsrDesc.Clear()
        Update-UsrCheck
    }
})

$btnUsrSample.Add_Click({
    try {
        $dlg = New-Object System.Windows.Forms.SaveFileDialog
        $dlg.Filter = "File CSV (*.csv)|*.csv"; $dlg.FileName = "user_list.csv"
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $dn = $script:DomainDN
        $lines = @(
            "Name,SamAccountName,Password,Path,Groups,Description",
            "Nguyễn Văn An,an.nv,P@ssw0rd2026!,""OU=KeToan,$dn"",GG_KeToan,Kế toán viên",
            "Trần Thị Bình,binh.tt,,""OU=KeToan,$dn"",GG_KeToan;GG_All,Để trống mật khẩu = dùng mật khẩu nhập ở form"
        )
        Set-Content -Path $dlg.FileName -Value $lines -Encoding UTF8
        Write-Log "Đã lưu file mẫu: $($dlg.FileName)" "Green"
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red" }
})

$btnUsrCsv.Add_Click({
    $script:Working = $false
    Update-OUList
    $script:Working = $true
    try {
        $dlg = New-Object System.Windows.Forms.OpenFileDialog
        $dlg.Filter = "File CSV (*.csv)|*.csv"
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $rows = @(Import-Csv -Path $dlg.FileName -Encoding UTF8)
        if ($rows.Count -eq 0 -or -not ($rows[0].PSObject.Properties.Name -contains 'Name') -or -not ($rows[0].PSObject.Properties.Name -contains 'SamAccountName')) {
            Show-Msg "File CSV phải có dòng đầu là:  Name,SamAccountName,Password,Path,Groups,Description`r`nBấm 'Lưu CSV mẫu' để lấy file mẫu." "File CSV chưa đúng" "Warning"; return
        }
        if (-not $chkDry.Checked) {
            if (-not (Confirm-Msg ("File CSV có " + $rows.Count + " dòng. Tạo user?`r`n(Dòng nào đã có sẽ bị bỏ qua. Mật khẩu để trống = dùng mật khẩu ở ô Mật khẩu.)"))) { return }
        }
        $count = @{ ok = 0; skip = 0; fail = 0; dry = 0 }
        Invoke-WithBusy {
            foreach ($r in $rows) {
                $pth = [string]$r.Path
                if ([string]::IsNullOrWhiteSpace($pth)) {
                    if ($cboUsrOU.SelectedIndex -le 0) { Write-Log "[LỖI] User '$($r.Name)': chưa chỉ định OU đích (không thể tạo ở gốc domain)." "Red"; $count.fail++; continue }
                    $pth = $script:OUDN[$cboUsrOU.SelectedIndex]
                }
                $pw  = [string]$r.Password; if ([string]::IsNullOrEmpty($pw)) { $pw = $txtUsrPwd.Text }
                $res = New-OneUser -FullName ([string]$r.Name).Trim() -Sam ([string]$r.SamAccountName).Trim() -Pwd $pw -Path $pth.Trim() -Desc $r.Description `
                    -Change $chkUsrChange.Checked -Never $chkUsrNever.Checked -Enabled $chkUsrEnable.Checked -Groups $r.Groups -CannotChange $chkUsrCannotChange.Checked
                $count[$res]++
            }
        } "Đang tạo danh sách User từ CSV..."
        Write-Log ("Xong: tạo " + $count.ok + ", bỏ qua " + $count.skip + ", lỗi " + $count.fail + ", chạy thử " + $count.dry) "Black"
        $script:Working = $false
        Update-OUList -Force
    }
    catch { Write-Log ("[LỖI] " + $_.Exception.Message) "Red"; Show-Msg $_.Exception.Message "Có lỗi" "Error" }
    finally { $script:Working = $false }
})

# ---------- Quota ----------
function Update-QuotaCreateButtonText {
    if (-not $btnGCreate -or -not $cboQuotaScopeType) { return }
    $isDry = ($chkDry -and $chkDry.Checked)
    if ($cboQuotaScopeType.SelectedIndex -eq 2) {
        $btnGCreate.Text = if ($isDry) { "Đặt Quota User (Thử)" } else { "Đặt Quota User" }
    }
    else {
        $btnGCreate.Text = if ($isDry) { "Tạo GPO quota (Thử)" } else { "Tạo GPO quota" }
    }
}

$cboQuotaTarget.Add_SelectedIndexChanged({
    if ($script:Sync) { return }
    $script:Sync = $true; Set-TreeSelectionFromCombo; $script:Sync = $false
})
$cboQuotaScopeType.Add_SelectedIndexChanged({
    $idx = $cboQuotaScopeType.SelectedIndex
    $txtQuotaScopeTarget.Enabled = ($idx -gt 0)
    $txtGName.Enabled = ($idx -ne 2)
    Update-QuotaCreateButtonText
})
$chkQWarn.Add_CheckedChanged({ $numQWarn.Enabled = $chkQWarn.Checked })

$btnQCreate.Add_Click({
    $path = $txtQPath.Text.Trim()
    if (-not $path -or $path -notmatch '^[A-Za-z]:\\') { Show-Msg "Đường dẫn thư mục phải bắt đầu bằng ổ đĩa (vd: D:\Shares)." "Chưa hợp lệ" "Warning"; return }
    $unit = [string]$cboQUnit.SelectedItem
    $size = [int64]$numQSize.Value * (Get-UnitBytes $unit)
    $soft = $rdoQSoft.Checked
    $warn = if ($chkQWarn.Checked) { [int]$numQWarn.Value } else { 0 }
    $auto = $chkQAuto.Checked
    $plan = "giới hạn " + $numQSize.Value + " " + $unit + " cho " + $path + $(if ($soft) { " (mềm)" } else { " (cứng)" })
    if ($warn -gt 0) { $plan += ", cảnh báo ở " + $warn + "%" }
    if ($auto) { $plan += ", áp riêng từng thư mục con (dùng Template)" }
    $plan += ". Tự cài vai trò FSRM nếu chưa có."
    [void](Invoke-PCAction $txtQSrv.Text "Tạo/cập nhật quota thư mục" $plan {
        param($path, $size, $soft, $warn, $auto, $ensure)
        . ([scriptblock]::Create($ensure))
        $root = [System.IO.Path]::GetPathRoot($path)
        if (-not $root -or $root.StartsWith('\\')) { throw ("Chỉ áp quota cho đường dẫn cục bộ trên máy chủ: " + $path) }
        $di = New-Object System.IO.DriveInfo $root
        if ($di.DriveType -ne 'Fixed') { throw "Chỉ áp quota cho ổ đĩa cố định của máy, không áp cho USB/ổ tháo rời: " + $path }
        if ($di.DriveFormat -ne 'NTFS') { throw "FSRM Quota chỉ hỗ trợ định dạng NTFS (ổ $root đang là $($di.DriveFormat))." }
        if (-not (Test-Path -LiteralPath $path)) { New-Item -ItemType Directory -Path $path -Force | Out-Null }
        $thresholds = @()
        if ($warn -gt 0) {
            $act = New-FsrmAction -Type Event -EventType Warning -Body "Thư mục [Quota Path] đã dùng [Quota Used Percent]% dung lượng quota."
            $thresholds = @(New-FsrmQuotaThreshold -Percentage $warn -Action $act)
        }
        if ($auto) {
            $tplName = "Jebtool-Auto-$size-$(if($soft){'Soft'}else{'Hard'})-$warn"
            $tp = @{ Name = $tplName; Size = [int64]$size; SoftLimit = [bool]$soft }
            if ($thresholds.Count -gt 0) { $tp.Threshold = $thresholds }
            if (Get-FsrmQuotaTemplate -Name $tplName -ErrorAction SilentlyContinue) {
                Set-FsrmQuotaTemplate @tp -ErrorAction Stop
            } else {
                New-FsrmQuotaTemplate @tp -ErrorAction Stop | Out-Null
            }
            if (Get-FsrmAutoQuota -Path $path -ErrorAction SilentlyContinue) {
                Set-FsrmAutoQuota -Path $path -Template $tplName -UpdateDerived -ErrorAction Stop
            } else {
                New-FsrmAutoQuota -Path $path -Template $tplName -ErrorAction Stop | Out-Null
            }
            "Đã đặt AutoQuota (Template '$tplName') cho thư mục con của: " + $path
        }
        else {
            $p = @{ Path = $path; Size = [int64]$size; SoftLimit = [bool]$soft }
            if ($thresholds.Count -gt 0) { $p.Threshold = $thresholds }
            if (Get-FsrmQuota -Path $path -ErrorAction SilentlyContinue) { Set-FsrmQuota @p -ErrorAction Stop } else { New-FsrmQuota @p -ErrorAction Stop | Out-Null }
            "Đã đặt quota cho: " + $path
        }
    } @($path, $size, $soft, $warn, $auto, $script:FsrmEnsure.ToString()) -PromptDryRun)
})

$btnQView.Add_Click({
    [void](Invoke-PCAction $txtQSrv.Text "Xem quota thư mục" "" {
        if (-not (Get-Module -ListAvailable -Name FileServerResourceManager)) {
            "Máy đích chưa cài vai trò File Server Resource Manager (FSRM), chưa có FSRM quota nào."
            return
        }
        Import-Module FileServerResourceManager -ErrorAction Stop
        $n = 0
        foreach ($q in @(Get-FsrmQuota -ErrorAction SilentlyContinue)) {
            $n++
            "{0}  |  giới hạn {1:N2} GB  |  đã dùng {2:N2} GB  |  {3}" -f $q.Path, ($q.Size / 1GB), ($q.Usage / 1GB), $(if ($q.SoftLimit) { 'mềm' } else { 'cứng' })
        }
        foreach ($q in @(Get-FsrmAutoQuota -ErrorAction SilentlyContinue)) {
            $n++
            $tpl = Get-FsrmQuotaTemplate -Name $q.Template -ErrorAction SilentlyContinue
            if ($tpl) {
                "{0}  |  tự áp thư mục con (Template: {1})  |  giới hạn {2:N2} GB  |  {3}" -f $q.Path, $q.Template, ($tpl.Size / 1GB), $(if ($tpl.SoftLimit) { 'mềm' } else { 'cứng' })
            } else {
                "{0}  |  tự áp thư mục con (Template: {1})" -f $q.Path, $q.Template
            }
        }
        if ($n -eq 0) { "Chưa có quota nào." }
    } @() -ReadOnly -RequireAdmin)
})

$btnQRemove.Add_Click({
    $path = $txtQPath.Text.Trim()
    if (-not $path) { Show-Msg "Bạn chưa nhập thư mục." "Chưa hợp lệ" "Warning"; return }
    [void](Invoke-PCAction $txtQSrv.Text "Gỡ quota thư mục" ("gỡ quota của " + $path) {
        param($path)
        if (-not (Get-Module -ListAvailable -Name FileServerResourceManager)) {
            "Máy đích chưa cài vai trò FSRM nên không có quota để gỡ."
            return
        }
        Import-Module FileServerResourceManager -ErrorAction Stop
        $done = $false
        if (Get-FsrmQuota -Path $path -ErrorAction SilentlyContinue) { Remove-FsrmQuota -Path $path -Confirm:$false -ErrorAction Stop; $done = $true }
        if (Get-FsrmAutoQuota -Path $path -ErrorAction SilentlyContinue) { Remove-FsrmAutoQuota -Path $path -Confirm:$false -ErrorAction Stop; $done = $true }
        if ($done) { "Đã gỡ quota: " + $path } else { "Không có quota nào ở: " + $path }
    } @($path) -Danger -PromptDryRun)
})

$btnGCreate.Add_Click({
    Update-OUList
    $script:Working = $true
    $createdGpo = $false; $nm = ""
    try {
        $qScopeIdx  = $cboQuotaScopeType.SelectedIndex
        $qScopeKind = if ($qScopeIdx -eq 1) { 'Group' } elseif ($qScopeIdx -eq 2) { 'User' } else { 'OU' }
        $qScopeObj  = $txtQuotaScopeTarget.Text.Trim()
        $unit       = [string]$cboGUnit.SelectedItem
        $limBytes   = [int64]$numGLimit.Value * (Get-UnitBytes $unit)
        $warnBytes  = [int64][math]::Max(1, [math]::Floor([double]$limBytes * ([double]$numGWarn.Value / 100.0)))

        if ($qScopeKind -eq 'User') {
            if (-not $qScopeObj) { Show-Msg "Bạn đã chọn 'Chỉ User' nhưng chưa nhập tên User." "Chưa hợp lệ" "Warning"; return }
            $lookupU = $qScopeObj
            if ($lookupU -match '^[^\\]+\\(.+)$') { $lookupU = $Matches[1] }
            elseif ($lookupU -match '^([^@]+)@') { $lookupU = $Matches[1] }
            $escU = $lookupU -replace "'", "''"
            $uHits = @(Get-ADUser -Filter "SamAccountName -eq '$escU' -or Name -eq '$escU'" -ErrorAction SilentlyContinue)
            if ($uHits.Count -eq 0) { Show-Msg "Không tìm thấy User '$qScopeObj' trong AD." "Không tìm thấy" "Warning"; return }
            if ($uHits.Count -gt 1) { Show-Msg "Có $($uHits.Count) User trùng tên '$qScopeObj'. Hãy nhập chính xác SamAccountName." "Trùng nhiều User" "Warning"; return }
            $uSam  = $uHits[0].SamAccountName
            $domNb = if ($script:DomainNetBIOS) { $script:DomainNetBIOS } else { $env:USERDOMAIN }
            $ntAcc = "$domNb\$uSam"

            $qPathVal = $txtQPath.Text.Trim()
            $drv = if ($qPathVal -match '^([A-Za-z]):') { $Matches[1].ToUpper() } else { 'C' }
            $uPlan = "Đặt NTFS Disk Quota trên ổ ${drv}: cho User '$ntAcc' | Tối đa $($numGLimit.Value) $unit | Cảnh báo $($numGWarn.Value)% ($(if ($chkGEnforce.Checked) { 'Chặn ghi khi vượt' } else { 'Chỉ ghi log' }))"
            $script:Working = $false
            [void](Invoke-PCAction $txtQSrv.Text "Đặt NTFS Quota cho User" $uPlan {
                param($d, $wb, $lb, $acc, $enf)
                $v = Get-Volume -DriveLetter $d -ErrorAction SilentlyContinue
                if (-not $v) { throw "Không tìm thấy ổ ${d}: trên máy đích (hãy kiểm tra ký tự ổ đĩa ở mục Thư mục bên trên)." }
                if ($v.DriveType -ne 'Fixed') { throw "Chỉ áp NTFS Quota cho ổ đĩa cố định." }
                if ($v.FileSystem -ne 'NTFS') { throw "Chỉ hỗ trợ NTFS Quota trên định dạng NTFS (ổ ${d}: đang là $($v.FileSystem))." }
                $r1 = if ($enf) { & fsutil quota enforce "${d}:" 2>&1 } else { & fsutil quota track "${d}:" 2>&1 }
                if ($LASTEXITCODE -ne 0) { throw ("fsutil quota lỗi: " + ($r1 -join ' ')) }
                $r2 = & fsutil quota modify "${d}:" $wb $lb $acc 2>&1
                if ($LASTEXITCODE -ne 0) { throw ("fsutil quota modify lỗi: " + ($r2 -join ' ')) }
                Write-Output "Đã đặt NTFS Quota trên ổ ${d}: cho $acc (Cảnh báo: $wb bytes, Giới hạn: $lb bytes)."
            } @($drv, $warnBytes, $limBytes, $ntAcc, $chkGEnforce.Checked) -Danger -PromptDryRun)
            return
        }

        $nm = $txtGName.Text.Trim()
        if (-not $nm -or $nm -match '[\\/:*?"<>|]') { Show-Msg "Tên GPO chưa hợp lệ." "Chưa hợp lệ" "Warning"; return }
        if ($cboQuotaTarget.SelectedIndex -lt 0 -or $cboQuotaTarget.SelectedIndex -ge $script:OUDN.Count) { Show-Msg "Chưa chọn OU đích." "Chưa hợp lệ" "Warning"; return }
        $target = $script:OUDN[$cboQuotaTarget.SelectedIndex]

        $qScopeSam = $qScopeObj
        if ($qScopeKind -eq 'Group') {
            $qScopeRes = Test-GpoScopeTarget 'Group' $qScopeObj $true $false
            if (-not $qScopeRes.Ok) { return }
            if ($qScopeRes.Sam) { $qScopeSam = $qScopeRes.Sam }
        }

        $unitCode = switch ($unit) { 'MB' { 2 } 'GB' { 3 } 'TB' { 4 } default { 3 } }
        # Hạ 1 bậc đơn vị cho Threshold để tránh tràn Int32 với TB và tránh làm tròn 1MB*80%=1MB
        $thrUnitCode = $unitCode - 1
        $thrUnitName = switch ($thrUnitCode) { 1 { 'KB' } 2 { 'MB' } 3 { 'GB' } default { 'MB' } }
        $thrVal      = [int][math]::Max(1, [math]::Floor([double]$numGLimit.Value * 1024.0 * ([double]$numGWarn.Value / 100.0)))
        $k = 'HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DiskQuota'
        $vals = @(
            (New-PV $k 'Enable' 'DWord' 1),
            (New-PV $k 'Enforce' 'DWord' $(if ($chkGEnforce.Checked) { 1 } else { 0 })),
            (New-PV $k 'Limit' 'DWord' ([int]$numGLimit.Value)),
            (New-PV $k 'LimitUnits' 'DWord' $unitCode),
            (New-PV $k 'Threshold' 'DWord' $thrVal),
            (New-PV $k 'ThresholdUnits' 'DWord' $thrUnitCode),
            (New-PV $k 'ApplyToRemovableMedia' 'DWord' 0),
            (New-PV $k 'LogEventOverLimit' 'DWord' 1),
            (New-PV $k 'LogEventOverThreshold' 'DWord' 1)
        )
        $plan = "mỗi người dùng tối đa " + $numGLimit.Value + " " + $unit + ", cảnh báo ở " + $thrVal + " " + $thrUnitName + $(if ($chkGEnforce.Checked) { ", chặn khi vượt" } else { ", chỉ ghi log" })
        $scopeNote = if ($qScopeKind -eq 'Group') { "`r`nLọc bảo mật: chỉ Group '$qScopeSam'" } else { "" }

        if (Get-GPO -Name $nm -ErrorAction SilentlyContinue) { Show-Msg "Đã có GPO tên '$nm'. Hãy đặt tên khác." "Trùng tên" "Warning"; return }
        $gMode = Resolve-DryRunBeforeCreate ("Tạo GPO '$nm' (quota NTFS: $plan), liên kết vào: $target$scopeNote")
        if ($gMode -eq "dry") {
            Write-Log ("[CHẠY THỬ] Sẽ tạo GPO '" + $nm + "': quota NTFS - " + $plan) "Blue"
            Write-Log ("[CHẠY THỬ]   Sẽ liên kết vào: " + $target) "Blue"
            if ($qScopeKind -eq 'Group') { Write-Log ("[CHẠY THỬ]   Lọc bảo mật: chỉ Group '$qScopeSam'") "Blue" }
            return
        }
        if ($gMode -eq "live") {
            if (-not (Confirm-Msg ("Tạo GPO '" + $nm + "' (quota NTFS)`r`n" + $plan + "`r`nLiên kết vào: " + $target + $scopeNote + "`r`n`r`nTiếp tục?"))) { return }
        }

        Invoke-WithBusy {
            $pdc = (Get-ADDomain).PDCEmulator
            $gpo = New-GPO -Name $nm -Comment "Tạo bằng Jebtool: quota ổ đĩa NTFS" -Server $pdc -ErrorAction Stop
            $script:TmpCreated = $true
            foreach ($v in $vals) {
                Set-GPRegistryValue -Name $nm -Server $pdc -Key $v.Key -ValueName $v.Name -Type $v.Type -Value $v.Value -ErrorAction Stop | Out-Null
            }
            # Đăng ký Disk Quota CSE ({3610EDA5-...}) để dskquota.dll thực sự xử lý chính sách trên máy trạm
            $guid = '{' + $gpo.Id.ToString().ToUpper() + '}'
            $dn = "CN=" + $guid + ",CN=Policies,CN=System," + $script:DomainDN
            $adObj = Get-ADObject -Identity $dn -Server $pdc -Properties gPCMachineExtensionNames, versionNumber -ErrorAction Stop
            $ext = Add-GpoMachineExt $adObj.gPCMachineExtensionNames '{3610EDA5-77EF-11D2-8DC5-00C04FA31A66}' '{0F6B957D-509E-11D1-A7CC-0000F87571E3}'
            $ver = [int]$adObj.versionNumber + 1
            Set-ADObject -Identity $dn -Server $pdc -Replace @{ gPCMachineExtensionNames = $ext; versionNumber = $ver } -ErrorAction Stop
            $gptIni = "\\" + $pdc + "\SYSVOL\" + $script:DomainName + "\Policies\" + $guid + "\GPT.INI"
            if (Test-Path -LiteralPath $gptIni) {
                $txt = [System.IO.File]::ReadAllText($gptIni, [System.Text.Encoding]::Default)
                if ($txt -match '(?im)^Version=\d+') { $txt = [regex]::Replace($txt, '(?im)^Version=\d+', ('Version=' + $ver)) }
                else { $txt = $txt.TrimEnd() + "`r`nVersion=" + $ver + "`r`n" }
                [System.IO.File]::WriteAllText($gptIni, $txt, [System.Text.Encoding]::Default)
            }
            if ($qScopeKind -eq 'Group') {
                Set-GpoScopeFilter -GpoName $nm -ScopeType 'Group' -TargetPrincipal $qScopeSam -Server $pdc
            }
            New-GPLink -Name $nm -Target $target -LinkEnabled Yes -Server $pdc -ErrorAction Stop | Out-Null
            $script:TmpCreated = $false
        } "Đang tạo GPO quota..."
        Write-Log ("[OK] Đã tạo GPO quota '" + $nm + "' (" + $plan + ") và liên kết vào: " + $target + $(if ($qScopeKind -eq 'Group') { " | Lọc Group: $qScopeSam" } else { "" })) "Green"
        Write-Log "Máy trạm nhận chính sách sau ~90 phút hoặc chạy: gpupdate /force" "Black"
        $script:Working = $false
        Update-OUList -Force
    }
    catch {
        Write-Log ("[LỖI] " + $_.Exception.Message) "Red"
        if ($script:TmpCreated -and $nm) {
            try { Remove-GPO -Name $nm -Confirm:$false -ErrorAction Stop; Write-Log ("      Đã dọn GPO lỗi dở dang: " + $nm) "DarkOrange" } catch {}
            $script:TmpCreated = $false
        }
        Show-Msg $_.Exception.Message "Có lỗi" "Error"
    }
    finally { $script:TmpCreated = $false; $script:Working = $false }
})

# ---------- Triển khai tệp ----------
$cboDeployTarget.Add_SelectedIndexChanged({
    if ($script:Sync) { return }
    $script:Sync = $true; Set-TreeSelectionFromCombo; $script:Sync = $false
    $rdoDOU.Checked = $true
})

function Set-DeployArgUi {
    switch ($cboDType.SelectedIndex) {
        0 { $lblDArg.Text = "Tham số MSI:";  $txtDArg.Text = "" }
        1 { $lblDArg.Text = "Tham số:";      $txtDArg.Text = "/S" }
        2 { $lblDArg.Text = "Tham số:";      $txtDArg.Text = "" }
        3 { $lblDArg.Text = "Thư mục đích:"; $txtDArg.Text = "C:\Tools" }
        4 { $lblDArg.Text = "Ổ ánh xạ:";     $txtDArg.Text = "*" }
    }
    if ($cboDType.SelectedIndex -eq 4) {
        $chkDOnce.Enabled = $false
        $rdoDAll.Text     = "Tất cả người dùng trong domain (Everyone - mọi người thấy)"
        $rdoDOU.Text      = "Chỉ người dùng trong OU:"
        $chkDGroup.Text   = "Chỉ cho Group / User:"
        $lblDNote.Text    = "Tự tạo file .bat trong SYSVOL + GPO User Logon để ánh xạ đường dẫn \\máy\share. Chọn Everyone → mọi người thấy; chọn OU / Group / User → chỉ đúng đối tượng đó thấy."
    }
    else {
        $chkDOnce.Enabled = $true
        $rdoDAll.Text     = "Tất cả máy trong domain (everyone - gắn vào gốc domain)"
        $rdoDOU.Text      = "Chỉ máy trong OU:"
        $chkDGroup.Text   = "Chỉ cho nhóm máy (security group):"
        $lblDNote.Text    = "Tool tạo GPO chứa startup script; máy trạm chạy khi khởi động lại (gpupdate /force rồi restart). Tệp lớn (>50 MB) nên để trên thư mục chia sẻ rồi dán đường dẫn \\máy\share\tệp vào ô trên thay vì chép vào SYSVOL."
    }
}
$cboDType.Add_SelectedIndexChanged({ Set-DeployArgUi })
$chkDGroup.Add_CheckedChanged({ $txtDGroup.Enabled = $chkDGroup.Checked })

$btnDBrowse.Add_Click({
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Filter = "Tệp cài đặt / script|*.msi;*.exe;*.bat;*.cmd;*.ps1|Mọi tệp|*.*"
    if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $txtDFile.Text = $dlg.FileName
        $cboDType.SelectedIndex = Get-FileTypeIndex $dlg.FileName
        Set-DeployArgUi
        if (-not $txtDGpo.Text.Trim() -or $txtDGpo.Text -like "VN-Deploy-*") {
            $base = [System.IO.Path]::GetFileNameWithoutExtension($dlg.FileName) -replace '[\\/:*?"<>|]', '-'
            $txtDGpo.Text = "VN-Deploy-" + $base
        }
    }
})

$btnDeploy.Add_Click({
    Update-OUList
    $script:Working = $true
    $created = $false; $nm = ""; $pdc = ""
    try {
        $src = $txtDFile.Text.Trim().Trim('"')
        $type = $cboDType.SelectedIndex
        $arg  = $txtDArg.Text.Trim()

        if ($type -eq 4) {
            if (-not $script:Ready) { Show-Msg "Chưa kết nối Active Directory." "Chưa sẵn sàng" "Warning"; return }
            if ($src -notmatch '^\\\\([^\\]+)\\([^\\]+)') {
                Show-Msg "Kiểu 'Ánh xạ Share qua SYSVOL' cần nhập đường dẫn mạng dạng \\máy\share (vd: \\DC01\GiamDoc) vào ô 1." "Chưa hợp lệ" "Warning"; return
            }
            $srvPart = $Matches[1]; $sharePart = $Matches[2]
            if (-not $arg) { $arg = '*' }
            if ($arg -ne '*' -and $arg -notmatch '^[A-Za-z]:?$') {
                Show-Msg "Ổ ánh xạ phải là '*' (tự động) hoặc ký tự ổ đĩa (vd: Z:)." "Chưa hợp lệ" "Warning"; return
            }
            $nm = $txtDGpo.Text.Trim()
            if (-not $nm) { $nm = "VN-MapShare-" + ($sharePart -replace '[\\/:*?"<>|]', '-') }
            if ($nm -match '[\\/:*?"<>|]') { Show-Msg "Tên GPO chưa hợp lệ." "Chưa hợp lệ" "Warning"; return }

            $tType = 'Everyone'; $tOu = ''; $tPrinc = ''
            if ($chkDGroup.Checked) {
                $pr = $txtDGroup.Text.Trim()
                if (-not $pr) { Show-Msg "Bạn chưa nhập tên Group hoặc User." "Chưa hợp lệ" "Warning"; return }
                $lookup = $pr
                if ($lookup -match '^[^\\]+\\(.+)$') { $lookup = $Matches[1] }
                elseif ($lookup -match '^([^@]+)@') { $lookup = $Matches[1] }
                $esc = $lookup -replace "'", "''"
                $gHits = @(Get-ADGroup -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction SilentlyContinue)
                if ($gHits.Count -eq 1) {
                    if ($gHits[0].GroupCategory -ne 'Security') { Show-Msg "Group '$($gHits[0].Name)' là nhóm Distribution, hãy chọn Security Group." "Chưa hợp lệ" "Warning"; return }
                    $tType = 'Group'; $tPrinc = $gHits[0].SamAccountName
                }
                elseif ($gHits.Count -gt 1) {
                    Show-Msg "Có $($gHits.Count) Group trùng tên '$pr'. Hãy nhập chính xác SamAccountName." "Trùng nhiều Group" "Warning"; return
                }
                else {
                    $uHits = @(Get-ADUser -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction SilentlyContinue)
                    if ($uHits.Count -eq 1) { $tType = 'User'; $tPrinc = $uHits[0].SamAccountName }
                    elseif ($uHits.Count -gt 1) { Show-Msg "Có $($uHits.Count) User trùng tên '$pr'. Hãy nhập chính xác SamAccountName." "Trùng nhiều User" "Warning"; return }
                    else { Show-Msg "Không tìm thấy Group hoặc User '$pr' trong AD." "Không tìm thấy" "Warning"; return }
                }
            }
            elseif ($rdoDAll.Checked) {
                $tType = 'Everyone'
            }
            else {
                if ($cboDeployTarget.SelectedIndex -lt 0 -or $cboDeployTarget.SelectedIndex -ge $script:OUDN.Count) {
                    Show-Msg "Chưa chọn OU đích." "Chưa hợp lệ" "Warning"; return
                }
                $tType = 'OU'; $tOu = $script:OUDN[$cboDeployTarget.SelectedIndex]
            }

            $pdc = (Get-ADDomain).PDCEmulator
            if (Get-GPO -Name $nm -Server $pdc -ErrorAction SilentlyContinue) {
                Show-Msg "Đã có GPO tên '$nm'. Hãy đặt tên khác." "Trùng tên" "Warning"; return
            }
            $scopeLbl = switch ($tType) { 'Everyone' { 'Everyone (mọi người thấy)' } 'OU' { "Chỉ OU $tOu" } 'Group' { "Chỉ Group $tPrinc" } 'User' { "Chỉ User $tPrinc" } }
            $sPlan = "Tạo script .bat trong SYSVOL ánh xạ \\$srvPart\$sharePart (ổ $arg) + GPO '$nm' | Phạm vi: $scopeLbl"
            $dMode = Resolve-DryRunBeforeCreate $sPlan
            if ($dMode -eq "dry") {
                Write-Log "[CHẠY THỬ] $sPlan" "Blue"
                return
            }
            if ($dMode -eq "live") {
                if (-not (Confirm-Msg ($sPlan + "`r`n`r`nTiếp tục?"))) { return }
            }
            $svRes = Invoke-WithBusy {
                New-ShareLogonScriptGpo -ServerName $srvPart -ShareName $sharePart -TargetType $tType -TargetOU $tOu -TargetPrincipal $tPrinc -DriveLetter $arg -GpoName $nm
            } "Đang tạo script SYSVOL & GPO..."
            Write-Log ("[OK] Đã tạo script SYSVOL: " + $svRes.SysvolScriptPath) "Green"
            Write-Log ("[OK] GPO '" + $svRes.GpoName + "' -> Liên kết: " + $svRes.LinkTarget + " | Phạm vi: " + $svRes.ScopeDesc) "Green"
            Write-Log "Người dùng đăng nhập lại (hoặc chạy gpupdate /force) để tự ánh xạ Share." "Black"
            $script:Working = $false
            Update-OUList -Force
            return
        }

        if (-not $src) { Show-Msg "Bạn chưa chọn tệp cần triển khai." "Chưa hợp lệ" "Warning"; return }
        $isUnc = $src.StartsWith('\\')
        if (-not $isUnc -and -not (Test-Path -LiteralPath $src -PathType Leaf)) { Show-Msg "Không tìm thấy tệp:`r`n$src" "Chưa hợp lệ" "Warning"; return }
        $nm = $txtDGpo.Text.Trim()
        if (-not $nm -or $nm -match '[\\/:*?"<>|]') { Show-Msg "Tên GPO chưa hợp lệ." "Chưa hợp lệ" "Warning"; return }
        if ($type -eq 3 -and -not $arg) { Show-Msg "Bạn chưa nhập thư mục đích." "Chưa hợp lệ" "Warning"; return }
        if ($type -eq 3 -and $arg -notmatch '^[A-Za-z]:\\') { Show-Msg "Thư mục đích phải bắt đầu bằng ổ đĩa của máy, ví dụ C:\Tools." "Chưa hợp lệ" "Warning"; return }
        if ($chkDGroup.Checked) {
            $grp = $txtDGroup.Text.Trim()
            if (-not $grp) { Show-Msg "Bạn chưa nhập tên nhóm máy." "Chưa hợp lệ" "Warning"; return }
            $grpEsc = $grp -replace "'", "''"
            $gObj = @(Get-ADGroup -Filter ("(Name -eq '$grpEsc' -or SamAccountName -eq '$grpEsc') -and GroupCategory -eq 'Security'") -ErrorAction SilentlyContinue)
            if ($gObj.Count -eq 0) { Show-Msg "Không tìm thấy Security Group '$grp' trong AD." "Chưa hợp lệ" "Warning"; return }
            if ($gObj.Count -gt 1) { Show-Msg "Có $($gObj.Count) Group trùng tên '$grp'. Hãy nhập chính xác SamAccountName." "Trùng nhiều Group" "Warning"; return }
            $grp = $gObj[0].SamAccountName
        }
        if (-not $rdoDAll.Checked -and ($cboDeployTarget.SelectedIndex -lt 0 -or $cboDeployTarget.SelectedIndex -ge $script:OUDN.Count)) {
            Show-Msg "Chưa chọn OU đích." "Chưa hợp lệ" "Warning"; return
        }
        $target = if ($rdoDAll.Checked) { $script:DomainDN } else { $script:OUDN[$cboDeployTarget.SelectedIndex] }
        $leaf = [System.IO.Path]::GetFileName($src)
        $kinds = @("cài MSI im lặng", "chạy tệp .exe", "chạy script", "chép tệp vào " + $arg)
        $scope = if ($rdoDAll.Checked) { "TẤT CẢ máy trong domain" } else { "máy trong " + $target }
        if ($chkDGroup.Checked) { $scope += ", chỉ nhóm '" + $txtDGroup.Text.Trim() + "'" }
        $plan = $leaf + " - " + $kinds[$type] + " - áp cho " + $scope

        $pdc = (Get-ADDomain).PDCEmulator
        if (Get-GPO -Name $nm -Server $pdc -ErrorAction SilentlyContinue) { Show-Msg "Đã có GPO tên '$nm'. Hãy đặt tên khác." "Trùng tên" "Warning"; return }

        $dMode = Resolve-DryRunBeforeCreate ("Tạo GPO triển khai '$nm': $plan`r`nLiên kết vào: $target")
        if ($dMode -eq "dry") {
            Write-Log ("[CHẠY THỬ] Sẽ tạo GPO '" + $nm + "': " + $plan) "Blue"
            Write-Log ("[CHẠY THỬ]   Liên kết vào: " + $target + $(if ($isUnc) { "  (dùng tệp tại đường dẫn mạng, không chép vào SYSVOL)" } else { "  (chép tệp vào SYSVOL)" })) "Blue"
            return
        }
        if (-not $isUnc) {
            $mb = (Get-Item -LiteralPath $src).Length / 1MB
            if ($mb -gt 50) {
                if (-not (Confirm-Msg ("Tệp nặng " + [math]::Round($mb) + " MB. Chép vào SYSVOL sẽ được nhân bản tới mọi Domain Controller.`r`nNên để trên thư mục chia sẻ rồi dán đường dẫn \\máy\share\tệp.`r`n`r`nVẫn chép vào SYSVOL?"))) { return }
            }
        }
        $warnAll = if ($rdoDAll.Checked -and -not $chkDGroup.Checked) { "`r`n`r`nCẢNH BÁO: sẽ áp cho MỌI máy trong domain (kể cả Domain Controller)." } else { "" }
        if ($dMode -eq "live" -or $warnAll) {
            if (-not (Confirm-Msg ("Tạo GPO '" + $nm + "'`r`n" + $plan + $warnAll + "`r`n`r`nTiếp tục?"))) { return }
        }

        Invoke-WithBusy {
            $dom = $script:DomainName
            $gpo = New-GPO -Name $nm -Comment ("Tạo bằng Jebtool: triển khai " + $leaf) -Server $pdc -ErrorAction Stop
            $script:TmpCreated = $true
            $guid = '{' + $gpo.Id.ToString().ToUpper() + '}'
            # Ghi 1 giá trị nhỏ để GPO có phần Computer + tăng phiên bản
            Set-GPRegistryValue -Name $nm -Server $pdc -Key 'HKLM\SOFTWARE\Policies\Microsoft\Jebtool' -ValueName 'Deploy' -Type String -Value $leaf -ErrorAction Stop | Out-Null

            $gpt = "\\" + $pdc + "\SYSVOL\" + $dom + "\Policies\" + $guid
            $startup = $gpt + "\Machine\Scripts\Startup"
            New-Item -ItemType Directory -Path $startup -Force -ErrorAction Stop | Out-Null

            # Đường dẫn tệp mà máy trạm sẽ dùng
            if ($isUnc) { $ref = $src }
            else {
                Copy-Item -LiteralPath $src -Destination (Join-Path $startup $leaf) -Force -ErrorAction Stop
                $ref = '%~dp0' + $leaf
            }
            $ref = $ref -replace '%(?!~dp0)', '%%'
            $argc = $arg -replace '%', '%%'
            switch ($type) {
                0 { $cmd = 'msiexec /i "' + $ref + '" /qn /norestart ' + $argc }
                1 { $cmd = '"' + $ref + '" ' + $argc }
                2 {
                    $ext = [System.IO.Path]::GetExtension($leaf).ToLower()
                    if ($ext -eq '.ps1') { $cmd = 'powershell -NoProfile -ExecutionPolicy Bypass -File "' + $ref + '" ' + $argc }
                    else { $cmd = 'call "' + $ref + '" ' + $argc }
                }
                3 {
                    $dl = $argc.Substring(0, 2)
                    $cmd = 'powershell -NoProfile -Command "if ((New-Object System.IO.DriveInfo ''' + $dl + ''').DriveType -ne ''Fixed'') { exit 9 }"' + "`r`n" +
                           'if errorlevel 9 exit /b 9' + "`r`n" +
                           'if not exist "' + $argc + '" mkdir "' + $argc + '"' + "`r`n" + 'copy /y "' + $ref + '" "' + $argc + '\"'
                }
            }
            $mark = $guid.Trim('{', '}')
            $lines = @('@echo off', 'chcp 65001 >nul')
            if ($chkDOnce.Checked) {
                $lines += 'set "MARK=%ProgramData%\Jebtool\' + $mark + '.done"'
                $lines += 'if exist "%MARK%" exit /b 0'
                $lines += 'if not exist "%ProgramData%\Jebtool" mkdir "%ProgramData%\Jebtool"'
            }
            $lines += $cmd
            $lines += 'set RC=%ERRORLEVEL%'
            if ($chkDOnce.Checked) {
                $lines += 'if "%RC%"=="0" echo %date% %time% > "%MARK%"'
                $lines += 'if "%RC%"=="3010" echo %date% %time% > "%MARK%"'
            }
            $lines += 'exit /b %RC%'
            [System.IO.File]::WriteAllText((Join-Path $startup 'Deploy.cmd'), (($lines -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))

            $ini = "`r`n[Startup]`r`n0CmdLine=Deploy.cmd`r`n0Parameters=`r`n"
            Set-Content -Path ($gpt + "\Machine\Scripts\scripts.ini") -Value $ini -Encoding Unicode -ErrorAction Stop

            # Khai báo extension "Scripts" cho phần Computer và tăng phiên bản (AD + GPT.INI)
            $dn = "CN=" + $guid + ",CN=Policies,CN=System," + $script:DomainDN
            $obj = Get-ADObject -Identity $dn -Server $pdc -Properties gPCMachineExtensionNames, versionNumber -ErrorAction Stop
            $ext = Add-GpoMachineExt $obj.gPCMachineExtensionNames '{42B5FAAE-6536-11D2-AE5A-0000F87571E3}' '{40B6664F-4972-11D1-A7CA-0000F87571E3}'
            $ver = [int]$obj.versionNumber + 1
            Set-ADObject -Identity $dn -Server $pdc -Replace @{ gPCMachineExtensionNames = $ext; versionNumber = $ver } -ErrorAction Stop
            $ini2 = $gpt + "\GPT.INI"
            if (Test-Path -LiteralPath $ini2) {
                $txt = [System.IO.File]::ReadAllText($ini2, [System.Text.Encoding]::Default)
                if ($txt -match '(?im)^Version=\d+') { $txt = [regex]::Replace($txt, '(?im)^Version=\d+', ('Version=' + $ver)) }
                else { $txt = $txt.TrimEnd() + "`r`nVersion=" + $ver + "`r`n" }
                [System.IO.File]::WriteAllText($ini2, $txt, [System.Text.Encoding]::Default)
            }

            if ($chkDGroup.Checked) {
                $auth = (New-Object System.Security.Principal.SecurityIdentifier 'S-1-5-11').Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
                Set-GPPermission -Name $nm -Server $pdc -TargetName $grp -TargetType Group -PermissionLevel GpoApply -Confirm:$false -ErrorAction Stop | Out-Null
                Set-GPPermission -Name $nm -Server $pdc -TargetName $auth -TargetType Group -PermissionLevel GpoRead -Replace -Confirm:$false -ErrorAction Stop | Out-Null
            }
            New-GPLink -Name $nm -Target $target -LinkEnabled Yes -Server $pdc -ErrorAction Stop | Out-Null
            $script:TmpCreated = $false
        } "Đang tạo GPO triển khai..."
        Write-Log ("[OK] Đã tạo GPO '" + $nm + "': " + $plan) "Green"
        Write-Log ("      Liên kết vào: " + $target) "DimGray"
        Write-Log "Máy trạm chạy khi khởi động lại: gpupdate /force rồi restart máy (hoặc chờ ~90 phút rồi restart)." "Black"
        $script:Working = $false
        Update-OUList -Force
    }
    catch {
        Write-Log ("[LỖI] " + $_.Exception.Message) "Red"
        if ($script:TmpCreated -and $nm) {
            try { Remove-GPO -Name $nm -Server $pdc -Confirm:$false -ErrorAction Stop; Write-Log ("      Đã dọn GPO dở dang: " + $nm) "DarkOrange" }
            catch { Write-Log ("      Không dọn được GPO dở dang '" + $nm + "', hãy xóa tay trong GPMC.") "Red" }
            $script:TmpCreated = $false
        }
        Show-Msg $_.Exception.Message "Có lỗi" "Error"
    }
    finally { $script:TmpCreated = $false; $script:Working = $false }
})
Set-DeployArgUi

# ---------- Sự kiện: Lọc phạm vi GPO (OU / Group / User) ----------
$cboGpoScopeType.Add_SelectedIndexChanged({ $txtGpoScopeTarget.Enabled = ($cboGpoScopeType.SelectedIndex -gt 0) })
$cboLibScopeType.Add_SelectedIndexChanged({ $txtLibScopeTarget.Enabled = ($cboLibScopeType.SelectedIndex -gt 0) })

# ---------- Sự kiện: Share tệp / thư mục (SMB + NTFS) ----------
$cboShTargetType.Add_SelectedIndexChanged({
    $idx = $cboShTargetType.SelectedIndex
    $cboShOU.Enabled        = ($idx -eq 1)
    $txtShPrincipal.Enabled = ($idx -in @(2, 3))
})
$chkShSysvol.Add_CheckedChanged({ $cboShDrive.Enabled = $chkShSysvol.Checked })

$btnShCreate.Add_Click({
    $srv   = $txtShSrv.Text.Trim()
    $path  = $txtShPath.Text.Trim()
    $sname = $txtShName.Text.Trim()
    if (-not $path -or $path -notmatch '^[A-Za-z]:\\') { Show-Msg "Đường dẫn thư mục phải bắt đầu bằng ổ đĩa (vd: D:\Shares\DuLieu)." "Chưa hợp lệ" "Warning"; return }
    if (-not $sname -or $sname -match '[\\/:*?"<>|]') { Show-Msg "Tên Share chưa hợp lệ." "Chưa hợp lệ" "Warning"; return }
    if ($sname -match '^(?i)(SYSVOL|NETLOGON|IPC\$|ADMIN\$|[A-Z]\$|print\$)$') {
        Show-Msg "BỊ CHẶN: Không được phép chỉnh sửa Share hệ thống / Active Directory ('$sname')." "Bị chặn" "Warning"; return
    }

    $tIdx = $cboShTargetType.SelectedIndex
    $pIdx = $cboShPerm.SelectedIndex
    $smbRight  = @('Read', 'Change', 'Full')[$pIdx]
    $ntfsRight = @('(OI)(CI)RX', '(OI)(CI)M', '(OI)(CI)F')[$pIdx]
    $syncNtfs  = $chkShNtfs.Checked

    $principals = @()
    $descTarget = ""
    $ouDn = ""
    $sysvolPrincipal = ""
    $adPrincipalFound = $false
    $domNb = if ($script:DomainNetBIOS) { $script:DomainNetBIOS } else { $env:USERDOMAIN }

    if ($tIdx -eq 0) {
        $principals = @('Everyone')
        $descTarget = 'Everyone'
    }
    elseif ($tIdx -eq 1) {
        if (-not $script:Ready -or $cboShOU.SelectedIndex -le 0) { Show-Msg "Chưa kết nối AD hoặc hãy chọn 1 OU cụ thể (không chọn gốc domain)." "Chưa hợp lệ" "Warning"; return }
        $ouDn = $script:OUDN[$cboShOU.SelectedIndex]
        try {
            $grps = @(Get-ADGroup -SearchBase $ouDn -SearchScope Subtree -Filter * -ErrorAction Stop | ForEach-Object { $domNb + "\" + $_.SamAccountName })
            $usrs = @(Get-ADUser  -SearchBase $ouDn -SearchScope Subtree -Filter * -ErrorAction Stop | ForEach-Object { $domNb + "\" + $_.SamAccountName })
            $principals = @($grps + $usrs)
            if ($principals.Count -eq 0) { Show-Msg "OU đã chọn chưa có Group hoặc User nào." "Trống" "Warning"; return }
            $descTarget = "OU ($($principals.Count) đối tượng: " + ($principals -join ', ') + ")"
        }
        catch { Show-Msg ("Không đọc được đối tượng trong OU: " + $_.Exception.Message) "Có lỗi" "Error"; return }
    }
    else {
        $pName = $txtShPrincipal.Text.Trim()
        if (-not $pName) { Show-Msg "Bạn chưa nhập tên Group hoặc User." "Chưa hợp lệ" "Warning"; return }
        if ($pName -match '[:"]') { Show-Msg 'Tên đối tượng không được chứa ký tự : hoặc ".' "Chưa hợp lệ" "Warning"; return }
        $principals = @($pName)
        if ($script:Ready) {
            $lookup = $pName
            if ($lookup -match '^[^\\]+\\(.+)$') { $lookup = $Matches[1] }
            elseif ($lookup -match '^([^@]+)@') { $lookup = $Matches[1] }
            $esc = $lookup -replace "'", "''"
            if ($tIdx -eq 2) {
                $hits = @(Get-ADGroup -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction SilentlyContinue)
                if ($hits.Count -gt 1) { Show-Msg "Có $($hits.Count) Group trùng tên '$pName'. Hãy nhập chính xác SamAccountName." "Trùng nhiều Group" "Warning"; return }
                if ($hits.Count -eq 1) {
                    $sysvolPrincipal = $hits[0].SamAccountName
                    $principals = @("$domNb\$sysvolPrincipal")
                    $adPrincipalFound = $true
                }
            }
            else {
                $hits = @(Get-ADUser -Filter "SamAccountName -eq '$esc' -or Name -eq '$esc'" -ErrorAction SilentlyContinue)
                if ($hits.Count -gt 1) { Show-Msg "Có $($hits.Count) User trùng tên '$pName'. Hãy nhập chính xác SamAccountName." "Trùng nhiều User" "Warning"; return }
                if ($hits.Count -eq 1) {
                    $sysvolPrincipal = $hits[0].SamAccountName
                    $principals = @("$domNb\$sysvolPrincipal")
                    $adPrincipalFound = $true
                }
            }
        }
        $descTarget = $(if ($tIdx -eq 2) { "Group " } else { "User " }) + $principals[0]
    }

    $drvChoice = if ($cboShDrive.SelectedIndex -le 0) { '*' } else { [string]$cboShDrive.SelectedItem }
    $doSysvol  = ($chkShSysvol.Checked -and $script:Ready -and ($tIdx -in @(0, 1) -or $adPrincipalFound))
    if ($chkShSysvol.Checked -and $script:Ready -and ($tIdx -in @(2, 3)) -and -not $adPrincipalFound) {
        Write-Log ("[LƯU Ý] Không tìm thấy '$($principals[0])' trong AD (tài khoản cục bộ) — bỏ qua tạo script SYSVOL.") "DarkOrange"
    }

    $plan = "Tạo/cập nhật SMB Share '\\$(if($srv){$srv}else{$env:COMPUTERNAME})\$sname' -> $path | Đối tượng: $descTarget | Quyền: $smbRight" +
            $(if ($syncNtfs) { " (+ NTFS)" } else { "" }) +
            $(if ($doSysvol) { " | SYSVOL: tự tạo .bat + GPO Logon (ổ $drvChoice)" } else { "" })
    $shOk = Invoke-PCAction $srv "Tạo / cập nhật Share" $plan {
        param($p, $sn, $accs, $smbR, $ntfsR, $doNtfs)
        $pNorm = if ($p -match '^[A-Za-z]:\\+$') { $p.Substring(0, 3) } else { $p.TrimEnd('\') }
        if (-not (Test-Path -LiteralPath $pNorm)) { New-Item -ItemType Directory -Path $pNorm -Force | Out-Null; Write-Output "Đã tạo thư mục: $pNorm" }
        $ex = Get-SmbShare -Name $sn -ErrorAction SilentlyContinue
        if ($ex) {
            if ($ex.Path.TrimEnd('\') -ine $pNorm.TrimEnd('\')) {
                throw "Share '$sn' đã tồn tại và đang trỏ tới '$($ex.Path)', khác với '$pNorm'. Hãy đặt tên Share khác."
            }
            try { Set-SmbShare -Name $sn -FolderEnumerationMode AccessBased -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        } else {
            $admName = (New-Object System.Security.Principal.SecurityIdentifier 'S-1-5-32-544').Translate([System.Security.Principal.NTAccount]).Value
            New-SmbShare -Name $sn -Path $pNorm -FullAccess $admName -FolderEnumerationMode AccessBased -ErrorAction Stop | Out-Null
            Write-Output "Đã tạo Share: $sn -> $pNorm (Access-Based Enumeration)"
        }
        foreach ($a in $accs) {
            Grant-SmbShareAccess -Name $sn -AccountName $a -AccessRight $smbR -Force -ErrorAction Stop | Out-Null
            Write-Output "SMB: cấp quyền $smbR cho $a"
            if ($doNtfs) {
                $r = & icacls $pNorm /remove:d $a /grant:r "${a}:${ntfsR}" /T /C 2>&1
                if ($LASTEXITCODE -ne 0) { throw ("icacls lỗi cho ${a}: " + ($r -join ' ')) }
                Write-Output "NTFS: cấp quyền $ntfsR cho $a"
            }
        }
        Write-Output ("Đường dẫn truy cập: \\" + $env:COMPUTERNAME + "\" + $sn)
    } @($path, $sname, $principals, $smbRight, $ntfsRight, $syncNtfs) -PromptDryRun

    if ($doSysvol) {
        $tTypeStr = @('Everyone', 'OU', 'Group', 'User')[$tIdx]
        if ($chkDry.Checked -and -not $shOk) {
            $safeS = ($sname -replace '[^\w\-]', '_'); if (-not $safeS) { $safeS = 'Share' }
            $suf = switch ($tTypeStr) {
                'Everyone' { 'Everyone' }
                'OU'       { 'OU_' + (($ouDn -split '(?<!\\)(?:\\\\)*,', 2)[0] -replace '^(?i)OU=', '' -replace '[^\w\-]', '_') }
                default    { ($sysvolPrincipal -replace '[^\w\-]', '_') }
            }
            Write-Log ("[CHẠY THỬ]   SYSVOL: sẽ tạo script MapShare_${safeS}_${suf}.bat + GPO 'VN-MapShare-$sname' ($tTypeStr)") "Blue"
        }
        elseif ($shOk -and -not $chkDry.Checked) {
            try {
                $svRes = Invoke-WithBusy {
                    New-ShareLogonScriptGpo -ServerName $srv -ShareName $sname -TargetType $tTypeStr -TargetOU $ouDn -TargetPrincipal $sysvolPrincipal -DriveLetter $drvChoice
                } "Đang tạo script SYSVOL & GPO..."
                Write-Log ("[OK] Đã tạo script SYSVOL: " + $svRes.SysvolScriptPath) "Green"
                Write-Log ("[OK] Đã cấu hình GPO '" + $svRes.GpoName + "' -> Liên kết: " + $svRes.LinkTarget + " | Phạm vi: " + $svRes.ScopeDesc) "Green"
                Update-OUList -Force
            }
            catch {
                Write-Log ("[LỖI] Tạo script SYSVOL / GPO cho Share '$sname': " + $_.Exception.Message) "Red"
                Show-Msg ("Share đã được tạo, nhưng tạo script SYSVOL gặp lỗi:`r`n" + $_.Exception.Message) "Lỗi script SYSVOL" "Warning"
            }
        }
    }
})

$btnShView.Add_Click({
    $srv = $txtShSrv.Text.Trim()
    [void](Invoke-PCAction $srv "Xem Share đang có" "" {
        $list = @(Get-SmbShare -ErrorAction Stop | Where-Object { $_.Name -notmatch '\$$' })
        if ($list.Count -eq 0) { Write-Output "(Không có Share người dùng nào)"; return }
        foreach ($s in $list) {
            $acc = @(Get-SmbShareAccess -Name $s.Name -ErrorAction SilentlyContinue | ForEach-Object { $_.AccountName + "(" + $_.AccessRight + ")" }) -join ', '
            Write-Output ($s.Name + "  ->  " + $s.Path + "  |  " + $acc)
        }
    } @() -ReadOnly -RequireAdmin)
})

$btnShRemove.Add_Click({
    $srv   = $txtShSrv.Text.Trim()
    $sname = $txtShName.Text.Trim()
    if (-not $sname) { Show-Msg "Nhập tên Share cần gỡ." "Chưa hợp lệ" "Warning"; return }
    if ($sname -match '^(?i)(SYSVOL|NETLOGON|IPC\$|ADMIN\$|[A-Z]\$|print\$)$') {
        Show-Msg "BỊ CHẶN: Không được phép gỡ Share hệ thống / Active Directory ('$sname')." "Bị chặn" "Warning"; return
    }
    $rmOk = Invoke-PCAction $srv "Gỡ Share" ("Gỡ SMB Share '$sname' (không xóa dữ liệu trong thư mục)") {
        param($sn)
        Remove-SmbShare -Name $sn -Force -ErrorAction Stop
        Write-Output "Đã gỡ Share: $sn"
    } @($sname) -Danger -PromptDryRun

    if ($rmOk -and -not $chkDry.Checked -and $script:Ready) {
        try {
            $pdc = (Get-ADDomain -ErrorAction Stop).PDCEmulator
            $gpoName = "VN-MapShare-" + ($sname -replace '[\\/:*?"<>|]', '-')
            $hasGpo = $null -ne (Get-GPO -Name $gpoName -Server $pdc -ErrorAction SilentlyContinue)
            $safeS = ($sname -replace '[^\w\-]', '_'); if (-not $safeS) { $safeS = 'Share' }
            $scriptsDir = "\\$pdc\SYSVOL\$($script:DomainName)\scripts"
            $bats = if (Test-Path -LiteralPath $scriptsDir) { @(Get-ChildItem -LiteralPath $scriptsDir -Filter "MapShare_${safeS}_*.bat" -File -ErrorAction SilentlyContinue) } else { @() }
            if ($hasGpo -or $bats.Count -gt 0) {
                if (Confirm-Msg "Tìm thấy script SYSVOL / GPO '$gpoName' gắn với Share '$sname'.`r`nBạn có muốn gỡ luôn GPO và file .bat trong SYSVOL không?") {
                    Invoke-WithBusy {
                        if ($hasGpo) { Remove-GPO -Name $gpoName -Server $pdc -Confirm:$false -ErrorAction Stop }
                        foreach ($b in $bats) { Remove-Item -LiteralPath $b.FullName -Force -ErrorAction Stop }
                    } "Đang dọn script SYSVOL & GPO..."
                    if ($hasGpo) { Write-Log "[OK] Đã gỡ GPO '$gpoName'." "Green" }
                    foreach ($b in $bats) { Write-Log "[OK] Đã xóa script SYSVOL: $($b.FullName)" "Green" }
                    Update-OUList -Force
                }
            }
        }
        catch {
            Write-Log ("[LỖI] Gỡ script SYSVOL / GPO: " + $_.Exception.Message) "Red"
        }
    }
})

# ---------- Sự kiện: Ổ đĩa (Disk Management) ----------
$script:DiskVisualBtns   = @()
$script:SelectedDiskTile = $null
$script:SelectedDiskMeta = $null
$script:SelectedVolKey   = ""
$script:LastDiskData     = $null
$script:SyncDiskSel      = $false

function Format-DiskSize {
    param([double]$Bytes)
    if ($Bytes -le 0) { return "0 MB" }
    if ($Bytes -lt 1GB) {
        return ([string][int][Math]::Round($Bytes / 1MB) + " MB")
    }
    $gb = [math]::Round($Bytes / 1GB, 2)
    return ($gb.ToString("0.00", [System.Globalization.CultureInfo]::InvariantCulture) + " GB")
}

function Test-DiskServerInput {
    param([string]$Srv)
    if ($Srv -match '(?i)^disk\s*\d+$') {
        Show-Msg "Ô 'Máy chủ' dùng để nhập tên máy tính từ xa (để trống nếu thao tác trên máy này).`r`nĐể chọn Disk ($Srv), hãy bấm trực tiếp vào dòng Disk đó bên dưới." "Nhầm ô Máy chủ" "Warning"
        return $false
    }
    if ($Srv -and $Srv -notmatch '^[A-Za-z0-9\.\-_]+$') {
        Show-Msg "Tên máy không hợp lệ." "Chưa hợp lệ" "Warning"
        return $false
    }
    return $true
}

$script:DpExecSrc = @'
param([string[]]$Cmds)
$full = @($Cmds) + @('exit')
$raw = $full | & diskpart 2>&1
$txt = ($raw | Out-String)
$chkTxt = $txt -replace '(?is)Virtual Disk Service error:\s*This disk is already online\.?', '' -replace '(?i)The disk is already online\.?', ''
if ($LASTEXITCODE -ne 0 -or $chkTxt -match '(?i)DiskPart has encountered an error|DiskPart was unable to|There is no (disk|volume|partition)|is not valid|virtual disk service error|The arguments specified for this command are not valid|Not enough usable (free )?space|does not support|The disk is not empty|cannot be (extended|converted|deleted|shrunk)|cannot shrink|is not a (basic|dynamic) disk|is already a (basic|dynamic) disk|A virtual disk support provider|The selected volume cannot|The specified disk is not') {
    throw ("diskpart lỗi (code $LASTEXITCODE): " + $txt.Trim())
}
$txt.TrimEnd()
'@

function Invoke-DiskInit {
    param([string]$Srv, [int]$DiskNumber, [string]$Style)
    $st = if ($Style -ieq 'MBR') { 'MBR' } else { 'GPT' }
    $plan = "Khởi tạo Disk $DiskNumber chuẩn $st (Initialize Disk)`r`n(Nếu Disk đang Offline sẽ được đưa Online trước.)"
    $ok = Invoke-PCAction $Srv "Khởi tạo Disk ($st)" $plan {
        param($dn, $pStyle)
        $d = Get-Disk -Number ([int]$dn) -ErrorAction Stop
        if ($d.IsSystem -or $d.IsBoot) { throw "BỊ CHẶN: Không được phép khởi tạo Disk hệ thống/khởi động (Disk $dn)." }
        if ($d.IsReadOnly) { throw "Disk $dn đang ở chế độ Read-Only." }
        if ($d.PartitionStyle -ne 'RAW') { throw "Disk $dn đã được khởi tạo chuẩn $($d.PartitionStyle) (chỉ khởi tạo được Disk RAW)." }
        if ($pStyle -eq 'MBR' -and $d.Size -gt 2TB) { throw "Disk $dn lớn hơn 2 TB, hãy chọn chuẩn GPT thay vì MBR." }
        if ($d.IsOffline) { Set-Disk -Number $d.Number -IsOffline $false -ErrorAction Stop }
        Initialize-Disk -Number $d.Number -PartitionStyle $pStyle -Confirm:$false -ErrorAction Stop
        Write-Output "Đã khởi tạo Disk $dn chuẩn $pStyle (Online)."
    } @($DiskNumber, $st) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskConvertStyle {
    param([string]$Srv, [int]$DiskNumber)
    $plan = "Chuyển đổi chuẩn phân vùng Disk $DiskNumber (Convert MBR <-> GPT)`r`n(Điều kiện: Disk Basic phải trống, không chứa phân vùng dữ liệu nào.)"
    $ok = Invoke-PCAction $Srv "Chuyển đổi MBR <-> GPT" $plan {
        param($dn, $getDynSrc, $dpSrc, $parseSrc)
        $d = Get-Disk -Number ([int]$dn) -ErrorAction Stop
        if ($d.IsSystem -or $d.IsBoot) { throw "BỊ CHẶN: Không được phép chuyển đổi Disk hệ thống/khởi động (Disk $dn)." }
        if ($d.IsReadOnly) { throw "Disk $dn đang ở chế độ Read-Only." }
        if ($d.PartitionStyle -eq 'RAW') { throw "Disk $dn đang là RAW — hãy dùng Initialize Disk trước." }
        $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
        $ldmParts = @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 })
        if (($dpMap.ContainsKey([int]$dn) -and $dpMap[[int]$dn].IsDynamic) -or $ldmParts.Count -gt 0) {
            throw "BỊ CHẶN: Disk $dn đang là Dynamic Disk. Hãy chuyển về Basic Disk trước khi đổi MBR <-> GPT."
        }
        $dataPts = @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.Type -ne 'Reserved' })
        if ($dataPts.Count -gt 0) {
            throw "BỊ CHẶN: Disk $dn đang chứa $($dataPts.Count) phân vùng dữ liệu. Hãy xóa toàn bộ phân vùng trên Disk trước khi chuyển đổi MBR <-> GPT."
        }
        $targetStyle = if ($d.PartitionStyle -eq 'GPT') { 'MBR' } else { 'GPT' }
        if ($targetStyle -eq 'MBR' -and $d.Size -gt 2TB) { throw "BỊ CHẶN: Disk $dn lớn hơn 2 TB, không thể chuyển về MBR." }
        if ($d.IsOffline) { Set-Disk -Number $d.Number -IsOffline $false -ErrorAction Stop }
        Clear-Disk -Number $d.Number -RemoveData -Confirm:$false -ErrorAction Stop
        Initialize-Disk -Number $d.Number -PartitionStyle $targetStyle -Confirm:$false -ErrorAction Stop
        Write-Output "Đã chuyển đổi Disk $dn từ $($d.PartitionStyle) sang chuẩn $targetStyle."
    } @($DiskNumber, $script:GetDynDisksSrc, $script:DpExecSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskConvertDynamic {
    param([string]$Srv, [int[]]$DiskNumbers)
    $dns = @($DiskNumbers | Select-Object -Unique)
    if ($dns.Count -eq 0) { return $false }
    $plan = "Chuyển đổi Disk ($($dns -join ', ')) từ Basic sang Dynamic Disk`r`n⚠ Lưu ý: Cần Dynamic Disk để tạo Spanned / Striped / Mirrored / RAID-5 Volume."
    $ok = Invoke-PCAction $Srv "Chuyển sang Dynamic Disk" $plan {
        param($nums, $getDynSrc, $dpSrc, $parseSrc)
        $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
        $cmds = New-Object 'System.Collections.Generic.List[string]'
        $toConv = @()
        foreach ($n in @($nums)) {
            $ni = [int]$n
            if ($dpMap.ContainsKey($ni) -and $dpMap[$ni].IsDynamic) { continue }
            $d = Get-CimInstance -Namespace root\Microsoft\Windows\Storage -ClassName MSFT_Disk -Filter "Number=$ni" -ErrorAction SilentlyContinue | Select-Object -First 1
            if (-not $d) {
                if (-not $dpMap.ContainsKey($ni)) { throw "Không tìm thấy Disk $ni." }
                continue
            }
            $stRaw = [string]$d.PartitionStyle
            $stName = switch ($stRaw) { '0' { 'RAW' } '1' { 'MBR' } '2' { 'GPT' } default { $stRaw.ToUpper() } }
            $busRaw = [string]$d.BusType
            $busName = switch ($busRaw) { '7' { 'USB' } '12' { 'SD' } '13' { 'MMC' } '15' { 'File Backed Virtual' } '17' { 'NVMe' } default { $busRaw } }
            if ($d.IsSystem -or $d.IsBoot) { throw "BỊ CHẶN: Không được phép chuyển Disk hệ thống/khởi động (Disk $ni) sang Dynamic trên tool." }
            if ($d.IsReadOnly) { throw "Disk $ni đang ở chế độ Read-Only." }
            if ($stName -eq 'RAW') { throw "Disk $ni đang ở trạng thái RAW — hãy Initialize Disk trước." }
            if ($busName -in @('File Backed Virtual', 'USB', 'SD', 'MMC')) {
                throw "BỊ CHẶN: Windows không hỗ trợ chuyển ổ đĩa chuẩn $busName (USB / File VHDX) sang Dynamic Disk."
            }
            $toConv += $ni
            $cmds.Add("select disk $ni")
            if ($d.IsOffline) { $cmds.Add("online disk noerr") }
            $cmds.Add("attributes disk clear readonly noerr")
            $cmds.Add("convert dynamic")
        }
        if ($toConv.Count -eq 0) {
            Write-Output ("Disk (" + ($nums -join ', ') + ") đã ở chế độ Dynamic Disk.")
            return
        }
        [void](& ([scriptblock]::Create($dpSrc)) $cmds.ToArray())
        Write-Output ("Đã chuyển sang Dynamic Disk: Disk " + ($toConv -join ', '))
    } @($dns, $script:GetDynDisksSrc, $script:DpExecSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskConvertBasic {
    param([string]$Srv, [int]$DiskNumber)
    $plan = "Chuyển đổi Disk $DiskNumber từ Dynamic về Basic Disk`r`n(Điều kiện: Disk phải không còn Dynamic Volume nào.)"
    $ok = Invoke-PCAction $Srv "Chuyển về Basic Disk" $plan {
        param($dn, $dpSrc, $getDynSrc, $parseSrc)
        $ni = [int]$dn
        $d = Get-CimInstance -Namespace root\Microsoft\Windows\Storage -ClassName MSFT_Disk -Filter "Number=$ni" -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($d) {
            if ($d.IsSystem -or $d.IsBoot) { throw "BỊ CHẶN: Không được phép thao tác trên Disk hệ thống (Disk $ni)." }
            if ($d.IsReadOnly) { throw "Disk $ni đang ở chế độ Read-Only." }
        }
        else {
            $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
            if (-not $dpMap.ContainsKey($ni)) { throw "Không tìm thấy Disk $ni." }
        }
        $out = & ([scriptblock]::Create($dpSrc)) @("select disk $ni", "detail disk")
        if ($out -match '(?i)Boot Disk\s*:\s*Yes|Crashdump Disk\s*:\s*Yes|Current Read-only State\s*:\s*Yes') {
            throw "BỊ CHẶN: Không được phép thao tác trên Disk hệ thống/Read-Only (Disk $ni)."
        }
        if ($out -match '(?m)^\s*\*?\s*Volume\s+\d+\s+') {
            throw "BỊ CHẶN: Disk $ni vẫn đang chứa Volume. Hãy xóa hết Volume trên Disk trước khi chuyển về Basic Disk."
        }
        [void](& ([scriptblock]::Create($dpSrc)) @("select disk $ni", "convert basic"))
        Write-Output "Đã chuyển đổi Disk $ni về Basic Disk."
    } @($DiskNumber, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskToggleOffline {
    param([string]$Srv, [int]$DiskNumber)
    $plan = "Chuyển trạng thái Online <-> Offline cho Disk $DiskNumber"
    $ok = Invoke-PCAction $Srv "Online / Offline Disk" $plan {
        param($dn, $dpSrc, $getDynSrc, $parseSrc)
        $ni = [int]$dn
        $d = Get-Disk -Number $ni -ErrorAction SilentlyContinue
        if ($d) {
            if ($d.IsSystem -or $d.IsBoot) { throw "BỊ CHẶN: Không được phép đưa Disk hệ thống/khởi động (Disk $ni) về Offline." }
            $newOff = (-not [bool]$d.IsOffline)
            Set-Disk -Number $d.Number -IsOffline $newOff -ErrorAction Stop
            $st = if ($newOff) { "Offline" } else { "Online" }
            Write-Output "Đã chuyển Disk $ni sang trạng thái $st."
            return
        }
        $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
        if (-not $dpMap.ContainsKey($ni)) { throw "Không tìm thấy Disk $ni." }
        $det = & ([scriptblock]::Create($dpSrc)) @("select disk $ni", "detail disk")
        if ($det -match '(?i)Boot Disk\s*:\s*Yes|Pagefile Disk\s*:\s*Yes|Crashdump Disk\s*:\s*Yes') {
            throw "BỊ CHẶN: Không được phép đưa Disk hệ thống/khởi động (Disk $ni) về Offline."
        }
        $wasOff = ($dpMap[$ni].Status -match '(?i)Offline')
        $cmd = if ($wasOff) { "online disk" } else { "offline disk" }
        [void](& ([scriptblock]::Create($dpSrc)) @("select disk $ni", $cmd))
        $st = if ($wasOff) { "Online" } else { "Offline" }
        Write-Output "Đã chuyển Disk $ni sang trạng thái $st."
    } @($DiskNumber, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

$script:ParseDpTableSrc = @'
param([string[]]$OutLines, [string]$RowRx)
$rows = @()
$curCols = $null
foreach ($ln in $OutLines) {
    if ($ln -match '^\s*-{2,}(\s+-{2,})+\s*$') {
        $curCols = [regex]::Matches($ln, '-+')
        continue
    }
    if ($curCols -and $ln -match $RowRx) {
        $vals = @()
        for ($ci = 0; $ci -lt $curCols.Count; $ci++) {
            $st = $curCols[$ci].Index
            if ($st -ge $ln.Length) { $vals += ""; continue }
            $lnLen = if ($ci -eq $curCols.Count - 1) { $ln.Length - $st } else { [Math]::Min($curCols[$ci].Length, $ln.Length - $st) }
            $vals += $ln.Substring($st, $lnLen).Trim()
        }
        $rows += ,$vals
    }
}
return $rows
'@

function Parse-DiskpartTable {
    param([string[]]$OutLines, [string]$RowRx)
    return (& ([scriptblock]::Create($script:ParseDpTableSrc)) $OutLines $RowRx)
}

$script:GetDynDisksSrc = @'
param($dpSrc, $parseSrc)
$raw = & ([scriptblock]::Create($dpSrc)) @("list disk")
$lns = @($raw -split "`r?`n")
$rows = & ([scriptblock]::Create($parseSrc)) $lns '^\s*\*?\s*Disk\s+\d+\s+'
$map = @{}
foreach ($r in $rows) {
    if ($r[0] -match 'Disk\s+(\d+)') {
        $dn = [int]$Matches[1]
        $freeBytes = 0.0
        if ($r.Count -ge 4 -and $r[3] -match '([\d\.,]+)\s*(TB|GB|MB|KB|B)\b') {
            $fv = [double]($Matches[1] -replace ',', '.')
            switch ($Matches[2].ToUpper()) { 'TB' { $freeBytes = $fv * 1TB } 'GB' { $freeBytes = $fv * 1GB } 'MB' { $freeBytes = $fv * 1MB } 'KB' { $freeBytes = $fv * 1KB } default { $freeBytes = $fv } }
        }
        $map[$dn] = @{
            Status    = $r[1]
            IsDynamic = ($r.Count -ge 5 -and $r[4] -match '\*')
            IsGpt     = ($r.Count -ge 6 -and $r[5] -match '\*')
            FreeMB    = [int][math]::Floor($freeBytes / 1MB)
        }
    }
}
return $map
'@

$script:BuildDynScriptSrc = @'
param([string]$VolType, [int[]]$DiskNumbers, [bool[]]$IsDynamicFlags, [int]$SizePerDiskMB, [int[]]$AvailMBs, [string]$Letter, [string]$FileSystem = 'NTFS', [string]$Label = '', [bool]$QuickFormat = $true)
$cmds = New-Object 'System.Collections.Generic.List[string]'
for ($i = 0; $i -lt $DiskNumbers.Count; $i++) {
    if (-not $IsDynamicFlags[$i]) {
        $cmds.Add("select disk $($DiskNumbers[$i])")
        $cmds.Add("convert dynamic")
    }
}
$minAvail = ($AvailMBs | Measure-Object -Minimum).Minimum
$omitSz = ($SizePerDiskMB -le 0 -or $SizePerDiskMB -ge ($minAvail - 64))
$szArg = if ($omitSz) { "" } else { " size=$SizePerDiskMB" }
$diskCsv = ($DiskNumbers -join ',')

switch ($VolType) {
    'Simple' {
        $cmds.Add("select disk $($DiskNumbers[0])")
        $cmds.Add("create volume simple$szArg")
    }
    'Spanned' {
        $cmds.Add("select disk $($DiskNumbers[0])")
        $cmds.Add("create volume simple$szArg")
        for ($i = 1; $i -lt $DiskNumbers.Count; $i++) {
            $avI = $AvailMBs[$i]
            $extSz = if ($SizePerDiskMB -le 0 -or $SizePerDiskMB -ge ($avI - 64)) { "" } else { " size=$SizePerDiskMB" }
            $cmds.Add("extend$extSz disk=$($DiskNumbers[$i])")
        }
    }
    'Striped'  { $cmds.Add("create volume stripe$szArg disk=$diskCsv") }
    'Mirrored' { $cmds.Add("create volume mirror$szArg disk=$diskCsv") }
    'RAID-5'   { $cmds.Add("create volume raid$szArg disk=$diskCsv") }
}
$cmds.Add("assign letter=$Letter")
$lblClean = ([string]$Label -replace '"', '').Trim()
$fmtCmd = "format fs=$($FileSystem.ToLower())" + $(if ($QuickFormat) { " quick" } else { "" }) + $(if ($lblClean) { " label=`"$lblClean`"" } else { "" })
$cmds.Add($fmtCmd)
return $cmds.ToArray()
'@

function Build-DynamicVolumeDiskpartScript {
    param([string]$VolType, [int[]]$DiskNumbers, [bool[]]$IsDynamicFlags, [int]$SizePerDiskMB, [int[]]$AvailMBs, [string]$Letter, [string]$FileSystem = 'NTFS', [string]$Label = '', [bool]$QuickFormat = $true)
    return (& ([scriptblock]::Create($script:BuildDynScriptSrc)) $VolType $DiskNumbers $IsDynamicFlags $SizePerDiskMB $AvailMBs $Letter $FileSystem $Label $QuickFormat)
}

function Invoke-DiskCreateVolume {
    param(
        [string]$Srv,
        [string]$VolType,
        [int[]]$DiskNumbers,
        [int]$SizePerDiskMB,
        [string]$Letter,
        [string]$FileSystem = 'NTFS',
        [string]$Label = 'New Volume',
        [bool]$QuickFormat = $true
    )
    $dns = @($DiskNumbers | Select-Object -Unique)
    $let = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    $fs  = if ($FileSystem) { [string]$FileSystem } else { 'NTFS' }
    $lbl = ([string]$Label).Trim()
    if ($let -notmatch '^[A-Z]$') { Show-Msg "Ký tự ổ đĩa không hợp lệ." "Chưa hợp lệ" "Warning"; return $false }
    if ($fs -eq 'FAT32' -and $lbl.Length -gt 11) { Show-Msg "Nhãn ổ FAT32 tối đa 11 ký tự." "Chưa hợp lệ" "Warning"; return $false }
    if ($lbl.Length -gt 32) { Show-Msg "Nhãn ổ tối đa 32 ký tự." "Chưa hợp lệ" "Warning"; return $false }
    if ($VolType -eq 'Simple' -and $dns.Count -lt 1) { Show-Msg "Chọn ít nhất 1 Disk." "Chưa hợp lệ" "Warning"; return $false }
    if ($VolType -in @('Spanned', 'Striped') -and $dns.Count -lt 2) { Show-Msg "$VolType Volume cần ít nhất 2 Disk." "Chưa hợp lệ" "Warning"; return $false }
    if ($VolType -eq 'Mirrored' -and $dns.Count -ne 2) { Show-Msg "Mirrored Volume (RAID-1) cần đúng 2 Disk." "Chưa hợp lệ" "Warning"; return $false }
    if ($VolType -eq 'RAID-5' -and $dns.Count -lt 3) { Show-Msg "RAID-5 Volume cần ít nhất 3 Disk." "Chưa hợp lệ" "Warning"; return $false }
    $approxTotalMB = switch ($VolType) {
        'Spanned' { $SizePerDiskMB * $dns.Count }
        'Striped' { $SizePerDiskMB * $dns.Count }
        'RAID-5'  { $SizePerDiskMB * ($dns.Count - 1) }
        default   { $SizePerDiskMB }
    }
    if ($fs -eq 'FAT32' -and $approxTotalMB -gt 32768) {
        Show-Msg "Windows chỉ hỗ trợ định dạng FAT32 tối đa 32 GB." "Chưa hợp lệ" "Warning"; return $false
    }

    $dynNote = if ($VolType -ne 'Simple') { "`r`n⚠ Lưu ý: Các Disk Basic được chọn sẽ tự động chuyển sang Dynamic Disk để tạo $VolType Volume." } else { "" }
    $plan = "Tạo $VolType Volume (${let}:, $fs, nhãn '$lbl', ~${SizePerDiskMB} MB/đĩa) trên Disk: $($dns -join ', ')$dynNote"
    $ok = Invoke-PCAction $Srv "Tạo $VolType Volume" $plan {
        param($vt, $nums, $mbPerDisk, $nLet, $fsTyp, $vLbl, $quick, $dpSrc, $parseSrc, $buildSrc, $getDynSrc)
        if (Get-Partition -DriveLetter $nLet -ErrorAction SilentlyContinue) { throw "Ký tự ổ ${nLet}: đã được sử dụng." }
        if (Get-Volume -DriveLetter $nLet -ErrorAction SilentlyContinue) { throw "Ký tự ổ ${nLet}: đang tồn tại." }
        if ([System.IO.DriveInfo]::GetDrives() | Where-Object { $_.Name -like "${nLet}:*" }) { throw "Ký tự ổ ${nLet}: đang được gắn." }

        $dpExec = [scriptblock]::Create($dpSrc)
        $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
        $diskObjs = @()
        foreach ($n in @($nums)) {
            $ni = [int]$n
            $d = Get-CimInstance -Namespace root\Microsoft\Windows\Storage -ClassName MSFT_Disk -Filter "Number=$ni" -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($d) {
                $stRaw = [string]$d.PartitionStyle
                $stName = switch ($stRaw) { '0' { 'RAW' } '1' { 'MBR' } '2' { 'GPT' } default { $stRaw.ToUpper() } }
                $busRaw = [string]$d.BusType
                $busName = switch ($busRaw) { '7' { 'USB' } '12' { 'SD' } '13' { 'MMC' } '15' { 'File Backed Virtual' } '17' { 'NVMe' } default { $busRaw } }
                if ($d.IsReadOnly) { throw "Disk $ni đang ở chế độ Read-Only." }
                if ($stName -eq 'RAW') { throw "Disk $ni chưa khởi tạo (RAW) — hãy Initialize Disk trước." }
                $isDyn = [bool](($dpMap.ContainsKey($ni) -and $dpMap[$ni].IsDynamic) -or (@(Get-Partition -DiskNumber $ni -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 }).Count -gt 0))
                if ($vt -ne 'Simple') {
                    if ($d.IsSystem -or $d.IsBoot) { throw "BỊ CHẶN: Không được phép đưa Disk hệ thống/khởi động (Disk $ni) vào mảng $vt / Dynamic trên tool." }
                    if ($busName -in @('File Backed Virtual', 'USB', 'SD', 'MMC')) {
                        throw "BỊ CHẶN: Windows không hỗ trợ chuyển ổ đĩa chuẩn $busName (USB / File VHDX) sang Dynamic Disk."
                    }
                }
                if ($d.IsOffline) { Set-Disk -Number $ni -IsOffline $false -ErrorAction Stop; $d = Get-CimInstance -Namespace root\Microsoft\Windows\Storage -ClassName MSFT_Disk -Filter "Number=$ni" -ErrorAction SilentlyContinue | Select-Object -First 1 }
                $dModel = [pscustomobject]@{ Number = $ni; PartitionStyle = $stName; LargestFreeExtent = [double]$d.LargestFreeExtent }
                $diskObjs += [pscustomobject]@{ Disk = $dModel; IsDynamic = $isDyn }
            }
            elseif ($dpMap.ContainsKey($ni) -and $dpMap[$ni].IsDynamic) {
                if ($dpMap[$ni].Status -match '(?i)Offline') {
                    [void](& $dpExec @("select disk $ni", "online disk"))
                }
                $dModel = [pscustomobject]@{
                    Number = $ni
                    PartitionStyle = $(if ($dpMap[$ni].IsGpt) { 'GPT' } else { 'MBR' })
                    LargestFreeExtent = ([double]$dpMap[$ni].FreeMB * 1MB)
                }
                $diskObjs += [pscustomobject]@{ Disk = $dModel; IsDynamic = $true }
            }
            else {
                throw "Không tìm thấy Disk $ni."
            }
        }

        if ($vt -eq 'Simple' -and -not $diskObjs[0].IsDynamic) {
            $d0 = $diskObjs[0].Disk
            if ($d0.PartitionStyle -eq 'MBR' -and @(Get-Partition -DiskNumber $d0.Number).Count -ge 4) {
                throw "Disk MBR $($d0.Number) đã đủ tối đa 4 phân vùng chính."
            }
            $reqBytes = [uint64]$mbPerDisk * 1MB
            $freeExt = [uint64]$d0.LargestFreeExtent
            if ($freeExt -lt 10MB) { throw "Disk $($d0.Number) không còn vùng trống Unallocated." }
            $np = if ($reqBytes -ge ($freeExt - 32MB)) {
                if ($reqBytes -le ($freeExt + 128MB)) {
                    New-Partition -DiskNumber $d0.Number -UseMaximumSize -DriveLetter $nLet -ErrorAction Stop
                } else {
                    throw "Không đủ dung lượng trống trên Disk $($d0.Number) (khả dụng: $([math]::Floor($freeExt / 1MB)) MB)."
                }
            } else {
                New-Partition -DiskNumber $d0.Number -Size $reqBytes -DriveLetter $nLet -ErrorAction Stop
            }
            $fp = @{ Partition = $np; FileSystem = $fsTyp; Confirm = $false; ErrorAction = 'Stop' }
            if ($vLbl) { $fp.NewFileSystemLabel = $vLbl }
            if (-not $quick) { $fp.Full = $true }
            Format-Volume @fp | Out-Null
            Write-Output "Đã tạo Simple Volume ${nLet}: ($([math]::Round($np.Size / 1GB, 2)) GB, $fsTyp) trên Disk $($d0.Number)."
            return
        }

        # Dynamic Disk path (Simple on Dynamic, Spanned, Striped, Mirrored, RAID-5)
        $dynFlags = @($diskObjs | ForEach-Object { [bool]$_.IsDynamic })
        $availArr = @($diskObjs | ForEach-Object {
            $dn = [int]$_.Disk.Number
            if ($dpMap.ContainsKey($dn) -and $dpMap[$dn].FreeMB -gt 0) { [int]$dpMap[$dn].FreeMB } else { [int][math]::Floor($_.Disk.LargestFreeExtent / 1MB) }
        })
        $cmds = & ([scriptblock]::Create($buildSrc)) $vt $nums $dynFlags $mbPerDisk $availArr $nLet $fsTyp $vLbl $quick
        [void](& $dpExec $cmds)
        Write-Output "Đã tạo $vt Volume ${nLet}: ($fsTyp) trên Disk: $($nums -join ',')."
    } @($VolType, $dns, $SizePerDiskMB, $let, $fs, $lbl, $QuickFormat, $script:DpExecSrc, $script:ParseDpTableSrc, $script:BuildDynScriptSrc, $script:GetDynDisksSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskExtendVolume {
    param([string]$Srv, [string]$Letter, [int]$AddMB, [int]$TargetDisk = -1)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Volume cần mở rộng phải có ký tự ổ đĩa." "Chưa hợp lệ" "Warning"; return $false }
    if ($AddMB -lt 1) { Show-Msg "Dung lượng mở rộng phải >= 1 MB." "Chưa hợp lệ" "Warning"; return $false }
    $plan = "Mở rộng ổ ${srcLet}: thêm ${AddMB} MB" + $(if ($TargetDisk -ge 0) { " trên Disk $TargetDisk" } else { "" })
    $ok = Invoke-PCAction $Srv "Mở rộng Volume (Extend)" $plan {
        param($let, $mb, $tDisk, $dpSrc, $getDynSrc, $parseSrc)
        $p = Get-Partition -DriveLetter $let -ErrorAction SilentlyContinue
        if ($p) {
            $d = Get-Disk -Number $p.DiskNumber -ErrorAction Stop
            $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
            $isDyn = (($dpMap.ContainsKey([int]$d.Number) -and $dpMap[[int]$d.Number].IsDynamic) -or $p.Type -match 'LDM|Logical Disk Manager' -or $p.MbrType -eq 66 -or @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 }).Count -gt 0)
            if (-not $isDyn) {
                if ($d.IsReadOnly) { throw "Disk $($d.Number) đang ở chế độ Read-Only." }
                $sup = Get-PartitionSupportedSize -DriveLetter $let -ErrorAction Stop
                $targetSize = [uint64]$p.Size + ([uint64]$mb * 1MB)
                if ($targetSize -gt $sup.SizeMax) {
                    if (($targetSize - $sup.SizeMax) -le 64MB -and $sup.SizeMax -gt $p.Size) {
                        $targetSize = $sup.SizeMax
                    } else {
                        $maxAdd = [math]::Max(0, [math]::Floor(([double]$sup.SizeMax - [double]$p.Size) / 1MB))
                        throw "Không đủ dung lượng trống liền kề để mở rộng thêm ${mb} MB (tối đa: ${maxAdd} MB)."
                    }
                }
                Resize-Partition -DriveLetter $let -Size $targetSize -ErrorAction Stop
                Write-Output "Đã mở rộng ổ ${let}: thêm $([math]::Round(([double]$targetSize - [double]$p.Size) / 1MB)) MB."
                return
            }
        }
        $dpExec = [scriptblock]::Create($dpSrc)
        $extCmd = "extend size=$mb" + $(if ($tDisk -ge 0) { " disk=$tDisk" } else { "" })
        [void](& $dpExec @("select volume $let", $extCmd))
        Write-Output "Đã mở rộng Volume ${let}: thêm ${mb} MB."
    } @($srcLet, $AddMB, $TargetDisk, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskShrinkVolume {
    param([string]$Srv, [string]$Letter, [int]$ShrinkMB)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Volume cần thu nhỏ phải có ký tự ổ đĩa." "Chưa hợp lệ" "Warning"; return $false }
    if ($ShrinkMB -lt 1) { Show-Msg "Dung lượng thu nhỏ phải >= 1 MB." "Chưa hợp lệ" "Warning"; return $false }
    $isLocal = (-not $Srv) -or ($Srv -in @('.', 'localhost', '127.0.0.1', '::1', $env:COMPUTERNAME))
    $osWarn = if ($isLocal -and "${srcLet}:" -ieq $env:SystemDrive) { "`r`n⚠ CẢNH BÁO: Ổ ${srcLet}: là ổ HỆ ĐIỀU HÀNH (giữ lại ít nhất 2 GB trống an toàn)." } else { "" }
    $plan = "Thu nhỏ ổ ${srcLet}: đi ${ShrinkMB} MB thành dung lượng trống (Unallocated)$osWarn"
    $ok = Invoke-PCAction $Srv "Thu nhỏ Volume (Shrink)" $plan {
        param($let, $mb, $dpSrc, $getDynSrc, $parseSrc)
        $p = Get-Partition -DriveLetter $let -ErrorAction SilentlyContinue
        if ($p) {
            $d = Get-Disk -Number $p.DiskNumber -ErrorAction Stop
            $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
            $isDyn = (($dpMap.ContainsKey([int]$d.Number) -and $dpMap[[int]$d.Number].IsDynamic) -or $p.Type -match 'LDM|Logical Disk Manager' -or $p.MbrType -eq 66 -or @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 }).Count -gt 0)
            if (-not $isDyn) {
                if ($d.IsReadOnly) { throw "Disk $($d.Number) đang ở chế độ Read-Only." }
                $sup = Get-PartitionSupportedSize -DriveLetter $let -ErrorAction Stop
                $reqBytes = [uint64]$mb * 1MB
                if ($reqBytes -ge $p.Size) { throw "Dung lượng thu nhỏ phải nhỏ hơn dung lượng hiện tại của ổ ${let}:." }
                $minFloor = [uint64]$sup.SizeMin
                if ($p.IsBoot -or $p.IsSystem -or $d.IsSystem) {
                    $safeFloor = [uint64]$sup.SizeMin + [uint64]2GB
                    if ($safeFloor -lt $p.Size) { $minFloor = $safeFloor }
                }
                $newSize = [uint64]$p.Size - $reqBytes
                if ($newSize -lt $minFloor) {
                    $maxShrink = [math]::Max(0, [math]::Floor(([double]$p.Size - [double]$minFloor) / 1MB))
                    throw "Không đủ dung lượng trống liên tục để thu nhỏ ${mb} MB (tối đa an toàn hiện tại: ${maxShrink} MB)."
                }
                Resize-Partition -DriveLetter $let -Size $newSize -ErrorAction Stop
                Write-Output "Đã thu nhỏ ổ ${let}: đi ${mb} MB thành vùng trống (Unallocated)."
                return
            }
        }
        $v = Get-Volume -DriveLetter $let -ErrorAction Stop
        if (("${let}:" -ieq $env:SystemDrive) -and ($v.SizeRemaining - ([uint64]$mb * 1MB)) -lt 2GB) {
            throw "BỊ CHẶN: Phải giữ ít nhất 2 GB trống an toàn trên ổ hệ điều hành (${let}:)."
        }
        $dpExec = [scriptblock]::Create($dpSrc)
        [void](& $dpExec @("select volume $let", "shrink desired=$mb"))
        Write-Output "Đã thu nhỏ Dynamic Volume ${let}: đi ${mb} MB."
    } @($srcLet, $ShrinkMB, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskFormatVolume {
    param([string]$Srv, [string]$Letter, [string]$FileSystem = 'NTFS', [string]$Label = '', [bool]$QuickFormat = $true)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    $fs = if ($FileSystem) { [string]$FileSystem } else { 'NTFS' }
    $lbl = ([string]$Label).Trim()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Chọn phân vùng cần Format." "Chưa hợp lệ" "Warning"; return $false }
    if ($fs -eq 'FAT32' -and $lbl.Length -gt 11) { Show-Msg "Nhãn ổ FAT32 tối đa 11 ký tự." "Chưa hợp lệ" "Warning"; return $false }
    if ($lbl.Length -gt 32) { Show-Msg "Nhãn ổ tối đa 32 ký tự." "Chưa hợp lệ" "Warning"; return $false }
    $plan = "Định dạng (Format) ổ ${srcLet}: sang $fs (nhãn: '$lbl')`r`n⚠ CẢNH BÁO NGUY HIỂM: Toàn bộ dữ liệu hiện có trên ổ ${srcLet}: sẽ bị XÓA SẠCH!"
    $ok = Invoke-PCAction $Srv "Định dạng Volume (Format)" $plan {
        param($let, $fsTyp, $vLbl, $quick)
        if ("${let}:" -ieq $env:SystemDrive) { throw "BỊ CHẶN: Không được phép Format ổ hệ điều hành (${let}:)." }
        $p = Get-Partition -DriveLetter $let -ErrorAction SilentlyContinue
        if ($p) {
            $d = Get-Disk -Number $p.DiskNumber -ErrorAction Stop
            if ($p.IsBoot -or $p.IsSystem -or $d.IsSystem) { throw "BỊ CHẶN: Không được phép Format phân vùng/ổ hệ điều hành (${let}:)." }
            if ($d.IsReadOnly) { throw "Disk $($d.Number) đang ở chế độ Read-Only." }
        }
        $v = Get-Volume -DriveLetter $let -ErrorAction Stop
        if ($fsTyp -eq 'FAT32' -and $v.Size -gt 32GB) { throw "BỊ CHẶN: Windows không hỗ trợ Format FAT32 > 32 GB." }
        $fp = @{ DriveLetter = $let; FileSystem = $fsTyp; Confirm = $false; ErrorAction = 'Stop' }
        if ($vLbl) { $fp.NewFileSystemLabel = $vLbl }
        if (-not $quick) { $fp.Full = $true }
        Format-Volume @fp | Out-Null
        Write-Output "Đã Format ổ ${let}: thành $fsTyp (nhãn: '$vLbl')."
    } @($srcLet, $fs, $lbl, $QuickFormat) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskChangeLetter {
    param([string]$Srv, [string]$OldLetter, [string]$NewLetter)
    $o = ([string]$OldLetter).Trim().TrimEnd(':').ToUpper()
    $n = ([string]$NewLetter).Trim().TrimEnd(':').ToUpper()
    if ($o -notmatch '^[A-Z]$' -or $n -notmatch '^[A-Z]$') { Show-Msg "Ký tự ổ đĩa không hợp lệ." "Chưa hợp lệ" "Warning"; return $false }
    if ($o -eq $n) { Show-Msg "Ký tự mới trùng ký tự cũ ($o)." "Chưa hợp lệ" "Warning"; return $false }
    $plan = "Đổi ký tự ổ đĩa ${o}: sang ${n}:`r`n(Không làm mất dữ liệu trên Volume)"
    $ok = Invoke-PCAction $Srv "Đổi ký tự ổ đĩa" $plan {
        param($oldL, $newL, $dpSrc, $getDynSrc, $parseSrc)
        if ("${oldL}:" -ieq $env:SystemDrive) { throw "BỊ CHẶN: Không được phép đổi ký tự ổ hệ điều hành/khởi động (${oldL}:)." }
        $p = Get-Partition -DriveLetter $oldL -ErrorAction SilentlyContinue
        if ($p -and ($p.IsBoot -or $p.IsSystem)) { throw "BỊ CHẶN: Không được phép đổi ký tự ổ hệ điều hành/khởi động (${oldL}:)." }
        if (Get-Partition -DriveLetter $newL -ErrorAction SilentlyContinue) { throw "Ký tự ổ ${newL}: đã được sử dụng." }
        if (Get-Volume -DriveLetter $newL -ErrorAction SilentlyContinue) { throw "Ký tự ổ ${newL}: đang tồn tại." }
        if ([System.IO.DriveInfo]::GetDrives() | Where-Object { $_.Name -like "${newL}:*" }) { throw "Ký tự ổ ${newL}: đang được gắn." }
        $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
        $isDyn = ($p -and (($dpMap.ContainsKey([int]$p.DiskNumber) -and $dpMap[[int]$p.DiskNumber].IsDynamic) -or $p.Type -match 'LDM|Logical Disk Manager' -or $p.MbrType -eq 66))
        if ($p -and -not $isDyn) {
            Set-Partition -DriveLetter $oldL -NewDriveLetter $newL -ErrorAction Stop
        } else {
            $dpExec = [scriptblock]::Create($dpSrc)
            [void](& $dpExec @("select volume $oldL", "assign letter=$newL"))
        }
        Write-Output "Đã đổi ký tự ổ ${oldL}: thành ${newL}:."
    } @($o, $n, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskRenameLabel {
    param([string]$Srv, [string]$Letter, [string]$NewLabel)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    $lbl = ([string]$NewLabel).Trim()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Chọn phân vùng có ký tự ổ đĩa." "Chưa hợp lệ" "Warning"; return $false }
    $plan = "Đổi nhãn tên ổ ${srcLet}: thành '$lbl'"
    $ok = Invoke-PCAction $Srv "Đổi nhãn ổ đĩa" $plan {
        param($let, $vLbl)
        $v = Get-Volume -DriveLetter $let -ErrorAction Stop
        if ($v.FileSystem -eq 'FAT32' -and $vLbl.Length -gt 11) { throw "Nhãn ổ FAT32 tối đa 11 ký tự." }
        if ($vLbl.Length -gt 32) { throw "Nhãn ổ tối đa 32 ký tự." }
        Set-Volume -DriveLetter $let -NewFileSystemLabel $vLbl -ErrorAction Stop
        Write-Output "Đã đổi nhãn ổ ${let}: thành '$vLbl'."
    } @($srcLet, $lbl) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskDeleteVolume {
    param([string]$Srv, [string]$Letter, [int]$VolNum = -1, [bool]$ForceDiskpart = $false)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    $targetId = if ($srcLet -match '^[A-Z]$') { "${srcLet}:" } elseif ($VolNum -ge 0) { "Volume $VolNum" } else { "" }
    if (-not $targetId) { Show-Msg "Không xác định được phân vùng/Volume cần xóa." "Chưa hợp lệ" "Warning"; return $false }
    $plan = "XÓA VĨNH VIỄN $targetId thành vùng trống (Unallocated)`r`n⚠ CẢNH BÁO NGUY HIỂM: Toàn bộ dữ liệu trên $targetId sẽ bị XÓA SẠCH!"
    $ok = Invoke-PCAction $Srv "Xóa Volume (Delete Volume)" $plan {
        param($let, $vn, $useDp, $dpSrc, $getDynSrc, $parseSrc)
        if ($let -and "${let}:" -ieq $env:SystemDrive) { throw "BỊ CHẶN: Không được phép xóa phân vùng hệ điều hành/khởi động (${let}:)." }
        $p = if ($let) { Get-Partition -DriveLetter $let -ErrorAction SilentlyContinue } else { $null }
        if ($p) {
            $d = Get-Disk -Number $p.DiskNumber -ErrorAction Stop
            if ($p.IsBoot -or $p.IsSystem -or $p.Type -in @('Recovery', 'System', 'Reserved') -or $d.IsSystem) {
                throw "BỊ CHẶN: Không được phép xóa phân vùng hệ thống/khởi động/Recovery (${let}:)."
            }
            if ($d.IsReadOnly) { throw "Disk $($d.Number) đang ở chế độ Read-Only." }
            $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
            $isDyn = (($dpMap.ContainsKey([int]$d.Number) -and $dpMap[[int]$d.Number].IsDynamic) -or $p.Type -match 'LDM|Logical Disk Manager' -or $p.MbrType -eq 66 -or @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 }).Count -gt 0)
            if (-not $useDp -and -not $isDyn) {
                Remove-Partition -DriveLetter $let -Confirm:$false -ErrorAction Stop
                Write-Output "Đã xóa phân vùng ${let}: thành dung lượng trống (Unallocated)."
                return
            }
        }
        $dpExec = [scriptblock]::Create($dpSrc)
        $sel = if ($let) { "select volume $let" } else { "select volume $vn" }
        $det = & $dpExec @($sel, "detail volume")
        if ($det -match '(?i)Boot Disk\s*:\s*Yes' -or $det -match '(?i)Pagefile Disk\s*:\s*Yes' -or ($let -and "${let}:" -ieq $env:SystemDrive)) {
            throw "BỊ CHẶN: Không được phép xóa Volume hệ thống/khởi động."
        }
        [void](& $dpExec @($sel, "delete volume"))
        Write-Output "Đã xóa Volume $(if ($let) { "${let}:" } else { $vn }) thành dung lượng trống."
    } @($srcLet, $VolNum, $ForceDiskpart, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskAddMirror {
    param([string]$Srv, [string]$Letter, [int]$TargetDisk)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Volume nguồn phải có ký tự ổ đĩa." "Chưa hợp lệ" "Warning"; return $false }
    $plan = "Thêm bản sao gương (Add Mirror - RAID-1) cho ổ ${srcLet}: sang Disk $TargetDisk`r`n⚠ Lưu ý: Nếu Disk còn ở chuẩn Basic sẽ được tự động chuyển sang Dynamic Disk."
    $ok = Invoke-PCAction $Srv "Thêm Mirror (RAID-1)" $plan {
        param($let, $tDisk, $dpSrc, $getDynSrc, $parseSrc)
        if ("${let}:" -ieq $env:SystemDrive) { throw "BỊ CHẶN: Tool không cho phép chuyển Disk hệ thống sang Dynamic/Mirror tự động." }
        $ti = [int]$tDisk
        $dpExec = [scriptblock]::Create($dpSrc)
        $dpMap = & ([scriptblock]::Create($getDynSrc)) $dpSrc $parseSrc
        $tDyn = $false
        $dT = Get-CimInstance -Namespace root\Microsoft\Windows\Storage -ClassName MSFT_Disk -Filter "Number=$ti" -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($dT) {
            $stT = switch ([string]$dT.PartitionStyle) { '0' { 'RAW' } '1' { 'MBR' } '2' { 'GPT' } default { ([string]$dT.PartitionStyle).ToUpper() } }
            $busT = switch ([string]$dT.BusType) { '7' { 'USB' } '12' { 'SD' } '13' { 'MMC' } '15' { 'File Backed Virtual' } '17' { 'NVMe' } default { [string]$dT.BusType } }
            if ($dT.IsSystem -or $dT.IsBoot) { throw "BỊ CHẶN: Không được chọn Disk hệ thống làm Mirror." }
            if ($busT -in @('File Backed Virtual', 'USB', 'SD', 'MMC')) { throw "BỊ CHẶN: Windows không hỗ trợ chuyển ổ đĩa chuẩn $busT (USB / File VHDX) sang Dynamic Disk." }
            if ($dT.IsReadOnly) { throw "Disk $ti đang ở chế độ Read-Only." }
            if ($stT -eq 'RAW') { throw "Disk $ti chưa khởi tạo (RAW)." }
            if ($dT.IsOffline) { Set-Disk -Number $ti -IsOffline $false -ErrorAction Stop }
            $tDyn = (($dpMap.ContainsKey($ti) -and $dpMap[$ti].IsDynamic) -or (@(Get-Partition -DiskNumber $ti -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 }).Count -gt 0))
        }
        elseif ($dpMap.ContainsKey($ti) -and $dpMap[$ti].IsDynamic) {
            $tDyn = $true
            if ($dpMap[$ti].Status -match '(?i)Offline') { [void](& $dpExec @("select disk $ti", "online disk")) }
        }
        else { throw "Không tìm thấy Disk $ti." }

        $cmds = New-Object 'System.Collections.Generic.List[string]'
        $pSrc = Get-Partition -DriveLetter $let -ErrorAction SilentlyContinue
        if ($pSrc) {
            $si = [int]$pSrc.DiskNumber
            if ($si -eq $ti) { throw "Không thể tạo Mirror trên cùng một Disk ($ti)." }
            $dS = Get-CimInstance -Namespace root\Microsoft\Windows\Storage -ClassName MSFT_Disk -Filter "Number=$si" -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($dS) {
                $busS = switch ([string]$dS.BusType) { '7' { 'USB' } '12' { 'SD' } '13' { 'MMC' } '15' { 'File Backed Virtual' } '17' { 'NVMe' } default { [string]$dS.BusType } }
                if ($dS.IsSystem -or $dS.IsBoot) { throw "BỊ CHẶN: Không thao tác Dynamic trên Disk hệ thống." }
                if ($busS -in @('File Backed Virtual', 'USB', 'SD', 'MMC')) { throw "BỊ CHẶN: Windows không hỗ trợ chuyển ổ đĩa chuẩn $busS (USB / File VHDX) sang Dynamic Disk." }
            }
            $sDyn = (($dpMap.ContainsKey($si) -and $dpMap[$si].IsDynamic) -or (@(Get-Partition -DiskNumber $si -ErrorAction SilentlyContinue | Where-Object { $_.Type -match 'LDM|Logical Disk Manager' -or $_.MbrType -eq 66 }).Count -gt 0))
            if (-not $sDyn) { $cmds.Add("select disk $si"); $cmds.Add("convert dynamic") }
        }
        if (-not $tDyn) { $cmds.Add("select disk $ti"); $cmds.Add("convert dynamic") }
        $cmds.Add("select volume $let")
        $cmds.Add("add disk=$ti")
        [void](& $dpExec $cmds.ToArray())
        Write-Output "Đã thêm Mirror cho ổ ${let}: trên Disk $ti."
    } @($srcLet, $TargetDisk, $script:DpExecSrc, $script:GetDynDisksSrc, $script:ParseDpTableSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskBreakMirror {
    param([string]$Srv, [string]$Letter, [int]$TargetDisk, [bool]$RemoveOnly = $false)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Volume phải có ký tự ổ đĩa." "Chưa hợp lệ" "Warning"; return $false }
    $actName = if ($RemoveOnly) { "Gỡ bản Mirror (Remove Mirror -> Unallocated)" } else { "Tách Mirrored Volume thành 2 Simple Volume (Break Mirror)" }
    $plan = "$actName cho ổ ${srcLet}: (Disk $TargetDisk)"
    $ok = Invoke-PCAction $Srv $actName $plan {
        param($let, $tDisk, $nokeep, $dpSrc)
        $dpExec = [scriptblock]::Create($dpSrc)
        $brkCmd = "break disk=$tDisk" + $(if ($nokeep) { " nokeep" } else { "" })
        [void](& $dpExec @("select volume $let", $brkCmd))
        Write-Output ("Đã " + $(if ($nokeep) { "gỡ" } else { "tách" }) + " Mirror trên Disk $tDisk cho ổ ${let}:.")
    } @($srcLet, $TargetDisk, $RemoveOnly, $script:DpExecSrc) -Danger -PromptDryRun
    if ($ok -and -not $chkDry.Checked) { Update-DiskInfo }
    return $ok
}

function Invoke-DiskApplyQuota {
    param([string]$Srv, [string]$Letter, [int]$LimitGB)
    $srcLet = ([string]$Letter).Trim().TrimEnd(':').ToUpper()
    if ($srcLet -notmatch '^[A-Z]$') { Show-Msg "Hãy chọn ổ đĩa NTFS có ký tự (vd: E) để bật Quota." "Chưa hợp lệ" "Warning"; return $false }
    $isLocal = (-not $Srv) -or ($Srv -in @('.', 'localhost', '127.0.0.1', '::1', $env:COMPUTERNAME))
    $osWarnQ = ""
    if ($isLocal -and "${srcLet}:" -ieq $env:SystemDrive) {
        $osWarnQ = "`r`n⚠ CẢNH BÁO NGUY HIỂM: Ổ ${srcLet}: là ổ HỆ ĐIỀU HÀNH!"
        if (-not $chkDry.Checked) {
            if (-not (Confirm-Msg "⚠ CẢNH BÁO NGUY HIỂM: Ổ ${srcLet}: là ổ HỆ ĐIỀU HÀNH!`r`nBật NTFS Quota (Enforce) giới hạn ${LimitGB} GB trên ổ hệ điều hành có thể làm lỗi Windows / Active Directory.`r`n`r`nTiếp tục?" "Cảnh báo ổ hệ điều hành" "Warning")) { return $false }
        }
    }
    $limB  = [int64]$LimitGB * 1GB
    $warnB = [int64][math]::Floor($limB * 0.8)
    $plan  = "Bật NTFS Disk Quota (Enforce) trên ổ ${srcLet}: | Giới hạn: ${LimitGB} GB | Cảnh báo: $([math]::Round($warnB/1GB, 2)) GB$osWarnQ"
    return (Invoke-PCAction $Srv "Bật NTFS Disk Quota" $plan {
        param($let, $wb, $lb)
        $v = Get-Volume -DriveLetter $let -ErrorAction Stop
        if ($v.DriveType -ne 'Fixed') { throw "Chỉ áp NTFS Quota cho ổ đĩa cố định." }
        if ($v.FileSystem -ne 'NTFS') { throw "Chỉ hỗ trợ NTFS Quota trên định dạng NTFS (ổ ${let}: đang là $($v.FileSystem))." }
        $r1 = & fsutil quota enforce "${let}:" 2>&1
        if ($LASTEXITCODE -ne 0) { throw ("fsutil enforce lỗi: " + ($r1 -join ' ')) }
        $qs = Get-CimInstance -ClassName Win32_QuotaSetting -ErrorAction SilentlyContinue | Where-Object { $_.VolumePath -eq "${let}:\" }
        if ($qs) {
            $qs.State = 2; $qs.DefaultLimit = [int64]$lb; $qs.DefaultWarningLimit = [int64]$wb
            $qs.ExceededNotification = $true; $qs.WarningExceededNotification = $true
            $qs | Set-CimInstance -ErrorAction Stop | Out-Null
        } else {
            $dq = $null
            try {
                $dq = New-Object -ComObject Microsoft.DiskQuota.1
                $dq.Initialize("${let}:\", $true)
                $dq.DefaultQuotaLimit = [double]$lb; $dq.DefaultQuotaThreshold = [double]$wb
                $dq.LogQuotaThreshold = $true; $dq.LogQuotaLimit = $true; $dq.QuotaState = 2
            } finally { if ($null -ne $dq) { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($dq) } }
        }
        Write-Output "Đã bật NTFS Disk Quota (Enforce) mặc định trên ổ ${let}: (Cảnh báo: $([math]::Round($wb/1GB,2)) GB, Giới hạn: $([math]::Round($lb/1GB,2)) GB)."
    } @($srcLet, $warnB, $limB) -Danger -PromptDryRun)
}

function Show-NewVolumeWizard {
    param([string]$VolType = 'Simple', [int]$PreDisk = -1)
    if (-not $script:LastDiskData -or -not $script:LastDiskData.Disks) { Update-DiskInfo }
    $disks = @($script:LastDiskData.Disks | Where-Object {
        -not $_.IsOffline -and $_.Style -ne 'RAW' -and ($_.FreeBytes -ge 16MB -or $_.FreeExtBytes -ge 16MB) -and
        ($VolType -eq 'Simple' -or (-not $_.IsSystem -and $_.BusType -notin @('File Backed Virtual', 'USB', 'SD', 'MMC')))
    })
    if ($disks.Count -eq 0) { Show-Msg "Không có Disk nào còn dung lượng trống (Unallocated >= 16 MB) phù hợp." "Không thể tạo Volume" "Warning"; return }
    $minDisks = switch ($VolType) { 'Spanned' { 2 } 'Striped' { 2 } 'Mirrored' { 2 } 'RAID-5' { 3 } default { 1 } }
    if ($disks.Count -lt $minDisks) {
        Show-Msg "Tạo $VolType Volume cần tối thiểu $minDisks Disk không phải OS có vùng trống Unallocated (hiện có $($disks.Count) Disk)." "Chưa đủ Disk" "Warning"; return
    }
    $freeLets = @($script:LastDiskData.FreeLetters)
    if ($freeLets.Count -eq 0) { Show-Msg "Không còn ký tự ổ đĩa trống (D..Z)." "Chưa hợp lệ" "Warning"; return }

    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = "New $VolType Volume Wizard"
    $dlg.ClientSize = New-Object System.Drawing.Size(520, 428)
    $dlg.StartPosition = "CenterParent"
    $dlg.FormBorderStyle = "FixedDialog"
    $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
    $dlg.Font = $fontMain; $dlg.BackColor = [System.Drawing.Color]::White

    $descTxt = switch ($VolType) {
        'Simple'   { "Simple Volume: Phân vùng đơn trên 1 đĩa cứng (Basic hoặc Dynamic)." }
        'Spanned'  { "Spanned Volume: Gộp vùng trống từ 2..32 đĩa cứng thành 1 ổ duy nhất (tự chuyển sang Dynamic)." }
        'Striped'  { "Striped Volume (RAID-0): Chia sọc tốc độ cao trên 2+ đĩa (tổng dung lượng = N × mỗi đĩa)." }
        'Mirrored' { "Mirrored Volume (RAID-1): Nhân đôi dữ liệu dự phòng trên đúng 2 đĩa cứng." }
        'RAID-5'   { "RAID-5 Volume: Lưu phân tán kèm Parity chịu lỗi trên 3+ đĩa (tổng = (N - 1) × mỗi đĩa)." }
    }
    $hdr = Add-Label $dlg $descTxt 14 10 492 $true 38
    $hdr.ForeColor = [System.Drawing.Color]::FromArgb(30, 58, 95)

    [void](Add-Label $dlg "1. Chọn Disk tham gia (yêu cầu $(if($VolType -eq 'Mirrored'){'đúng 2'}else{"ít nhất $minDisks"}) đĩa):" 14 52 492 $true)
    $clb = New-Object System.Windows.Forms.CheckedListBox
    $clb.Location = New-Object System.Drawing.Point(14, 76)
    $clb.Size     = New-Object System.Drawing.Size(492, 118)
    $clb.CheckOnClick = $true
    $dlg.Controls.Add($clb)
    $diskAvailList = @()
    $preCount = 0
    foreach ($d in $disks) {
        $avB = if ($d.DiskType -eq 'Dynamic' -and $d.FreeBytes -gt 0) { [double]$d.FreeBytes } else { [double]$d.FreeExtBytes }
        $avMB = [int][Math]::Floor($avB / 1MB)
        $itemTxt = "Disk $($d.Number)  |  $($d.DiskType) ($($d.Style))  |  Trống: $avMB MB ($(Format-DiskSize $avB))"
        $idx = $clb.Items.Add($itemTxt)
        $diskAvailList += [pscustomobject]@{ Disk = $d; AvailMB = $avMB }
        if ($d.Number -eq $PreDisk -or ($VolType -ne 'Simple' -and $preCount -lt $minDisks)) {
            $clb.SetItemChecked($idx, $true); $preCount++
        }
    }
    if ($clb.CheckedIndices.Count -lt $minDisks) {
        for ($i = 0; $i -lt $clb.Items.Count -and $clb.CheckedIndices.Count -lt $minDisks; $i++) { $clb.SetItemChecked($i, $true) }
    }

    [void](Add-Label $dlg "2. Dung lượng trên mỗi Disk (MB):" 14 206 224)
    $numMB = New-Object System.Windows.Forms.NumericUpDown
    $numMB.Location = New-Object System.Drawing.Point(242, 203)
    $numMB.Size = New-Object System.Drawing.Size(108, 26)
    $numMB.Minimum = 16; $numMB.Maximum = 100000000; $numMB.Value = 1024
    $dlg.Controls.Add($numMB)
    $lblMaxMB = Add-Label $dlg "" 356 206 152
    $lblMaxMB.ForeColor = [System.Drawing.Color]::DimGray

    [void](Add-Label $dlg "3. Ký tự ổ đĩa:" 14 242 112)
    $cboL = New-Object System.Windows.Forms.ComboBox
    $cboL.Location = New-Object System.Drawing.Point(130, 239)
    $cboL.Size = New-Object System.Drawing.Size(66, 26)
    $cboL.DropDownStyle = "DropDownList"
    [void]$cboL.Items.AddRange([object[]]$freeLets)
    $cboL.SelectedIndex = 0
    $dlg.Controls.Add($cboL)

    [void](Add-Label $dlg "File system:" 210 242 84)
    $cboFS = New-Object System.Windows.Forms.ComboBox
    $cboFS.Location = New-Object System.Drawing.Point(298, 239)
    $cboFS.Size = New-Object System.Drawing.Size(92, 26)
    $cboFS.DropDownStyle = "DropDownList"
    [void]$cboFS.Items.AddRange([object[]]$(if ($VolType -eq 'Simple') { @('NTFS', 'exFAT', 'FAT32', 'ReFS') } else { @('NTFS', 'ReFS') }))
    $cboFS.SelectedIndex = 0
    $dlg.Controls.Add($cboFS)

    [void](Add-Label $dlg "Nhãn Volume:" 14 278 112)
    $txtL = New-Object System.Windows.Forms.TextBox
    $txtL.Location = New-Object System.Drawing.Point(130, 275)
    $txtL.Size = New-Object System.Drawing.Size(260, 26)
    $txtL.Text = if ($VolType -eq 'Simple') { "New Volume" } else { "$VolType Vol" }
    $dlg.Controls.Add($txtL)

    $chkQ = New-Object System.Windows.Forms.CheckBox
    $chkQ.Text = "Perform a quick format"
    $chkQ.Checked = $true
    $chkQ.Location = New-Object System.Drawing.Point(14, 312); $chkQ.Size = New-Object System.Drawing.Size(224, 24)
    $dlg.Controls.Add($chkQ)

    $lblTot = Add-Label $dlg "" 14 342 492 $true 22
    $lblTot.ForeColor = [System.Drawing.Color]::FromArgb(6, 95, 70)

    $syncWizard = {
        param([int]$OverrideIdx = -1, [bool]$OverrideChecked = $false)
        $chkIndices = @()
        for ($i = 0; $i -lt $clb.Items.Count; $i++) {
            $isChk = if ($i -eq $OverrideIdx) { $OverrideChecked } else { $clb.GetItemChecked($i) }
            if ($isChk) { $chkIndices += $i }
        }
        $sel = @($chkIndices | ForEach-Object { $diskAvailList[$_] })
        if ($sel.Count -eq 0) { $lblMaxMB.Text = "(chọn Disk)"; $lblTot.Text = "Chưa chọn Disk nào."; return }
        $minM = ($sel | Measure-Object AvailMB -Minimum).Minimum
        $lblMaxMB.Text = "(Tối đa: $minM MB)"
        $curV = [Math]::Max(16, [Math]::Min($minM, [int]$numMB.Value))
        if ($numMB.Maximum -ne [Math]::Max(16, $minM)) { $numMB.Maximum = [Math]::Max(16, $minM) }
        $totM = switch ($VolType) { 'Spanned' { $sel.Count * $curV } 'Striped' { $sel.Count * $curV } 'RAID-5' { [Math]::Max(0, $sel.Count - 1) * $curV } default { $curV } }
        $lblTot.Text = "Đã chọn $($sel.Count) Disk — Tổng dung lượng ước tính: $totM MB (~$([math]::Round($totM / 1024, 2)) GB)"
    }
    $selFirstMin = ($clb.CheckedIndices | ForEach-Object { $diskAvailList[$_].AvailMB } | Measure-Object -Minimum).Minimum
    if ($selFirstMin -ge 16) { $numMB.Maximum = $selFirstMin; $numMB.Value = $selFirstMin }
    & $syncWizard
    $clb.Add_SelectedIndexChanged({ & $syncWizard })
    $clb.Add_ItemCheck({ param($s, $e) & $syncWizard $e.Index ($e.NewValue -eq [System.Windows.Forms.CheckState]::Checked) })
    $numMB.Add_ValueChanged({ & $syncWizard })

    $btnOk = Add-Button $dlg "Finish (Tạo Volume)" 264 380 154 32
    $btnOk.Font = $fontBold; $btnOk.Tag = 'Primary'
    $btnCancel = Add-Button $dlg "Cancel" 424 380 82 32
    $btnCancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $btnOk.Add_Click({
        $cnt = $clb.CheckedIndices.Count
        if ($VolType -eq 'Mirrored' -and $cnt -ne 2) { Show-Msg "Mirrored Volume yêu cầu chọn đúng 2 Disk." "Chưa hợp lệ" "Warning"; return }
        if ($cnt -lt $minDisks) { Show-Msg "$VolType Volume yêu cầu ít nhất $minDisks Disk." "Chưa hợp lệ" "Warning"; return }
        $dlg.Tag = [pscustomobject]@{
            Disks = @($clb.CheckedIndices | ForEach-Object { $diskAvailList[$_].Disk.Number })
            MB    = [int]$numMB.Value
            Let   = [string]$cboL.SelectedItem
            FS    = [string]$cboFS.SelectedItem
            Lbl   = $txtL.Text.Trim()
            Quick = $chkQ.Checked
        }
        $dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK
        $dlg.Close()
    })
    Set-ModernButtons $dlg
    if ($dlg.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK -and $dlg.Tag) {
        $p = $dlg.Tag
        [void](Invoke-DiskCreateVolume ($txtDiskSrv.Text.Trim()) $VolType $p.Disks $p.MB $p.Let $p.FS $p.Lbl $p.Quick)
    }
    $dlg.Dispose()
}

