function Show-AddMirrorDialog {
    param([string]$Letter, [double]$VolBytes, [int[]]$CurDisks)
    $cands = @($script:LastDiskData.Disks | Where-Object {
        -not $_.IsSystem -and -not $_.IsOffline -and $_.Style -ne 'RAW' -and ($_.Number -notin $CurDisks) -and
        ([Math]::Max($_.FreeBytes, $_.FreeExtBytes) -ge ($VolBytes - 16MB))
    })
    if ($cands.Count -eq 0) { Show-Msg "Không có Disk trống khác đủ dung lượng ($((Format-DiskSize $VolBytes))) để thêm Mirror." "Chưa có Disk phù hợp" "Warning"; return }
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = "Add Mirror (${Letter}:)"
    $dlg.ClientSize = New-Object System.Drawing.Size(370, 145)
    $dlg.StartPosition = "CenterParent"; $dlg.FormBorderStyle = "FixedDialog"; $dlg.MaximizeBox = $false; $dlg.MinimizeBox = $false
    $dlg.Font = $fontMain; $dlg.BackColor = [System.Drawing.Color]::White
    [void](Add-Label $dlg "Chọn Disk chứa bản sao Mirror cho ổ ${Letter}:" 14 14 342 $true)
    $cbo = New-Object System.Windows.Forms.ComboBox; $cbo.Location = New-Object System.Drawing.Point(14, 42); $cbo.Size = New-Object System.Drawing.Size(342, 26); $cbo.DropDownStyle = "DropDownList"
    foreach ($c in $cands) { [void]$cbo.Items.Add("Disk $($c.Number) ($($c.DiskType), trống $(Format-DiskSize ([Math]::Max($c.FreeBytes, $c.FreeExtBytes))))") }
    $cbo.SelectedIndex = 0; $dlg.Controls.Add($cbo)
    $btnOk = Add-Button $dlg "Add Mirror" 168 94 102 32; $btnOk.Font = $fontBold; $btnOk.Tag = 'Primary'
    $btnCan = Add-Button $dlg "Cancel" 278 94 78 32; $btnCan.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $btnOk.Add_Click({ $dlg.DialogResult = [System.Windows.Forms.DialogResult]::OK; $dlg.Close() })
    Set-ModernButtons $dlg
    if ($dlg.ShowDialog($form) -eq [System.Windows.Forms.DialogResult]::OK) {
        [void](Invoke-DiskAddMirror ($txtDiskSrv.Text.Trim()) $Letter $cands[$cbo.SelectedIndex].Number)
    }
    $dlg.Dispose()
}

