    }
    finally { $script:Working = $false }
})

$btnOUUnprotect.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -le 0) { Show-Msg "Hãy chọn 1 OU (không phải gốc domain)." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    if (Test-IsDomainControllersOU $ouDn) { Show-Msg "BỊ CHẶN: Không được phép tắt bảo vệ chống xóa trên OU hệ thống 'Domain Controllers'." "Bị chặn" "Warning"; return }
    $script:Working = $true
    try {
        try { Get-ADOrganizationalUnit -Identity $ouDn -ErrorAction Stop | Out-Null }
        catch { Show-Msg "OU '$ouDn' không còn tồn tại." "Không tìm thấy" "Warning"; return }
