        if (-not (Confirm-Msg "TẮT bảo vệ chống xóa nhầm (ProtectedFromAccidentalDeletion) cho OU:`r`n$ouDn`r`n`r`nOU sẽ có thể bị xóa hoặc di chuyển dễ dàng hơn. Tiếp tục?" "Cảnh báo" "Warning")) { return }
        Invoke-WithBusy { Set-ADOrganizationalUnit -Identity $ouDn -ProtectedFromAccidentalDeletion $false -ErrorAction Stop } "Đang tắt bảo vệ OU..."
