        Show-Msg $_.Exception.Message "Lỗi tắt bảo vệ OU" "Error"
    }
    finally { $script:Working = $false }
})

$btnBlockInhOn.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -le 0) { Show-Msg "Hãy chọn 1 OU." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    if (Test-IsDomainControllersOU $ouDn) { Show-Msg "BỊ CHẶN: Không được phép bật Block Inheritance trên OU hệ thống 'Domain Controllers'." "Bị chặn" "Warning"; return }
    $script:Working = $true
    try {
        try { Get-ADOrganizationalUnit -Identity $ouDn -ErrorAction Stop | Out-Null }
        catch { Show-Msg "OU '$ouDn' không còn tồn tại." "Không tìm thấy" "Warning"; return }
        if ($chkDry.Checked) { Write-Log "[CHẠY THỬ] Sẽ bật Block Inheritance cho OU: $ouDn" "Blue"; return }
        if (-not (Confirm-Msg "Bật Block Inheritance sẽ CHẶN các GPO kế thừa từ domain/OU cha áp xuống:`r`n$ouDn`r`n(Trừ các GPO đánh dấu Enforced)`r`n`r`nTiếp tục?" "Xác nhận" "Warning")) { return }
        Invoke-WithBusy {
            Set-GPInheritance -Target $ouDn -IsBlocked Yes -ErrorAction Stop | Out-Null
            if ((Get-ADObject -Identity $ouDn -Properties gPOptions -ErrorAction Stop).gPOptions -ne 1) {
                Set-ADObject -Identity $ouDn -Replace @{ gPOptions = 1 } -ErrorAction Stop
            }
            if (-not (Get-GPInheritance -Target $ouDn -ErrorAction Stop).GpoInheritanceBlocked) {
                throw "AD chưa xác nhận bật Block Inheritance cho '$ouDn'."
            }
        } "Đang bật Block Inheritance..."
        Write-Log "[OK] Đã BẬT Block Inheritance cho OU: $ouDn" "Green"
        $script:Working = $false
        Update-OUList -Force
    }
    catch {
        Write-Log ("[LỖI] Block Inheritance: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi Block Inheritance" "Error"
    }
    finally { $script:Working = $false }
})

$btnBlockInhOff.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -le 0) { Show-Msg "Hãy chọn 1 OU." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    $script:Working = $true
    try {
        try { Get-ADOrganizationalUnit -Identity $ouDn -ErrorAction Stop | Out-Null }
        catch { Show-Msg "OU '$ouDn' không còn tồn tại." "Không tìm thấy" "Warning"; return }
        if ($chkDry.Checked) { Write-Log "[CHẠY THỬ] Sẽ tắt Block Inheritance cho OU: $ouDn" "Blue"; return }
        if (-not (Confirm-Msg "Tắt Block Inheritance cho OU:`r`n$ouDn`r`n`r`nTiếp tục?")) { return }
        Invoke-WithBusy {
            Set-GPInheritance -Target $ouDn -IsBlocked No -ErrorAction Stop | Out-Null
            $gpOpt = (Get-ADObject -Identity $ouDn -Properties gPOptions -ErrorAction Stop).gPOptions
            if ($null -ne $gpOpt -and [int]$gpOpt -ne 0) {
                Set-ADObject -Identity $ouDn -Clear gPOptions -ErrorAction Stop
            }
            if ((Get-GPInheritance -Target $ouDn -ErrorAction Stop).GpoInheritanceBlocked) {
                throw "AD chưa xác nhận tắt Block Inheritance cho '$ouDn'."
            }
        } "Đang tắt Block Inheritance..."
        Write-Log "[OK] Đã TẮT Block Inheritance cho OU: $ouDn" "Green"
        $script:Working = $false
        Update-OUList -Force
    }
    catch {
        Write-Log ("[LỖI] Block Inheritance: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi Block Inheritance" "Error"
    }
    finally { $script:Working = $false }
})

$btnCheckInh.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -lt 0) { Show-Msg "Chưa kết nối AD hoặc chưa chọn OU." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    $script:Working = $true
    try {
        $res = Invoke-WithBusy {
            $inh = Get-GPInheritance -Target $ouDn -ErrorAction Stop
            $gpoSt = @{}
            try { Get-GPO -All -ErrorAction SilentlyContinue | ForEach-Object { $gpoSt[$_.Id] = [string]$_.GpoStatus } } catch {}
            @{ Inh = $inh; Status = $gpoSt }
        } "Đang kiểm tra kế thừa GPO..."
        $inh = $res.Inh; $gpoSt = $res.Status
        Write-Log ("[INFO] Kế thừa GPO của '$ouDn' | Block Inheritance: " + $inh.GpoInheritanceBlocked) "Black"
        $links = @($inh.InheritedGpoLinks)
        if ($links.Count -eq 0) { Write-Log "      (Không có GPO nào đang kế thừa/áp dụng tại đây)" "DimGray" }
        foreach ($g in $links) {
            $st = if ($gpoSt.ContainsKey($g.GpoId)) { $gpoSt[$g.GpoId] } else { "?" }
            $warnDis = if ($st -eq 'AllSettingsDisabled') { " [BỊ TẮT TRONG GPO!]" } else { "" }
            Write-Log ("      #" + $g.Order + " " + $g.DisplayName + " (Enforced: " + $g.Enforced + ", LinkEnabled: " + $g.Enabled + ", Status: " + $st + $warnDis + ", Gắn tại: " + $g.Target + ")") "DimGray"
        }
        $disabledDirect = @($inh.GpoLinks | Where-Object { -not $_.Enabled })
        foreach ($dg in $disabledDirect) {
            Write-Log ("      [Link đang tắt tại OU này] " + $dg.DisplayName) "DarkOrange"
        }
    }
    catch {
        Write-Log ("[LỖI] Kiểm tra kế thừa: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi kiểm tra kế thừa" "Error"
    }
    finally { $script:Working = $false }
})

$btnOURename.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -le 0) { Show-Msg "Hãy chọn 1 OU (không phải gốc domain)." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    if (Test-IsDomainControllersOU $ouDn) { Show-Msg "BỊ CHẶN: Không được phép đổi tên OU hệ thống 'Domain Controllers'." "Bị chặn" "Warning"; return }
    $newName = $txtOUEditVal.Text
    $err = Test-OUName $newName
    if ($err) { Show-Msg $err "Chưa hợp lệ" "Warning"; return }
    $script:Working = $true
    try {
        $ou = Get-ADOrganizationalUnit -Identity $ouDn -ErrorAction Stop
        if ($newName -ieq $ou.Name) { Show-Msg "Tên mới trùng với tên hiện tại '$($ou.Name)'." "Chưa hợp lệ" "Warning"; return }
        $parentDn = ($ouDn -split '(?<!\\)(?:\\\\)*,', 2)[1]
        $sibDn = "OU=$newName,$parentDn"
        if ($script:OUSet.ContainsKey($sibDn.ToLower()) -or (Get-ADOrganizationalUnit -Filter "DistinguishedName -eq '$($sibDn -replace "'","''")'" -ErrorAction SilentlyContinue)) {
            Show-Msg "Đã có OU tên '$newName' trong cùng OU cha." "Trùng tên" "Warning"; return
        }
        if ($chkDry.Checked) { Write-Log "[CHẠY THỬ] Sẽ đổi tên OU '$($ou.Name)' -> '$newName' ($ouDn)" "Blue"; return }
        if (-not (Confirm-Msg "Đổi tên OU '$($ou.Name)' thành '$newName'?")) { return }
        Invoke-WithBusy { Rename-ADObject -Identity $ouDn -NewName $newName -ErrorAction Stop } "Đang đổi tên OU..."

        $oldDnLow = $ouDn.ToLower()
        $newDnLow = $sibDn.ToLower()
        $script:ExpectedRemoved[$oldDnLow] = $true
        $script:Created[$newDnLow] = $true
        $oldSuf = "," + $oldDnLow; $newSuf = "," + $newDnLow
        foreach ($k in @($script:OUSet.Keys)) {
            if ($k.EndsWith($oldSuf)) { $script:ExpectedRemoved[$k] = $true; $script:Created[($k.Substring(0, $k.Length - $oldSuf.Length) + $newSuf)] = $true }
        }
        foreach ($k in @($script:ObjSet.Keys)) {
            if ($k.EndsWith($oldSuf)) { $script:ExpectedRemoved[$k] = $true; $script:Created[($k.Substring(0, $k.Length - $oldSuf.Length) + $newSuf)] = $true }
        }
        Write-Log "[OK] Đã đổi tên OU '$($ou.Name)' -> '$newName'." "Green"
        $txtOUEditVal.Clear()
        $script:Working = $false
        Update-OUList -Force
        $newIdx = Find-DNIndex $sibDn
        if ($newIdx -ge 0) { $cboMgmtOU.SelectedIndex = $newIdx }
    }
    catch {
        Write-Log ("[LỖI] Đổi tên OU: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi đổi tên OU" "Error"
    }
    finally { $script:Working = $false }
})

$btnOUDesc.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -le 0) { Show-Msg "Hãy chọn 1 OU (không phải gốc domain)." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    $desc = $txtOUEditVal.Text.Trim()
    $script:Working = $true
    try {
        Get-ADOrganizationalUnit -Identity $ouDn -ErrorAction Stop | Out-Null
        if ($chkDry.Checked) {
            $preview = if ([string]::IsNullOrWhiteSpace($desc)) { "(XÓA TRẮNG mô tả)" } else { "'$desc'" }
            Write-Log "[CHẠY THỬ] Sẽ cập nhật mô tả OU '$ouDn' thành: $preview" "Blue"; return
        }
        $qMsg = if ([string]::IsNullOrWhiteSpace($desc)) {
            "Ô mô tả đang để TRỐNG.`r`nThao tác này sẽ XÓA TRẮNG mô tả hiện tại của OU:`r`n$ouDn`r`n`r`nTiếp tục?"
        } else { "Cập nhật mô tả cho OU '$ouDn'?" }
        if (-not (Confirm-Msg $qMsg "Xác nhận" $(if ([string]::IsNullOrWhiteSpace($desc)) { "Warning" } else { "Question" }))) { return }
        Invoke-WithBusy {
            if ([string]::IsNullOrWhiteSpace($desc)) { Set-ADOrganizationalUnit -Identity $ouDn -Clear Description -ErrorAction Stop }
            else { Set-ADOrganizationalUnit -Identity $ouDn -Description $desc -ErrorAction Stop }
        } "Đang cập nhật mô tả OU..."
        Write-Log "[OK] Đã cập nhật mô tả cho OU: $ouDn" "Green"
        $txtOUEditVal.Clear()
        $script:Working = $false
        Update-OUList -Force
    }
    catch {
        Write-Log ("[LỖI] Sửa mô tả OU: " + $_.Exception.Message) "Red"
        Show-Msg $_.Exception.Message "Lỗi sửa mô tả OU" "Error"
    }
    finally { $script:Working = $false }
})

$btnOUDelete.Add_Click({
    if (-not $script:Ready -or $cboMgmtOU.SelectedIndex -le 0) { Show-Msg "Hãy chọn 1 OU cần xóa (không phải gốc domain)." "Chưa hợp lệ" "Warning"; return }
    $ouDn = $script:OUDN[$cboMgmtOU.SelectedIndex]
    [void](Invoke-DeleteOU $ouDn $chkOUDelRecurse.Checked)
})

# ---------- Giao diện hiện đại (Modern UI/UX) & Tooltips ----------
function Update-ModeBadge {
    if ($chkDry.Checked) {
        $lblModeBadge.Text      = "CHẠY THỬ (Bấm để tạo thật)"
        $lblModeBadge.BackColor = [System.Drawing.Color]::FromArgb(14, 165, 233)
        $lblModeBadge.ForeColor = [System.Drawing.Color]::White
        $chkDry.ForeColor       = [System.Drawing.Color]::FromArgb(15, 23, 42)
        if ($btnCreateOU)      { $btnCreateOU.Text      = "Tạo OU (Thử)" }
        if ($btnDeleteOUQuick) { $btnDeleteOUQuick.Text = "Xóa OU (Thử)" }
        if ($btnCreateGrp)     { $btnCreateGrp.Text     = "Tạo Group (Thử)" }
        if ($btnDeleteGrp)     { $btnDeleteGrp.Text     = "Xóa Group (Thử)" }
        if ($btnCreateGPO)     { $btnCreateGPO.Text     = "Tạo GPO (Thử)" }
        if ($btnLibCreate)     { $btnLibCreate.Text     = "Tạo GPO đã chọn (Thử)" }
        Update-UsrButtonText
        Update-QuotaCreateButtonText
        if ($lblHomeTip) {
            $lblHomeTip.ForeColor = [System.Drawing.Color]::FromArgb(30, 41, 59)
            $lblHomeTip.Font      = $fontMain
            $lblHomeTip.Text      = "Mẹo an toàn: Chế độ 'Chạy thử' đang BẬT. Bạn có thể bấm thử mọi tính năng để xem trước mà không làm thay đổi hệ thống."
        }
    }
    else {
        $lblModeBadge.Text      = "THAO TÁC THẬT (Đang bật)"
        $lblModeBadge.BackColor = [System.Drawing.Color]::FromArgb(220, 38, 38)
        $lblModeBadge.ForeColor = [System.Drawing.Color]::White
        $chkDry.ForeColor       = [System.Drawing.Color]::FromArgb(185, 28, 28)
        if ($btnCreateOU)      { $btnCreateOU.Text      = "Tạo OU" }
        if ($btnDeleteOUQuick) { $btnDeleteOUQuick.Text = "Xóa OU" }
        if ($btnCreateGrp)     { $btnCreateGrp.Text     = "Tạo Group" }
        if ($btnDeleteGrp)     { $btnDeleteGrp.Text     = "Xóa Group" }
        if ($btnCreateGPO)     { $btnCreateGPO.Text     = "Tạo Group Policy" }
        if ($btnLibCreate)     { $btnLibCreate.Text     = "Tạo các GPO đã chọn" }
        Update-UsrButtonText
        Update-QuotaCreateButtonText
        if ($lblHomeTip) {
            $lblHomeTip.ForeColor = [System.Drawing.Color]::FromArgb(185, 28, 28)
            $lblHomeTip.Font      = $fontBold
            $lblHomeTip.Text      = "⚠ CẢNH BÁO: Đang ở CHẾ ĐỘ THAO TÁC THẬT! Mọi thao tác sau khi xác nhận sẽ thay đổi trực tiếp hệ thống / Active Directory."
        }
    }
    if ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsStyled) {
        if ($lblModeBadge) { $lblModeBadge.Invalidate() }
        if ($chkDry) { $chkDry.Invalidate() }
        if ($lblHomeTip) { $lblHomeTip.Invalidate() }
    }
}
$chkDry.Add_CheckedChanged({ Update-ModeBadge })
$lblModeBadge.Add_Click({ $chkDry.Checked = (-not $chkDry.Checked) })
Update-ModeBadge

function Apply-ButtonStyle {
    param($Btn)
    if ($null -eq $Btn) { return }
    $r = if ($Btn.Tag -in @('Primary', 'Secondary', 'Danger')) { [string]$Btn.Tag } elseif ($Btn.Text -match '^(Gỡ|Khóa|Tắt|Xóa)\b') { 'Danger' } elseif ($Btn.Font.Bold) { 'Primary' } else { 'Secondary' }
    $isStyled = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsStyled)
    $isThemed = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive)
    if ($isStyled) {
        $Btn.FlatAppearance.BorderSize = 0
        if ($isThemed) {
            if (-not $Btn.Enabled) {
                $Btn.BackColor = [System.Drawing.Color]::FromArgb(20, 28, 44)
                $Btn.ForeColor = [System.Drawing.Color]::FromArgb(148, 163, 184)
            } elseif ($r -eq 'Danger') {
                $Btn.BackColor = [System.Drawing.Color]::FromArgb(44, 12, 20)
                $Btn.ForeColor = [System.Drawing.Color]::White
            } elseif ($r -eq 'Primary') {
                $Btn.BackColor = [System.Drawing.Color]::FromArgb(20, 38, 76)
                $Btn.ForeColor = [System.Drawing.Color]::White
            } else {
                $Btn.BackColor = [System.Drawing.Color]::FromArgb(14, 22, 40)
                $Btn.ForeColor = [System.Drawing.Color]::White
            }
        } else {
            if (-not $Btn.Enabled) {
                $Btn.BackColor = [System.Drawing.Color]::FromArgb(248, 250, 252)
                $Btn.ForeColor = [System.Drawing.Color]::FromArgb(148, 163, 184)
            } elseif ($r -eq 'Danger') {
                $Btn.BackColor = [System.Drawing.Color]::White
                $Btn.ForeColor = [System.Drawing.Color]::FromArgb(185, 28, 28)
            } elseif ($r -eq 'Primary') {
                $Btn.BackColor = [System.Drawing.Color]::White
                $Btn.ForeColor = [System.Drawing.Color]::FromArgb(15, 23, 42)
            } else {
                $Btn.BackColor = [System.Drawing.Color]::White
                $Btn.ForeColor = [System.Drawing.Color]::FromArgb(30, 41, 59)
            }
        }
        $Btn.Invalidate()
        return
    }
    if (-not $Btn.Enabled) {
        $Btn.BackColor = [System.Drawing.Color]::FromArgb(226, 232, 240)
        $Btn.ForeColor = [System.Drawing.Color]::FromArgb(100, 116, 139)
        $Btn.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(203, 213, 225)
        $Btn.FlatAppearance.BorderSize  = 1
    } elseif ($r -eq 'Danger') {
        $Btn.BackColor = [System.Drawing.Color]::FromArgb(254, 242, 242)
        $Btn.ForeColor = [System.Drawing.Color]::FromArgb(185, 28, 28)
        $Btn.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(252, 165, 165)
        $Btn.FlatAppearance.BorderSize  = 1
        $Btn.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(254, 226, 226)
    } elseif ($r -eq 'Primary') {
        $Btn.BackColor = [System.Drawing.Color]::FromArgb(37, 99, 235)
        $Btn.ForeColor = [System.Drawing.Color]::White
        $Btn.FlatAppearance.BorderSize = 0
        $Btn.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(29, 78, 216)
    } else {
        $Btn.BackColor = [System.Drawing.Color]::FromArgb(241, 245, 249)
        $Btn.ForeColor = [System.Drawing.Color]::FromArgb(30, 41, 59)
        $Btn.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(203, 213, 225)
        $Btn.FlatAppearance.BorderSize  = 1
        $Btn.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(226, 232, 240)
    }
}

function Update-ModernButtonsTheme {
    param($Container = $form)
    foreach ($c in $Container.Controls) {
        if ($c -is [System.Windows.Forms.Button]) {
            if ($c.Tag -eq 'NavItem' -or $c.Tag -eq 'ThemeQuick') { continue }
            Apply-ButtonStyle $c
        }
        if ($c.HasChildren) { Update-ModernButtonsTheme $c }
    }
}

function Set-ModernButtons {
    param($Container)
    foreach ($c in $Container.Controls) {
        if ($c -is [System.Windows.Forms.Button]) {
            if ($c.Tag -eq 'NavItem' -or $c.Tag -eq 'ThemeQuick') { continue }
            $c.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
            $c.Cursor    = [System.Windows.Forms.Cursors]::Hand
            $role = if ($c.Tag -in @('Primary', 'Secondary', 'Danger')) {
                [string]$c.Tag
            } elseif ($c.Text -match '^(Gỡ|Khóa|Tắt|Xóa)\b') {
                'Danger'
            } elseif ($c.Font.Bold) {
                'Primary'
            } else {
                'Secondary'
            }
            if ($null -eq $c.Tag -or $c.Tag -is [string]) { $c.Tag = $role }
            Apply-ButtonStyle $c
            $c.Add_EnabledChanged({ Apply-ButtonStyle $this })
        }
        if ($c.HasChildren) { Set-ModernButtons $c }
    }
}
