# ---------- Quản lý Theme (Động: MP4 / GIF & Thường: JPG / PNG) ----------
$script:ThemeLoadingCfg = $false

function Format-ThemeSize {
    param([long]$Bytes)
    if ($Bytes -ge 1MB) { return ("{0:N1} MB" -f ($Bytes / 1MB)) }
    if ($Bytes -ge 1KB) { return ("{0:N0} KB" -f ($Bytes / 1KB)) }
    return "$Bytes B"
}

function Get-ThemeConfigPath {
    return (Join-Path (Get-ThemeDir -Ensure) "theme-config.json")
}

function Load-ThemeConfig {
    $cfgPath = Get-ThemeConfigPath
    if (-not (Test-Path -LiteralPath $cfgPath)) { return $null }
    try {
        $raw = [System.IO.File]::ReadAllText($cfgPath, [System.Text.Encoding]::UTF8)
        if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
        return ($raw | ConvertFrom-Json)
    } catch {
        return $null
    }
}

function Save-ThemeConfig {
    try {
        $dir = Get-ThemeDir -Ensure
        $cfgPath = Join-Path $dir "theme-config.json"
        $remember = $chkThemeRemember.Checked
        $rel = ""
        if ($remember -and $null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive -and $script:ThemeEngine.ActivePath) {
            $ap = [string]$script:ThemeEngine.ActivePath
            if ($ap.StartsWith($dir, [System.StringComparison]::OrdinalIgnoreCase)) {
                $rel = $ap.Substring($dir.Length).TrimStart('\', '/')
            } else {
                $rel = $ap
            }
        }
        $obj = [ordered]@{
            ActiveRelPath  = $rel
            DimPercent     = [int]$trkThemeDim.Value
            StrongOutline  = [bool]$chkThemeOutline.Checked
            TextPreset     = [int]$cboThemeTextPreset.SelectedIndex
            ShowOrnaments  = [bool]$chkThemeOrnaments.Checked
            OrnamentSeason = [int]$cboThemeOrnamentSeason.SelectedIndex
            ShowAnimation  = [bool]$chkThemeAnim.Checked
            AnimEffect     = 0
            Remember       = [bool]$remember
        }
        $json = $obj | ConvertTo-Json -Depth 3
        [System.IO.File]::WriteAllText($cfgPath, $json, (New-Object System.Text.UTF8Encoding($true)))
    } catch { }
}

function Get-ThemeCatalog {
    $dir = Get-ThemeDir -Ensure
    $items = New-Object 'System.Collections.Generic.List[object]'
    if (-not (Test-Path -LiteralPath $dir)) { return @() }
    try {
        $files = @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue)
        foreach ($sub in @(Get-ChildItem -LiteralPath $dir -Directory -ErrorAction SilentlyContinue)) {
            $files += @(Get-ChildItem -LiteralPath $sub.FullName -File -ErrorAction SilentlyContinue)
        }
        foreach ($f in $files) {
            $ext = $f.Extension.ToLowerInvariant()
            if ($ext -notin @('.mp4', '.gif', '.jpg', '.jpeg', '.png', '.bmp')) { continue }
            $cat = if ($ext -in @('.mp4', '.gif')) { 'Dynamic' } else { 'Static' }
            $typeLabel = if ($cat -eq 'Dynamic') { "Động ($($ext.TrimStart('.').ToUpperInvariant()))" } else { "Thường ($($ext.TrimStart('.').ToUpperInvariant()))" }
            $rel = if ($f.FullName.StartsWith($dir, [System.StringComparison]::OrdinalIgnoreCase)) { $f.FullName.Substring($dir.Length).TrimStart('\', '/') } else { $f.Name }
            $folderLbl = if ($f.DirectoryName -ieq $dir) { "Theme\" } else { "Theme\" + $f.Directory.Name }
            $items.Add([pscustomobject]@{
                Name        = $f.Name
                RelPath     = $rel
                FullPath    = $f.FullName
                Ext         = $ext.TrimStart('.').ToUpperInvariant()
                Category    = $cat
                TypeLabel   = $typeLabel
                SizeText    = (Format-ThemeSize $f.Length)
                FolderLabel = $folderLbl
            })
        }
    } catch { }
    return @($items | Sort-Object @{ Expression = { if ($_.Category -eq 'Dynamic') { 0 } else { 1 } } }, Name)
}

function Populate-ThemeList {
    if ($null -eq $lvThemes -or $lvThemes.IsDisposed) { return }
    $activePath = if ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive) { [string]$script:ThemeEngine.ActivePath } else { "" }
    $filterIdx = $cboThemeFilter.SelectedIndex
    $catalog = @(Get-ThemeCatalog)
    $isThemed = ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive)
    $preset = if ($null -ne $script:ThemeEngine) { [int]$script:ThemeEngine.TextPreset } elseif ($null -ne $cboThemeTextPreset -and $cboThemeTextPreset.SelectedIndex -ge 0) { [int]$cboThemeTextPreset.SelectedIndex } else { 0 }
    $rowFg = Get-NativePresetForeColor $isThemed $preset
    $dynFg = if ($isThemed) { [System.Drawing.Color]::FromArgb(56, 189, 248) } else { [System.Drawing.Color]::FromArgb(29, 78, 216) }

    $lvThemes.BeginUpdate()
    try {
        $lvThemes.Items.Clear()
        $defItem = New-Object System.Windows.Forms.ListViewItem "(Mặc định — Nền trắng)"
        [void]$defItem.SubItems.Add("Nền trắng")
        [void]$defItem.SubItems.Add("-")
        [void]$defItem.SubItems.Add("-")
        [void]$defItem.SubItems.Add("Hệ thống")
        $defItem.Tag = ""
        $defItem.ForeColor = $rowFg
        if (-not $activePath) { $defItem.Selected = $true }
        [void]$lvThemes.Items.Add($defItem)

        foreach ($it in $catalog) {
            if ($filterIdx -eq 1 -and $it.Category -ne 'Dynamic') { continue }
            if ($filterIdx -eq 2 -and $it.Category -ne 'Static') { continue }
            $li = New-Object System.Windows.Forms.ListViewItem $it.Name
            [void]$li.SubItems.Add($it.TypeLabel)
            [void]$li.SubItems.Add($it.Ext)
            [void]$li.SubItems.Add($it.SizeText)
            [void]$li.SubItems.Add($it.FolderLabel)
            $li.Tag = $it.FullPath
            $li.ForeColor = if ($it.Category -eq 'Dynamic') { $dynFg } else { $rowFg }
            if ($activePath -and $it.FullPath -ieq $activePath) {
                $li.Selected = $true
            }
            [void]$lvThemes.Items.Add($li)
        }
    } finally {
        $lvThemes.EndUpdate()
    }
}

$script:LastNativeTextPreset = -1
$script:LastNativeThemed     = $null

function Set-TreeNodesThemeRecursive {
    param($Nodes, [bool]$IsThemed, [System.Drawing.Color]$DefaultFg = [System.Drawing.Color]::Empty)
    if ($DefaultFg.IsEmpty) {
        $preset = if ($null -ne $script:ThemeEngine) { [int]$script:ThemeEngine.TextPreset } else { 0 }
        $DefaultFg = Get-NativePresetForeColor $IsThemed $preset
    }
    foreach ($nd in $Nodes) {
        if ($nd.ForeColor -eq [System.Drawing.Color]::ForestGreen -or ($nd.ForeColor.R -eq 74 -and $nd.ForeColor.G -eq 222)) {
            $nd.ForeColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(74, 222, 128) } else { [System.Drawing.Color]::ForestGreen }
        } elseif ($nd.ForeColor -eq [System.Drawing.Color]::DarkOrange -or ($nd.ForeColor.R -eq 251 -and $nd.ForeColor.G -eq 191)) {
            $nd.ForeColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(251, 191, 36) } else { [System.Drawing.Color]::DarkOrange }
        } elseif ($nd.ForeColor -eq [System.Drawing.Color]::Gray -or $nd.ForeColor -eq [System.Drawing.Color]::DimGray -or ($nd.ForeColor.R -eq 203 -and $nd.ForeColor.G -eq 213)) {
            $nd.ForeColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(203, 213, 225) } else { if ($nd.Text -like '*`[tắt`]*') { [System.Drawing.Color]::Gray } else { [System.Drawing.Color]::DimGray } }
        } else {
            $nd.ForeColor = $DefaultFg
        }
        if ($nd.Nodes.Count -gt 0) { Set-TreeNodesThemeRecursive $nd.Nodes $IsThemed $DefaultFg }
    }
}

function Set-InputsThemeRecursive {
    param($Container, [bool]$IsThemed, [int]$Preset = -1)
    if ($Preset -lt 0) {
        $Preset = if ($null -ne $script:ThemeEngine) { [int]$script:ThemeEngine.TextPreset } elseif ($null -ne $cboThemeTextPreset -and $cboThemeTextPreset.SelectedIndex -ge 0) { [int]$cboThemeTextPreset.SelectedIndex } else { 0 }
    }
    $natFg = Get-NativePresetForeColor $IsThemed $Preset
    foreach ($c in $Container.Controls) {
        if ($c -is [System.Windows.Forms.TextBox]) {
            if ($c -ne $txtDiskInfo) {
                $c.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(20, 30, 48) } else { [System.Drawing.SystemColors]::Window }
                $c.ForeColor = $natFg
            }
        } elseif ($c -is [System.Windows.Forms.ComboBox]) {
            $c.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
            $c.DrawMode  = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
            $c.ItemHeight = 18
            $c.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(14, 22, 40) } else { [System.Drawing.Color]::White }
            $c.ForeColor = $natFg
            $c.Invalidate()
        } elseif ($c -is [System.Windows.Forms.NumericUpDown]) {
            $c.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(20, 30, 48) } else { [System.Drawing.SystemColors]::Window }
            $c.ForeColor = $natFg
        } elseif ($c -is [System.Windows.Forms.CheckedListBox]) {
            $c.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.SystemColors]::Window }
            $c.ForeColor = $natFg
        }
        if ($c.HasChildren) { Set-InputsThemeRecursive $c $IsThemed $Preset }
    }
}

function Update-TextPresetNativeControls {
    param([bool]$IsThemed)
    $preset = if ($null -ne $script:ThemeEngine) { [int]$script:ThemeEngine.TextPreset } elseif ($null -ne $cboThemeTextPreset -and $cboThemeTextPreset.SelectedIndex -ge 0) { [int]$cboThemeTextPreset.SelectedIndex } else { 0 }
    $script:LastNativeTextPreset = $preset
    $script:LastNativeThemed     = $IsThemed
    $natFg = Get-NativePresetForeColor $IsThemed $preset

    Set-InputsThemeRecursive $form $IsThemed $preset

    $txtLog.ForeColor = $natFg
    Rebuild-LogColors

    $txtHelp.ForeColor = $natFg
    if ($txtHelp.TextLength -gt 0) {
        $prevStart = $txtHelp.SelectionStart
        $prevLen   = $txtHelp.SelectionLength
        $txtHelp.SelectAll()
        $txtHelp.SelectionColor = $natFg
        $txtHelp.Select($prevStart, $prevLen)
    }

    $txtDiskInfo.ForeColor = $natFg

    $tree.ForeColor = $natFg
    Set-TreeNodesThemeRecursive $tree.Nodes $IsThemed $natFg

    $lvLib.ForeColor = $natFg
    foreach ($li in $lvLib.Items) {
        $it = $li.Tag
        if ($it -and $it.Kind -eq 'Manual') {
            $li.ForeColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(203, 213, 225) } else { [System.Drawing.Color]::Gray }
        } elseif ($it -and $it.Kind -eq 'Domain') {
            $li.ForeColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(255, 107, 107) } else { [System.Drawing.Color]::Firebrick }
        } else {
            $li.ForeColor = $natFg
        }
    }

    $lvDiskVols.ForeColor = $natFg
    $lvThemes.ForeColor   = $natFg
    $dynFg = if ($IsThemed) { [System.Drawing.Color]::FromArgb(56, 189, 248) } else { [System.Drawing.Color]::FromArgb(29, 78, 216) }
    foreach ($li in $lvThemes.Items) {
        $tagPath = [string]$li.Tag
        if ($tagPath -and ([System.IO.Path]::GetExtension($tagPath).ToLowerInvariant() -in @('.mp4', '.gif'))) {
            $li.ForeColor = $dynFg
        } else {
            $li.ForeColor = $natFg
        }
    }
}

function Update-DataViewsTheme {
    param([bool]$IsThemed)
    $pnlHeader.BackColor   = if ($IsThemed) { [System.Drawing.Color]::FromArgb(30, 58, 95) } else { [System.Drawing.Color]::White }
    $lblHdrTitle.ForeColor = if ($IsThemed) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::FromArgb(15, 23, 42) }
    $lblHdrSub.ForeColor   = if ($IsThemed) { [System.Drawing.Color]::FromArgb(191, 219, 254) } else { [System.Drawing.Color]::FromArgb(71, 85, 105) }
    $pnlHeader.Invalidate()
    $lblHdrTitle.Invalidate()
    $lblHdrSub.Invalidate()

    $txtLog.BackColor      = if ($IsThemed) { [System.Drawing.Color]::FromArgb(12, 18, 32) } else { [System.Drawing.Color]::White }
    $txtHelp.BackColor     = if ($IsThemed) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::White }
    $txtDiskInfo.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::White }

    $tree.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::White }
    $tree.LineColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(100, 116, 139) } else { [System.Drawing.Color]::Gray }

    $lvLib.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(12, 19, 34) } else { [System.Drawing.Color]::White }
    $lvLib.OwnerDraw = $true

    $lvDiskVols.BackColor = if ($IsThemed) { [System.Drawing.Color]::FromArgb(12, 19, 34) } else { [System.Drawing.Color]::White }
    $lvDiskVols.OwnerDraw = $true
    $lvThemes.BackColor   = if ($IsThemed) { [System.Drawing.Color]::FromArgb(12, 19, 34) } else { [System.Drawing.Color]::White }
    $lvThemes.OwnerDraw   = $true

    Update-TextPresetNativeControls $IsThemed

    $pnlContentHost.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    foreach ($card in @($script:QuickCards)) {
        if ($null -eq $card -or $card.IsDisposed) { continue }
        $card.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    }

    $dvBg = if ($IsThemed) { [System.Drawing.Color]::FromArgb(15, 23, 42) } else { [System.Drawing.Color]::White }
    $pnlDiskVisual.BackColor = $dvBg
    foreach ($child in $pnlDiskVisual.Controls) {
        if ($child -is [System.Windows.Forms.Panel]) { $child.BackColor = $dvBg }
    }
    foreach ($b in @($script:DiskVisualBtns)) {
        if ($null -ne $b -and -not $b.IsDisposed) {
            $b.BackColor = $dvBg
            $b.Invalidate()
        }
    }

    $trkThemeDim.Invalidate()
    $subTabs.DrawMode      = [System.Windows.Forms.TabDrawMode]::OwnerDrawFixed
    $subQuotaTabs.DrawMode = [System.Windows.Forms.TabDrawMode]::OwnerDrawFixed

    $btnThemeQuick.FlatAppearance.BorderSize = 0
    if ($IsThemed) {
        $btnThemeQuick.BackColor = [System.Drawing.Color]::FromArgb(14, 24, 52)
        $btnThemeQuick.ForeColor = [System.Drawing.Color]::White
    } else {
        $btnThemeQuick.BackColor = [System.Drawing.Color]::White
        $btnThemeQuick.ForeColor = [System.Drawing.Color]::FromArgb(15, 23, 42)
    }
    $btnThemeQuick.Invalidate()
}

$script:ApplyingTheme = $false

function Apply-AppTheme {
    param([string]$FilePath = "", [switch]$NoSave)
    if ($null -eq $script:ThemeEngine -or $script:ApplyingTheme) { return }
    $script:ApplyingTheme = $true
    try {
        $script:ThemeEngine.SetReadabilityConfig([int]$trkThemeDim.Value, [bool]$chkThemeOutline.Checked, [int]$cboThemeTextPreset.SelectedIndex, [int]$cboThemeOrnamentSeason.SelectedIndex, [bool]$chkThemeOrnaments.Checked, [int]$cboThemeOrnamentSeason.SelectedIndex, [bool]$chkThemeAnim.Checked, 0)

        if ([string]::IsNullOrWhiteSpace($FilePath)) {
            $script:ThemeEngine.ClearTheme()
        }
        else {
            if (-not (Test-Path -LiteralPath $FilePath)) {
                Write-Log "[LỖI] Không tìm thấy tệp theme: $FilePath" "Red"
                Show-Msg "Không tìm thấy tệp theme:`r`n$FilePath" "Thiếu tệp Theme" "Warning"
                return
            }
            $ok = $script:ThemeEngine.LoadTheme($FilePath)
            if (-not $ok) {
                $err = if ($script:ThemeEngine.LastError) { $script:ThemeEngine.LastError } else { "Định dạng không hỗ trợ hoặc file bị lỗi." }
                Write-Log "[LỖI] Không nạp được theme '$FilePath': $err" "Red"
                Show-Msg "Không thể mở theme này.`r`nChi tiết: $err" "Lỗi mở Theme" "Warning"
                return
            }
        }

        $isThemed = $script:ThemeEngine.IsActive
        Update-DataViewsTheme $isThemed
        Update-NavSelection
        Update-ModeBadge
        Update-ModernButtonsTheme
        if ($pnlDiskLegend) { $pnlDiskLegend.Invalidate() }

        if ($isThemed) {
            $fname = [System.IO.Path]::GetFileName($script:ThemeEngine.ActivePath)
            $kindText = switch ($script:ThemeEngine.ActiveKind) {
                'MP4' { 'Theme động (MP4)' }
                'GIF' { if ($script:ThemeEngine.IsAnimated) { 'Theme động (GIF)' } else { 'Ảnh GIF tĩnh' } }
                default { 'Theme thường (Ảnh)' }
            }
            $lblThemeCurrent.Text = "Theme hiện tại: $fname  [$kindText]  |  Thư mục: " + (Get-ThemeDir)
            $btnThemeQuick.Text   = "✦ Theme: ON ▾"
            $btnThemePause.Enabled = $script:ThemeEngine.IsAnimated
            $btnThemePause.Text    = if ($script:ThemeEngine.IsPaused) { "Phát tiếp" } else { "Tạm dừng động" }
        }
        else {
            $lblThemeCurrent.Text  = "Theme hiện tại: Mặc định (Nền trắng)  |  Thư mục: " + (Get-ThemeDir)
            $btnThemeQuick.Text    = "✦ Theme ▾"
            $btnThemePause.Enabled = $false
            $btnThemePause.Text    = "Tạm dừng động"
        }

        Populate-ThemeList
        $script:ThemeEngine.RefreshNow()
        if (-not $NoSave) { Save-ThemeConfig }
    } finally {
        $script:ApplyingTheme = $false
    }
}

$btnThemeQuick.Add_Click({
    $themeQuickMenu.Items.Clear()
    $curPath = if ($null -ne $script:ThemeEngine -and $script:ThemeEngine.IsActive) { [string]$script:ThemeEngine.ActivePath } else { "" }

    $miDef = New-Object System.Windows.Forms.ToolStripMenuItem($(if (-not $curPath) { "✓ Mặc định (Nền trắng)" } else { "Mặc định (Nền trắng)" }))
    $miDef.Add_Click({ Apply-AppTheme "" })
    [void]$themeQuickMenu.Items.Add($miDef)
    [void]$themeQuickMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))

    $catalog = @(Get-ThemeCatalog)
    $dyn = @($catalog | Where-Object { $_.Category -eq 'Dynamic' })
    $sta = @($catalog | Where-Object { $_.Category -eq 'Static' })

    if ($dyn.Count -gt 0) {
        $hdrDyn = New-Object System.Windows.Forms.ToolStripMenuItem("── Theme động (MP4 / GIF) ──")
        $hdrDyn.Enabled = $false
        [void]$themeQuickMenu.Items.Add($hdrDyn)
        foreach ($it in $dyn) {
            $mark = if ($curPath -and $curPath -ieq $it.FullPath) { "✓ " } else { "" }
            $mi = New-Object System.Windows.Forms.ToolStripMenuItem("${mark}[$($it.Ext)] $($it.Name)")
            $mi.Tag = $it.FullPath
            $mi.Add_Click({ Apply-AppTheme ([string]$this.Tag) })
            [void]$themeQuickMenu.Items.Add($mi)
        }
    }

    if ($sta.Count -gt 0) {
        $hdrSta = New-Object System.Windows.Forms.ToolStripMenuItem("── Theme thường (JPG / PNG) ──")
        $hdrSta.Enabled = $false
        [void]$themeQuickMenu.Items.Add($hdrSta)
        foreach ($it in $sta) {
            $mark = if ($curPath -and $curPath -ieq $it.FullPath) { "✓ " } else { "" }
            $mi = New-Object System.Windows.Forms.ToolStripMenuItem("${mark}[$($it.Ext)] $($it.Name)")
            $mi.Tag = $it.FullPath
            $mi.Add_Click({ Apply-AppTheme ([string]$this.Tag) })
            [void]$themeQuickMenu.Items.Add($mi)
        }
    }

    if ($catalog.Count -eq 0) {
        $miEmpty = New-Object System.Windows.Forms.ToolStripMenuItem("(Thư mục Theme đang trống — bỏ .mp4/.gif/.jpg/.png vào)")
        $miEmpty.Enabled = $false
        [void]$themeQuickMenu.Items.Add($miEmpty)
    }

    [void]$themeQuickMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    $miSeasonMenu = New-Object System.Windows.Forms.ToolStripMenuItem("Khung viền & hiệu ứng")
    $seasonLabels = @(
        "Mùa Xuân — Hoa Anh Đào",
        "Mùa Hạ — Nắng Vàng & Hoa Hướng Dương",
        "Mùa Thu — Lá Phong Vàng Rơi",
        "Mùa Đông — Người Tuyết & Bông Tuyết",
        "Hoa Hướng Dương — Nắng Vàng Rực Rỡ",
        "Nguyên tố Lửa — Ngọn Lửa & Tàn Tro",
        "Nguyên tố Sấm Chớp — Tia Sét & Hào Quang",
        "Nguyên tố Lốc Xoáy — Phễu Gió Cuộn",
        "Nguyên tố Sóng Thần — Sóng Cuộn Bọt Trắng",
        "Thiên Thạch — Sao Chổi Lửa (Meteor)",
        "Sao Băng — Bầu Trời Đêm (Shooting Star)",
        "Gió — Làn Gió Mát & Lá Bay (Wind)",
        "Tia Nắng — Ánh Dương Rực Rỡ (Sunbeams)",
        "Mưa — Hạt Mưa & Gợn Sóng (Rain)"
    )
    $anyFxActive = ($chkThemeOrnaments.Checked -or $chkThemeAnim.Checked)
    for ($si = 0; $si -lt $seasonLabels.Count; $si++) {
        $sMark = if ($anyFxActive -and $cboThemeOrnamentSeason.SelectedIndex -eq $si) { "✓ " } else { "" }
        $miS = New-Object System.Windows.Forms.ToolStripMenuItem("$sMark$($seasonLabels[$si])")
        $miS.Tag = $si
        $miS.Add_Click({
            $script:ThemeLoadingCfg = $true
            try {
                if (-not $chkThemeOrnaments.Checked -and -not $chkThemeAnim.Checked) {
                    $chkThemeOrnaments.Checked = $true
                    $chkThemeAnim.Checked      = $true
                }
                $cboThemeOrnamentSeason.SelectedIndex = [int]$this.Tag
            } finally {
                $script:ThemeLoadingCfg = $false
            }
            & $syncThemeReadability
        })
        [void]$miSeasonMenu.DropDownItems.Add($miS)
    }
    [void]$miSeasonMenu.DropDownItems.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    $miToggleOrn = New-Object System.Windows.Forms.ToolStripMenuItem($(if ($chkThemeOrnaments.Checked) { "✓ Bật họa tiết khung viền" } else { "Bật họa tiết khung viền" }))
    $miToggleOrn.Add_Click({ $chkThemeOrnaments.Checked = (-not $chkThemeOrnaments.Checked) })
    [void]$miSeasonMenu.DropDownItems.Add($miToggleOrn)
    $miToggleAnim = New-Object System.Windows.Forms.ToolStripMenuItem($(if ($chkThemeAnim.Checked) { "✓ Bật hiệu ứng animation" } else { "Bật hiệu ứng animation" }))
    $miToggleAnim.Add_Click({ $chkThemeAnim.Checked = (-not $chkThemeAnim.Checked) })
    [void]$miSeasonMenu.DropDownItems.Add($miToggleAnim)
    [void]$themeQuickMenu.Items.Add($miSeasonMenu)

    $miMgr = New-Object System.Windows.Forms.ToolStripMenuItem("Tùy chỉnh nổi bật chữ & Quản lý Theme...")
    $miMgr.Add_Click({ $tabs.SelectedTab = $tabTheme })
    [void]$themeQuickMenu.Items.Add($miMgr)

    $miDir = New-Object System.Windows.Forms.ToolStripMenuItem("Mở thư mục Theme")
    $miDir.Add_Click({ Start-Process explorer.exe (Get-ThemeDir -Ensure) })
    [void]$themeQuickMenu.Items.Add($miDir)

    $miScan = New-Object System.Windows.Forms.ToolStripMenuItem("Quét lại thư mục Theme")
    $miScan.Add_Click({ Populate-ThemeList })
    [void]$themeQuickMenu.Items.Add($miScan)

    $themeQuickMenu.Show($btnThemeQuick, 0, $btnThemeQuick.Height)
})

$cboThemeFilter.Add_SelectedIndexChanged({ Populate-ThemeList })
$btnThemeScan.Add_Click({ Populate-ThemeList })
$btnThemeOpenDir.Add_Click({ Start-Process explorer.exe (Get-ThemeDir -Ensure) })

$btnThemeApply.Add_Click({
    if ($lvThemes.SelectedItems.Count -eq 0) {
        Show-Msg "Hãy chọn 1 theme trong danh sách để áp dụng." "Chưa chọn Theme" "Information"
        return
    }
    Apply-AppTheme ([string]$lvThemes.SelectedItems[0].Tag)
})
$lvThemes.Add_DoubleClick({
    if ($lvThemes.SelectedItems.Count -gt 0) {
        Apply-AppTheme ([string]$lvThemes.SelectedItems[0].Tag)
    }
})
$btnThemeReset.Add_Click({ Apply-AppTheme "" })
$btnThemePause.Add_Click({
    if ($null -eq $script:ThemeEngine -or -not $script:ThemeEngine.IsAnimated) { return }
    $script:ThemeEngine.IsPaused = (-not $script:ThemeEngine.IsPaused)
    $btnThemePause.Text = if ($script:ThemeEngine.IsPaused) { "Phát tiếp" } else { "Tạm dừng động" }
})

$syncThemeReadability = {
    $lblThemeDimVal.Text = "$($trkThemeDim.Value)%"
    if ($script:ThemeLoadingCfg) { return }
    if ($null -ne $script:ThemeEngine) {
        $script:ThemeEngine.UpdateReadability([int]$trkThemeDim.Value, [bool]$chkThemeOutline.Checked, [int]$cboThemeTextPreset.SelectedIndex, [int]$cboThemeOrnamentSeason.SelectedIndex, [bool]$chkThemeOrnaments.Checked, [int]$cboThemeOrnamentSeason.SelectedIndex, [bool]$chkThemeAnim.Checked, 0)
        $curP = [int]$script:ThemeEngine.TextPreset
        $curT = [bool]$script:ThemeEngine.IsActive
        if ($curP -ne $script:LastNativeTextPreset -or $curT -ne $script:LastNativeThemed) {
            Update-TextPresetNativeControls $curT
        }
        if ($pnlDiskLegend) { $pnlDiskLegend.Invalidate() }
    }
    Save-ThemeConfig
}
$trkThemeDim.Add_ValueChanged($syncThemeReadability)
$chkThemeOutline.Add_CheckedChanged($syncThemeReadability)
$cboThemeTextPreset.Add_SelectedIndexChanged($syncThemeReadability)
$cboThemeOrnamentSeason.Add_SelectedIndexChanged({
    if (-not $script:ThemeLoadingCfg -and -not $chkThemeOrnaments.Checked -and -not $chkThemeAnim.Checked) {
        $script:ThemeLoadingCfg = $true
        try {
            $chkThemeOrnaments.Checked = $true
            $chkThemeAnim.Checked      = $true
        } finally {
            $script:ThemeLoadingCfg = $false
        }
    }
    & $syncThemeReadability
})
$chkThemeOrnaments.Add_CheckedChanged($syncThemeReadability)
$chkThemeAnim.Add_CheckedChanged($syncThemeReadability)
$chkThemeRemember.Add_CheckedChanged({ if (-not $script:ThemeLoadingCfg) { Save-ThemeConfig } })

