$form.Add_FormClosing({
    if ($script:Timer) { $script:Timer.Stop(); $script:Timer.Dispose() }
    if ($script:ClockTimer) { $script:ClockTimer.Stop(); $script:ClockTimer.Dispose() }
    if ($script:ThemeEngine) { $script:ThemeEngine.Dispose() }
})

$form.Add_Shown({
    $script:ThemeEngine = New-Object JebtoolTheme.ThemeSurfaceEngine
    $trkThemeDim.ThemeEngine = $script:ThemeEngine
    $script:ThemeEngine.Attach(
        $form,
        ([System.Windows.Forms.Control[]]@($pnlHeader, $pnlNav) + [System.Windows.Forms.Control[]]$script:QuickCards),
        [System.Windows.Forms.Control[]]@($chkDry, $lblStatus),
        [System.Windows.Forms.Control[]]$script:ExcludedThemeControls,
        $tabs,
        [System.Windows.Forms.TabControl[]]@($subTabs, $subQuotaTabs),
        $lblModeBadge
    )
    $themeDir = Get-ThemeDir -Ensure
    $cfg = Load-ThemeConfig
    $initCatalog = @(Get-ThemeCatalog)
    $appliedStartup = $false
    if ($null -ne $cfg) {
        $script:ThemeLoadingCfg = $true
        try {
            if ($null -ne $cfg.DimPercent) {
                $dv = [Math]::Max(20, [Math]::Min(88, [int]$cfg.DimPercent))
                $trkThemeDim.Value = $dv
                $lblThemeDimVal.Text = "$dv%"
            }
            if ($null -ne $cfg.StrongOutline) { $chkThemeOutline.Checked = [bool]$cfg.StrongOutline }
            if ($null -ne $cfg.TextPreset) {
                $tp = [Math]::Max(0, [Math]::Min(6, [int]$cfg.TextPreset))
                $cboThemeTextPreset.SelectedIndex = $tp
            }
            if ($null -ne $cfg.PSObject.Properties['ShowOrnaments'] -and $null -ne $cfg.ShowOrnaments) {
                $chkThemeOrnaments.Checked = [bool]$cfg.ShowOrnaments
            } else {
                $chkThemeOrnaments.Checked = $true
            }
            $os = 0
            if ($null -ne $cfg.PSObject.Properties['OrnamentSeason'] -and $null -ne $cfg.OrnamentSeason) {
                $os = [Math]::Max(0, [Math]::Min(13, [int]$cfg.OrnamentSeason))
            }
            if ($null -ne $cfg.PSObject.Properties['AnimEffect'] -and $null -ne $cfg.AnimEffect -and $os -le 8) {
                $oldAe = [int]$cfg.AnimEffect
                if ($oldAe -ge 1 -and $oldAe -le 5) { $os = $oldAe + 8 }
                elseif ($oldAe -eq 6) { $os = 4 }
                elseif ($oldAe -ge 7 -and $oldAe -le 10) { $os = $oldAe - 2 }
            }
            $cboThemeOrnamentSeason.SelectedIndex = $os
            if ($null -ne $cfg.PSObject.Properties['ShowAnimation'] -and $null -ne $cfg.ShowAnimation) {
                $chkThemeAnim.Checked = [bool]$cfg.ShowAnimation
            } else {
                $chkThemeAnim.Checked = $true
            }
            if ($null -ne $cfg.Remember) { $chkThemeRemember.Checked = [bool]$cfg.Remember }
        } finally {
            $script:ThemeLoadingCfg = $false
        }
        $script:ThemeEngine.UpdateReadability([int]$trkThemeDim.Value, [bool]$chkThemeOutline.Checked, [int]$cboThemeTextPreset.SelectedIndex, [int]$cboThemeOrnamentSeason.SelectedIndex, [bool]$chkThemeOrnaments.Checked, [int]$cboThemeOrnamentSeason.SelectedIndex, [bool]$chkThemeAnim.Checked, 0)
        if ($cfg.Remember -and $cfg.ActiveRelPath) {
            $cand = if ([System.IO.Path]::IsPathRooted([string]$cfg.ActiveRelPath)) { [string]$cfg.ActiveRelPath } else { Join-Path $themeDir ([string]$cfg.ActiveRelPath) }
            if (Test-Path -LiteralPath $cand) {
                Apply-AppTheme $cand -NoSave
                $appliedStartup = $true
            }
            elseif ($initCatalog.Count -gt 0) {
                Apply-AppTheme $initCatalog[0].FullPath -NoSave
                $appliedStartup = $true
            }
        }
    }
    elseif ($initCatalog.Count -gt 0) {
        Apply-AppTheme $initCatalog[0].FullPath -NoSave
        $appliedStartup = $true
    }
    if (-not $appliedStartup) {
        Apply-AppTheme "" -NoSave
    }
    Update-NavSelection
    $script:ClockTimer.Start()
    $lblNow.Text = (Get-Date).ToString('dd/MM/yyyy   HH:mm:ss')
    $initOk = Invoke-WithBusy { Initialize-Env } "Đang kết nối Active Directory..."
    if ($initOk) {
        $script:Ready = $true
        $lblStatus.Text = "Domain: " + $script:DomainName + "   |   Người dùng: " + $env:USERDOMAIN + "\" + $env:USERNAME + "   |   Sơ đồ tự cập nhật mỗi 10 giây"
        Write-Log "Sẵn sàng. Đang bật chế độ 'Chạy thử' - bỏ tick để thao tác thật." "Black"
        Invoke-WithBusy { Update-OUList -Force } "Đang tải sơ đồ cây OU từ Active Directory..."
        $script:Timer.Start()
    }
    else {
        $lblStatus.Text = "Chế độ cục bộ (Chưa kết nối AD) — Tab Ổ đĩa, Share và Giờ máy vẫn dùng được."
        Write-Log "[LƯU Ý] Chưa có RSAT/Domain: các nút AD/OU/GPO đã tạm khóa. Các tab Ổ đĩa, Share, Giờ máy vẫn hoạt động." "DarkOrange"
        $nd = New-Object System.Windows.Forms.TreeNode "(Chưa kết nối Active Directory)"
        $nd.ForeColor = Get-ThemeColor "DimGray"
        [void]$tree.Nodes.Add($nd)
        $txtTreeSearch.Enabled = $false
        foreach ($c in @($btnCreateOU, $btnDeleteOUQuick, $btnCsv, $btnSample, $btnCreateGPO, $btnGpoMgr, $btnRefresh, $btnTreeFind, $btnLibCreate, $btnLibSafe, $btnLibAll, $btnLibNone, $btnGCreate, $btnDeploy, $btnCreateGrp, $btnDeleteGrp, $btnGrpCsv, $btnGrpSample, $btnCreateUsr, $btnDeleteUsr, $btnUsrCsv, $btnUsrSample, $btnDelReset, $btnMoveObj, $btnOUProtect, $btnOUUnprotect, $btnBlockInhOn, $btnBlockInhOff, $btnCheckInh, $btnOURename, $btnOUDesc, $btnOUDelete, $chkShSysvol, $cboShDrive)) {
            $c.Enabled = $false
        }
        $chkShSysvol.Checked = $false
    }
})

# Kích hoạt chống sao chép nội dung trên các ô log / hướng dẫn chỉ đọc
try { [JebtoolSecurity.Guard]::ProtectReadOnlyControls($form) } catch { }

# Watchdog chống mở công cụ debug/dịch ngược trong lúc chạy
$script:JebGuardTimer = New-Object System.Windows.Forms.Timer
$script:JebGuardTimer.Interval = 5000
$script:JebGuardTimer.Add_Tick({
    try {
        $d = [JebtoolSecurity.Guard]::CheckEnvironment()
        if ($d) {
            $script:JebGuardTimer.Stop()
            [Environment]::FailFast("Security violation")
        }
    } catch { }
})
$script:JebGuardTimer.Start()
$form.Add_FormClosed({ try { $script:JebGuardTimer.Stop(); $script:JebGuardTimer.Dispose() } catch { } })

# Kiểm tra cập nhật tự động từ GitHub (version.json)
$script:JebCurrentVersion = "2.2.0"
$form.Add_Shown({
    try {
        [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12
        $wc = New-Object System.Net.WebClient
        $wc.Encoding = [System.Text.Encoding]::UTF8
        $wc.Headers.Add("User-Agent", "Jebtool-Updater/2.2")
        $vUrl = "https://raw.githubusercontent.com/Yanfeii999/jebtool/main/version.json?_t=" + [DateTime]::UtcNow.Ticks
        $vJson = $wc.DownloadString($vUrl) | ConvertFrom-Json
        $wc.Dispose()
        if ($vJson -and $vJson.version -and ([string]$vJson.version -ne $script:JebCurrentVersion)) {
            $note = if ($vJson.notes) { "`r`n`r`nNội dung mới:`r`n" + [string]$vJson.notes } else { "" }
            $ans = [System.Windows.Forms.MessageBox]::Show(
                "Jebtool đã có bản cập nhật mới: v$($vJson.version) (bản hiện tại: v$($script:JebCurrentVersion))$note`r`n`r`nBạn có muốn Cập nhật & Khởi động lại ngay để nhận tính năng mới không?",
                "Jebtool — Thông báo cập nhật mới",
                [System.Windows.Forms.MessageBoxButtons]::YesNo,
                [System.Windows.Forms.MessageBoxIcon]::Information
            )
            if ($ans -eq [System.Windows.Forms.DialogResult]::Yes) {
                $exePath = $null
                try { $exePath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { }
                if ($exePath -and $exePath.EndsWith('.exe', [System.StringComparison]::OrdinalIgnoreCase)) {
                    Start-Process -FilePath $exePath
                    $form.Close()
                }
            }
        }
    } catch { }
})

# Hoàn tất màn hình Loading -> mở giao diện chính Jebtool
if ($script:JebLoadingForm -and -not $script:JebLoadingForm.IsDisposed) {
    Update-JebtoolLoading $script:JebLoadingForm 90 "Đang nạp cấu hình & chuẩn bị không gian làm việc..." 10
    Update-JebtoolLoading $script:JebLoadingForm 100 "Sẵn sàng! Đang mở Jebtool..." 12
    Start-Sleep -Milliseconds 180
    $script:JebLoadingForm.Close()
    $script:JebLoadingForm.Dispose()
}
[void]$form.ShowDialog()
